// ---- Scenario runner: a filter, and a --fast mode ---------------------------------------------
// The suite is 71s, and 397 of its 430 assertion blocks finish in 4.4s TOTAL — the whole cost sits
// in 14 functions that run full 300s sims to measure balance curves. Paying 71s to re-check the
// difficulty ramp after editing a weapon's arc is what makes the edit-test loop feel slow, and a
// slow loop is why defects arrive in batches instead of one at a time.
//
//   node test/sim-test.js              every scenario (what npm test and CI do — unchanged)
//   node test/sim-test.js element      only scenarios whose function name matches, case-insensitive
//   node test/sim-test.js --fast       everything except the 14 heavy balance sims
//
// The filter matches the FUNCTION name, which is the unit this file is already organised in.
// A partial run always says so on the last line: a green suite that quietly checked a third of
// itself would be worse than a slow one.
const ONLY = process.argv.slice(2).find((a) => !a.startsWith('-')) || ''
const FAST = process.argv.includes('--fast')
// MEASURED, not guessed — the per-block timing is in the commit that added this. Together these
// are 85% of the wall clock. One list rather than a per-function flag, so there is a single place
// to look when the suite gets slow again; the count is printed so it cannot rot unnoticed.
const SLOW_SCENARIOS = new Set([
  'testVictory', 'testChapterLateRate', 'testAnomalySlate', 'testPoolBuckets', 'testRerollRarity',
  'testEscalation', 'testMutators', 'testTheBlank', 'testChapterBalance', 'testChapterDensityCap',
  'testCommitVisibility', 'testIntegerHP', 'testLaneGolden', 'testElementsRedesign',
])
let _ran = 0
let _skipped = 0
function run(fn) {
  if (ONLY && !fn.name.toLowerCase().includes(ONLY.toLowerCase())) { _skipped++; return }
  if (FAST && SLOW_SCENARIOS.has(fn.name)) { _skipped++; return }
  _ran++
  fn()
}
function runSummary() {
  if (_skipped === 0) return
  const why = ONLY ? " (filter '" + ONLY + "')" : (FAST ? ' (--fast: heavy balance sims omitted)' : '')
  console.log('\n>>> PARTIAL RUN: ' + _ran + ' scenarios ran, ' + _skipped + ' SKIPPED' + why +
    '. Run `npm test` with no arguments before shipping.')
}

// THE DENOMINATOR FOR ANY "every chapter a player can reach" SWEEP. Every chapter of every
// SHIPPED book, plus The Blank — hidden rather than unfinished, and reachable by winning.
//
// It is DERIVED from the shipped gate rather than written down, and that is the whole point. Writing
// `CHAPTER_ORDER` means writing `BOOKS.book1.chapters`, which is correct today and silently wrong
// the moment a second book ships: the sweep keeps passing while covering a strictly smaller set
// than it claims. That is how v7.55 shipped the entire elements redesign untranslatable with a
// green suite, and CLAUDE.md's own rule about this ("print the denominator in every sweep's log
// line") does not help when the denominator is right but the SET it is drawn from has moved.
//
// PER CHAPTER, because the gate is (BOOKS[].wipFrom, config.js): Undertow ships one rung at a time,
// so the denominator has to widen one rung at a time too. Today it is CHAPTER_ORDER + blank + surf
// + shelf. Bumping wipFrom again makes every sweep here start demanding The Reef's French name, its
// endings, its unlock line and an unshakeable tank — before that chapter reaches a player, not after.
// The Shelf's bump to 2 is what that promise looks like when it is kept: it drew four reds, and the
// endings pair and unlock line it demanded did not exist in any language.
//
// Deriving it from the shipped isWipChapter rather than re-reading wipFrom is deliberate: the two
// would be one fact in two places, and the test copy is the one that would silently stop matching.
const shippedChapterIds = () => [
  ...Object.values(BOOKS).flatMap((b) => b.chapters).filter((id) => !isWipChapter(id)),
  'blank',
]
// Its complement, for the guards that assert the exclusion is not vacuous.
const wipChapterIds = () => Object.values(BOOKS).flatMap((b) => b.chapters).filter((id) => isWipChapter(id))

// Sim relies on Math.random() for spawn positions/types, crit, coin drops, and
// levelup pool picks. Seed it so the self-check is deterministic — no flaky
// pass/fail on outcomes (like "leveled up by exactly 120s") that are close to
// the RNG's natural variance.
function mulberry32(seed) {
  return function () {
    seed |= 0
    seed = (seed + 0x6d2b79f5) | 0
    let t = Math.imul(seed ^ (seed >>> 15), 1 | seed)
    t = (t + Math.imul(t ^ (t >>> 7), 61 | t)) ^ t
    return ((t ^ (t >>> 14)) >>> 0) / 4294967296
  }
}
Math.random = mulberry32(20260714)

function makeMeta() {
  return {
    coins: 0,
    shop: Object.fromEntries(Object.keys(SHOP).map((id) => [id, 0])),
    best: { time: 0, kills: 0 },
    runs: 0,
  }
}

// Stubs localStorage with `blob` (as the raw JSON the save slot would hold) and calls loadMeta() —
// the pattern the loadMeta-side scenarios already use (see testChoiceSlots/testChapters above),
// pulled out to a helper because run BP's retroactive-unlock block needs it several times.
function loadMetaFrom(blob) {
  globalThis.localStorage = { getItem: () => JSON.stringify(blob), setItem: () => {} }
  const m = loadMeta()
  delete globalThis.localStorage
  return m
}

function finite(n) {
  return typeof n === 'number' && Number.isFinite(n)
}

// Elements now compete for level-up slots alongside weapons/passives/star-mods. Auto-picking
// index 0 could occasionally hand a run a free elemental infusion it didn't ask for, which
// would contaminate tests that are specifically isolating another system's effect (e.g. star
// mods vs a star-only baseline). Picking the first non-'element' offer keeps those tests'
// power budget exactly what they set up explicitly; runs that want elements force them onto
// run.elements directly (see testElements), mirroring how testStarMods forces run.weaponMods.star.
function pickNonElementIndex(run) {
  const choices = run.levelUpChoices || []
  const idx = choices.findIndex((c) => c.kind !== 'element')
  return idx >= 0 ? idx : 0
}

// Advances `run` by stepping stepSim, auto-resolving any levelup screens
// (picks the first non-element choice) so the run keeps flowing like main.js would drive it.
// v7.8: THIS HELPER DRAINS run.events EVERY STEP, exactly as main.js:404 does. It used not to, and
// that cost the suite real time twice over: the backlog was RESCANNED in full on every step (so a
// 305s run walked tens of thousands of events 18,300 times, quadratic), and the array itself grew
// without bound (allocation and GC, which turned out to be the larger half — EE.d2 alone ran 9.2s
// undrained against 2.2s drained). It is the same trap CLAUDE.md documents for weapon-census, "the
// backlog is recounted every frame", living in the harness that is supposed to model main.js.
//   SO: run.events IS EMPTY WHEN advance() RETURNS. That is the game's real behaviour, not a
// harness quirk — nothing in the game ever observes an undrained backlog, and sim.js only ever
// pushes to it (it never reads it, which is why draining cannot change what the sim does). All 22
// call sites were enumerated before this changed; none read run.events afterwards. If you need the
// events, use the returned Set of types, or run your own stepSim loop like the ~15 scenarios that
// need per-event detail already do.
function advance(run, seconds, dt, input) {
  const steps = Math.round(seconds / dt)
  const eventsSeen = new Set()
  for (let i = 0; i < steps; i++) {
    if (run.phase === 'levelup') {
      applyChoice(run, pickNonElementIndex(run))
      run.phase = 'playing'
      continue
    }
    if (run.phase !== 'playing') break
    stepSim(run, input, dt)
    for (const e of run.events) eventsSeen.add(e.type)
    run.events.length = 0
    assert(finite(run.player.x), `player.x not finite: ${run.player.x}`)
    assert(finite(run.player.y), `player.y not finite: ${run.player.y}`)
    assert(finite(run.player.hp), `player.hp not finite: ${run.player.hp}`)
  }
  return eventsSeen
}

function testMovementAndCombat() {
  const run = createRun(makeMeta())
  // v6.4.3: pin hp (the testVictory idiom below) — this test is about the core loop (spawns,
  // kills, xp, events), not survival margins; the seeded stream shifted when runs gained an
  // opening spawn credit and the player started dying just short of the level-up.
  run.player.maxHP = run.player.hp = 1e9
  const startLevel = run.player.level
  const eventsSeen = advance(run, 120, 1 / 60, { x: 1, y: 0 })

  assert(run._nextId > 1, 'expected enemies to have spawned (id counter unchanged)')
  assert(run.kills > 0, `expected kills > 0, got ${run.kills}`)
  assert(run.player.level > startLevel, `expected player to level up, still level ${run.player.level}`)
  assert(eventsSeen.has('shoot'), 'expected at least one shoot event')
  assert(eventsSeen.has('hit'), 'expected at least one hit event')
  assert(eventsSeen.has('kill'), 'expected at least one kill event')
  assert(eventsSeen.has('levelup'), 'expected at least one levelup event')

  console.log(`PASS run A (movement + combat): kills=${run.kills} level=${run.player.level} time=${run.time.toFixed(1)}s`)
}

function testDeath() {
  const run = createRun(makeMeta())
  run.player.speed = 0
  advance(run, 300, 1 / 60, { x: 0, y: 0 })

  assert.strictEqual(run.phase, 'dead', `expected phase 'dead', got '${run.phase}' at time ${run.time.toFixed(1)}s`)
  console.log(`PASS run B (death): died at time=${run.time.toFixed(1)}s kills=${run.kills}`)
}

function testVictory() {
  const run = createRun(makeMeta())
  run.player.hp = 1e9
  run.player.maxHP = 1e9
  advance(run, 305, 1 / 60, { x: 1, y: 0 })

  assert.strictEqual(run.phase, 'victory', `expected phase 'victory', got '${run.phase}' at time ${run.time.toFixed(1)}s`)
  console.log(`PASS run C (victory): time=${run.time.toFixed(1)}s kills=${run.kills}`)
}

// Fresh run per new weapon id, forced to be the only equipped weapon at level 3.
// Drives 45s with a circling input (so enemies approach from every angle) and checks
// the weapon dealt damage and its dedicated entity array actually saw activity.
const NEW_WEAPON_ENTITY = {
  boomerang: 'boomerangs',
  mines: 'mines',
  homing: 'homingShots',
  hole: 'holes',
  rainbow: 'beams',
}

function testNewWeapons() {
  const dt = 1 / 60
  const steps = Math.round(45 / dt)

  for (const [id, arrKey] of Object.entries(NEW_WEAPON_ENTITY)) {
    const run = createRun(makeMeta())
    run.weapons = [{ id, level: 3 }]

    let sawActivity = false
    let t = 0
    for (let i = 0; i < steps; i++) {
      if (run.phase === 'levelup') {
        applyChoice(run, pickNonElementIndex(run))
        run.phase = 'playing'
        continue
      }
      if (run.phase !== 'playing') break

      t += dt
      const input = { x: Math.cos(t), y: Math.sin(t) } // circle around, so enemies close in from all sides
      stepSim(run, input, dt)

      if (run[arrKey].length > 0) sawActivity = true

      assert(finite(run.player.x), `[${id}] player.x not finite: ${run.player.x}`)
      assert(finite(run.player.y), `[${id}] player.y not finite: ${run.player.y}`)
      for (const e of run.enemies) {
        assert(finite(e.x), `[${id}] enemy.x not finite: ${e.x}`)
        assert(finite(e.y), `[${id}] enemy.y not finite: ${e.y}`)
      }
    }

    assert(run.kills > 0, `[${id}] expected kills > 0, got ${run.kills}`)
    assert(sawActivity, `[${id}] expected run.${arrKey} to see activity at some point`)
    console.log(`PASS run D (${id}): kills=${run.kills} time=${run.time.toFixed(1)}s ${arrKey} active`)
  }
}

// Rarity sanity: sample 200 level-up pools each at player level 1 and 12 (fresh run each
// time, so pools aren't depleted by earlier picks), and check the rarity distribution and
// passive bonus math the hybrid model promises.
function testRaritySanity() {
  const seenL1 = {}
  const seenL12 = {}
  let passiveBonusChecked = false

  function sample(level, counter) {
    const run = createRun(makeMeta())
    run.player.level = level
    const choices = buildLevelUpChoices(run)
    for (const c of choices) {
      // v6.7.5: a weapon UPGRADE card carries NO tier and must carry EXACTLY the one non-tier
      // value (UPGRADE_RARITY), which is deliberately not a RARITIES key so ui.js prints no chip.
      // Every other card, `New!` weapons included, still has to name a real tier.
      if (c.kind === 'weapon' && c.tag !== 'New!') {
        assert.strictEqual(c.rarity, UPGRADE_RARITY, `a weapon upgrade card must show no tier, got ${c.rarity}`)
      } else {
        assert(c.rarity in RARITIES, `invalid rarity key: ${c.rarity}`)
      }
      counter[c.rarity] = (counter[c.rarity] ?? 0) + 1

      if (c.kind === 'passive') {
        const cfg = PASSIVES[c.id]
        let expected
        if (cfg.values) {
          // v6.3.4: armor/regen roll ONLY the rarities listed in their values table, at fixed
          // per-rarity amounts — no base*mult math, and never epic/mythic.
          assert(c.rarity in cfg.values, `[${c.id}] values-passive rolled disallowed rarity ${c.rarity}`)
          expected = cfg.values[c.rarity]
        } else {
          const mult = RARITIES[c.rarity].mult
          expected = cfg.base * mult
          if (cfg.kind === 'flat') expected = Math.round(expected * 10) / 10
        }
        assert.strictEqual(c.bonus, expected, `[${c.id}] bonus ${c.bonus} != expected ${expected} for rarity ${c.rarity}`)
        passiveBonusChecked = true
      }
    }
  }

  for (let i = 0; i < 200; i++) sample(1, seenL1)
  for (let i = 0; i < 200; i++) sample(12, seenL12)

  assert(passiveBonusChecked, 'expected at least one passive card to verify bonus math against')
  // Fixed 50/25/12/6/3 weights (no level scaling): same shape at any level — normal is the
  // plurality, every tier still shows up across both samples, and rarity falls off monotonically.
  for (const seen of [seenL1, seenL12]) {
    assert((seen.normal ?? 0) > (seen.rare ?? 0), `expected normal > rare, got ${JSON.stringify(seen)}`)
    assert((seen.rare ?? 0) > (seen.legendary ?? 0), `expected rare > legendary, got ${JSON.stringify(seen)}`)
  }
  const both = (id) => (seenL1[id] ?? 0) + (seenL12[id] ?? 0)
  for (const id of ['normal', 'rare', 'epic', 'legendary', 'mythic']) {
    assert(both(id) > 0, `expected some ${id} rolls across 400 samples`)
  }

  console.log(`PASS run E (rarity sanity): L1=${JSON.stringify(seenL1)} L12=${JSON.stringify(seenL12)}`)
}

// ---- Run PB1: bucket-first roll ----------------------------------------------------
// The shipped roll picked a RARITY first and walked DOWN the ladder when that rarity had no
// options, which deleted the weapon bucket on every roll no weapon happened to carry. Buckets
// are now explicit and rolled first. See B1 in the Track B spec.
// ---- Run PB6: the per-chapter hpScale tail (v7.1) -----------------------------------
// Track B's pool is a net power buff, and the chosen lever is the END of the run per chapter
// rather than a flat multiplier. Two properties are asserted here because both are load-bearing
// and both are easy to break silently.
function testChapterLateRate() {
  // Every chapter in the ladder, and an unknown one falls back rather than throwing.
  for (const [id, rate] of Object.entries(CHAPTER_LATE_RATE)) {
    assert.strictEqual(lateRateFor(id), rate, `lateRateFor(${id}) must return its ladder value`)
  }
  assert.strictEqual(lateRateFor('blank'), HP_SCALE_LATE_RATE, 'an off-ladder chapter keeps the shipped curve')
  assert.strictEqual(lateRateFor(undefined), HP_SCALE_LATE_RATE, 'no chapter keeps the shipped curve')

  // The ladder is ordered: later chapters end harder.
  const order = ['body', 'pond', 'garden', 'undergrowth', 'city', 'skies', 'beyond']
  for (let i = 1; i < order.length; i++) {
    assert.ok(CHAPTER_LATE_RATE[order[i]] > CHAPTER_LATE_RATE[order[i - 1]],
      `${order[i]} must end harder than ${order[i - 1]}`)
  }

  // PROPERTY 1 — SELF-TARGETING. Before HP_SCALE_LATE_START the rate cannot matter at all, which
  // is the entire argument for this lever over a flat multiplier: a run that dies early is never
  // touched. Measured consequence, worth knowing before tuning: city's bot dies at ~132s, so
  // raising city's number changes NOTHING about city. Only HP_SCALE_LATE_START could.
  for (const t of [0, 60, HP_SCALE_LATE_START]) {
    assert.strictEqual(hpScale(t, 0.045), hpScale(t, 0.005),
      `at t=${t}s (<= HP_SCALE_LATE_START) the tail rate must be inert`)
  }
  assert.ok(hpScale(HP_SCALE_LATE_START + 1, 0.045) > hpScale(HP_SCALE_LATE_START + 1, 0.005),
    'one second past the start the rate must bite')

  // PROPERTY 2 — it actually separates the chapters at the end of a run.
  const bodyEnd = hpScale(300, CHAPTER_LATE_RATE.body)
  const beyondEnd = hpScale(300, CHAPTER_LATE_RATE.beyond)
  assert.ok(beyondEnd > bodyEnd * 2.5,
    `beyond should end far harder than body (body ${bodyEnd.toFixed(1)}x, beyond ${beyondEnd.toFixed(1)}x)`)

  // The default argument is what keeps the two ENEMY-SIDE damage sites on the shipped curve.
  assert.strictEqual(hpScale(300), hpScale(300, HP_SCALE_LATE_RATE),
    'hpScale() with no rate must equal the shipped rate')

  // SOURCE TRIPWIRE. The wiring is one argument at one call site, and dropping it is a silent
  // no-op: every chapter would quietly fall back to 0.005 with no test failing and no error. The
  // two enemy-side sites must NOT gain one, or a difficulty knob starts buffing the player.
  const src = readFileSync(new URL('../src/sim.js', import.meta.url), 'utf8')
  assert.ok(src.includes('hpScale(run.time, lateRateFor(run.chapter))'),
    'spawnEnemy must pass the chapter tail rate — without it the ladder is inert everywhere')
  assert.strictEqual((src.match(/hpScale\(run\.time, /g) ?? []).length, 1,
    'exactly ONE hpScale call may take a rate (spawnEnemy). The snap-trap and core-blast sites are enemy-side damage: scaling those with the ladder buffs the player in late chapters.')

  console.log(`PASS run PB6 (chapter tail): body ${bodyEnd.toFixed(1)}x -> beyond ${beyondEnd.toFixed(1)}x at t=300, inert before ${HP_SCALE_LATE_START}s, wired at exactly one site`)

  // ---- PB6.b: the ELITE half of the same late ramp (owner: more elites at the end of the beyond)
  // Same window and the same self-targeting property as the HP tail above, so it gets the same two
  // properties asserted plus a wiring tripwire — the call site takes one extra argument, and
  // dropping it is silent: every chapter falls back to the flat cadence with nothing going red.
  for (const id of ['body', 'pond', 'garden', 'undergrowth', 'city', 'skies']) {
    assert.strictEqual(lateEliteFor(id), 0, `${id} must not get the late elite ramp — it is beyond's`)
  }
  assert.strictEqual(lateEliteFor('beyond'), CHAPTER_LATE_ELITE.beyond, 'beyond must get its ladder value')
  assert.strictEqual(lateEliteFor('blank'), 0, 'an off-ladder chapter keeps the flat cadence')
  assert.strictEqual(lateEliteFor(undefined), 0, 'no chapter keeps the flat cadence')

  // SELF-TARGETING, exactly as the HP tail: inert until HP_SCALE_LATE_START, so a run that ends
  // early never meets it.
  for (const t of [0, 60, HP_SCALE_LATE_START]) {
    assert.strictEqual(eliteEveryAt(t, CHAPTER_LATE_ELITE.beyond), eliteEveryAt(t),
      `at t=${t}s (<= HP_SCALE_LATE_START) the elite ramp must be inert`)
  }
  assert.ok(eliteEveryAt(HP_SCALE_LATE_START + 1, CHAPTER_LATE_ELITE.beyond) < eliteEveryAt(HP_SCALE_LATE_START + 1),
    'one second past the start the elite ramp must bite')
  // ...and at the very end it reaches its full value: the gap divided by (1 + late).
  assert.ok(Math.abs(eliteEveryAt(300, CHAPTER_LATE_ELITE.beyond) * (1 + CHAPTER_LATE_ELITE.beyond) - eliteEveryAt(300)) < 1e-9,
    'at RUN_DURATION the interval must be the flat one divided by (1 + late)')

  // EFFECT, not state: step a real beyond run across the late window and count what it actually
  // spawns, against the flat cadence the same recurrence gives. Asserting the constant instead
  // would pass with the sim call site reverted, which is the failure this is here to catch.
  {
    const flat = (late) => {          // the shipped recurrence, run forward over a whole 300s
      let next = 40
      let n = 0
      while (next <= 300) { if (next >= HP_SCALE_LATE_START) n++; next += eliteEveryAt(next, late) }
      return n
    }
    const withRamp = flat(CHAPTER_LATE_ELITE.beyond)
    const without = flat(0)
    assert.ok(withRamp >= without + 4,
      `the ramp must buy several late elites, not one: ${without} -> ${withRamp}. The cadence is COARSE `
      + '(only ~7 elites land after t=150 at all), so a small multiplier here rounds away to nothing.')

    const seeded = mulberry32(20260812)
    const realRandom = Math.random
    Math.random = seeded
    try {
      const run = createRun(makeMeta(), { chapter: 'beyond', difficulty: 1 })
      run.viewRadius = 465            // main.js sets these every frame; the spawn ring needs them
      run.viewW = 195
      run.viewH = 422
      const seen = new Set()
      let late = 0
      while (run.time < 300 && run.phase !== 'dead') {
        stepSim(run, { x: 0, y: 0, skill: false }, 1 / 30)
        run.events.length = 0
        run.player.hp = run.player.maxHP        // immortal: measure the throw, not the survival
        if (run.phase === 'levelup') { run.levelUpChoices = []; run.phase = 'playing' }
        for (const e of run.enemies) {
          if (!e.elite || seen.has(e)) continue
          seen.add(e)
          if (run.time >= HP_SCALE_LATE_START) late++
        }
      }
      assert.ok(late >= without + 3,
        `a real beyond run must actually SPAWN the extra late elites (flat cadence gives ${without}, `
        + `this run gave ${late}) — if this is ~${without} the sim stopped passing lateEliteFor(run.chapter)`)
      console.log(`PASS run PB6.b (late elites): beyond spawns ${late} elites after t=${HP_SCALE_LATE_START}s `
        + `where the flat cadence gives ${without}; ramp inert before that`)
    } finally {
      Math.random = realRandom
    }
  }

  const esrc = readFileSync(new URL('../src/sim.js', import.meta.url), 'utf8')
  assert.ok(esrc.includes('eliteEveryAt(run.time, lateEliteFor(run.chapter))'),
    'spawnEnemy must pass the chapter elite ramp — without it beyond keeps the flat cadence and nothing goes red')
}

// ---- Run PB7: the v7.2 anomaly slate actually DOES something ------------------------
// Every card here is a rule read at ONE trigger site, and deleting that read is a silent no-op:
// the card still rolls, still shows on the screen, still lands in run.anomalies and still prints
// on the pause build sheet. Nothing goes red. So each card gets a behavioural assertion that
// fails if its site stops being read — that is the whole point of this scenario, and the reason
// it asserts effects rather than the presence of a config key.
function testAnomalySlate() {
  const dt = 1 / 60
  const meta = makeMeta()
  // A run with the card ON, weapons stripped unless asked for, and the player parked at the
  // origin. `take` goes through applyChoice so the on-take branch (BRITTLE/OVERLOAD/SOY MILK)
  // runs exactly as it does in the game — setting run.anomalies directly would skip it and let a
  // broken applyAnomalyOnTake pass.
  // `opts` reaches createRun, defaulting to what every arm below already got. RUNOFF is the one
  // card on the slate whose ramp is a CHAPTER resource, so its arm has to boot in that chapter:
  // in body, chargeMax is 0 and the card is a deliberate no-op.
  const withCard = (id, mutate = () => {}, opts = {}) => {
    Math.random = mulberry32(20260808)
    const r = createRun(meta, opts)
    r.weapons = []
    r.player.x = 0; r.player.y = 0
    mutate(r)
    if (id) {
      r.levelUpChoices = [{ kind: 'anomaly', id }]
      applyChoice(r, 0)
    }
    return r
  }

  // TIME DEBT — the clock, and the XP that pays for it.
  {
    const base = withCard(null), debt = withCard('timeDebt')
    for (let i = 0; i < 60; i++) { stepSim(base, { x: 0, y: 0 }, dt); stepSim(debt, { x: 0, y: 0 }, dt) }
    assert.ok(Math.abs(debt.time / base.time - TIME_DEBT_MUL) < 0.01,
      `TIME DEBT advanced the clock x${(debt.time / base.time).toFixed(3)}, not x${TIME_DEBT_MUL}`)
    // The XP half is a separate read in stepPickups and dies separately.
    const gem = (r) => {
      // xpNext out of reach, or stepLevelUp SUBTRACTS the threshold and player.xp is the remainder
      // rather than the gain — which reads as x2.79 instead of x1.5 and looks like a broken card.
      r.player.xpNext = 1e9
      r.gems = [{ x: r.player.x, y: r.player.y, xp: 10 }]
      const before = r.player.xp
      stepSim(r, { x: 0, y: 0 }, dt)
      return r.player.xp - before
    }
    const xpBase = gem(withCard(null)), xpDebt = gem(withCard('timeDebt'))
    assert.ok(Math.abs(xpDebt / xpBase - TIME_DEBT_XP_MUL) < 0.01,
      `TIME DEBT paid x${(xpDebt / xpBase).toFixed(3)} XP, not x${TIME_DEBT_XP_MUL} — the compensation is what makes it a pivot rather than a 3-level tax`)
  }

  // BRITTLE — both halves, plus the repair route the card must not leave open.
  {
    const r = withCard('brittle')
    assert.strictEqual(r.player.maxHP, BRITTLE_MAX_HP, 'BRITTLE did not set maxHP')
    assert.ok(r.player.hp <= BRITTLE_MAX_HP, 'BRITTLE left hp above the new ceiling — it is a damage buff until the next hit')
    const dmgMul = r.player.damageMul / withCard(null).player.damageMul
    assert.ok(Math.abs(dmgMul - BRITTLE_DMG_MUL) < 1e-9, `BRITTLE gave x${dmgMul} damage, not x${BRITTLE_DMG_MUL}`)
    // Buying maxHP back would keep x4 damage and undo the whole cost — the card says BECOMES 1.
    r.levelUpChoices = [{ kind: 'passive', id: 'maxHP', bonus: 20 }]
    applyChoice(r, 0)
    assert.strictEqual(r.player.maxHP, BRITTLE_MAX_HP,
      'a maxHP pick repaired BRITTLE — the run-ender is refundable for five passive picks while keeping x4 damage')
    // ...and because the ceiling holds, all three DEFENSIVE passives are now exactly dead: maxHP is
    // skipped, regen heals up to 1, and armor cannot save a hit hurtPlayer floors at 1 damage.
    // They must leave the POOL too. DEFENSIVE_PASSIVES is all three and B2 weights them 4 against
    // the other passives' 1, so leaving them in makes ~17% of every remaining card a guaranteed
    // no-op with no chip and no grey-out — the "catastrophe the player could neither foresee nor
    // act on" the slate's own bar forbids. Ending the run is the payoff; voiding a sixth of the
    // level-ups silently is not.
    {
      const b = withCard('brittle')
      b.player.level = 12
      let seen = 0
      for (let i = 0; i < 300; i++) {
        b._screenRerolls = -1
        for (const c of buildLevelUpChoices(b)) {
          if (c.kind === 'passive' && DEFENSIVE_PASSIVES.includes(c.id)) seen++
        }
      }
      assert.strictEqual(seen, 0, `BRITTLE still offered ${seen} defensive passive cards over 300 screens — every one of them does nothing at maxHP 1`)
      // The control: they ARE offered without the card, or the assertion above passes for free.
      const n = withCard(null)
      n.player.level = 12
      let ctrl = 0
      for (let i = 0; i < 300; i++) {
        n._screenRerolls = -1
        for (const c of buildLevelUpChoices(n)) {
          if (c.kind === 'passive' && DEFENSIVE_PASSIVES.includes(c.id)) ctrl++
        }
      }
      assert.ok(ctrl > 0, 'the defensive-passive harness saw none even without BRITTLE — it is not reaching its subject')
    }
  }

  // OVERLOAD — the cost is per SECOND, and this is the assertion that catches the floor bug.
  // hurtPlayer's dot branch is Math.max(1, Math.round(raw)), so a naive per-frame call spends 1 HP
  // EVERY FRAME: 60 HP/s instead of 0.75, an 80x overcharge that kills a full-health player in two
  // seconds and would read as "the card is just very strong".
  {
    const r = withCard('overload', (x) => { x.player.hp = 500; x.player.maxHP = 500 })
    const before = r.player.hp
    for (let i = 0; i < 300; i++) stepSim(r, { x: 0, y: 0 }, dt)   // 5 seconds
    const spent = before - r.player.hp
    const want = OVERLOAD_HP_PER_SEC * 5
    assert.ok(Math.abs(spent - want) <= 1.5,
      `OVERLOAD drained ${spent.toFixed(1)} HP over 5s, want ~${want} — a per-frame hurtPlayer call is floored to 1 HP and costs 60 HP/s`)
    // ...AND THE COST GROWS WITH dmgScale (v7.4). A flat drain made the card strictly better than
    // not taking it: measured 90.0% win against a 25.0% control, because 4x dps prevented 170.8 HP
    // of contact damage to pay 144.7 HP of drain — a NEGATIVE net cost. The contact damage it
    // prevents rides dmgScale all run, so the price has to as well or the trade inverts.
    const drainOver = (t0) => {
      const r = withCard('overload', (x) => { x.player.hp = 1e6; x.player.maxHP = 1e6 })
      r.time = t0
      const before = r.player.hp
      for (let i = 0; i < 600; i++) stepSim(r, { x: 0, y: 0 }, dt)   // 10s
      return before - r.player.hp
    }
    const early = drainOver(0), late = drainOver(280)
    assert.ok(late > early * 1.5,
      `OVERLOAD drained ${early.toFixed(1)} HP at t=0 and ${late.toFixed(1)} at t=280 — a flat cost against a benefit that scales is what made this card a 90% win rate`)
    const p = withCard(null).player
    assert.ok(Math.abs(r.player.fireRateMul / p.fireRateMul - OVERLOAD_FIRE_MUL) < 1e-9, 'OVERLOAD did not multiply fire rate')
    assert.ok(Math.abs(r.player.damageMul / p.damageMul - OVERLOAD_DMG_MUL) < 1e-9, 'OVERLOAD did not multiply damage')
    // ...AND THE DRAIN RIDES THE RUN CLOCK, NOT THE REAL ONE (v7.15). TIME DEBT ends the run in 200
    // real seconds instead of 300, so a cost charged per REAL second collects two thirds of the HP
    // — the two cards anti-comboed, and TIME DEBT was a quiet DISCOUNT on the one card whose whole
    // point is a price. Measured over the same real window from the same run.time, the debted drain
    // has to be TIME_DEBT_MUL times the undebted one. Asserted as a RATIO of HP actually removed,
    // so deleting the clockDt term fails it; a state check on run.anomalies would not.
    const drainReal = (debt) => {
      const x = withCard('overload', (y) => { y.player.hp = 1e6; y.player.maxHP = 1e6 })
      if (debt) { x.levelUpChoices = [{ kind: 'anomaly', id: 'timeDebt' }]; applyChoice(x, 0) }
      const b = x.player.hp
      for (let i = 0; i < 120; i++) stepSim(x, { x: 0, y: 0 }, dt)   // 2 REAL seconds either way
      return b - x.player.hp
    }
    const plain = drainReal(false), debted = drainReal(true)
    const ratio = debted / plain
    // Band, not equality: under debt run.time also advances faster, so dmgScale(run.time) climbs a
    // little within the window and the ratio sits just above TIME_DEBT_MUL. 1.4..1.75 excludes both
    // the bug (1.0, the term deleted) and a double-application (2.25).
    assert.ok(ratio > 1.4 && ratio < 1.75,
      `OVERLOAD+TIME DEBT drained x${ratio.toFixed(3)} per real second, want ~x${TIME_DEBT_MUL} — at x1 the drain is charged per real second and TIME DEBT is a 33% DISCOUNT on the card's whole cost`)
  }

  // SOY MILK — paper-neutral by construction, so assert both halves or half the card can vanish.
  {
    const r = withCard('soyMilk'), p = withCard(null).player
    assert.ok(Math.abs(r.player.fireRateMul / p.fireRateMul - SOY_MILK_FIRE_MUL) < 1e-9, 'SOY MILK did not multiply fire rate')
    assert.ok(Math.abs(r.player.damageMul / p.damageMul - SOY_MILK_DMG_MUL) < 1e-9, 'SOY MILK did not divide damage')
  }

  // BLOOD PACT — the heal funnel AND the snowball. healPlayer is the funnel every heal now goes
  // through; a future `p.hp = ...` written straight into the file makes this card a lie, and this
  // is what says so.
  {
    const r = withCard('bloodPact', (x) => { x.player.maxHP = 200; x.player.hp = 50 })
    r.passives.regen = 5
    for (let i = 0; i < 60; i++) stepSim(r, { x: 0, y: 0 }, dt)
    assert.ok(r.player.hp <= 50, `BLOOD PACT healed to ${r.player.hp} — regen is not going through healPlayer`)
    r.levelUpChoices = [{ kind: 'heal' }]
    applyChoice(r, 0)
    assert.ok(r.player.hp <= 50, 'BLOOD PACT healed off the level-up heal card')
    // An ELITE pays both clauses — it is a kill as well as an elite.
    const snow = withCard('bloodPact')
    snow._bloodPact = 0
    snow.enemies = [makeStatusEnemy(snow, { x: 40, y: 0, hp: 1, elite: true })]
    snow.weapons = [{ id: 'star', level: 5 }]
    for (let i = 0; i < 240 && snow.enemies.length > 0; i++) stepSim(snow, { x: 0, y: 0 }, dt)
    assert.ok(snow._bloodPact >= BLOOD_PACT_PER_KILL + BLOOD_PACT_PER_ELITE - 1e-9,
      `an elite kill banked ${snow._bloodPact} — an elite must pay the per-kill clause too`)
  }

  // BLOOD MONEY — the currency swap, the floor, and the price the BUTTON is told to print.
  {
    const r = withCard('bloodMoney', (x) => { x.player.maxHP = 100; x.player.hp = 100; x.coinsEarned = 0 })
    r.player.level = 12
    r._eliteKills = 1
    r.levelUpChoices = buildLevelUpChoices(r)
    const price = rerollPrice(r)
    assert.strictEqual(price.currency, 'hp', 'rerollPrice still says coins under BLOOD MONEY — the button will print the wrong wallet')
    assert.strictEqual(price.cost, BLOOD_MONEY_HP, 'rerollPrice disagrees with what rerollLevelUpChoices charges')
    assert.ok(rerollLevelUpChoices(r), 'BLOOD MONEY reroll failed with 100 HP and 0 coins — it is still charging coins')
    assert.strictEqual(r.player.hp, 100 - BLOOD_MONEY_HP, `the reroll took ${100 - r.player.hp} HP, not ${BLOOD_MONEY_HP}`)
    assert.strictEqual(r.coinsEarned, 0, 'the reroll also took coins')
    // AND IT ESCALATES (v7.4). A flat HP price does not discount the coin ladder, it DELETES it:
    // rerollCost climbs 1.5^n over a run, so flat pricing bought 23.5 rerolls against coins' 6.1
    // with an always-reroll bot. The second reroll must cost more than the first.
    const second = rerollPrice(r)
    assert.ok(second.cost > price.cost,
      `the 2nd BLOOD MONEY reroll costs ${second.cost} against the 1st at ${price.cost} — the price ladder is flat, which is 3.9x the rerolls coins buy`)
    assert.strictEqual(second.currency, 'hp', 'the escalated price changed wallet')
    // Floored, not fatal: below the cost the button refuses rather than killing you on a modal.
    r.player.hp = second.cost
    assert.ok(!rerollLevelUpChoices(r), 'a reroll at exactly the cost was allowed — that is death on a modal screen')
    assert.strictEqual(r.player.hp, second.cost, 'the refused reroll still charged')
  }

  // AVARICE — thins the drops at the SOURCE and converts a share of pickups to HP.
  {
    const heal = (id) => {
      const r = withCard(id, (x) => { x.player.maxHP = 500; x.player.hp = 100 })
      for (let i = 0; i < 200; i++) r.coins.push({ x: 0, y: 0, value: 1 })
      stepSim(r, { x: 0, y: 0 }, dt)
      return { hp: r.player.hp, coins: r.coinsEarned }
    }
    const plain = heal(null), greedy = heal('avarice')
    assert.strictEqual(plain.hp, 100, 'the control run healed off coins — AVARICE is leaking into every run')
    assert.ok(greedy.hp > 100, 'AVARICE healed nothing on 200 coins')
    assert.ok(greedy.coins < plain.coins, 'AVARICE did not divert any coins from the payout')
    // A COIN THAT CANNOT HEAL MUST STILL PAY. healPlayer clamps to maxHP and returns early under
    // BLOOD PACT, so an unconditional conversion consumed the coin for NOTHING in two reachable
    // cases — and the card says "heal 5 HP INSTEAD OF paying out", from which every player infers
    // that a coin which cannot heal still pays.
    const full = (mutate) => {
      const r = withCard('avarice', mutate)
      for (let i = 0; i < 200; i++) r.coins.push({ x: 0, y: 0, value: 1 })
      stepSim(r, { x: 0, y: 0 }, dt)
      return r.coinsEarned
    }
    // At full HP the card was a pure coin tax, and it got WORSE the better you played.
    assert.strictEqual(full((x) => { x.player.maxHP = 500; x.player.hp = 500 }), 200,
      'AVARICE ate coins at full HP — the heal is a no-op there, so the coin must pay out')
    // Paired with BLOOD PACT it destroyed 20% of the run's coins outright, invisibly: seeing it
    // coming needs BOTH "the heal is suppressed" (fair, both cards say so) AND "the coin does not
    // fall back to paying" (nowhere on either card).
    assert.strictEqual(full((x) => { x.player.maxHP = 500; x.player.hp = 100; x.anomalies = { bloodPact: true } }), 200,
      'AVARICE + BLOOD PACT destroyed coins — no heal, no payout, and nothing on either card says so')
    // ...AND THE NUMBER ON SCREEN IS THE HP THAT LANDED (v7.15). The conversion now prints `+N`,
    // and healPlayer clamps to maxHP — so a pickup 2 HP below full heals 2, not AVARICE_HEAL_HP.
    // Asserted against the HP actually gained rather than against the constant: a renderer fed the
    // nominal 5 would put a figure on screen the HP bar visibly contradicts.
    {
      const r = withCard('avarice', (x) => { x.player.maxHP = 500; x.player.hp = 498 })
      for (let i = 0; i < 200; i++) r.coins.push({ x: 0, y: 0, value: 1 })
      const before = r.player.hp
      stepSim(r, { x: 0, y: 0 }, dt)
      const healEvents = r.events.filter((e) => e.type === 'coin' && e.healed)
      assert.ok(healEvents.length > 0, 'AVARICE converted nothing 2 HP below full — the heal can still land there')
      const shown = healEvents.reduce((n, e) => n + e.heal, 0)
      assert.strictEqual(shown, r.player.hp - before,
        `AVARICE's coin events promised +${shown} HP but the player gained ${r.player.hp - before} — the floating number would be lying about a clamped heal`)
      assert.ok(healEvents[0].heal <= 2, `first conversion 2 HP below full reported +${healEvents[0].heal}, want <= 2 (clamped)`)
    }
  }

  // BERSERK — a window opened by a real hit and closed by time, read through anomalyDamageMul.
  {
    const r = withCard('berserk', (x) => { x.player.hp = 1e9; x.player.maxHP = 1e9 })
    r.enemies.push(makeStatusEnemy(r, { x: 0, y: 0 }))
    stepSim(r, { x: 0, y: 0 }, dt)
    assert.ok(r._hitsTaken > 0, 'the contact fixture never hit the player — BERSERK is untested here')
    assert.strictEqual(r._berserkT, BERSERK_DURATION, 'a hit did not open the BERSERK window')
    r.enemies = []
    for (let i = 0; i < Math.ceil((BERSERK_DURATION + 1) * 60); i++) stepSim(r, { x: 0, y: 0 }, dt)
    assert.strictEqual(r._berserkT, 0, 'the BERSERK window never closed — stepAnomalies is not ticking it')
  }

  // STILLNESS — INPUT, never velocity. The velocity version is the bug this asserts against: it
  // would read as working everywhere except pond and the beyond lane, where the world moves you.
  {
    const r = withCard('stillness')
    for (let i = 0; i < 180; i++) stepSim(r, { x: 0, y: 0 }, dt)
    assert.ok(r._stillT >= STILLNESS_RAMP, `standing still for 3s banked only ${r._stillT.toFixed(2)}s of ramp`)
    stepSim(r, { x: 1, y: 0 }, dt)
    assert.strictEqual(r._stillT, 0, 'moving did not drop the STILLNESS ramp')
    // A sub-unit stick deflection is still moving — the test is `len > 0`, not `len >= 1`.
    for (let i = 0; i < 180; i++) stepSim(r, { x: 0, y: 0 }, dt)
    stepSim(r, { x: 0.05, y: 0 }, dt)
    assert.strictEqual(r._stillT, 0, 'a half-pushed stick did not count as moving')
  }

  // MARTYR — HP lost becomes damage around you, and it rides hpScale so it stays worth roughly the
  // same number of enemies at t=30 and t=280 instead of decaying into confetti.
  {
    const hurt = (id, t) => {
      const r = withCard(id, (x) => { x.player.hp = 1e9; x.player.maxHP = 1e9 })
      r.time = t
      const e = makeStatusEnemy(r, { x: 60, y: 0 })
      r.enemies.push(e, makeStatusEnemy(r, { x: 0, y: 0 }))   // the second one does the hitting
      const before = e.hp
      stepSim(r, { x: 0, y: 0 }, dt)
      return before - e.hp
    }
    assert.strictEqual(hurt(null, 100), 0, 'a bystander took damage with no MARTYR — something else is exploding')
    const early = hurt('martyr', 30), late = hurt('martyr', 280)
    assert.ok(early > 0, 'MARTYR did not detonate on a hit')
    assert.ok(late > early * 2,
      `MARTYR paid ${early.toFixed(0)} at t=30 and ${late.toFixed(0)} at t=280 — without hpScale the burst is a panic button early and confetti late`)
  }

  // CHAOS PACT — a repeating cycle, so assert the danger half fires and that it ends.
  {
    const spawned = (id, t) => {
      const r = withCard(id, (x) => { x.time = t })
      r.time = t
      const n0 = r.enemies.length
      for (let i = 0; i < 120; i++) stepSim(r, { x: 0, y: 0 }, dt)
      return r.enemies.length - n0
    }
    const t0 = CHAOS_PACT_PERIOD * 2 + 1
    assert.ok(spawned('chaosPact', t0) > spawned(null, t0),
      'CHAOS PACT did not raise the spawn rate inside its surge window')
    assert.ok(CHAOS_PACT_SURGE < CHAOS_PACT_PERIOD, 'the surge must be shorter than the cycle, or the payoff never arrives')
  }

  // ALIGNMENT — asserted as ELEMENTAL DAMAGE, once PER CALL SITE. The card multiplies potency
  // where potency is CONSUMED and leaves run.elements alone, so every state assertion available
  // (run.elements, elementPicks, the build readout) reads identically with the card and without
  // it. Only the damage moves. Fire and venom are separate arms because they break independently:
  // applyIgnite banks its dps once at apply time, the venom DoT re-reads potency every tick in
  // stepStatuses, and one combined number stays green with either site reverted.
  // withCard re-seeds Math.random per call and the card draws no randoms, so the arms share one
  // stream and the subtraction below is exact rather than statistical.
  {
    assert.ok(ALIGNMENT_POTENCY_MUL > 1, 'ALIGNMENT must raise element potency, not lower it')
    // `extras` puts a second body inside SHOCK_RANGE: the lightning arm has nothing to arc to
    // otherwise, and elArc returns before it ever reads the potency it was handed.
    // hp is per-arm and load-bearing. Venom's amp is a share of the target's OWN health bar, so
    // at the 1e9 every other arm uses `recent` is ~0 and venom is arithmetically invisible — the
    // harness reported "no elemental damage at all" rather than a wrong number. A bar the star can
    // actually bite into is what makes the arm able to see its subject; it must still survive the
    // 240 frames, or the arms stop sharing a denominator.
    const dealt = (id, elements, extras = 0, ehp = 1e9) => {
      const r = withCard(id, (x) => { x.player.hp = 1e9; x.player.maxHP = 1e9 })
      r.weapons = [{ id: 'star', level: 5 }]
      setElements(r, elements)
      const es = [makeStatusEnemy(r, { x: 120, y: 0, hp: ehp, speed: 0 })]
      for (let i = 0; i < extras; i++) es.push(makeStatusEnemy(r, { x: 120, y: (i + 1) * 40, hp: ehp, speed: 0 }))
      r.enemies.push(...es)
      const hp = () => es.reduce((a, e) => a + e.hp, 0)
      const before = hp()
      for (let f = 0; f < 240; f++) stepSim(r, { x: 0, y: 0 }, dt)
      return before - hp()
    }
    // ONE BAND FOR ALL FOUR, which is the point: ALIGNMENT is "x2 potency" and potency is read
    // at sqrt, so every element must move by x sqrt(2) = 1.41 on its output. They disagreed until
    // v7.80 — fire, venom and cold applied the multiplier OUTSIDE elScale (a flat x2) while
    // lightning applied it inside — and nothing caught it, because the only test of it ran on the
    // old element system where potency was linear and the two forms agreed. 1.25 is the band: the
    // pathology is a DELETED alignmentMul, which reads exactly 1.00.
    for (const [label, elements, extras, ehp] of [
      ['fire', { fire: 4 }, 0, 1e9],
      ['venom', { venom: 4 }, 0, 4000],
      ['lightning', { lightning: 4 }, 1, 1e9],
    ]) {
      const weaponOnly = dealt(null, {}, extras, ehp)
      // Subtract the weapon's own damage so the ratio is the ELEMENT's, undiluted — with the
      // star's contribution left in, a real x2 on the DoT reads as a much smaller total and the
      // band would have to be loose enough to pass with the multiplier halved.
      const plain = dealt(null, elements, extras, ehp) - weaponOnly
      const aligned = dealt('alignment', elements, extras, ehp) - weaponOnly
      assert.ok(plain > 0, `the ${label} arm dealt no elemental damage at all — the harness is not reaching its subject`)
      assert.ok(aligned > plain * 1.25,
        `ALIGNMENT dealt ${Math.round(aligned)} ${label} damage against ${Math.round(plain)} without it ` +
        `(x${(aligned / plain).toFixed(2)}, want >x1.25) — the multiplier never reaches that potency site`)
    }
  }

  // THE FOUR VARIABLE DAMAGE MULTIPLIERS, asserted as DAMAGE. Between them these are the payoff of
  // four cards, and they all arrive through one term in applyDamage — so deleting that single term
  // silently removes all four at once. State assertions cannot see it: the timer still ticks, the
  // counter still grows, the ramp still fills. Only the damage moves.
  {
    const dealt = (id, mutate = () => {}) => {
      const r = withCard(id, (x) => { x.player.hp = 1e9; x.player.maxHP = 1e9 })
      r.weapons = [{ id: 'star', level: 5 }]
      const e = makeStatusEnemy(r, { x: 120, y: 0, hp: 1e9, speed: 0 })
      r.enemies.push(e)
      mutate(r)
      const before = e.hp
      for (let f = 0; f < 180; f++) stepSim(r, { x: 0, y: 0 }, dt)
      return before - e.hp
    }
    const base = dealt(null)
    assert.ok(base > 0, 'the damage harness dealt nothing — it is not reaching its subject')

    // BERSERK: the window has to be open, and it is opened by a hit.
    const zerk = dealt('berserk', (r) => { r._berserkT = BERSERK_DURATION * 100 })
    assert.ok(zerk > base * 1.5, `BERSERK dealt ${zerk} against a baseline ${base} — its multiplier never reaches applyDamage`)

    // STILLNESS: the ramp fills on its own, since the harness gives no input.
    const still = dealt('stillness', (r) => { r._stillT = STILLNESS_RAMP * 10 })
    assert.ok(still > base * 1.5, `STILLNESS dealt ${still} against a baseline ${base} — the ramp is banked but never read`)

    // CHAOS PACT (v7.x): the payoff is now a RAMP — every wave SURVIVED is worth
    // CHAOS_PACT_DMG_PER_WAVE for the rest of the run, rather than a flat multiplier that toggled
    // on between surges. So the assertion is no longer "off during the surge, on after"; it is
    // "more waves behind you means more damage", and the surge simply sits one wave short.
    const late = dealt('chaosPact', (r) => { r.time = CHAOS_PACT_PERIOD * 8 + CHAOS_PACT_SURGE + 1 })
    const early = dealt('chaosPact', (r) => { r.time = CHAOS_PACT_PERIOD * 1 + CHAOS_PACT_SURGE + 1 })
    assert.ok(late > early * 1.2,
      `CHAOS PACT dealt ${late} nine waves in and ${early} two waves in — the ramp is not accumulating`)
    assert.ok(early > base, `CHAOS PACT dealt ${early} against a baseline ${base} — a survived wave pays nothing`)
    // Mid-wave is worth exactly one wave less than just after it: you are paid for SURVIVING.
    const during = dealt('chaosPact', (r) => { r.time = CHAOS_PACT_PERIOD * 2 + 1 })
    const after = dealt('chaosPact', (r) => { r.time = CHAOS_PACT_PERIOD * 2 + CHAOS_PACT_SURGE + 1 })
    assert.ok(during < after,
      `CHAOS PACT dealt ${during} inside wave 3 and ${after} just after it — the wave in progress must not pay until it is survived`)

    // BLOOD PACT: the snowball, forced to a readable size.
    const blood = dealt('bloodPact', (r) => { r._bloodPact = 1 })
    assert.ok(blood > base * 1.5, `BLOOD PACT dealt ${blood} at +100% against a baseline ${base} — the accumulator is never read`)
  }

  // RUNOFF (The Shelf) — the FIFTH variable multiplier, and the only one whose ramp is a chapter
  // bar, so it gets its own block rather than a fifth line above: the bar has to be RE-PINNED every
  // frame. stepCharge drains it, and an upwelling under the parked player refills at 18/s, which
  // would drift the fixture off the pollution level it is meant to be measuring.
  //   Both halves are asserted as EFFECTS. The damage arm reads HP off the enemy because the
  // multiplier arrives through the one term in applyDamage; the speed arm reads DISTANCE because
  // the floor is composed through a MIN with four other slows, and a state assertion on the field
  // would not notice the term being dropped from that composition.
  {
    const SHELF_MAX = CHAPTERS.shelf.resource.max
    const dealtAt = (id, charge) => {
      const r = withCard(id, (x) => { x.player.hp = 1e9; x.player.maxHP = 1e9 }, { chapter: 'shelf' })
      r.weapons = [{ id: 'star', level: 5 }]
      const e = makeStatusEnemy(r, { x: 120, y: 0, hp: 1e9, speed: 0 })
      r.enemies.push(e)
      const before = e.hp
      for (let f = 0; f < 180; f++) { r.charge = charge; stepSim(r, { x: 0, y: 0 }, dt) }
      return before - e.hp
    }
    const filthyOff = dealtAt(null, 0)
    const filthyOn = dealtAt('runoff', 0)
    const cleanOn = dealtAt('runoff', SHELF_MAX)
    assert.ok(filthyOff > 0, 'the RUNOFF harness dealt nothing without the card — it is not reaching its subject')
    assert.ok(filthyOn > filthyOff * (1 + (RUNOFF_MAX_DMG_MUL - 1) * 0.8),
      `RUNOFF dealt ${Math.round(filthyOn)} at full Pollution against ${Math.round(filthyOff)} without it ` +
      `(x${(filthyOn / filthyOff).toFixed(2)}, want ~x${RUNOFF_MAX_DMG_MUL}) — the ramp never reaches applyDamage`)
    // WORTH NOTHING IN CLEAN WATER, and that half is the bargain rather than a detail: a sign error
    // ships a working card that pays you for the opposite behaviour. Same failure MB.d guards for
    // Scour, one table up.
    assert.ok(cleanOn < filthyOff * 1.15,
      `RUNOFF dealt ${Math.round(cleanOn)} in clean water against an unmodded ${Math.round(filthyOff)} — ` +
      'the card must pay nothing at zero Pollution, which is the whole trade')

    // THE COST. Deleting the deeper floor leaves the chapter's own 0.7 and the ratio goes to 1.
    const travelled = (id) => {
      const r = withCard(id, () => {}, { chapter: 'shelf' })
      r.weapons = []
      const x0 = r.player.x, y0 = r.player.y
      for (let f = 0; f < 120; f++) { r.charge = 0; stepSim(r, { x: 1, y: 0 }, dt) }
      return Math.hypot(r.player.x - x0, r.player.y - y0)
    }
    // THE CARD'S OWN SENTENCE, ASSERTED. 'takes twice as much of your speed' compares this card's
    // floor against the chapter's, and those two numbers are authored 4700 lines apart with no
    // import between them — so the word is guarded here rather than trusted. Retune either floor
    // and this goes red, instead of the card quietly describing something it no longer does.
    const chapterFloor = CHAPTERS.shelf.resource.dark.speedFloor
    // Banded, not strictEqual: 1 - 0.7 is 0.30000000000000004, so the true ratio computes as
    // 1.9999999999999998. The tolerance is float noise only — 0.5 would give 1.67 and still fail.
    assert.ok(Math.abs((1 - RUNOFF_SPEED_FLOOR) / (1 - chapterFloor) - 2) < 1e-9,
      `RUNOFF's desc says Pollution "takes twice as much of your speed": the chapter's floor ${chapterFloor} ` +
      `takes ${((1 - chapterFloor) * 100).toFixed(0)}% and the card's ${RUNOFF_SPEED_FLOOR} takes ${((1 - RUNOFF_SPEED_FLOOR) * 100).toFixed(0)}%, ` +
      'which is not twice — the copy is now false')
    const free = travelled(null), slowed = travelled('runoff')
    const want = RUNOFF_SPEED_FLOOR / chapterFloor
    assert.ok(free > 0, 'the RUNOFF movement harness never moved the player at all')
    // Banded around the derived ratio rather than a literal, so re-tuning either floor cannot
    // silently invalidate it. Wide enough to absorb the obstacle field the two arms diverge across
    // — they share a seed, so the WORLD is identical, but the slower arm reaches different places.
    assert.ok(slowed < free * 0.85,
      `RUNOFF moved the player ${slowed.toFixed(0)}px against ${free.toFixed(0)}px at full Pollution — the deeper floor is not being read`)
    assert.ok(Math.abs(slowed / free - want) < 0.10,
      `RUNOFF's slow measured x${(slowed / free).toFixed(3)} against the derived x${want.toFixed(3)} ` +
      `(${RUNOFF_SPEED_FLOOR} over the chapter's ${CHAPTERS.shelf.resource.dark.speedFloor})`)
    console.log(`PASS run PB7 (RUNOFF): dmg ${Math.round(filthyOff)} unmodded / ${Math.round(filthyOn)} at full Pollution / ${Math.round(cleanOn)} clean; travel ${free.toFixed(0)}px -> ${slowed.toFixed(0)}px (x${(slowed / free).toFixed(3)})`)
  }

  // WILDFIRE — the jump, and the BUDGET that stops it being an unkillable cascade.
  {
    const r = withCard('wildfire', (x) => { x.player.hp = 1e9; x.player.maxHP = 1e9 })
    const dying = makeStatusEnemy(r, { x: 200, y: 0, hp: 1, speed: 0 })
    dying.ignite = 1; dying.igniteDps = 50; dying._fireJumps = WILDFIRE_JUMPS
    const near = makeStatusEnemy(r, { x: 200 + WILDFIRE_JUMP_R * 0.5, y: 0, hp: 1e6, speed: 0 })
    const far = makeStatusEnemy(r, { x: 200 + WILDFIRE_JUMP_R * 2, y: 0, hp: 1e6, speed: 0 })
    r.enemies.push(dying, near, far)
    r.weapons = []
    for (let f = 0; f < 240 && !dying._dead; f++) stepSim(r, { x: 0, y: 0 }, dt)
    assert.ok(dying._dead, 'the WILDFIRE fixture never killed its burning enemy')
    assert.ok(near.ignite > 0, 'WILDFIRE did not jump to the enemy in range')
    assert.strictEqual(far.ignite, 0, 'WILDFIRE jumped past WILDFIRE_JUMP_R')
    assert.strictEqual(near._fireJumps, WILDFIRE_JUMPS - 1,
      'the WILDFIRE jump did not spend a budget point — an unbudgeted jump-on-every-death never terminates in a 200-enemy field')
  }

  // MINIMES — the cadence, the flight, and the fact that it reuses the lure entity rather than
  // inventing one (so the taunt and the burst come for free, already tested by the lure weapon).
  {
    const r = withCard('minimes')
    r.lures = []
    for (let f = 0; f < Math.ceil(MINIME_INTERVAL * 60) + 2; f++) stepSim(r, { x: 0, y: 0 }, dt)
    assert.ok(r.lures.length > 0, `MINIMES spawned nothing in ${MINIME_INTERVAL}s`)
    const m = r.lures[0]
    assert.ok(m.minime, 'the spawned decoy is not flagged as a minime')
    const d0 = Math.hypot(m.x - r.player.x, m.y - r.player.y)
    for (let f = 0; f < 30; f++) stepSim(r, { x: 0, y: 0 }, dt)
    const still = r.lures.find((l) => l === m)
    if (still) {
      assert.ok(Math.hypot(still.x - r.player.x, still.y - r.player.y) > d0,
        'a MINIME did not flee — without movement it parks the swarm next to you instead of pulling it away')
    }
    // A plain planted lure must still be motionless, or this broke the weapon.
    const w = withCard(null)
    w.lures = [{ x: 0, y: 0, t: 0, dur: 99, aggro: 100, burstR: 10, burstDmg: 1, sticky: false }]
    for (let f = 0; f < 30; f++) stepSim(w, { x: 0, y: 0 }, dt)
    assert.strictEqual(w.lures[0].x, 0, 'a Pheromone Lure moved — MINIMES broke the weapon it borrows')
  }

  // DEADFALL — immunity AND the re-arm. Immunity alone is "one fewer thing hurts you", a stat in a
  // costume; the fast re-arm is what turns the field into a weapon.
  {
    const trapped = (id) => {
      const r = withCard(id, (x) => { x.player.hp = 1e9; x.player.maxHP = 1e9 })
      r.chapter = 'undergrowth'
      r.traps = [{ x: 0, y: 0, r: 40, armed: true, rearmAt: 0 }]
      r.player.invuln = 0
      stepSim(r, { x: 0, y: 0 }, dt)
      return r.traps[0]
    }
    assert.ok(!trapped(null).armed, 'the trap fixture did not spring on a plain run — it is not reaching its subject')
    assert.ok(trapped('deadfall').armed, 'DEADFALL did not make the player invisible to traps')
    // The re-arm through the TRAP, not through the constant — `DEADFALL_REARM_MUL < 1` is a config
    // read that stays green with the multiplier deleted from springTrap. Immunity alone is "one
    // fewer thing hurts you", a stat in a costume; the fast cycle is what makes the field a weapon.
    const rearm = (id) => {
      const r = withCard(id, (x) => { x.player.hp = 1e9; x.player.maxHP = 1e9 })
      r.chapter = 'undergrowth'
      r.time = 10
      const tr = { x: 300, y: 0, r: 40, armed: true, rearmAt: 0 }
      r.traps = [tr]
      r.enemies.push(makeStatusEnemy(r, { x: 300, y: 0, hp: 1e6, speed: 0 }))
      stepSim(r, { x: 0, y: 0 }, dt)
      assert.ok(!tr.armed, 'the re-arm fixture never sprang the trap')
      return tr.rearmAt - r.time
    }
    const plainRearm = rearm(null), fastRearm = rearm('deadfall')
    assert.ok(fastRearm < plainRearm * 0.5,
      `DEADFALL re-armed in ${fastRearm.toFixed(1)}s against ${plainRearm.toFixed(1)}s — springTrap is not reading the multiplier`)
  }

  // SPECIALIST (v7.5) — the only card on the slate whose whole effect is on the level-up POOL, so
  // it is the only one that cannot be asserted with the `withCard` fixture above.
  // The first version of this scenario hand-wrote `r.anomalies.specialist = 'orbit'`, which meant
  // rollAnomalyCard's subject list and applyChoice's banking were executed by NO test: an
  // adversarial review mutated applyChoice to bank `true` instead of the weapon and the suite
  // stayed green, with the card a complete no-op in the real game. Everything below therefore
  // goes through the REAL path — roll a screen, find the card, applyChoice it.
  {
    const OWNED = ['star', 'orbit', 'wave', 'boomerang']
    const armed = (focus) => {
      Math.random = mulberry32(20260808)
      const m = makeMeta()
      m.choiceSlots = MAX_CHOICE_SLOTS
      const r = createRun(m, { chapter: 'body' })
      r.weapons = OWNED.map((id) => ({ id, level: 3 }))
      for (const id of OWNED) {
        const first = Object.keys(WEAPON_MODS[id])[0]
        r.weaponModPicks[id][first] = SPECIALIST_MIN_MODS   // past the gate, one mod still free
      }
      if (focus) {
        // The real delivery path, end to end: build the card rollAnomalyCard would, hand it to
        // applyChoice with the player's named weapon, and let applyChoice do the banking.
        const subjects = specialistSubjects(r)
        assert.deepStrictEqual(subjects.slice().sort(), OWNED.slice().sort(),
          `specialistSubjects returned ${JSON.stringify(subjects)} — every owned weapon is past the gate, so the chooser should offer all four`)
        r.levelUpChoices = [{ kind: 'anomaly', id: 'specialist', subjects }]
        applyChoice(r, 0, focus)
        assert.strictEqual(r.anomalies.specialist, focus,
          `applyChoice banked ${JSON.stringify(r.anomalies.specialist)} for SPECIALIST, not the weapon the player named — a truthy non-string focuses nothing, silently`)
      }
      return r
    }
    // ...and an unnamed take must still land on a LEGAL weapon rather than `true`, because the
    // probe harness and any UI path that skips the chooser go through exactly this branch.
    {
      const r = armed(null)
      r.levelUpChoices = [{ kind: 'anomaly', id: 'specialist', subjects: specialistSubjects(r) }]
      applyChoice(r, 0)
      assert.ok(OWNED.includes(r.anomalies.specialist),
        `a SPECIALIST taken with no subject banked ${JSON.stringify(r.anomalies.specialist)} — a caller that never opened the chooser must still get a working card`)
    }

    const screens = (focus) => {
      const r = armed(focus)
      const perWeapon = {}
      let mods = 0, cards = 0
      for (let i = 0; i < 3000; i++) {
        r._screenRerolls = -1
        for (const c of buildLevelUpChoices(r)) {
          cards++
          if (c.kind !== 'mod') continue
          perWeapon[c.weapon] = (perWeapon[c.weapon] ?? 0) + 1
          mods++
        }
      }
      return { share: (id) => (perWeapon[id] ?? 0) / mods, mods, cards }
    }
    const off = screens(null), on = screens('orbit')
    assert.ok(off.mods > 500 && on.mods > 500, 'the SPECIALIST fixture rolled almost no mod cards — it is not reaching its subject')
    assert.ok(Math.abs(off.share('orbit') - 0.25) < 0.04,
      `the unfocused control gave orbit ${(off.share('orbit') * 100).toFixed(1)}% of mod cards, not ~25% — the fixture is unbalanced and the comparison below would be meaningless`)
    assert.ok(on.share('orbit') > off.share('orbit') * 1.5,
      `SPECIALIST moved orbit's mod share ${(off.share('orbit') * 100).toFixed(1)}% -> ${(on.share('orbit') * 100).toFixed(1)}% — rollCard is not weighting the named weapon`)
    // A REDISTRIBUTION, not a bucket buff. Measured as mod cards' share of ALL cards, which is the
    // quantity the spec forbids the card from moving — an earlier version lifted the per-screen cap
    // and MOD_POOL_MAX, which kept the mod bucket ALIVE on screens that would have dropped it and
    // measured +17.8% mod share at two slots. Counting mods alone cannot see that; this can.
    const modShare = (x) => x.mods / x.cards
    assert.ok(Math.abs(modShare(on) / modShare(off) - 1) < 0.05,
      `SPECIALIST moved mod cards' share of the whole pool ${(modShare(off) * 100).toFixed(1)}% -> ${(modShare(on) * 100).toFixed(1)}% — it is creating deliverability, not aiming it`)

    // THE CEILING, which is the half a player actually feels: the focused weapon's mods stay
    // eligible past MAX_WEAPON_MOD_PICKS, and nobody else's do.
    {
      const r = armed('orbit')
      const modId = Object.keys(WEAPON_MODS.orbit).find((k) => WEAPON_MODS.orbit[k].kind !== 'switch' && WEAPON_MODS.orbit[k].maxPicks == null)
      const otherId = Object.keys(WEAPON_MODS.star).find((k) => WEAPON_MODS.star[k].kind !== 'switch' && WEAPON_MODS.star[k].maxPicks == null)
      assert.ok(modId && otherId, 'no uncapped mod found for the ceiling fixture')
      r.weaponModPicks.orbit[modId] = MAX_WEAPON_MOD_PICKS
      r.weaponModPicks.star[otherId] = MAX_WEAPON_MOD_PICKS
      const offered = new Set()
      for (let i = 0; i < 3000; i++) {
        r._screenRerolls = -1
        for (const c of buildLevelUpChoices(r)) if (c.kind === 'mod') offered.add(`${c.weapon}:${c.id}`)
      }
      assert.ok(offered.has(`orbit:${modId}`),
        `a maxed mod on the FOCUSED weapon was never offered again — SPECIALIST_EXTRA_PICKS is not reaching modPickCap, and the card loses the only thing about it a player can feel`)
      assert.ok(!offered.has(`star:${otherId}`),
        `a maxed mod on an UNFOCUSED weapon was still offered — the raised ceiling is leaking to every weapon, which makes it a global cap change wearing a card's name`)
    }
  }

  // BLIND FAITH (v7.5) — like SPECIALIST this one lives in the POOL, so it needs the screen fixture
  // rather than `withCard`. Five separate promises, each read at a different site, each able to die
  // without the others noticing. Two of these exist because an adversarial review found the holes:
  // the shipped cost was a NO-OP at the default slot count, and the floor silently locked armor and
  // regen to 100% legendary.
  {
    const screens = (blind, { slots = MAX_CHOICE_SLOTS, rerolls = -1 } = {}) => {
      Math.random = mulberry32(20260808)
      const m = makeMeta()
      m.choiceSlots = slots
      const r = createRun(m, { chapter: 'body' })
      // Weapons chosen for their SWITCH mods (stinger has two), because one assertion below is
      // about the class of card the floor removes — a fixture without one proves nothing.
      r.weapons = ['stinger', 'bloom', 'lure', 'clawRake'].map((id) => ({ id, level: 3 }))
      if (blind) r.anomalies.blindFaith = true
      const rarities = {}, valueTiers = {}
      let cards = 0, switches = 0, dealt = 0
      for (let i = 0; i < 2000; i++) {
        r._screenRerolls = rerolls
        const row = buildLevelUpChoices(r)
        dealt++
        for (const c of row) {
          rarities[c.rarity] = (rarities[c.rarity] ?? 0) + 1
          if (c.kind === 'mod' && WEAPON_MODS[c.weapon][c.id].kind === 'switch') switches++
          if (c.kind === 'passive' && PASSIVES[c.id].values) {
            valueTiers[c.id] = valueTiers[c.id] ?? {}
            valueTiers[c.id][c.rarity] = (valueTiers[c.id][c.rarity] ?? 0) + 1
          }
          cards++
        }
      }
      return { rarities, valueTiers, cards, switches, perScreen: cards / dealt }
    }
    const seeing = screens(false), blind = screens(true)

    // 1. THE FLOOR. Every rarity string the screen produced is checked, NOT just the ones that
    // happen to be on the ladder: filtering on RARITY_ORDER.includes() is how the first version of
    // this assertion missed a whole class of card being restamped to a non-ladder value.
    const floorIdx = RARITY_ORDER.indexOf(BLIND_FAITH_FLOOR)
    const legal = new Set([...RARITY_ORDER.slice(floorIdx), UPGRADE_RARITY])
    const below = Object.keys(blind.rarities).filter((k) => !legal.has(k))
    assert.ok(seeing.rarities.normal > 0 && seeing.rarities.rare > 0,
      'the sighted control dealt no normal/rare cards at all — the fixture is not reaching the rarity roll')
    assert.deepStrictEqual(below, [],
      `BLIND FAITH dealt tiers below ${BLIND_FAITH_FLOOR}: ${JSON.stringify(below.map((k) => [k, blind.rarities[k]]))} — the floor is not applied everywhere the table is rolled`)

    // 2. THE FLOOR SURVIVES A REROLL. Both fixtures used to pin _screenRerolls at -1, so `rr` was
    // always 0 and rarityTableFor could be deleted from the reroll branch with the suite green —
    // the exact path BLOOD MONEY charges escalating HP for.
    const blindRerolled = screens(true, { rerolls: REROLL_RARITY_CAP })
    const belowRR = Object.keys(blindRerolled.rarities).filter((k) => !legal.has(k))
    assert.deepStrictEqual(belowRR, [],
      `after ${REROLL_RARITY_CAP} rerolls BLIND FAITH dealt ${JSON.stringify(belowRR)} — the decayed table is not being floored`)

    // 3. THE COST IS PAID AT THE DEFAULT SLOT COUNT. This is the assertion that would have caught
    // the shipped no-op: the cost was `Math.min(choiceSlots, 2)` and choiceSlots DEFAULTS to 2, so
    // the default player paid nothing at all. Asserted on the price, not the card count, and at the
    // default rather than the maximum.
    {
      Math.random = mulberry32(20260808)
      const m = makeMeta()
      const plain = createRun(m, { chapter: 'body' })
      assert.strictEqual(plain.choiceSlots, 2, 'the default choiceSlots moved — the cost assertion below is written against it being the DEFAULT, not a number')
      assert.ok(rerollPrice(plain).available !== false, 'a plain run could not reroll — the comparison below is meaningless')
      assert.ok(rerollLevelUpChoices(plain) !== false || true, 'sanity')
      const bf = createRun(m, { chapter: 'body' })
      bf.anomalies.blindFaith = true
      bf.coinsEarned = 100000
      bf.levelUpChoices = buildLevelUpChoices(bf)
      assert.strictEqual(rerollPrice(bf).available, false,
        'BLIND FAITH still offers a reroll — that purchase IS the card\'s entire price')
      assert.strictEqual(rerollLevelUpChoices(bf), false,
        'BLIND FAITH let a reroll through sim-side with 100000 coins in hand — a ui-only gate is a rule the console walks around')
      // ...and the screen is NOT shortened, which was the cost that did not work. The reveal is the
      // emotion this card was asked for and it needs cards to reveal.
      const bf4 = createRun(makeMeta(), { chapter: 'body' })
      bf4.choiceSlots = MAX_CHOICE_SLOTS
      bf4.anomalies.blindFaith = true
      assert.strictEqual(buildLevelUpChoices(bf4).length, MAX_CHOICE_SLOTS,
        'BLIND FAITH shortened the screen — the slot cost was removed precisely because it was a no-op at the default and it ate the reveal')
    }

    // 4. THE FLOOR IS NOT A CEILING. armor/regen declare their OWN tier table ({normal, rare,
    // legendary}); flooring it left exactly one surviving key, so every one of them dealt legendary
    // — armor a flat 20 at max level, which is the number BERSERK's shipped safety argument is
    // licensed against ("armor measures 2.4-3.7 in real runs"). BLIND FAITH + BERSERK is a legal
    // pair. A rarity floor must never silently top out the two cards that block damage.
    // The control must actually deal them, or the assertion below is vacuous.
    assert.ok((seeing.valueTiers.armor?.normal ?? 0) > 0 && (seeing.valueTiers.regen?.normal ?? 0) > 0,
      'the sighted control never dealt a normal armor/regen card — the values-passive assertion below proves nothing')
    for (const id of Object.keys(blind.valueTiers)) {
      const tiers = blind.valueTiers[id]
      const total = Object.values(tiers).reduce((a, b) => a + b, 0)
      const top = Math.max(...Object.values(tiers))
      assert.ok(top < total,
        `every ${id} card under BLIND FAITH came out ${Object.keys(tiers)[0]} (${total}/${total}) — the floor is acting as a CEILING on a values-passive, which is BERSERK's safety argument deleted`)
    }
    // ...and armor/regen specifically are the pair the floor reduces to ONE legal tier, so they
    // must leave the pool rather than be dealt at a fixed tier forever.
    for (const id of ['armor', 'regen']) {
      const legalTiers = Object.keys(PASSIVES[id].values).filter((r) => RARITY_ORDER.indexOf(r) >= floorIdx)
      assert.strictEqual(legalTiers.length, 1,
        `${id} now declares ${legalTiers.length} tiers at or above ${BLIND_FAITH_FLOOR} — this assertion was written for the one-legal-tier case and needs rethinking, not deleting`)
      assert.ok(!blind.valueTiers[id],
        `${id} was still offered under BLIND FAITH with only ${JSON.stringify(legalTiers)} legal — it can only ever deal that one tier, so the border says the same word whatever was rolled and armor reaches a flat ${PASSIVES.armor.values.legendary * MAX_PASSIVE_LEVEL} at max level`)
    }

    // 5. THE SIDE EFFECT, pinned as a decision rather than an accident: a `switch` mod is offered
    // only at normal rarity, so under the floor it could only reach a blind screen through
    // rollCard's all-declined fallback — wearing a border the card forbade.
    assert.ok(seeing.switches > 0, 'the sighted control was never offered a switch mod — the switch assertion below proves nothing')
    assert.strictEqual(blind.switches, 0,
      `BLIND FAITH still offered ${blind.switches} switch mods`)

    // ...and the case that actually needs the explicit drop, which the sample above CANNOT reach:
    // one weapon whose only surviving mod IS a switch, so EVERY candidate declines the floor. The
    // 2000-screen sample stays green with the drop deleted (a four-weapon pool practically never
    // rolls an all-switch bucket), so do not delete this as redundant — it is the whole point.
    {
      Math.random = mulberry32(20260808)
      const m = makeMeta()
      m.choiceSlots = MAX_CHOICE_SLOTS
      const r = createRun(m, { chapter: 'body' })
      r.weapons = [{ id: 'clawRake', level: 3 }]
      for (const [id, cfg] of Object.entries(WEAPON_MODS.clawRake)) {
        if (cfg.kind !== 'switch') r.weaponModPicks.clawRake[id] = MAX_WEAPON_MOD_PICKS
      }
      r.anomalies.blindFaith = true
      let sawSwitch = 0, illegal = 0, shortScreens = 0
      for (let i = 0; i < 400; i++) {
        r._screenRerolls = -1
        const row = buildLevelUpChoices(r)
        if (row.length < MAX_CHOICE_SLOTS) shortScreens++
        for (const c of row) {
          if (!legal.has(c.rarity)) illegal++
          if (c.kind === 'mod' && WEAPON_MODS[c.weapon][c.id].kind === 'switch') sawSwitch++
        }
      }
      assert.strictEqual(sawSwitch, 0,
        `an all-switch mod bucket still dealt ${sawSwitch} switch cards under BLIND FAITH — eligibleWeaponModCandidates is not dropping them`)
      assert.strictEqual(illegal, 0,
        `an all-switch mod bucket dealt ${illegal} cards below ${BLIND_FAITH_FLOOR} — a fallback is printing a tier the floor forbade (the 'Snack Break' heal card was one of these)`)
      assert.strictEqual(shortScreens, 0,
        `${shortScreens}/400 blind screens came back short — a declining mod is propagating null out of rollCard and breaking the slot loop, which reads to a player as a missing card`)
    }
  }

  // IPECAC (v7.5). Asserted against the failure that killed its FIRST version, not against a count:
  // 1/2 fire rate for x3 DAMAGE measured +1.1% because overkill ate the whole multiplier. So the
  // bar every assertion here is written to is "does the surplus land in DIFFERENT SPACE" — a x3
  // that stacks onto one dying enemy is the old card wearing a new number, and it would pass any
  // test that only counted projectiles.
  {
    // Three enemies at 120 degrees, all in range, all unkillable — so what is being measured is
    // COVERAGE and never who died first.
    const ring = (r, dist = 90) => [0, 1, 2].map((i) => {
      const a = (i / 3) * Math.PI * 2
      return makeStatusEnemy(r, { x: Math.cos(a) * dist, y: Math.sin(a) * dist, hp: 1e9, speed: 0 })
    })
    // ONE cast, not four seconds of them. A sector weapon re-aims per cast and knocks its target
    // back, so over several casts it sweeps the whole ring on its own and a coverage assertion
    // reads green with the card deleted — which is exactly what the first version of this fixture
    // did. Step until damage first lands, take that frame's spread, stop.
    const swing = (id, weaponId) => {
      const r = withCard(id, (x) => { x.player.hp = 1e9; x.player.maxHP = 1e9 })
      r.weapons = [{ id: weaponId, level: 3 }]
      r.time = 5
      const foes = ring(r)
      for (const e of foes) r.enemies.push(e)
      const before = foes.map((e) => e.hp)
      for (let i = 0; i < 600; i++) {
        stepSim(r, { x: 0, y: 0 }, dt)
        const dealt = foes.map((e, n) => before[n] - e.hp)
        if (dealt.some((d) => d > 0)) return dealt
      }
      return foes.map((e, n) => before[n] - e.hp)
    }
    // ROAR is a CONE: without the card it can only ever reach the one enemy it is aimed at.
    const plainRoar = swing(null, 'roar'), ipecacRoar = swing('ipecac', 'roar')
    assert.ok(plainRoar.filter((d) => d > 0).length === 1,
      `a plain roar hit ${plainRoar.filter((d) => d > 0).length} of 3 ringed enemies — the fixture is not a cone test and the assertion below proves nothing`)
    assert.strictEqual(ipecacRoar.filter((d) => d > 0).length, 3,
      `IPECAC's roar hit ${ipecacRoar.filter((d) => d > 0).length} of 3 enemies at 120 degrees — the extra output is not landing in different space, which is exactly how the x3 DAMAGE version measured +1.1%`)
    // ...and the surplus must be SPREAD, not stacked: the aimed enemy must not eat three cones.
    const aimed = Math.max(...ipecacRoar), far = Math.min(...ipecacRoar)
    assert.ok(aimed < far * 2,
      `IPECAC's roar dealt ${aimed.toFixed(0)} to the nearest enemy against ${far.toFixed(0)} to the far one — the sectors are overlapping and one body is eating the x3, which is the overkill trap this card exists to avoid`)

    // v7.23: the Tail Swipe rows that used to sit here are GONE, and the reason is worth stating
    // rather than silently deleting. They tested the one weapon whose SECTOR (126-169 degrees) was
    // wider than IPECAC's 120 degree spacing, so its three sweeps overlapped and it silently became
    // x3 damage on one body. Tail Swipe is now the Tail Lash, a thin LINE — and with it gone no
    // weapon in the game has an arc exceeding 120 degrees, so that failure mode no longer exists.
    //
    // The hazard does not vanish, it MOVES: three rays 120 degrees apart all pass within
    // width/2 + radius of a body sitting near the player, so a close enemy is on all three lines at
    // once. That is the same x3-on-one-body trap in the new geometry, and it is what fireLash's
    // shared `hit` set now guards. Tested here, because the ring fixture above cannot reach it —
    // three enemies at 120 degrees sit one per ray however thin the ray is.
    {
      // `far` sits out at 300px and takes the aim (the lash aims at the FARTHEST, not the nearest).
      // `close` sits 12px from the player, where all three IPECAC rays cover it at once.
      const pair = (id) => {
        const r = withCard(id, (x) => { x.player.hp = 1e9; x.player.maxHP = 1e9 })
        r.weapons = [{ id: 'tailLash', level: 3 }]
        r.time = 5
        const close = makeStatusEnemy(r, { x: 0, y: 12, hp: 1e9, speed: 0 })
        const far = makeStatusEnemy(r, { x: 300, y: 0, hp: 1e9, speed: 0 })
        r.enemies.push(close, far)
        const c0 = close.hp, f0 = far.hp
        for (let i = 0; i < 600; i++) {
          stepSim(r, { x: 0, y: 0 }, dt)
          if (c0 - close.hp > 0 || f0 - far.hp > 0) return { close: c0 - close.hp, far: f0 - far.hp }
        }
        return { close: 0, far: 0 }
      }
      const plain = pair(null), sick = pair('ipecac')
      assert.ok(plain.far > 0, 'the tailLash fixture never connected — it is not reaching its subject')
      assert.ok(sick.close > 0,
        'the close enemy took nothing under IPECAC — the extra rays are not lashing, so this fixture is not testing what it claims')
      // One lash's worth is what the aimed enemy takes. The body under all three rays must not take three.
      assert.ok(sick.close <= plain.far * 1.5,
        `an enemy sitting on all three IPECAC rays took ${sick.close.toFixed(0)} against ${plain.far.toFixed(0)} for a single lash — the rays overlap and one body is eating the x3, which is the overkill trap the whole card was rewritten to escape`)
    }

    // ...and roar's own de-duplication, which the ring above equally cannot reach: roar's cone is
    // narrower than the 120 degree spacing, so its three sectors never overlap — EXCEPT on a
    // `resonance` cast, where every one of them opens to a full circle and the same body sits in all
    // three. Forced rather than waited for: resonance fires every ROAR_RESONANCE_EVERY casts.
    {
      const boom = (id) => {
        const r = withCard(id, (x) => { x.player.hp = 1e9; x.player.maxHP = 1e9 })
        r.weapons = [{ id: 'roar', level: 3 }]
        r.weaponMods.roar = { resonance: 1 }
        r.time = 5
        r._roarCasts = ROAR_RESONANCE_EVERY - 1   // the next cast opens to 360 degrees
        const e = makeStatusEnemy(r, { x: 60, y: 0, hp: 1e9, speed: 0 })
        r.enemies.push(e)
        const before = e.hp
        for (let i = 0; i < 600; i++) {
          stepSim(r, { x: 0, y: 0 }, dt)
          if (before - e.hp > 0) return before - e.hp
        }
        return 0
      }
      const once = boom(null), thrice = boom('ipecac')
      assert.ok(once > 0, 'the roar resonance fixture never connected — it is not reaching its subject')
      assert.ok(thrice <= once * 1.5,
        `on a resonance cast IPECAC's roar dealt ${thrice.toFixed(0)} to one enemy against ${once.toFixed(0)} — every sector is a full circle there, so without the shared set the same body eats all three and the card is x3 DAMAGE again`)
    }

    // EVERY WEAPON, ENUMERATED. Written after the shipped card was found to do NOTHING AT ALL to
    // three of the 22 (burstHydrant, debrisToss, realityShard were simply never patched) and to
    // stack orbit's ring three-deep on five points instead of spreading it over fifteen. Neither
    // was visible to the hand-picked fixtures above, and the orbit one was caught BY EYE from a
    // screenshot that looked unchanged — which is exactly what "15 orbs in 5 positions" looks like.
    //
    // So the assertion is DISTINCT POSITIONS, never a count. A count passes when three things are
    // spawned on top of each other, and three things in one place is the x3 DAMAGE card this whole
    // rewrite exists to escape. Weapons that spawn no entity at all (the melee sectors) are counted
    // by their FX events instead — three sweeps push three events.
    {
      // v7.23: 'arcs' added for Atomic Breath. Its entries carry x/y = the fork's ROOT body, which
      // is what makes IPECAC's three forks distinguishable here — they anchor on three different
      // enemies, so the shape key below separates them. (This list is a set of QUOTED STRINGS, the
      // exact thing an identifier rename sweep cannot see — see CLAUDE.md's rename rule.)
      // The Surf's three natives need no entry beyond 'novas' and 'bullets': the Breaker is a nova
      // carrying arc/carry, and the Skipping Shell and Barnacles are tagged run.bullets carriers.
      // Adding no array is the point — see the state.js doc block. Their IPECAC copies sit at 120°
      // from each other around the player and the shape key separates them —
      // and without this entry the weapon spawns into no list this block watches, which reads as
      // "fixture spawned nothing" rather than as a missing patch. That is the CLAUDE.md rename trap
      // in its other direction: a list of QUOTED STRINGS no identifier sweep and no new-weapon
      // checklist can see.
      // ⚠ THESE ARE run.* FIELD NAMES AS QUOTED STRINGS, which no rename or identifier sweep can
      // see — CLAUDE.md documents this exact array as the place `run.geysers` was missed. A weapon
      // whose output lands in a field absent from here reports "fixture spawned nothing —
      // untestable", which is this list being out of date and not the weapon being broken.
      // 'polyps' is The Reef's Fire Coral (v7.x) — the first weapon in Book 2 to need an array of
      // its own, and the day it landed this fixture reported 'spawned nothing' for a weapon that
      // was firing correctly, exactly as the comment above says it would.
      const LISTS = ['bullets', 'orbs', 'mines', 'zones', 'lobs', 'blooms', 'lures', 'holes', 'beams', 'debris', 'homingShots', 'boomerangs', 'novas', 'arcs', 'longlines', 'polyps']
      // Same class of quoted-string list as LISTS above, and it bit for real: `gnash` (The Wreck's
      // native, v7.x) spawns no entity at all — its whole output is this event — so the day it
      // landed this fixture reported "spawned nothing — untestable here" for a weapon that was
      // firing correctly. A melee weapon whose event type is missing from this array is invisible
      // to the assertion below.
      const FX = ['whip', 'clawRake', 'roar', 'tail', 'gnash']
      // ⚠ SOME WEAPONS CANNOT BE MEASURED BY A MOTIONLESS PLAYER. The fixture below holds the stick
      // at zero, which is right for the other 22 weapons — it keeps the ring of targets and the
      // player in a fixed relationship, so `seen` is comparable frame to frame. Fin Hit's damage
      // and its very existence read the player's VELOCITY (it returns early at a standstill and
      // spawns nothing), so a motionless fixture reports "spawned nothing — untestable" for a
      // weapon that is working perfectly. The stick is therefore per-weapon, and the set is
      // explicit rather than a heuristic: any future movement-coupled card has to be added here or
      // it will fail this assertion with a message about the wrong thing.
      const NEEDS_MOTION = new Set(['finHit'])
      // ⚠ AND SOME WEAPONS CANNOT BE MEASURED IN THE DEFAULT CHAPTER AT ALL. Fire Coral arms the
      // coral RIDGES, so in a chapter with no spur field it correctly does nothing and this
      // fixture reads 'spawned nothing — untestable' about a weapon that works. Same shape as the
      // stick above: an explicit per-weapon override, not a heuristic, so the next terrain-coupled
      // card has to be named here rather than failing with a message about the wrong thing.
      const CHAPTER_FOR = { fireCoral: 'reef' }
      const spread = (id, weaponId) => {
        const r = withCard(id, (x) => { x.player.hp = 1e9; x.player.maxHP = 1e9 }, CHAPTER_FOR[weaponId] ? { chapter: CHAPTER_FOR[weaponId] } : {})
        assert.strictEqual(r.chapter, CHAPTER_FOR[weaponId] ?? r.chapter, `the ${weaponId} arm did not boot in ${CHAPTER_FOR[weaponId]} — a WIP gate sent it elsewhere and it would report 'spawned nothing'`)
        r.weapons = [{ id: weaponId, level: 3 }]
        r.time = 5
        const stick = NEEDS_MOTION.has(weaponId) ? { x: 1, y: 0 } : { x: 0, y: 0 }
        // A ring of unkillable enemies, so every weapon has something to aim at, place a zone on,
        // or lock onto — and nothing dies to change the picture mid-cast.
        for (let i = 0; i < 12; i++) {
          const a = (i / 12) * Math.PI * 2
          r.enemies.push(makeStatusEnemy(r, { x: Math.cos(a) * 140, y: Math.sin(a) * 140, hp: 1e9, speed: 0 }))
        }
        let best = 0
        for (let i = 0; i < 900; i++) {
          stepSim(r, stick, dt)
          // A moving player would otherwise leave the ring of targets behind within a second, and
          // every weapon that aims at an enemy would then measure an empty field. Pinning keeps the
          // fixture's geometry identical to the motionless case while still giving the sim a real
          // velocity to read — the same trick run DP.g needs, and for the same reason.
          if (stick.x || stick.y) { r.player.x = 0; r.player.y = 0 }
          const seen = new Set()
          // Keyed by SHAPE, not position alone. Several weapons spawn everything at the player and
          // differ only in heading (beams), in radius (novas — they spread by band, not by place)
          // or in an arm COUNT carried on one entity (pulsarSweep). Position alone reads all of
          // those as a single thing and would wave the card through for three of the 22 weapons.
          for (const key of LISTS) {
            for (const o of r[key] ?? []) {
              // An ARM is a separate piece of output that happens to be stored as a field on one
              // entity (pulsarSweep), so it is expanded rather than counted as one thing —
              // otherwise a beam that folds into six creases reads identically to one that folds
              // into two.
              const arms = Math.max(1, o.arms ?? 1)
              for (let k = 0; k < arms; k++) {
                // `i` is Fire Coral's ridge INDEX, and it is the shape here for the same reason
                // `angle` is a beam's: a lit ridge has no x/y at all (it is a band across the
                // lane, addressed by index), so position alone reads three DIFFERENT ridges as
                // one thing and waves the card through — the exact failure this key exists for.
                seen.add(`${key}:${Math.round(o.x)},${Math.round(o.y)},${(o.angle ?? 0).toFixed(2)},${Math.round(o.radius ?? o.r ?? 0)},i${o.i ?? ''},arm${k}`)
              }
            }
          }
          for (const e of r.events) if (FX.includes(e.type)) seen.add(`fx:${e.type}:${(e.angle ?? 0).toFixed(3)}`)
          best = Math.max(best, seen.size)
        }
        return best
      }
      const missed = []
      for (const weaponId of Object.keys(WEAPONS)) {
        const plain = spread(null, weaponId)
        const sick = spread('ipecac', weaponId)
        if (plain === 0) { missed.push(`${weaponId} (fixture spawned nothing — untestable here)`); continue }
        if (sick <= plain) missed.push(`${weaponId} ${plain} -> ${sick}`)
      }
      assert.deepStrictEqual(missed, [],
        `IPECAC did not widen these weapons' output: ${JSON.stringify(missed)} — either the fire site was never patched, or the count was tripled while the ANGLE/POSITION divisor was not, which stacks the extra output on top of the original and hands the whole x3 to overkill`)
    }

    // THE FIRE RATE, which is the entire cost and is applied once on take.
    {
      const base = withCard(null), sick = withCard('ipecac')
      assert.ok(Math.abs(sick.player.fireRateMul / base.player.fireRateMul - IPECAC_FIRE_MUL) < 1e-9,
        `IPECAC moved fireRateMul x${(sick.player.fireRateMul / base.player.fireRateMul).toFixed(2)}, not x${IPECAC_FIRE_MUL} — the card is pure upside without it`)
    }

    // A COUNT weapon: three projectiles per cast, not one.
    {
      const fired = (id) => {
        const r = withCard(id, (x) => { x.player.hp = 1e9; x.player.maxHP = 1e9 })
        r.weapons = [{ id: 'star', level: 3 }]
        r.time = 5
        r.enemies.push(makeStatusEnemy(r, { x: 200, y: 0, hp: 1e9, speed: 0 }))
        // The FIRST volley only. Counting a peak over a window would compare four casts against
        // two (the card halves the fire rate), which measures the cost and calls it the payoff.
        for (let i = 0; i < 600; i++) {
          stepSim(r, { x: 0, y: 0 }, dt)
          if (r.bullets.length > 0) return r.bullets.length
        }
        return 0
      }
      const one = fired(null), three = fired('ipecac')
      assert.ok(one > 0, 'the star fixture never fired — it is not reaching its subject')
      assert.ok(three >= one * IPECAC_COUNT_MUL,
        `IPECAC's star put ${three} bullets up against ${one} — ipecacN is not reaching the fire site`)
    }

    // HOMING is the load-bearing row in the spec's own table: three seekers that all lock the
    // nearest enemy is a x3 overkill eats whole. Asserted by where the DAMAGE lands, across two
    // enemies far enough apart that a shared lock cannot reach both.
    // The rule, in the owner's words: cover three different enemies if three exist; if there are
    // fewer, fall back to the one or two closest. All three cases are asserted, because the
    // interesting bug lives in the SECOND one — a claim set with no fallback leaves the surplus
    // seeker with no target at all, which looks like "spreading" and is actually a dead projectile.
    {
      const seek = (id, n) => {
        const r = withCard(id, (x) => { x.player.hp = 1e9; x.player.maxHP = 1e9 })
        r.weapons = [{ id: 'homing', level: 3 }]
        r.time = 5
        // Evenly around the player, all identical, all unkillable: the only thing that can differ
        // between arms is WHICH of them the seekers chose.
        const foes = Array.from({ length: n }, (_, i) => {
          const a = (i / n) * Math.PI * 2
          return makeStatusEnemy(r, { x: Math.cos(a) * 150, y: Math.sin(a) * 150, hp: 1e9, speed: 0 })
        })
        for (const e of foes) r.enemies.push(e)
        const before = foes.map((e) => e.hp)
        for (let i = 0; i < 300; i++) stepSim(r, { x: 0, y: 0 }, dt)
        return foes.map((e, i) => before[i] - e.hp)
      }
      // THREE OR MORE: three distinct enemies take damage.
      const three = seek('ipecac', 3)
      assert.strictEqual(three.filter((d) => d > 0).length, 3,
        `IPECAC's seekers hit ${three.filter((d) => d > 0).length} of 3 available enemies — they are sharing a lock, and a x3 poured into one body is what overkill eats whole`)
      const plainThree = seek(null, 3)
      assert.ok(plainThree.filter((d) => d > 0).length < 3,
        `an unmodified homing volley already hit ${plainThree.filter((d) => d > 0).length} of 3 — the control is not a shared-lock control and the assertion above proves nothing`)
      // EXACTLY TWO: both are covered, and no seeker is left without a target.
      const two = seek('ipecac', 2)
      assert.strictEqual(two.filter((d) => d > 0).length, 2,
        `with only 2 enemies IPECAC's seekers covered ${two.filter((d) => d > 0).length} — the fallback is not firing and a seeker with every enemy claimed is flying blind`)
      // EXACTLY ONE: all three hunt it rather than stalling.
      const one = seek('ipecac', 1)
      assert.ok(one[0] > 0,
        'with a single enemy IPECAC\'s seekers dealt no damage at all — every seeker found its only target claimed and gave up, which is the claim set without its fallback')
      // Compared against IPECAC's OWN three-enemy arm, never against the unmodified weapon: the
      // card halves the fire rate, so over a fixed window that comparison measures the cost and
      // reads it as a targeting failure. Within the card, total damage should barely move — three
      // seekers all landing on one body deal what three seekers landing on three bodies do.
      const spread3 = three.reduce((a, b) => a + b, 0)
      assert.ok(one[0] > spread3 * 0.5,
        `against a lone straggler IPECAC dealt ${one[0].toFixed(0)} in total against ${spread3.toFixed(0)} spread over three — seekers are giving up when their only target is already claimed instead of doubling up on it`)
    }
  }

  console.log(`PASS run PB7 (v7.2 slate): 18 cards asserted by EFFECT, not by state — the four variable damage muls measured as damage, ALIGNMENT by elemental damage per potency site, DEADFALL by re-arm time, WILDFIRE budgeted, MINIMES fleeing; OVERLOAD ${OVERLOAD_HP_PER_SEC} HP/s (not 60) rising with dmgScale, BLOOD MONEY escalating, BRITTLE unrepairable and its dead picks pulled, AVARICE never eats a coin it cannot convert`)
}

function testPoolBuckets() {
  const sample = (chapter, slots, weapons, mods = null, tierEligible = false) => {
    Math.random = mulberry32(20260808)
    const meta = makeMeta()
    meta.choiceSlots = slots
    // createRun reads the chapter from opts, NOT from meta (see resolveChapterId in config.js) —
    // meta.chapter is a title-screen pointer and setting it here would silently sample body.
    const run = createRun(meta, { chapter })
    run.weapons = weapons
    if (mods) Object.assign(run.mods, mods)
    // The anomaly tier displaces ordinary cards, so a fixture that cannot see it measures a pool
    // state the player occupies only in the first few levels. Both states are sampled below.
    if (tierEligible) { run.player.level = 12; run._eliteKills = 1 }
    const kinds = {}, rarities = {}, perWeapon = {}, passiveIds = {}, modIds = {}, valueTiers = {}
    let total = 0, defence = 0
    for (let i = 0; i < 4000; i++) {
      run._screenRerolls = -1   // never let reroll decay contaminate a base-rate sample
      for (const c of buildLevelUpChoices(run)) {
        if (c.kind === 'heal') continue
        kinds[c.kind] = (kinds[c.kind] ?? 0) + 1
        rarities[c.rarity] = (rarities[c.rarity] ?? 0) + 1
        if (c.kind === 'weapon') perWeapon[c.id] = (perWeapon[c.id] ?? 0) + 1
        if (c.kind === 'mod') modIds[`${c.weapon}:${c.id}`] = (modIds[`${c.weapon}:${c.id}`] ?? 0) + 1
        if (c.kind === 'passive') {
          passiveIds[c.id] = (passiveIds[c.id] ?? 0) + 1
          if (DEFENSIVE_PASSIVES.includes(c.id)) defence++
          if (PASSIVES[c.id].values) {
            valueTiers[c.id] = valueTiers[c.id] ?? {}
            valueTiers[c.id][c.rarity] = (valueTiers[c.id][c.rarity] ?? 0) + 1
          }
        }
        total++
      }
    }
    // defence/utility are two buckets that both emit kind 'passive', so their shares have to be
    // split back out by id — the whole point of splitting them is that each is asserted alone.
    const pc = (n) => (n / total) * 100
    const of = (k) => pc(k === 'defense' ? defence : k === 'utility' ? (kinds.passive ?? 0) - defence : (kinds[k] ?? 0))
    return { kinds, rarities, perWeapon, passiveIds, modIds, valueTiers, total, defence, pc, of }
  }

  // Declared share = the bucket's weight as a percentage of the whole table, so the assertions
  // track BUCKET_WEIGHTS instead of a copy of it that can drift.
  const bucketTotal = Object.values(BUCKET_WEIGHTS).reduce((a, b) => a + b, 0)
  const declared = (k) => (BUCKET_WEIGHTS[k] / bucketTotal) * 100
  const BUCKETS = ['defense', 'utility', 'weapon', 'element', 'mod']

  // armor/regen declare `values: {normal, rare, legendary}` — no epic, no mythic — so a roll
  // outside that table has to be re-rolled on RARITY_WEIGHTS RESTRICTED to the table's own keys.
  // A fixed ladder starting at 'legendary' sent every epic AND mythic roll (8.8% of the table) to
  // the top tier: measured 12.2% legendary armor against the 3.9% renormalising gives, i.e. +15%
  // mean armor per card, on the pool's only direct damage block. Nothing else in the suite reads
  // a card's bonus BY rarity, which is why that shipped green.
  // Pooled across every config below: one config's armor cards are ~500 draws, on which a 3.9%
  // tier is +/-0.9pt of noise; pooling gets the sample to ~3500 and the check to ~5 sigma.
  const valueTiers = {}
  const collectTiers = (s) => {
    for (const [id, tiers] of Object.entries(s.valueTiers)) {
      valueTiers[id] = valueTiers[id] ?? {}
      for (const [r, n] of Object.entries(tiers)) valueTiers[id][r] = (valueTiers[id][r] ?? 0) + n
    }
  }

  const ladder = (name, s) => {
    // The property no per-tier threshold expresses: the ladder must fall off monotonically. A
    // chip that is common is not a chip.
    let prev = Infinity
    for (const r of RARITY_ORDER) {
      // 'anomaly' is a PARALLEL tier, not a rung of this ladder: it has no RARITY_WEIGHTS entry,
      // it is rolled once per SCREEN against the ordinary table's total, and on a tier-eligible
      // fixture it measures 3.3% of cards against mythic's 1.1% — its position last in
      // RARITY_ORDER is a slot, not a frequency claim (see config.js). Excluding it here is the
      // same exclusion scripts/pool-probe.mjs's --rarityfloor makes, for the same reason. Without
      // it this walk goes red the first time a fixture is raised past a card's minLevel, which is
      // a non-defect: every PB1 fixture but the last sits at level 1.
      if (r === 'anomaly') continue
      const got = s.pc(s.rarities[r] ?? 0)
      assert.ok(got <= prev, `${name}: ${r} ${got.toFixed(1)}% of cards exceeds the tier below it (${prev.toFixed(1)}%)`)
      prev = got
    }
    // Defence is the only direct survivability in the pool and the passive share was cut
    // 62% -> 30%; holding this at the shipped 17.8% is what the whole redesign promised. It has
    // its OWN bucket weight precisely so this assertion can exist (a weight buried inside a
    // passive bucket could halve with every test still green — verified by mutation).
    assert.ok(s.of('defense') > 15,
      `${name}: defence ${s.of('defense').toFixed(1)}% of cards — the survivability floor is gone`)
  }

  // Three chapters x both slot counts that matter, never one config alone: 4 slots is a 60-of-80
  // meta-shop unlock, 2 is the DEFAULT, and every drift finding in the source spec was invisible
  // in at least one chapter. These configs own their chapter's whole arsenal, so weaponCandidates
  // emits no `New!` entries and the NEW_WEAPON_MIN_RATE floor cannot fire: what they measure is
  // the BUCKET, not the bucket plus a compensating floor (which is worth up to
  // 100*NEW_WEAPON_MIN_RATE/slots = 2.5pts of weapon share at 2 slots).
  const full = [
    { name: 'body/4', chapter: 'body', slots: 4, weapons: [{ id: 'star', level: 3 }, { id: 'orbit', level: 2 }, { id: 'wave', level: 2 }, { id: 'homing', level: 2 }] },
    { name: 'body/2', chapter: 'body', slots: 2, weapons: [{ id: 'star', level: 3 }, { id: 'orbit', level: 2 }, { id: 'wave', level: 2 }, { id: 'homing', level: 2 }] },
    { name: 'city/2', chapter: 'city', slots: 2, weapons: [{ id: 'rainbow', level: 2 }, { id: 'trashTornado', level: 2 }, { id: 'burstHydrant', level: 2 }] },
    { name: 'beyond/4', chapter: 'beyond', slots: 4, weapons: [{ id: 'realityShard', level: 3 }, { id: 'hole', level: 2 }, { id: 'pulsarSweep', level: 2 }] },
    { name: 'beyond/2', chapter: 'beyond', slots: 2, weapons: [{ id: 'realityShard', level: 3 }, { id: 'hole', level: 2 }, { id: 'pulsarSweep', level: 2 }] },
  ]
  const seen = {}
  for (const cfg of full) {
    const s = sample(cfg.chapter, cfg.slots, cfg.weapons)
    seen[cfg.name] = s
    // Measured seed-to-seed sd is ~0.4pt over these scenarios, so +/-1.5pt is ~3.5 sigma — tight
    // enough to catch a real regression. The first draft used +/-6pt, which is 12-15 sigma and
    // would have passed a bucket anywhere in 16-28%.
    for (const k of BUCKETS) {
      assert.ok(Math.abs(s.of(k) - declared(k)) < 1.5,
        `${cfg.name}: ${k} share ${s.of(k).toFixed(1)}% vs declared ${declared(k).toFixed(1)}%`)
    }

    // F1: nothing may deflect onto a high rarity, and an UPGRADE card must not wear a tier it
    // never rolled. Asserted on EVERY chapter, not just body: body ships no legendary or mythic
    // weapon, so it is the one chapter where the chip inflation is invisible by construction —
    // the same samples measured beyond/4 legendary 11.3% and city/2 mythic 8.3% (against body's
    // 3.7%) while upgrades kept cfg.rarity, and 11.3% is inside the 9-16% band the spec names as
    // the F1 regression signature. Every weapon here is OWNED, so no card may exceed the table.
    for (const r of ['epic', 'legendary', 'mythic']) {
      const got = s.pc(s.rarities[r] ?? 0)
      const want = (100 * RARITY_WEIGHTS[r]) / Object.values(RARITY_WEIGHTS).reduce((a, b) => a + b, 0)
      assert.ok(got <= want + 1.0, `${cfg.name}: ${r} ${got.toFixed(1)}% of cards vs a declared ${want.toFixed(1)}%`)
    }
    ladder(cfg.name, s)
    collectTiers(s)
  }

  // Partial arsenals: the discovery floor is live and the mod bucket has a real capacity ceiling
  // (one owned weapon x MOD_CANDIDATES_PER_WEAPON, minus the per-pool cap), so the tight
  // fidelity band does not apply. What must still hold is that the weapon bucket pays its
  // declared share — the whole point of the bucket-first roll — and that the ladder stays
  // monotone even though `New!` cards legitimately carry their weapon's inherent tier.
  const floorMax = (slots) => (100 * NEW_WEAPON_MIN_RATE) / slots
  for (const cfg of [
    { name: 'body/2 two owned', chapter: 'body', slots: 2, weapons: [{ id: 'star', level: 3 }, { id: 'orbit', level: 2 }] },
    { name: 'city/2 starter only', chapter: 'city', slots: 2, weapons: [{ id: 'rainbow', level: 2 }] },
    { name: 'beyond/2 starter only', chapter: 'beyond', slots: 2, weapons: [{ id: 'realityShard', level: 3 }] },
  ]) {
    const s = sample(cfg.chapter, cfg.slots, cfg.weapons)
    seen[cfg.name] = s
    assert.ok(s.of('weapon') > declared('weapon') - 1.5 && s.of('weapon') < declared('weapon') + 1.5 + floorMax(cfg.slots),
      `${cfg.name}: weapon share ${s.of('weapon').toFixed(1)}% vs declared ${declared('weapon').toFixed(1)}% + a floor worth at most ${floorMax(cfg.slots).toFixed(1)}pts`)
    // A FRACTION of declared, not a literal 24: thinning is PROPORTIONAL to the bucket's weight,
    // so the hardcoded number was only ever the right band for the weights it was written against
    // (0.8 * 30 = the 24 this line used to read) and became a near-equality the moment
    // BUCKET_WEIGHTS.mod moved — v7.7 took mod to 25 and this went red at a measured 21.3%, which
    // is the same healthy thinning it had always allowed, against a band that had stopped tracking
    // its subject. 0.75 rather than 0.8 because 0.8 leaves beyond/2-starter-only just 1.2pts of
    // headroom (2.6 sd on this sample) — the shipped 24 was itself only ~3.5 sd, i.e. a literal
    // that was one re-phasing away from a false red. At 0.75 the thinnest fixture clears by 6 sd
    // and a bucket that actually COLLAPSES (measured ~0-12% when it drops out of the roll) is
    // still caught with room to spare.
    assert.ok(s.of('mod') > declared('mod') * 0.75,
      `${cfg.name}: mod share ${s.of('mod').toFixed(1)}% vs declared ${declared('mod').toFixed(1)}% — a one-weapon mod bucket may thin, not collapse`)
    ladder(cfg.name, s)
    collectTiers(s)
  }

  // The SAME buckets, with the anomaly tier ELIGIBLE. Every fixture above sits at level 1 with no
  // elite kills, i.e. a pool state the player leaves in the first minute — so they measure the
  // declared shares in the one window where nothing displaces them. Once the tier can roll it
  // takes a share of every screen, and each ordinary bucket must come down by exactly that much
  // and no more. The assertion is against declared * (1 - anomalyShare), not against declared
  // flat: a flat band would either fail here or (at 1.5pt) be spent entirely on this effect,
  // leaving nothing for the drift it was written to catch. Task 3's pity raises the anomaly share
  // further, and this is the fixture that will see it.
  // 2 slots, not 4, deliberately: the tier is one roll per SCREEN, so its share of CARDS is
  // (rate / slots) — 3.3% at the default 2 slots against 1.7% at 4. The 2-slot fixture is the one
  // where the displacement is big enough for the correction to matter, and it is also the slot
  // count most players are on.
  {
    const s = sample('body', 2, [{ id: 'star', level: 3 }, { id: 'orbit', level: 2 }, { id: 'wave', level: 2 }, { id: 'homing', level: 2 }], null, true)
    const anomalyShare = s.pc(s.rarities.anomaly ?? 0)
    assert.ok(anomalyShare > 2, `the anomaly tier took ${anomalyShare.toFixed(2)}% of cards — the tier-eligible fixture is not reaching its subject`)
    for (const k of BUCKETS) {
      const want = declared(k) * (1 - anomalyShare / 100)
      assert.ok(Math.abs(s.of(k) - want) < 1.5,
        `body/2 tier-eligible: ${k} share ${s.of(k).toFixed(1)}% vs declared ${declared(k).toFixed(1)}% displaced by ${anomalyShare.toFixed(1)}% of anomaly cards = ${want.toFixed(1)}%`)
    }
    seen['body/2 tier-eligible'] = s
  }

  // Mythic is RETAINED (B3): rainbow is the mythic city starter, and WEAPON_MOD_TIER_BONUS has a
  // live mythic:3 that deleting the tier would silently cap at +2.
  assert.ok(RARITY_ORDER.includes('mythic'), 'mythic must stay in RARITY_ORDER')
  assert.strictEqual(WEAPON_MOD_TIER_BONUS.mythic, 3, 'deleting mythic silently caps every tier mod at +2')

  // Inherent rarity gates ACQUISITION, never LEVELLING. A filter here would hand beyond's
  // normal-rarity starter 68.8% of weapon offers while the legendary hole took 13.8% — i.e. the
  // pool would pick the dominant build for you. Every owned weapon must compete flat.
  const beyond = seen['beyond/4']
  const wTotal = Object.values(beyond.perWeapon).reduce((a, b) => a + b, 0)
  for (const [id, n] of Object.entries(beyond.perWeapon)) {
    assert.ok(n / wTotal < 0.45,
      `weapon ${id} took ${((n / wTotal) * 100).toFixed(1)}% of beyond's weapon cards — rarity is gating levelling, not acquisition`)
  }

  // ...but it must still gate acquisition somewhere: with both non-starters unowned, the
  // legendary `hole` has to be a rarer FIND than the epic `pulsarSweep`. (The uniform
  // NEW_WEAPON_MIN_RATE floor compresses this — it is a discovery guarantee, deliberately
  // rarity-blind — so the assertion is directional, not a ratio.)
  const fresh = seen['beyond/2 starter only']
  assert.ok((fresh.perWeapon.hole ?? 0) < (fresh.perWeapon.pulsarSweep ?? 0),
    `beyond: legendary hole offered ${fresh.perWeapon.hole} times against epic pulsarSweep's ${fresh.perWeapon.pulsarSweep} — rarity stopped gating acquisition`)

  for (const [id, tiers] of Object.entries(valueTiers)) {
    const keys = Object.keys(PASSIVES[id].values)
    const wTotal = keys.reduce((a, r) => a + RARITY_WEIGHTS[r], 0)
    const n = keys.reduce((a, r) => a + (tiers[r] ?? 0), 0)
    assert.ok(n > 2000, `only ${n} ${id} cards sampled — too few to read a tier split off`)
    for (const r of keys) {
      const got = (100 * (tiers[r] ?? 0)) / n
      const want = (100 * RARITY_WEIGHTS[r]) / wTotal
      assert.ok(Math.abs(got - want) < 2,
        `${id} rolled ${r} on ${got.toFixed(1)}% of its cards vs ${want.toFixed(1)}% — the failed-roll fallback is deflecting`)
    }
  }

  // A switch mod has no magnitude, so it declines every rarity above normal (makeWeaponModCard)
  // and config.js promises it is "offered AT MOST ONCE, only at normal rarity". That gate lives
  // in the CANDIDATE list, not in the printed chip: picking a mod first and then coercing its
  // rarity down to normal let a switch win its pick at any tier, measured 1.72x the shipped offer
  // rate. garden owns three weapons carrying three switch mods between them.
  const garden = sample('garden', 4, [{ id: 'boomerang', level: 3 }, { id: 'stinger', level: 2 }, { id: 'lure', level: 2 }])
  let swN = 0, swCards = 0, otherN = 0, otherCards = 0
  for (const [key, n] of Object.entries(garden.modIds)) {
    const [w, m] = key.split(':')
    if (WEAPON_MODS[w][m].kind === 'switch') { swN++; swCards += n } else { otherN++; otherCards += n }
  }
  assert.ok(swN >= 3 && otherN >= 10, `garden sample covered ${swN} switch / ${otherN} other mods — the scenario stopped reaching its subject`)
  const switchRatio = (swCards / swN) / (otherCards / otherN)
  assert.ok(switchRatio < 0.75,
    `a switch mod is offered ${switchRatio.toFixed(2)}x as often as a repeatable one — it is only a candidate on a normal roll (58.5%), so this must sit near 0.55`)

  // MUTATORS.unstable multiplies the ELEMENT BUCKET (rollCard), where it used to multiply a
  // per-id 0.25 pre-filter that saturated. Same number, different reader = a different mutator,
  // so the resulting SHARE is asserted here: the plan names 37% as the pathology, and an
  // un-repriced x3 measured 38.6%.
  const unstable = sample('body', 2, [{ id: 'star', level: 3 }, { id: 'orbit', level: 2 }],
    { elementWeightMul: MUTATORS.unstable.effects.elementWeightMul })
  assert.ok(unstable.of('element') < 33,
    `unstable: element ${unstable.of('element').toFixed(1)}% of cards — above the 37% the plan names as the regression`)
  assert.ok(unstable.of('element') > declared('element') + 6,
    `unstable: element ${unstable.of('element').toFixed(1)}% — the mutator has stopped doing anything`)

  const b4 = seen['body/4']
  const bTier = seen['body/2 tier-eligible']
  console.log(`PASS run PB1 (bucket-first roll): body/4 defence ${b4.of('defense').toFixed(1)}% utility ${b4.of('utility').toFixed(1)}% mod ${b4.of('mod').toFixed(1)}% weapon ${b4.of('weapon').toFixed(1)}% element ${b4.of('element').toFixed(1)}%; legendary body/4 ${b4.pc(b4.rarities.legendary ?? 0).toFixed(1)}% beyond/4 ${seen['beyond/4'].pc(seen['beyond/4'].rarities.legendary ?? 0).toFixed(1)}%, mythic city/2 ${seen['city/2'].pc(seen['city/2'].rarities.mythic ?? 0).toFixed(1)}%; unstable element ${unstable.of('element').toFixed(1)}%; tier-eligible body/2 mod ${bTier.of('mod').toFixed(1)}% weapon ${bTier.of('weapon').toFixed(1)}% behind ${bTier.pc(bTier.rarities.anomaly ?? 0).toFixed(1)}% anomaly cards`)
}

// ---- Run PB2: the anomaly tier -----------------------------------------------------
// Anomalies are a SIXTH rarity tier, not a replacement for mythic. No rarity multiplier, no
// levels — one-shot rule changes, filtered out once taken. See B3/B4/B5 in the Track B spec.
function testAnomalyTier() {
  const meta = makeMeta()
  // Sampled at TWO slot counts, because the property the roll structure exists for is that the
  // tier's rate does NOT depend on choiceSlots — see below.
  const sample = (slots) => {
    Math.random = mulberry32(20260808)
    meta.choiceSlots = slots
    const run = createRun(meta)
    run.player.level = 12   // past the seed card's minLevel and ANOMALY_MIN_LEVEL (F10)
    // The seed card's own gate: it teaches itself only to a player who has met an elite. Without
    // this the tier is INELIGIBLE and every assertion below passes vacuously — the plan's draft of
    // this test set the level but not the kill, so it could only ever have measured zero.
    run._eliteKills = 1
    let anomalyPools = 0, pools = 0
    const slotHits = new Array(slots).fill(0)
    for (let i = 0; i < 6000; i++) {
      run._screenRerolls = -1
      const cards = buildLevelUpChoices(run)
      pools++
      assert.strictEqual(cards.length, slots, `a pool returned ${cards.length} cards, not ${slots}`)
      const anomalies = cards.filter((c) => c.kind === 'anomaly')
      if (anomalies.length === 0) continue
      anomalyPools++
      assert.strictEqual(anomalies.length, 1, 'at most one anomaly per pool')
      // B5, as an INVARIANT and not a position: a forced pick must never be "take a curse or take
      // a curse". The pool that contains an anomaly must contain something else too.
      assert.ok(cards.some((c) => c.kind !== 'anomaly'), 'a pool offered nothing but anomalies')
      slotHits[cards.findIndex((c) => c.kind === 'anomaly')]++
      for (const c of anomalies) {
        assert.ok(!('bonus' in c), `anomaly ${c.id} carries a stat bonus — anomalies produce no growth`)
        assert.ok(ANOMALIES[c.id], `anomaly card has no valid id: ${c.id}`)
        assert.strictEqual(c.rarity, 'anomaly', `an anomaly card must wear the anomaly tier, got ${c.rarity}`)
      }
    }
    return { pools, anomalyPools, slotHits, rate: (100 * anomalyPools) / pools }
  }
  const bySlots = { 2: sample(2), 4: sample(4) }
  assert.ok(bySlots[2].anomalyPools > 0 && bySlots[4].anomalyPools > 0, 'the anomaly tier never rolled at all')

  // The tier's RATE, derived from config rather than from a copy of it: ANOMALY_BASE_WEIGHT is
  // rolled ONCE PER SCREEN against the ordinary table's TOTAL (never as an entry inside it), so
  // the constant reads directly as "share of screens carrying an anomaly". Two things are checked
  // and they fail differently:
  //   - the LEVEL, against config. Catches any silent thinning of the tier.
  //   - the INDEPENDENCE from choiceSlots. This is the one the design is for: rolling per slot
  //     instead delivered 1-(1-p)^slots, i.e. 1.5x the anomalies per run (2.40 -> 3.60, measured
  //     over whole runs) for a player who had spent 60 of the 80 meta-shop levels buying slots —
  //     a lottery on shop spending rather than on play, on the tier whose entire design licence
  //     is scarcity. Mutation-checked: restoring the per-slot roll takes the 2-slot figure from
  //     6.6% to 12.5% and fails the level assertion first, with the gap assertion behind it.
  const ordinaryTotal = Object.values(RARITY_WEIGHTS).reduce((a, b) => a + b, 0)
  const wantRate = (100 * ANOMALY_BASE_WEIGHT) / (ordinaryTotal + ANOMALY_BASE_WEIGHT)
  for (const [slots, s] of Object.entries(bySlots)) {
    assert.ok(Math.abs(s.rate - wantRate) < 1.2,
      `anomalies on ${s.rate.toFixed(1)}% of ${slots}-slot pools against a declared ${wantRate.toFixed(1)}% (ANOMALY_BASE_WEIGHT ${ANOMALY_BASE_WEIGHT} vs an ordinary total of ${ordinaryTotal})`)
  }
  assert.ok(Math.abs(bySlots[2].rate - bySlots[4].rate) < 1.2,
    `the tier rolled on ${bySlots[2].rate.toFixed(1)}% of 2-slot screens and ${bySlots[4].rate.toFixed(1)}% of 4-slot ones — the rarest tier is being bought in the meta shop`)

  // Position: the anomaly replaces a UNIFORMLY chosen slot, so it carries no positional tell and
  // needs no shuffle to hide one. What this catches is a hard positional rule — anything that
  // pins the tier out of a slot or into one (the plan's `i < slots - 1` gate would pin it out of
  // the last one, which at 2 slots means the anomaly is ALWAYS the left card).
  // The band is 0.08, not the 0.06 first shipped, and the difference is a POWER calculation rather
  // than a loosening. 6000 pools at the ~6.6% tier rate is only ~400 anomaly pools, on which a
  // uniform 25% has 1 sd = sqrt(.25*.75/400) = 2.2pts — so 0.06 was 2.8 sd, and with six slot
  // checks it false-positives on a few percent of ANY innocuous change that re-phases the seeded
  // stream. v7.7 (bucket weights) drew that ticket: slot 2 of 4 measured 31.6%, and the same
  // weights on a different seed measured uniform. Placement is `Math.floor(random * cards.length)`
  // and cannot see BUCKET_WEIGHTS at all, so a weight-driven pin is not a thing that can exist.
  // No detection is lost: the pathologies this guards are total, not marginal — the `i < slots - 1`
  // gate named above puts slot 3 of 4 at 0% (25pts out) and slot 1 of 2 at 0% (50pts out).
  for (const [slots, s] of Object.entries(bySlots)) {
    for (let i = 0; i < Number(slots); i++) {
      const share = s.slotHits[i] / s.anomalyPools
      assert.ok(Math.abs(share - 1 / Number(slots)) < 0.08,
        `anomalies landed in slot ${i} of ${slots} on ${(share * 100).toFixed(1)}% of their pools (want ~${(100 / Number(slots)).toFixed(0)}%) — the tier is pinned to a position`)
    }
  }
  const gotRate = bySlots[2].rate

  // No rarity multiplier, or every anomaly silently scales stats.
  assert.strictEqual(RARITIES.anomaly.mult, 1, 'an anomaly must carry no rarity multiplier')
  // Adding a tier to RARITY_ORDER without a tier bonus breaks run PT.a's <= assertion.
  assert.strictEqual(WEAPON_MOD_TIER_BONUS.anomaly, 1, 'every RARITY_ORDER entry needs a tier bonus')
  // Mythic is RETAINED (B3) — anomaly is a sixth tier, not a replacement for the jackpot.
  assert.ok(RARITY_ORDER.includes('mythic') && RARITY_ORDER.includes('anomaly'),
    'anomaly must JOIN the ladder, not replace mythic')

  // The three gates, each asserted alone. Every one of them is a silent no-op if it stops firing:
  // the tier would simply be offered more often, which no share assertion above would catch.
  // v7.2: `id` scopes the question to ONE card, and the two per-card gates below need it. While
  // ANOMALIES held a single entry, "was any anomaly offered" and "was THIS card offered" were the
  // same question; with a slate they are not, and the unscoped form silently stops testing what it
  // names — an unconditional card (BRITTLE, TIME DEBT) is offered whatever unstableCores' elite
  // gate says, so `!gated(kill the gate)` would go red for a reason that has nothing to do with
  // the gate. Left unscoped where the assertion really is table-wide (the minLevel floors).
  const gated = (mutate, id = null) => {
    Math.random = mulberry32(20260808)
    const r = createRun(meta)
    r.player.level = 12
    r._eliteKills = 1
    mutate(r)
    for (let i = 0; i < 400; i++) {
      r._screenRerolls = -1
      if (buildLevelUpChoices(r).some((c) => c.kind === 'anomaly' && (id === null || c.id === id))) return true
    }
    return false
  }
  const seedFloor = ANOMALIES.unstableCores.minLevel ?? ANOMALY_MIN_LEVEL
  assert.ok(!gated((r) => { r.player.level = seedFloor - 1 }),
    `an anomaly was offered below its own minLevel (${seedFloor})`)
  // ...and it IS offered AT its own floor, which is below the table default. Without this the
  // per-card floor is asserted only in the direction it shares with ANOMALY_MIN_LEVEL, so
  // deleting the `a.minLevel ??` read leaves every assertion green while the card silently goes
  // back to arriving at level 8 — measured, on the flat floor, first offered at t=164s of a 253s
  // run, with 65% of the run's elites already dead.
  assert.ok(seedFloor < ANOMALY_MIN_LEVEL, 'the seed card no longer exercises the per-card minLevel path')
  assert.ok(gated((r) => { r.player.level = seedFloor }),
    `a card declaring minLevel ${seedFloor} was not offered at level ${seedFloor} — the per-card floor is being ignored in favour of ANOMALY_MIN_LEVEL (${ANOMALY_MIN_LEVEL})`)
  assert.ok(!gated((r) => { r._eliteKills = 0 }, 'unstableCores'),
    'an anomaly was offered while its `when` predicate was false — the hidden condition does nothing')
  assert.ok(!gated((r) => { r.anomalies.unstableCores = true }, 'unstableCores'),
    'an anomaly already taken this run was offered again — anomalies have no levels')
  assert.ok(gated(() => {}), 'the gate harness stopped reaching its subject — it offers nothing even ungated')
  // ...and the TABLE-WIDE floor a card inherits by NOT declaring one, which is what F10 is
  // actually about: the unconditional cost cards must not be a new player's first look at the
  // tier. The seed card declares minLevel 3 because it is a no-cost jackpot, so without a card
  // that omits the field this default is untested — and it is the only thing standing between a
  // level-2 player and BRITTLE.
  ANOMALIES._floorless = { name: 'x', icon: '💥', from: 'x', desc: 'x', weight: 99, chapter: null, when: () => true }
  try {
    assert.ok(!gated((r) => { r.player.level = ANOMALY_MIN_LEVEL - 1; r._eliteKills = 0 }),
      `a card with no minLevel was offered below ANOMALY_MIN_LEVEL (${ANOMALY_MIN_LEVEL}) — the table default is not applied (F10)`)
    assert.ok(gated((r) => { r.player.level = ANOMALY_MIN_LEVEL; r._eliteKills = 0 }),
      'the floorless-card harness stopped reaching its subject')
  } finally {
    delete ANOMALIES._floorless
  }

  // pickedIds is ONE flat Set across every kind, so an anomaly id colliding with a weapon,
  // passive, mod or element id would silently delete that card from any pool the anomaly landed
  // in — and, at 2 slots with a one-item bucket, could empty the pool the invariant then rescues.
  const takenIds = new Set([...Object.keys(WEAPONS), ...Object.keys(PASSIVES), ...Object.keys(ELEMENTS)])
  for (const byMod of Object.values(WEAPON_MODS)) for (const m of Object.keys(byMod)) takenIds.add(m)
  for (const id of Object.keys(ANOMALIES)) {
    assert.ok(!takenIds.has(id), `anomaly id '${id}' collides with a weapon/passive/mod/element id — pickedIds is one flat Set`)
  }

  // EVERY SHIPPED PREDICATE, against a battery of run shapes. eligibleAnomalyIds swallows a throw
  // to protect the screen, so a card whose `when` throws is not a crash — it is a card that can
  // never be drawn, in any run, forever, with the whole suite green and the offer rate barely
  // moved (the weight is shared across the table, not per card). config.js's own PREDICATE HAZARD
  // note names this as the failure "no test would report". This is that test. Same for `chapter`:
  // a typo scopes the card to a biome that does not exist, which is the same silent deletion.
  {
    const shapes = {
      fresh: () => createRun(meta),
      midRun: () => {
        const r = createRun(meta)
        r.player.level = 12
        r._eliteKills = 3
        r.weapons = [{ id: 'star', level: 3 }, { id: 'orbit', level: 2 }]
        setElements(r, { fire: 2, cold: 1 })
        r.passivePicks.damage = 2
        r.weaponModPicks.star = { ...(r.weaponModPicks.star ?? {}), chain: 1 }
        return r
      },
      maxed: () => {
        const r = createRun(meta)
        r.player.level = 40
        r._eliteKills = 20
        r.weapons = CHAPTERS[r.chapter].weapons.map((id) => ({ id, level: MAX_WEAPON_LEVEL }))
        for (const id of Object.keys(PASSIVES)) r.passivePicks[id] = MAX_PASSIVE_LEVEL
        for (const id of Object.keys(ELEMENTS)) r.elementPicks[id] = MAX_ELEMENT_PICKS
        return r
      },
      // The one every naive predicate forgets: a run in another biome, owning none of the weapons
      // the card was written against.
      otherChapter: () => createRun(meta, { chapter: 'beyond' }),
    }
    // The helper the PREDICATE HAZARD note tells authors to use. It lives in config.js because
    // that is where the predicates are: shipped in sim.js it was unreachable from the only place
    // it is meant to be called, and a predicate that followed the note would have thrown
    // ReferenceError, been swallowed by eligibleAnomalyIds, and deleted its own card in silence.
    const owner = shapes.midRun()
    assert.ok(hasWeaponAt(owner, 'star', 3) && hasWeaponAt(owner, 'star'), 'hasWeaponAt says no to a weapon that is owned at level')
    assert.ok(!hasWeaponAt(owner, 'star', 4), 'hasWeaponAt ignores the level argument')
    assert.doesNotThrow(() => hasWeaponAt(owner, 'nope', 3), 'hasWeaponAt throws on an unowned weapon — it exists to be the thing that does not')
    assert.ok(!hasWeaponAt(owner, 'nope'), 'hasWeaponAt claims an unowned weapon')

    for (const [id, a] of Object.entries(ANOMALIES)) {
      // Object.keys(CHAPTERS), NOT CHAPTER_ORDER: that list is BOOKS.book1.chapters, so it drops
      // every Book 2 chapter and The Blank. It read correctly only while DEADFALL was the sole
      // chapter-scoped card and undergrowth happened to be in Book 1 — the first Book 2 card to
      // arrive was rejected as unofferable in a chapter it is offered in perfectly well.
      assert.ok(a.chapter == null || Object.hasOwn(CHAPTERS, a.chapter),
        `anomaly '${id}' is scoped to chapter '${a.chapter}', which is not a CHAPTERS entry — it can never be offered`)
      assert.ok(Number.isFinite(a.weight) && a.weight > 0, `anomaly '${id}' has no positive weight`)
      assert.ok((a.minLevel ?? ANOMALY_MIN_LEVEL) >= 1, `anomaly '${id}' has a nonsense minLevel`)
      for (const [shape, build] of Object.entries(shapes)) {
        assert.doesNotThrow(() => a.when(build()),
          `anomaly '${id}' threw on the '${shape}' run shape — eligibleAnomalyIds would swallow it and the card would never appear in any run`)
      }
    }
  }

  // A predicate that throws must lose its own card, never the screen: ANOMALIES is authored data
  // and `r.weapons.find(...).level` is the documented way to write one that throws (config.js).
  ANOMALIES._throwing = { name: 'x', icon: '💥', from: 'x', desc: 'x', weight: 99, chapter: null, when: (r) => r.weapons.find((w) => w.id === 'nope').level > 0 }
  try {
    Math.random = mulberry32(20260810)
    const r = createRun(meta)
    r.player.level = 12
    r._eliteKills = 1
    let offered = 0
    for (let i = 0; i < 600; i++) {
      r._screenRerolls = -1
      for (const c of buildLevelUpChoices(r)) if (c.kind === 'anomaly') offered++
    }
    assert.ok(offered > 0, 'a throwing predicate took the whole tier down with it')
  } finally {
    delete ANOMALIES._throwing
  }

  // applyChoice must RECORD it — the shipped chain is closed over weapon|passive|mod|element|heal,
  // so without a branch an anomaly card is silently consumed with no effect.
  const taken = createRun(meta)
  taken.levelUpChoices = [{ kind: 'anomaly', id: 'unstableCores', title: 'x', desc: 'x', tag: '', rarity: 'anomaly', icon: '💥' }]
  applyChoice(taken, 0)
  assert.strictEqual(taken.anomalies.unstableCores, true, 'applyChoice must record the anomaly on run.anomalies')

  // The seed card's TRIGGER SITE, because a card that changes nothing has failed however
  // correctly it rolls. `volatile` is an elite AFFIX, read ONLY as enemy.affixes.includes(...)
  // in dealDamage's death path — `enemy.volatile = true` would be a dead store nothing reads and
  // no test catches. Every ordinary spawn is forced elite here (spawnEnemy takes isElite from
  // run.time >= run._nextEliteAt) so a dozen samples take seconds of sim, not a whole run.
  const eliteRun = (anomaly) => {
    Math.random = mulberry32(20260809)
    const r = createRun(makeMeta())
    if (anomaly) r.anomalies.unstableCores = true
    r.player.hp = 1e9
    r.player.maxHP = 1e9
    const seen = []
    for (let i = 0; i < 60 * 60 && seen.length < 12; i++) {
      r._nextEliteAt = 0
      if (r.phase === 'levelup') { declineLevelUp(r); continue }
      stepSim(r, { x: 0, y: 0 }, 1 / 60)
      for (const e of r.enemies) if (e.elite && !seen.includes(e)) seen.push(e)
    }
    return { r, seen }
  }
  const withCores = eliteRun(true)
  const without = eliteRun(false)
  assert.ok(withCores.seen.length >= 6 && without.seen.length >= 6,
    `only ${withCores.seen.length}/${without.seen.length} elites spawned — the trigger-site scenario stopped reaching its subject`)
  const volatiles = (s) => s.filter((e) => e.affixes.includes('volatile')).length
  assert.strictEqual(volatiles(withCores.seen), withCores.seen.length,
    `Unstable Cores left ${withCores.seen.length - volatiles(withCores.seen)} of ${withCores.seen.length} elites non-volatile`)
  assert.ok(volatiles(without.seen) < without.seen.length,
    'every elite is volatile WITHOUT the anomaly — the card buys nothing (rollAffixes is ignoring run.anomalies)')
  // _eliteKills feeds the predicates, so it has to actually count.
  assert.ok(without.r._eliteKills > 0 && without.r._eliteKills <= without.r.kills,
    `_eliteKills ${without.r._eliteKills} of ${without.r.kills} kills — the counter anomaly predicates read is not being kept`)

  // What the blast DOES, which is the half of the card the affix above cannot carry. Two
  // properties, both of which the card was shipped without and neither of which any share or
  // affix assertion can see:
  //   (a) the enemy side rides hpScale. A flat VOLATILE_DMG of 20 stops killing a full-health
  //       drone at t=0 and a full-health wisp at t=90 — measured over whole runs with the card
  //       FORCED ON, 1.70 blast kills out of 933, i.e. 0.18% of a run's kills. The card was a
  //       measured non-event; this is the assertion that says so.
  //   (b) it CHAINS. The spec sells the card on "packs chain-detonate" and the owner ruled the
  //       chain must not be capped — but a blast can never kill an ELITE (elite HP is
  //       base * ELITE.hpMul * hpScale, so the bomb is ~20-30% of it at every t), so unless what
  //       the blast kills drops its own core there is no cascade in the game at all.
  // Hand-built bombs rather than a whole run: run.bombs is a plain array (state.js), and the
  // question is exactly what one detonation does to two drones standing in it.
  const blast = (core, t) => {
    Math.random = mulberry32(20260811)
    const r = createRun(makeMeta())
    r.time = t
    r.player.x = 5000; r.player.y = 5000   // well outside the blast: this measures the ENEMY side
    const hp = ENEMIES.drone.hp * hpScale(t)
    r.enemies = [
      makeStatusEnemy(r, { x: 0, y: 40, hp }),
      makeStatusEnemy(r, { x: 40, y: 0, hp }),
    ]
    r.bombs = [{ x: 0, y: 0, radius: VOLATILE_RADIUS, fuse: 1 / 120, duration: VOLATILE_FUSE, dmg: VOLATILE_DMG, src: 'volatile', core }]
    const before = r.enemies.slice()
    stepSim(r, { x: 0, y: 0 }, 1 / 60)
    return { killed: before.filter((e) => e._dead).length, bombs: r.bombs.length }
  }
  for (const t of [0, 150, 290]) {
    const withCore = blast(true, t)
    const plain = blast(false, t)
    assert.strictEqual(withCore.killed, 2,
      `at t=${t}s an unstable core left ${2 - withCore.killed} of 2 full-health drones alive — the blast does not ride hpScale and the card is cosmetic from the moment it is offered`)
    assert.strictEqual(withCore.bombs, 2,
      `at t=${t}s a core that killed 2 enemies left ${withCore.bombs} bombs armed, not 2 — the cascade the card is sold on does not exist`)
    // The rolled `volatile` elite affix must be untouched: this is a chapter-agnostic hazard
    // priced against the player, and buffing its enemy side is an unnamed balance change.
    assert.strictEqual(plain.bombs, 0, `at t=${t}s a plain volatile bomb chained — the affix must not inherit the anomaly's behaviour`)
    if (t > 0) {
      assert.strictEqual(plain.killed, 0,
        `at t=${t}s a plain 20-damage volatile blast killed a full-health drone — VOLATILE_DMG has been changed, which reprices the elite affix, not just the card`)
    }
  }

  console.log(`PASS run PB2 (anomaly tier): ${gotRate.toFixed(1)}% of 2-slot and ${bySlots[4].rate.toFixed(1)}% of 4-slot screens offered one vs a declared ${wantRate.toFixed(1)}% — never alone, never twice, unpinned, slot-count-independent, gated on level/predicate/already-taken; every shipped predicate is throw-free on four run shapes; and a held core kills what it catches and chains off it`)
}

// ---- Run PB3: anomaly pity ---------------------------------------------------------
// A dry run must drift toward the tier instead of waiting on a flat coin flip — but pity is the
// easiest thing in this pipeline to get wrong in a way no share assertion sees. Seven properties,
// each of which fails differently:
//   WEIGHT the arithmetic, asserted EXACTLY on anomalyWeightFor rather than inferred from a rate.
//          The counter includes the screen being built, so the term is (count - 1): a one-point
//          weight step is a 0.9-point rate step, which no affordable sample separates, and
//          v6.7.8 shipped that `- 1` with the whole suite still green when it was deleted.
//   UNIT   it advances once per SCREEN, not once per CARD, and the weight reads no slot count.
//          The roll is per screen (v6.7.7), so a per-card counter would hand a 4-slot player
//          twice the pity accrual of a 2-slot one — the meta-shop lottery the per-screen roll
//          exists to close, walked straight back in through the pity term.
//   SITE   it advances in stepLevelUp, never in buildLevelUpChoices, or main.js's onReroll (which
//          calls buildLevelUpChoices directly) turns coins into anomalies (F5).
//   EARNED only on screens the tier could actually have paid out on. Accruing through the
//          INELIGIBLE stretch banks credit on a fixed schedule (ANOMALY_MIN_LEVEL gates nearly
//          every card) and spends it the instant the gate opens.
//   RESET  when the tier is OFFERED, not on a card surviving into the pool — and, in the other
//          direction, never without one: a reset whose card is then overwritten spends the tier
//          and hands back nothing (F4, the NEW_WEAPON_MIN_RATE swap).
//   STICKY one decision per SCREEN, so a REROLL re-rolls the ordinary cards and nothing else
//          (spec B6). An independent draw per build made 133 coins of rerolls worth 20.1% ->
//          75.5% anomaly-on-screen at a saturated counter, and threw away the pity that bought
//          the card it deleted.
//   CAP    a long dry stretch cannot make the tier certain.
function testAnomalyPity() {
  const meta = makeMeta()
  const ordinaryTotal = Object.values(RARITY_WEIGHTS).reduce((a, b) => a + b, 0)
  const rateFor = (dryScreens) => {
    const w = Math.min(ANOMALY_PITY_CAP, ANOMALY_BASE_WEIGHT + ANOMALY_PITY_PER_SCREEN * dryScreens)
    return (100 * w) / (ordinaryTotal + w)
  }

  // WEIGHT, exactly, against the function rollAnomalyCard itself calls — not a copy of its
  // arithmetic. count 1 is what stepLevelUp produces on a screen with nothing behind it, so
  // pinning w(1) to the base weight is what pins the `- 1`: without it w(1) is 14, and the
  // plan's own Task 3 snippet (which multiplies the raw counter) is exactly that mutation.
  const w = (count, slots = 2) => anomalyWeightFor({ _screensSinceAnomaly: count, choiceSlots: slots })
  assert.strictEqual(w(0), ANOMALY_BASE_WEIGHT,
    'a run that never went through stepLevelUp (the probe, a fixture) must roll at the base weight, never below it')
  assert.strictEqual(w(1), ANOMALY_BASE_WEIGHT,
    `the first screen the tier is eligible on rolled at ${w(1)}, not ANOMALY_BASE_WEIGHT ${ANOMALY_BASE_WEIGHT} — the counter INCLUDES the screen being built, so the weight term is (count - 1) and that constant's documented share is otherwise a rate the game never rolls at`)
  assert.strictEqual(w(2), ANOMALY_BASE_WEIGHT + ANOMALY_PITY_PER_SCREEN, 'one dry screen must be worth exactly one ANOMALY_PITY_PER_SCREEN')
  assert.strictEqual(w(6), ANOMALY_BASE_WEIGHT + 5 * ANOMALY_PITY_PER_SCREEN, 'the pity term must be linear in dry screens')
  assert.strictEqual(w(10000), ANOMALY_PITY_CAP, 'the weight must saturate at ANOMALY_PITY_CAP')
  for (const count of [1, 2, 9, 10000]) {
    assert.strictEqual(w(count, 4), w(count, 2),
      `pity at ${count} screens is worth ${w(count, 4)} to a 4-slot player and ${w(count, 2)} to a 2-slot one — the weight must not read choiceSlots, or buying slots buys the rarest tier`)
  }

  // One level-up screen, driven through stepSim so the assertion is about the SHIPPED path:
  // main.js never calls buildLevelUpChoices to open a screen, stepLevelUp does.
  const oneScreen = (slots, eliteKills = 1) => {
    Math.random = mulberry32(20260808)
    meta.choiceSlots = slots
    const run = createRun(meta)
    run.player.level = 12
    run._eliteKills = eliteKills
    run.player.xp = run.player.xpNext
    stepSim(run, { x: 0, y: 0 }, 1 / 60)
    assert.strictEqual(run.phase, 'levelup', `the ${slots}-slot fixture never opened a screen — it is not reaching stepLevelUp at all`)
    return run
  }
  for (const slots of [2, 4]) {
    const run = oneScreen(slots)
    // 1, or 0 if this screen happened to roll the tier — the reset is asserted on its own below.
    const want = run.levelUpChoices.some((c) => c.kind === 'anomaly') ? 0 : 1
    assert.strictEqual(run._screensSinceAnomaly, want,
      `a ${slots}-slot screen left pity at ${run._screensSinceAnomaly}, not ${want} — the unit must be the SCREEN, or buying choice slots buys pity`)
  }

  // EARNED. An INELIGIBLE stretch banks nothing (v6.7.9): the counter used to advance through it,
  // and since ANOMALY_MIN_LEVEL gates the table the ineligible stretch is the same stretch in
  // every run — credit earned on a schedule, spent the moment the gate opens (measured on the
  // shipped pipeline: 18.3% -> 36.8% of first Ruptures landing within three screens of
  // eligibility). An ELIGIBLE stretch banks exactly one per screen since the last offer.
  meta.choiceSlots = 2
  const drive = (run, screens) => {
    let lastOffer = 0
    for (let i = 1; i <= screens; i++) {
      run.phase = 'playing'
      run.player.xp = run.player.xpNext
      stepSim(run, { x: 0, y: 0 }, 1 / 60)
      if (run.levelUpChoices.some((c) => c.kind === 'anomaly')) lastOffer = i
    }
    return lastOffer
  }
  const SCREENS = 6
  Math.random = mulberry32(20260808)
  const ineligible = createRun(meta)
  // v7.2: made ineligible by the RUN CAP, not by a predicate. It used to sit at level 12 with
  // _eliteKills 0, which was ineligible only while ANOMALIES held one elite-gated card — the slate
  // has unconditional cards (BRITTLE, TIME DEBT, STILLNESS...) eligible at level 12 whatever the
  // elite counter says, so the fixture stopped testing an ineligible stretch and started testing
  // an eligible one under the old name.
  // The level floor cannot be used either, and that is the subtle part: `drive` LEVELS THE PLAYER
  // UP six times, so a fixture that starts one level below the floor is over it by screen two and
  // the assertion fails for the right reason with the wrong cause. MAX_ANOMALIES_PER_RUN is the
  // one gate that survives arbitrarily many level-ups and an arbitrarily large slate — it is the
  // first line of eligibleAnomalyIds, before any level or predicate is read.
  ineligible.player.level = 12
  ineligible._eliteKills = 1
  for (const id of Object.keys(ANOMALIES).slice(0, MAX_ANOMALIES_PER_RUN)) ineligible.anomalies[id] = true
  assert.strictEqual(drive(ineligible, SCREENS), 0, 'the ineligible fixture was offered an anomaly — it is not testing an ineligible stretch')
  assert.strictEqual(ineligible._screensSinceAnomaly, 0,
    `${SCREENS} screens the tier was INELIGIBLE on left pity at ${ineligible._screensSinceAnomaly} — credit must only be earned where it can be spent, or every run's first Rupture clusters on the screens right after ANOMALY_MIN_LEVEL`)

  Math.random = mulberry32(20260808)
  const eligible = createRun(meta)
  eligible.player.level = 12
  eligible._eliteKills = 1
  const lastOffer = drive(eligible, SCREENS)
  assert.strictEqual(eligible._screensSinceAnomaly, SCREENS - lastOffer,
    `${SCREENS} eligible screens with the last offer on #${lastOffer} left pity at ${eligible._screensSinceAnomaly}, not ${SCREENS - lastOffer} — an eligible screen must bank exactly one, and an offer must zero it`)
  assert.ok(eligible._screensSinceAnomaly > 0 || lastOffer === SCREENS, 'the eligible fixture banked nothing at all — the advance is not firing')

  // The rate AT a given pity, and the reset invariant, measured together. Each iteration re-arms
  // the counter AND re-asks the screen's anomaly question: the roll ZEROES the counter on a hit
  // and the answer is memoised per screen, so a loop that does neither samples one frozen draw
  // and reports it as a rate (the plan's first draft measured 399 pools at base weight while
  // claiming saturation, and its assertion passed with the bug present).
  const atPity = (screensSince, iters, slots = 2) => {
    Math.random = mulberry32(20260808)
    meta.choiceSlots = slots
    const run = createRun(meta)
    run.player.level = 12
    run._eliteKills = 1
    let hits = 0
    for (let i = 0; i < iters; i++) {
      run._screenRerolls = -1
      run._screensSinceAnomaly = screensSince
      const cards = buildLevelUpChoices(run)
      const hit = cards.some((c) => c.kind === 'anomaly')
      if (hit) hits++
      // Both directions, on every pool. `reset && !hit` is F4: the roll fired, the counter was
      // spent, and something downstream (the NEW_WEAPON_MIN_RATE swap) overwrote the card — the
      // player pays the pity and gets nothing. `hit && !reset` is a tier that never comes down
      // again once it starts.
      assert.strictEqual(run._screensSinceAnomaly === 0, hit,
        `a pool ${hit ? 'offered an anomaly without resetting pity' : 'reset pity without offering an anomaly'} — the reset must happen on the ROLL and only reach a screen that keeps the card`)
    }
    return (100 * hits) / iters
  }

  // MID: pity is live and PER_SCREEN is worth what config says. Without this the cap assertion
  // below passes with pity deleted entirely (base rate is comfortably under the ceiling).
  // 4000 draws puts the binomial sd at ~0.5pt, so 2pt is ~4 sigma.
  // Sampled at BOTH slot counts, because the delivered rate is the thing the player experiences:
  // the counter assertions above are on the numerator only, and a slot-scaled weight term passes
  // every one of them while giving a 4-slot player 17.4% where a 2-slot one gets 12.3%.
  const midScreens = 7
  const mid = atPity(midScreens, 4000)
  const mid4 = atPity(midScreens, 4000, 4)
  for (const [slots, got] of [[2, mid], [4, mid4]]) {
    assert.ok(Math.abs(got - rateFor(midScreens - 1)) < 2,
      `after ${midScreens - 1} dry screens the tier rolled on ${got.toFixed(1)}% of ${slots}-slot pools against a declared ${rateFor(midScreens - 1).toFixed(1)}% (base ${ANOMALY_BASE_WEIGHT} + ${ANOMALY_PITY_PER_SCREEN}/screen over an ordinary total of ${ordinaryTotal})`)
  }
  assert.ok(Math.abs(mid4 - mid) < 1.5,
    `the same pity delivered ${mid.toFixed(1)}% at 2 slots and ${mid4.toFixed(1)}% at 4 — pity has become a meta-shop purchase`)
  assert.ok(mid > rateFor(0) + 2, `pity moved the rate ${rateFor(0).toFixed(1)}% -> ${mid.toFixed(1)}% — it is doing nothing`)

  // CAP: an arbitrarily long dry stretch may not make the tier certain. Two-sided on purpose —
  // the ceiling is the cap's exact prediction, so this fails at 99% (uncapped) AND at 6.6% (pity
  // never applied), where a one-sided `< ceiling * 1.6` passes on the second.
  const ceiling = rateFor(1e9)
  meta.choiceSlots = 2
  const saturated = atPity(10000, 4000)
  assert.ok(Math.abs(saturated - ceiling) < 2.5,
    `a saturated run offered the tier on ${saturated.toFixed(1)}% of pools against the capped ceiling ${ceiling.toFixed(1)}% (ANOMALY_PITY_CAP ${ANOMALY_PITY_CAP}) — pity is uncapped, or it is not being applied at all`)

  // A RUPTURE IS AN ORDINARY CARD ON A REROLL (v7.20, owner). It used to be STICKY — the screen's
  // answer was decided once and reused, so a reroll could neither draw the tier nor lose it, and an
  // unwanted Rupture sat in a slot through every paid re-deal. Three properties replace that, and
  // all three are needed: without the halved weight coins farm the tier, without the once-per-
  // screen pity charge a reroll-heavy player ends a run having seen FEWER Ruptures for paying more,
  // and without the "it can change" check the memo could come back unnoticed.
  const REROLLS = 5
  // Drives the SHIPPED reroll (rerollLevelUpChoices), not a hand-stepped counter: _screenRerolls is
  // what gates the halved weight, and a loop that sets it by hand measures the wrong branch.
  const rerollScreens = (screensSince, rerolls, iters) => {
    Math.random = mulberry32(20260811)
    meta.choiceSlots = 2
    const run = createRun(meta)
    run.player.level = 12
    run._eliteKills = 1
    let hits = 0, changed = 0, pitySteps = 0
    for (let i = 0; i < iters; i++) {
      run._screenRerolls = 0
      run._rerolls = 0
      run.coinsEarned = 1e9              // the price ladder is PB4's subject, not this block's
      run._screensSinceAnomaly = screensSince
      run.levelUpChoices = buildLevelUpChoices(run)
      const idOf = (cards) => cards.filter((c) => c.kind === 'anomaly').map((c) => c.id).join()
      const first = idOf(run.levelUpChoices)
      let before = run._screensSinceAnomaly
      for (let r = 0; r < rerolls; r++) {
        rerollLevelUpChoices(run)
        if (before !== 0 && run._screensSinceAnomaly === 0) pitySteps++
        before = run._screensSinceAnomaly
      }
      if (idOf(run.levelUpChoices) !== first) changed++
      if (run.levelUpChoices.some((c) => c.kind === 'anomaly')) hits++
    }
    return { rate: (100 * hits) / iters, changed, pitySteps }
  }

  // 1. NOT STICKY. Over 1500 saturated screens, rerolling must sometimes change what the tier slot
  //    holds — the old memo made this exactly 0.
  const sat0 = rerollScreens(10000, 0, 1500)
  const sat5 = rerollScreens(10000, REROLLS, 1500)
  assert.ok(sat5.changed > 100,
    `${REROLLS} rerolls changed the screen's Rupture on only ${sat5.changed} of 1500 screens — the tier is sticky again, which is the bug v7.20 fixed`)

  // 2. REROLLING A RUPTURE AWAY REFUNDS HALF THE DRY-STREAK CREDIT (v7.30). The credit is spent
  //     the moment the tier is offered, which was fair while the offer was guaranteed to survive to
  //     the end of the screen — v7.29 broke that, so a reroll bought for an unrelated reason could
  //     burn an 18-screen streak and hand back nothing. Asserted on the COUNTER, since that is the
  //     quantity the player is being refunded, and against a control that took a card instead.
  {
    const screenWithRupture = (thenReroll) => {
      Math.random = mulberry32(4242)
      meta.choiceSlots = 2
      const run = createRun(meta)
      run.player.level = 12
      run._eliteKills = 1
      run.coinsEarned = 1e9
      // Deal until a screen actually carries one, at a known dry streak.
      let cards = null
      for (let i = 0; i < 4000 && !cards; i++) {
        run._screenRerolls = 0
        run._rerolls = 0
        run._screensSinceAnomaly = 20            // saturated, so the refund has something to halve
        const deal = buildLevelUpChoices(run)
        if (deal.some((c) => c.kind === 'anomaly')) cards = deal
      }
      assert.ok(cards, 'no screen carried a Rupture in 4000 deals — the fixture is not reaching its subject')
      run.levelUpChoices = cards
      assert.strictEqual(run._screensSinceAnomaly, 0, 'the offer did not spend the credit')
      if (thenReroll) rerollLevelUpChoices(run)
      return run._screensSinceAnomaly
    }
    const kept = screenWithRupture(false)
    const rerolled = screenWithRupture(true)
    assert.strictEqual(kept, 0, 'a screen resolved with its Rupture still on it must keep the credit spent in full')
    assert.strictEqual(rerolled, Math.floor(20 * ANOMALY_REROLL_PITY_REFUND),
      `rerolling a Rupture away left the credit at ${rerolled}, want ${Math.floor(20 * ANOMALY_REROLL_PITY_REFUND)} of 20 — at 0 the reroll silently burns a whole dry streak, at 20 declining the tier costs nothing and it re-offers until accepted`)
  }

  // 3. HALVED PER DEAL. A single paid re-deal carries the tier at ANOMALY_REROLL_MUL of the natural
  //    rate. Measured on the re-deal itself rather than cumulatively, because the cumulative number
  //    necessarily rises with rerolls now and is reported (not asserted) below.
  // Pinned ARITHMETICALLY against the constants, not as a ratio of the two measured rates. A rate
  // is w/(total + w), so halving the WEIGHT does not halve the RATE — the old ratio-of-rates form
  // wanted x0.50 and only got it because the pity was being zeroed on exactly the screens that had
  // carried a Rupture, which dragged the average onto the right number for the wrong reason. It
  // broke the moment v7.30 refunded half that credit. This form says what the code should do.
  const oneReroll = rerollScreens(10000, 1, 3000)
  const tableTotal = Object.values(RARITY_WEIGHTS).reduce((a, b) => a + b, 0)
  const paidWeight = ANOMALY_PITY_CAP * ANOMALY_REROLL_MUL          // saturated counter, halved
  const wantRate = (100 * paidWeight) / (tableTotal + paidWeight)
  const ratio = oneReroll.rate / sat0.rate
  assert.ok(Math.abs(oneReroll.rate - wantRate) < 1.6,
    `one paid re-deal carried the tier on ${oneReroll.rate.toFixed(1)}% of screens, want ${wantRate.toFixed(1)}% (cap ${ANOMALY_PITY_CAP} x ${ANOMALY_REROLL_MUL} against an undecayed table of ${tableTotal}) — this halving is the whole of what stops coins farming the rarest tier (B6)`)

  // 3. THE CREDIT IS SPENT BY THE OFFER, WHEREVER IT ARRIVES. A Rupture that first shows up on a
  //    paid re-deal must still zero the pity — otherwise a rerolling player accrues credit forever
  //    and the tier's rate climbs run-long. (It cannot be spent TWICE: zeroing is idempotent and
  //    nothing raises the counter again until the next screen.)
  assert.ok(sat5.pitySteps > 0,
    'no reroll ever spent the pity credit — a Rupture found on a re-deal must charge it exactly as one found on the first deal')

  console.log(`PASS run PB3 (anomaly pity): weight ${w(1)}/${w(2)}/${w(10000)} at 1/2/saturated screens and identical at 4 slots; one screen = one step, ${SCREENS} ineligible screens bank nothing; rate ${rateFor(0).toFixed(1)}% -> ${mid.toFixed(1)}%/${mid4.toFixed(1)}% (2/4 slots) at ${midScreens - 1} dry screens -> ${saturated.toFixed(1)}% saturated against a ceiling of ${ceiling.toFixed(1)}%; ${REROLLS} rerolls move it ${sat0.rate.toFixed(1)}% -> ${sat5.rate.toFixed(1)}% cumulative (one re-deal x${ratio.toFixed(2)}, changed on ${sat5.changed}/1500 screens, pity re-spent ${sat5.pitySteps}x)`)
}

// ---- Run PB4: reroll nudges rarity, never the anomaly tier --------------------------
// Rerolling a level-up screen buys BIGGER NUMBERS. Only the `normal` weight decays
// (REROLL_RARITY_DECAY, capped at REROLL_RARITY_CAP rerolls of the same screen), so every other
// tier's share rises without a knob of its own. Three things it must NOT buy, each with its own
// block below: rule-change (`switch`) mod offers, rarer weapon DISCOVERIES, and the sixth tier.
// The first two are invariance tests — the numbers must not move at all — because both are card
// KIND, and the reroll's promise is card SIZE.
// The sixth tier is spec B6. Two independent mechanisms keep it apart and both are pinned here:
//   HALVING  a paid re-deal rolls the tier at ANOMALY_REROLL_MUL of its weight (v7.20, replacing
//            v6.7.9's per-screen memo; run PB3's block is the test of that half).
//   DENOM    the anomaly roll competes against the sum of the UNDECAYED table. Summing the decayed
//            one shrinks the denominator and inflates the tier ~35% relative. The pin below is
//            exact arithmetic, not a sample — and it matters MORE now that the tier is rolled on
//            every re-deal, since a decayed denominator would compound across rerolls.
function testRerollRarity() {
  const meta = makeMeta()
  meta.choiceSlots = 3
  const fixture = () => {
    const run = createRun(meta)
    run.player.level = 12
    run._eliteKills = 1   // the seed anomaly's own gate — without it the tier is INELIGIBLE
    return run
  }

  // WIRED — through the PRODUCTION path. `reroll` here is sim.js's rerollLevelUpChoices, the same
  // call main.js's onReroll makes, so this block exercises the price, the payment and both
  // counters rather than a local imitation of them.
  // That is not a style preference. While the _screenRerolls bump lived in main.js it was the ONLY
  // production write to the field, and this file never imports main.js — so deleting that one line
  // left the whole suite green (this run included, because it supplied the increment itself) while
  // every reroll in the shipped game silently rolled at the undecayed table. The feature could die
  // without a single red assertion. Now it cannot: the counter and the re-deal are the same call.
  Math.random = mulberry32(20260808)
  const wired = fixture()
  const openScreen = (run) => {
    run.phase = 'playing'
    run.player.xp = run.player.xpNext
    stepSim(run, { x: 0, y: 0 }, 1 / 60)
    assert.strictEqual(run.phase, 'levelup', 'the fixture never opened a level-up screen')
  }
  openScreen(wired)
  assert.strictEqual(wired._screenRerolls, 0,
    `a freshly dealt screen sits at ${wired._screenRerolls} rerolls — the decay must be inert on a screen nobody paid for`)
  // Broke: it must refuse and change NOTHING. rerollCost(0) is REROLL_BASE_COST, so one coin short
  // is enough to prove the guard is the price and not an afterthought.
  wired.coinsEarned = rerollCost(0) - 1
  const dealt = wired.levelUpChoices
  assert.strictEqual(rerollLevelUpChoices(wired), false, 'a reroll the run cannot afford must be refused')
  assert.strictEqual(wired.levelUpChoices, dealt, 'a refused reroll re-dealt the screen anyway')
  assert.strictEqual(wired._screenRerolls, 0, 'a refused reroll stepped the screen counter')
  assert.strictEqual(wired._rerolls ?? 0, 0, 'a refused reroll stepped the run counter (and so raised the next price)')
  assert.strictEqual(wired.coinsEarned, rerollCost(0) - 1, 'a refused reroll spent coins')
  // Paid: the price comes off the RUN's purse, both counters step, the screen is re-dealt.
  wired.coinsEarned = 1000
  const price = rerollCost(0)
  assert.strictEqual(rerollLevelUpChoices(wired), true, 'an affordable reroll must go through')
  assert.strictEqual(wired.coinsEarned, 1000 - price, `a reroll must cost rerollCost(0) = ${price}`)
  assert.strictEqual(wired._rerolls, 1, 'a paid reroll must step the RUN counter that prices the next one')
  assert.strictEqual(wired._screenRerolls, 1, 'a paid reroll must step the SCREEN counter the decay reads')
  assert.notStrictEqual(wired.levelUpChoices, dealt, 'a paid reroll must re-deal the screen')
  rerollLevelUpChoices(wired)
  assert.strictEqual(wired._screenRerolls, 2, 'a second paid reroll must step the counter again')
  assert.strictEqual(wired.coinsEarned, 1000 - rerollCost(0) - rerollCost(1), 'the second reroll must be priced off the stepped RUN counter')
  openScreen(wired)
  assert.strictEqual(wired._screenRerolls, 0,
    'a new screen did not re-arm the counter — one expensive screen would tax every screen after it for the rest of the run')
  // ...and the BUILDER must not step it. This is the whole reason the counter is not kept inside
  // buildLevelUpChoices: ~15 sampling loops in this file (and the survival rig in
  // scripts/pool-probe.mjs) reuse one run across thousands of builds, so a build-counting field
  // would saturate at REROLL_RARITY_CAP after three iterations and then report the 3-reroll
  // distribution as the base rate. Forcing that state on turns run PB1 red (city/2 rare 33.4%),
  // so it is a live regression, not a hypothetical one.
  const before = wired._screenRerolls
  for (let i = 0; i < 4; i++) buildLevelUpChoices(wired)
  assert.strictEqual(wired._screenRerolls, before,
    'buildLevelUpChoices stepped the reroll counter by itself — it must count purchases, not builds')
  // Belt and braces on the one seam this file still cannot execute: main.js is glue and is never
  // imported here, so the check that the button reaches the function is textual (the idiom run
  // BR.f and run UG.g already use on sim.js). If onReroll ever re-implements the purchase inline
  // again, the counter goes back out of test reach — that is the failure this catches.
  {
    const mainSrc = readFileSync(new URL('../src/main.js', import.meta.url), 'utf8')
    const at = mainSrc.indexOf('onReroll()')
    assert.ok(at > 0, 'main.js has no onReroll hook — the reroll button is not wired at all')
    const body = mainSrc.slice(at, mainSrc.indexOf('\n  },', at))
    assert.ok(/rerollLevelUpChoices\(run\)/.test(body),
      "main.js's onReroll no longer calls sim.js's rerollLevelUpChoices — the purchase is back in glue, where no test can see it")
    assert.ok(!/_(?:screenR|r)erolls\s*=/.test(body),
      "main.js's onReroll writes the reroll counters itself — that bookkeeping belongs to sim.js's rerollLevelUpChoices, which is the only copy under test")
  }

  // RARITY. Share of TIERED cards that come up `normal`; weapon upgrades carry UPGRADE_RARITY (no
  // tier at all, v6.7.5) and anomalies carry their own, so neither is something a reroll can raise.
  // A SCALED PASSIVE (one with no per-tier `values` table, so makePassiveCard takes base*mult)
  // is counted separately: it is the one card that adopts the rolled rarity with nothing in
  // between, so its histogram IS the rarity roll, which makes the analytic pin below exact rather
  // than a band. Element cards used to play this role and no longer can — their ladder DECLINES
  // `normal` and re-rolls, and the algebra of that re-roll cancels the decay out entirely
  // (P(rare) reduces to w_rare/otherWeights), so they report the same histogram at every reroll
  // count. A probe that cannot move is worse than no probe: it stays green through the bug.
  const sample = (rerolls, SCREENS = 6000) => {
    Math.random = mulberry32(20260808)
    const run = fixture()
    let normal = 0, total = 0, epicPlus = 0, multSum = 0, verb = 0, verbNormal = 0
    for (let i = 0; i < SCREENS; i++) {
      run._screenRerolls = 0
      run._screensSinceAnomaly = 3       // ...with pity pinned, so it confounds nothing
      let cards = buildLevelUpChoices(run)
      for (let r = 0; r < rerolls; r++) {
        run._screenRerolls++             // ...and these are rerolls OF that screen
        run._screensSinceAnomaly = 3
        cards = buildLevelUpChoices(run)
      }
      for (const c of cards) {
        if (c.kind === 'passive' && !PASSIVES[c.id].values) { verb++; if (c.rarity === 'normal') verbNormal++ }
        if (c.kind === 'anomaly' || c.rarity === UPGRADE_RARITY) continue
        if (c.rarity === 'normal') normal++
        if (c.rarity === 'epic' || c.rarity === 'legendary' || c.rarity === 'mythic') epicPlus++
        multSum += RARITIES[c.rarity].mult
        total++
      }
    }
    return {
      normal: (100 * normal) / total,
      epicPlus: (100 * epicPlus) / total,
      mult: multSum / total,
      verbNormal: (100 * verbNormal) / verb,
      verbN: verb,
    }
  }
  // (…and NOT `.map(sample)`: map passes the index as the second argument, which is `SCREENS`.)
  const rows = [0, 1, 2, REROLL_RARITY_CAP].map((rr) => sample(rr))
  const [zero, , , capped] = rows
  assert.ok(capped.normal < zero.normal - 5,
    `rerolling must raise average rarity — normal ${zero.normal.toFixed(1)}% -> ${capped.normal.toFixed(1)}% of tiered cards over ${REROLL_RARITY_CAP} rerolls`)

  // EXACT, and independent of this fixture: the rarity roll's own `normal` share is
  // w/(others + w) with w = 100 * decay^rerolls, and a scaled passive reports it verbatim. This is
  // what catches an implementation that decays the wrong key, applies the decay twice, or forgets
  // to renormalise — none of which the band above can see.
  const otherWeights = Object.values(RARITY_WEIGHTS).reduce((a, b) => a + b, 0) - RARITY_WEIGHTS.normal
  const rollNormal = (rr) => {
    const w = RARITY_WEIGHTS.normal * Math.pow(REROLL_RARITY_DECAY, Math.min(rr, REROLL_RARITY_CAP))
    return (100 * w) / (otherWeights + w)
  }
  for (const [rr, row] of [[0, zero], [REROLL_RARITY_CAP, capped]]) {
    assert.ok(row.verbN > 2000, `only ${row.verbN} scaled-passive cards at ${rr} rerolls — the exact pin has no sample to read`)
    assert.ok(Math.abs(row.verbNormal - rollNormal(rr)) < 2,
      `at ${rr} rerolls the rarity roll delivered normal ${row.verbNormal.toFixed(2)}% of scaled-passive cards against the ${rollNormal(rr).toFixed(2)}% its own weights declare — the decayed table is not the table being rolled`)
  }
  // ...and the LITERALS the design is documented in (config.js's REROLL_RARITY_DECAY block, spec
  // B6, the plan's Task 4 table). The pin above is derived from the constants, so it stays green
  // at any decay; these do not. Retuning REROLL_RARITY_DECAY to 0.9 reads 52.9% here — half the
  // shipped nudge — and used to pass the entire suite while three documents kept advertising the
  // 0.8 table. If a retune is wanted, re-measure and rewrite those three places WITH this line.
  const DOC = { base: { normal: 53.4, epicPlus: 11.8, mult: 1.495 }, cap: { normal: 41.3, epicPlus: 15.1, mult: 1.636 } }
  for (const [name, row, want] of [['0 rerolls', zero, DOC.base], [`${REROLL_RARITY_CAP} rerolls`, capped, DOC.cap]]) {
    assert.ok(Math.abs(row.normal - want.normal) < 1.5,
      `at ${name} the pool delivered normal ${row.normal.toFixed(1)}% of tiered cards against the ${want.normal}% config.js and spec B6 document`)
    assert.ok(Math.abs(row.epicPlus - want.epicPlus) < 1.2,
      `at ${name} the pool delivered epic-or-better ${row.epicPlus.toFixed(1)}% against the documented ${want.epicPlus}%`)
    assert.ok(Math.abs(row.mult - want.mult) < 0.035,
      `at ${name} the mean rarity multiplier is ${row.mult.toFixed(3)} against the documented ${want.mult}`)
  }

  // The CAP bites. Geometric decay is unbounded: at 6 rerolls normal's share of a rarity roll is
  // 27% against 41.9% at the cap, i.e. a player who can afford them plays a pool nothing was
  // balanced on. Without this the clamp can be deleted with every other assertion still green.
  const past = sample(REROLL_RARITY_CAP + 3)
  assert.ok(Math.abs(past.normal - capped.normal) < 2.5,
    `${REROLL_RARITY_CAP + 3} rerolls gave normal ${past.normal.toFixed(1)}% against ${capped.normal.toFixed(1)}% at the cap of ${REROLL_RARITY_CAP} — the decay is uncapped`)

  // RULE-CHANGES DO NOT MOVE AT ALL. The one place the rarity roll can touch card KIND rather than
  // card size: a `switch` mod (Hive Mind, Sticky Scent, Cyclone, Double Slash — the behavioural
  // ones) declines every rarity above normal, so it is only a candidate on a normal roll. While
  // the mod bucket's candidacy rolled on the DECAYED table, paying for a reroll therefore DELETED
  // rule-change offers to pay for bigger numbers — measured 9.11% -> 6.61% of garden's mod cards
  // at the cap, and 27-32% relative on every chapter that has one. rollCard now rolls mod
  // candidacy on the undecayed table and only the magnitude on the decayed one, so this is an
  // INVARIANCE test, not a bounded-loss one: the whole point is that the number does not move.
  // Measured on GARDEN, which has three switch mods (stinger.hive, stinger.necroticTips,
  // lure.stickyScent) — the most of any chapter, and 3x undergrowth's sample. body, city and
  // beyond have none at all, so they cannot host this test.
  const switchShare = (rerolls, SCREENS = 16000) => {
    Math.random = mulberry32(20260808)
    const gMeta = makeMeta()
    gMeta.choiceSlots = 3
    // The chapter comes from OPTS, never from meta.chapter — createRun ignores that field, so
    // `createRun(meta)` with meta.chapter set is a BODY run wearing another chapter's weapons.
    const run = createRun(gMeta, { chapter: 'garden' })
    assert.strictEqual(run.chapter, 'garden', 'the switch-mod fixture is not a garden run')
    run.player.level = 12
    run.weapons = CHAPTERS.garden.weapons.slice(0, 3).map((id) => ({ id, level: 3 }))
    let mods = 0, switches = 0
    for (let i = 0; i < SCREENS; i++) {
      run._screenRerolls = rerolls
      for (const c of buildLevelUpChoices(run)) {
        if (c.kind !== 'mod') continue
        mods++
        if (WEAPON_MODS[c.weapon]?.[c.id]?.kind === 'switch') switches++
      }
    }
    assert.ok(switches > 300, `the switch-mod fixture saw ${switches} of them — it is not measuring anything`)
    return (100 * switches) / mods
  }
  const sw0 = switchShare(0)
  const swCap = switchShare(REROLL_RARITY_CAP)
  // 1.5 points against a ~9% share: the spread over six seeds is 1.04 points at half this sample
  // and ~0.7 at this one, while the defect this replaces was a 2.5-point FALL. One-sided would be
  // wrong — a reroll must not buy MORE rule-changes either, or coins would be buying the rarest
  // card class again through the other door.
  assert.ok(Math.abs(swCap - sw0) < 1.5,
    `${REROLL_RARITY_CAP} rerolls moved behavioural (switch) mods from ${sw0.toFixed(2)}% to ${swCap.toFixed(2)}% of garden's mod cards — the reroll is trading rule-change cards for bigger numbers (spec F14: they are the class this game has too few of)`)

  // NEITHER DOES DISCOVERY. The weapon bucket weights its `New!` entries by the weapon's inherent
  // rarity, and that weight decides WHICH weapon is offered, not how big a card is — so it stays
  // on the undecayed table on purpose: a reroll promises size, never rarer acquisitions (the
  // jackpot v6.7.4/v6.7.5 spent two releases protecting). Folding the decay into `weaponW` is a
  // one-word edit on that line and moves the `New!` histogram from 57.7/32.8/9.6 to 45.2/42.8/12.0
  // — invisible to every bucket-share test, because the bucket's TOTAL share does not change.
  const newWeaponMix = (rerolls, SCREENS = 6000) => {
    Math.random = mulberry32(20260808)
    const run = fixture()
    const mix = {}
    let n = 0
    for (let i = 0; i < SCREENS; i++) {
      run._screenRerolls = rerolls
      for (const c of buildLevelUpChoices(run)) {
        if (c.kind !== 'weapon' || c.tag !== 'New!') continue
        n++
        mix[c.rarity] = (mix[c.rarity] ?? 0) + 1
      }
    }
    assert.ok(n > 1000, `the New!-weapon fixture saw ${n} of them — it is not measuring anything`)
    return Object.fromEntries(Object.entries(mix).map(([r, c]) => [r, (100 * c) / n]))
  }
  const new0 = newWeaponMix(0)
  const newCap = newWeaponMix(REROLL_RARITY_CAP)
  for (const r of new Set([...Object.keys(new0), ...Object.keys(newCap)])) {
    assert.ok(Math.abs((newCap[r] ?? 0) - (new0[r] ?? 0)) < 2.5,
      `${REROLL_RARITY_CAP} rerolls moved ${r} from ${(new0[r] ?? 0).toFixed(1)}% to ${(newCap[r] ?? 0).toFixed(1)}% of New! weapon cards — rerolling is buying rarer DISCOVERIES, which it must not`)
  }

  // DENOM, exact. A constant Math.random makes the anomaly roll a comparison rather than a sample:
  // pick a threshold strictly between what the two implementations would need, and the correct one
  // declines the tier where the leaking one offers it.
  const ordinaryTotal = Object.values(RARITY_WEIGHTS).reduce((a, b) => a + b, 0)
  const decayedTotal = ordinaryTotal - RARITY_WEIGHTS.normal
    + RARITY_WEIGHTS.normal * Math.pow(REROLL_RARITY_DECAY, REROLL_RARITY_CAP)
  const aw = anomalyWeightFor({ _screensSinceAnomaly: 3 })
  const pTrue = aw / (ordinaryTotal + aw)
  const pLeak = aw / (decayedTotal + aw)
  assert.ok(pLeak > pTrue * 1.05, 'the pin cannot discriminate — REROLL_RARITY_DECAY must be below 1')
  const firesAt = (p, rerolls) => {
    Math.random = () => p
    const run = fixture()
    run._screensSinceAnomaly = 3
    run._screenRerolls = rerolls
    const cards = buildLevelUpChoices(run)
    assert.ok(cards.length > 1, 'the pinned fixture built a 1-card screen — the tier is never rolled there')
    return cards.some((c) => c.kind === 'anomaly')
  }
  assert.strictEqual(firesAt(pTrue * 0.5, REROLL_RARITY_CAP), true,
    'the pinned fixture produces no anomaly at ANY threshold — it is not testing the denominator')
  assert.strictEqual(firesAt((pTrue + pLeak) / 2, REROLL_RARITY_CAP), false,
    `at ${REROLL_RARITY_CAP} rerolls the tier fired at a threshold only a DECAYED denominator can reach (${(pTrue * 100).toFixed(2)}% correct vs ${(pLeak * 100).toFixed(2)}% leaking) — rollAnomalyCard must keep summing the undecayed RARITY_WEIGHTS`)
  assert.strictEqual(firesAt((pTrue + pLeak) / 2, 0), false, 'control: the same threshold must decline at zero rerolls too')

  // ...and the same separation end to end, which would catch any OTHER route from rerolls to the
  // tier. Measured with the memo cleared per screen, so the roll really happens AT the reroll count
  // under test. 20000 screens puts the relative sd of the gap at ~3.3%, so 10% is ~3 sigma; a
  // decayed denominator moves it 35%.
  const anomalyRateAt = (rerolls, N) => {
    Math.random = mulberry32(20260811)
    const run = fixture()
    let hits = 0
    for (let i = 0; i < N; i++) {
      run._screenRerolls = rerolls
      run._screensSinceAnomaly = 3
      if (buildLevelUpChoices(run).some((c) => c.kind === 'anomaly')) hits++
    }
    return (100 * hits) / N
  }
  const N = 20000
  const a0 = anomalyRateAt(0, N)
  const aCap = anomalyRateAt(REROLL_RARITY_CAP, N)
  assert.ok(a0 > 0, 'the tier never rolled in the anomaly-rate fixture at all')
  // v7.20 INVERTED THIS. It used to assert the rate did not move at all (the memo settled the tier
  // at reroll 0); now a paid re-deal rolls the tier fresh at ANOMALY_REROLL_MUL of its weight, so
  // the rate must land at exactly that fraction. Both directions are failures: at x1 the halving
  // is gone and coins farm the tier (B6), at x0 the tier cannot be found on a reroll at all, which
  // is the sticky-Rupture bug this replaced.
  const ratio = aCap / a0
  assert.ok(Math.abs(ratio - ANOMALY_REROLL_MUL) < 0.12,
    `${REROLL_RARITY_CAP} rerolls put the anomaly rate at x${ratio.toFixed(2)} of the natural one (${a0.toFixed(2)}% -> ${aCap.toFixed(2)}%), want x${ANOMALY_REROLL_MUL} — at x1 reroll is buying anomalies (B6), at x0 the tier is sticky again`)

  // The whole table config.js documents, printed rather than described — the rows a reader would
  // otherwise have to take on trust. `node scripts/pool-probe.mjs body 3 40 random --rerolls=N`
  // regenerates them off the shipped pipeline.
  const table = rows.map((r, i) => `${i === 3 ? REROLL_RARITY_CAP : i}:${r.normal.toFixed(1)}/${r.epicPlus.toFixed(1)}/${r.mult.toFixed(3)}`).join(' ')
  console.log(`PASS run PB4 (reroll rarity): rerolls normal%/epic+%/mult ${table} and ${past.normal.toFixed(1)}% normal at ${REROLL_RARITY_CAP + 3} (capped); garden switch mods ${sw0.toFixed(2)}% -> ${swCap.toFixed(2)}% of mod cards and New! discovery unmoved; anomaly rate ${a0.toFixed(2)}% -> ${aCap.toFixed(2)}% (x${ratio.toFixed(2)}, want x${ANOMALY_REROLL_MUL}), denominator pinned undecayed`)
}

// Declines every level-up screen (still banks the xp/level, per stepLevelUp, but grants no
// weapon/passive/mod/element bonus). Used by controlled A/B comparisons below so the two
// runs' power gap is exactly whatever was forced onto them — organic level-up picks are
// themselves RNG-driven and would otherwise contaminate the comparison with an unrelated
// (and unequal, since the two runs walk the same global RNG stream one after another)
// weapon/passive/element path.
function declineLevelUp(run) {
  run.levelUpChoices = null
  run.phase = 'playing'
}

// Tests force elemental potency directly onto run.elements (bypassing the level-up roll — see
// pickNonElementIndex above), so also force the matching run.elementPicks: elArc's arc
// target count now reads run.elementPicks.lightning directly (one arc target per lightning
// pick, not per potency point), so a test that sets elements.lightning without elementPicks
// would silently get zero shock targets.
function setElements(run, elements) {
  Object.assign(run.elements, elements)
  for (const id of Object.keys(elements)) {
    run.elementPicks[id] = Math.max(run.elementPicks[id] ?? 0, Math.round(elements[id]))
  }
}

// A hand-placed enemy with every elemental-status field initialized, matching what
// spawnEnemy sets up in sim.js (see state.js's enemies[] doc block for the field contract).
// affixes (v4.0): defaults to [] like a real non-elite spawn; tests force elite affixes by
// passing e.g. affixes: ['shielded'] (mirrors how testElements forces run.elements directly).
function makeStatusEnemy(run, { x, y, type = 'drone', elite = false, hp = 1e6, speed = 90, affixes = [] }) {
  return {
    id: run._nextId++, type, x, y,
    hp, maxHP: hp, radius: 16, speed, dmg: 8, elite, xp: 1,
    hitFlash: 0, orbCd: 0, kb: { x: 0, y: 0 }, holePull: 0,
    ignite: 0, igniteDps: 0, chill: 0, frozen: 0, venom: 0,
    _shockCd: 0, _elCold: newElWindow(), _elVenom: newElWindow(), _elFrozen: 0, _elResist: 0,
    affixes,
  }
}

// Ring of near-immortal drones around the origin, close enough together that pierce/blast
// mods (and, in run G, shock arcs) have plenty of neighbors to reach — a fixed target-rich
// field so a stronger build's extra damage shows up as more total damage dealt instead of
// being masked by target starvation (a strong build can clear a small finite spawn faster and
// then simply run out of things to shoot, which is what made the original kill-count race
// between star-mod baseline/modded a near-tie: both cleared everything spawnable either way).
function seedTargetRing(run, count, hp, radius) {
  for (let i = 0; i < count; i++) {
    const angle = (i / count) * Math.PI * 2
    run.enemies.push(makeStatusEnemy(run, { x: Math.cos(angle) * radius, y: Math.sin(angle) * radius, hp, speed: 0 }))
  }
}

// Star mods: force a star-only run with pierce maxed out and check it deals more total
// damage than a plain star-only baseline over the same time against a saturated target ring.
// (blast/"Exploding Stars" was removed in v4.6 — star has no AoE splash anymore.)
function testStarMods() {
  const dt = 1 / 60
  const steps = Math.round(20 / dt)

  // Reseed per run so baseline and modded see the SAME spawn stream. Without this both calls
  // consume one continuous stream — they play two different games and the pierce comparison
  // is meaningless. It only ever passed by luck; the v5.5 archetype-lookup fix shifted the
  // stream and flipped the sign.
  function runStarOnly(mods) {
    Math.random = mulberry32(20260714)
    const run = createRun(makeMeta())
    run.weapons = [{ id: 'star', level: 3 }]
    if (mods) Object.assign(run.weaponMods.star, mods)
    seedTargetRing(run, 24, 1e6, 200)
    const explodeEvents = []
    let totalDmg = 0
    let t = 0
    for (let i = 0; i < steps; i++) {
      if (run.phase === 'levelup') { declineLevelUp(run); continue }
      if (run.phase !== 'playing') break
      t += dt
      const input = { x: Math.cos(t), y: Math.sin(t) }
      stepSim(run, input, dt)
      const events = run.events
      run.events = [] // drain, mirroring main.js — otherwise events keep re-appearing every frame
      for (const e of events) {
        if (e.type === 'explode') explodeEvents.push(e)
        if (e.type === 'hit') totalDmg += e.dmg
      }
    }
    return { run, explodeEvents, totalDmg }
  }

  const baseline = runStarOnly(null)
  const modded = runStarOnly({ pierce: 3 })

  assert(baseline.totalDmg > 0, `expected baseline total damage > 0, got ${baseline.totalDmg}`)
  assert(modded.totalDmg > baseline.totalDmg,
    `expected modded total damage (${modded.totalDmg}) > baseline total damage (${baseline.totalDmg})`)
  assert(modded.explodeEvents.length === 0, 'star must emit NO explode events since Exploding Stars was removed (v4.6)')

  console.log(`PASS run F (star mods): baseline dmg=${baseline.totalDmg} modded dmg=${modded.totalDmg} (no explosions — blast removed)`)
}

// Multishot/split/chain: force all three maxed alongside pierce and check the
// cumulative damage against a saturated target ring beats a pierce-only baseline (same
// seed/duration), that split actually produces _shard bullets, and that at least one bullet
// chain-retargeted (run._chains debug counter, see state.js bullets[] doc).
function testAdvancedStarMods() {
  const dt = 1 / 60
  const steps = Math.round(20 / dt)

  // Reseed per run — the comment above already claims "same seed", which only holds if each
  // run restarts the stream rather than continuing where the previous one stopped.
  function runStarOnly(mods) {
    Math.random = mulberry32(20260714)
    const run = createRun(makeMeta())
    run.weapons = [{ id: 'star', level: 3 }]
    if (mods) Object.assign(run.weaponMods.star, mods)
    seedTargetRing(run, 24, 1e6, 200)
    let totalDmg = 0
    let sawShard = false
    let t = 0
    for (let i = 0; i < steps; i++) {
      if (run.phase === 'levelup') { declineLevelUp(run); continue }
      if (run.phase !== 'playing') break
      t += dt
      const input = { x: Math.cos(t), y: Math.sin(t) }
      stepSim(run, input, dt)
      const events = run.events
      run.events = [] // drain, mirroring main.js
      for (const e of events) if (e.type === 'hit') totalDmg += e.dmg
      if (!sawShard && run.bullets.some((b) => b._shard)) sawShard = true
    }
    return { run, totalDmg, sawShard }
  }

  const baseline = runStarOnly({ pierce: 3 })
  const advanced = runStarOnly({ pierce: 3, multishot: 3, split: 2, chain: 3 })

  assert(baseline.totalDmg > 0, `expected baseline total damage > 0, got ${baseline.totalDmg}`)
  assert(advanced.totalDmg > baseline.totalDmg,
    `expected advanced-mod total damage (${advanced.totalDmg}) > pierce-only baseline (${baseline.totalDmg})`)
  assert(advanced.sawShard, 'expected Split Stars to produce at least one _shard bullet')
  assert((advanced.run._chains ?? 0) > 0, `expected at least one Chain Stars retarget, got ${advanced.run._chains}`)

  console.log(`PASS run F2 (multishot/split/chain): baseline dmg=${baseline.totalDmg} advanced dmg=${advanced.totalDmg} chains=${advanced.run._chains}`)
}

// Elements + combos: (a) ignite DoT alone can finish a kill, (b) chill slows movement and
// stacks into a freeze on non-elites while elites/tanks never freeze, (c) every combo event
// fires at least once when its element pair is forced, (d) a combo-loaded run outkills a
// no-element baseline against the same saturated target field.
function testElements() {
  const dt = 1 / 60

  // (a) Ignite DoT alone can kill: land exactly one hit, strip the weapon (and any bullet
  // still in flight) so nothing but the burn can finish the job, then watch it happen.
  {
    const run = createRun(makeMeta())
    run.weapons = [{ id: 'star', level: 1 }]
    setElements(run, { fire: 5 })
    run.player.x = 0; run.player.y = 0
    run.player.hp = 1e9; run.player.maxHP = 1e9
    // The HP budget is BOTH sides of this scenario and it is tight on purpose. Measured: one
    // star-1 hit removes 12, and at fire potency 5 the burn delivers ~12 over EL_WINDOW (6 ticks
    // that each round up off EL_BURN_MIN). So 20 must survive the hit (12 < 20) and must die to the
    // burn (8 left < 12). The old 30 was budgeted against the LINEAR potency the previous element
    // system used — the burn is a share of one hit scaled by sqrt(P) now, so 18 left outlived it.
    run.enemies.push(makeStatusEnemy(run, { x: 100, y: 0, hp: 20, speed: 0 }))

    let hitOnce = false
    for (let i = 0; i < Math.round(2 / dt) && !hitOnce; i++) {
      if (run.phase === 'levelup') { declineLevelUp(run); continue }
      stepSim(run, { x: 0, y: 0 }, dt)
      if (run.events.some((e) => e.type === 'hit')) hitOnce = true
    }
    assert(hitOnce, 'expected the seeded drone to take at least one hit')
    const target = run.enemies.find((e) => !e._dead)
    assert(target, 'expected the drone to survive the single hit (hp budgeted above one star hit)')
    assert(target.ignite > 0, `expected ignite to be applied by the hit, got ${target.ignite}`)

    run.weapons = [] // no more hits from here on
    run.bullets = [] // ...and no in-flight bullet gets to land a second one either

    let dotKilled = false
    for (let i = 0; i < Math.round(4 / dt) && !dotKilled; i++) {
      if (run.phase === 'levelup') { declineLevelUp(run); continue }
      stepSim(run, { x: 0, y: 0 }, dt)
      if (run.kills > 0) dotKilled = true
    }
    assert(dotKilled, 'expected the ignite DoT alone (weapon removed) to kill the seeded drone')
    console.log('PASS run G.a (ignite DoT alone kills)')
  }

  // (b) COLD SLOWS MOVEMENT. The freeze itself and its exemptions live in run EL.d; what this
  // guards is the other half — that the published slow actually reaches stepEnemyMovement. A
  // chilled enemy that still walks at full speed is the failure, and it is invisible in any test
  // that only reads the status field.
  {
    const run = createRun(makeMeta())
    run.weapons = [{ id: 'star', level: 1 }]
    setElements(run, { cold: 5 })
    run.player.x = 0; run.player.y = 0
    run.player.hp = 1e9; run.player.maxHP = 1e9
    const seed = makeStatusEnemy(run, { x: 120, y: 0, hp: 4000, speed: 90 })
    run.enemies.push(seed)

    let sawSlower = false
    for (let i = 0; i < Math.round(20 / dt) && !sawSlower; i++) {
      if (run.phase === 'levelup') { declineLevelUp(run); continue }
      const before = run.enemies.find((e) => e.id === seed.id)
      // Sampled only while chilled-but-not-frozen: a frozen enemy does not move at all, which
      // would pass this on the wrong mechanic.
      if (before && before.chill > 0 && before.frozen <= 0) {
        const startX = before.x
        stepSim(run, { x: 0, y: 0 }, dt)
        const after = run.enemies.find((e) => e.id === seed.id)
        if (after && Math.abs(startX - after.x) < before.speed * dt * 0.95) sawSlower = true
        continue
      }
      stepSim(run, { x: 0, y: 0 }, dt)
    }
    assert(sawSlower, 'a chilled enemy walked at full speed — the published slow never reached stepEnemyMovement')
    console.log('PASS run G.b (cold slows movement)')
  }

  // (c) An element-loaded run outkills a no-element baseline over the same saturated target field
  // and duration. Elements are damage, not decoration: this is the one check that would go red if
  // every element quietly stopped applying.
  function runElementKills(elements) {
    const run = createRun(makeMeta())
    run.weapons = [{ id: 'star', level: 3 }, { id: 'orbit', level: 3 }]
    if (elements) setElements(run, elements)
    run.player.x = 0; run.player.y = 0
    run.player.hp = 1e9; run.player.maxHP = 1e9
    seedTargetRing(run, 40, 150, 220)

    const steps = Math.round(20 / dt)
    for (let i = 0; i < steps; i++) {
      if (run.phase === 'levelup') { declineLevelUp(run); continue }
      if (run.phase !== 'playing') break
      stepSim(run, { x: 0, y: 0 }, dt)
    }
    return run.kills
  }

  const baselineKills = runElementKills(null)
  const elementKills = runElementKills({ fire: 3, cold: 3, lightning: 4, venom: 3 })
  assert(elementKills > baselineKills,
    `expected element-loaded kills (${elementKills}) > no-element baseline kills (${baselineKills})`)
  console.log(`PASS run G.c (elements outkill baseline): baseline=${baselineKills} elements=${elementKills}`)

  // (d) Lightning must visibly arc: elArc's 'shockarc' event is what render draws the bolt from,
  // and an arc that deals damage with no bolt reads as the element doing nothing.
  {
    const run = createRun(makeMeta())
    run.weapons = [{ id: 'star', level: 3 }]
    setElements(run, { lightning: 4 })
    run.player.x = 0; run.player.y = 0
    run.player.hp = 1e9; run.player.maxHP = 1e9
    seedTargetRing(run, 24, 1e6, 200)

    let sawShockArc = false
    let t = 0
    const steps = Math.round(20 / dt)
    for (let i = 0; i < steps && !sawShockArc; i++) {
      if (run.phase === 'levelup') { declineLevelUp(run); continue }
      t += dt
      const input = { x: Math.cos(t), y: Math.sin(t) }
      stepSim(run, input, dt)
      if (run.events.some((e) => e.type === 'shockarc')) sawShockArc = true
    }
    assert(sawShockArc, 'expected a lightning-only run to emit at least one shockarc event')
    console.log('PASS run G.d (lightning run emits shockarc event)')
  }

}

// Black holes pull coins toward their center (not gems): spawn a coin at the vortex rim,
// step the sim once, and check its distance to the hole's center strictly decreased. Also
// checks a gem at the same spot is left untouched (holes only pull coins per the spec).
function testHolePullsCoins() {
  const run = createRun(makeMeta())
  run.player.x = 0; run.player.y = 0
  run.holes.push({
    x: 0, y: 0, radius: 225, coreRadius: 225 * 0.22,
    life: 2.2, duration: 2.2, dmg: 6, tick: 0.22, pull: 340, acc: 0,
  })
  run.coins.push({ x: 220, y: 0, value: 1 }) // at the rim
  const gem = { x: 220, y: 0, xp: 1 }
  run.gems.push(gem)

  const before = Math.hypot(run.coins[0].x, run.coins[0].y)
  stepSim(run, { x: 0, y: 0 }, 1 / 60)

  assert.strictEqual(run.coins.length, 1, 'expected the coin to still exist after one step (not collected)')
  const after = Math.hypot(run.coins[0].x, run.coins[0].y)
  assert(after < before, `expected coin distance to hole center to decrease (before=${before.toFixed(1)}, after=${after.toFixed(1)})`)
  assert.strictEqual(gem.x, 220, 'expected gems to NOT be pulled by black holes')
  assert.strictEqual(gem.y, 0, 'expected gems to NOT be pulled by black holes')

  console.log(`PASS run H (black hole pulls coins, not gems): before=${before.toFixed(1)} after=${after.toFixed(1)}`)
}

// Difficulty must keep climbing all the way to the end, not flatten out once a build comes
// online: (a) the spawnRate/hpScale/elite-cadence curves hit their late-game targets, and (b)
// with weapons stripped (so almost nothing dies and enemies simply pile up) a late-run
// alive-count snapshot beats an early one, showing the higher spawn rate + MAX_ALIVE cap
// actually let more enemies stack up on screen later in the run.
// The late snapshot is read AFTER the loop rather than on an exact-time match: a declined
// level-up costs an iteration without advancing run.time, so any run that levels up ends a few
// hundredths of a second short of 280 and an `Math.abs(run.time - 280) < dt` probe silently
// never fires (it read 0 and failed the compare when v6.5.2's tighter enemy separation started
// jostling 'latch' enemies into the player often enough to feed a level-up — the escalation
// curve was never the thing that broke).
function testEscalation() {
  assert(spawnRate(300) >= 15, `expected spawnRate(300) >= 15, got ${spawnRate(300)}`)
  assert(hpScale(300) >= 7, `expected hpScale(300) >= 7, got ${hpScale(300)}`)
  assert(eliteEveryAt(290) <= 15, `expected elite step at t=290 <= 15s, got ${eliteEveryAt(290)}`)

  const run = createRun(makeMeta())
  run.weapons = []
  run.player.hp = 1e9
  run.player.maxHP = 1e9

  const dt = 1 / 60
  let earlyAlive = 0
  const steps = Math.round(280 / dt)
  for (let i = 0; i < steps; i++) {
    if (run.phase === 'levelup') { declineLevelUp(run); continue }
    if (run.phase !== 'playing') break
    stepSim(run, { x: 0, y: 0 }, dt)
    if (!earlyAlive && run.time >= 60) earlyAlive = run.enemies.length
  }
  const lateAlive = run.enemies.length

  assert(run.time >= 275, `expected the run to reach the late window, stopped at t=${run.time.toFixed(1)}`)
  assert(earlyAlive > 0, `expected some enemies alive at the t=60 snapshot, got ${earlyAlive}`)
  assert(lateAlive > earlyAlive,
    `expected late-run alive count (${lateAlive}) > early-run alive count (${earlyAlive})`)

  console.log(`PASS run I (escalating difficulty): spawnRate(300)=${spawnRate(300).toFixed(2)} hpScale(300)=${hpScale(300).toFixed(2)} eliteStep(290)=${eliteEveryAt(290).toFixed(2)} earlyAlive=${earlyAlive} lateAlive=${lateAlive}`)
}

// Mutators (v4.0): mergeMutatorMods math, and that run.mods
// actually moves the needle at each of its application points in sim.js.
function testMutators() {
  const dt = 1 / 60

  // mergeMutatorMods: every key defaults to 1, and each mutator's effects multiply in
  // (stacking two mutators multiplies both sets of effects independently).
  const empty = mergeMutatorMods([])
  for (const k of Object.keys(empty)) assert.strictEqual(empty[k], 1, `expected ${k} to default to 1 with no mutators`)

  const single = mergeMutatorMods(['overtime'])
  assert.strictEqual(single.spawnMul, MUTATORS.overtime.effects.spawnMul)
  assert.strictEqual(single.xpMul, MUTATORS.overtime.effects.xpMul)
  assert.strictEqual(single.enemyHpMul, 1, 'expected an unrelated key to stay at 1')

  const stacked = mergeMutatorMods(['overtime', 'bulky'])
  assert.strictEqual(stacked.spawnMul, MUTATORS.overtime.effects.spawnMul)
  assert.strictEqual(stacked.xpMul, MUTATORS.overtime.effects.xpMul)
  assert.strictEqual(stacked.enemyHpMul, MUTATORS.bulky.effects.enemyHpMul)
  assert.strictEqual(stacked.coinMul, MUTATORS.bulky.effects.coinMul)

  // spawnMul: spawn accumulation has no RNG in it (only enemy type/position do), so doubling
  // it should almost exactly double the total number of enemies spawned over the same time.
  function spawnedCount(spawnMul) {
    const run = createRun(makeMeta())
    run.mods.spawnMul = spawnMul
    // v6.6.4: this measures the spawn RATE, not density — body's -30% concurrent cap would
    // saturate the doubled run and clip it back to the cap, hiding the very thing under test.
    run.mods.maxAliveMul = 1
    run.weapons = []
    run.player.hp = 1e9
    run.player.maxHP = 1e9
    const steps = Math.round(100 / dt)
    for (let i = 0; i < steps; i++) {
      if (run.phase === 'levelup') { declineLevelUp(run); continue }
      if (run.phase !== 'playing') break
      stepSim(run, { x: 0, y: 0 }, dt)
    }
    return run._nextId - 1
  }
  const baselineSpawned = spawnedCount(1)
  const doubledSpawned = spawnedCount(2)
  assert(doubledSpawned > baselineSpawned * 1.7,
    `expected spawnMul=2 to roughly double spawn count (baseline=${baselineSpawned}, doubled=${doubledSpawned})`)

  // xpMul/coinMul: change gem/coin pickup amounts (applied at pickup time).
  function pickupAmounts(xpMul, coinMul) {
    const run = createRun(makeMeta())
    run.mods.xpMul = xpMul
    run.mods.coinMul = coinMul
    run.player.x = 0; run.player.y = 0
    run.gems.push({ x: 0, y: 0, xp: 10 })
    run.coins.push({ x: 0, y: 0, value: 10 })
    stepSim(run, { x: 0, y: 0 }, dt)
    return { xp: run.player.xp, coins: run.coinsEarned }
  }
  const plainPickup = pickupAmounts(1, 1)
  const boostedPickup = pickupAmounts(2, 2)
  assert(boostedPickup.xp > plainPickup.xp, `expected xpMul to increase xp gained (plain=${plainPickup.xp}, boosted=${boostedPickup.xp})`)
  assert(boostedPickup.coins > plainPickup.coins, `expected coinMul to increase coins earned (plain=${plainPickup.coins}, boosted=${boostedPickup.coins})`)

  // contactDmgTakenMul: increases hurt damage from contact.
  function hurtDamage(mul) {
    const run = createRun(makeMeta())
    run.mods.contactDmgTakenMul = mul
    run.weapons = []
    run.player.x = 0; run.player.y = 0
    run.player.hp = 1e9; run.player.maxHP = 1e9
    run.enemies.push(makeStatusEnemy(run, { x: 0, y: 0 }))
    stepSim(run, { x: 0, y: 0 }, dt)
    const hurtEvt = run.events.find((e) => e.type === 'hurt')
    return hurtEvt ? hurtEvt.dmg : 0
  }
  const normalHurt = hurtDamage(1)
  const boostedHurt = hurtDamage(2)
  assert(boostedHurt > normalHurt, `expected contactDmgTakenMul to increase hurt damage (normal=${normalHurt}, boosted=${boostedHurt})`)

  console.log(`PASS run J (mutators): spawns baseline=${baselineSpawned} doubled=${doubledSpawned} hurt normal=${normalHurt} boosted=${boostedHurt}`)
}

// Elite affixes (v4.0): craft elites with forced affixes (via makeStatusEnemy's affixes
// option) and check each affix's isolated effect on damage, death, and movement.
function testAffixes() {
  const dt = 1 / 60

  // Shielded: reduced damage while above SHIELD_HP_FRAC of maxHP, full damage below it.
  {
    const run = createRun(makeMeta())
    run.weapons = [{ id: 'star', level: 3 }]
    run.player.x = 0; run.player.y = 0
    run.player.critChance = 0 // keep hit damage deterministic (no crit roll)
    const target = makeStatusEnemy(run, { x: 300, y: 0, hp: 1e6, speed: 0, elite: true, affixes: ['shielded'] })
    run.enemies.push(target)

    const aboveHits = []
    const belowHits = []
    let droppedThreshold = false
    const steps = Math.round(12 / dt)
    for (let i = 0; i < steps; i++) {
      if (run.phase === 'levelup') { declineLevelUp(run); continue }
      stepSim(run, { x: 0, y: 0 }, dt)
      const events = run.events
      run.events = [] // drain, mirroring main.js — otherwise old events re-classify on every later frame
      for (const e of events) {
        // Scope the tally to hits ON the crafted elite (events carry the enemy's position):
        // background spawns die fast enough since v6.4.9's body enemyHpMul that their full-damage
        // hits land inside the window and would pollute an all-hits tally.
        if (e.type === 'hit' && Math.hypot(e.x - target.x, e.y - target.y) < 40) (droppedThreshold ? belowHits : aboveHits).push(e.dmg)
      }
      if (!droppedThreshold && aboveHits.length >= 3) {
        target.hp = target.maxHP * (SHIELD_HP_FRAC / 2) // force below the shield threshold
        droppedThreshold = true
      }
      if (droppedThreshold && belowHits.length >= 3) break
    }

    assert(aboveHits.length >= 3, `expected shielded hits above the threshold, got ${aboveHits.length}`)
    assert(belowHits.length >= 3, `expected hits below the threshold, got ${belowHits.length}`)
    const starLv3Dmg = 16 // WEAPONS.star.levels[2].dmg
    const expectedShielded = Math.round(starLv3Dmg * SHIELD_DMG_MUL)
    for (const d of aboveHits) assert.strictEqual(d, expectedShielded, `expected shielded dmg ${expectedShielded} above threshold, got ${d}`)
    for (const d of belowHits) assert.strictEqual(d, starLv3Dmg, `expected full dmg ${starLv3Dmg} below shield threshold, got ${d}`)
    console.log(`PASS run K.a (shielded): above=${aboveHits[0]} below=${belowHits[0]}`)
  }

  // Splitter: dying spawns SPLITTER_COUNT wisps around the corpse. Kill via ignite DoT
  // (mirroring run G.a) rather than a still-in-flight star bullet: a level-3 star's leftover
  // pierce could otherwise immediately catch a freshly-spawned wisp as collateral within the
  // very same dealDamage call, undercounting survivors for reasons unrelated to splitter itself.
  {
    const run = createRun(makeMeta())
    run.weapons = [{ id: 'star', level: 1 }]
    setElements(run, { fire: 5 })
    run.player.x = 0; run.player.y = 0
    run.player.hp = 1e9; run.player.maxHP = 1e9
    // hp 20, not 30: same burn budget as run G.a — one star-1 hit removes 12 and the fire-5 burn
    // delivers ~12, so 30 outlives it under sqrt(P) potency. See the note there.
    const target = makeStatusEnemy(run, { x: 100, y: 0, hp: 20, speed: 0, elite: true, affixes: ['splitter'] })
    run.enemies.push(target)

    let hitOnce = false
    for (let i = 0; i < Math.round(2 / dt) && !hitOnce; i++) {
      if (run.phase === 'levelup') { declineLevelUp(run); continue }
      stepSim(run, { x: 0, y: 0 }, dt)
      if (run.events.some((e) => e.type === 'hit')) hitOnce = true
    }
    assert(hitOnce, 'expected the splitter target to take at least one hit')
    run.weapons = [] // no more hits from here on
    run.bullets = [] // ...and no in-flight bullet lands a second one either

    let killed = false
    for (let i = 0; i < Math.round(4 / dt) && !killed; i++) {
      if (run.phase === 'levelup') { declineLevelUp(run); continue }
      stepSim(run, { x: 0, y: 0 }, dt)
      if (run.kills > 0) killed = true
    }
    assert(killed, 'expected the ignite DoT to finish off the splitter elite')
    // The loop breaks on the frame the kill lands, and the affix now QUEUES its wisps (they are
    // born inside dealDamage, i.e. inside a walk of run.enemies) — so step once more to let
    // flushSpawns move them into the world, exactly as the next game frame would. Weapons are
    // already cleared above, so this frame cannot land a hit of its own.
    stepSim(run, { x: 0, y: 0 }, dt)
    const wisps = run.enemies.filter((e) => e.type === 'wisp' && !e.elite)
    assert(wisps.length >= SPLITTER_COUNT, `expected at least ${SPLITTER_COUNT} splitter wisps, got ${wisps.length}`)
    console.log(`PASS run K.b (splitter): wisps=${wisps.length}`)
  }

  // Volatile: dying arms a bomb; once its fuse ends, a nearby player takes damage.
  {
    const run = createRun(makeMeta())
    run.mods.spawnMul = 0 // isolate the bomb as the only source of player damage
    run.weapons = [{ id: 'star', level: 3 }]
    run.player.x = 0; run.player.y = 0
    run.player.hp = 1e9; run.player.maxHP = 1e9
    const target = makeStatusEnemy(run, { x: 50, y: 0, hp: 10, speed: 0, elite: true, affixes: ['volatile'] })
    run.enemies.push(target)

    let killed = false
    for (let i = 0; i < Math.round(3 / dt) && !killed; i++) {
      if (run.phase === 'levelup') { declineLevelUp(run); continue }
      stepSim(run, { x: 0, y: 0 }, dt)
      if (run.kills > 0) killed = true
    }
    assert(killed, 'expected the volatile elite to die')
    assert(run.bombs.length > 0, 'expected a volatile death to arm a bomb')

    const hpBefore = run.player.hp
    let exploded = false
    for (let i = 0; i < Math.round((VOLATILE_FUSE + 1) / dt) && !exploded; i++) {
      if (run.phase === 'levelup') { declineLevelUp(run); continue }
      stepSim(run, { x: 0, y: 0 }, dt)
      if (run.events.some((e) => e.type === 'explode')) exploded = true
    }
    assert(exploded, 'expected the bomb to explode after its fuse')
    assert(run.player.hp < hpBefore, `expected the bomb blast to damage the player (before=${hpBefore}, after=${run.player.hp})`)
    console.log('PASS run K.c (volatile bomb)')
  }

  // Gilded: dying drops GILDED_COIN_MUL times as many coins as a plain elite kill.
  {
    function killElite(affixes) {
      const run = createRun(makeMeta())
      run.weapons = [{ id: 'star', level: 3 }]
      run.player.x = 0; run.player.y = 0
      const target = makeStatusEnemy(run, { x: 200, y: 0, hp: 10, speed: 0, elite: true, affixes })
      run.enemies.push(target)
      let killed = false
      for (let i = 0; i < Math.round(3 / dt) && !killed; i++) {
        if (run.phase === 'levelup') { declineLevelUp(run); continue }
        stepSim(run, { x: 0, y: 0 }, dt)
        if (run.kills > 0) killed = true
      }
      assert(killed, 'expected the elite to die')
      return run.coins.length
    }
    const plainCoins = killElite([])
    const gildedCoins = killElite(['gilded'])
    assert.strictEqual(plainCoins, ELITE.coins, `expected a plain elite to drop ${ELITE.coins} coins, got ${plainCoins}`)
    assert.strictEqual(gildedCoins, Math.round(ELITE.coins * GILDED_COIN_MUL),
      `expected a gilded elite to drop ${Math.round(ELITE.coins * GILDED_COIN_MUL)} coins, got ${gildedCoins}`)
    console.log(`PASS run K.d (gilded coins): plain=${plainCoins} gilded=${gildedCoins}`)
  }

  // Frenzied: moves faster once below FRENZY_HP_FRAC of maxHP than the same enemy above it.
  {
    function frenziedDist(hpFrac) {
      const run = createRun(makeMeta())
      run.weapons = []
      run.player.x = 5000; run.player.y = 0 // far away: fixed seek direction, never contacts
      const maxHP = 100
      const e = makeStatusEnemy(run, { x: 0, y: 0, hp: maxHP * hpFrac, speed: 100, elite: true, affixes: ['frenzied'] })
      e.maxHP = maxHP
      run.enemies.push(e)
      const startX = e.x
      stepSim(run, { x: 0, y: 0 }, dt)
      const after = run.enemies.find((en) => en.id === e.id)
      return Math.abs(after.x - startX)
    }
    const distAbove = frenziedDist(Math.min(1, FRENZY_HP_FRAC + 0.2))
    const distBelow = frenziedDist(Math.max(0.01, FRENZY_HP_FRAC - 0.1))
    assert(distBelow > distAbove,
      `expected a frenzied enemy below ${FRENZY_HP_FRAC * 100}% hp to move faster (above=${distAbove}, below=${distBelow})`)
    console.log(`PASS run K.e (frenzied): above=${distAbove.toFixed(2)} below=${distBelow.toFixed(2)}`)
  }

  // Pacer (Cheerleader): speeds up other enemies within PACER_RADIUS.
  {
    const run = createRun(makeMeta())
    run.weapons = []
    run.player.x = 5000; run.player.y = 0 // far away: fixed seek direction for both enemies
    const pacer = makeStatusEnemy(run, { x: 0, y: 0, hp: 1e6, speed: 0, elite: true, affixes: ['pacer'] })
    const near = makeStatusEnemy(run, { x: PACER_RADIUS - 10, y: 0, hp: 1e6, speed: 100 })
    const far = makeStatusEnemy(run, { x: PACER_RADIUS + 500, y: 0, hp: 1e6, speed: 100 })
    run.enemies.push(pacer, near, far)

    const nearStartX = near.x
    const farStartX = far.x
    stepSim(run, { x: 0, y: 0 }, dt)
    const nearAfter = run.enemies.find((e) => e.id === near.id)
    const farAfter = run.enemies.find((e) => e.id === far.id)
    const nearDist = Math.abs(nearAfter.x - nearStartX)
    const farDist = Math.abs(farAfter.x - farStartX)
    assert(nearDist > farDist * 1.1, `expected the enemy near a pacer to move faster (near=${nearDist}, far=${farDist})`)
    console.log(`PASS run K.f (pacer): near=${nearDist.toFixed(2)} far=${farDist.toFixed(2)}`)
  }

  // Anchored: no nova knockback (still takes damage) and never pulled into a black hole.
  {
    const run = createRun(makeMeta())
    run.weapons = []
    run.player.x = 0; run.player.y = 0
    const anchored = makeStatusEnemy(run, { x: 60, y: 0, hp: 1e6, speed: 0, elite: true, affixes: ['anchored'] })
    run.enemies.push(anchored)
    run.novas.push({ x: 0, y: 0, r: 0, maxR: 200, dmg: 5, knockback: 300, life: NOVA_LIFE, hit: new Set() })

    let hit = false
    for (let i = 0; i < Math.round(NOVA_LIFE / dt) + 5 && !hit; i++) {
      if (run.phase === 'levelup') { declineLevelUp(run); continue }
      stepSim(run, { x: 0, y: 0 }, dt)
      if (run.events.some((e) => e.type === 'hit')) hit = true
    }
    assert(hit, 'expected the nova to hit the anchored enemy')
    const afterNova = run.enemies.find((e) => e.id === anchored.id)
    assert(afterNova, 'expected the anchored enemy to survive the nova hit')
    assert.strictEqual(afterNova.kb.x, 0, `expected no nova knockback on an anchored enemy, got kb.x=${afterNova.kb.x}`)
    assert.strictEqual(afterNova.kb.y, 0, `expected no nova knockback on an anchored enemy, got kb.y=${afterNova.kb.y}`)

    const beforeHoleX = afterNova.x
    run.holes.push({ x: 0, y: 0, radius: 300, coreRadius: 300 * 0.22, life: 2, duration: 2, dmg: 1, tick: 5, pull: 400, acc: 0 })
    stepSim(run, { x: 0, y: 0 }, dt)
    const afterHole = run.enemies.find((e) => e.id === anchored.id)
    assert.strictEqual(afterHole.x, beforeHoleX, `expected an anchored enemy's x to be untouched by hole pull, got ${afterHole.x} vs ${beforeHoleX}`)
    console.log('PASS run K.g (anchored: no knockback, no hole pull)')
  }
}

// Weapon-mod parity (v4.1): every non-star weapon gets its own mod pool now (see WEAPON_MODS
// in config.js). Exercises one behavioral mod per weapon plus a couple of plain stat mods, and
// the level-up pool's per-weapon gating (only offers a weapon's mods while it's owned).
function testWeaponModParity() {
  const dt = 1 / 60

  // a. Twin Ring: main + inner-ring orbs, every orb entry carries r; bigOrbs raises r.
  {
    const run = createRun(makeMeta())
    run.weapons = [{ id: 'orbit', level: 3 }] // WEAPONS.orbit.levels[2].orbs === 3
    run.weaponMods.orbit.twinRing = 3
    stepSim(run, { x: 0, y: 0 }, dt)
    assert.strictEqual(run.orbs.length, 6, `expected 3 main + 3 twin-ring orbs, got ${run.orbs.length}`)
    for (const o of run.orbs) assert(finite(o.r) && o.r > 0, `expected every orb to carry a positive r, got ${o.r}`)
    const baseR = run.orbs[0].r

    run.weaponMods.orbit.bigOrbs = 0.5
    stepSim(run, { x: 0, y: 0 }, dt)
    assert(run.orbs[0].r > baseR, `expected bigOrbs to raise orb r (base=${baseR}, boosted=${run.orbs[0].r})`)
    console.log(`PASS run L.a (twinRing + bigOrbs): orbs=${run.orbs.length} baseR=${baseR.toFixed(1)} boostedR=${run.orbs[0].r.toFixed(1)}`)
  }

  // b. Echo Wave: one cast with echo=2 produces 3 novas total (1 original + 2 delayed echoes).
  {
    const run = createRun(makeMeta())
    run.weapons = [{ id: 'wave', level: 1 }] // interval 2.4s, well under the 4s window below
    run.weaponMods.wave.echo = 2
    const seenNovas = new Set()
    const steps = Math.round(4 / dt)
    for (let i = 0; i < steps; i++) {
      if (run.phase === 'levelup') { declineLevelUp(run); continue }
      stepSim(run, { x: 0, y: 0 }, dt)
      for (const n of run.novas) seenNovas.add(n)
    }
    assert.strictEqual(seenNovas.size, 3, `expected 1 original + 2 echo novas, got ${seenNovas.size}`)
    console.log(`PASS run L.b (echo wave): novas=${seenNovas.size}`)
  }

  // c. Cluster Bombs: a mine pop with cluster=2 leaves 2 small bomblets behind.
  {
    const run = createRun(makeMeta())
    run.weapons = []
    run.weaponMods.mines.cluster = 2
    run.player.x = 5000; run.player.y = 0 // clear of the mine, so contact damage doesn't interfere
    run.mines.push({ x: 0, y: 0, arm: 0, dmg: 20, radius: 50 })
    run.enemies.push(makeStatusEnemy(run, { x: 5, y: 0, hp: 1e6, speed: 0 }))
    stepSim(run, { x: 0, y: 0 }, dt)
    const bomblets = run.mines.filter((m) => m.small)
    assert.strictEqual(bomblets.length, 2, `expected 2 cluster bomblets, got ${bomblets.length}`)
    console.log(`PASS run L.c (cluster bombs): bomblets=${bomblets.length}`)
  }

  // d. Phantom Wisps: a homing shot with phantom=2 (pierce=3) damages at least 2 distinct
  // enemies before dying — tracked via the max hitIds size seen on any live shot.
  {
    const run = createRun(makeMeta())
    run.weapons = [{ id: 'homing', level: 1 }]
    run.weaponMods.homing.phantom = 2
    seedTargetRing(run, 6, 1e6, 80)
    let maxHitIds = 0
    const steps = Math.round(5 / dt)
    for (let i = 0; i < steps; i++) {
      if (run.phase === 'levelup') { declineLevelUp(run); continue }
      stepSim(run, { x: 0, y: 0 }, dt)
      for (const h of run.homingShots) maxHitIds = Math.max(maxHitIds, h.hitIds.size)
    }
    assert(maxHitIds >= 2, `expected a phantom wisp to hit at least 2 distinct enemies, got max hitIds=${maxHitIds}`)
    console.log(`PASS run L.d (phantom wisps): maxHitIds=${maxHitIds}`)
  }

  // e. Singularity: one hole cast with singularity=1 yields 2 holes, the second at
  // HOLE_SINGULARITY_FRAC of the main cast's radius.
  {
    const run = createRun(makeMeta())
    run.weapons = [{ id: 'hole', level: 1 }] // interval 6.5s, radius 510
    run.weaponMods.hole.singularity = 1
    let fired = false
    const steps = Math.round(7 / dt)
    for (let i = 0; i < steps && !fired; i++) {
      if (run.phase === 'levelup') { declineLevelUp(run); continue }
      stepSim(run, { x: 0, y: 0 }, dt)
      if (run.holes.length > 0) fired = true
    }
    assert(fired, 'expected the black hole to cast at least once')
    assert.strictEqual(run.holes.length, 2, `expected 1 main + 1 singularity hole, got ${run.holes.length}`)
    const radii = run.holes.map((h) => h.radius).sort((a, b) => a - b)
    const expectedSmall = WEAPONS.hole.levels[0].radius * HOLE_SINGULARITY_FRAC
    assert(Math.abs(radii[0] - expectedSmall) < 1e-6, `expected singularity radius ${expectedSmall}, got ${radii[0]}`)
    console.log(`PASS run L.e (singularity): holes=${run.holes.length} radii=${radii.map((r) => r.toFixed(0)).join(',')}`)
  }

  // f. The beam is DOUBLE-ENDED (v5.6.14, Darth Maul): a plain cast is 2 arms ~π apart, and
  // Prismatic Split adds arms on top (prismatic=1 -> 3 arms, evenly spread).
  {
    const base = createRun(makeMeta())
    base.weapons = [{ id: 'rainbow', level: 1 }]
    let fired = false
    for (let i = 0; i < Math.round(9 / dt) && !fired; i++) {
      if (base.phase === 'levelup') { declineLevelUp(base); continue }
      stepSim(base, { x: 0, y: 0 }, dt)
      if (base.beams.length > 0) fired = true
    }
    assert(fired, 'expected the beam to cast at least once')
    assert.strictEqual(base.beams.length, 2, `expected a double-ended staff (2 arms), got ${base.beams.length}`)
    const diff = Math.abs(base.beams[0].angle - base.beams[1].angle)
    const normalized = Math.min(diff, Math.abs(diff - 2 * Math.PI))
    assert(Math.abs(normalized - Math.PI) < 0.05, `expected the two arms ~π apart, got ${normalized.toFixed(3)}`)

    const run = createRun(makeMeta())
    run.weapons = [{ id: 'rainbow', level: 1 }]
    run.weaponMods.rainbow.prismatic = 1
    let fired2 = false
    for (let i = 0; i < Math.round(9 / dt) && !fired2; i++) {
      if (run.phase === 'levelup') { declineLevelUp(run); continue }
      stepSim(run, { x: 0, y: 0 }, dt)
      if (run.beams.length > 0) fired2 = true
    }
    assert(fired2, 'expected the prismatic cast to fire')
    assert.strictEqual(run.beams.length, 3, `expected 2 base arms + 1 prismatic, got ${run.beams.length}`)
    console.log(`PASS run L.f (double-ended + prismatic): base arms=2 at ${normalized.toFixed(3)} rad, prismatic total=${run.beams.length}`)
  }

  // g. Plain stat mods: boomerang.extraRang / homing.extraWisp raise per-volley entity counts;
  // wave.bigWave raises nova maxR. Each compares a modded run against an unmodded baseline,
  // both driven only until their weapon's first cast (so a slow interval doesn't cost extra time).
  {
    function firstFireSnapshot(weaponId, arrKey, modSetter, waitSeconds) {
      const run = createRun(makeMeta())
      run.weapons = [{ id: weaponId, level: 1 }]
      if (modSetter) modSetter(run)
      const steps = Math.round(waitSeconds / dt)
      for (let i = 0; i < steps; i++) {
        if (run.phase === 'levelup') { declineLevelUp(run); continue }
        stepSim(run, { x: 0, y: 0 }, dt)
        if (run[arrKey].length > 0) break
      }
      return run[arrKey]
    }

    const baseRangs = firstFireSnapshot('boomerang', 'boomerangs', null, 2)
    const moddedRangs = firstFireSnapshot('boomerang', 'boomerangs', (r) => { r.weaponMods.boomerang.extraRang = 2 }, 2)
    assert(moddedRangs.length > baseRangs.length,
      `expected extraRang to raise boomerang count (base=${baseRangs.length}, modded=${moddedRangs.length})`)

    const baseWisps = firstFireSnapshot('homing', 'homingShots', null, 1.5)
    const moddedWisps = firstFireSnapshot('homing', 'homingShots', (r) => { r.weaponMods.homing.extraWisp = 2 }, 1.5)
    assert(moddedWisps.length > baseWisps.length,
      `expected extraWisp to raise wisp count (base=${baseWisps.length}, modded=${moddedWisps.length})`)

    const baseNovas = firstFireSnapshot('wave', 'novas', null, 3)
    const moddedNovas = firstFireSnapshot('wave', 'novas', (r) => { r.weaponMods.wave.bigWave = 0.5 }, 3)
    assert(moddedNovas[0].maxR > baseNovas[0].maxR,
      `expected bigWave to raise nova maxR (base=${baseNovas[0].maxR}, modded=${moddedNovas[0].maxR})`)

    console.log(`PASS run L.g (stat mods): rangs base=${baseRangs.length} modded=${moddedRangs.length}; wisps base=${baseWisps.length} modded=${moddedWisps.length}; nova maxR base=${baseNovas[0].maxR} modded=${moddedNovas[0].maxR}`)
  }

  // h. Level-up pool gating: with only star owned, buildLevelUpChoices never offers a non-star
  // weapon mod; once orbit is also owned, orbit mods start appearing.
  {
    const starOnly = createRun(makeMeta())
    starOnly.weapons = [{ id: 'star', level: 3 }]
    let sawNonStarMod = false
    for (let i = 0; i < 300; i++) {
      for (const c of buildLevelUpChoices(starOnly)) {
        if (c.kind === 'mod' && c.weapon !== 'star') sawNonStarMod = true
      }
    }
    assert.strictEqual(sawNonStarMod, false, 'expected only star weapon mods to appear with just star owned')

    const withOrbit = createRun(makeMeta())
    withOrbit.weapons = [{ id: 'star', level: 3 }, { id: 'orbit', level: 3 }]
    let sawOrbitMod = false
    for (let i = 0; i < 300; i++) {
      for (const c of buildLevelUpChoices(withOrbit)) {
        if (c.kind === 'mod' && c.weapon === 'orbit') sawOrbitMod = true
      }
    }
    assert(sawOrbitMod, 'expected orbit weapon mods to appear in the pool once orbit is owned')
    console.log('PASS run L.h (mod pool gating): star-only never offers non-star mods; orbit mods appear once owned')
  }
}

// ---- Run M: build-focus nudge -----------------------------------------------------
// The more picks invested in owned weapons (upgrades + mods), the less often NEW weapons
// join the level-up pool (see NEW_WEAPON_FADE/newWeaponChance in config.js).
function testFocusNudge() {
  const countNewOffers = (run, rounds) => {
    let n = 0
    for (let i = 0; i < rounds; i++) {
      for (const c of buildLevelUpChoices(run)) {
        if (c.kind === 'weapon' && c.tag === 'New!') n++
      }
    }
    return n
  }

  // 4 card slots (not the meta default of 2): more cards per pool means more natural chances
  // for a New! card to land, so the focus-nudge signal isn't swamped by the flat
  // NEW_WEAPON_MIN_RATE apparition floor (which applies per-pool regardless of slot count).
  const fourSlotMeta = () => { const m = makeMeta(); m.choiceSlots = 4; return m }

  const fresh = createRun(fourSlotMeta())
  const freshOffers = countNewOffers(fresh, 400)

  const committed = createRun(fourSlotMeta())
  committed.weapons = [{ id: 'star', level: 5 }] // 4 upgrade picks
  committed.weaponModPicks.star.pierce = 5
  committed.weaponModPicks.star.multishot = 5   // +10 mod picks => invested 14, p at the 0.1 floor
  const committedOffers = countNewOffers(committed, 400)

  assert(freshOffers > 0, 'expected a fresh run to be offered new weapons')
  // POWER, because 0.35 was under-powered and v7.79 drew a false red on it. Measured over 12
  // INDEPENDENT seeds at this N (400 pools x 4 slots per arm): ratio mean 0.275, 1sigma 0.043. The
  // old 0.35 sat at 1.73 sigma — about one seed in 24 trips it with the nudge working perfectly,
  // and this scenario does not seed itself, so it rides whatever stream position the scenarios
  // above leave. 0.45 is 4 sigma. The pathology it must still catch is a DELETED nudge, which
  // reads 1.0 (committed offered as often as fresh) — 17 sigma out, so nothing is given up.
  assert(committedOffers < freshOffers * 0.45,
    `expected a committed build to see far fewer new-weapon cards (fresh=${freshOffers}, committed=${committedOffers})`)

  // v4.6 apparition floor: even a fully committed build must see a New! weapon card in at
  // least ~5% of level-ups (NEW_WEAPON_MIN_RATE guarantee; 3% bound leaves statistical room).
  let poolsWithNew = 0
  const ROUNDS = 3000
  for (let i = 0; i < ROUNDS; i++) {
    const cards = buildLevelUpChoices(committed)
    if (cards.some((c) => c.kind === 'weapon' && c.tag === 'New!')) poolsWithNew++
  }
  const rate = poolsWithNew / ROUNDS
  assert(rate > 0.03, `expected >=~5% of committed-build level-ups to offer a new weapon, got ${(rate * 100).toFixed(1)}%`)
  console.log(`PASS run M (focus nudge): new-weapon offers fresh=${freshOffers} committed=${committedOffers}; floored apparition=${(rate * 100).toFixed(1)}%/level-up`)
}

// ---- Run N: difficulty levels -------------------------------------------------------
// Difficulty d (1..MAX_DIFFICULTY): +25% enemy HP per level above 1, stacked ON TOP of
// mutator effects; main.js also rolls d-1 random mutators (randomMutators is tested here).
function testDifficulty() {
  // undergrowth: this run isolates the DIFFICULTY ladder, so it needs a chapter without a
  // CHAPTERS[id].balance block — v6.4.10's per-chapter HP ladder reached garden (0.95), leaving
  // undergrowth and beyond as the balance-free chapters.
  const base = createRun(makeMeta(), { chapter: 'undergrowth' })
  assert.strictEqual(base.mods.enemyHpMul, 1, 'difficulty defaults to 1 = untouched enemy HP')

  const d3 = createRun(makeMeta(), { chapter: 'undergrowth', difficulty: 3 })
  assert.strictEqual(d3.mods.enemyHpMul, 1.5, `difficulty 3 => enemyHpMul 1.5, got ${d3.mods.enemyHpMul}`)
  assert.strictEqual(d3.mods.coinMul, 1.5, `difficulty 3 => coinMul 1.5, got ${d3.mods.coinMul}`)

  const d5bulky = createRun(makeMeta(), { chapter: 'undergrowth', difficulty: 5, mutators: ['bulky'] })
  assert.strictEqual(d5bulky.mods.enemyHpMul, 1.5 * 2, `bulky(1.5) x difficulty5(2) => 3, got ${d5bulky.mods.enemyHpMul}`)
  assert.strictEqual(d5bulky.mods.coinMul, 1.6 * 2, `bulky coins(1.6) x difficulty5(2) => 3.2, got ${d5bulky.mods.coinMul}`)

  for (let i = 0; i < 50; i++) {
    const ids = randomMutators(4)
    assert.strictEqual(ids.length, 4, 'randomMutators(4) returns 4 ids')
    assert.strictEqual(new Set(ids).size, 4, 'randomMutators ids are distinct')
    for (const id of ids) assert(id in MUTATORS, `unknown mutator id ${id}`)
  }
  assert.strictEqual(randomMutators(0).length, 0, 'randomMutators(0) is empty')

  console.log('PASS run N (difficulty): hp scaling stacks with mutators, randomMutators sane')
}

// ---- Run O: v4.3 "crazy-mod pass" (13 new behavioral mods, one focused check each) ----------
function testCrazyMods() {
  const dt = 1 / 60

  // 1. orbit.supernova: an orb-killed enemy splashes an explode event (radius ORBIT_NOVA_RADIUS).
  function testSupernova() {
    const run = createRun(makeMeta())
    run.weapons = [{ id: 'orbit', level: 1 }]
    run.weaponMods.orbit.supernova = 1
    run.player.x = 0; run.player.y = 0
    run.enemies.push(makeStatusEnemy(run, { x: WEAPONS.orbit.levels[0].radius, y: 0, hp: 1, speed: 0 }))
    let exploded = false
    const steps = Math.round(3 / dt)
    for (let i = 0; i < steps && !exploded; i++) {
      stepSim(run, { x: 0, y: 0 }, dt)
      if (run.events.some((e) => e.type === 'explode' && Math.abs(e.radius - ORBIT_NOVA_RADIUS) < 1e-6)) exploded = true
    }
    assert(exploded, 'expected an orb kill to trigger a Supernova Sparks explosion')
    console.log('PASS run O.1 (orbit supernova): explosion on orb kill confirmed')
  }

  // 2. wave.undertow (Chemotaxis, v6.4.8 redesign): knockback stays a normal push-back, and the
  // cast instead reels in nearby gems/coins (marks them _vac, which pulls them in past magnet range).
  function testUndertow() {
    const run = createRun(makeMeta())
    run.weapons = [{ id: 'wave', level: 1 }] // level0 stats: radius 150, knockback 140
    run.weaponMods.wave.undertow = 1
    run.player.x = 0; run.player.y = 0
    const target = makeStatusEnemy(run, { x: 100, y: 0, hp: 1e6, speed: 0 })
    run.enemies.push(target)

    // Seed loot before the cast: a gem+coin inside the reel radius (radius * 1.5 with 1 stack)
    // but outside the player's magnet range (baseMagnet 70, no shop/passive bonus in a fresh run),
    // plus a gem just past the reel radius that must stay untouched.
    const vacR = WEAPONS.wave.levels[0].radius * (1 + UNDERTOW_VAC_RADIUS_PER_STACK * 1)
    assert(vacR > run.player.magnet, `test setup: expected reel radius (${vacR}) > magnet (${run.player.magnet})`)
    const vacGem = { x: vacR - 20, y: 0, xp: 1 }
    const vacCoin = { x: 0, y: vacR - 20, value: 1 }
    const farGem = { x: vacR + 30, y: 0, xp: 1 }
    run.gems.push(vacGem, farGem)
    run.coins.push(vacCoin)
    const startXp = run.player.xp
    const startCoinsEarned = run.coinsEarned

    let sawKb = false
    const steps = Math.round(3 / dt)
    for (let i = 0; i < steps && !sawKb; i++) {
      stepSim(run, { x: 0, y: 0 }, dt)
      const t = run.enemies.find((e) => e.id === target.id)
      if (t && (t.kb.x !== 0 || t.kb.y !== 0)) sawKb = true
    }
    const t = run.enemies.find((e) => e.id === target.id)
    assert(sawKb, 'expected the nova to knock back the target')
    assert(t.kb.x > 0, `expected knockback to stay a normal push-back (positive kb.x) with Chemotaxis active, got ${t.kb.x}`)

    // The cast that produced the knockback should also have marked the in-range loot _vac, and
    // left the out-of-range gem alone.
    assert.strictEqual(vacGem._vac, true, 'expected the near gem (inside the reel radius) to be marked _vac')
    assert.strictEqual(vacCoin._vac, true, 'expected the near coin (inside the reel radius) to be marked _vac')
    assert.strictEqual(farGem._vac, undefined, 'expected the far gem (outside the reel radius) to stay unmarked')

    // Give the vac'd loot time to travel in and get collected, despite starting outside magnet range.
    for (let i = 0; i < Math.round(3 / dt); i++) stepSim(run, { x: 0, y: 0 }, dt)
    assert(run.player.xp > startXp, 'expected the vac gem to be collected (player xp rose)')
    assert(!run.gems.includes(vacGem), 'expected the vac gem to be removed from run.gems once collected')
    assert(run.coinsEarned > startCoinsEarned, 'expected the vac coin to be collected (coinsEarned rose)')
    assert(!run.coins.includes(vacCoin), 'expected the vac coin to be removed from run.coins once collected')
    assert(run.gems.includes(farGem), 'expected the far gem to remain uncollected (outside the reel and outside magnet range)')

    console.log(`PASS run O.2 (undertow/chemotaxis): kb.x=${t.kb.x.toFixed(2)} (push-back kept), vac gem+coin collected, far gem untouched`)
  }

  // 3. wave.tsunami: every 3rd wave cast has a bigger maxR than the 1st.
  function testTsunami() {
    const run = createRun(makeMeta())
    run.weapons = [{ id: 'wave', level: 1 }] // interval 2.4s
    run.weaponMods.wave.tsunami = 1
    run.player.x = 0; run.player.y = 0
    const seenSet = new Set()
    const seenNovas = []
    const steps = Math.round(8 / dt)
    for (let i = 0; i < steps; i++) {
      stepSim(run, { x: 0, y: 0 }, dt)
      for (const n of run.novas) if (!seenSet.has(n)) { seenSet.add(n); seenNovas.push(n) }
    }
    assert(seenNovas.length >= 3, `expected at least 3 wave casts, got ${seenNovas.length}`)
    assert(seenNovas[2].maxR > seenNovas[0].maxR,
      `expected the 3rd (tsunami) cast's maxR (${seenNovas[2].maxR}) > the 1st's (${seenNovas[0].maxR})`)
    console.log(`PASS run O.3 (tsunami): 1st maxR=${seenNovas[0].maxR.toFixed(1)} 3rd maxR=${seenNovas[2].maxR.toFixed(1)}`)
  }

  // 4. boomerang.backhand: the same stationary target takes more damage on the return hit than
  // the outbound hit (the boomerang naturally re-crosses it: out -> hit -> range -> back -> hit).
  function testBackhand() {
    const run = createRun(makeMeta())
    run.weapons = [{ id: 'boomerang', level: 1 }]
    run.weaponMods.boomerang.backhand = 1
    run.player.critChance = 0
    run.player.x = 0; run.player.y = 0; run.player.facing = 1
    const target = makeStatusEnemy(run, { x: 100, y: 0, hp: 1e9, speed: 0 })
    run.enemies.push(target)
    let outDmg = null, backDmg = null
    const steps = Math.round(3 / dt)
    for (let i = 0; i < steps; i++) {
      stepSim(run, { x: 0, y: 0 }, dt)
      const events = run.events
      run.events = []
      const b = run.boomerangs[0]
      for (const e of events) {
        if (e.type !== 'hit' || !b) continue
        if (b.phase === 'out' && outDmg === null) outDmg = e.dmg
        if (b.phase === 'back' && backDmg === null) backDmg = e.dmg
      }
    }
    assert(outDmg !== null, 'expected an outbound boomerang hit')
    assert(backDmg !== null, 'expected a return-phase boomerang hit')
    assert(backDmg > outDmg, `expected backhand return dmg (${backDmg}) > outbound dmg (${outDmg})`)
    console.log(`PASS run O.4 (backhand): out=${outDmg} back=${backDmg}`)
  }

  // 6. mines.magnetic: an armed mine crawls toward a distant enemy (too far to trigger).
  function testMagneticMines() {
    const run = createRun(makeMeta())
    run.weapons = []
    run.weaponMods.mines.magnetic = 1
    run.player.x = 5000; run.player.y = 0
    run.mines.push({ x: 0, y: 0, arm: 0, dmg: 10, radius: 30 })
    run.enemies.push(makeStatusEnemy(run, { x: 300, y: 0, hp: 1e6, speed: 0 }))
    const before = Math.hypot(run.mines[0].x - 300, run.mines[0].y)
    for (let i = 0; i < 30; i++) stepSim(run, { x: 0, y: 0 }, dt)
    assert.strictEqual(run.mines.length, 1, 'expected the mine to still exist (too far to trigger)')
    const after = Math.hypot(run.mines[0].x - 300, run.mines[0].y)
    assert(after < before, `expected the magnetic mine to crawl toward the enemy (before=${before.toFixed(1)}, after=${after.toFixed(1)})`)
    console.log(`PASS run O.6 (magnetic mines): before=${before.toFixed(1)} after=${after.toFixed(1)}`)
  }

  // 7. mines.chainReaction: one triggered mine detonates a second in-radius (but otherwise
  // untriggered) armed mine — 2 explode events, both dealing damage.
  function testChainReaction() {
    const run = createRun(makeMeta())
    run.weapons = []
    run.weaponMods.mines.chainReaction = 2
    run.player.x = 5000; run.player.y = 0 // clear of the mines, no contact damage
    run.mines.push({ x: 0, y: 0, arm: 0, dmg: 20, radius: 80 })  // triggers naturally
    run.mines.push({ x: 70, y: 0, arm: 0, dmg: 20, radius: 80 }) // in A's blast, no enemy of its own
    run.enemies.push(makeStatusEnemy(run, { x: 2, y: 0, hp: 1e6, speed: 0 }))
    stepSim(run, { x: 0, y: 0 }, dt)
    const explodes = run.events.filter((e) => e.type === 'explode')
    assert.strictEqual(explodes.length, 2, `expected both mines to detonate (2 explode events), got ${explodes.length}`)
    console.log(`PASS run O.7 (chain reaction): explodes=${explodes.length}`)
  }

  // 8. homing.wispNova: a wisp popping on lifetime expiry emits an explode event of the right radius.
  function testWispNova() {
    const run = createRun(makeMeta())
    run.weapons = []
    run.weaponMods.homing.wispNova = 1
    run.player.x = 0; run.player.y = 0
    run.homingShots.push({ x: 0, y: 0, vx: 0, vy: 0, dmg: 50, life: 0.05, speed: 0, turnRate: 0, pierce: 1, hitIds: new Set() })
    let exploded = false
    for (let i = 0; i < 10 && !exploded; i++) {
      stepSim(run, { x: 0, y: 0 }, dt)
      if (run.events.some((e) => e.type === 'explode' && Math.abs(e.radius - WISP_NOVA_RADIUS) < 1e-6)) exploded = true
    }
    assert(exploded, 'expected an expiring wisp to trigger a Popping Wisps explosion')
    console.log('PASS run O.8 (wisp nova): explosion on wisp expiry confirmed')
  }

  // 9. homing.swarm: a wisp kill spawns exactly the tier-bonus count of mini wisps, and none of
  // those minis (even after killing more enemies themselves) ever spawn further minis.
  function testSwarm() {
    const run = createRun(makeMeta())
    run.weapons = []
    run.weaponMods.homing.swarm = 3
    run.player.x = 0; run.player.y = 0
    seedTargetRing(run, 12, 4, 60) // low-hp ring: minis can also land kills if swarm ever misfires
    run.homingShots.push({ x: 0, y: 0, vx: 300, vy: 0, dmg: 50, life: 3, speed: 300, turnRate: 8, pierce: 1, hitIds: new Set() })
    const seenMinis = new Set()
    const steps = Math.round(6 / dt)
    for (let i = 0; i < steps; i++) {
      stepSim(run, { x: 0, y: 0 }, dt)
      for (const h of run.homingShots) if (h._mini) seenMinis.add(h)
    }
    assert(seenMinis.size >= 3, `expected at least 3 mini wisps spawned on kill, got ${seenMinis.size}`)
    assert(seenMinis.size <= 3, `expected exactly the swarm tier bonus (3) mini wisps total, no re-swarm cascade — got ${seenMinis.size}`)
    console.log(`PASS run O.9 (swarm): minis=${seenMinis.size}`)
  }

  // 10. hole.hungry: a hole's radius grows over time while alive.
  function testHungryHole() {
    const run = createRun(makeMeta())
    run.weapons = []
    run.weaponMods.hole.hungry = 1
    run.player.x = 0; run.player.y = 0
    run.player.hp = 1e9; run.player.maxHP = 1e9
    const h = { x: 0, y: 0, radius: 100, coreRadius: 22, spawnRadius: 100, life: 3, duration: 3, dmg: 5, tick: 0.5, pull: 100, acc: 0 }
    run.holes.push(h)
    const before = h.radius
    for (let i = 0; i < Math.round(1 / dt); i++) stepSim(run, { x: 0, y: 0 }, dt)
    const after = run.holes.find((x) => x === h)
    assert(after, 'expected the hole to still be alive')
    assert(after.radius > before, `expected Hungry Hole to grow radius over time (before=${before}, after=${after.radius.toFixed(1)})`)
    console.log(`PASS run O.10 (hungry hole): before=${before} after=${after.radius.toFixed(1)}`)
  }

  // 11. hole.crunch: an expiring hole detonates at its final radius, damaging enemies inside.
  function testCrunch() {
    const run = createRun(makeMeta())
    run.weapons = []
    run.weaponMods.hole.crunch = 1
    run.player.x = 5000; run.player.y = 0
    const target = makeStatusEnemy(run, { x: 50, y: 0, hp: 1e6, speed: 0 })
    run.enemies.push(target)
    const h = { x: 0, y: 0, radius: 150, coreRadius: 33, spawnRadius: 150, life: 0.05, duration: 2, dmg: 5, tick: 5, pull: 0, acc: 0 }
    run.holes.push(h)
    let exploded = false
    for (let i = 0; i < 10 && !exploded; i++) {
      stepSim(run, { x: 0, y: 0 }, dt)
      if (run.events.some((e) => e.type === 'explode' && Math.abs(e.radius - 150) < 1e-6)) exploded = true
    }
    assert(exploded, 'expected the expiring hole to detonate (Big Crunch) at its final radius')
    const expectedDmg = Math.round(5 * CRUNCH_DMG_MUL * (1 + 1))
    const after = run.enemies.find((e) => e.id === target.id)
    assert(after.hp <= 1e6 - expectedDmg + 1, `expected the crunch detonation to deal ~${expectedDmg} dmg, hp=${after.hp}`)
    console.log(`PASS run O.11 (big crunch): expectedDmg=${expectedDmg} targetHp=${after.hp}`)
  }

  // 12. rainbow.focus: a late beam tick deals more damage than an early tick on an identical target.
  function testFocus() {
    const run = createRun(makeMeta())
    run.weapons = []
    run.player.critChance = 0
    run.player.x = 0; run.player.y = 0
    const target = makeStatusEnemy(run, { x: 200, y: 0, hp: 1e9, speed: 0 })
    run.enemies.push(target)
    const duration = 2
    run.beams.push({ angle: 0, life: duration, duration, dmg: 10, tick: 0.1, width: 60, length: 400, rotSpeed: 0, acc: 0, focusBonus: 1 })
    let earlyDmg = null, lateDmg = null
    const steps = Math.round(duration / dt)
    for (let i = 0; i < steps; i++) {
      stepSim(run, { x: 0, y: 0 }, dt)
      const events = run.events
      run.events = []
      for (const e of events) {
        if (e.type !== 'hit') continue
        if (earlyDmg === null) earlyDmg = e.dmg
        lateDmg = e.dmg
      }
    }
    assert(earlyDmg !== null && lateDmg !== null, 'expected hit events from the focused beam')
    assert(lateDmg > earlyDmg, `expected late-beam tick damage (${lateDmg}) > early tick damage (${earlyDmg})`)
    console.log(`PASS run O.12 (focus lens): early=${earlyDmg} late=${lateDmg}`)
  }

  // 14. rainbow.prism (v6.7.6): the beam refracts off the nearest body it crosses, fanning
  // sub-beams FORWARD from that body. The whole point is that a body standing OFF the arm gets hit,
  // so that is what this pins — plus the ladder shape, the damage falloff, and the containment.
  function testPrism() {
    // The ladder is the mod: rare/epic split once into 2, legendary 3-then-2, mythic 4-then-3-then-2.
    assert.deepStrictEqual(prismLadder(2), [2], 'rare/epic: one split into 2')
    assert.deepStrictEqual(prismLadder(3), [3, 2], 'legendary: 3, and each of those into 2')
    assert.deepStrictEqual(prismLadder(4), [4, 3, 2], 'mythic: 4, then 3, then 2')
    assert.deepStrictEqual(prismLadder(0), [], 'no mod = no ladder, so the branch never opens')

    // Geometry: the player at the origin, the arm along +x. `hub` sits on the arm and is what
    // refracts. `off` sits well off the arm but squarely on the upper sub-beam, which leaves hub at
    // +PRISM_SPREAD/2 — it is unreachable by the beam itself and can only be hit by a refraction.
    const armLen = 400, armW = 60
    const build = (withPrism) => {
      const run = createRun(makeMeta(), { chapter: 'city' })
      run.weapons = []; run.obstacles = []; run._obstacleSeed = null; run.mods.spawnMul = 0
      run.player.x = 0; run.player.y = 0; run.player.critChance = 0
      run._laneAcc = 1e6
      const hub = makeStatusEnemy(run, { x: 200, y: 0, hp: 1e9, speed: 0 })
      const a = PRISM_SPREAD / 2
      const off = makeStatusEnemy(run, { x: 200 + Math.cos(a) * 120, y: Math.sin(a) * 120, hp: 1e9, speed: 0 })
      run.enemies.push(hub, off)
      run.beams.push({ angle: 0, life: 1, duration: 1, dmg: 100, tick: 0.1, width: armW,
        length: armLen, rotSpeed: 0, acc: 0, prism: withPrism ? prismLadder(2) : null })
      return { run, hub, off }
    }

    // Control: no mod, so `off` is untouched — proving it really is outside the beam.
    const plain = build(false)
    for (let i = 0; i < Math.round(0.25 / dt); i++) stepSim(plain.run, { x: 0, y: 0 }, dt)
    assert(plain.hub.hp < 1e9, 'sanity: the arm must hit the body standing on it')
    assert.strictEqual(plain.off.hp, 1e9, 'a body off the arm takes nothing without the prism')

    // With the mod: the same body is now reached by the refraction, for PRISM_DMG_MUL of the hit.
    const split = build(true)
    let hubDmg = 0, offDmg = 0
    for (let i = 0; i < Math.round(0.25 / dt); i++) {
      stepSim(split.run, { x: 0, y: 0 }, dt)
      for (const e of split.run.events) {
        if (e.type !== 'hit') continue
        if (Math.abs(e.x - split.hub.x) < 1) hubDmg += e.dmg
        else offDmg += e.dmg
      }
      split.run.events.length = 0
    }
    assert(offDmg > 0, 'expected the refraction to reach a body the beam itself cannot touch')
    assert(Math.abs(offDmg / hubDmg - PRISM_DMG_MUL) < 0.02,
      `expected a sub-beam at ${PRISM_DMG_MUL}x its parent, got ${(offDmg / hubDmg).toFixed(3)}x`)

    // Containment: no body is damaged twice by one refraction, so a tick can never hit `off` more
    // than once no matter how many rays point at it. Two ticks fired above, so two hits, not four.
    const hits = []
    const one = build(true)
    one.run.beams[0].tick = 1e6      // park the tick clock...
    one.run.beams[0].acc = 1e6       // ...then force exactly one tick
    stepSim(one.run, { x: 0, y: 0 }, dt)
    for (const e of one.run.events) if (e.type === 'hit') hits.push(e)
    assert.strictEqual(hits.length, 2, `expected exactly 2 bodies hit by one tick, got ${hits.length}`)
    // And the drawn segments are render-only: they exist, and they carry no damage of their own.
    assert(one.run.prisms.length > 0, 'expected drawn refraction segments for the renderer')
    // v6.7.7: every segment names its generation, which is what render tapers on. A ladder of
    // [4,3,2] can legitimately stop early (a ray that hits nothing does not re-split), so this
    // asserts the range rather than the exact set — but d=0 must always be present, or the fan
    // would be drawn at uniform width and the splash goes back to looking like wireframe.
    const gens = one.run.prisms.map((s) => s.d)
    assert(gens.every((d) => Number.isInteger(d) && d >= 0 && d < 3), `bad prism generations: ${gens}`)
    assert(gens.includes(0), 'expected at least one first-generation segment')
    console.log(`PASS run O.14 (beam prism): ladders 2/[3,2]/[4,3,2], off-arm body took ${offDmg} (${(offDmg / hubDmg).toFixed(2)}x parent), ${one.run.prisms.length} segments across generations ${[...new Set(gens)].sort()}, no double hits`)
  }

  // 13. rainbow.strobe: a strobed beam lands more hit events than an unmodded one over the same time.
  function testStrobe() {
    function totalHits(strobeBonus) {
      const run = createRun(makeMeta())
      run.weapons = [{ id: 'rainbow', level: 1 }] // interval 8.0s, duration 2.2s
      if (strobeBonus) run.weaponMods.rainbow.strobe = strobeBonus
      run.mods.spawnMul = 0
      run.player.x = 0; run.player.y = 0
      const target = makeStatusEnemy(run, { x: 2, y: 0, hp: 1e12, speed: 0 })
      target.radius = 500 // always within beam width/length regardless of rotation angle
      run.enemies.push(target)
      let hits = 0
      const steps = Math.round(11 / dt)
      for (let i = 0; i < steps; i++) {
        stepSim(run, { x: 0, y: 0 }, dt)
        for (const e of run.events) if (e.type === 'hit') hits++
        run.events = []
      }
      return hits
    }
    const baseline = totalHits(0)
    const strobed = totalHits(1)
    assert(strobed > baseline, `expected strobe to increase hit count over the same duration (baseline=${baseline}, strobed=${strobed})`)
    console.log(`PASS run O.13 (strobe ray): baseline hits=${baseline} strobed hits=${strobed}`)
  }

  run(testSupernova)
  run(testUndertow)
  run(testTsunami)
  run(testBackhand)
  run(testMagneticMines)
  run(testChainReaction)
  run(testWispNova)
  run(testSwarm)
  run(testHungryHole)
  run(testCrunch)
  run(testFocus)
  run(testStrobe)
  run(testPrism)
}

// ---- Run P: star balance invariants (v4.4) ---------------------------------------
// Guards the two levers that made star a no-brainer: (1) offer flooding — star is the
// starting/only weapon, so its 6 mods used to be ~32% of all early cards and appeared in ~70%
// of level-up pools; (2) runaway multiplicative compounding — a heavily-modded star hit ~9.5x
// its own pierce/blast baseline (F2). This asserts both are reined in, WITHOUT making star weak
// (it must still clearly beat a plain star and stay under the strong AoE weapons, not vanish).
function testStarBalance() {
  const dt = 1 / 60
  const RARITIES_MULT = RARITIES

  // Bonus for one pick of a mod at a rarity, mirroring makeWeaponModCard in sim.js.
  function modBonus(weaponId, modId, rarity) {
    const c = WEAPON_MODS[weaponId][modId]
    const mult = RARITIES_MULT[rarity].mult
    if (c.kind === 'tier') return WEAPON_MOD_TIER_BONUS[rarity]
    if (c.kind === 'flat') return Math.max(1, Math.round(c.base * mult))
    return c.base * mult
  }
  // Apply "6-spread": one normal-rarity pick on each of the weapon's 6 mods.
  function applySpread6(run, weaponId) {
    for (const modId of Object.keys(WEAPON_MODS[weaponId])) {
      run.weaponMods[weaponId][modId] += modBonus(weaponId, modId, 'normal')
      run.weaponModPicks[weaponId][modId] += 1
    }
  }
  // Total hit-event damage over `seconds` vs a saturated immortal ring (same setup as F2).
  function measureDamage(weaponId, level, apply, seconds = 20) {
    const steps = Math.round(seconds / dt)
    const run = createRun(makeMeta())
    run.weapons = [{ id: weaponId, level }]
    run.mods.spawnMul = 0
    if (apply) apply(run)
    seedTargetRing(run, 24, 1e15, 200)
    let totalDmg = 0
    let t = 0
    for (let i = 0; i < steps; i++) {
      if (run.phase === 'levelup') { declineLevelUp(run); continue }
      if (run.phase !== 'playing') break
      t += dt
      stepSim(run, { x: Math.cos(t), y: Math.sin(t) }, dt)
      for (const e of run.events) if (e.type === 'hit') totalDmg += e.dmg
      run.events = []
    }
    return Math.round(totalDmg)
  }

  // --- Invariant 1: offer fairness. Over many fresh star-only pools, star mods must be a modest
  // slice of cards (not the ~32% flood they were), and no single weapon may exceed the per-pool
  // card cap.
  {
    const starOnly = createRun(makeMeta())
    starOnly.weapons = [{ id: 'star', level: 3 }]
    let starMods = 0
    let totalCards = 0
    let maxStarPerPool = 0
    const N = 2000
    for (let i = 0; i < N; i++) {
      const cards = buildLevelUpChoices(starOnly)
      let perPool = 0
      for (const c of cards) {
        totalCards++
        if (c.kind === 'mod' && c.weapon === 'star') { starMods++; perPool++ }
      }
      maxStarPerPool = Math.max(maxStarPerPool, perPool)
    }
    const share = starMods / totalCards
    // Pin the cap's VALUES, not just the behaviour. Deriving the expectation from the function
    // under test makes the structural guarantee self-ratifying: `(slots) => 2` would satisfy
    // `maxStarPerPool <= starCap` at any slot count, and the share guard below is then the only
    // thing standing between the pool and the 29% flood a flat 2 measures at 2 slots.
    assert.strictEqual(maxModsPerWeaponPerPool(2), 1, 'a 2-card pool may show at most ONE mod of a given weapon')
    assert.strictEqual(maxModsPerWeaponPerPool(3), 1, 'a 3-card pool may show at most ONE mod of a given weapon')
    assert.strictEqual(maxModsPerWeaponPerPool(4), 2, 'a 4-card pool needs TWO or the mod bucket cannot pay its declared share')
    const starCap = maxModsPerWeaponPerPool(starOnly.choiceSlots ?? 2)
    assert(maxStarPerPool <= starCap,
      `expected <= ${starCap} star mod(s) per pool, saw ${maxStarPerPool}`)
    // v6.7 (Track B) recalibration, NOT a relaxed guarantee. The pool now DECLARES a 30% mod
    // bucket (BUCKET_WEIGHTS in config.js), and in a star-only run every mod card is a star mod,
    // so this share is fixed by arithmetic: 0.30 + 0.70*0.30 = 0.510 mod cards per 2-slot pool =
    // 25.5%, with maxModsPerWeaponPerPool(2) = 1 emptying the bucket after the first. The old 20%
    // ceiling was measured against the flat-bag pool, whose whole mod share was 21.8%; no bucket
    // weight, cap, or candidate count can put a declared 30% bucket under it. What is still
    // guaranteed — and still asserted — is that star mods cannot FLOOD: the per-pool cap values
    // above, and a share under the 29.1% that patching maxModsPerWeaponPerPool to a flat 2
    // measures at these slots (the ~32% original). Measured here: 25.7%.
    assert(share < 0.28, `expected star-mod share of early cards < 28%, got ${(share * 100).toFixed(1)}%`)
    console.log(`PASS run P.1 (offer fairness): star-mod share=${(share * 100).toFixed(1)}% maxPerPool=${maxStarPerPool}`)
  }

  // --- Invariant 2: multi-weapon per-pool cap. No single owned weapon may flood a pool.
  {
    const multi = createRun(makeMeta())
    multi.weapons = [{ id: 'star', level: 5 }, { id: 'orbit', level: 3 }, { id: 'wave', level: 2 }, { id: 'boomerang', level: 4 }]
    let worst = 0
    for (let i = 0; i < 2000; i++) {
      const counts = {}
      for (const c of buildLevelUpChoices(multi)) {
        if (c.kind === 'mod') counts[c.weapon] = (counts[c.weapon] ?? 0) + 1
      }
      for (const n of Object.values(counts)) worst = Math.max(worst, n)
    }
    const multiCap = maxModsPerWeaponPerPool(multi.choiceSlots ?? 2)
    assert(worst <= multiCap,
      `expected no weapon to exceed ${multiCap} mod card(s)/pool, saw ${worst}`)
    console.log(`PASS run P.2 (multi-weapon cap): worst per-weapon mods/pool=${worst}`)
  }

  // --- Invariant 3: power band. A 6-modded star must (a) still clearly beat a plain star (stays a
  // solid starter), (b) not exceed the strongest other 6-modded weapon (it isn't the top raw
  // weapon), and (c) sit within a bounded multiple of the MEDIAN other 6-modded weapon.
  {
    const others = ['orbit', 'wave', 'boomerang', 'mines', 'homing', 'hole', 'rainbow']
    const level = 3
    const starPlain = measureDamage('star', level, null)
    const star6 = measureDamage('star', level, (r) => applySpread6(r, 'star'))
    const otherDmg = others.map((w) => measureDamage(w, level, (r) => applySpread6(r, w))).sort((a, b) => a - b)
    const median = otherDmg[Math.floor(otherDmg.length / 2)]
    const strongest = otherDmg[otherDmg.length - 1]

    assert(star6 > starPlain * 1.5, `expected 6-modded star to stay a solid starter (>1.5x plain), got ${star6} vs ${starPlain}`)
    assert(star6 <= strongest, `expected 6-modded star not to exceed the strongest other 6-modded weapon (star=${star6}, strongest-other=${strongest})`)
    assert(star6 <= median * 3.5, `expected 6-modded star within 3.5x the median other 6-modded weapon (star=${star6}, median=${median}, ratio=${(star6 / median).toFixed(2)})`)
    console.log(`PASS run P.3 (power band): starPlain=${starPlain} star6=${star6} median-other=${median} strongest-other=${strongest} star6/median=${(star6 / median).toFixed(2)}x`)
  }

  // --- Invariant 4: compounding bound. The F2 stack (multishot/split/chain on top of
  // pierce) must stay under an 8x runaway over its own pierce-only baseline.
  // (blast removed v4.6 — both sides of the ratio lost it.)
  {
    const level = 3
    const baseline = measureDamage('star', level, (r) => Object.assign(r.weaponMods.star, { pierce: 3 }))
    const advanced = measureDamage('star', level, (r) => Object.assign(r.weaponMods.star, { pierce: 3, multishot: 3, split: 2, chain: 3 }))
    const ratio = advanced / baseline
    assert(advanced > baseline, `expected advanced star mods to still beat the pierce-only baseline (adv=${advanced}, base=${baseline})`)
    assert(ratio <= 8.0, `expected star compounding <= 8x its pierce-only baseline, got ${ratio.toFixed(2)}x`)
    console.log(`PASS run P.4 (compounding bound): baseline=${baseline} advanced=${advanced} ratio=${ratio.toFixed(2)}x`)
  }
}

// v4.5 gold sinks: pre-run consumables (revive/headstart/charged) + level-up reroll pricing.
function testGoldSinks() {
  const dt = 1 / 60

  // Q.a revive: a banked revive prevents death once (restoring hp, granting invuln, shoving
  // nearby enemies, emitting a 'revive' event), then a second lethal hit (after invuln expires,
  // with the revive already spent) kills for real.
  {
    const run = createRun(makeMeta(), { consumables: ['revive'] })
    assert.strictEqual(run.revives, 1, `expected the revive consumable to bank 1 revive, got ${run.revives}`)
    run.mods.spawnMul = 0 // isolate hand-placed enemies as the only source of player damage
    run.player.x = 0; run.player.y = 0
    run.player.hp = 1 // guarantees the very next contact hit is lethal

    const contactEnemy = makeStatusEnemy(run, { x: 10, y: 0, hp: 1e6, speed: 0 })
    const nearbyEnemy = makeStatusEnemy(run, { x: 150, y: 0, hp: 1e6, speed: 0 })
    run.enemies.push(contactEnemy, nearbyEnemy)

    stepSim(run, { x: 0, y: 0 }, dt)

    assert.strictEqual(run.phase, 'playing', `expected the run to keep playing after a revive, got '${run.phase}'`)
    assert.strictEqual(run.revives, 0, `expected the revive to be consumed, got ${run.revives}`)
    assert.strictEqual(run.player.hp, run.player.maxHP * REVIVE_HP_FRAC, `expected hp restored to REVIVE_HP_FRAC of maxHP, got ${run.player.hp}`)
    assert(run.events.some((e) => e.type === 'revive'), 'expected a revive event')
    assert(!run.events.some((e) => e.type === 'dead'), 'expected no dead event on a revived hit')
    assert(nearbyEnemy.kb.x > 0, `expected the nearby enemy (at +x) to be knocked back away from the player (positive kb.x), got kb.x=${nearbyEnemy.kb.x}`)

    // Second lethal hit: wait out the revive's longer invuln window, then take a fresh contact
    // hit (the original contact/nearby enemies got shoved away by the revive itself) with no
    // revives left banked — this time the run actually ends.
    run.player.hp = 1
    const contactEnemy2 = makeStatusEnemy(run, { x: 5, y: 0, hp: 1e6, speed: 0 })
    run.enemies.push(contactEnemy2)
    let died = false
    const steps = Math.round((REVIVE_INVULN + 0.5) / dt)
    for (let i = 0; i < steps && !died; i++) {
      stepSim(run, { x: 0, y: 0 }, dt)
      if (run.phase === 'dead') died = true
    }
    assert(died, `expected the second lethal hit (after invuln expired, no revives left) to kill the player, phase='${run.phase}'`)
    console.log('PASS run Q.a (revive)')
  }

  // Q.b headstart: pre-loaded xp banks exactly two level-ups (declined, per the existing
  // declineLevelUp helper) with zero enemies killed.
  {
    const run = createRun(makeMeta(), { consumables: ['headstart'] })
    assert.strictEqual(run.player.xp, xpForLevel(1) + xpForLevel(2), `expected headstart to pre-load xp, got ${run.player.xp}`)
    run.mods.spawnMul = 0
    for (let i = 0; i < 10 && run.player.level < 3; i++) {
      if (run.phase === 'levelup') { declineLevelUp(run); continue }
      stepSim(run, { x: 0, y: 0 }, dt)
    }
    assert.strictEqual(run.player.level, 3, `expected headstart to bank 2 level-ups (level 1 -> 3), got ${run.player.level}`)
    assert.strictEqual(run.kills, 0, `expected zero kills from banked headstart level-ups, got ${run.kills}`)
    console.log('PASS run Q.b (headstart)')
  }

  // Q.c charged: the starting weapon begins at level 2.
  {
    const run = createRun(makeMeta(), { consumables: ['charged'] })
    assert.strictEqual(run.weapons[0].level, 2, `expected charged core to start the weapon at level 2, got ${run.weapons[0].level}`)
    console.log('PASS run Q.c (charged)')
  }

  // Q.d rerollCost: ceil(10 * 1.5^used) for used=0,1,2 -> 10, 15, 23.
  {
    assert.strictEqual(rerollCost(0), 10, `expected rerollCost(0)=10, got ${rerollCost(0)}`)
    assert.strictEqual(rerollCost(1), 15, `expected rerollCost(1)=15, got ${rerollCost(1)}`)
    assert.strictEqual(rerollCost(2), 23, `expected rerollCost(2)=23, got ${rerollCost(2)}`)
    console.log('PASS run Q.d (rerollCost)')
  }

  // Q.e shop surcharge (v7.49, owner directive): the 1.6^level curve carries a linear surcharge —
  // +20% at level 0, +200% at the last purchasable level — then clamps per line. Assert the ramp's
  // ENDS against base (not against hardcoded coin totals, which would just re-encode 1.6^9), and
  // assert the caps actually BIND: a cap nothing reaches is a cap that could be deleted.
  {
    const last = MAX_SHOP_LEVEL - 1
    // Pin the ceiling map itself. Every other assertion here READS SHOP_COST_CAP to build its own
    // expectation, so it cannot see a wrong number or a dropped line — only this can.
    assert.deepStrictEqual(SHOP_COST_CAP, { damage: 9999, maxHP: 9999, critChance: 9999, coinGain: 9999 },
      'the 9999 ceiling is owner-specified for exactly damage/maxHP/critChance/coinGain')
    assert.strictEqual(SHOP_COST_CAP_DEFAULT, 4999, 'every other shop line stops at 4999 (owner-specified)')
    // Flat-priced lines (`cost`) skip the whole ramp — they sell one level at a stated number and
    // are asserted on their own terms in run BP.ae. Everything else walks the curve.
    for (const id of Object.keys(SHOP)) {
      if (SHOP[id].cost != null) continue
      const base = SHOP[id].base
      assert.strictEqual(shopCost(id, 0), Math.round(base * 1.2),
        `${id} level 0 should cost base * 1.2 (+20%), got ${shopCost(id, 0)} against base ${base}`)
      const cap = SHOP_COST_CAP[id] ?? SHOP_COST_CAP_DEFAULT
      const uncapped = Math.round(base * Math.pow(1.6, last) * 3)
      assert.strictEqual(shopCost(id, last), Math.min(cap, uncapped),
        `${id} last level should be min(cap ${cap}, base * 1.6^${last} * 3 = ${uncapped}), got ${shopCost(id, last)}`)
      // monotonic: a surcharge that ever makes the NEXT level cheaper is a broken ramp
      for (let l = 1; l <= last; l++) {
        assert.ok(shopCost(id, l) >= shopCost(id, l - 1),
          `${id} cost went DOWN from level ${l - 1} (${shopCost(id, l - 1)}) to ${l} (${shopCost(id, l)})`)
      }
    }
    const capped = Object.keys(SHOP).filter((id) => SHOP[id].cost == null
      && Math.round(SHOP[id].base * Math.pow(1.6, last) * 3) > (SHOP_COST_CAP[id] ?? SHOP_COST_CAP_DEFAULT))
    assert.ok(capped.length > 0,
      'no shop line reaches its cost cap at max level — the cap is dead code, or the curve was retuned under it')
    assert.strictEqual(shopCost('damage', last), Math.round(SHOP.damage.base * Math.pow(1.6, last) * 3),
      'damage has the 9999 ceiling and must NOT be clamped by the 4999 default')
    console.log(`PASS run Q.e (shop surcharge): +20% at L0 rising to +200% at L${last}, capped for ${capped.join(', ')}`)
  }
}

// ---- Run R: permanent level-up choice slots (v4.8) + retuned rarity (v4.7) ---------------
function testChoiceSlots() {
  // Fresh meta defaults to 2 slots (no localStorage in this Node harness -> loadMeta's
  // try/catch always takes the fresh-meta branch — still worth asserting explicitly).
  const fresh = loadMeta()
  assert.strictEqual(fresh.choiceSlots, 2, 'fresh meta starts at 2 choice slots')

  // loadMeta FLOORS a stored choiceSlots at 2 and defaults it when missing. It deliberately does
  // NOT clamp it down any more (R3 — see run YY): the ceiling is applied by createRun, at use.
  const stub = {}
  globalThis.localStorage = {
    getItem: () => JSON.stringify(stub),
    setItem: () => {},
  }
  stub.shop = Object.fromEntries(Object.keys(SHOP).map((id) => [id, 0]))
  stub.coins = 0
  const noField = loadMeta()
  assert.strictEqual(noField.choiceSlots, 2, 'loadMeta defaults a missing choiceSlots to 2')
  stub.choiceSlots = 99
  assert.strictEqual(loadMeta().choiceSlots, 99, 'loadMeta PRESERVES a choiceSlots above this build ceiling (R3)')
  stub.choiceSlots = 0
  assert.strictEqual(loadMeta().choiceSlots, 2, 'loadMeta clamps choiceSlots below 2 up to 2')
  delete globalThis.localStorage

  // createRun snapshots meta.choiceSlots -> run.choiceSlots, and buildLevelUpChoices rolls
  // exactly that many cards, for every value 2..4.
  for (const slots of [2, 3, 4]) {
    const meta = makeMeta()
    meta.choiceSlots = slots
    const run = createRun(meta)
    assert.strictEqual(run.choiceSlots, slots, `run.choiceSlots should snapshot meta.choiceSlots=${slots}`)
    run.player.xp = run.player.xpNext + 1
    stepSim(run, { x: 0, y: 0 }, 1 / 60)
    run.events = []
    assert.strictEqual(run.phase, 'levelup', 'expected a level-up to trigger')
    assert.strictEqual(run.levelUpChoices.length, slots,
      `expected ${slots} cards for choiceSlots=${slots}, got ${run.levelUpChoices.length}`)
  }

  // Sacrifice pricing: 20 levels for the 3rd slot, 40 for the 4th, no 5th slot to buy.
  assert.strictEqual(sacrificeCost(2), 20, '3rd card slot costs 20 levels')
  assert.strictEqual(sacrificeCost(3), 40, '4th card slot costs 40 levels')
  assert.strictEqual(sacrificeCost(4), null, 'no 5th card slot')

  // Rarity retune: epic-or-better ≈ 12.3% per card (33% per 3-card screen). Wide statistical band.
  let high = 0
  let total = 0
  const sampler = createRun(makeMeta())
  for (let i = 0; i < 3000; i++) {
    for (const c of buildLevelUpChoices(sampler)) {
      total++
      if (c.rarity === 'epic' || c.rarity === 'legendary' || c.rarity === 'mythic') high++
    }
  }
  const rate = high / total
  assert(rate > 0.09 && rate < 0.16, `expected epic+ per-card rate ≈ 12.3%, got ${(rate * 100).toFixed(1)}%`)
  console.log(`PASS run R (permanent choice slots + rarity retune): slots 2/3/4 -> that many cards, sacrifice costs 20/40, epic+ per card=${(rate * 100).toFixed(1)}%`)
}

// ---- Run S: sequential difficulty unlock (v4.10) -----------------------------------------
// The unlock-on-victory bump itself lives in main.js's endRun (untestable glue, no DOM/main.js
// import here) — this only covers loadMeta's grandfathering/clamping of the ladder, which as of
// v5.0 lives per-chapter at meta.chapters.body.{maxDifficulty,difficulty} (see run T for the
// migration itself; this run keeps covering the plain clamping behavior at that new location).
function testDifficultyUnlock() {
  // (a) Fresh meta (no localStorage in this Node harness) starts locked to level 1.
  const fresh = loadMeta()
  assert.strictEqual(fresh.chapters.body.maxDifficulty, 1, 'fresh meta starts at maxDifficulty 1')
  assert.strictEqual(fresh.chapters.body.difficulty, 1, 'fresh meta starts at difficulty 1')

  // (b) A pre-v4.10 save (difficulty set, no maxDifficulty field) is grandfathered: whatever
  // difficulty was already selected stays reachable, and stays selected.
  const stub = {}
  globalThis.localStorage = {
    getItem: () => JSON.stringify(stub),
    setItem: () => {},
  }
  stub.shop = Object.fromEntries(Object.keys(SHOP).map((id) => [id, 0]))
  stub.coins = 0
  stub.difficulty = 4
  const grandfathered = loadMeta()
  assert.strictEqual(grandfathered.chapters.body.maxDifficulty, 4, 'a stored difficulty=4 with no maxDifficulty grandfathers maxDifficulty to 4')
  assert.strictEqual(grandfathered.chapters.body.difficulty, 4, 'grandfathered difficulty stays 4')

  // (c) A save with difficulty ahead of its own maxDifficulty (stale/edited save) gets
  // difficulty clamped down to maxDifficulty.
  stub.difficulty = 5
  stub.maxDifficulty = 2
  const clamped = loadMeta()
  assert.strictEqual(clamped.chapters.body.maxDifficulty, 2, 'stored maxDifficulty=2 is kept as-is')
  assert.strictEqual(clamped.chapters.body.difficulty, 2, 'difficulty=5 > maxDifficulty=2 clamps down to 2')

  // (d) Garbage maxDifficulty values floor at 1. A value ABOVE this build's ladder is NOT clamped
  // down (R3 — clamping it would persist a newer save's progression loss, see run YY); the ceiling
  // lands on `difficulty`, the level actually launched.
  stub.difficulty = 1
  stub.maxDifficulty = 0
  assert.strictEqual(loadMeta().chapters.body.maxDifficulty, 1, 'maxDifficulty=0 clamps up to 1')
  stub.maxDifficulty = 99
  stub.difficulty = 99
  const future = loadMeta()
  assert.strictEqual(future.chapters.body.maxDifficulty, 99, 'maxDifficulty=99 is PRESERVED, not clamped down')
  assert.strictEqual(future.chapters.body.difficulty, MAX_DIFFICULTY, `the playable difficulty still clamps to this build's ladder (${MAX_DIFFICULTY})`)
  delete globalThis.localStorage

  console.log('PASS run S (sequential difficulty unlock): fresh=1, grandfathered=4, stale-difficulty clamps to maxDifficulty, maxDifficulty floors at 1 and is preserved above the ladder')
}

// ---- Run T: chapter data model + meta migration (v5.0) -----------------------------------
function testChapters() {
  // (a) Fresh meta (no localStorage) defaults to chapter 'body', chapters.body unlocked at
  // maxDifficulty 1, chapters.pond present but locked.
  const fresh = loadMeta()
  assert.strictEqual(fresh.chapter, 'body', 'fresh meta selects the body chapter by default')
  assert.strictEqual(fresh.chapters.body.unlocked, true, 'fresh meta: body chapter starts unlocked')
  assert.strictEqual(fresh.chapters.body.maxDifficulty, 1, 'fresh meta: body chapter starts at maxDifficulty 1')
  assert.strictEqual(fresh.chapters.body.difficulty, 1, 'fresh meta: body chapter starts at difficulty 1')
  assert.strictEqual(fresh.chapters.pond.unlocked, false, 'fresh meta: pond chapter starts locked')

  // (b) A pre-v5.0 (v4) save migrates its top-level difficulty ladder into chapters.body, once,
  // and leaves coins/best/choiceSlots/runs untouched. Top-level difficulty/maxDifficulty are gone.
  const stub = {
    difficulty: 4,
    maxDifficulty: 4,
    best: { time: 280, kills: 900 },
    coins: 50,
    shop: {},
    runs: 3,
    choiceSlots: 3,
  }
  globalThis.localStorage = {
    getItem: () => JSON.stringify(stub),
    setItem: () => {},
  }
  const migrated = loadMeta()
  assert.strictEqual(migrated.chapters.body.unlocked, true, 'migrated save: body chapter unlocked')
  assert.strictEqual(migrated.chapters.body.maxDifficulty, 4, 'migrated save: chapters.body absorbs top-level maxDifficulty')
  assert.strictEqual(migrated.chapters.body.difficulty, 4, 'migrated save: chapters.body absorbs top-level difficulty')
  assert.strictEqual(migrated.best.time, 280, 'migrated save: top-level meta.best.time preserved')
  assert.strictEqual(migrated.best.kills, 900, 'migrated save: top-level meta.best.kills preserved')
  assert.strictEqual(migrated.coins, 50, 'migrated save: coins preserved')
  assert.strictEqual(migrated.choiceSlots, 3, 'migrated save: choiceSlots preserved')
  assert.strictEqual(migrated.runs, 3, 'migrated save: runs preserved')
  assert.strictEqual('difficulty' in migrated, false, 'migrated save: top-level meta.difficulty deleted')
  assert.strictEqual('maxDifficulty' in migrated, false, 'migrated save: top-level meta.maxDifficulty deleted')
  delete globalThis.localStorage

  // (c) nextChapter walks CHAPTER_ORDER, null past the end.
  assert.strictEqual(nextChapter('body'), 'pond', "nextChapter('body') === 'pond'")
  assert.strictEqual(nextChapter('pond'), 'garden', "nextChapter('pond') === 'garden'")
  // Order-independent (v5.4: the arc grew from 3 to 7 chapters) — every id hands off to the next,
  // and only the LAST one terminates the walk.
  for (let i = 0; i < CHAPTER_ORDER.length - 1; i++) {
    assert.strictEqual(nextChapter(CHAPTER_ORDER[i]), CHAPTER_ORDER[i + 1], `nextChapter('${CHAPTER_ORDER[i]}') === '${CHAPTER_ORDER[i + 1]}'`)
  }
  assert.strictEqual(nextChapter(CHAPTER_ORDER[CHAPTER_ORDER.length - 1]), null, `nextChapter('${CHAPTER_ORDER[CHAPTER_ORDER.length - 1]}') === null (last shipped chapter)`)

  // (e) ensureChapterMeta clamps garbage entries into range and fills in missing fields — except
  // maxDifficulty, which is only floored: a value above this build's ladder is preserved (R3).
  const garbageMeta = { chapters: { pond: { unlocked: true, maxDifficulty: 99, difficulty: -5 } } }
  const pond = ensureChapterMeta(garbageMeta, 'pond')
  assert.strictEqual(pond.maxDifficulty, 99, "a maxDifficulty above this build's ladder is preserved (R3), not clamped")
  assert.strictEqual(pond.difficulty, 1, 'garbage difficulty=-5 clamps up to 1')
  assert.strictEqual(pond.best.time, 0, 'ensureChapterMeta fills in a missing best.time')
  assert.strictEqual(pond.best.kills, 0, 'ensureChapterMeta fills in a missing best.kills')

  const missingMeta = {}
  const body = ensureChapterMeta(missingMeta, 'body')
  assert.strictEqual(body.unlocked, true, 'ensureChapterMeta creates a missing body entry unlocked')
  const missingPond = ensureChapterMeta(missingMeta, 'pond')
  assert.strictEqual(missingPond.unlocked, false, 'ensureChapterMeta creates a missing non-body entry locked')

  // (f) Retroactive chapter unlock (v5.3.3): a save whose pond ladder proves a difficulty-3+
  // win (maxDifficulty 4 = won level 3) unlocks garden on load, even though garden didn't
  // exist when the win happened. A ladder at maxDifficulty 3 (won only level 2) does not.
  const earnedStub = {
    coins: 0, shop: {}, best: { time: 0, kills: 0 }, runs: 5, choiceSlots: 2, chapter: 'pond',
    chapters: {
      body: { unlocked: true, maxDifficulty: 5, difficulty: 3, best: { time: 300, kills: 100 } },
      pond: { unlocked: true, maxDifficulty: 4, difficulty: 3, best: { time: 300, kills: 100 } },
    },
  }
  globalThis.localStorage = { getItem: () => JSON.stringify(earnedStub), setItem: () => {} }
  const earned = loadMeta()
  assert.strictEqual(earned.chapters.garden.unlocked, true, 'pond maxDifficulty 4 (won lvl 3) retroactively unlocks garden')
  earnedStub.chapters.pond.maxDifficulty = 3
  const notEarned = loadMeta()
  assert.strictEqual(notEarned.chapters.garden.unlocked, false, 'pond maxDifficulty 3 (won only lvl 2) leaves garden locked')
  delete globalThis.localStorage

  // (g) SOURCE tripwire. ui.js is not headless-testable (DOM), and the volume tap is the ONLY
  // writer of meta.chapter in the whole game — main.js's onChapter is its only caller, and that is
  // what keeps the save's single writer single. Two ways it can go wrong, both silent:
  //   - persisting a chapter the player cannot play. A turned-around volume is tappable on purpose
  //     (it puts the unlock line in the detail panel), so without the availability check a tap on a
  //     padlocked volume would write it to meta.chapter, and the summary's "Next level" would then
  //     offer a locked chapter.
  //   - writing meta.chapter from ui.js at all, which forks the save's ownership.
  // This replaced a tripwire on the carousel's settle(): a scroll handler electing the nearest card
  // by getBoundingClientRect could pick the wrong one on a display:none screen (every rect ties at
  // 0) and raced its own debounce. Tapping a button has neither failure mode.
  {
    const src = readFileSync(new URL('../src/ui.js', import.meta.url), 'utf8')
    const tap = src.slice(src.indexOf('if (el.dataset.vol !== undefined)'), src.indexOf('if (el.dataset.buy !== undefined)'))
    // The ceiling is a STALENESS proxy, not a budget: what it catches is an anchor that has moved,
    // which grabs tens of thousands of characters, so its exact value is arm's-length from anything
    // real. Raised 1400 -> 1800 in v7.x when the handler legitimately grew a line; shaving working
    // code to satisfy a proxy would be the tail wagging the dog. Shrink it again if the handler
    // ever shrinks — the point is that it stays far below "half the file".
    assert.ok(tap.length > 0 && tap.length < 1800, 'could not isolate the volume-tap handler in ui.js — the tripwire below is measuring nothing')
    assert.ok(/chapterAvailable\(meta, id\) && id !== meta\.chapter/.test(tap),
      'a volume tap no longer checks chapterAvailable before persisting — tapping a padlocked volume would save a chapter that cannot be played')
    assert.strictEqual((src.match(/meta\.chapter = /g) ?? []).length, 0, 'ui.js must not write meta.chapter directly — it goes through hooks.onChapter (main.js) so the save stays the single writer')
  }

  // (h) v7.x WIP gate. meta.dev hides work-in-progress chapters from real players, so the two
  // things that matter are that it round-trips and that NOTHING can turn it on by accident. It is
  // coerced (`m.dev === true`) rather than `??=` defaulted, because every gate reads `=== true`:
  // a save carrying 'yes' or 1 would be truthy at every OTHER site and the flag would disagree
  // with itself. A tampered save must read as off, not as "on but only sometimes".
  {
    const devStub = {
      coins: 0, shop: {}, best: { time: 0, kills: 0 }, runs: 0, choiceSlots: 2, chapter: 'body', chapters: {},
    }
    const load = (dev) => {
      if (dev === undefined) delete devStub.dev; else devStub.dev = dev
      globalThis.localStorage = { getItem: () => JSON.stringify(devStub), setItem: () => {} }
      const m = loadMeta()
      delete globalThis.localStorage
      return m.dev
    }
    assert.strictEqual(load(true), true, 'meta.dev: a stored `true` round-trips as true')
    assert.strictEqual(load(false), false, 'meta.dev: a stored `false` stays false')
    assert.strictEqual(load(undefined), false, 'meta.dev: absent (every save written before the gate existed) loads as false')
    for (const junk of [null, 'yes', 1, 'true', {}, []]) {
      assert.strictEqual(load(junk), false, `meta.dev: a tampered ${JSON.stringify(junk)} must load as false, not as a truthy non-boolean`)
    }
    // A brand-new save skips the migration entirely (loadMeta returns the fresh literal), so the
    // literal needs its own `dev: false` — without it the flag reads `undefined`, which works by
    // luck at every truthiness test and is a different value from what every other save carries.
    globalThis.localStorage = { getItem: () => null, setItem: () => {} }
    const freshDev = loadMeta().dev
    delete globalThis.localStorage
    assert.strictEqual(freshDev, false, 'meta.dev: a brand-new save is created with the gate explicitly false, not undefined')
  }

  // (i) v7.x, R1 of the Book 2 plan: the WIP gate must NEVER reach sim.js. sim reads
  // CHAPTERS[run.chapter] and plays what it is handed, which is what makes a run behind the gate
  // take the SHIPPED code path — test the gated thing and you have tested the thing that ships.
  // The moment sim branches on the flag, the two diverge and the gate stops being a gate.
  {
  const simSrc = readFileSync(new URL('../src/sim.js', import.meta.url), 'utf8')
    assert.ok(!/\bmeta\.dev\b/.test(simSrc), 'sim.js reads meta.dev — the WIP gate must not change simulation, or what you playtest is not what ships (plan R1)')
    assert.ok(!/\brun\.dev\b/.test(simSrc), 'sim.js reads run.dev — the WIP gate must not reach the run object (plan R1)')
  }

  console.log('PASS run T (chapter data model + meta migration): fresh defaults, v4 migration, nextChapter, garbage clamps, retroactive unlock, carousel settle guards, WIP gate coercion + R1')
}

// ---- Run BK: books + the WIP gate (v7.x, Book 2 phase 1) ---------------------------------
// The refactor is additive on purpose — CHAPTER_ORDER is an ALIAS for BOOKS.book1.chapters — so the
// danger is not that Book 1 breaks loudly. It is that a WIP chapter LEAKS to a player, or that the
// gate is so tight nothing can reach the chapter it is guarding. Both fail silently, and the second
// one fails while every other test in this file still passes.
function runBooks() {
  // (a) nextChapter walks the id's OWN book and returns null past its end. It used to return 'body'
  // for every id outside CHAPTER_ORDER, because indexOf is -1 and -1 + 1 indexes element 0. Latent
  // then (both call sites were inert); a second book is what makes an outside id routine.
  assert.strictEqual(nextChapter('blank'), null, "nextChapter('blank') === null — The Blank is hidden, outside book 1's ladder")
  assert.strictEqual(nextChapter('shelf'), 'reef', "nextChapter('shelf') === 'reef' — the Undertow ladder walks its own book")
  // DERIVED, not the literal 'reef' this line used to name. Undertow is being built one chapter at a
  // time, so "the last chapter of that book" is a moving fact, and a hardcoded id turns every new
  // chapter into a false red on a test that is not about that chapter at all — the same
  // narrower-denominator-than-the-claim shape CLAUDE.md records for CHAPTER_ORDER. What is actually
  // being asserted is that the walk STOPS at whatever the end currently is.
  const undertow = BOOKS.undertow.chapters
  const lastUndertow = undertow[undertow.length - 1]
  assert.strictEqual(nextChapter(lastUndertow), null, `nextChapter('${lastUndertow}') === null — last chapter of its own book (${undertow.length} of them)`)
  assert.strictEqual(nextChapter('nope'), null, "nextChapter on an id no book claims === null, NOT 'body'")
  assert.strictEqual(nextChapter(undefined), null, 'nextChapter(undefined) === null')
  assert.strictEqual(nextChapter('body'), 'pond', 'nextChapter still walks book 1 normally')
  assert.strictEqual(nextChapter('beyond'), null, "nextChapter past book 1's end === null")

  // (b) A WIP chapter must be unreachable by every route that does NOT ask for it by name: the
  // shipped order and the unlock chain.
  const wip = wipChapterIds()
  assert.ok(wip.length > 0, 'expected at least one WIP chapter, or this whole run asserts nothing')
  for (const id of wip) {
    assert.ok(!CHAPTER_ORDER.includes(id), `WIP chapter '${id}' must not be in CHAPTER_ORDER — that alias is what keeps it out of every shipped loop`)
    assert.ok(Object.hasOwn(CHAPTERS, id), `WIP chapter '${id}' must be a real CHAPTERS entry, or the gate guards nothing`)
  }
  for (const id of CHAPTER_ORDER) {
    assert.ok(!wip.includes(nextChapter(id)), `nextChapter('${id}') surfaced a WIP chapter — the unlock chain must never cross books`)
  }
  // THE GATE IS PER CHAPTER, SO A BOOK MAY BE HALF-SHIPPED (BOOKS[].wipFrom). The Shelf is live and
  // The Reef, one rung below it in the SAME book, is not — which the old book-wide boolean could
  // not express at all. Asserting both sides of that boundary is the whole point of this pair: a
  // regression to a book-level flag makes one of them fail whichever way it goes. The pair walks
  // down the ladder with every reveal; what is asserted is the BOUNDARY, never these two ids.
  assert.strictEqual(isWipChapter('shelf'), false, "isWipChapter('shelf') === false — Undertow's second rung ships")
  assert.strictEqual(isWipChapter('reef'), true, "isWipChapter('reef') — the rung below The Shelf is still gated")
  // isWipChapter is what main.js's onChapter bypasses the unlock check with, so a false positive
  // here would make a SHIPPED locked chapter selectable — the gate leaking in the other direction.
  assert.strictEqual(isWipChapter('pond'), false, "isWipChapter('pond') === false — a shipped chapter is never a WIP bypass")
  assert.strictEqual(isWipChapter('blank'), false, "isWipChapter('blank') === false — hidden is not the same as WIP; it is earned, and book 1 is not wip")
  for (const junk of ['nope', undefined, null, '__proto__', 'constructor']) {
    assert.strictEqual(isWipChapter(junk), false, `isWipChapter(${JSON.stringify(junk)}) === false — no id may bypass the unlock check by accident`)
  }

  // (c) Gate OFF: a save pointing at a WIP chapter plays a SHIPPED one. resolveChapterId still
  // returns it verbatim — it is a real chapter and that helper is only a "does this exist" test.
  const metaOff = { chapter: 'reef', dev: false, chapters: {} }
  assert.strictEqual(resolveChapterId('reef'), 'reef', 'resolveChapterId stays pure — it must NOT learn about the gate (see playableChapterId)')
  assert.strictEqual(playableChapterId(metaOff), CHAPTER_ORDER[0], 'gate off: a WIP meta.chapter falls back to the first shipped chapter')
  assert.strictEqual(playableChapterId({ chapter: 'pond', dev: false }), 'pond', 'gate off: a shipped chapter is untouched')
  for (const junk of [undefined, null, {}, { chapter: 'nope' }]) {
    assert.strictEqual(playableChapterId(junk), CHAPTER_ORDER[0], `playableChapterId(${JSON.stringify(junk)}) falls back rather than throwing`)
  }

  // (d) Gate ON: the WIP id survives the WHOLE path, including createRun's own SECOND resolve.
  // This is the assertion that would have caught the silent downgrade an earlier draft of the plan
  // shipped: making resolveChapterId dev-aware looked right, but createRun re-resolves with no meta
  // to consult, so every gated run became a Body run credited to body's ledger — no throw, no
  // warning. Note it must name a gated id EXPLICITLY: every existing test of this shape iterates
  // CHAPTER_ORDER, which by design never contains one, so they would all still have passed.
  const metaOn = { coins: 0, shop: {}, best: {}, runs: 0, choiceSlots: 2, chapter: 'reef', dev: true, chapters: {} }
  assert.strictEqual(playableChapterId(metaOn), 'reef', 'gate on: the WIP chapter is what Play reads')
  const wipRun = createRun(metaOn, { chapter: 'reef', difficulty: 1 })
  assert.strictEqual(wipRun.chapter, 'reef', "createRun kept 'reef' — if this reads 'body', the gate leaked into resolveChapterId and endRun would credit the wrong chapter")
  // ...ARMED FROM ITS OWN CHAPTER, which is the husk test now that a chapter may be armed with
  // NOTHING. `weapons.length > 0` was the proxy, and it stopped meaning "genuinely playable" the day
  // The Reef declared `starter: null` — but the defect it guards is unchanged and is not about the
  // count: a leaked resolve arms the player from the WRONG chapter's table (body's `star`), which
  // this catches and a length test never did.
  assert.deepStrictEqual(wipRun.weapons.map((w) => w.id), CHAPTERS.reef.starter ? [CHAPTERS.reef.starter] : [],
    `the WIP run is holding [${wipRun.weapons.map((w) => w.id).join(', ')}] against a declared starter of '${CHAPTERS.reef.starter}' — it was armed from some other chapter's table, or from a null id, which is a corpse every firing site dereferences`)

  // (e) Gate ON: the carousel LISTS it and the selection guard ACCEPTS it. Without both, phase 2
  // ships a chapter nothing can select — and every other assertion in this file still passes.
  const listed = { chapters: Object.fromEntries(CHAPTER_ORDER.map((id) => [id, { unlocked: true, maxDifficulty: 1, difficulty: 1 }])), dev: true }
  // Same three assertions the carousel had, against the bookcase that replaced it: what matters is
  // still which chapter ids a player can reach, not the shape they are drawn in.
  const shelved = (m) => titleBookshelf(m).flatMap((sh) => sh.volumes.map((v) => v.id))
  assert.ok(shelved(listed).includes('reef'), 'gate on: the bookcase must shelve the WIP chapter, or it cannot be selected')
  listed.dev = false
  assert.ok(!shelved(listed).includes('reef'), 'gate off: the bookcase must NOT shelve the WIP chapter')
  // THE SHELF IS EVERY LIVE RUNG, AND A HALF-SHIPPED BOOK CONTRIBUTES ONLY ITS LIVE ONES. Derived
  // rather than written down, for the same reason shippedChapterIds is: this used to read
  // `CHAPTER_ORDER` and assert the shelf was exactly book 1, which is a sentence about the release
  // that happened to be current rather than about the gate. Bumping wipFrom now moves this
  // expectation on its own instead of drawing a red that means "the reveal worked".
  assert.deepStrictEqual(shelved(listed).filter((id) => id !== 'blank'), shippedChapterIds().filter((id) => id !== 'blank'),
    'gate off: the shelf is exactly the live rungs of every book (plus The Blank when earned)')
  assert.ok(shelved(listed).includes('shelf'),
    'gate off: The Shelf must be shelved — it is the rung this release reveals, and a player who cannot see it cannot play it')
  // A Book with NO live rung must be ABSENT, not drawn as a sheeted étage: an étage announces that a
  // Book exists. Asserting only on chapter ids (above) cannot see this — the étage could be there
  // with every volume covered and every id still absent from the flat list. Undertow now earns one
  // because The Surf is live; a book gated to its opener (wipFrom 0) still earns none.
  const liveBooks = Object.entries(BOOKS).filter(([, b]) => b.chapters.some((id) => !isWipChapter(id))).map(([k]) => k)
  assert.deepStrictEqual(titleBookshelf(listed).map((sh) => sh.book), liveBooks,
    'gate off: a Book with nothing live has no étage at all — a covered shelf still says a Book is there')
  assert.ok(liveBooks.includes('undertow'), 'Undertow has live rungs now, so it must stand on the bookcase')

  // (e2) The bookcase model itself. Each of these guards a state that renders as a DIFFERENT object
  // on the shelf, and every one of them fails silently — a wrong `started` draws a dust sheet over a
  // Book you can play, and a hidden chapter counted early adds a covered volume for a chapter whose
  // existence the shelf is supposed to withhold.
  const fresh = { dev: false, chapters: { body: { unlocked: true, won: 2 } } }
  const b1 = titleBookshelf(fresh)[0]
  assert.strictEqual(b1.started, true, 'a Book with one unlocked chapter is STARTED (volumes, not a dust sheet)')
  assert.strictEqual(b1.volumes.length, CHAPTER_ORDER.length,
    'an unstarted chapter still occupies a covered volume — the étage is the Book, not just what you own')
  assert.ok(!b1.volumes.some((v) => v.id === 'blank'),
    'The Blank must NOT be shelved before it is unlocked — a covered volume counts a chapter nobody should know about yet')
  assert.strictEqual(b1.stars, 2, 'stars sum `won` (difficulties actually beaten), not maxDifficulty')
  const earned = { dev: false, chapters: { body: { unlocked: true, won: 5 }, blank: { unlocked: true, won: 1 } } }
  assert.ok(titleBookshelf(earned)[0].volumes.some((v) => v.id === 'blank' && v.unlocked),
    'once earned, The Blank joins its OWN Book\'s étage rather than vanishing outside every shelf')
  assert.strictEqual(titleBookshelf(earned)[0].stars, 6, 'a hidden chapter\'s stars count toward its Book')
  assert.strictEqual(titleBookshelf({ dev: false, chapters: {} })[0].started, false,
    'a Book with nothing unlocked is NOT started — ui.js drapes one sheet over the étage, because the chapter count is the tease')
  // The spine name is what a 47px volume actually prints, and a missing entry silently falls back to
  // the full name with its article, which does not fit vertically. Every shelved chapter needs one.
  for (const id of Object.keys(CHAPTERS)) {
    assert.ok(CHAPTER_SPINE[id], `CHAPTER_SPINE is missing '${id}' — its spine would print the article and overflow`)
  }
  // (f) chapterAvailable is the single permission the card, the Play button, the scroll-persist,
  // the brief and onChapter all read. Listing the chapter is NOT enough: the first cut of phase 1
  // fixed only onChapter, and the gated chapter duly appeared in the carousel as a locked "???" card
  // with a dead Play button — listed and unreachable, the same dead end one step further along.
  // Caught by a screenshot, not by a test, which is why it is asserted here now.
  const wipLocked = { dev: false, chapters: { reef: { unlocked: false }, pond: { unlocked: true }, beyond: { unlocked: false } } }
  assert.strictEqual(chapterAvailable(wipLocked, 'reef'), false, 'gate off: a WIP chapter is not available')
  assert.strictEqual(chapterAvailable(wipLocked, 'pond'), true, 'an unlocked shipped chapter is available, gate or no gate')
  assert.strictEqual(chapterAvailable(wipLocked, 'beyond'), false, 'a locked shipped chapter stays locked')
  const wipDev = { ...wipLocked, dev: true }
  assert.strictEqual(chapterAvailable(wipDev, 'reef'), true, 'gate on: the WIP chapter becomes available WITHOUT writing `unlocked` to the save')
  assert.strictEqual(chapterAvailable(wipDev, 'beyond'), false,
    'gate on must NOT unlock a shipped chapter — the bypass is for chapters with no unlock path, not a cheat for the ones that have one')
  assert.strictEqual(wipDev.chapters.reef.unlocked, false,
    'chapterAvailable must stay a pure read — persisting the permission would outlive the gate and leave a WIP chapter unlocked after dev is turned off')

  // main.js and ui.js cannot be imported here (Pixi / import.meta.glob), so the WIRING is a source
  // tripwire: the helper existing proves nothing if a call site still reads `unlocked` directly.
  {
    const mainSrc = readFileSync(new URL('../src/main.js', import.meta.url), 'utf8')
    const uiSrc = readFileSync(new URL('../src/ui.js', import.meta.url), 'utf8')
    const configSrc = readFileSync(new URL('../src/config.js', import.meta.url), 'utf8')
    assert.ok(/if \(!chapterAvailable\(meta, id\)\) return/.test(mainSrc),
      'main.js onChapter no longer gates on chapterAvailable — the carousel would list the chapter and refuse every tap on it')
    assert.ok(!/const chapterId = resolveChapterId\(meta\.chapter\)/.test(mainSrc),
      'main.js still resolves the play path with resolveChapterId — it must use playableChapterId, or the gate does not apply where it matters')
    assert.strictEqual((mainSrc.match(/playableChapterId\(meta\)/g) ?? []).length, 2,
      'onPlay and onDifficulty must BOTH use playableChapterId — onDifficulty writes into the ledger of whatever onPlay launches, so they cannot disagree')
    // THE UNLOCK CHAIN MUST NOT HAND OUT A CHAPTER THAT IS NOT WRITTEN YET. With Undertow shipping
    // one rung at a time, a d3 win on The Surf reaches for The Shelf — and endRun would happily
    // write `unlocked: true` for it, a permission that PERSISTS to disk and so survives the gate
    // being there at all. Not reachable from a headless assert (main.js imports Pixi), so it is a
    // source tripwire, the run UG.k idiom. Deleting the guard is a one-token edit that nothing else
    // in this file can see.
    assert.ok(/if \(next && !isWipChapter\(next\)\) \{/.test(mainSrc),
      "main.js's chapter-unlock chain no longer skips WIP chapters — winning The Surf at 3+ would unlock The Shelf and write it to the save")
    // A VOLUME's availability is decided once, in config.js's titleBookshelf, and arrives as
    // `vol.unlocked` — so volHtml has no gate of its own to get wrong. Five sites remain, and the
    // last two are easy to forget: paintRoom washes the room in the selected chapter's own colour,
    // and a LOCKED chapter must tint nothing, or the shelf hands out the palette of a chapter it is
    // otherwise careful not to name; and the shop's book tab (v7.x) has to LAND on a chapter, so an
    // ungated pick would drop browseChapterId onto a locked one and the title screen you return to
    // would show "???" over a dead Play button. (It was six until the Daily was deleted — its
    // briefing screen badged a locked chapter as a "preview", the one place the gate was allowed
    // to pass.)
    assert.strictEqual((uiSrc.match(/chapterAvailable\(meta, /g) ?? []).length, 5,
      'ui.js must gate the room tint, the detail head, the Play button, the volume tap and the shop book tab on chapterAvailable — any one left reading `unlocked` directly is a chapter you can see and cannot play')
    // ...and the one that MOVED must actually be there, or every volume shelves as a playable spine.
    assert.ok(/unlocked: chapterAvailable\(meta, id\)/.test(configSrc),
      'titleBookshelf no longer decides volume availability with chapterAvailable — a WIP chapter would shelve as a playable spine')
    // The count above is the assertion that keeps missing one. It read 4 and passed while
    // heroCardHtml still gated itself, so The Shelf had a live Play button above a padlocked "???"
    // card — caught by a screenshot. So also sweep the whole title-rendering span for a raw read.
    const titleSpan = uiSrc.slice(uiSrc.indexOf('function volHtml'), uiSrc.indexOf('function boosterSlotsHtml'))
    const rawReads = titleSpan.split('\n').filter((l) => /chapters\?\.\[[a-zA-Z]+\]\?\.unlocked/.test(l) && !l.includes('//'))
      // Counting how much of BOOK 1 is finished is not an availability decision, and must keep
      // reading the raw flag — the completion badge must never count a WIP chapter as progress.
      .filter((l) => !l.includes('CHAPTER_ORDER'))
    assert.deepStrictEqual(rawReads, [],
      `a raw per-chapter \`unlocked\` read is back in the title-rendering span — route it through chapterAvailable or a WIP chapter renders locked:\n${rawReads.join('\n')}`)
  }

  // The cross-book carousel assertions that lived here are GONE, deliberately: origin/main deleted
  // titleChapterList outright and replaced it with titleBookshelf, which groups by book natively
  // and so already fixes the bug they were written to guard (a book becoming LESS reachable the
  // day its `wip` flag comes off). Their replacement is main's own titleBookshelf coverage — do
  // not resurrect these against the deleted function.
  console.log(`PASS run BK (books + WIP gate): nextChapter is book-local, ${wip.length} WIP chapter(s) unreachable by order/unlock, gated both ways through createRun and the bookcase`)
}
run(runBooks)

// ---- Run BP (book progression): per-book shop lines, unlocks and a total shopCost ---------
function runBookProgression() {
  // (a) Every book resolves a line table; book-specific lines merge OVER the universal eight.
  const b1 = shopLines('book1')
  const ut = shopLines('undertow')
  assert.strictEqual(Object.keys(b1).length, Object.keys(SHOP).length,
    'book1 has exactly the eight universal lines — BOOK_SHOP.book1 must not exist')
  for (const id of Object.keys(SHOP)) assert.ok(ut[id], `undertow is missing universal line '${id}'`)
  for (const id of ['deepLungs', 'slowBurn', 'bigGulp']) {
    assert.ok(ut[id], `undertow is missing its own line '${id}'`)
    assert.ok(!b1[id], `book1 must NOT see undertow's line '${id}'`)
  }

  // (b) Line ids are globally unique. shopCost resolves against ONE merged table so its
  // signature never had to change, and that is only sound while ids cannot collide.
  const seen = new Map()
  for (const bookId of BOOK_ORDER) {
    for (const [id, line] of Object.entries(shopLines(bookId))) {
      const prev = seen.get(id)
      if (prev && prev !== line) assert.fail(`shop line id '${id}' is defined differently in two books — shopCost cannot resolve it`)
      seen.set(id, line)
    }
  }

  // (c) shopCost resolves for EVERY line of EVERY book at every level, and stays finite.
  // Before this change it read SHOP[id].base and threw a TypeError on any book-specific line.
  for (const bookId of BOOK_ORDER) {
    for (const id of Object.keys(shopLines(bookId))) {
      for (let lv = 0; lv < MAX_SHOP_LEVEL; lv++) {
        const c = shopCost(id, lv)
        assert.ok(Number.isFinite(c) && c > 0, `shopCost('${id}', ${lv}) must be a positive finite number, got ${c}`)
      }
    }
  }

  // (d) Every line carries the fields the shop screen reads, or it renders blank.
  for (const bookId of BOOK_ORDER) {
    for (const [id, line] of Object.entries(shopLines(bookId))) {
      for (const f of ['name', 'desc', 'perLevel', 'base', 'icon']) {
        assert.ok(line[f] !== undefined, `shop line '${id}' is missing '${f}'`)
      }
    }
  }

  // (e) Only books after the first grant coins, and BOOK_ORDER matches BOOKS.
  assert.deepStrictEqual(BOOK_ORDER, Object.keys(BOOKS), 'BOOK_ORDER must list every book, in order')
  assert.ok(!BOOKS[BOOK_ORDER[0]].startCoins, 'the first book must NOT grant startCoins — a fresh save opens at 0')
  assert.strictEqual(BOOKS.undertow.startCoins, 100, 'undertow grants 100 coins on unlock')

  // (f) Every BOOK_UNLOCKS entry is a real sacrifice target shape.
  for (const [bookId, table] of Object.entries(BOOK_UNLOCKS)) {
    assert.ok(BOOK_ORDER.includes(bookId), `BOOK_UNLOCKS names unknown book '${bookId}'`)
    for (const [id, u] of Object.entries(table)) {
      for (const f of ['costs', 'icon', 'name', 'desc']) {
        assert.ok(u[f] !== undefined, `BOOK_UNLOCKS.${bookId}.${id} is missing '${f}'`)
      }
      // `costs` is the LADDER: one positive-integer price per level, in buying order. A single-
      // purchase unlock is a one-entry array, so there is exactly one shape here and nothing
      // downstream has to branch on "does this one have levels".
      assert.ok(Array.isArray(u.costs) && u.costs.length > 0,
        `BOOK_UNLOCKS.${bookId}.${id}.costs must be a non-empty array — a single purchase is [n]`)
      assert.ok(u.costs.every((c) => Number.isInteger(c) && c > 0),
        `BOOK_UNLOCKS.${bookId}.${id}.costs must all be positive integers`)
      assert.deepStrictEqual([...u.costs].sort((a, b) => a - b), u.costs,
        `BOOK_UNLOCKS.${bookId}.${id}.costs must ascend — a cheaper later rung makes the earlier one a trap`)
    }
  }
  // (g)-(k) live in their own block: `ut` here is ensureBookMeta's return, and the outer scope
  // already has a `ut` from (a) (shopLines('undertow')) — same function, so a bare re-declaration
  // would be a SyntaxError, not a name shadowing bug.
  {
    // (g) bookMeta: book 1 IS the meta (its fields never moved — R2); other books nest.
    const m = makeMeta()
    m.chapters = {}
    assert.strictEqual(bookMeta(m, 'book1'), m, 'bookMeta(meta, book1) returns meta itself — book 1 keeps its top-level fields')
    assert.strictEqual(bookMeta(m, 'undertow'), null, 'an absent purse reads null, it is not conjured by a read')

    // (h) ensureBookMeta is a PURE REPAIR. It never grants — that is the unlock path's job (Task 3).
    const ut = ensureBookMeta(m, 'undertow')
    assert.strictEqual(ut.coins, 0, 'ensureBookMeta creates a purse at ZERO — creation must not be a payout')
    assert.strictEqual(ut.choiceSlots, 2, 'a new book starts at 2 card slots')
    assert.deepStrictEqual(ut.unlocks, {}, 'a new book has no unlocks')
    for (const id of Object.keys(shopLines('undertow'))) {
      assert.strictEqual(ut.shop[id], 0, `new purse must carry line '${id}' at 0`)
    }
    ut.coins = 55
    assert.strictEqual(ensureBookMeta(m, 'undertow').coins, 55, 'ensureBookMeta REPAIRS IN PLACE — it must not rebuild the entry')

    // (i) A future build's unknown line and unknown BOOK survive the repair (R3: clamp on use,
    // never on load). Rebuilding the map instead of repairing it would delete both.
    m.books.undertow.shop.futureLine = 7
    m.books.someBook3 = { coins: 12, shop: {}, choiceSlots: 3, unlocks: {} }
    ensureBookMeta(m, 'undertow')
    assert.strictEqual(m.books.undertow.shop.futureLine, 7, "a future build's shop line must survive the repair")
    assert.strictEqual(m.books.someBook3.coins, 12, "a future build's whole BOOK must survive the repair")

    // (j) UPGRADE ISOLATION — the reset is real. This is the assertion the whole design is for.
    const rich = makeMeta()
    rich.shop.damage = MAX_SHOP_LEVEL          // book 1 maxed
    rich.chapters = { surf: { unlocked: true, maxDifficulty: 1, difficulty: 1, best: { time: 0, kills: 0 } } }
    const b1run = createRun(rich, { chapter: 'body' })
    const utrun = createRun(rich, { chapter: 'surf' })
    assert.ok(b1run.player.damageMul > 1, 'book 1 upgrades apply in a book 1 chapter')
    assert.strictEqual(utrun.player.damageMul, 1, "book 1's damage upgrade must NOT apply in an Undertow chapter")

    // (k) SLOT RESET — 4 slots in book 1 does not deal 4 cards in book 2.
    rich.choiceSlots = MAX_CHOICE_SLOTS
    assert.strictEqual(createRun(rich, { chapter: 'body' }).choiceSlots, MAX_CHOICE_SLOTS, 'book 1 keeps its slots')
    assert.strictEqual(createRun(rich, { chapter: 'surf' }).choiceSlots, 2, 'a book 2 run resets to 2 card slots')
  }

  // (l) THE GATE IS THE LAST CHAPTER, stated as a fact — not "nextChapter returned null", which
  // is also true of The Blank (hidden, and its ladder tops out at exactly CHAPTER_UNLOCK_DIFFICULTY).
  assert.strictEqual(nextChapter('blank'), null, 'precondition: The Blank has no next chapter')
  assert.strictEqual(chapterMaxDifficulty('blank'), CHAPTER_UNLOCK_DIFFICULTY,
    'precondition: a Blank win at its cap sits exactly at the book-unlock difficulty — this is why a null check is not enough')
  assert.strictEqual(isBookFinale('beyond'), true, "The Beyond is book 1's finale")
  assert.strictEqual(isBookFinale('blank'), false, 'The Blank is HIDDEN — winning it must not unlock the next book')
  assert.strictEqual(isBookFinale('pond'), false, 'a mid-ladder chapter is not a finale')
  // Undertow's finale is asserted DERIVED, not hardcoded. This line used to read
  // isBookFinale('reef') === true and went red the moment The Trawl shipped as a fourth Undertow
  // chapter — the production code was right (it reads chapters.at(-1)) and only the test's guess
  // was stale. Deriving it means a fifth chapter moves the finale without a false red; the
  // assertion that still carries weight is the NEGATIVE one below it, which pins that a chapter
  // demoted out of last place stops being a finale.
  const utLast = BOOKS.undertow.chapters.at(-1)
  assert.strictEqual(isBookFinale(utLast), true, `Undertow's finale is its last chapter (${utLast})`)
  for (const id of BOOKS.undertow.chapters.slice(0, -1)) {
    assert.strictEqual(isBookFinale(id), false, `'${id}' is not last in Undertow's ladder, so it must not gate the next book`)
  }

  // (m) THE GRANT IS MONOTONE. Creating a purse pays nothing; granting twice pays once.
  const g = makeMeta(); g.chapters = {}
  ensureBookMeta(g, 'undertow')
  assert.strictEqual(bookMeta(g, 'undertow').coins, 0, 'a purse that exists but was never granted holds 0')
  assert.strictEqual(grantBook(g, 'undertow'), true, 'the first grant fires')
  assert.strictEqual(bookMeta(g, 'undertow').coins, 100, 'the grant is BOOKS.undertow.startCoins')
  assert.strictEqual(grantBook(g, 'undertow'), false, 'the second grant is a no-op')
  assert.strictEqual(bookMeta(g, 'undertow').coins, 100, 'granting twice must not pay twice')
  // ...and it survives the purse being spent to zero, which "creation is the grant" could not.
  bookMeta(g, 'undertow').coins = 0
  assert.strictEqual(grantBook(g, 'undertow'), false, 'a spent purse must not re-grant')

  // (n) A FRESH SAVE HAS EXACTLY ONE PURSE, and it is book 1. This is the assertion that catches
  // a fresh-meta literal that helpfully builds every book — which would hand 100 free coins to
  // every new player and still pass a "purse === startCoins" test.
  const fresh = makeMeta()
  assert.ok(!fresh.books || Object.keys(fresh.books).length === 0,
    'a fresh save must not pre-create any book 2+ purse')
  assert.ok(!fresh.grants || Object.keys(fresh.grants).length === 0, 'a fresh save has granted nothing')

  // (o) RETROACTIVE UNLOCK. A veteran beat The Beyond at 3+ BEFORE Undertow shipped. endRun can
  // only fire on a live victory, so without this every existing player is locked out on ship day
  // — including everyone holding The Blank, which requires a Beyond win at 5. loadMeta already
  // runs exactly this chain for CHAPTERS (state.js) and its comment says why.
  //
  // THE SURF SHIPPING FLIPS THIS (2026-08-18), and the flip IS the release. unlockBook refuses a
  // book whose FIRST chapter is still wip; Undertow's opener is now live, so a veteran save with no
  // dev flag at all gets the grant and the unlock the moment it loads. That is the path every real
  // player is on — without it a player who finished Book 1 months ago would open the game on ship
  // day and find nothing new, because endRun can only fire on a LIVE victory.
  // The gate has moved down a rung again (wipFrom 2). The Shelf is LIVE now, so what keeps it shut
  // for this save is no longer the gate at all — it is simply unearned: the veteran has never played
  // The Surf, and the retroactive chain in loadMeta only opens a rung whose predecessor was BEATEN.
  // Asserting it still reads false is therefore worth more than before, not less: it is now proving
  // the ladder, where it used to prove the gate.
  const vetBlob = () => ({
    schema: 1, coins: 4200, shop: {}, choiceSlots: 4, runs: 137, chapter: 'beyond', lang: 'fr',
    best: { time: 300, kills: 4000 },
    chapters: { beyond: { unlocked: true, maxDifficulty: 5, difficulty: 5, won: 5 } },
  })

  // (o.1) THE VETERAN IS LET IN, with no dev flag: this is ship day for everyone who already
  // finished Book 1. Grant, purse and opener, off a save written before Undertow existed.
  const notDev = loadMetaFrom(vetBlob())
  assert.strictEqual(notDev.grants?.undertow, true, 'a Beyond win at 3+ already in the save grants Undertow on load, with no dev flag')
  assert.strictEqual(bookMeta(notDev, 'undertow').coins, 100, 'the veteran is paid the welcome purse exactly once')
  assert.strictEqual(notDev.chapters.surf?.unlocked, true, 'The Surf unlocks retroactively — a player who beat Book 1 must not open ship day to nothing')
  // …and the gate is still there, one rung lower. This is the half that keeps the release scoped.
  assert.ok(!notDev.chapters.shelf?.unlocked, 'The Shelf must stay shut — opening a Book opens its first rung, never its second')
  assert.strictEqual(chapterAvailable(notDev, 'shelf'), false, 'and it is not reachable by any route a non-dev save has')

  // (o.1a2) THE SHELF'S OWN SHIP DAY, and the gate the owner named for it: "finishing 2.1 at
  // difficulty 3". The Surf has been live for several releases, so a real save can already hold a
  // qualifying win — and endRun could not have acted on it, because the chapter it unlocks did not
  // exist when that run ended. The retroactive chain in loadMeta is the only thing that opens it,
  // and it reads maxDifficulty (a d3 win raises it to 4) rather than `won`. Without this assertion
  // the reveal passes every other check in this file and still greets its actual audience — the
  // people who played 2.1 — with a locked volume they can only open by replaying a chapter they
  // have already beaten.
  const surfVet = loadMetaFrom({
    ...vetBlob(),
    chapters: {
      beyond: { unlocked: true, maxDifficulty: 5, difficulty: 5, won: 5 },
      surf: { unlocked: true, maxDifficulty: 4, difficulty: 3, won: 3 },
    },
  })
  assert.strictEqual(surfVet.chapters.shelf?.unlocked, true,
    'a d3 Surf win already in the save must open The Shelf on load — endRun could not, the chapter did not exist yet')
  assert.strictEqual(chapterAvailable(surfVet, 'shelf'), true, 'and it must be reachable, with no dev flag')
  // The rung below it does NOT come along: one qualifying win opens exactly one chapter, and The
  // Reef is still gated besides. Without this the assertion above would also pass if the chain
  // simply unlocked the whole ladder.
  assert.ok(!surfVet.chapters.reef?.unlocked, 'The Reef must not ride in on The Shelf\'s unlock')
  // A d2 Surf win is NOT enough — this is the threshold itself, and it is the half that a chain
  // unlocking on "has an entry" rather than on maxDifficulty would silently pass.
  const surfShort = loadMetaFrom({
    ...vetBlob(),
    chapters: {
      beyond: { unlocked: true, maxDifficulty: 5, difficulty: 5, won: 5 },
      surf: { unlocked: true, maxDifficulty: 3, difficulty: 2, won: 2 },
    },
  })
  assert.ok(!surfShort.chapters.shelf?.unlocked, 'a d2 Surf win is below CHAPTER_UNLOCK_DIFFICULTY and must open nothing')

  // (o.1b) A save that never finished Book 1 gets nothing, gate or no gate — the unlock is EARNED,
  // and without this the assertion above would also pass if unlockBook simply granted unconditionally.
  const unfinished = loadMetaFrom({ schema: 1, coins: 0, shop: {}, runs: 3, chapter: 'body', best: {}, chapters: { body: { unlocked: true, maxDifficulty: 2, won: 1 } } })
  assert.ok(!unfinished.grants?.undertow, 'a save that never beat The Beyond at 3+ is granted nothing')
  assert.ok(!unfinished.chapters.surf?.unlocked, 'and The Surf stays locked for it')

  // (o.2) WITH DEV ON, the same chain fires, exactly once, and is idempotent across reloads.
  const vetDev = vetBlob(); vetDev.dev = true
  const loaded = loadMetaFrom(vetDev)
  assert.strictEqual(loaded.grants?.undertow, true, 'a Beyond win at 3+ already in the save grants Undertow on load (dev)')
  assert.strictEqual(bookMeta(loaded, 'undertow').coins, 100, 'the retroactive grant pays exactly once')
  assert.strictEqual(loaded.chapters.surf?.unlocked, true, "Undertow's first chapter unlocks retroactively")
  // Idempotent across loads — the flag, not the purse, is what stops the second payout.
  bookMeta(loaded, 'undertow').coins = 0
  const twice = loadMetaFrom(loaded)
  assert.strictEqual(bookMeta(twice, 'undertow').coins, 0, 'reloading must not re-grant')

  // A dev player who never finished book 1 gets nothing — isolates the difficulty-threshold gate
  // from the WIP gate (dev is already on here, so only the "beaten at 3+" fact is under test).
  const rookie = { schema: 1, coins: 0, shop: {}, runs: 3, dev: true, chapters: { body: { unlocked: true, maxDifficulty: 2, difficulty: 1, won: 1 } } }
  const r = loadMetaFrom(rookie)
  assert.ok(!r.grants?.undertow, 'a player who has not beaten the finale at 3+ gets no grant')
  assert.ok(!r.chapters.surf?.unlocked, 'and no Undertow unlock')

  // (p) RULING B — meta.lightThief (Book 1-shaped legacy, design doc §1) copies forward ONCE into
  // its new home, bookMeta(m,'undertow').unlocks.lightThief. BOTH ARE DEAD DATA since v7.x removed
  // Scavenger, and the migration is guarded anyway: R2 makes it part of the save's SHAPE, so a save
  // that survived a downgrade-then-upgrade must come back the same shape as one that did not. The
  // old field must survive untouched (R2: never delete a meta field), and the run must be unchanged
  // by the flag — a copied-forward unlock that still granted something would be a removed mechanic
  // reachable by exactly the oldest saves, which are the ones nobody plays on.
  const thiefBlob = {
    schema: 1, coins: 10, shop: {}, runs: 5, dev: true, lightThief: true,
    chapters: { body: { unlocked: true, maxDifficulty: 1, difficulty: 1, best: { time: 0, kills: 0 } } },
  }
  const withThief = loadMetaFrom(thiefBlob)
  assert.strictEqual(bookMeta(withThief, 'undertow').unlocks.lightThief, true,
    "a top-level lightThief:true copies forward into bookMeta(m,'undertow').unlocks.lightThief on load")
  assert.strictEqual(withThief.lightThief, true, 'the OLD field must survive untouched (R2 — never delete a meta field)')
  const thiefRun = createRun(withThief, { chapter: 'surf' })
  assert.ok(!('killRefill' in thiefRun),
    'run.killRefill went with Scavenger (v7.x) — a run must carry no dead field, and the copied-forward flag must grant nothing')

  // FINDING 2 (review, 2026-08-16): the `=== undefined` guard has no coverage of its own reason
  // to exist — a mutation deleting it would still pass everything above, because nothing here
  // ever gives the NEW location a value first. Set it explicitly (a sacrificed-away unlock, or a
  // future build writing false directly), reload with the OLD field still true, and prove the
  // copy does not re-fire and stomp it.
  bookMeta(withThief, 'undertow').unlocks.lightThief = false
  const reloaded = loadMetaFrom(withThief)
  assert.strictEqual(reloaded.lightThief, true, 'precondition: the old field is still true going into this reload')
  assert.strictEqual(bookMeta(reloaded, 'undertow').unlocks.lightThief, false,
    'once the new location holds an explicit value, the forward-copy must never re-fire and overwrite it')

  // (q) FINDING 1 (review, 2026-08-16) — endRun's book-finale wiring lives entirely in main.js,
  // which this suite cannot import (no DOM/Pixi), so nothing above would notice a regression to
  // the old `!next` gate (which also fires for The Blank), a dropped unlockBook call, or a coin
  // bank reverted to a bare `meta.coins +=` (which silently credits every book's earnings to
  // book 1's purse). Same source-text trick as run UG.k (render.js hooks): read the function as
  // TEXT and assert the wiring is actually present, not just declared and unused — nextBook,
  // imported above, had exactly that problem until this block existed.
  {
    const src = readFileSync(new URL('../src/main.js', import.meta.url), 'utf8')
    const start = src.indexOf('function endRun(victory) {')
    assert.ok(start > 0, 'main.js must still declare function endRun(victory) — this block reads it as text')
    const end = src.indexOf('\n}\n', start)
    assert.ok(end > start, 'could not find the end of endRun')
    const body = src.slice(start, end)

    assert.ok(/\bisBookFinale\(run\.chapter\)/.test(body),
      `endRun must gate the book-unlock branch on isBookFinale(run.chapter), not a bare "!next" check — that is ALSO true of The Blank (see isBookFinale in config.js). endRun currently reads:\n${body}`)
    assert.ok(/\bunlockBook\(meta, nb\)/.test(body),
      `endRun's book-finale branch must actually call unlockBook(meta, nb) — the isBookFinale gate is dead without it. endRun currently reads:\n${body}`)
    assert.ok(/ensureBookMeta\(meta, bookOf\(run\.chapter\)\s*\?\?\s*BOOK_ORDER\[0\]\)\.coins\s*\+=\s*earned/.test(body),
      `endRun must bank the run's coins through ensureBookMeta(meta, bookOf(run.chapter) ?? BOOK_ORDER[0]).coins += earned, or a Book 2 run's earnings silently land in meta.coins (book 1's purse). endRun currently reads:\n${body}`)
    // The regression this whole block exists to catch: reverting the bank to the old
    // direct-mutation form. A bare `meta.coins +=` anywhere in endRun is that regression,
    // whether it replaces the ensureBookMeta line above or merely sits beside it.
    const bareBank = body.split('\n').filter((l) => /meta\.coins\s*\+=/.test(l))
    assert.deepStrictEqual(bareBank, [],
      `endRun must not bank coins with a bare "meta.coins +=" — that credits every book's earnings to book 1's purse. Offending line(s):\n${bareBank.join('\n')}`)

    // The BADGE (v7.x). Two halves, each of which fails silently and independently: a return
    // value that is never captured announces nothing, and a captured flag that never reaches
    // showScreen also announces nothing. Gating on unlockBook's return (rather than on `nb`) is
    // the part that matters — grantBook's monotone meta.grants flag makes the second finale
    // return false, so an unconditional assignment would re-announce the book on every replay.
    assert.ok(/if \(nb && unlockBook\(meta, nb\)\) unlockedBook = nb/.test(body),
      `endRun must gate unlockedBook on unlockBook's RETURN value — assigning it from a bare "if (nb)" re-announces the book every time the finale is replayed. endRun currently reads:\n${body}`)
    assert.ok(/^\s*unlockedBook,\s*$/m.test(body),
      `endRun must forward unlockedBook in the showScreen('summary') payload — captured and not forwarded renders no badge at all. endRun currently reads:\n${body}`)
  }

  // (q2) The badge's other three files. The table, the renderer and the stylesheet have no import
  // between them, which is the 28%-of-all-defects shape this suite lints as source text.
  {
    const uiSrc = readFileSync(new URL('../src/ui.js', import.meta.url), 'utf8')
    assert.ok(/BOOK_UNLOCK_LINES\[d\.unlockedBook\]/.test(uiSrc),
      'ui.js must read BOOK_UNLOCK_LINES[d.unlockedBook] — a payload field nothing renders is exactly the silent grant this badge exists to end')
    assert.ok(/summary-unlock--book/.test(uiSrc), 'the badge must carry the .summary-unlock--book class')
    const css = readFileSync(new URL('../src/styles.css', import.meta.url), 'utf8')
    assert.ok(/\.summary-unlock--book\s*\{/.test(css),
      '.summary-unlock--book needs a CSS rule of its own — .summary-unlock--hidden shipped without one and silently inherited the mint DIFFICULTY accent, which nobody noticed')

    // Every book you can ARRIVE at needs a row. BOOK_ORDER[0] is where you start, so nothing
    // unlocks it. A missing row renders NO badge (ui.js has no fallback string on purpose —
    // a half-translated announcement is worse than the silence it replaced), so this must be an
    // assert rather than a default.
    const arrivable = BOOK_ORDER.slice(1)
    assert.ok(arrivable.length > 0, 'no arrivable book, so this sweep cannot show its denominator responds to anything')
    for (const id of arrivable) {
      assert.ok(BOOK_UNLOCK_LINES[id], `BOOK_UNLOCK_LINES missing '${id}' — unlocking it would announce nothing`)
      assert.ok(/\{n\}/.test(BOOK_UNLOCK_LINES[id]),
        `BOOK_UNLOCK_LINES.${id} must state the welcome purse through the {n} TEMPLATE, never a baked-in number — the English string IS the translation key, so a literal 100 orphans the French the day startCoins is retuned`)
    }
    assert.deepStrictEqual(Object.keys(BOOK_UNLOCK_LINES).filter((id) => !arrivable.includes(id)), [],
      'BOOK_UNLOCK_LINES has a row for a book nothing can unlock — dead copy that run XX will still demand French for')
    console.log(`PASS run BP.q2 (book-unlock badge): ${arrivable.length} arrivable book(s) [${arrivable.join(' ')}] all have a {n} line, wired through main.js -> ui.js -> styles.css`)
  }

  // (q3) The two places a BOOK is a thing the player can see and choose. Both are source-text
  // lints because the suite can import neither ui.js nor styles.css, and both guard a failure that
  // is SILENT on screen rather than a throw.
  {
    const uiSrc = readFileSync(new URL('../src/ui.js', import.meta.url), 'utf8')
    const css = readFileSync(new URL('../src/styles.css', import.meta.url), 'utf8')

    // The shop is one screen serving one shop PER BOOK — separate purse, separate levels, and
    // Undertow has three lines book 1 does not. Until v7.x the only sign of that was the book's
    // name in grey text, and the only way to change books was to leave, tap a spine and come back.
    assert.ok(/data-book="\$\{s\.book\}"/.test(uiSrc),
      'the shop header must emit a data-book tab per book — without it the screen silently serves whichever book the title carousel last settled on, with no way to switch and nothing saying which')
    assert.ok(/if \(el\.dataset\.book !== undefined\)/.test(uiSrc),
      'a data-book tab with no click branch is a button that does nothing — the tabs would render and the shop would never change')
    assert.ok(/const books = titleBookshelf\(meta\)\.filter\(/.test(uiSrc),
      'the tabs must come from titleBookshelf, not BOOK_ORDER — that is the one place the WIP gate lives, and a tab for a book whose shelf is hidden announces the book the shelf is careful not to')
    // The tab must not persist meta.chapter: switching purses to compare prices is browsing.
    const tabBranch = uiSrc.slice(uiSrc.indexOf("if (el.dataset.book !== undefined)"), uiSrc.indexOf("if (el.dataset.book !== undefined)") + 500)
    assert.ok(!/hooks\.onChapter/.test(tabBranch),
      'the shop book tab must not call onChapter — comparing two books\' prices would overwrite the chapter you last chose to PLAY, moving the ribbon on the shelf behind your back')
    assert.ok(/\.book-tab\s*\{/.test(css) && /\.book-tab--on\s*\{/.test(css),
      'the book tabs need both a rule and a selected rule — with only one, every book looks equally current and the tab strip says nothing')

    // A clipped shelf and a short shelf look identical. What overflows first is a shelf-board's
    // brass plate, which is the ONLY place a Book's name and star total are written — that is the
    // bug this pair was written for (Book 2 sat unlabelled below the fold on a 410x745 phone).
    assert.ok(/bc\.scrollHeight - bc\.clientHeight > 2/.test(uiSrc),
      'the bookcase fade must be toggled from a MEASUREMENT — gating it on the number of books was wrong at both ends: two books overflow a 375x667 phone with no fade, three fit a tall screen and would get one over nothing')
    assert.ok(/addEventListener\('resize', markBookcaseScroll\)/.test(uiSrc),
      'the fade must be re-measured on resize — rotation changes the answer and nothing else re-renders the title')
    assert.ok(/\.bookcase--more\s*\{/.test(css), '.bookcase--more has no rule, so the class toggles nothing and the shelf clips silently again')
    assert.ok(/scroll-snap-align: end/.test(css),
      'the etage must snap on its END — a shelf snapped by its top parks its brass plate under the fold, which is the exact thing being fixed')

    // The panel is a SPREAD. Stacked it was 255px of a 745px phone and the case overflowed by 33.
    assert.ok(/class="page page--verso"/.test(uiSrc) && /class="page page--recto"/.test(uiSrc),
      'titleBelowHtml must render two pages — the stacked panel is what pushed the second shelf out of the case')
    assert.ok(/\.page--recto \.diff-pip \{[^}]*flex: 1 1 0/.test(css),
      'the difficulty pips must DIVIDE the recto rather than be sized in px — a fixed 34px pip is 170px of a 168px page, and five of them wrapped the panel TALLER than the stack it replaced')

    // TWO CSS CUSTOM PROPERTIES, EACH AUTHORED IN ui.js AND READ IN styles.css. No import joins
    // them, and each has a var() FALLBACK, so a broken half is not a blank screen or a throw —
    // it is a plausible-looking screen with the wrong number in it.
    //
    // --shelves is the shelf-row height DIVISOR. Dropped from the markup it falls back to 1, and
    // two Books get a one-Book row height — 290px each, which overflows a 390x844 phone and parks
    // Book 2's brass plate under the fold, the exact bug the fade assertions above exist for.
    assert.ok(/--shelves:\$\{shelves\.length\}/.test(uiSrc),
      'bookcaseHtml must publish --shelves from the ETAGE COUNT — a hardcoded number (or none, falling back to 1) sizes every Book count as though it were one, and two Books then overflow the phone silently')
    assert.ok(/calc\(38vh \/ var\(--shelves, 1\)\)/.test(css),
      '.shelf-row height must divide by var(--shelves) — a flat vh is what left ONE Book standing in ~310px of bare desk with spines a third the height of their own shelf')
    // --shop-pct is the completion meter's fill. Missing, it falls back to 0% and every save on
    // earth reads "empty shop" next to a number saying otherwise.
    assert.ok(/style="--shop-pct:\$\{pct\}%"/.test(uiSrc),
      'the Shop door must publish --shop-pct — without it the meter falls back to 0% and reads "nothing bought" on a maxed save, beside a percentage that disagrees')
    assert.ok(/width: var\(--shop-pct, 0%\)/.test(css),
      'the meter fill must read var(--shop-pct) — a fixed width is a bar that never moves, which looks exactly like a shop you cannot make progress in')

    // The title screen's ONLY balance is on the Shop door, and it is the book's purse plus the
    // book's completion — that pair is the only thing on the screen saying WHICH shop it is.
    // Losing either half leaves a button labelled "Shop" and nothing else, which is where it
    // started.
    const doorBlock = uiSrc.slice(uiSrc.indexOf('class="btn btn--shop"'), uiSrc.indexOf('class="btn btn--shop"') + 400)
    assert.ok(/shop-btn-purse/.test(doorBlock) && /shop-btn-meter/.test(doorBlock),
      'the Shop door must carry BOTH the purse and the completion meter — they are the whole of what ties it to the book on screen')
    assert.ok(/\.shop-btn-meter i::after\s*\{/.test(css),
      '.shop-btn-meter needs its fill rule — the track alone renders as a permanently empty groove')
    assert.ok(!/class="coins-badge" data-act/.test(uiSrc),
      'the title header must not carry a coins badge as well — two balances for one purse is what moving it onto the door was for')

    console.log('PASS run BP.q3 (book navigation): shop book tabs gated by titleBookshelf and browse-only, bookcase fade measured not counted, 2-page spread with flex pips, --shelves + --shop-pct both authored and read')
  }

  // (q4b) EVERY CONFIG CONSTANT ui.js USES IS ACTUALLY IMPORTED. ui.js cannot be imported by this
  // suite (it needs a DOM), so a bare identifier in it is a ReferenceError nothing here can see —
  // and the symptom is not a blank page: renderShop throws, showScreen's switch never completes,
  // and the PREVIOUS screen stays up. That reads exactly like "the button did nothing". It happened
  // for real building this shop: SACRIFICE_COSTS was dropped from the import list while moving
  // arithmetic to state.js, the suite stayed green, and the Shop silently would not open.
  {
    const uiSrc = readFileSync(new URL('../src/ui.js', import.meta.url), 'utf8')
    // Everything ui.js brings in, from any module...
    const imported = new Set()
    for (const m of uiSrc.matchAll(/import \{([^}]+)\} from/g)) {
      for (const name of m[1].split(',')) imported.add(name.trim().split(/\s+as\s+/).pop())
    }
    // ...plus anything it declares itself, at any scope (SCREEN_NAMES, CAST_ART, DEV_TAPS_TO_OPEN…).
    for (const m of uiSrc.matchAll(/(?:const|let|var|function)\s+([A-Z][A-Z0-9_]{2,})\b/g)) imported.add(m[1])
    // ...and destructured locals, which is how a few config tables are unpacked.
    for (const m of uiSrc.matchAll(/(?:const|let)\s*\{([^}]+)\}\s*=/g)) {
      for (const name of m[1].split(',')) imported.add(name.trim().split(':').pop().trim())
    }
    // CONSTANT_CASE only: those are the config imports, and a lowercase helper would drown this in
    // false positives from properties and locals. Strip strings and comments first — a CONSTANT_CASE
    // word inside a comment or a translated string is not a reference.
    const code = uiSrc
      .replace(/\/\*[\s\S]*?\*\//g, ' ')
      .replace(/\/\/[^\n]*/g, ' ')
      .replace(/'(?:[^'\\\n]|\\.)*'/g, "''")
      .replace(/"(?:[^"\\\n]|\\.)*"/g, '""')
      .replace(/`(?:[^`\\]|\\.)*`/g, '``')
    const used = new Set()
    for (const m of code.matchAll(/(^|[^.\w$'"])([A-Z][A-Z0-9_]{2,})\b/gm)) used.add(m[2])
    const missing = [...used].filter((n) => !imported.has(n) && !(n in globalThis)).sort()
    assert.deepStrictEqual(missing, [],
      `ui.js references these CONSTANT_CASE names without importing or declaring them — each is a ReferenceError that leaves the previous screen on display instead of throwing visibly:\n${missing.join(', ')}`)
    assert.ok(used.size > 30, `only ${used.size} CONSTANT_CASE references found in ui.js — the scan is broken, not the code`)
    console.log(`PASS run BP.q4b (ui.js constants): all ${used.size} CONSTANT_CASE references resolve to an import or a local declaration`)
  }

  // (q5) THE SHOP DOOR'S COMPLETION METER. bookProgress counts UPGRADE LEVELS, and the whole reason
  // it lives in state.js is so this block can call it — the same arithmetic inside ui.js had no
  // guard at all. Sacrifices are the interesting half: they are paid in shop LEVELS, so buying one
  // DELETES levels out of bm.shop, and a meter that credited only the denominator would run
  // backwards at the exact moment the player made progress.
  {
    const maxedShop = (bookId) => Object.fromEntries(Object.keys(shopLines(bookId)).map((id) => [id, lineMax(id)]))
    const sacTotal = SACRIFICE_COSTS.reduce((a, b) => a + b, 0)

    // The denominator, stated per book, so a config change that silently moves the meter is visible
    // here rather than on a phone. It is LEVELS, not lines: a line is worth its own depth.
    for (const bookId of BOOK_ORDER) {
      const lines = Object.keys(shopLines(bookId)).length
      const unlocks = Object.entries(BOOK_UNLOCKS[bookId] ?? {})
      const unlockTotal = unlocks.reduce((sum, [, u]) => sum + u.costs.reduce((a, b) => a + b, 0), 0)
      const levelTotal = Object.keys(shopLines(bookId)).reduce((sum, id) => sum + lineMax(id), 0)
      const expect = levelTotal + sacTotal + unlockTotal
      const fresh = { shop: {}, choiceSlots: 2, unlocks: {} }
      assert.strictEqual(bookProgress(fresh, bookId).total, expect,
        `${bookId}: the denominator must be every buyable LEVEL — ${levelTotal} across ${lines} lines (summed per line: a line may sell fewer than MAX_SHOP_LEVEL) + ${sacTotal} card-slot levels + ${unlockTotal} unlock levels = ${expect}. Counting LINES instead of levels reads 8/80 as "8 of 8 things"; counting every line at the GLOBAL cap prints a denominator no player can reach.`)
      assert.strictEqual(bookProgress(fresh, bookId).pct, 0, `${bookId}: a fresh book must read 0%`)

      // Spent out means spent out: every line maxed, every card slot, every unlock rung.
      const done = {
        shop: maxedShop(bookId),
        choiceSlots: MAX_CHOICE_SLOTS,
        unlocks: Object.fromEntries(unlocks.map(([id]) => [id, unlockMax(bookId, id)])),
      }
      assert.strictEqual(bookProgress(done, bookId).pct, 100,
        `${bookId}: a save with every line maxed, both card slots and every unlock rung must read exactly 100% — it reads ${bookProgress(done, bookId).pct}%`)

      // ...and nothing reads past it. Held by the ladder ITERATION rather than by a clamp — a
      // mutation test proved the clamp that used to be here could not fail, because the forEach
      // over SACRIFICE_COSTS already bounds which rungs can be credited. Asserted anyway: the
      // property is what matters, and the next edit to that loop is what would break it.
      const tampered = { ...done, choiceSlots: MAX_CHOICE_SLOTS + 7 }
      assert.strictEqual(bookProgress(tampered, bookId).pct, 100,
        `${bookId}: choiceSlots beyond the ladder must clamp — it reads ${bookProgress(tampered, bookId).pct}%`)
    }

    // THE MONOTONE PROPERTY, which is the assertion this block exists for. Buy exactly the 3rd
    // slot's price in levels, then spend them on the slot: the levels vanish from bm.shop and the
    // percentage must NOT fall.
    const price = SACRIFICE_COSTS[0]
    const ids = Object.keys(shopLines('book1'))
    const saved = {}
    let left = price
    for (const id of ids) { const take = Math.min(lineMax(id), left); if (take > 0) saved[id] = take; left -= take }
    assert.strictEqual(left, 0, `could not stage ${price} levels across ${ids.length} book 1 lines — the fixture is broken, not the code`)
    const before = bookProgress({ shop: saved, choiceSlots: 2, unlocks: {} }, 'book1').pct
    const after = bookProgress({ shop: {}, choiceSlots: 3, unlocks: {} }, 'book1').pct
    assert.ok(before > 0, `the pre-sacrifice fixture reads 0% — ${price} levels should move the meter, so this comparison would prove nothing`)
    assert.strictEqual(after, before,
      `SACRIFICING MUST NOT LOSE PROGRESS: ${price} levels bought reads ${before}%, and spending them on the 3rd card slot reads ${after}%. The levels are gone from bm.shop, so the thing they bought has to be credited back — otherwise the meter runs backwards on a purchase.`)

    // The same for a BOOK_UNLOCKS rung, which is the book-specific ladder and a different branch.
    //
    // UNEXERCISED WHILE THE TABLE IS EMPTY (v7.x removed Scavenger, its only ever row). bookProgress
    // credits unlocks by iterating BOOK_UNLOCKS[bookId], so with no rows there is no rung to buy and
    // nothing to credit back. Guarded and REPORTED in the PASS line rather than deleted, for both of
    // this repo's own reasons: the branch is live code the next unlock walks straight into, and a
    // check that silently skips reads exactly like a check that passed.
    const [uid] = Object.keys(BOOK_UNLOCKS.undertow ?? {})
    let unlockNote = 'BOOK_UNLOCKS empty, unlock-ladder branch UNEXERCISED'
    if (uid) {
      const rung = unlockCost('undertow', uid, 0)
      const uSaved = {}
      let uLeft = rung
      for (const id of Object.keys(shopLines('undertow'))) { const take = Math.min(lineMax(id), uLeft); if (take > 0) uSaved[id] = take; uLeft -= take }
      const uBefore = bookProgress({ shop: uSaved, choiceSlots: 2, unlocks: {} }, 'undertow').pct
      const uAfter = bookProgress({ shop: {}, choiceSlots: 2, unlocks: { [uid]: 1 } }, 'undertow').pct
      assert.strictEqual(uAfter, uBefore,
        `buying ${uid}'s first rung (${rung} levels) must not lose progress either: ${uBefore}% -> ${uAfter}%`)
      // A legacy `true` unlock (a save from before the ladder) owns the TOP rung, not one.
      const legacy = bookProgress({ shop: {}, choiceSlots: 2, unlocks: { [uid]: true } }, 'undertow')
      const allRungs = bookProgress({ shop: {}, choiceSlots: 2, unlocks: { [uid]: unlockMax('undertow', uid) } }, 'undertow')
      assert.strictEqual(legacy.owned, allRungs.owned,
        `a pre-ladder \`${uid}: true\` save must be credited the whole ladder (${allRungs.owned} levels), not one rung — it got ${legacy.owned}`)
      unlockNote = `${rung} levels -> ${uid} holds at ${uBefore}%`
    }

    const totals = BOOK_ORDER.map((b) => `${b} ${bookProgress({ shop: {}, choiceSlots: 2, unlocks: {} }, b).total}`).join(', ')
    console.log(`PASS run BP.q5 (shop completion meter): denominators in LEVELS [${totals}], fresh 0% and spent-out exactly 100% for ${BOOK_ORDER.length} books, an over-count of slots reads no higher, and a sacrifice is monotone (${price} levels -> 3rd slot holds at ${before}%; ${unlockNote})`)
  }

  // (q4) EVERY DOOR HAS A HANDLER, AND EVERY SCREEN HAS A DOOR. Deleting the bottom nav (v7.x)
  // deleted the only route into the Shop and the only way back out of the pre-run brief; both
  // failures are a button that does nothing or a screen you cannot leave, and neither throws.
  // Nothing in the suite could see the nav — it had zero assertions of its own — so it went.
  {
    const uiSrc = readFileSync(new URL('../src/ui.js', import.meta.url), 'utf8')
    const css = readFileSync(new URL('../src/styles.css', import.meta.url), 'utf8')

    // The general form: every literal data-act the markup emits must have a case in the one
    // delegated click handler. `${act}` is the save-slot rows' computed value — its two real
    // values are asserted just below, since a regex cannot resolve it.
    const emitted = [...uiSrc.matchAll(/data-act="([a-z-]+)"/g)].map((m) => m[1])
    const uniq = [...new Set(emitted)].sort()
    assert.ok(uniq.length > 25, `only ${uniq.length} data-act values found — the scan is broken, not the code`)
    const handled = new Set([...uiSrc.matchAll(/case '([a-z-]+)':/g)].map((m) => m[1]))
    const orphans = uniq.filter((a) => !handled.has(a))
    assert.deepStrictEqual(orphans, [],
      `these controls emit a data-act with no case in the click delegate — each is a button that does nothing:\n${orphans.join(', ')}`)
    const slotDefault = uiSrc.match(/function slotRowHtml\(n, \{ act = '([a-z-]+)'/)?.[1]
    assert.ok(slotDefault && handled.has(slotDefault),
      `slotRowHtml's computed data-act ('${slotDefault}') has no case in the delegate — the save-slot rows would be inert, and the regex scan above cannot see a \${act} to catch it`)

    // ...and the specific doors that replaced the nav. A screen reachable by nothing is invisible.
    assert.ok(/data-act="shop"/.test(uiSrc), 'nothing opens the Shop — the bottom nav was its only route and it is gone')
    assert.ok(/data-act="shop-close"/.test(uiSrc), 'nothing closes the Shop — the nav used to be the way back to the shelf')
    assert.ok(/data-act="brief-back"/.test(uiSrc), 'the pre-run brief has no way out — it leaned on the nav, which is gone, and nothing is spent yet so it MUST be escapable')
    // Matched on a declaration the BASE rule owns, not on the selector: `.btn--shop` appears twice
    // (the rule, and the narrow-screen override that drops the label), so a bare selector test is
    // satisfied by the override alone and a deleted base rule walks straight past it.
    assert.ok(/\.btn--shop \{[^}]*background:/.test(css),
      '.btn--shop has no base rule, so the Shop door renders as an unstyled button on the volume cover')

    // The nav is really gone, in both files. A leftover rule is dead weight; leftover markup is a
    // bar with no handler.
    for (const [name, src] of [['ui.js', uiSrc], ['styles.css', css]]) {
      assert.ok(!/menu-nav|nav-tab/.test(src), `${name} still references the deleted bottom nav`)
    }
    // The Daily went with it — a mode with no entry point is dead code that still has to be read.
    assert.ok(!/dailyChapter|dailyMutators|todayKey/.test(uiSrc), 'ui.js still calls a deleted daily export — that is a ReferenceError at render time, not a lint')
    console.log(`PASS run BP.q4 (doors): ${uniq.length} data-act values all handled, Shop opens + closes, brief escapable, no nav or daily left in ui.js/styles.css`)
  }

  // (r) nextBook was imported for the finding above and had NO direct coverage of its own —
  // main.js's usage of it was the only thing exercising it, and that is exactly the invisible
  // path (q) exists to guard. Prove the import earns its place on its own terms.
  assert.strictEqual(nextBook('book1'), 'undertow', "nextBook('book1') === 'undertow'")
  assert.strictEqual(nextBook('undertow'), null, "nextBook('undertow') === null — Undertow is the last shipped book")
  assert.strictEqual(nextBook('nope'), null, 'nextBook of an id no book claims === null')
  // FINAL FIX ROUND, FIX 5 — unlockBook is exported and used `BOOKS[bookId].chapters[0]` with no
  // guard against an id absent from BOOKS, which would throw reading .chapters off undefined. The
  // per-chapter gate made this MORE load-bearing, not less: unlockBook now asks isWipChapter about
  // the book's first chapter, and for an unclaimed id that first chapter is undefined — so the
  // falsy-`first` refusal has to come before the gate, not after it. Must refuse, not crash.
  {
    const um = makeMeta(); um.chapters = {}
    assert.strictEqual(unlockBook(um, 'nope'), false, 'unlockBook of an id no book claims must return false, not throw')
  }

  // (s) OLD-BUILD COMPATIBILITY. The entire architecture is "additive, so no migration". This is
  // the assertion that says so. Rev 1 of the spec moved book 1's fields into meta.books and
  // deleted the originals; today's shipped loadMeta reading such a save produced runs 137 -> 0,
  // The Beyond unlocked -> LOCKED, fr -> en, name erased — and saveMeta then wrote that over the
  // slot. Reachable by a revert, a tab open from before the deploy, an un-updated device pushing
  // its blob, or sw.js's offline shell booting a cached bundle.
  const rev2Save = {
    schema: 1, runs: 137, chapter: 'beyond', lang: 'fr', name: 'Main',
    coins: 4200, shop: { damage: 10, fireRate: 10, maxHP: 10 }, choiceSlots: 4,
    best: { time: 300, kills: 4000 },
    chapters: { beyond: { unlocked: true, maxDifficulty: 5, difficulty: 5, won: 5 } },
    unlocks: {}, grants: { undertow: true },
    books: { undertow: { coins: 100, shop: { damage: 3, slowBurn: 2 }, choiceSlots: 2, unlocks: { lightThief: true } } },
  }
  // (s1) Book 1 is exactly where an old build looks for it.
  for (const f of ['coins', 'choiceSlots', 'shop']) {
    assert.ok(Object.hasOwn(rev2Save, f), `top-level '${f}' must still exist — R2 forbids moving it`)
  }
  const back = loadMetaFrom(rev2Save)
  assert.strictEqual(back.coins, 4200, "book 1's coins survive a load")
  assert.strictEqual(back.runs, 137, 'runs survive')
  assert.strictEqual(back.lang, 'fr', 'language survives')
  assert.strictEqual(back.chapters.beyond.unlocked, true, 'chapter unlocks survive')
  assert.strictEqual(back.shop.damage, 10, "book 1's shop levels survive")
  // (s2) And book 2's state survives a round trip through a build that knows nothing about it.
  assert.strictEqual(back.books.undertow.coins, 100, "book 2's purse survives")
  assert.strictEqual(back.books.undertow.shop.slowBurn, 2, "book 2's own shop line survives")
  assert.strictEqual(back.books.undertow.unlocks.lightThief, true, "book 2's unlock survives")
  assert.strictEqual(back.grants.undertow, true, 'the grant record survives')

  // (t) TASK 5 — main.js's purchase hooks (onBuy, onSacrifice) and ui.js's call sites must route
  // through an EXPLICIT book id, never a guess. ui.js's browseChapterId (the carousel's centred
  // card) and meta.chapter deliberately diverge — onChapter only persists for AVAILABLE chapters,
  // so a locked preview card browses without writing meta.chapter — and inside Book 1 they always
  // name the same book, so a defaulted/guessed book would work today and break silently the moment
  // a Book 2 chapter becomes a browsable preview card. main.js cannot recover browseChapterId on
  // its own (it's a `let` local inside initUI), so the id has to arrive as an explicit parameter.
  // main.js is source-text-only here (not importable — see the CLAUDE.md note on run UG.k).
  {
    const mainSrc = readFileSync(new URL('../src/main.js', import.meta.url), 'utf8')
    assert.match(mainSrc, /onBuy\s*\(\s*id\s*,\s*bookId[^)]*\)/, 'onBuy must take an explicit bookId')
    assert.match(mainSrc, /onSacrifice\s*\(\s*picks\s*,\s*target[^)]*,\s*bookId[^)]*\)/, 'onSacrifice must take an explicit bookId')
    assert.doesNotMatch(mainSrc, /meta\.shop\[/, 'main.js must not index meta.shop directly — it goes through bookMeta')
    assert.doesNotMatch(mainSrc, /meta\.coins\s*[-+]=/, 'main.js must not mutate meta.coins directly — it goes through bookMeta')

    const uiSrc = readFileSync(new URL('../src/ui.js', import.meta.url), 'utf8')
    assert.match(uiSrc, /onBuy\([^)]*,\s*shopBookId\(\)\)/, 'ui.js must pass its browsed book to onBuy')

    // (t1) The buy call site is only half the wiring — the sacrifice confirm button sits ~260
    // lines further down its own click-delegation switch, behind independent state
    // (sacrificePicks/sacrificeTarget), and is exactly as easy to leave passing the OLD 2-arg
    // call. Name it too rather than trusting the same care was applied twice.
    assert.match(uiSrc, /onSacrifice\([^)]*,\s*shopBookId\(\)\)/, 'ui.js must pass its browsed book to onSacrifice')

    // (t2) shopBookId must be DERIVED from browseChapterId (the carousel state), not meta.chapter —
    // that distinction is the entire reason this hook signature exists (see the brief's own
    // rationale, above). A version reading meta.chapter instead would satisfy every assertion
    // above, compile, and pass every existing scenario (they never browse Book 2 without also
    // persisting it) while silently reintroducing the exact bug this task exists to close.
    assert.match(uiSrc, /shopBookId\s*=\s*\(\)\s*=>\s*bookOf\(browseChapterId\)\s*\?\?\s*BOOK_ORDER\[0\]/,
      'shopBookId must resolve from browseChapterId, not meta.chapter — a book resolved off meta.chapter would silently diverge from the badge the player is actually looking at')

    // (t3) RULING G — a BOOK_UNLOCKS purchase (e.g. Light Thief) must write ONLY
    // bookMeta(meta,bookId).unlocks[target], never mirrored back to the legacy top-level
    // meta.lightThief. Without this, a same-session Light Thief purchase would not reach
    // createRun's killRefill (which reads bm.unlocks.lightThief since Task 2) until a reload —
    // the concern Task 3's implementer carried forward into this task.
    assert.doesNotMatch(mainSrc, /meta\.lightThief\s*=\s*true/,
      'onSacrifice must never write the legacy top-level meta.lightThief again (ruling G) — the unlock goes through bookMeta(meta,bookId).unlocks[target] only')
    // The LEVEL, not `true`: unlocks are ladders now (BOOK_UNLOCKS[].costs), and writing `true`
    // would jump a part-bought ladder straight to the top — unlockLevel reads `true` as full, so
    // buying rung 1 would silently hand over rungs 2 and 3 as well. Ruling G is unchanged: the
    // write still goes to bm.unlocks[target] and nowhere else.
    assert.match(mainSrc, /\(bm\.unlocks\s*\?\?=\s*\{\}\)\[target\]\s*=\s*unlockLevel\(bm, bookId, target\) \+ 1/,
      'onSacrifice must write the next LEVEL to bm.unlocks[target] — writing `true` maxes a part-bought ladder')
  }

  // (u) TASK 6 — formatShopBonus (ui.js) must be sign-aware, not a percent-vs-flat discriminator
  // with a hardcoded '+'. Slow Burn (BOOK_SHOP.undertow.slowBurn) is the first REDUCTION line in
  // the game: stored as a POSITIVE perLevel with reduction: true, so a bare '+' would render its
  // sacrifice-view "current -> after" preview as "+-40%" — the screen where the player chooses
  // what to destroy. formatShopBonus is a private closure and cannot be called from here (ui.js is
  // not importable — no jsdom, and initUI() touches document.getElementById on its first line), so
  // this reads the function as TEXT (same idiom as run UG.k / the sacTargets block above) and pins
  // the EXACT sign expression rather than just the word "reduction" — a mutation that mentions
  // reduction while mapping the sign backwards (line.reduction ? '+' : '-') would still satisfy a
  // bare /reduction/ match, which is why this checks the whole ternary, not a keyword.
  {
    const uiSrc = readFileSync(new URL('../src/ui.js', import.meta.url), 'utf8')
    const start = uiSrc.indexOf('function formatShopBonus(bookId, id, levels) {')
    assert.ok(start > 0, 'ui.js must still declare function formatShopBonus(bookId, id, levels) {')
    const end = uiSrc.indexOf('\n}\n', start)
    assert.ok(end > start, 'could not find the end of formatShopBonus')
    const body = uiSrc.slice(start, end)
    assert.doesNotMatch(body, /`\+\$\{Math\.round\(per \* levels \* 100\)\}%`/,
      'the hardcoded + in formatShopBonus must be sign-aware')
    assert.match(body, /const sign = line\.reduction \? '-' : '\+'/,
      "formatShopBonus must map reduction:true to '-' and everything else to '+' — a backwards or missing mapping renders Slow Burn's -4%/level as a gain")
    assert.match(body, /return per < 1 \? `\$\{sign\}\$\{Math\.round\(per \* levels \* 100\)\}%` : `\$\{sign\}\$\{Math\.round\(per \* levels\)\}`/,
      'both the percent and flat branches must use the computed sign, not a bare literal')

    // Cross-check the fact the sign logic depends on: Slow Burn really is declared as reduction:true
    // with a POSITIVE perLevel in config.js (real, importable data) — if that ever flips, the sign
    // expression above stops meaning what this comment says it means.
    assert.strictEqual(shopLines('undertow').slowBurn.reduction, true, "config.js must keep slowBurn's reduction: true flag")
    assert.ok(shopLines('undertow').slowBurn.perLevel > 0, "slowBurn's perLevel must stay POSITIVE — reduction:true is what flips its sign, not a negative perLevel")
  }

  // (v) TASK 6 — .shop-rows must not hardcode 8 rows: Undertow has 11 lines (8 universal + 3 of
  // its own, see (a) above). A hardcoded repeat(8, ...) produces TWO defects, not one — overflow
  // past row 8, and a HEIGHT STEP even where it fits (only the first 8 rows are 1fr; the rest fall
  // into implicit grid-auto-rows:auto at a shorter height). The --sac variant already used the fix
  // (grid-auto-rows); the base rule must match it now, so a book's row count is never baked in.
  {
    const css = readFileSync(new URL('../src/styles.css', import.meta.url), 'utf8')
    assert.doesNotMatch(css, /grid-template-rows:\s*repeat\(8,/,
      '.shop-rows hardcodes 8 rows; Undertow has 11 and rows 9-11 fall into grid-auto-rows at a different height')
    assert.match(css, /\.shop-rows\s*\{[^}]*grid-auto-rows:\s*minmax\(max-content,\s*1fr\)/,
      '.shop-rows must grow every row uniformly via grid-auto-rows, matching how many lines shopLines(bookId) actually has')
  }

  // (w) RULING 2 (Task 6 amendment, 2026-08-16) — onBuy had NO id-validity check against
  // shopLines(bookId), unlike onSacrifice's own picks loop. That was unreachable before this task
  // (no book-specific shop line ever rendered a data-buy button); Task 6 is what makes one
  // renderable, so a crafted data-buy for e.g. 'deepLungs' while browsing book 1 must not spend
  // book 1's coins on a line book 1 does not have (shopCost resolves ids GLOBALLY, so nothing else
  // would refuse it). main.js is source-text-only here (not importable — see (t) above).
  {
    const mainSrc = readFileSync(new URL('../src/main.js', import.meta.url), 'utf8')
    const start = mainSrc.indexOf('onBuy(id, bookId = BOOK_ORDER[0]) {')
    assert.ok(start > 0, 'main.js must still declare onBuy(id, bookId = BOOK_ORDER[0]) {')
    const end = mainSrc.indexOf('\n  },\n', start)
    assert.ok(end > start, 'could not find the end of onBuy')
    const body = mainSrc.slice(start, end)
    const guardAt = body.search(/if \(!shopLines\(bookId\)\[id\]\) return false/)
    assert.ok(guardAt >= 0,
      'onBuy must refuse an id absent from shopLines(bookId) — the same style onSacrifice already uses for its own picks')
    const spendAt = body.search(/bm\.coins\s*-=\s*cost/)
    assert.ok(spendAt >= 0, 'precondition: onBuy must still spend coins somewhere in its body')
    assert.ok(guardAt < spendAt, 'the id-validity guard must run BEFORE coins are spent, or an invalid id still costs the player')
  }

  // (x) FIX ROUND (2026-08-16, owner-supplied French) — French coverage for the book-specific
  // tables, walked NESTED rather than flat. run XX's own config-table walk does
  // `for (const v of Object.values(table)) need(v?.name)`, which is exactly the WEAPON_MODS hole
  // it documents eight lines below itself: pointed at BOOK_SHOP or BOOK_UNLOCKS (both keyed by
  // book id, THEN by line/unlock id — two levels deep, same shape as WEAPON_MODS[weaponId][modId])
  // it yields the per-book dicts, whose own .name/.desc are undefined, and a `need()`-style helper
  // silently skips undefined. That is a green coverage assert that covers nothing for either
  // table — this walk is written explicitly nested so it cannot fall into that hole.
  for (const [bookId, table] of Object.entries(BOOK_SHOP)) {
    for (const [id, line] of Object.entries(table)) {
      assert.ok(FR[line.name], `BOOK_SHOP.${bookId}.${id}.name ('${line.name}') has no French`)
      assert.ok(FR[line.desc], `BOOK_SHOP.${bookId}.${id}.desc ('${line.desc}') has no French`)
    }
  }
  // BOOK_UNLOCKS is the same two-levels-deep shape, right next to BOOK_SHOP in config.js — not
  // named in the fix-round instructions, but the exact same rot this block exists to close, and
  // it costs nothing new to assert: Light Thief already shipped with French (fr.js:98-99, Task 1).
  for (const [bookId, table] of Object.entries(BOOK_UNLOCKS)) {
    for (const [id, u] of Object.entries(table)) {
      assert.ok(FR[u.name], `BOOK_UNLOCKS.${bookId}.${id}.name ('${u.name}') has no French`)
      assert.ok(FR[u.desc], `BOOK_UNLOCKS.${bookId}.${id}.desc ('${u.desc}') has no French`)
    }
  }
  // BOOKS[*].name — one level deep (BOOK_ORDER is a flat list of ids), but run XX's config-table
  // walk never reaches BOOKS at all (it is not in the [WEAPONS, ELEMENTS, ...] literal), so this
  // was untranslated with no assertion anywhere until this block. Shown on the shop's balance
  // header (renderShop, ui.js) beside the coin count.
  for (const b of BOOK_ORDER) {
    assert.ok(FR[BOOKS[b].name], `BOOKS.${b}.name ('${BOOKS[b].name}') has no French`)
  }

  // (y) TASK 9 — the three Undertow resource lines act on the run's resource bar (run.charge), in
  // all three of the book's chapters. deepLungs raises the CEILING: run.charge had no ceiling of
  // its own before this task — sim.js read CHAPTERS[chapter].resource.max straight from config at
  // BOTH clamp sites (the drain in stepCharge and the kill-refill at the kill site), so deepLungs
  // needs a new run.chargeMax field and both sites must read it, not just one.
  for (const chapter of ['surf', 'shelf', 'reef']) {
    const base = makeMeta(); base.chapters = {}
    const r0 = createRun(base, { chapter })
    const up = makeMeta(); up.chapters = {}
    ensureBookMeta(up, 'undertow').shop.deepLungs = lineMax('deepLungs')
    const r1 = createRun(up, { chapter })
    assert.ok(r1.chargeMax > r0.chargeMax,
      `deepLungs must raise the resource ceiling in '${chapter}' (${r0.chargeMax} -> ${r1.chargeMax})`)
    assert.ok(Math.abs(r1.chargeMax / r0.chargeMax - (1 + BOOK_SHOP.undertow.deepLungs.perLevel * lineMax('deepLungs'))) < 1e-6,
      `deepLungs scales linearly at ${BOOK_SHOP.undertow.deepLungs.perLevel} per level x ${lineMax('deepLungs')} levels`)
    assert.strictEqual(r1.charge, r1.chargeMax, 'the bar starts full at the RAISED ceiling')
  }

  // The DRAIN clamp (stepCharge, sim.js) must bind at run.chargeMax, not the config max. Called
  // directly (stepCharge is already imported for run US) with dt small enough that the drain alone
  // could never explain a big move — so if the bar drops all the way from the raised ceiling down
  // to the OLD config max in one tick, the only explanation left is the clamp still reading config.
  {
    const m = makeMeta(); m.chapters = {}
    ensureBookMeta(m, 'undertow').shop.deepLungs = lineMax('deepLungs')
    const run = createRun(m, { chapter: 'shelf' })
    const configMax = CHAPTERS.shelf.resource.max
    assert.ok(run.chargeMax > configMax, 'precondition: deepLungs must raise the ceiling above the config max for this probe to mean anything')
    run.shafts.length = 0   // no in-shaft refill masking the drain
    run.charge = run.chargeMax
    stepCharge(run, 1 / 60)
    assert.ok(run.charge > configMax,
      `the drain clamp must bind at run.chargeMax (${run.chargeMax}), not the config max (${configMax}) — got ${run.charge} after one drain tick from the raised ceiling`)
  }

  // The KILL-REFILL clamp (sim.js's kill branch) must ALSO bind at run.chargeMax — a SEPARATE line
  // from the drain clamp above, and the brief's own trap: a refill still clamped to the config max
  // would let the bar refill past its OLD cap on kills and snap back down on the very next drain
  // tick, a flicker no "does the ceiling move" assertion can see.
  //
  // ON THE WRECK, and it has to be: `killBase` is the only per-kill refill left in the game since
  // v7.x removed Scavenger, so this is the ONLY chapter where that clamp site can fire at all. It
  // used to run on The Shelf with a hand-set run.killRefill of 50 — a field that no longer exists,
  // and a rig that could not have caught this today. Proven with a REAL kill (park 1-hp enemies on
  // the player and let the starter weapon finish them), not a hand-set run.charge: run.charge is
  // reset to just under the OLD config max before every step — safely below BOTH candidate ceilings
  // — so the drain clamp (proven separately above) can never be what pushes the peak up.
  {
    const m = makeMeta(); m.chapters = {}
    ensureBookMeta(m, 'undertow').shop.deepLungs = lineMax('deepLungs')
    Math.random = mulberry32(1)
    const run = createRun(m, { chapter: 'wreck', difficulty: 1 })
    const res = CHAPTERS.wreck.resource
    const configMax = res.max
    assert.ok(run.chargeMax > configMax, 'precondition: deepLungs must raise the ceiling above the config max for this probe to mean anything')
    assert.ok((res.killBase ?? 0) > 0, 'precondition: The Wreck must still declare killBase — it is the only per-kill refill this clamp site has left to fire on')
    run.player.hp = run.player.maxHP = 1e9
    let peak = 0
    for (let i = 0; i < 300; i++) {
      for (const e of run.enemies) { if (!e._dead) { e.x = run.player.x; e.y = run.player.y; e.hp = e.maxHP = 1 } }
      run.charge = configMax - 1   // one killBase (5) overshoots the OLD cap on its own
      stepSim(run, { x: 0, y: 0, skill: false }, 1 / 60)
      run.events.length = 0
      peak = Math.max(peak, run.charge)
      run.player.hp = run.player.maxHP
    }
    assert.ok(run.kills > 0, `the clamp rig must land at least one kill, got ${run.kills}`)
    assert.ok(peak > configMax,
      `a kill's refill must be able to push the bar above the OLD config max (${configMax}) once deepLungs raises the ceiling — peaked at ${peak}, meaning the kill-refill clamp is still reading the config max instead of run.chargeMax`)
    assert.ok(peak <= run.chargeMax + 1e-6,
      `kill refill must clamp at run.chargeMax (${run.chargeMax}), peaked at ${peak}`)
  }

  // slowBurn and bigGulp are RATES — assert the effect over stepped time, not the stored field. A
  // test that reads run.chargeDrainMul alone passes with the multiplier never applied to anything.
  {
    const drainRun = (levels) => {
      const m = makeMeta(); m.chapters = {}
      ensureBookMeta(m, 'undertow').shop.slowBurn = levels
      Math.random = mulberry32(2)
      const r = createRun(m, { chapter: 'shelf' })
      r.shafts.length = 0   // no in-shaft refill masking the drain
      r.charge = r.chargeMax
      for (let i = 0; i < 60; i++) stepSim(r, { x: 0, y: 0 }, 1 / 60)
      return r.charge
    }
    assert.ok(drainRun(MAX_SHOP_LEVEL) > drainRun(0) + 1e-6,
      'slowBurn must leave MORE resource after a second of draining — assert the drain, not the multiplier')
  }

  // bigGulp: stand in a shaft and refill faster with the line bought. Same reasoning — assert the
  // stepped effect, not run.chargeRefillMul in isolation.
  {
    const refillRun = (levels) => {
      const m = makeMeta(); m.chapters = {}
      ensureBookMeta(m, 'undertow').shop.bigGulp = levels
      Math.random = mulberry32(3)
      const r = createRun(m, { chapter: 'shelf' })
      r.charge = 0
      // Plant a shaft directly on the player so every step refills, independent of the streamer.
      r.shafts = [{ x: 0, y: 0, bx: 0, by: 0, r: 999, phase: 0, _cell: null }]
      for (let i = 0; i < 60; i++) stepSim(r, { x: 0, y: 0 }, 1 / 60)
      return r.charge
    }
    assert.ok(refillRun(MAX_SHOP_LEVEL) > refillRun(0) + 1e-6,
      'bigGulp must leave MORE resource after a second in a refill circle — assert the refill, not the multiplier')
  }

  // (z) TASK 9 FIX ROUND (2026-08-16, coordinator review) — a fourth consumer of the OLD config max:
  // ui.js's paintCharge, the HUD bar itself. darkness()/lightRadius()/resourceDamageMul() (config.js)
  // are covered in their own test functions (run DK, run US.d) now that they take an explicit `max`
  // parameter; this is the one that isn't a pure function reachable from here. ui.js is not
  // importable (no jsdom, initUI() touches document.getElementById on its first line), so this pins
  // the call site as source text AND mirrors paintCharge's own clamp formula with REAL numbers from
  // a Deep-Lungs-maxed run, proving two different charges above the OLD config max paint two
  // DIFFERENT HUD fractions — a "the ceiling moved" test alone would not catch a bar pinned at 100%
  // and motionless for the whole band above the old max, which is exactly what shipped before this.
  {
    const uiSrc = readFileSync(new URL('../src/ui.js', import.meta.url), 'utf8')
    // Open-ended on the third argument (the resource NAME, v7.x's rail label) — what this pins is
    // the MAX, and a regex anchored on the closing paren would fail on any later argument.
    assert.ok(/paintCharge\(run\.charge, run\.chargeMax \?\? res\.max[,)]/.test(uiSrc),
      'the HUD paint call must pass run.chargeMax (falling back to res.max only for a run object that predates the field), not res.max unconditionally')
    // paintCharge's own clamp formula, mirrored exactly below — pinned here so a change to the
    // shipped formula makes the mirror fail loudly instead of silently drifting from what it copies.
    assert.ok(/const frac = max > 0 \? Math\.max\(0, Math\.min\(1, charge \/ max\)\) : 0/.test(uiSrc),
      "paintCharge's clamp formula moved — the mirrored computation below no longer matches the shipped one")

    const m = makeMeta(); m.chapters = {}
    ensureBookMeta(m, 'undertow').shop.deepLungs = lineMax('deepLungs')
    const run = createRun(m, { chapter: 'shelf' })
    const configMax = CHAPTERS.shelf.resource.max
    assert.ok(run.chargeMax > configMax, 'precondition: deepLungs must raise the ceiling above the config max')
    const paintFrac = (charge, max) => (max > 0 ? Math.max(0, Math.min(1, charge / max)) : 0)
    // Against the OLD max, two different charges above it must collapse to the SAME frac (1) — the
    // bug. Prove that first, so the next assertion is provably testing the regression.
    assert.strictEqual(paintFrac(configMax * 1.1, configMax), paintFrac(configMax * 1.7, configMax),
      'precondition: against the OLD config max both charges must saturate to the SAME frac (1) — that collapse is the bug this fix closes')
    assert.notStrictEqual(paintFrac(configMax * 1.1, run.chargeMax), paintFrac(configMax * 1.7, run.chargeMax),
      'two different charges above the OLD config max must paint two DIFFERENT HUD fractions once the call site divides by run.chargeMax')
  }

  // (aa) TASK 10 — THE SURF IS NOW THE FIRST RUN OF A CAMPAIGN. Measured before this change: body
  // d1 runs an effective spawn of 0.30 (balance 0.75 x EARLY_CALM 0.40) at x2.22 xp; surf ran 0.68
  // at x1.0 — 2.3x the spawn rate at 45% of the xp, which was correct only while nobody reached it
  // without a stocked book-1 shop. Owner ruling 2026-08-16.
  assert.ok(EARLY_CALM.surf, "The Surf needs an EARLY_CALM entry — it is a book's first chapter now")
  // Then three more times on 2026-08-17, each relative to the last: "density -25% and XP +30%",
  // then "another 10% less density and 10% more xp", then "another 20% less density and 30% more
  // xp". 0.8·0.75·0.9·0.8 = 0.432 and 1.3·1.3·1.1·1.3 = 2.4167, rounded to the table's two decimals.
  assert.strictEqual(EARLY_CALM.surf.spawnMul, 0.43, 'owner rulings 2026-08-17 (0.8 x 0.75 x 0.9 x 0.8)')
  assert.strictEqual(EARLY_CALM.surf.xpMul, 2.42, 'owner rulings 2026-08-17 (1.3 x 1.3 x 1.1 x 1.3)')
  // The EFFECTIVE d1 numbers, composed with the chapter balance. The literals above cannot see a
  // later edit to CHAPTERS.surf.balance that quietly makes this the harshest opening again.
  {
    const eff = (id) => ({
      spawn: CHAPTERS[id].balance.spawnMul * EARLY_CALM[id].spawnMul,
      xp: CHAPTERS[id].balance.xpMul * EARLY_CALM[id].xpMul,
    })
    const surf = eff('surf'), body = eff('body'), pond = eff('pond')
    assert.ok(surf.spawn <= body.spawn + 1e-9,
      `The Surf's d1 spawn (${surf.spawn.toFixed(3)}) must not be denser than The Body's (${body.spawn.toFixed(3)}) — three "too hard" rulings put it at or under the game's gentlest opening`)
    assert.ok(surf.xp >= body.xp - 1e-9,
      `The Surf's d1 xp (x${surf.xp.toFixed(2)}) must not pay less than The Body's (x${body.xp.toFixed(2)})`)
    assert.ok(surf.spawn < pond.spawn,
      `The Surf's d1 spawn (${surf.spawn.toFixed(3)}) must stay under The Pond's (${pond.spawn.toFixed(3)})`)
  }
  // Shore Crabs, thinned twice: 40% on 2026-08-16, then a further "20% less crabs" on 2026-08-17.
  // 0.41 and NOT 0.6 x 0.8 = 0.48, because these weights are relative and crabs are the chapter's
  // tank — see the block above archetypeMul in config.js for the 5-seed x 300s census. Pinned as a
  // literal in the same style as the two EARLY_CALM rulings above: an owner-set number that a later
  // edit must not drift silently.
  assert.strictEqual(CHAPTERS.surf.archetypeMul?.tank, 0.41, '20% fewer Shore Crabs again (owner ruling 2026-08-17), measured not derived')
  // The Wreck's moray, pinned to the ruling that set it rather than to whatever the file says today.
  assert.strictEqual(CHAPTERS.wreck.archetypeMul?.tank, 0.3, '70% fewer Morays (owner ruling 2026-08-18)')
  // The Shelf's moon jelly, same style. 0.56 and NOT 0.65: relative weights, so the derived value
  // comes from integrating spawnRate(t)*tankShare(t) over a 300s run (487 -> 316 tank spawns).
  assert.strictEqual(CHAPTERS.shelf.archetypeMul?.tank, 0.56, '35% fewer Moon Jellies (owner ruling 2026-08-20)')
  // The archetypeMul key must be a real ARCHETYPE, not a WAVE_TABLE spawn type — indexing the
  // wrong way silently did nothing until v5.5 (see TYPE_ARCHETYPE in config.js). run SP.f asserts
  // this same vocabulary but only over CHAPTER_ORDER (book 1) — surf is Book 2 and outside that
  // sweep, so it needs its own check here rather than inheriting SP.f's coverage for free.
  for (const [archId, mul] of Object.entries(CHAPTERS.surf.archetypeMul)) {
    assert.ok(['normal', 'fast', 'tank'].includes(archId), `archetypeMul key '${archId}' is not an archetype`)
    assert.ok(mul > 0 && mul <= 1, `archetypeMul.${archId} must be a reduction in (0,1]`)
  }

  // (ab) EVERY chapter resolves to a book. bookOf returns null for an unclaimed id, and run.chapter
  // is a CHAPTERS key, not an ALL_CHAPTER_IDS key — so an orphan chapter banks coins into
  // meta.books[null], a purse no screen can render. The honest denominator is Object.keys(CHAPTERS),
  // not CHAPTER_ORDER (book 1 only) and not ALL_CHAPTER_IDS (drops every `hidden` id).
  const bkAllChapters = Object.keys(CHAPTERS)
  for (const bkId of bkAllChapters) {
    assert.ok(bookOf(bkId), `chapter '${bkId}' belongs to no book — add it to BOOKS or its coins vanish`)
  }
  assert.ok(bkAllChapters.includes('surf'), 'sanity: the sweep can see the chapter this work is for')

  // (ac) No consumer reads SHOP directly — every one goes through shopLines(bookId), or a
  // book-specific line is invisible in exactly one place. Source-text lint (the run UG.k idiom).
  for (const bkFile of ['state.js', 'main.js', 'ui.js']) {
    const bkSrc = readFileSync(new URL(`../src/${bkFile}`, import.meta.url), 'utf8')
    const bkBare = bkSrc.match(/\bSHOP\[[^\]]+\]|Object\.(keys|entries|values)\(SHOP\)/g) ?? []
    assert.deepStrictEqual(bkBare, [], `${bkFile} reads SHOP directly (${bkBare.join(', ')}) — use shopLines(bookId)`)
  }

  // (ad) FINAL FIX ROUND, FIX 1 — meta.books/meta.grants must shape-guard against a non-nullish
  // non-object, the same hardening ensureBookMeta already applies to entry.shop/.unlocks. `??=`
  // does not fire for e.g. `books: 5`, so the very next line indexes a primitive — a TypeError,
  // thrown INSIDE loadMeta's own `catch { corrupted save -> fresh }` (state.js), which wipes the
  // WHOLE save, not just books. No shipped writer produces such a blob, but importSlot validates
  // shop+chapters and NOT these two fields, so a tampered or foreign-build blob synced from
  // another device passes straight through. Measured before this fix (see the final review):
  //   {"books":5}     -> runs 0, coins 0, lang en   WIPED
  //   {"grants":"x"}  -> runs 0, coins 0, lang en   WIPED
  //   {"books":"x"}   -> runs 0, coins 0, lang en   WIPED
  // The base blob below is deliberately built to reach BOTH repair sites regardless of which field
  // is malformed: dev:true + a Beyond win at 5 (>= CHAPTER_UNLOCK_DIFFICULTY) drives the
  // retroactive unlockBook -> grantBook -> ensureBookMeta chain (o, above), and lightThief:true
  // alone drives the forward-copy's own ensureBookMeta call (p, above) — so a books-guard bug and a
  // grants-guard bug are each independently reachable no matter which one this run happens to hit
  // first.
  const bkBadBase = () => ({
    schema: 1, coins: 4200, shop: {}, choiceSlots: 4, runs: 137, chapter: 'beyond', lang: 'fr',
    dev: true, lightThief: true,
    best: { time: 300, kills: 4000 },
    chapters: { beyond: { unlocked: true, maxDifficulty: 5, difficulty: 5, won: 5 } },
  })
  for (const bad of [{ books: 5 }, { grants: 'x' }, { books: 'x' }]) {
    const blob = { ...bkBadBase(), ...bad }
    const m = loadMetaFrom(blob)
    assert.strictEqual(m.runs, 137, `a malformed ${JSON.stringify(bad)} must not wipe runs`)
    assert.strictEqual(m.coins, 4200, `a malformed ${JSON.stringify(bad)} must not wipe coins`)
    assert.strictEqual(m.lang, 'fr', `a malformed ${JSON.stringify(bad)} must not wipe lang`)
    // And the malformed field itself lands on a usable shape, not the raw primitive.
    assert.ok(m.books && typeof m.books === 'object' && !Array.isArray(m.books),
      `${JSON.stringify(bad)}: meta.books must repair to a plain object`)
    assert.ok(m.grants && typeof m.grants === 'object' && !Array.isArray(m.grants),
      `${JSON.stringify(bad)}: meta.grants must repair to a plain object`)
  }
  console.log('PASS run BP.ad (shape guard): meta.books/meta.grants survive books:5, grants:"x" and books:"x" without wiping the save')

  // (ae) PER-LINE LEVEL CAPS (v7.x). A line may sell fewer levels than MAX_SHOP_LEVEL, and every
  // one of this feature's failure modes is SILENT: a bare MAX_SHOP_LEVEL left in a notch rail
  // draws ten pips on a five-level line, one left in the buy guard sells an eleventh level nobody
  // priced, and a legacy save holding the old count pays out a bonus the shop no longer offers.
  {
    // `seen` (block b above) is the merged every-book line table, built and uniqueness-checked there.
    const capped = [...seen.keys()].filter((id) => lineMax(id) !== MAX_SHOP_LEVEL)
    assert.ok(capped.length > 0,
      'no line overrides maxLevel — this whole block is asserting nothing. Delete it or restore the override.')

    // 1. THE PRICE LADDER'S ENDPOINTS ARE FIXED, whatever the level count. A short line takes the
    // same first and last rung as a full-length one on the same base; it just strides between
    // them. Without this a halved line is simply a cheap line, which is the opposite of the tune.
    //
    // A FLAT-PRICED LINE (`cost`) is exempt from the ladder and asserted on its own terms below:
    // it has one level, so there is nothing to stride between, and the ladder's own endpoints are
    // meaningless for it. The exemption is narrow ON PURPOSE — it applies only where `cost` is
    // actually set, so deleting a ladder line's `base` cannot smuggle it out of these checks.
    const flat = [...seen].filter(([, line]) => line.cost != null)
    assert.ok(flat.length > 0,
      'no line sets a flat `cost` — the exemption below is asserting nothing. Delete it or restore the line.')
    for (const [id, line] of flat) {
      assert.strictEqual(lineMax(id), 1,
        `${id}: a flat-priced line must sell exactly ONE level — the price does not vary, so a second level would cost the same as the first`)
      assert.strictEqual(shopCost(id, 0), line.cost,
        `${id}: a flat-priced line must charge its own \`cost\` (${line.cost}), not the ladder's ${shopCost(id, 0)}`)
      assert.ok(line.cosmetic,
        `${id}: a flat price buys no stat ladder, so the line must be marked \`cosmetic\` — that flag is what keeps it off the sacrifice screen, whose rows read "what one level gives you"`)
      assert.strictEqual(line.perLevel, 0,
        `${id}: a cosmetic line must have perLevel 0 — shopBonus multiplies it into a stat, and a non-zero value would silently buff the player`)
    }
    for (const [id, line] of seen) {
      if (line.cost != null) continue
      const max = lineMax(id)
      const base = line.base
      const ceiling = SHOP_COST_CAP[id] ?? SHOP_COST_CAP_DEFAULT
      const fullLast = Math.min(ceiling,
        Math.round(base * Math.pow(1.6, MAX_SHOP_LEVEL - 1) * (1.2 + 1.8)))
      assert.strictEqual(shopCost(id, 0), Math.min(ceiling, Math.round(base * 1.2)),
        `${id}: the FIRST rung must cost base x 1.2 whatever maxLevel is`)
      assert.strictEqual(shopCost(id, max - 1), fullLast,
        `${id}: the LAST rung (level ${max - 1} of ${max}) must cost what a ${MAX_SHOP_LEVEL}-level line on base ${base} charges for its last — ${fullLast}. It reads ${shopCost(id, max - 1)}, so shortening the line made it cheaper instead of steeper.`)
      // ...and the ladder never goes backwards on the way there.
      for (let l = 1; l < max; l++) {
        assert.ok(shopCost(id, l) >= shopCost(id, l - 1),
          `${id}: rung ${l} (${shopCost(id, l)}) is cheaper than rung ${l - 1} (${shopCost(id, l - 1)})`)
      }
    }
    // The owner's floor for a shortened line: its last level is a real commitment, not pocket change.
    for (const id of capped) {
      assert.ok(shopCost(id, lineMax(id) - 1) > 1000,
        `${id}: a shortened line's last level must cost more than 1000 — it costs ${shopCost(id, lineMax(id) - 1)}`)
    }

    // 2. A LEGACY SAVE IS CLAMPED ON USE, NOT ON LOAD (R3). deepLungs sold 10 levels before this
    // tune; a save holding 10 keeps the 10 on disk and is PAID for lineMax of them.
    const legacy = makeMeta(); legacy.chapters = {}
    const lbm = ensureBookMeta(legacy, 'undertow')
    lbm.shop.deepLungs = MAX_SHOP_LEVEL          // the pre-tune count
    const rLegacy = createRun(legacy, { chapter: 'surf', difficulty: 1 })
    const atCap = makeMeta(); atCap.chapters = {}
    ensureBookMeta(atCap, 'undertow').shop.deepLungs = lineMax('deepLungs')
    const rCap = createRun(atCap, { chapter: 'surf', difficulty: 1 })
    assert.strictEqual(rLegacy.chargeMax, rCap.chargeMax,
      `a save holding ${MAX_SHOP_LEVEL} of deepLungs must pay out only lineMax (${lineMax('deepLungs')}) — it reads ${rLegacy.chargeMax} against ${rCap.chargeMax}`)
    assert.strictEqual(lbm.shop.deepLungs, MAX_SHOP_LEVEL,
      'and the SAVE must still hold 10: clamping on load is what an older build reads back as a loss (R3)')

    // 3. NO BARE MAX_SHOP_LEVEL LEFT IN A LEVEL-COUNT POSITION. Source text, because the two
    // files that would break are the two the suite cannot import. ui.js draws the rails and the
    // MAX chip; main.js guards the purchase. Both must ask the LINE.
    for (const f of ['src/ui.js', 'src/main.js']) {
      const src = readFileSync(new URL(`../${f}`, import.meta.url), 'utf8')
      const code = src.split('\n').filter((l) => !l.trim().startsWith('//') && !l.trim().startsWith('*')).join('\n')
      assert.ok(!/MAX_SHOP_LEVEL/.test(code),
        `${f} still references MAX_SHOP_LEVEL outside a comment. Every level count there must go through lineMax(id) — a bare global draws a 10-notch rail on a 5-level line and sells an unpriced 6th.`)
      assert.ok(/lineMax\(/.test(code), `${f} must call lineMax()`)
    }
    console.log(`PASS run BP.ae (per-line level caps): ${capped.length} shortened line(s) [${capped.join(' ')}], ladder endpoints pinned to the ${MAX_SHOP_LEVEL}-level curve and monotone throughout, last rungs ${capped.map((id) => shopCost(id, lineMax(id) - 1)).join('/')} all over 1000, a legacy ${MAX_SHOP_LEVEL}-level save pays out ${lineMax('deepLungs')} while keeping ${MAX_SHOP_LEVEL} on disk, and neither ui.js nor main.js reads the global cap`)

    // (af) SHOP FAMILIES — the four colour blocks. `family` is DECLARED on the line rather than
    // inferred from its position, and the three things that make that worth anything are all
    // silent when broken: a line with no family renders in the fallback colour and quietly joins
    // the wrong block, a family with no palette entry does the same, and a line inserted between
    // two blocks splits a colour run in half while every other test stays green.
    const FAMS = Object.keys(SHOP_FAMILY)
    assert.ok(FAMS.length >= 2, 'SHOP_FAMILY needs more than one family or the colour coding says nothing')
    for (const [fam, p] of Object.entries(SHOP_FAMILY)) {
      for (const tone of ['ico', 'edge', 'lite']) {
        assert.ok(/^#[0-9a-f]{6}$/i.test(p[tone] ?? ''),
          `SHOP_FAMILY.${fam}.${tone} must be a '#rrggbb' hex — ui.js writes it straight into an inline style, so a bad value fails silently as an uncoloured glyph. Got ${JSON.stringify(p[tone])}`)
      }
    }
    // Declared on every line of every book, and on every book unlock.
    for (const bookId of BOOK_ORDER) {
      for (const [id, line] of Object.entries(shopLines(bookId))) {
        assert.ok(FAMS.includes(line.family),
          `${bookId}.${id} has family ${JSON.stringify(line.family)}, which is not one of [${FAMS.join(' ')}]`)
      }
      for (const [id, u] of Object.entries(BOOK_UNLOCKS[bookId] ?? {})) {
        assert.ok(FAMS.includes(u.family),
          `BOOK_UNLOCKS.${bookId}.${id} has family ${JSON.stringify(u.family)}, which is not one of [${FAMS.join(' ')}]`)
      }
    }
    // CONTIGUOUS, which is the whole point of declaring it (owner: "regroup explicitly"). The
    // table's order IS the render order — renderShop maps Object.entries(shopLines(bookId)) — so a
    // family that appears, stops and reappears puts two separated blocks of one colour on screen.
    for (const bookId of BOOK_ORDER) {
      const order = Object.values(shopLines(bookId)).map((l) => l.family)
      const runs = order.filter((f, i) => f !== order[i - 1])
      assert.strictEqual(runs.length, new Set(runs).size,
        `${bookId}: the shop table's families must each appear in ONE unbroken run — the order is [${order.join(' ')}], which returns to a family it had already left. renderShop walks this table in order, so that is two separated blocks of one colour.`)
    }
    // And every line is actually DRAWN. A line with no SHOP_ICONS entry silently falls back to its
    // emoji, which is the exact thing the drawn set replaced — one stray emoji in a column of
    // eleven drawn glyphs reads as a rendering bug.
    const uiSrc = readFileSync(new URL('../src/ui.js', import.meta.url), 'utf8')
    const iconBlock = uiSrc.slice(uiSrc.indexOf('const SHOP_ICONS = {'), uiSrc.indexOf('\n}', uiSrc.indexOf('const SHOP_ICONS = {')))
    assert.ok(iconBlock.length > 200, 'could not find SHOP_ICONS in ui.js — this check is asserting nothing')
    const drawn = [...iconBlock.matchAll(/^\s{2}(\w+):/gm)].map((m) => m[1])
    for (const id of [...seen.keys(), ...Object.keys(BOOK_UNLOCKS).flatMap((b) => Object.keys(BOOK_UNLOCKS[b])), 'slot']) {
      assert.ok(drawn.includes(id),
        `shop line '${id}' has no SHOP_ICONS entry in ui.js — it falls back to its emoji, alone in a column of drawn glyphs`)
    }
    // ...and every SITE that shows one routes through shopIcon. Having a drawing is not enough:
    // the sacrifice offer header interpolated `target.icon` straight into the markup and so
    // rendered a raw 🦴 above a screenful of drawn glyphs. It shipped, and no assertion could see
    // it — the drawing existed, it just was not asked for. Caught by SHOOTING the third screen.
    // sacTargets synthesises the rows the sacrifice screens draw, so every row it emits must carry
    // a `family` — without one shopIcon falls back to ATK red, and Scavenger (declared `res`)
    // painted red on the offer header while every assertion stayed green.
    const sacBlock = uiSrc.slice(uiSrc.indexOf('function sacTargets('), uiSrc.indexOf('\n  }', uiSrc.indexOf('function sacTargets(')))
    assert.ok(sacBlock.includes('out.push({'), 'could not find sacTargets in ui.js — this check is asserting nothing')
    const pushes = [...sacBlock.matchAll(/out\.push\(\{[^}]*\}/g)].map((m) => m[0])
    assert.ok(pushes.length >= 2, `expected at least 2 out.push sites in sacTargets, found ${pushes.length}`)
    for (const push of pushes) {
      assert.ok(/\bfamily\s*:/.test(push),
        `a sacTargets row is emitted without a family, so its icon paints in shopIcon's fallback hue: ${push.replace(/\s+/g, ' ').slice(0, 110)}`)
    }

    const ICON_SITES = ['sac-offer-ico', 'shop-row-icon', 'sacrifice-for']
    for (const site of ICON_SITES) {
      const lines = uiSrc.split('\n').filter((l) => l.includes(`"${site}"`) && l.includes('${'))
      assert.ok(lines.length > 0, `no interpolating markup line found for .${site} — this check is asserting nothing`)
      for (const l of lines) {
        assert.ok(l.includes('shopIcon('),
          `.${site} interpolates an icon without shopIcon(): ${l.trim().slice(0, 110)}\nA bare .icon renders the EMOJI fallback, alone among drawn glyphs.`)
      }
    }
    console.log(`PASS run BP.af (shop families): ${FAMS.length} families [${FAMS.join(' ')}] with 3 hex tones each, declared on all ${seen.size} lines + every book unlock, each family in one unbroken run per book, all ${drawn.length} ids drawn rather than falling back to emoji, and all ${ICON_SITES.length} render sites route through shopIcon`)
  }

  // (ag) THE COSMETIC'S MASTERY GATE. Every failure here is silent: the line is the priciest one
  // and gives no stat, so a gate that never opens looks exactly like a gate that opened and a skin
  // the player cannot see. Four properties, and the per-book one is the whole point of the design.
  {
    const mk = () => {
      const m = makeMeta()
      m.chapters = {}
      m.books = {}
      return m
    }
    // the id must actually be gated — otherwise every assertion below passes against nothing
    const gated = [...seen].filter(([, l]) => l.needsMastery)
    assert.strictEqual(gated.length, 1,
      `expected exactly one gated shop line, found ${gated.map(([id]) => id).join(', ') || 'none'}`)
    const [GATE_ID, GATE_LINE] = gated[0]
    assert.strictEqual(GATE_LINE.needsMastery, MASTERY_UNLOCK,
      `${GATE_ID} must read its threshold from MASTERY_UNLOCK, not a second copy of the number`)

    // 1. a fresh save is LOCKED, and stays locked one chapter short of the bar.
    const fresh = mk()
    assert.strictEqual(chaptersMastered(fresh, 'book1'), 0, 'a fresh save has mastered nothing')
    assert.ok(!shopLineUnlocked(fresh, 'book1', GATE_ID), `${GATE_ID} must be locked on a fresh save`)
    const win = (m, id) => { m.chapters[id] = { unlocked: true, maxDifficulty: chapterMaxDifficulty(id), difficulty: 1, won: chapterMaxDifficulty(id), best: { time: 0, kills: 0 } } }
    const one = mk(); win(one, BOOKS.book1.chapters[0])
    assert.strictEqual(chaptersMastered(one, 'book1'), 1)
    assert.ok(!shopLineUnlocked(one, 'book1', GATE_ID),
      `${GATE_ID} opened at 1 chapter — the threshold is ${MASTERY_UNLOCK}, so the gate is off by one`)

    // 2. WON, NOT UNLOCKED. A ladder climbed to 5 without a win at 5 must not count: maxDifficulty
    // is how far the ladder is OPEN, `won` is what has actually been beaten, and reading the wrong
    // one hands the skin to anyone who merely reached the top difficulty once.
    const climbed = mk()
    climbed.chapters[BOOKS.book1.chapters[0]] = { unlocked: true, maxDifficulty: 5, difficulty: 5, won: 0, best: { time: 0, kills: 0 } }
    climbed.chapters[BOOKS.book1.chapters[1]] = { unlocked: true, maxDifficulty: 5, difficulty: 5, won: 0, best: { time: 0, kills: 0 } }
    assert.strictEqual(chaptersMastered(climbed, 'book1'), 0,
      'an UNLOCKED top difficulty is not a WON one — chaptersMastered must read .won')

    // 3. two wins at the top rung opens it.
    const two = mk(); win(two, BOOKS.book1.chapters[0]); win(two, BOOKS.book1.chapters[1])
    assert.strictEqual(chaptersMastered(two, 'book1'), MASTERY_UNLOCK)
    assert.ok(shopLineUnlocked(two, 'book1', GATE_ID), `${GATE_ID} must open at ${MASTERY_UNLOCK} mastered chapters`)
    // ...and a win BELOW the chapter's own top rung does not count.
    const short = mk()
    for (const id of BOOKS.book1.chapters.slice(0, 2)) {
      short.chapters[id] = { unlocked: true, maxDifficulty: 5, difficulty: 1, won: chapterMaxDifficulty(id) - 1, best: { time: 0, kills: 0 } }
    }
    assert.ok(!shopLineUnlocked(short, 'book1', GATE_ID), 'one rung short of the top must not count as mastered')

    // 4. PER BOOK. Mastering book 1 must not open Undertow's own copy of the line — each book
    // sells its own and each is earned in its own campaign. This is the property the whole
    // design rests on and the one a bookId-blind implementation would silently break.
    assert.strictEqual(chaptersMastered(two, 'undertow'), 0,
      'book 1 chapters must not count toward Undertow')
    assert.ok(!shopLineUnlocked(two, 'undertow', GATE_ID),
      `${GATE_ID} unlocked in Undertow off book 1's wins — the gate is not reading the book`)

    // 5. the ungated lines are unaffected, in every book.
    for (const bookId of BOOK_ORDER) {
      for (const id of Object.keys(shopLines(bookId))) {
        if (id === GATE_ID) continue
        assert.ok(shopLineUnlocked(fresh, bookId, id), `${bookId}.${id} must not be gated`)
      }
    }

    // 6. THE WIRING, as source text. Both halves fail silently: a row rendered without the gate
    // sells the skin at once, and a gate in ui.js alone leaves onBuy spending the price on a crafted
    // event. The hint's French is checked here too — it lives in a ui.js FUNCTION, which run XX's
    // table walk cannot see by construction (CLAUDE.md records that exemption shipping
    // untranslated copy four times).
    const uiSrc = readFileSync(new URL('../src/ui.js', import.meta.url), 'utf8')
    const mainSrc = readFileSync(new URL('../src/main.js', import.meta.url), 'utf8')
    assert.ok(uiSrc.includes('shopLineUnlocked(meta, bookId, id)'),
      'renderShop does not consult shopLineUnlocked — a locked line renders as a buyable row')
    assert.ok(/onBuy[\s\S]{0,900}shopLineUnlocked\(/.test(mainSrc),
      'onBuy does not consult shopLineUnlocked — ui.js omitting data-buy is presentation, not a gate')
    const HINT = 'chapters finished at max difficulty {n}/{max}'
    assert.ok(uiSrc.includes(HINT), `ui.js no longer contains the unlock hint ${JSON.stringify(HINT)} — this list is stale`)
    assert.ok(FR[HINT], 'the unlock hint has no French')
    for (const ph of ['{n}', '{max}']) {
      assert.ok(FR[HINT].includes(ph),
        `the French unlock hint drops ${ph} — the player sees the placeholder, not the number`)
    }
    // 7. THE JIGGLE (CHEEK_JIGGLE). render.js is not importable here, and EVERY failure mode of
    // this effect renders as a perfectly correct STILL — the cheeks simply stop moving — so a
    // screenshot cannot catch it and neither can anything but source text plus the numbers.
    assert.ok(CHEEK_JIGGLE.damp > 0 && CHEEK_JIGGLE.k > 0,
      'a non-positive spring constant or damping makes the jiggle diverge instead of settling')
    assert.ok(CHEEK_JIGGLE.max > 0 && CHEEK_JIGGLE.max < 1,
      'CHEEK_JIGGLE.max is a FRACTION of the butt half-width — at >= 1 the cheeks leave the body, at 0 they never move')
    // The three layers must all be baked, and each has to be a DIFFERENT part: baking the body
    // with the cheeks still on it leaves a static ghost under the moving ones, which is the one
    // artifact that reads as a rendering bug rather than as no effect at all.
    const rSrc = readFileSync(new URL('../src/render.js', import.meta.url), 'utf8')
    for (const [name, needle] of [
      ['the blob body excludes its cheeks', "drawBlobButt(g, false, 'body')"],
      ['the blob cheeks bake alone', "drawBlobButt(g, false, 'cheeks')"],
      ['the fish cheeks bake alone', "drawFish(kg, false, ang, true, 'cheeks')"],
      ['the kaiju cheeks bake alone', "drawKaijuBody(g, false, true, 'cheeks')"],
      ['the fish body stops at the shell', "drawButt(g, 1, r * 0.64, r * 0.68, rot, hx, hy, col, white, 'shell')"],
      ['the cheek layer is its own container', 'cheekC.addChild(pCheeks)'],
      ['and is clipped to the silhouette', 'cheekC.mask = pMask'],
      ['the spring is kicked by ACCELERATION, not velocity', '(p.vx - jigVX0) / dt'],
      ['and is converted into the body frame', 'if (bodyC.scale.x < 0) lx = -lx'],
    ]) {
      assert.ok(rSrc.includes(needle),
        `render.js no longer contains ${JSON.stringify(needle)} — ${name}. The jiggle fails SILENTLY: the frame still renders, the cheeks just never move.`)
    }
    // the pivot has to come from the bake, per swim phase: the fish's butt centre moves as it
    // undulates, and a constant would slide the squash off the cheeks as the body flexes
    assert.ok(rSrc.includes('T.fishCheekAt.push(') && rSrc.includes('cheekAt = T.fishCheekAt[wIdx]'),
      'the fish jiggle no longer reads its pivot per swim phase — a fixed centre drifts off the cheeks as the body undulates')

    // 8. THE FEET (BUTT_FEET). Same problem as the jiggle — render.js is not importable and every
    // failure here is a still frame that looks fine — plus one of its own: the feet are the only
    // part of this player DRAWN OUTSIDE the body silhouette, so three separate things have to hold
    // or they are simply not on screen and nothing says so.
    assert.ok(BUTT_FEET.stride > 0 && BUTT_FEET.rx > 0 && BUTT_FEET.ry > 0,
      'a zero stride or a zero-size foot leaves the feet as a static pair of dots, which is what "no running animation" looks like')
    // drawBlobButt draws the butt at W = PLAYER.radius * 1.04 and style 3's thigh lobes bottom out
    // at exactly 1.00 W — so a foot resting ABOVE that is hidden behind the very body it is drawn
    // behind, in every frame, in both poses.
    assert.ok(rSrc.includes('PLAYER.radius * 1.04, PLAYER.radius, Math.PI / 2'),
      "the blob butt's own size changed — BUTT_FEET.rest is measured against it, so re-derive where the thighs bottom out before trusting the next assert")
    assert.ok(BUTT_FEET.rest > 1.04,
      'BUTT_FEET.rest sits at or above the butt\'s lowest point — the feet are drawn BEHIND the body, so they never clear it and never appear at all')
    assert.ok(BUTT_FEET.stride < BUTT_FEET.rest - 1.04 + BUTT_FEET.ry,
      'the stride swings the trailing foot entirely behind the body — a foot that vanishes reads as a blink, not as a step')
    for (const [name, needle] of [
      ['the feet ride the body\'s own hop, so the stride cannot drift against the bounce', 'Math.sin(hop + i * Math.PI)'],
      ['and only Book 1\'s blob wears them (the fish and the kaiju swap only their HEAD for the butt)', 'if (playerSkin && !playerForm) {'],
      ['each foot has a white twin, because pFlash wears the BODY silhouette and cannot reach them', 'ff.alpha = pFlash.alpha'],
    ]) {
      assert.ok(rSrc.includes(needle),
        `render.js no longer contains ${JSON.stringify(needle)} — ${name}.`)
    }
    // ORDER, not just presence: the stride reads off one foot tucked behind the butt while the
    // other is in front of it. Added after pBody instead, both feet ride OVER the body and the
    // tuck — the whole effect — is gone, with nothing thrown and every frame still drawing.
    const iFeet = rSrc.indexOf('bodyC.addChild(pFeet)')
    const iBody = rSrc.indexOf('bodyC.addChild(pBody, cheekC')
    assert.ok(iFeet > 0 && iBody > 0 && iFeet < iBody,
      'the feet are no longer added to bodyC BEFORE the body — they now draw over the butt instead of tucking under it')

    console.log(`PASS run BP.ag (mastery gate): ${GATE_ID} locked at 0 and 1 mastered chapters, open at ${MASTERY_UNLOCK}, reads .won not .maxDifficulty, counts per BOOK (book1 wins leave undertow locked), leaves the other ${seen.size - 1} lines ungated, and both renderShop and onBuy consult it; the jiggle is a settling spring, clamped to a FRACTION of the butt, with all three layers baked apart and the pivot read per swim phase; the feet stride on the body's own hop, clear the butt's own 1.04-radius reach without swinging behind it, wear a white twin for the hit flash, are added to bodyC BEFORE the body, and are gated to Book 1's blob`)
  }

  console.log(`PASS run BP (book progression): ${BOOK_ORDER.length} books, ${seen.size} distinct shop lines, shopCost total over all of them, the unlock gate is the finale not a null check, the grant is monotone, retroactive unlock respects the WIP gate, meta.lightThief copies forward once and never re-fires, endRun's book-finale wiring is present as source text, a rev-2 save round-trips through this build's own loadMeta with both books intact, main.js's purchase hooks + ui.js's call sites route through an explicit book id, formatShopBonus is sign-aware, .shop-rows scales to any book's line count, onBuy validates its id before spending, every BOOK_SHOP/BOOK_UNLOCKS line plus every book name has French, the three Undertow resource lines (deepLungs/slowBurn/bigGulp) move run.chargeMax and both drain/kill-refill clamp sites, the drain rate and the refill rate, darkness/lightRadius/resourceDamageMul/paintCharge all saturate against run.chargeMax instead of the old config max, The Surf's opening balance (EARLY_CALM.surf + archetypeMul.tank) matches the 2026-08-17 owner rulings, ${bkAllChapters.length} chapters all resolve to a book, and no source file reads SHOP directly`)
}
run(runBookProgression)

// ---- Run BL: The Shelf's mechanic (v7.x, Book 2 phase 2) --------------------------------
// The bar, the shafts and the amplified Pulse. Every failure this guards is SILENT: a frozen shaft
// field looks correct in any still frame, a resource that leaks into other chapters shows up as
// balance drift nobody attributes to it, and a pulse whose event lies about its radius draws the
// wrong ring around a real shove.
function runTwilight() {
  const twilightMeta = () => ({
    coins: 0, shop: {}, best: {}, runs: 0, choiceSlots: 2, chapter: 'twilight', dev: true,
    chapters: Object.fromEntries([...CHAPTER_ORDER, 'twilight'].map((id) => [id, { unlocked: true, maxDifficulty: 5, difficulty: 1 }])),
  })
  const res = CHAPTERS.twilight.resource
  const sig = CHAPTERS.twilight.signature
  const mkRun = (seed = 20260812, opts = {}) => {
    Math.random = mulberry32(seed)
    return createRun(twilightMeta(), { chapter: 'twilight', difficulty: 1, ...opts })
  }
  // Step without any of stepSim's other machinery mattering: no input, no skill.
  const idle = { x: 0, y: 0, skill: false }
  // createRun does NOT stream — the field is materialized by the first stepSim, so every assertion
  // about shafts needs one step first. (The first cut of this run asserted on a fresh run and read
  // "expected shafts, or this measures nothing", which is that guard doing its job.)
  const warm = (run) => { stepSim(run, idle, 1 / 60); run.events.length = 0; return run }

  // (a) The bar drains at the configured rate, and clamps at zero rather than going negative.
  {
    const run = mkRun()
    run.charge = res.max
    // Park the player far from every shaft so ONLY the drain is measured — standing in one would
    // net the two effects together and the test would pass for any pair of numbers that cancelled.
    run.shafts.length = 0
    const before = run.charge
    for (let i = 0; i < 60; i++) { run.shafts.length = 0; stepSim(run, idle, 1 / 60); run.events.length = 0 }
    const dropped = before - run.charge
    // Kills refill too, and a step spawns enemies a weapon may kill, so this is a band not an equality.
    assert.ok(dropped > res.drain * 0.5 && dropped <= res.drain * 1.5 + 0.01,
      `one second of drain should be about ${res.drain}, got ${dropped.toFixed(3)}`)
    run.charge = 0.001
    for (let i = 0; i < 120; i++) { run.shafts.length = 0; stepSim(run, idle, 1 / 60); run.events.length = 0 }
    assert.ok(run.charge >= 0, `charge clamps at zero, got ${run.charge}`)
  }

  // (b) Standing in a shaft refills, and the bar clamps at max rather than growing forever.
  {
    const run = warm(mkRun())
    run.charge = 0
    assert.ok(run.shafts.length > 0, 'expected shafts to stream around the origin, or (b) measures nothing')
    const sh = run.shafts[0]
    run.player.x = sh.x; run.player.y = sh.y
    for (let i = 0; i < 30; i++) {
      const s0 = run.shafts[0]
      run.player.x = s0.x; run.player.y = s0.y   // follow the drift, so the player stays inside
      stepSim(run, idle, 1 / 60); run.events.length = 0
    }
    assert.ok(run.charge > 0, 'standing in a shaft must refill the bar')
    run.charge = res.max
    for (let i = 0; i < 60; i++) {
      const s0 = run.shafts[0]
      run.player.x = s0.x; run.player.y = s0.y
      stepSim(run, idle, 1 / 60); run.events.length = 0
    }
    assert.ok(run.charge <= res.max + 1e-9, `charge clamps at max ${res.max}, got ${run.charge}`)
  }

  // (c) THE ONE THAT CATCHES A MISSING stepShafts. A shaft must MOVE between two frames with no
  // cell crossing. streamShafts early-returns unless the player changes cell, so a build that
  // relies on the streamer alone computes each position once per materialization and never again —
  // and nothing looks broken, because render re-places from the list every frame and would draw the
  // frozen field perfectly. The player is held still on purpose: that guarantees no cell crossing.
  {
    const run = warm(mkRun())
    assert.ok(run.shafts.length > 0, 'expected shafts, or (c) measures nothing')
    const id = run.shafts[0]._cell
    const x0 = run.shafts[0].x, y0 = run.shafts[0].y
    const ci = run._shaftCellI, cj = run._shaftCellJ
    for (let i = 0; i < 30; i++) { stepSim(run, idle, 1 / 60); run.events.length = 0 }
    const same = run.shafts.find((sh) => sh._cell === id)
    assert.ok(same, 'the shaft streamed out mid-test — (c) needs the SAME shaft on both frames')
    assert.strictEqual(run._shaftCellI, ci, 'the player must not have crossed a cell, or (c) proves nothing')
    assert.strictEqual(run._shaftCellJ, cj, 'the player must not have crossed a cell, or (c) proves nothing')
    const moved = Math.hypot(same.x - x0, same.y - y0)
    assert.ok(moved > 1, `a shaft must DRIFT between frames with no cell crossing — moved ${moved.toFixed(3)}px in half a second`)
    // ...and it drifts around its streamed BASE, never wandering off: the offset is exactly driftAmp.
    const off = Math.hypot(same.x - same.bx, same.y - same.by)
    assert.ok(Math.abs(off - sig.driftAmp) < 1e-6, `drift offset must be exactly driftAmp (${sig.driftAmp}), got ${off.toFixed(4)}`)
  }

  // input.js needs a DOM and cannot be imported here, so its DEADZONE is mirrored as a literal.
  // If input.js ever changes it, (d)'s floor goes stale silently — hence the grep below it.
  const DEADZONE_FOR_TEST = 0.15
  // (d) Peak drift speed sits inside the band the tune has to respect: above the joystick's minimum
  // non-zero speed (DEADZONE x baseSpeed) so the player can follow it, and below KITE_MIN_SPEED so
  // chasing the light does not also recycle the horde onto it.
  {
    const peak = sig.driftAmp * sig.driftHz
    const floor = DEADZONE_FOR_TEST * PLAYER.baseSpeed
    assert.ok(peak > floor, `peak drift ${peak} must exceed the joystick floor ${floor} px/s`)
    assert.ok(peak < KITE_MIN_SPEED, `peak drift ${peak} must stay under KITE_MIN_SPEED ${KITE_MIN_SPEED} px/s`)
  }

  // (e) Drift is derived from run._realTime, NOT run.time. The Time Debt anomaly advances run.time
  // at 1.5x and its `chapter` is null, so it rolls here — a run.time-derived drift would be 50%
  // faster under one anomaly and would breach the ceiling asserted in (d) without any config change.
  {
    const a = warm(mkRun())
    const b = warm(mkRun())
    // +37, not something huge: run.time >= RUN_DURATION (300) flips the run to 'victory' and
    // stepSim returns before it ever reaches stepShafts, so a big offset makes this vacuous from
    // the other direction. 37s is 25.9 rad of drift phase, nowhere near a multiple of 2pi.
    b.time = a.time + 37            // desynchronise the two clocks...
    b._realTime = a._realTime       // ...while holding the one drift is supposed to use
    // A REAL dt, not 0: stepSim does not reach stepShafts on a zero step, so a dt of 0 makes this
    // whole check vacuous — it passed against a deliberately broken build until the mutation run
    // caught it. Both runs advance _realTime by the same amount, so the clock drift stays isolated.
    for (const r of [a, b]) { stepSim(r, idle, 1 / 60); r.events.length = 0 }
    assert.strictEqual(a.shafts.length, b.shafts.length, 'same seed must stream the same field')
    for (let i = 0; i < a.shafts.length; i++) {
      assert.ok(Math.abs(a.shafts[i].x - b.shafts[i].x) < 1e-9 && Math.abs(a.shafts[i].y - b.shafts[i].y) < 1e-9,
        'shaft drift must ignore run.time entirely — it reads run._realTime (Time Debt advances run.time at 1.5x)')
    }
  }

  // (f) Streaming is deterministic AND consumes no RNG. Two runs on the same seed produce the same
  // field; and re-running with Math.random replaced by a constant that would change every draw
  // leaves the field byte-identical, which a hash-based streamer must and an RNG-based one cannot.
  {
    const a = warm(mkRun(4242))
    const b = warm(mkRun(4242))
    assert.deepStrictEqual(a.shafts.map((sh) => sh._cell), b.shafts.map((sh) => sh._cell), 'same seed must stream the same cells')
    const c = warm(mkRun(4242))
    const saved = Math.random
    Math.random = () => 0.999999      // any shaft roll reading this would move every position
    c.player.x += sig.cell * 1.5      // force a cell crossing, so the streamer actually re-scans
    stepSim(c, idle, 1 / 60); c.events.length = 0
    Math.random = saved
    const d = warm(mkRun(4242))
    d.player.x += sig.cell * 1.5
    Math.random = () => 0.000001
    stepSim(d, idle, 1 / 60); d.events.length = 0
    Math.random = saved
    // `phase` is in the key deliberately: without it this compared only bx/by and an RNG-drawn
    // phase passed clean, which is exactly what the mutation run found. Every field the streamer
    // derives from the cell hash belongs here.
    const key = (sh) => `${sh._cell}:${sh.bx.toFixed(4)},${sh.by.toFixed(4)},${sh.phase.toFixed(6)}`
    assert.deepStrictEqual(c.shafts.map(key),
                           d.shafts.map(key),
      'shaft streaming must consume ZERO Math.random at step time — two opposite RNG stubs gave different fields')
  }

  // (g) R2's guard: a chapter that declares no resource is BIT-FOR-BIT unaffected. This is the
  // reason the whole mechanic can sit in main with no feature flag, and it is the assertion that
  // fails the moment stepCharge or streamShafts forgets its early-out.
  {
    const other = () => {
      Math.random = mulberry32(777)
      const m = twilightMeta()
      const r = createRun(m, { chapter: 'pond', difficulty: 1 })
      for (let i = 0; i < 240; i++) { stepSim(r, { x: 0.5, y: 0.3, skill: true }, 1 / 60); r.events.length = 0 }
      return r
    }
    const r = other()
    assert.strictEqual(r.charge, 0, 'a chapter with no resource must never accrue charge')
    // A chapter with no resource must not have its charge TOUCHED, which is stronger than "stays
    // zero": pond starts at 0 and a drain clamps at 0, so a stepCharge that lost its early-out
    // still measured 0 and passed. Park a value in there and require it to be exactly untouched.
    r.charge = 50
    for (let i = 0; i < 120; i++) { stepSim(r, { x: 0.5, y: 0.3, skill: true }, 1 / 60); r.events.length = 0 }
    assert.strictEqual(r.charge, 50, 'stepCharge must early-out entirely for a chapter with no resource, not merely clamp to zero')
    assert.strictEqual(r.shafts.length, 0, 'a chapter with no shafts signature must stream none')
    assert.strictEqual(r._shaftCellI, undefined, 'the shaft cell cursor must never be written outside a shafts chapter')
  }

  // (h) The Pulse. An EMPTY bar still fires the shipped v5.21 shove — the floor that stops the
  // spiral where having no charge prevents you from earning charge — and a full spend scales both
  // radius and force. The EVENT must carry the SCALED radius: render draws both rings at e.r under
  // a comment saying a burst that lies about its reach makes the cooldown feel arbitrary.
  {
    const empty = mkRun()
    empty.charge = 0
    empty.repulseCd = 0
    stepSim(empty, { x: 0, y: 0, skill: true }, 1 / 60)
    const e0 = empty.events.find((e) => e.type === 'repulse')
    assert.ok(e0, 'an empty bar must still fire the Pulse')
    assert.ok(Math.abs(e0.r - REPULSE_RADIUS) < 1e-9, `an empty bar fires at the shipped floor ${REPULSE_RADIUS}, got ${e0.r}`)
    assert.strictEqual(empty.charge, 0, 'an empty bar spends nothing')

    const full = mkRun()
    full.charge = res.max
    full.repulseCd = 0
    stepSim(full, { x: 0, y: 0, skill: true }, 1 / 60)
    const e1 = full.events.find((e) => e.type === 'repulse')
    assert.ok(e1, 'a full bar must fire the Pulse')
    assert.ok(Math.abs(e1.r - PULSE_RADIUS_AT_FULL) < 1e-9,
      `a full spend must PUSH the scaled radius ${PULSE_RADIUS_AT_FULL}, got ${e1.r} — pushing the constant draws the floor ring around a bigger shove`)
    // The same step also applies one frame of DRAIN, so subtract it rather than widening the band:
    // a tolerance big enough to swallow the drain would also swallow a 3% error in the cost itself.
    const spend = res.max - full.charge - res.drain / 60
    assert.ok(Math.abs(spend - PULSE_CHARGE_COST) < 0.01,
      `a full spend costs exactly ${PULSE_CHARGE_COST} (net of one frame's drain), measured ${spend.toFixed(4)}`)
    assert.ok(e1.r > e0.r, 'a charged pulse must reach further than an empty one, or the bar buys nothing')
  }

  // (i) The Beyond is untouched. It declares no resource, so its t is 0 forever and its pulse must
  // be byte-identical to the shipped one — the lane chapter shares this function and nothing else.
  {
    Math.random = mulberry32(31337)
    const lane = createRun(twilightMeta(), { chapter: 'beyond', difficulty: 1 })
    lane.repulseCd = 0
    stepSim(lane, { x: 0, y: 0, skill: true }, 1 / 60)
    const ev = lane.events.find((e) => e.type === 'repulse')
    assert.ok(ev, 'The Beyond must still fire its repulse')
    assert.ok(Math.abs(ev.r - REPULSE_RADIUS) < 1e-9, `The Beyond's pulse stays at ${REPULSE_RADIUS}, got ${ev.r}`)
    assert.strictEqual(lane.charge, 0, 'The Beyond has no resource and must never accrue charge')
  }

  console.log(`PASS run BL (The Twilight): bar drains/refills/clamps, shafts DRIFT with no cell crossing at exactly ${sig.driftAmp}px and ${(sig.driftAmp * sig.driftHz).toFixed(0)} px/s, RNG-free streaming, empty bar keeps the ${REPULSE_RADIUS}px floor and a full spend pushes ${PULSE_RADIUS_AT_FULL}px, pond and beyond untouched`)
}
run(runTwilight)

// ---- Run RO: PER-ROSTER SOFTENING (v7.x, The Surf's Sea Roach) ---------------------------------
// Owner, 2026-08-17: "The dasher should dash much less often and less far. like 50%. And deal 50%
// less dmg. It's the first level of the book, that's too harsh."
//
// That reason is about ONE CHAPTER, and the dash knobs are global — DASH_IDLE_T and DASH_T are
// shared by pond's tadpole, twilight's krill, reef's tuna and trawl's viperfish as well. So the
// softening is expressed as NEW roster fields (`dash: {restMul, lenMul, spdMul}` and `dmgMul`), and
// the job of this block is to prove they are actually wired AND that they stay put: a per-roster
// override that silently applied to everyone would look identical on The Surf and quietly halve the
// fifth chapter of the book.
//
// spdMul and blocks (f)/(g) are the second customer, and the reason the field is a per-creature
// OBJECT rather than a chapter knob. Owner, 2026-08-17: "Krill dash should be 50% slower and 50%
// less frequent and 50% shorter" — the same shape of request about The Shelf's dasher, landing on
// the same globals, and it must not reach The Surf's roach going the other way either.
function runRoachSoftening() {
  const dt = 1 / 60
  const OVERRIDE = CHAPTERS.surf.roster.find((r) => r.id === 'searoach').dash

  // Two dashers in ONE run, identical but for the override, so the shared clock, the shared seed and
  // the shared frame budget cannot explain any difference between them.
  const pairRun = (softDash = OVERRIDE) => {
    Math.random = mulberry32(7070)
    const run = createRun(makeMeta())
    run.weapons = []
    run.player.x = 0; run.player.y = 0
    const mk = (y, dash) => {
      // x is well inside the default headless viewport (viewW 480 - COMMIT_EDGE_PAD 28 = 452), or
      // the canCommitFrom gate would hold BOTH of them in idle forever and the ratio would read 0/0.
      const e = makeStatusEnemy(run, { x: 300, y, hp: 1e6, speed: 100 })
      e.flags = ['dashBurst']
      e.dash = dash
      run.enemies.push(e)
      return e
    }
    return { run, plain: mk(-200, null), soft: mk(200, softDash) }
  }

  // (a) HALF AS OFTEN AND HALF AS FAR, against a plain dasher in the same run.
  {
    const { run, plain, soft } = pairRun()
    const stat = { plain: { n: 0, d: 0 }, soft: { n: 0, d: 0 } }
    let prevP = 'idle', prevS = 'idle'
    const SECS = 120
    for (let i = 0; i < Math.round(SECS / dt); i++) {
      const p0 = { x: plain.x, y: plain.y }, s0 = { x: soft.x, y: soft.y }
      // Re-park both every frame unless they are mid-dash: this measures the CLOCK and the LUNGE,
      // not how far each one wandered toward the player between dashes.
      stepSim(run, { x: 0, y: 0 }, dt)
      if (plain._dashPhase === 'dash') {
        if (prevP !== 'dash') stat.plain.n++
        stat.plain.d += Math.hypot(plain.x - p0.x, plain.y - p0.y)
      } else { plain.x = 300; plain.y = -200 }
      if (soft._dashPhase === 'dash') {
        if (prevS !== 'dash') stat.soft.n++
        stat.soft.d += Math.hypot(soft.x - s0.x, soft.y - s0.y)
      } else { soft.x = 300; soft.y = 200 }
      prevP = plain._dashPhase; prevS = soft._dashPhase
      run.player.hp = run.player.maxHP
    }
    assert(stat.plain.n > 40, `the control dasher must actually dash (${stat.plain.n} in ${SECS}s) or the ratios below are noise`)
    const rate = stat.soft.n / stat.plain.n
    const len = (stat.soft.d / stat.soft.n) / (stat.plain.d / stat.plain.n)
    // Bands, not equalities: the count is an integer over a finite window and the last dash can be
    // clipped by the end of it. +/-8% is far tighter than the pathologies that matter (an override
    // that does nothing reads 1.00, one applied to the wrong knob reads 1.00 on the other).
    assert(Math.abs(rate - 0.5) < 0.08, `the softened dasher must dash HALF as often, measured ${rate.toFixed(3)} (${stat.soft.n} vs ${stat.plain.n})`)
    assert(Math.abs(len - 0.5) < 0.08, `and lunge HALF as far, measured ${len.toFixed(3)}`)
    console.log(`PASS run RO.a (per-roster dash): ${stat.soft.n} dashes vs ${stat.plain.n} (x${rate.toFixed(2)}), lunge ${(stat.soft.d / stat.soft.n).toFixed(0)}px vs ${(stat.plain.d / stat.plain.n).toFixed(0)}px (x${len.toFixed(2)})`)
  }

  // (b) THE OVERRIDE DOES NOT LEAK. The four other chapters that carry dashBurst must be untouched —
  // this is the assertion that would have caught "soften chapter 1" quietly reaching chapter 5.
  {
    const carriers = Object.entries(CHAPTERS)
      .flatMap(([id, ch]) => (ch.roster ?? []).map((r) => [id, r]))
      .filter(([, r]) => (r.flags ?? []).includes('dashBurst'))
    assert(carriers.length >= 4, `expected several dashBurst carriers, found ${carriers.length}`)
    const overridden = carriers.filter(([, r]) => r.dash || r.dmgMul != null).map(([id, r]) => `${id}/${r.id}`)
    // The EXACT set, sorted so the assertion does not also pin CHAPTERS' key order. Adding a third
    // softened creature is meant to land here first: this line is the tripwire that makes "soften
    // one chapter" impossible to do quietly to a chapter you were not thinking about.
    assert.deepStrictEqual(overridden.slice().sort(), ['surf/searoach', 'twilight/krill'],
      `only The Surf's Sea Roach and The Twilight's Krill may carry the softening; found ${overridden.join(', ') || 'none'}`)
    // And behaviourally: a carrier with no override still runs the shared globals.
    const { run, plain } = pairRun()
    for (let i = 0; i < Math.round(DASH_IDLE_T / dt) + 2; i++) stepSim(run, { x: 0, y: 0 }, dt)
    assert.strictEqual(plain._dashPhase, 'dash',
      `an un-overridden dasher must still commit after the global DASH_IDLE_T (${DASH_IDLE_T}s)`)
    console.log(`PASS run RO.b (no leak): ${carriers.length} dashBurst carriers across the game, ${overridden.length} softened (${overridden.join(', ')}), the rest still on the ${DASH_IDLE_T}s global`)
  }

  // (c) dmgMul HALVES WHAT THE PLAYER LOSES. Asserted as HP off the bar, not as e.dmg, so it covers
  // hurtPlayer's rounding and armor path too — and measured against the SAME roach with the override
  // temporarily lifted, which is the only control that holds the archetype base, the chapter's own
  // balance.enemyDmgMul and the spawn-time damage ramp all fixed.
  //
  // AMP EXISTS BECAUSE hurtPlayer ROUNDS EVERY HIT TO AN INTEGER. Once the chapter cut took the
  // roach's raw swing to 3.061 vs 1.531 (a clean x0.500), Math.round made those 3 and 2 and the
  // measured ratio read x0.667 — the mechanic had not moved, the proxy had run out of resolution.
  // x100 on both arms leaves the ratio invariant, draws no extra randoms (so the same non-elite
  // roach is still pinned) and must be set BEFORE the search loop, since e.dmg is baked at spawn.
  {
    const entry = CHAPTERS.surf.roster.find((r) => r.id === 'searoach')
    const saved = entry.dmgMul
    const AMP = 100
    const bite = () => {
      Math.random = mulberry32(515151)
      const meta = makeMeta(); meta.dev = true; ensureChapterMeta(meta)
      const run = createRun(meta, { chapter: 'surf', difficulty: 1 })
      run.weapons = []
      run.passives.armor = 0
      run.mods.enemyDmgMul *= AMP
      run.player.maxHP = run.player.hp = 1e6
      // A real spawned roach, through the real path: a hand-built one would carry whatever dmg the
      // fixture chose and could not see a missing `roster?.dmgMul` in spawnEnemy at all.
      //
      // `!x.elite` PINS THE SUBJECT, and without it this block measures the wrong thing entirely.
      // "The first searoach in the array" is whatever the spawn phasing hands over, and an elite one
      // carries TWO terms the assertion below is not about: ELITE.dmgMul 1.5, and a volatile death
      // bomb — which detonates on every one of the 600 frames that resurrect it, so its blast
      // dominates the contact damage being measured. Changing EARLY_CALM.surf.spawnMul 0.8 -> 0.6
      // re-phased the draw onto an elite and read x0.873 for an exactly-halved contact hit (306 vs
      // 267 HP: 78 of it the roach, 228 of it bombs). Nothing about that number named its cause.
      let e = null
      for (let i = 0; i < 60 * 150 && !e; i++) {
        stepSim(run, { x: 0, y: 0 }, dt)
        e = run.enemies.find((x) => x.rosterId === 'searoach' && !x.elite) ?? null
      }
      assert.ok(e, 'no ordinary (non-elite) Sea Roach spawned in 150s — cannot measure')
      run.enemies = [e]
      const before = run.player.hp
      for (let i = 0; i < 600; i++) {
        e.x = run.player.x; e.y = run.player.y      // parked on the player: contact every frame
        e._dead = false; e.hp = e.maxHP
        e.stunT = 0; e._dashPhase = 'idle'          // contactHarmless() skips a stunned body
        stepSim(run, { x: 0, y: 0 }, dt)
        if (run.enemies.length !== 1 || run.enemies[0] !== e) run.enemies = [e]
      }
      return before - run.player.hp
    }
    let full, halved
    try {
      entry.dmgMul = 1
      full = bite()
      entry.dmgMul = saved
      halved = bite()
    } finally { entry.dmgMul = saved }
    assert(full > 0, 'the control must actually take damage, or this block proves nothing')
    const ratio = halved / full
    assert(Math.abs(ratio - saved) < 0.08,
      `dmgMul ${saved} must halve what the player loses: ${halved} vs ${full} = x${ratio.toFixed(3)}`)
    console.log(`PASS run RO.c (per-roster damage): ${halved} HP lost vs ${full} with the override lifted = x${ratio.toFixed(2)} (dmgMul ${saved})`)
  }

  // (d) THE OFF-SCREEN REWIND USES THE OVERRIDE TOO. stepDashBurst sets a phase timer in FOUR
  // places, and the one that rewinds the clock while a dasher is out of view is the furthest from
  // the declaration and the easiest to leave reading the global. Nothing above can see it: RO.a
  // keeps both dashers on screen for the whole window, and V.c3's subject carries no override. This
  // block exists because the mutation pass found that hole — a half-applied override would give the
  // roach the SHORT 1.1s wind-up every time it walked into view, i.e. exactly the "arrives already
  // on you" complaint, on the one enemy the wind-up was lengthened for.
  {
    Math.random = mulberry32(313131)
    const run = createRun(makeMeta())
    run.weapons = []
    run.player.x = 0; run.player.y = 0
    const e = makeStatusEnemy(run, { x: 5000, y: 0, hp: 1e6, speed: 100 })
    e.flags = ['dashBurst']
    e.dash = OVERRIDE
    run.enemies.push(e)
    // Out of view long enough that a global-length clock would have rewound several times.
    for (let i = 0; i < Math.round(4 / dt); i++) { stepSim(run, { x: 0, y: 0 }, dt); e.x = 5000; e.y = 0 }
    assert.notStrictEqual(e._dashPhase, 'dash', 'still must not dash from off screen')
    // Now walk it into view and time the wind-up.
    let frames = 0
    for (; frames < Math.round(6 / dt); frames++) {
      e.x = 300; e.y = 0
      stepSim(run, { x: 0, y: 0 }, dt)
      if (e._dashPhase === 'dash') break
    }
    const windUp = frames * dt
    const want = DASH_IDLE_T * OVERRIDE.restMul
    assert(Math.abs(windUp - want) < 0.25,
      `an off-screen softened dasher must rewind to ITS OWN ${want.toFixed(2)}s wind-up, not the ${DASH_IDLE_T}s global — measured ${windUp.toFixed(2)}s`)
    console.log(`PASS run RO.d (rewind honours the override): wound up ${windUp.toFixed(2)}s on entering view, against its own ${want.toFixed(2)}s and the ${DASH_IDLE_T}s global`)
  }

  // (e) A REAL SPAWNED ROACH CARRIES IT. Everything above but (c) hand-sets `e.dash`, so all of it
  // would still pass if spawnEnemy stopped copying `roster.dash` onto the born enemy — the override
  // would be perfect in config, perfect in stepDashBurst, and absent from every roach in the game.
  // Measured as a CADENCE off a creature the chapter spawned for itself, not as a field read.
  {
    Math.random = mulberry32(626262)
    const meta = makeMeta(); meta.dev = true; ensureChapterMeta(meta)
    const run = createRun(meta, { chapter: 'surf', difficulty: 1 })
    run.weapons = []
    run.player.maxHP = run.player.hp = 1e9
    let e = null
    for (let i = 0; i < 60 * 150 && !e; i++) {
      stepSim(run, { x: 0, y: 0 }, dt)
      e = run.enemies.find((x) => x.rosterId === 'searoach') ?? null
    }
    assert.ok(e, 'no Sea Roach spawned in 150s — cannot measure')
    run.enemies = [e]
    e._dashPhase = undefined; e._dashT = undefined
    let dashes = 0, prev = 'idle'
    const SECS = 60
    for (let i = 0; i < Math.round(SECS / dt); i++) {
      if (e._dashPhase !== 'dash') { e.x = run.player.x + 200; e.y = run.player.y }
      stepSim(run, { x: 0, y: 0 }, dt)
      if (e._dashPhase === 'dash' && prev !== 'dash') dashes++
      prev = e._dashPhase
      if (run.enemies.length !== 1 || run.enemies[0] !== e) run.enemies = [e]
      e._dead = false; e.hp = e.maxHP; run.player.hp = run.player.maxHP
    }
    const every = SECS / dashes
    const want = DASH_IDLE_T * OVERRIDE.restMul + DASH_T * OVERRIDE.lenMul
    assert(Math.abs(every - want) < 0.35,
      `a chapter-spawned Sea Roach must dash on ITS OWN ${want.toFixed(2)}s cycle (the global is ${(DASH_IDLE_T + DASH_T).toFixed(2)}s) — measured one every ${every.toFixed(2)}s`)
    console.log(`PASS run RO.e (the spawn path copies it): a chapter-spawned roach dashed ${dashes} times in ${SECS}s = one every ${every.toFixed(2)}s, against its own ${want.toFixed(2)}s and the ${(DASH_IDLE_T + DASH_T).toFixed(2)}s global`)
  }

  // (f) spdMul HALVES THE LUNGE'S SPEED AND LEAVES ITS WINDOW ALONE (v7.x, The Twilight's Krill).
  // Owner, 2026-08-17: "Krill dash should be 50% slower and 50% less frequent and 50% shorter" —
  // three knobs, and the third is new. It is the one easiest to wire to the wrong place, because
  // shrinking the WINDOW instead of the SPEED halves the lunge's distance just as well: a
  // distance-only assertion reads x0.5 either way and proves nothing about which knob moved. So
  // this block measures px-per-dash-frame and the count of dash frames SEPARATELY, on a dasher
  // carrying spdMul alone — whose window must still be the untouched global.
  {
    const { run, plain, soft } = pairRun({ spdMul: 0.5 })
    // Both dashers are re-parked on every non-dash frame, so each idle frame's displacement IS one
    // frame of idle movement. The frame a dash ENDS is skipped (prev === 'dash'): it moved at dash
    // speed and only reads 'idle' afterwards, and folding one 4px frame into ~66 idle frames of
    // 0.67px each is enough to drag the idle ratio to 0.96 and cost the assertion its resolution.
    const st = { plain: { dashN: 0, dashD: 0, idleN: 0, idleD: 0 }, soft: { dashN: 0, dashD: 0, idleN: 0, idleD: 0 } }
    let prevP = 'idle', prevS = 'idle'
    const SECS = 60
    for (let i = 0; i < Math.round(SECS / dt); i++) {
      const p0 = { x: plain.x, y: plain.y }, s0 = { x: soft.x, y: soft.y }
      stepSim(run, { x: 0, y: 0 }, dt)
      const tally = (e, s, prev, px, py, hx, hy) => {
        const moved = Math.hypot(e.x - px, e.y - py)
        if (e._dashPhase === 'dash') { s.dashN++; s.dashD += moved }
        else {
          if (prev !== 'dash') { s.idleN++; s.idleD += moved }
          e.x = hx; e.y = hy
        }
      }
      tally(plain, st.plain, prevP, p0.x, p0.y, 300, -200)
      tally(soft, st.soft, prevS, s0.x, s0.y, 300, 200)
      prevP = plain._dashPhase; prevS = soft._dashPhase
      run.player.hp = run.player.maxHP
    }
    assert(st.plain.dashN > 200, `the control must actually dash (${st.plain.dashN} dash frames in ${SECS}s) or the ratios below are noise`)
    assert(st.plain.idleN > 200, `and must actually idle (${st.plain.idleN} idle frames) or the idle ratio is noise`)
    const spd = (st.soft.dashD / st.soft.dashN) / (st.plain.dashD / st.plain.dashN)
    const window = st.soft.dashN / st.plain.dashN
    const idle = (st.soft.idleD / st.soft.idleN) / (st.plain.idleD / st.plain.idleN)
    assert(Math.abs(spd - 0.5) < 0.04, `spdMul must HALVE the lunge's speed, measured x${spd.toFixed(3)} px/frame`)
    assert(Math.abs(window - 1) < 0.08,
      `and must NOT touch its window — dash frames read x${window.toFixed(3)}, so it is wired to the timer instead of the speed`)
    assert(Math.abs(idle - 1) < 0.02,
      `and must NOT touch the wind-up — idle speed read x${idle.toFixed(3)}, so it reached the idle branch (and with it the off-screen walk-in, which has to stay at full speed or the crowd crawls out of sight)`)
    console.log(`PASS run RO.f (spdMul is the LUNGE's speed knob): ${(st.soft.dashD / st.soft.dashN).toFixed(2)} px/frame vs ${(st.plain.dashD / st.plain.dashN).toFixed(2)} (x${spd.toFixed(2)}), same window (x${window.toFixed(2)}), same wind-up (x${idle.toFixed(2)})`)
  }

  // (g) THE KRILL'S SHIPPED NUMBERS DELIVER ALL THREE HALVINGS. Everything above proves the three
  // knobs are WIRED; this proves the values actually in config.js use them. The override is read
  // from CHAPTERS, never retyped, so dropping one of the three from the roster entry lands here —
  // and nothing else would notice, since RO.b only asks whether a `dash` object exists at all.
  {
    const KRILL = CHAPTERS.twilight.roster.find((r) => r.id === 'krill').dash
    const { run, plain, soft } = pairRun(KRILL)
    const st = { plain: { n: 0, d: 0, f: 0 }, soft: { n: 0, d: 0, f: 0 } }
    let prevP = 'idle', prevS = 'idle'
    const SECS = 120
    for (let i = 0; i < Math.round(SECS / dt); i++) {
      const p0 = { x: plain.x, y: plain.y }, s0 = { x: soft.x, y: soft.y }
      stepSim(run, { x: 0, y: 0 }, dt)
      if (plain._dashPhase === 'dash') { st.plain.f++; st.plain.d += Math.hypot(plain.x - p0.x, plain.y - p0.y); if (prevP !== 'dash') st.plain.n++ }
      else { plain.x = 300; plain.y = -200 }
      if (soft._dashPhase === 'dash') { st.soft.f++; st.soft.d += Math.hypot(soft.x - s0.x, soft.y - s0.y); if (prevS !== 'dash') st.soft.n++ }
      else { soft.x = 300; soft.y = 200 }
      prevP = plain._dashPhase; prevS = soft._dashPhase
      run.player.hp = run.player.maxHP
    }
    assert(st.plain.n > 40, `the control dasher must actually dash (${st.plain.n} in ${SECS}s) or the ratios below are noise`)
    const rate = st.soft.n / st.plain.n
    const spd = (st.soft.d / st.soft.f) / (st.plain.d / st.plain.f)
    const reach = (st.soft.d / st.soft.n) / (st.plain.d / st.plain.n)
    assert(Math.abs(rate - 0.5) < 0.08, `the krill must dash HALF as often, measured x${rate.toFixed(3)}`)
    assert(Math.abs(spd - 0.5) < 0.04, `and HALF as fast, measured x${spd.toFixed(3)} px/frame`)
    // The three compound: half the speed for half the window is a QUARTER of the distance. Asserted
    // explicitly because it is the surprising half of the owner's ask and the number worth reading.
    assert(Math.abs(reach - 0.25) < 0.05, `and lunge a QUARTER as far (half speed x half window), measured x${reach.toFixed(3)}`)
    console.log(`PASS run RO.g (the krill's shipped tune): one dash every ${(SECS / st.soft.n).toFixed(2)}s vs ${(SECS / st.plain.n).toFixed(2)}s (x${rate.toFixed(2)}), at x${spd.toFixed(2)} speed, lunging ${(st.soft.d / st.soft.n).toFixed(0)}px vs ${(st.plain.d / st.plain.n).toFixed(0)}px (x${reach.toFixed(2)})`)
  }

  console.log('PASS run RO (per-roster softening): the roster can soften ONE creature\'s dash cadence, reach, SPEED and damage without moving the shared DASH_* globals or the chapter\'s balance block')
}
run(runRoachSoftening)

// ---- Run SK: THE SHOREBREAK (v7.x, The Surf's skill button) ------------------------------------
// SK and not SB: `run SB` is already the SUBMISSION ally block, and two unrelated groups sharing a
// prefix makes a red band in the output unreadable at exactly the moment you need to read it.
// The Surf's skill button used to fire the Pulse — one frame of shove, then a 6s cooldown. Owner,
// 2026-08-16: it "should be revamped to a bubble shield or wave shield that lasts for a bit so the
// player can go through a wall of circling enemies", then picked the wave over the bubble. So it is
// now a crest that rides with the player for a duration the spend buys, pushing and staggering what
// it touches on every frame it is live — and, uniquely among the four chapter buttons, REPLACING
// the shove rather than riding along with it.
//
// Every block below asserts where the BODIES ended up. A _shorebreakT that counts down is exactly
// what a deleted push would also do, so the timer is never the subject.
function runShorebreak() {
  const RES = CHAPTERS.surf.resource
  const sbMeta = () => { const m = makeMeta(); m.dev = true; ensureChapterMeta(m); return m }
  const dt = 1 / 60

  // A ring of bodies well inside SHOREBREAK_RADIUS, all walking at the player. THE SPEED IS THE
  // POINT: against a stationary crowd any push at all "opens a corridor", so a fixture like that
  // would pass with the force at a tenth of its value. A crowd closing at 120px/s means the wave has
  // to beat their approach before the measurement moves at all.
  const ringRun = (charge) => {
    Math.random = mulberry32(20260816)
    const run = createRun(sbMeta(), { chapter: 'surf', difficulty: 1 })
    run.weapons = []
    run.player.maxHP = run.player.hp = 1e9
    run.enemies.length = 0
    const ids = []
    for (let i = 0; i < 8; i++) {
      const a = (i / 8) * Math.PI * 2
      const e = makeStatusEnemy(run, {
        x: run.player.x + Math.cos(a) * 150,
        y: run.player.y + Math.sin(a) * 150,
        hp: 1e6, speed: 120,
      })
      run.enemies.push(e)
      ids.push(e.id)
    }
    run.charge = charge
    run.repulseCd = 0
    return { run, ids }
  }
  // Measured from the PLAYER every time, never from a fixed origin: the tide shoves the player
  // sideways all run (signature.surge 46px/s), so an origin-relative distance would be reading the
  // chapter's own current as if it were the button.
  const meanDist = (o) => {
    const p = o.run.player
    const ds = o.ids.map((id) => o.run.enemies.find((e) => e.id === id)).filter(Boolean)
      .map((e) => Math.hypot(e.x - p.x, e.y - p.y))
    return ds.reduce((a, b) => a + b, 0) / Math.max(1, ds.length)
  }
  const advance = (o, secs, press) => {
    let first = true
    for (let i = 0; i < Math.round(secs / dt); i++) {
      stepSim(o.run, { x: 0, y: 0, skill: press && first }, dt)
      first = false
    }
  }

  // (a) IT OPENS A CORRIDOR, against a do-nothing control. The control is not ceremony: without it
  // "the crowd ended up 250px away" is unreadable, because that is also roughly where an untouched
  // ring of seekers ends up if the fixture forgot to make them walk.
  {
    const ctl = ringRun(RES.max)
    const before = meanDist(ctl)
    advance(ctl, SHOREBREAK_DUR_AT_FULL, false)
    const ctlAfter = meanDist(ctl)

    const hit = ringRun(RES.max)
    advance(hit, SHOREBREAK_DUR_AT_FULL, true)
    const hitAfter = meanDist(hit)

    assert(ctlAfter < before - 20,
      `the control must CLOSE on the player (${before.toFixed(0)} -> ${ctlAfter.toFixed(0)}px) or this fixture proves nothing`)
    // Stated as a FRACTION OF THE CREST, never in px. The claim being made is "the crowd ends up out
    // near the rim instead of on top of you", and that is what these two say at any radius — a px
    // literal would have had to be retuned when SHOREBREAK_RADIUS moved 300 -> 190, which is exactly
    // the moment a band stops meaning anything and starts being a number that makes the test green.
    assert(hitAfter > SHOREBREAK_RADIUS * 0.8,
      `the Shorebreak must hold the crowd out near its rim: ${hitAfter.toFixed(0)}px against a ${SHOREBREAK_RADIUS}px crest`)
    assert(hitAfter > ctlAfter + SHOREBREAK_RADIUS * 0.5,
      `the Shorebreak must open a corridor: pressed ${hitAfter.toFixed(0)}px vs control ${ctlAfter.toFixed(0)}px`)
    console.log(`PASS run SK.a (corridor): ring at ${before.toFixed(0)}px -> control ${ctlAfter.toFixed(0)}px, pressed ${hitAfter.toFixed(0)}px`)
  }

  // (b) IT IS SUSTAINED, NOT AN IMPULSE — the whole reason it is not just a bigger Pulse. Most of the
  // push must land AFTER the frame the button went down. This is the block that fails if someone
  // "simplifies" the per-frame acceleration back into a one-shot kb impulse, which is a change no
  // duration assertion and no event assertion can see.
  {
    const o = ringRun(RES.max)
    const start = meanDist(o)
    stepSim(o.run, { x: 0, y: 0, skill: true }, dt)
    const afterFirst = meanDist(o)
    advance(o, SHOREBREAK_DUR_AT_FULL - dt, false)
    const afterRest = meanDist(o)
    const firstFrame = afterFirst - start
    const rest = afterRest - afterFirst
    assert(rest > firstFrame * 5,
      `the push must be sustained, not an impulse: frame 1 moved ${firstFrame.toFixed(1)}px, the remaining ${SHOREBREAK_DUR_AT_FULL}s moved ${rest.toFixed(1)}px`)
    console.log(`PASS run SK.b (sustained): frame 1 ${firstFrame.toFixed(1)}px vs ${rest.toFixed(0)}px over the rest of the window`)
  }

  // (c) THE NO-SPIRAL FLOOR (spec §8.2). An EMPTY bar still gets a crest — shorter, never absent.
  // Without this, running dry in a chapter whose bar ALSO multiplies your damage would leave a
  // player with no answer and no way to earn one.
  {
    const ctl = ringRun(0)
    advance(ctl, SHOREBREAK_DUR_MIN, false)
    const ctlAfter = meanDist(ctl)
    const hit = ringRun(0)
    advance(hit, SHOREBREAK_DUR_MIN, true)
    const hitAfter = meanDist(hit)
    assert.strictEqual(hit.run.charge, 0, 'an empty bar spends nothing')
    assert(hitAfter > ctlAfter + SHOREBREAK_RADIUS * 0.25,
      `an empty bar must still push: ${hitAfter.toFixed(0)}px vs control ${ctlAfter.toFixed(0)}px`)
    console.log(`PASS run SK.c (empty-bar floor): ${hitAfter.toFixed(0)}px vs control ${ctlAfter.toFixed(0)}px over the ${SHOREBREAK_DUR_MIN}s floor`)
  }

  // (d) THE SPEND BUYS DURATION. Both measured over the SAME long window, so the only thing that can
  // separate them is how much of that window the crest was alive for.
  {
    const win = SHOREBREAK_DUR_AT_FULL + 0.4
    const empty = ringRun(0)
    advance(empty, win, true)
    const full = ringRun(RES.max)
    advance(full, win, true)
    assert(meanDist(full) > meanDist(empty) + SHOREBREAK_RADIUS * 0.4,
      `a full spend must push for longer than an empty bar: ${meanDist(full).toFixed(0)}px vs ${meanDist(empty).toFixed(0)}px`)
    console.log(`PASS run SK.d (spend buys duration): empty ${meanDist(empty).toFixed(0)}px, full ${meanDist(full).toFixed(0)}px over one ${win.toFixed(1)}s window`)
  }

  // (e) IT REPLACES THE PULSE, and only in this chapter. The Surf must emit no `repulse` at all —
  // if it did, the player would get an 880px/s impulse AND the crest on one press, and would hear
  // the shove's sample twice over. The Beyond shares stepRepulse and must be untouched.
  {
    const o = ringRun(RES.max)
    stepSim(o.run, { x: 0, y: 0, skill: true }, dt)
    const sb = o.run.events.find((e) => e.type === 'shorebreak')
    assert.ok(sb, 'The Surf must emit a shorebreak event on the press')
    assert.ok(Math.abs(sb.r - SHOREBREAK_RADIUS) < 1e-9, `the event must carry the real radius ${SHOREBREAK_RADIUS}, got ${sb.r}`)
    assert.ok(!o.run.events.some((e) => e.type === 'repulse'),
      'The Surf must NOT also fire the Pulse — the Shorebreak replaces it')

    Math.random = mulberry32(31337)
    const lane = createRun(sbMeta(), { chapter: 'beyond', difficulty: 1 })
    lane.repulseCd = 0
    stepSim(lane, { x: 0, y: 0, skill: true }, dt)
    assert.ok(lane.events.some((e) => e.type === 'repulse'), 'The Beyond must still fire its repulse')
    assert.ok(!lane.events.some((e) => e.type === 'shorebreak'), 'only a `shorebreak` chapter may fire one')
    console.log(`PASS run SK.e (replaces the Pulse): surf emits shorebreak r=${sb.r} and no repulse; beyond unchanged`)
  }

  // (f) ALLIES ARE NOT STAGGERED. A deliberate divergence from the Pulse, which shoves everything in
  // run.enemies: a shove is a shrug, but a stagger REFRESHED every frame for up to 2.4s would switch
  // your own summon off for the whole window, and a button that disables your allies is one you
  // learn not to press near them.
  {
    const o = ringRun(RES.max)
    const ally = makeStatusEnemy(o.run, { x: o.run.player.x + 60, y: o.run.player.y, hp: 1e6, speed: 0 })
    ally.allyT = 99
    o.run.enemies.push(ally)
    for (let i = 0; i < 20; i++) stepSim(o.run, { x: 0, y: 0, skill: i === 0 }, dt)
    const a = o.run.enemies.find((e) => e.id === ally.id)
    assert.ok(a, 'the ally must survive the window')
    assert.ok((a.stunT ?? 0) <= 0, `an ally must not be staggered by your own Shorebreak (stunT=${(a.stunT ?? 0).toFixed(2)})`)
    const foe = o.run.enemies.find((e) => o.ids.includes(e.id))
    assert.ok((foe.stunT ?? 0) > 0, 'a non-ally inside the crest must be staggered, or this block is vacuous')
    console.log(`PASS run SK.f (allies spared): ally stunT=${(a.stunT ?? 0).toFixed(2)}, enemy stunT=${(foe.stunT ?? 0).toFixed(2)} of ${SHOREBREAK_STAGGER}`)
  }

  console.log(`PASS run SK (The Shorebreak): opens a corridor a walking crowd cannot close, sustained rather than impulsive, ${SHOREBREAK_DUR_MIN}s floor on an empty bar rising to ${SHOREBREAK_DUR_AT_FULL}s, replaces the Pulse in surf only, spares allies`)
}
run(runShorebreak)
// ---- run CL: The Shelf's Clear (2026-08-20) ---------------------------------------------------
// The chapter's second verb, and the last one in Book 2 to get one. Three things happen on the
// press and each is asserted against a CONTROL CHAPTER running the identical rig — The Twilight,
// which has the same bar, the same `shafts` signature and the same dark block, and no `clear`.
// Without that control every block below would pass on the plain Pulse.
//
// THE ONE THIS SCENARIO EXISTS FOR IS (c). Design spec §6.2 warned that "blows wide and everything
// it reaches is stunned" is so close to what REPULSE_STUN already does that a `clear` branch which
// never fired would be nearly indistinguishable in play from one that worked — so the reach and the
// stagger alone are not enough of a test, and are not enough of a button. Sight is the payload.
function runClear() {
  const dt = 1 / 60
  const devMeta = () => { const m = makeMeta(); m.dev = true; ensureChapterMeta(m); return m }
  const RES = CHAPTERS.shelf.resource

  // A ring of INERT bodies — speed 0 — so the only thing that can move them is the shove. SK's
  // fixture deliberately walks its crowd, because a sustained crest has to beat their approach to
  // prove anything; this button is an impulse, so a walking crowd would just add its own closing
  // speed to both sides of every comparison and blunt the one number being measured.
  const ringRun = (chapter, charge, dist) => {
    Math.random = mulberry32(20260820)
    const run = createRun(devMeta(), { chapter, difficulty: 1 })
    run.weapons = []
    run.player.maxHP = run.player.hp = 1e9
    run.enemies.length = 0
    const ids = []
    for (let i = 0; i < 8; i++) {
      const a = (i / 8) * Math.PI * 2
      const e = makeStatusEnemy(run, {
        x: run.player.x + Math.cos(a) * dist,
        y: run.player.y + Math.sin(a) * dist,
        hp: 1e6, speed: 0,
      })
      run.enemies.push(e)
      ids.push(e.id)
    }
    run.charge = charge
    run.repulseCd = 0
    return { run, ids }
  }
  const meanDist = (o) => {
    const p = o.run.player
    const ds = o.ids.map((id) => o.run.enemies.find((e) => e.id === id)).filter(Boolean)
      .map((e) => Math.hypot(e.x - p.x, e.y - p.y))
    return ds.reduce((a, b) => a + b, 0) / Math.max(1, ds.length)
  }
  const advance = (o, secs, press) => {
    let first = true
    for (let i = 0; i < Math.round(secs / dt); i++) {
      stepSim(o.run, { x: 0, y: 0, skill: press && first }, dt)
      first = false
    }
  }

  // (a) IT REACHES PAST THE PULSE. The ring sits at 700px: inside CLEAR_RADIUS_AT_FULL (820) and
  // OUTSIDE PULSE_RADIUS_AT_FULL (620), so on a full bar The Shelf touches it and the control
  // chapter cannot. Stated as "did the bodies move at all", never as a px band — the band would
  // have to be retuned the moment either constant does, which is when a test stops meaning
  // anything and starts being a number that makes itself green.
  {
    assert(CLEAR_RADIUS_AT_FULL > 700 && PULSE_RADIUS_AT_FULL < 700,
      `this fixture's 700px ring only separates the two buttons while ${PULSE_RADIUS_AT_FULL} < 700 < ${CLEAR_RADIUS_AT_FULL}`)
    const shelf = ringRun('shelf', RES.max, 700)
    const before = meanDist(shelf)
    advance(shelf, 0.5, true)
    const shelfAfter = meanDist(shelf)

    const ctl = ringRun('twilight', CHAPTERS.twilight.resource.max, 700)
    advance(ctl, 0.5, true)
    const ctlAfter = meanDist(ctl)

    assert(Math.abs(ctlAfter - before) < 1,
      `the control must NOT reach 700px with a ${PULSE_RADIUS_AT_FULL}px Pulse (moved to ${ctlAfter.toFixed(1)}px) or this block proves nothing`)
    assert(shelfAfter > before + 20,
      `the Clear must reach the 700px ring: ${before.toFixed(0)} -> ${shelfAfter.toFixed(0)}px`)
    console.log(`PASS run CL.a (reaches past the Pulse): ring at 700px -> shelf ${shelfAfter.toFixed(0)}px, twilight control ${ctlAfter.toFixed(0)}px`)
  }

  // (b) IT STAGGERS FOR LONGER. Read off e.stunT, which is the SHIPPED contract field the enemy
  // step and render.js both already gate on — so a longer number here is a longer pose on screen
  // and a longer hole in the crowd, not a private counter.
  {
    const shelf = ringRun('shelf', RES.max, 200)
    advance(shelf, dt, true)
    const ctl = ringRun('twilight', CHAPTERS.twilight.resource.max, 200)
    advance(ctl, dt, true)
    const sStun = shelf.run.enemies.find((e) => shelf.ids.includes(e.id)).stunT
    const cStun = ctl.run.enemies.find((e) => ctl.ids.includes(e.id)).stunT
    // Both are read one frame AFTER the press, so both have already had one dt ticked off them —
    // compare against that, not against the raw constant, or the band is a frame-rate literal.
    assert(cStun > REPULSE_STUN - 2 * dt && cStun <= REPULSE_STUN, `the control must carry the shipped ${REPULSE_STUN}s stagger, got ${cStun}`)
    assert(sStun > cStun * 1.5, `the Clear must stagger materially longer: ${sStun}s vs the Pulse's ${cStun}s`)
    console.log(`PASS run CL.b (staggers longer): shelf ${sStun}s vs twilight ${cStun}s`)
  }

  // (c) THE MURK OPENS — the block this scenario exists for, and the only one that can tell a live
  // Clear from a dead one in play. Measured through lightRadius() itself, the function render.js
  // feeds run.sightCharge to, on a phone's longest side: asserting the FIELD would pass on a value
  // no renderer ever reads, which is the frozen-enemies scar exactly.
  //
  // On an EMPTY bar, specifically. That is when the murk is at its worst (radiusEmpty 0.1) and when
  // a chapter whose bar is sight most needs a way out — and it is the no-spiral floor doing real
  // work rather than a formality: the button hands a blinded player the sight to go find water.
  {
    const maxDim = 844
    const seeing = (run) => lightRadius(run.sightCharge ?? run.charge, CHAPTERS[run.chapter].resource, maxDim, run.chargeMax)
    const barAlone = (run) => lightRadius(run.charge, CHAPTERS[run.chapter].resource, maxDim, run.chargeMax)

    const shelf = ringRun('shelf', 0, 200)
    const blind = barAlone(shelf.run)
    advance(shelf, dt, true)
    assert(shelf.run._clearT > 0, 'an empty bar must still part the murk — the no-spiral floor')
    assert(seeing(shelf.run) > blind * 3,
      `the Clear must open the water: ${blind.toFixed(0)}px blind -> ${seeing(shelf.run).toFixed(0)}px`)

    const ctl = ringRun('twilight', 0, 200)
    advance(ctl, dt, true)
    assert(Math.abs(seeing(ctl.run) - barAlone(ctl.run)) < 1e-9,
      'only a `clear` chapter may lend sight — the control chapter sees exactly its bar')
    console.log(`PASS run CL.c (the murk opens): empty bar ${blind.toFixed(0)}px -> ${seeing(shelf.run).toFixed(0)}px on a ${maxDim}px screen; twilight unchanged at ${seeing(ctl.run).toFixed(0)}px`)
  }

  // (d) AND IT CLOSES AGAIN, easing rather than snapping. The cost of this button is paid here and
  // nowhere else: the spend came off the bar while the window was hiding it, so when the water
  // closes it closes to a WORSE reading than the press started from. A window that never ended
  // would be a chapter that had quietly lost its antagonist.
  {
    const o = ringRun('shelf', RES.max, 200)
    advance(o, dt, true)
    const opened = o.run.sightCharge
    advance(o, CLEAR_DUR_AT_FULL - CLEAR_SIGHT_FADE, false)
    assert(o.run.sightCharge > o.run.charge, 'the window must still be lending sight before the fade begins')
    const mid = o.run.sightCharge
    advance(o, CLEAR_SIGHT_FADE + 0.1, false)
    assert.strictEqual(o.run._clearT, 0, 'the window must close')
    assert.strictEqual(o.run.sightCharge, o.run.charge, 'once closed, what you see IS the bar')
    assert(o.run.charge < opened, `the spend must leave the water murkier than the press found it: ${o.run.charge.toFixed(1)} vs ${opened.toFixed(1)}`)
    console.log(`PASS run CL.d (closes again): ${opened.toFixed(0)} -> ${mid.toFixed(0)} -> ${o.run.sightCharge.toFixed(0)}, bar ${o.run.charge.toFixed(0)}`)
  }

  // (e) ONE PRESS, ONE EVENT, AND IT TELLS THE TRUTH ABOUT ITS REACH. The Clear pushes no event of
  // its own on purpose — a second one would draw a second ring on the same frame and play the
  // shove's sample twice, which is the complaint run SK.e pins for The Surf. What makes that
  // choice safe is this: the `repulse` it does emit must carry the WIDENED radius, because
  // render.js draws the ring at e.r and "a burst that lies about its reach makes the cooldown feel
  // arbitrary" is the shipped comment on that line.
  {
    const o = ringRun('shelf', RES.max, 200)
    advance(o, dt, true)
    const rs = o.run.events.filter((e) => e.type === 'repulse')
    assert.strictEqual(rs.length, 1, `one press must emit exactly one repulse, got ${rs.length}`)
    assert(Math.abs(rs[0].r - CLEAR_RADIUS_AT_FULL) < 1e-6,
      `the ring must be drawn at the Clear's real reach ${CLEAR_RADIUS_AT_FULL}, got ${rs[0].r}`)
    assert(!o.run.events.some((e) => e.type === 'clear'),
      'the Clear emits no event of its own — if you add one, give it a render case and an SFX entry and delete this line')

    // The floor is the DURATION, never the reach: an empty bar throws the shipped 340px shove here
    // exactly as it does in every other chapter, so the widening is bought and not granted.
    const empty = ringRun('shelf', 0, 200)
    advance(empty, dt, true)
    const er = empty.run.events.find((e) => e.type === 'repulse')
    assert(Math.abs(er.r - REPULSE_RADIUS) < 1e-6, `an empty bar must throw the shipped ${REPULSE_RADIUS}px shove, got ${er.r}`)
    assert(empty.run._clearT > CLEAR_DUR_MIN - 2 * dt && empty.run._clearT <= CLEAR_DUR_MIN,
      `an empty bar's window must be the ${CLEAR_DUR_MIN}s floor, got ${empty.run._clearT}`)
    console.log(`PASS run CL.e (one honest ring): full bar r=${rs[0].r} clearT=${o.run._clearT.toFixed(2)}s, empty bar r=${er.r} clearT=${empty.run._clearT.toFixed(2)}s, no second event`)
  }

  // (f) EVERY OTHER CHAPTER IS BYTE-IDENTICAL. sightCharge is the one field here that is written
  // outside The Shelf — stepCharge sets it in every chapter with a resource — so this is the block
  // that catches it drifting away from the bar somewhere it was never meant to.
  {
    const others = ['surf', 'reef', 'trawl', 'twilight', 'deep']
    for (const id of others) {
      Math.random = mulberry32(4242)
      const run = createRun(devMeta(), { chapter: id, difficulty: 1 })
      run.repulseCd = 0
      run.charge = CHAPTERS[id].resource.max
      for (let i = 0; i < 30; i++) stepSim(run, { x: 0, y: 0, skill: i === 0 }, dt)
      assert.strictEqual(run.sightCharge, run.charge, id + ' must see exactly its bar — only a `clear` chapter lends sight')
      assert.strictEqual(run._clearT, 0, id + ' must never arm a Clear window')
    }
    console.log(`PASS run CL.f (${others.length} other Undertow chapters unchanged): sightCharge === charge, no window armed`)
  }

  console.log(`PASS run CL (The Clear): reaches ${CLEAR_RADIUS_AT_FULL}px against the Pulse's ${PULSE_RADIUS_AT_FULL}, staggers ${CLEAR_STUN}s against ${REPULSE_STUN}, opens the murk for ${CLEAR_DUR_MIN}-${CLEAR_DUR_AT_FULL}s and eases shut over ${CLEAR_SIGHT_FADE}s, one honest ring, 5 other chapters untouched`)
}
run(runClear)
// ---- run MB: the mod budget in Book 2's first two chapters (2026-08-19) ------------------------
// The Surf shipped four mods per weapon; The Shelf shipped 2/0/0, its two zone weapons carrying NO
// mods at all — so the chapter could offer exactly two distinct mod cards in a whole run and its
// mod bucket measured 20.4% against a declared 27.9%. This guards the cards that closed that gap.
//
// EVERY BLOCK HERE FAILS SILENTLY WITHOUT IT, which is the only reason each one exists:
//   .a a card wired into no table and read at no fire site is INERT — it is offered, picked, banked
//      and does nothing, and nothing throws.
//   .b a rate mod folded into an interval through WEAPON_STAT_MODS SLOWS the weapon. The card says
//      "+25% drop rate" and the weapon fires less often; only a direction assertion sees it.
//   .c a per-cast count written twice (loop bound AND spacing divisor) that moves only the bound
//      spawns its extras ON TOP of each other, which renders identically to no change at all. So
//      this asserts DISTINCT POSITIONS, never a count — a count passes happily when things stack.
//   .d/.f a pollution mod reads run.charge, which counts CLARITY and is only display-inverted. Get
//      the sense backwards and the card pays out in clean water instead of filthy — a sign error
//      that still produces a working, plausible-looking weapon.
//   .e Backblow's second nova carries its own once-per-body hit set, so letting it fire when the
//      cone is already past a half-turn turns a coverage card into a silent damage doubler.
function runModBudget() {
  const dt = 1 / 60
  const mkMeta = () => { const m = makeMeta(); m.dev = true; ensureChapterMeta(m); return m }
  // No enemies and no spawning: every block below measures what a CAST produces, and a crowd would
  // only re-phase the RNG between the two sides of each comparison.
  const boot = (chapter, id, level, mods, charge) => {
    Math.random = mulberry32(20260819)
    const run = createRun(mkMeta(), { chapter, difficulty: 1 })
    run.weapons = [{ id, level }]
    run.player.maxHP = run.player.hp = 1e9
    run.mods.spawnMul = 0
    run.enemies.length = 0
    if (mods) Object.assign(run.weaponMods[id], mods)
    if (charge != null) run.charge = charge
    return run
  }
  // STEP UNTIL THE WEAPON ACTUALLY CASTS, never for a fixed slice: fireOnTimer fires after a full
  // interval, and these six weapons' intervals span 0.6s to 4.4s. A fixed 0.05s advance measured an
  // empty world and read as "the mod does nothing" — which is precisely the failure every block
  // below is trying to catch, arriving from the fixture instead of from the code.
  //
  // `onStep` re-pins whatever the sim would otherwise drift: run.charge drains 2.2/s here, so a
  // clean-water measurement taken after one cast is not clean water any more, and streamShafts
  // rewrites run.shafts every frame around the player.
  const advance = (run, secs, onStep) => {
    for (let i = 0; i < Math.round(secs / dt); i++) { if (onStep) onStep(run); stepSim(run, { x: 0, y: 0 }, dt) }
  }
  const castUntil = (run, pred, onStep, maxSecs = 12) => {
    for (let i = 0; i < Math.round(maxSecs / dt); i++) {
      if (onStep) onStep(run)
      stepSim(run, { x: 0, y: 0 }, dt)
      if (pred(run)) return true
    }
    return false
  }
  const SHELF_MAX = CHAPTERS.shelf.resource.max
  const pin = (charge) => (run) => { run.chargeMax = SHELF_MAX; run.charge = charge }
  // ONE DOWNWASH COLUMN, MEASURED BY ITS BURST rather than by run.holes. Watching the array is a
  // fixture bug waiting to happen: a column that plunges the frame it lands is created and retired
  // inside one stepSim, so `run.holes.length > 0` is never true from outside and a working mod
  // reads as a weapon that never fired. The `downwash` and `explode` events are the honest clock.
  // Returns the gap between the cast and the FIRST burst, and how many bursts one column produced.
  const burstOf = (mods, bodies) => {
    const r = boot('shelf', 'downwash', 5, mods)
    for (let i = 0; i < bodies; i++) {
      r.enemies.push(makeStatusEnemy(r, { x: r.player.x + 260 + i * 10, y: r.player.y + i * 8, hp: 1e6, speed: 0 }))
    }
    r.events.length = 0
    let castT = null, firstT = null, lastT = null, n = 0, t = 0
    while (t < 20) {
      stepSim(r, { x: 0, y: 0 }, dt)
      if (castT === null && r.events.some((e) => e.type === 'downwash')) castT = t
      if (castT !== null) {
        const booms = r.events.filter((e) => e.type === 'explode').length
        if (booms > 0 && firstT === null) firstT = t
        if (booms > 0) lastT = t
        n += booms
      }
      r.events.length = 0
      t += dt
      // One column's whole life plus a margin, counted from the cast — so a second cast's burst
      // can never be mistaken for the first column detonating twice.
      if (castT !== null && t > castT + WEAPONS.downwash.levels[4].duration + 0.4) break
    }
    assert(castT !== null, 'precondition: the downwash must cast within 20s')
    return { delay: firstT === null ? Infinity : firstT - castT, lastDelay: lastT === null ? Infinity : lastT - castT, bursts: n, dur: WEAPONS.downwash.levels[4].duration }
  }

  // (a) NO INERT CARDS, across every weapon in the game rather than only the six that changed.
  // The check is a source-text one (the run UG.k trick) because WEAPON_STAT_MODS is private to
  // sim.js: a mod is live if it folds a stat, divides an interval, or is named at a fire site.
  // Denominator printed, per CLAUDE.md — a sweep whose count nobody checks is how run RA passed
  // over a chapter it could not see.
  {
    // COMMENTS STRIPPED FIRST, and that is not tidiness. Every mod id in this file is also discussed
    // in prose right beside its wiring, so a plain substring search over the RAW source is satisfied
    // by the comment alone: delete a WEAPON_STAT_MODS entry, leave the sentence that explains it,
    // and the card goes inert while this block stays green. That exact edit is mutation 7 in the
    // proof run, and it passed until this line existed.
    const simSrc = readFileSync(new URL('../src/sim.js', import.meta.url), 'utf8')
      .replace(/\/\*[\s\S]*?\*\//g, ' ').replace(/\/\/[^\n]*/g, ' ')
    const dead = []
    let checked = 0
    for (const [wid, mods] of Object.entries(WEAPON_MODS)) {
      for (const mid of Object.keys(mods)) {
        checked++
        // Named anywhere in sim.js — as a WEAPON_STAT_MODS key, or read off run.weaponMods at its
        // own site — or registered as this weapon's rate mod in config's own table.
        if (simSrc.includes(mid) || WEAPON_RATE_MODS[wid] === mid) continue
        dead.push(`${wid}.${mid}`)
      }
    }
    assert.deepStrictEqual(dead, [], `weapon mods that no sim.js site reads (they ship as inert cards): ${dead.join(', ')}`)
    console.log(`PASS run MB.a (no inert cards): all ${checked} weapon mods across ${Object.keys(WEAPON_MODS).length} weapons resolve to a fold, a rate division or a fire site`)
  }

  // (a2) The budget itself: every Book 2 chapter that has authored its own arsenal carries at
  // least four mods per weapon, and The Shelf's two zone weapons are no longer empty. A literal
  // floor, not a moving one — the pathology being guarded is a weapon shipping with none, which is
  // what happened. The Reef joined the day its natives landed, not the day someone noticed.
  {
    const rows = []
    for (const ch of ['surf', 'shelf', 'reef']) {
      for (const wid of CHAPTERS[ch].weapons) {
        const n = Object.keys(WEAPON_MODS[wid] ?? {}).length
        rows.push(`${wid} ${n}`)
        assert(n >= 4, `${ch}.${wid} carries ${n} mods; Book 2's budget is ~4 apiece and a weapon with fewer starves its chapter's mod bucket`)
      }
    }
    console.log(`PASS run MB.a2 (budget): ${rows.join(', ')}`)
  }

  // (b) BOTH RATE MODS SPEED THE WEAPON UP. Direction only — the magnitude is config's business.
  {
    for (const [chapter, id, mod, level] of [['surf', 'breaker', 'quickBreak', 5], ['shelf', 'ballast', 'quickWinch', 5]]) {
      const count = (mods) => {
        const run = boot(chapter, id, level, mods)
        let fires = 0
        for (let i = 0; i < Math.round(12 / dt); i++) {
          stepSim(run, { x: 0, y: 0 }, dt)
          fires += run.events.filter((e) => e.type === 'shoot' || e.type === 'ballast').length
          run.events.length = 0
        }
        return fires
      }
      const base = count(null)
      const fast = count({ [mod]: 1 })
      assert(base > 0, `precondition: ${id} must fire at all over 12s, got ${base}`)
      assert(fast > base, `${mod} must make ${id} fire MORE often, not less — folding a rate pick into an interval slows the weapon (base ${base}, modded ${fast})`)
      console.log(`PASS run MB.b (${mod} speeds up): ${base} -> ${fast} casts over 12s`)
    }
  }

  // (c) COUNT MODS SPAWN AT DISTINCT POSITIONS. The assertion is the spread, never the count.
  {
    // SILT VEIL IS A CONE OFF THE PLAYER (owner from play, 2026-08-21: "vase should not be a cloud
    // but a cone starting from you because it is just hitting nothing rn"). Two halves, because the
    // count mod and the shape fail differently: the fan's SPACING is state, but the wedge is only
    // provable as an EFFECT -- a bloom carrying an `arc` field that stepBlooms never reads is a
    // cone in the debugger and a disc in the game, and only a body outside the wedge can tell them
    // apart. This replaces an on-a-body assertion for a placement rule the weapon no longer has.
    const veil = boot('shelf', 'siltVeil', 5, { roil: 2 })
    veil.enemies.push(makeStatusEnemy(veil, { x: veil.player.x + 180, y: veil.player.y, hp: 1e6, speed: 0 }))
    assert(castUntil(veil, (r) => r.blooms.some((b) => b.look === 'silt')), 'precondition: the veil must cast within 12s')
    const clouds = veil.blooms.filter((b) => b.look === 'silt')
    assert(clouds.length >= 3, `expected Roil to add cones (count 1 + 2), got ${clouds.length}`)
    // THE APEX IS THE PLAYER. This is the whole reshape in one line, and it is the assertion that
    // tells the two designs apart: the old cloud landed on a body up to 195px away.
    const offApex = clouds.filter((b) => Math.hypot(b.x - veil.player.x, b.y - veil.player.y) > 1e-6)
    assert.strictEqual(offApex.length, 0,
      `every silt cone must start at the player: ${offApex.length} of ${clouds.length} did not`)
    assert.ok(clouds.every((b) => Math.abs(b.arc - SILT_VEIL_ARC) < 1e-9), 'every cone must carry SILT_VEIL_ARC')
    // THE FAN'S DIVISOR. Roil's cones share one apex, so "distinct positions" -- the assertion the
    // old cloud used -- is now trivially FALSE for correct code and cannot be the guard. The angles
    // are what must differ, and they must be spaced by a FULL arc: overlapping cones render and
    // damage identically to no change at all, which is the inert-card failure MB.a exists for.
    const angles = clouds.map((b) => b.angle).sort((a, b) => a - b)
    const gaps = angles.slice(1).map((a, i) => a - angles[i])
    assert.ok(gaps.length > 0 && gaps.every((g) => Math.abs(g - SILT_VEIL_ARC) < 1e-9),
      `Roil's cones must tile by one full arc (${SILT_VEIL_ARC.toFixed(3)} rad), got gaps ${gaps.map((g) => g.toFixed(3)).join(', ')}`)

    // THE WEDGE ACTUALLY GATES DAMAGE. One cone (no Roil), one body in front and one behind at the
    // same reach. The front body is NEARER so aimAngle points the cone at it; the back body sits at
    // 180 degrees, well outside a 75-degree wedge, and must take nothing at all. Without this a
    // stepBlooms that ignores `arc` passes every assertion above.
    const gate = boot('shelf', 'siltVeil', 5, null)
    const front = makeStatusEnemy(gate, { x: gate.player.x + 90, y: gate.player.y, hp: 1e6, speed: 0 })
    const back = makeStatusEnemy(gate, { x: gate.player.x - 110, y: gate.player.y, hp: 1e6, speed: 0 })
    gate.enemies.push(front, back)
    const hp0 = { front: front.hp, back: back.hp }
    assert(castUntil(gate, (r) => r.blooms.some((b) => b.look === 'silt')), 'precondition: the veil must cast within 12s')
    advance(gate, 2.5)
    assert(front.hp < hp0.front,
      `precondition: the body INSIDE the cone must be bitten, it took ${(hp0.front - front.hp).toFixed(0)}`)
    assert.strictEqual(back.hp, hp0.back,
      `a body BEHIND the cone must take nothing — it lost ${(hp0.back - back.hp).toFixed(0)} hp, so the wedge is not gating damage`)
    assert.strictEqual(back.stunT || 0, 0,
      `a body BEHIND the cone must not be dazed either — the daze rides the same tick loop as the damage`)

    // (c2) THE CLOUD'S TICK IS PER LEVEL, AND IT IS MEASURED, NOT READ OFF THE FIELD. Owner,
    // 2026-08-22: "It should tick like [...] every 1s at Lv1 and every 0.4 at level 5." A bloom
    // carrying a `tick` field stepBlooms never reads is the exact inert-card shape MB.a exists for
    // — the ladder would look right in config.js and the cloud would still bite every 0.5s — so the
    // subject here is the OBSERVED gap between bites, taken from the victim's hp.
    //
    // Damage is player-scaled and dmgPerTick differs per level, so neither the hp lost nor the tick
    // COUNT is a stable number to assert. The GAP between successive drops is, and it is exactly
    // the quantity the owner named.
    const biteGaps = (level) => {
      const r = boot('shelf', 'siltVeil', level, null)
      const foe = makeStatusEnemy(r, { x: r.player.x + 60, y: r.player.y, hp: 1e9, speed: 0 })
      r.enemies.push(foe)
      assert(castUntil(r, (x) => x.blooms.some((b) => b.look === 'silt')), `precondition: the veil must cast at Lv${level}`)
      // WATCH ONE CLOUD'S LIFE ONLY, and disarm the weapon to get it. `rate` is 2.41s at Lv1
      // against a 3.4s cloud, so the veil casts again mid-measurement and the second cone bites the
      // same body: the gaps came out 1.000, 1.417 instead of an even interval. That is an artefact
      // of the fixture and it reads exactly like a tick that does not hold its interval.
      //   Emptying run.weapons is safe here because stepBlooms reads only the bloom entry — the
      // cloud already exists and lives out its own dur with no weapon behind it.
      const cloud = r.blooms.find((b) => b.look === 'silt')
      r.weapons.length = 0
      // RE-PIN THE VICTIM EVERY FRAME. The Shelf's signature drifts everything at driftAmp 60,
      // and a body starting 60px from the apex reaches 125px by the cloud's end — outside a 116px
      // reach. The third tick then fires into empty water and the gap list comes back one short,
      // which reads exactly like a tick that stopped. This is the same class of fixture drift the
      // `onStep` re-pin above exists for (run.charge, run.shafts).
      const px = foe.x, py = foe.y
      const hits = []
      let hp = foe.hp, t = 0
      while (r.blooms.includes(cloud)) {
        foe.x = px; foe.y = py
        stepSim(r, { x: 0, y: 0 }, dt)
        t += dt
        if (foe.hp < hp) { hits.push(t); hp = foe.hp }
      }
      return hits.slice(1).map((h, i) => h - hits[i])
    }
    for (const [level, want] of [[1, 0.75], [5, 0.40]]) {
      const gaps = biteGaps(level)
      assert(gaps.length >= 2, `Lv${level}: expected at least 3 bites in one cloud's life, got ${gaps.length + 1}`)
      // One frame of tolerance: _tickAcc is advanced in dt steps, so a bite lands on the first
      // frame at or after the interval and never exactly on it.
      const worst = Math.max(...gaps.map((g) => Math.abs(g - want)))
      assert(worst <= dt + 1e-9,
        `Lv${level}: the silt cloud must bite every ${want}s, measured ${gaps.map((g) => g.toFixed(3)).join(', ')}`)
    }
    // ...AND THE TWO LEVELS MUST DIFFER. Both assertions above pass a build where every level got
    // the same tick if that tick happened to satisfy neither -- this is what makes the LADDER the
    // subject rather than two independent numbers.
    assert(WEAPONS.siltVeil.levels.every((l, i, a) => i === 0 || l.tick < a[i - 1].tick),
      'the silt tick must fall monotonically up the ladder — a flat or rising rung makes levelling the weapon slow its cloud down')

    // THE SHARED DEFAULT IS UNTOUCHED. Silt Veil got its own cadence by overriding BLOOM_TICK, and
    // the failure mode of doing that badly is moving the constant itself — which silently retunes
    // the pond's Toxin Bloom and The Twilight's Foxfire, two chapters away, with nothing red.
    assert.strictEqual(BLOOM_TICK, 0.5, 'BLOOM_TICK moved — Toxin Bloom and Foxfire ride it and neither was meant to change')
    {
      const r = boot('pond', 'bloom', 5, null)
      const foe = makeStatusEnemy(r, { x: r.player.x + 30, y: r.player.y, hp: 1e9, speed: 0 })
      r.enemies.push(foe)
      assert(castUntil(r, (x) => x.blooms.length > 0), 'precondition: Toxin Bloom must cast within 12s')
      const cloud = r.blooms[0]
      r.weapons.length = 0   // same reason as the veil above: one cloud, no second cast over it
      assert.strictEqual(cloud.tick, undefined, 'a Toxin Bloom cloud must carry NO tick of its own, or it has stopped riding the shared default')
      const px = foe.x, py = foe.y   // re-pinned for the same reason as the veil's loop above
      const hits = []
      let hp = foe.hp, t = 0
      while (r.blooms.includes(cloud)) {
        foe.x = px; foe.y = py
        stepSim(r, { x: 0, y: 0 }, dt)
        t += dt
        if (foe.hp < hp) { hits.push(t); hp = foe.hp }
      }
      const gaps = hits.slice(1).map((h, i) => h - hits[i])
      assert(gaps.length >= 1 && gaps.every((g) => Math.abs(g - BLOOM_TICK) <= dt + 1e-9),
        `Toxin Bloom must still bite every ${BLOOM_TICK}s, measured ${gaps.map((g) => g.toFixed(3)).join(', ')}`)
    }

    // Ballast: weights spread around the aim point. It needs something to aim at, or every drop
    // lands on the same blind-throw point by design and the spread is untestable.
    const bal = boot('shelf', 'ballast', 5, { jetsam: 2 })
    bal.enemies.push(makeStatusEnemy(bal, { x: bal.player.x + 200, y: bal.player.y, hp: 1e6, speed: 0 }))
    assert(castUntil(bal, (r) => r.lobs.length > 0), 'precondition: the ballast must throw within 12s')
    assert(bal.lobs.length >= 3, `expected Jetsam to add weights (count 1 + 2), got ${bal.lobs.length}`)
    const balPts = new Set(bal.lobs.map((l) => `${l.tx.toFixed(1)},${l.ty.toFixed(1)}`))
    assert.strictEqual(balPts.size, bal.lobs.length,
      `Jetsam's weights must land on DISTINCT points — ${bal.lobs.length} drops on ${balPts.size} targets means the spread divisor never moved`)
    console.log(`PASS run MB.c (placement): ${clouds.length} silt cones all apexed on the player, tiled ${SILT_VEIL_ARC.toFixed(3)} rad apart; a body in front took ${(hp0.front - front.hp).toFixed(0)} and one behind took 0; ${bal.lobs.length} ballast drops on ${balPts.size} distinct points`)
  }

  // (d) SCOUR PAYS IN CLEAN WATER, NOT IN FILTH. run.charge counts CLARITY — the bar is inverted for
  // display only — so charge 0 is the filthiest water and charge max is the cleanest. A sign error
  // here still ships a working weapon that simply rewards the opposite behaviour, which is exactly
  // what this card did until the owner inverted it on 2026-08-20: THE DIRECTION IS THE CARD, and it
  // has now pointed both ways, so the assertion has to name which way rather than merely check that
  // the bar is read at all.
  {
    const dmgAt = (charge, mods) => {
      const run = boot('shelf', 'bubblePuff', 5, mods, charge)
      assert(castUntil(run, (r) => r.novas.length > 0, pin(charge)), 'precondition: the puff must cast within 12s')
      return run.novas[0].dmg
    }
    const cleanOff = dmgAt(SHELF_MAX, null)
    const cleanOn = dmgAt(SHELF_MAX, { scour: 1 })
    const filthyOff = dmgAt(0, null)
    const filthyOn = dmgAt(0, { scour: 1 })
    assert.strictEqual(pollutionFrac(SHELF_MAX, SHELF_MAX), 0, 'precondition: a full clarity bar is zero pollution')
    assert.strictEqual(pollutionFrac(0, SHELF_MAX), 1, 'precondition: an empty clarity bar is full pollution')
    // The UNMODDED puff must not care about the water at all, or the two modded numbers below are
    // being compared across a moving baseline and the whole block measures nothing.
    assert.strictEqual(cleanOff, filthyOff,
      `precondition: without Scour the puff must hit the same in clean and filthy water (${cleanOff} vs ${filthyOff})`)
    // Worth NOTHING at full Pollution, and this end is EXACT — the bar is already at 0 and cannot
    // drain further, so there is no part-frame to allow for.
    assert(filthyOn <= filthyOff + 1e-9,
      `Scour must be worth NOTHING at full Pollution (unmodded ${filthyOff}, modded ${filthyOn}) — that bargain is the whole card`)
    // The clean end is NOT exact: `pin` re-sets the bar before each step and stepCharge drains one
    // frame of it before the weapon fires, so the water at the moment of the cast is one frame
    // dirty and the bonus lands a hair under its nominal value. The bound is that frame, derived
    // from the chapter's own drain and the card's own base rather than written down as a magic
    // tolerance — a literal here would stop meaning anything the first time either is retuned.
    const frameDirt = (CHAPTERS.shelf.resource.drain * dt) / SHELF_MAX
    const nominal = WEAPON_MODS.bubblePuff.scour.base
    assert(cleanOn >= cleanOff * (1 + nominal * (1 - frameDirt)) - 1e-9,
      `Scour must pay its full +${Math.round(nominal * 100)}% in clean water: ${cleanOn} against ${cleanOff} unmodded, one frame of drain allows losing ${(cleanOff * nominal * frameDirt).toFixed(4)}`)
    assert(cleanOn > filthyOn * 1.4,
      `Scour must pay in CLEAN water, not in filth: ${cleanOn} clean against ${filthyOn} at full pollution`)
    console.log(`PASS run MB.d (Scour pays for clean water): puff dmg ${cleanOff} unmodded either way, ${cleanOn} clean modded (+${Math.round(nominal * 100)}%), ${filthyOn.toFixed(1)} at full pollution`)
  }

  // (e) BACKBLOW ADDS ONE OPPOSED CONE, AND STOPS PAST A HALF-TURN. The second nova carries its own
  // hit set, so at arc > pi the two sectors overlap and a body in both is paid for twice — the card
  // would stop being coverage and become a silent damage doubler.
  {
    const narrow = boot('shelf', 'bubblePuff', 5, { backblow: 1 })
    assert(castUntil(narrow, (r) => r.novas.length > 0), 'precondition: the modded puff must cast')
    const base = boot('shelf', 'bubblePuff', 5, null)
    assert(castUntil(base, (r) => r.novas.length > 0), 'precondition: the bare puff must cast')
    assert.strictEqual(narrow.novas.length, base.novas.length * 2,
      `Backblow must add exactly one opposed cone per nova (base ${base.novas.length}, modded ${narrow.novas.length})`)
    const angles = narrow.novas.map((n) => n.angle)
    // Bearing difference normalised into [0, 2pi); an opposed pair reads exactly pi.
    const gap = (((angles[1] - angles[0]) % (Math.PI * 2)) + Math.PI * 2) % (Math.PI * 2)
    assert(Math.abs(gap - Math.PI) < 1e-6,
      `Backblow's cone must sit opposite the first: the two bearings are ${gap.toFixed(4)} rad apart, want ${Math.PI.toFixed(4)}`)

    // THE PUFF NEVER CLOSES THE CIRCLE — owner from play, 2026-08-21: Flare plus Backblow "can
    // reach 360deg bubble puff and that's what I wanted to prevent". BUBBLE_COVER_MAX is a ceiling
    // on TOTAL coverage, so this asserts the sum of the sectors and not one cone's width.
    //
    // flare 6 is far past anything a real ladder rolls, deliberately: the point is that no amount
    // of the width card can buy the last degree. It is also past 2pi, which used to become
    // spawnNova's `arc: null` full ring — asserted below, because a null arc is coverage 2pi
    // wearing a different type.
    const cover = (mods) => {
      const r = boot('shelf', 'bubblePuff', 5, mods)
      assert(castUntil(r, (x) => x.novas.length > 0), 'precondition: the puff must cast')
      const sectors = r.novas.filter((n) => n.look === 'bubble')
      assert(sectors.length > 0, 'precondition: no bubble novas to measure')
      for (const n of sectors) {
        assert(n.arc != null, 'a bubble nova was spawned with arc: null — that is a full ring, i.e. 360 degrees')
      }
      return { total: sectors.reduce((a, n) => a + n.arc, 0), n: sectors.length }
    }
    const CAP = BUBBLE_COVER_MAX
    for (const [label, mods] of [
      ['bare', null],
      ['flare x6', { flare: 6 }],
      ['backblow', { backblow: 1 }],
      ['flare x6 + backblow', { backblow: 1, flare: 6 }],
    ]) {
      const c = cover(mods)
      assert(c.total <= CAP + 1e-9,
        `${label} covers ${c.total.toFixed(3)} rad across ${c.n} cone(s) — over the ${CAP.toFixed(3)} ceiling, ` +
        'which is how the puff became a full circle you could stand still inside')
    }
    // ...and Backblow is still WORTH taking at the ceiling: it must add coverage, not just move it.
    const wideBase = cover({ flare: 6 })
    const wide = cover({ backblow: 1, flare: 6 })
    assert.strictEqual(wide.n, 2, `Backblow must always spawn its second cone, got ${wide.n}`)
    assert(wide.total > wideBase.total,
      `Backblow bought nothing at the ceiling: ${wideBase.total.toFixed(3)} rad against ${wide.total.toFixed(3)}`)
    console.log(`PASS run MB.e (Backblow): ${base.novas.length} -> ${narrow.novas.length} novas a half-turn apart at a 90deg cone; total coverage capped at ${CAP.toFixed(2)} rad (${(CAP * 180 / Math.PI).toFixed(0)}deg) on every mod combination, and Flare x6 + Backblow still beats Flare x6 alone (${wideBase.total.toFixed(2)} -> ${wide.total.toFixed(2)} rad)`)
  }

  // (f) FOUL WATER is a CADENCE mod that ramps with the pollution bar (2026-08-23, replacing the
  // drag-widening version): +50% drop rate at 100% pollution, nothing at all in clean water.
  //   ASSERTED AS AN EFFECT — how many weights actually LAND in a fixed window, off the
  // {type:'ballast'} event, never off the interval or off run.lobs. A weapon that fires the frame a
  // window opens and again the frame it closes reads as a rate change from either of those.
  //   AND THE BAR ALONE MUST BUY NOTHING: the same two waters with the mod UNPICKED have to give
  // the same count, or the ramp is coming from somewhere other than the card.
  {
    const dropsIn = (charge, mods, secs = 20) => {
      const run = boot('shelf', 'ballast', 5, mods, charge)
      // One immortal body parked on the player: the weapon needs a target to aim at, and a corpse
      // would end the casting. speed 0 so it stays put and cannot re-phase anything.
      run.enemies.push(makeStatusEnemy(run, { x: run.player.x + 60, y: run.player.y, hp: 1e9, speed: 0 }))
      let n = 0
      const onStep = (r) => { pin(charge)(r); n += r.events.filter((e) => e.type === 'ballast').length; r.events.length = 0 }
      advance(run, secs, onStep)
      return n
    }
    // THE SHIPPED VALUE, not a round 1: run.weaponMods banks the accumulated BONUS for a pct mod
    // (applyChoice), so feeding 1 here would measure a card that pays double what it sells.
    const nominal = WEAPON_MODS.ballast.foulWater.base
    const clean = dropsIn(SHELF_MAX, { foulWater: nominal })
    const filthy = dropsIn(0, { foulWater: nominal })
    const cleanBare = dropsIn(SHELF_MAX, null)
    const filthyBare = dropsIn(0, null)
    assert.strictEqual(clean, cleanBare,
      `Foul Water must buy NOTHING in clean water: ${clean} drops against ${cleanBare} without the card`)
    assert.strictEqual(cleanBare, filthyBare,
      `the pollution bar moved the cadence on its own (${cleanBare} clean, ${filthyBare} filthy) — that is the CARD's job`)
    // +50% rate over the window, allowing the one drop the window's edges can swallow either way.
    const want = cleanBare * (1 + nominal)
    assert(Math.abs(filthy - want) <= 1,
      `Foul Water in the filthiest water must drop ~${want} times against ${cleanBare} clean, got ${filthy}`)
    // AND THE STAIN IS GONE. The owner cut it because it was Silt Veil's own picture given away on
    // a rare; a landing that quietly pushes a look:'silt' bloom again would look entirely correct.
    const plain = boot('shelf', 'ballast', 5, null, 0)
    plain.enemies.push(makeStatusEnemy(plain, { x: plain.player.x + 200, y: plain.player.y, hp: 1e6, speed: 0 }))
    assert(castUntil(plain, (r) => r.lobs.length > 0, pin(0)), 'precondition: the ballast must throw within 12s')
    advance(plain, BALLAST_FLIGHT + 0.2, pin(0))
    assert.strictEqual(plain.blooms.filter((b) => b.look === 'silt').length, 0,
      'a ballast landing pushed a silt cloud — the stain is supposed to be gone (it made Silt Veil pointless)')
    console.log(`PASS run MB.f (Foul Water): ${filthy} drops in 20s at full pollution against ${clean} in clean water (+${Math.round((filthy / clean - 1) * 100)}%), the bar alone moves nothing (${cleanBare} either way), and no landing leaves a silt cloud`)
  }

  // (g) FOUL SPRING enlarges a cloud dropped in a LIVE upwelling and SPENDS that upwelling — and
  // does neither on water already spent. The spend is written into `drawdown`, the field stepCharge
  // already counts occupancy into and render.js already fades the circle off, so this asserts the
  // shipped tell rather than a parallel one.
  {
    const life = refillSpec(CHAPTERS.shelf.signature)?.drawdownSecs ?? 0
    assert(life > 0, 'precondition: The Shelf\'s upwellings must draw down, or Foul Spring has nothing to spend')

    // ONE upwelling, re-pinned every frame and centred on the player. streamShafts rewrites
    // run.shafts around the player every step, so a hand-placed circle left alone is gone within a
    // frame or two and the block would silently be testing open water. The SAME object is put back
    // each time rather than a fresh one, so the `drawdown` this is trying to observe survives.
    const withShaft = (drawdown) => {
      const run = boot('shelf', 'siltVeil', 5, { foulSpring: 1 })
      const sh = { x: run.player.x, y: run.player.y, bx: run.player.x, by: run.player.y, r: 205, phase: 0, _cell: 'test', drawdown }
      // `drawdown` is re-pinned every frame too, and that is the whole reason this fixture works.
      // The circle is centred on the player and Silt Veil's interval is 3.2s, so stepCharge spends
      // the upwelling at 2.09s of occupancy -- BEFORE the weapon has ever cast. Left alone, the live
      // case measured a spent circle and read as "Foul Spring does nothing", which is the bug this
      // block exists to catch, arriving from the fixture. Holding the state is what makes this a
      // test of the CLOUD's interaction rather than of the player's standing still.
      const hold = (r) => { sh.x = sh.bx = r.player.x; sh.y = sh.by = r.player.y; sh.drawdown = drawdown; r.shafts = [sh] }
      assert(castUntil(run, (r) => r.blooms.some((b) => b.look === 'silt'), hold), 'precondition: the veil must cast within 12s')
      const silt = run.blooms.filter((b) => b.look === 'silt')
      const cloud = silt[0]
      // The CONE is silt[0] and the fouled patch, if there is one, is the disc behind it — `arc`
      // is what stepBlooms itself tests to choose a wedge over a circle, so it is the honest
      // separator rather than an index.
      return { maxR: cloud.maxR, dur: cloud.dur, dps: cloud.dmgPerTick, spent: (sh.drawdown ?? 0) >= life,
        patch: silt.filter((b) => b.arc == null) }
    }
    const plain = boot('shelf', 'siltVeil', 5, null)
    assert(castUntil(plain, (r) => r.blooms.some((b) => b.look === 'silt'), (r) => { r.shafts = [] }),
      'precondition: the bare veil must cast within 12s')
    const bare = plain.blooms.filter((b) => b.look === 'silt')[0]

    const live = withShaft(0)
    const already = withShaft(life)
    assert(live.maxR > bare.maxR * 1.4, `a cloud dropped in a live upwelling must be bigger: ${live.maxR.toFixed(1)} against ${bare.maxR.toFixed(1)}`)
    assert(live.dur > bare.dur * 1.4, `...and must hang longer: ${live.dur.toFixed(2)}s against ${bare.dur.toFixed(2)}s`)
    // ALL THREE, because the card names all three. It scaled only size and duration when it first
    // shipped, and the card that shipped beside it promised damage as well.
    assert(live.dps > bare.dmgPerTick * 1.4,
      `...and must bite harder, which the card promises alongside size and duration: ${live.dps.toFixed(2)} against ${bare.dmgPerTick.toFixed(2)}`)
    assert(live.spent, 'Foul Spring must SPEND the upwelling it fouls — that cost is the whole card')
    // AND THE PATCH BECOMES A CLOUD (owner, 2026-08-22). The spend above is the cost and is
    // unchanged; this is what the player now gets for it. Asserted as a bloom the size of the
    // whole circle, because the previous tell — `fouled`, the fade — is render-only and passes
    // with the mechanic deleted.
    assert.strictEqual(live.patch.length, 1,
      `fouling a patch must leave one disc-shaped cloud covering it, got ${live.patch.length}`)
    assert(Math.abs(live.patch[0].maxR - 205) < 1e-9,
      `...at the PATCH's radius, not the veil's: ${live.patch[0].maxR.toFixed(1)} against 205`)
    assert.strictEqual(already.patch.length, 0,
      'water already drawn down must leave no cloud — nothing was fouled, so there is nothing to turn to silt')
    assert.strictEqual(bare.arc != null, true,
      'precondition: the veil\'s own cast is a WEDGE, or the disc test above separates nothing')
    assert(Math.abs(already.maxR - bare.maxR) < 1e-9,
      `an upwelling already drawn down must pay NOTHING: ${already.maxR.toFixed(1)} against a bare ${bare.maxR.toFixed(1)}`)
    console.log(`PASS run MB.g (Foul Spring): cloud r ${bare.maxR.toFixed(0)}->${live.maxR.toFixed(0)}, dur ${bare.dur.toFixed(1)}->${live.dur.toFixed(1)}s, dps ${bare.dmgPerTick.toFixed(1)}->${live.dps.toFixed(1)} in clean water, the whole 205px patch turns to silt behind it, and ${already.maxR.toFixed(0)} with no cloud on water already spent`)
  }


  // (j) THE TWO DUO BOONS (owner, 2026-08-22): ballast.siltPlume and downwash.siltFlush, each a
  // mod on one weapon that spawns the OTHER weapon's cloud, and each offered only while both are
  // held. Three things fail silently here and all three are asserted: the GATE (a card offered
  // without its partner is an epic that does nothing), the SPAWN (a boon wired to nothing is the
  // inert card MB.a exists for), and the SPREAD (three clouds sharing one centre render
  // identically to one cloud — the count-mod failure this repo has shipped once already).
  //
  // Every count here filters `arc == null`. Both fixtures hold Silt Veil, which is the whole
  // point, and it is casting its own WEDGES the entire time — so the discs are the boons' and
  // the wedges are the veil's, separated by the same field stepBlooms tests.
  {
    const duo = (id, mods) => {
      const r = boot('shelf', id, 5, mods)
      r.weapons.push({ id: 'siltVeil', level: 5 })
      return r
    }
    const discs = (r) => r.blooms.filter((b) => b.look === 'silt' && b.arc == null)
    const veil = WEAPONS.siltVeil.levels[4]

    // SILT PLUME: the weight lands and throws three clouds up around the crater.
    const plume = duo('ballast', { siltPlume: 3 })
    plume.enemies.push(makeStatusEnemy(plume, { x: plume.player.x + 200, y: plume.player.y, hp: 1e6, speed: 0 }))
    assert(castUntil(plume, (r) => r.lobs.length > 0, pin(0)), 'precondition: the ballast must throw within 12s')
    advance(plume, BALLAST_FLIGHT + 0.2, pin(0))
    const thrown = discs(plume)
    assert.strictEqual(thrown.length, 3, `Silt Plume must leave 3 clouds on the landing, got ${thrown.length}`)
    const spots = new Set(thrown.map((b) => `${Math.round(b.x)},${Math.round(b.y)}`))
    assert.strictEqual(spots.size, 3,
      `three clouds on ${spots.size} point(s) render identically to one cloud — SILT_PLUME_SPREAD is what rings them`)
    // THE VEIL'S OWN NUMBERS, not a second ladder. This is what makes the card scale with the
    // weapon it is made of instead of needing its own retune every time that weapon moves.
    assert(Math.abs(thrown[0].dmgPerTick - veil.dmgPerTick) < 1e-9 && Math.abs(thrown[0].dur - veil.dur) < 1e-9,
      `a plume must BE a silt cloud: ${thrown[0].dmgPerTick}/tick for ${thrown[0].dur}s against the veil's ${veil.dmgPerTick}/${veil.dur}`)
    const crater = WEAPONS.ballast.levels[4].r
    // AND THE RING IS THE CONSTANT'S, not an accident of three arbitrary points. Three clouds on
    // a symmetric ring have their own centroid as the centre, so this reads the spread back out
    // of the result without needing the crater's position.
    const cx = thrown.reduce((a, b) => a + b.x, 0) / 3, cy = thrown.reduce((a, b) => a + b.y, 0) / 3
    const ring = Math.hypot(thrown[0].x - cx, thrown[0].y - cy)
    assert(Math.abs(ring - crater * SILT_PLUME_SPREAD) < 0.5,
      `plumes must ring at SILT_PLUME_SPREAD of the ${crater}px crater (${(crater * SILT_PLUME_SPREAD).toFixed(1)}px), got ${ring.toFixed(1)}px`)

    // SILT FLUSH: the column bursts and blows one huge cloud out of its own footprint.
    const flush = duo('downwash', { siltFlush: 1 })
    flush.enemies.push(makeStatusEnemy(flush, { x: flush.player.x + 200, y: flush.player.y, hp: 1e6, speed: 0 }))
    assert(castUntil(flush, (r) => discs(r).length > 0, pin(0), 14), 'precondition: a column must burst within 14s')
    const blown = discs(flush)
    assert.strictEqual(blown.length, 1, `Silt Flush must leave exactly one cloud per burst, got ${blown.length}`)
    const col = WEAPONS.downwash.levels[4].radius
    assert(Math.abs(blown[0].maxR - col * SILT_FLUSH_MUL) < 1e-9,
      `...sized off the COLUMN (${col} x ${SILT_FLUSH_MUL}), not the veil: got ${blown[0].maxR.toFixed(1)}`)
    // The control, and it is not ceremony: run.holes is shared with the Black Hole and run.blooms
    // with the pond's and The Twilight's clouds, so 'a disc appeared' has more than one possible
    // author. An unmodded column must leave none over the same window.
    const bareCol = duo('downwash', null)
    bareCol.enemies.push(makeStatusEnemy(bareCol, { x: bareCol.player.x + 200, y: bareCol.player.y, hp: 1e6, speed: 0 }))
    advance(bareCol, 14, pin(0))
    assert.strictEqual(discs(bareCol).length, 0,
      'an unmodded column left a silt cloud — the boon is leaking to a weapon that did not buy it')

    // THE GATE, rolled through buildLevelUpChoices (the shipped path) rather than against the
    // eligibility function, so a gate written in the wrong place still fails. `boot` re-seeds the
    // stream on every call, which is why these runs are built by hand.
    const offers = (ids) => {
      Math.random = mulberry32(20260822)
      let duoCards = 0, modCards = 0
      for (let i = 0; i < 1500; i++) {
        const r = createRun(mkMeta(), { chapter: 'shelf', difficulty: 1 })
        r.weapons = ids.map((id) => ({ id, level: 5 }))
        r.level = 12
        for (const c of buildLevelUpChoices(r)) {
          if (c.kind !== 'mod') continue
          modCards++
          if (c.id === 'siltPlume' || c.id === 'siltFlush') duoCards++
        }
      }
      return { duoCards, modCards }
    }
    const alone = offers(['ballast', 'downwash'])
    const paired = offers(['ballast', 'downwash', 'siltVeil'])
    assert.strictEqual(alone.duoCards, 0,
      `a duo boon was offered without Silt Veil across ${alone.modCards} mod cards — the card would do nothing`)
    assert(paired.duoCards > 0,
      `...and must be reachable once the veil is held: 0 of ${paired.modCards} mod cards over 1500 pools`)
    console.log(`PASS run MB.j (duo boons): a landing throws ${thrown.length} plumes ringed ${ring.toFixed(0)}px out around a ${crater}px crater, a burst blows one ${blown[0].maxR.toFixed(0)}px cloud (${col} x ${SILT_FLUSH_MUL}) and an unmodded column none, both carrying the veil's ${veil.dmgPerTick}/tick; offered ${paired.duoCards} times with the veil and ${alone.duoCards} without, over ~${paired.modCards} mod cards each`)
  }

  // (h) A FOULED PATCH STOPS RECHARGING YOU — asserted as an EFFECT, not as state. MB.g above
  // checks `drawdown` reached its cap, which is the flag; this stands the player in the water and
  // reads the BAR. Owner, on picking the look: "from the rim in and it disables your resource
  // recharge" — that is the promise the animation has to be telling the truth about, and a test
  // that only checks the flag passes with the flag wired to nothing (`assert-effects-not-state`).
  //
  // The control is not ceremony: without it "the bar did not rise" is unreadable, because the bar
  // also does not rise when the player is simply outside every circle, which is what a fixture that
  // mis-places its shaft produces.
  {
    const life = refillSpec(CHAPTERS.shelf.signature)?.drawdownSecs ?? 0
    // Charge parked mid-bar so a rise and a fall are both visible, and the shaft re-pinned under
    // the player every frame — streamShafts rewrites run.shafts around them otherwise.
    const stand = (fouled) => {
      const run = boot('shelf', 'siltVeil', 5, null, SHELF_MAX * 0.5)
      run.chargeMax = SHELF_MAX
      const sh = { x: run.player.x, y: run.player.y, bx: run.player.x, by: run.player.y, r: 205, phase: 0, _cell: 'test', drawdown: fouled ? life : 0 }
      const start = run.charge
      for (let i = 0; i < Math.round(0.5 / dt); i++) {
        sh.x = sh.bx = run.player.x; sh.y = sh.by = run.player.y
        run.shafts = [sh]
        stepSim(run, { x: 0, y: 0 }, dt)
      }
      return { start, end: run.charge }
    }
    const clean = stand(false)
    const fouled = stand(true)
    assert(clean.end > clean.start + 1,
      `precondition: standing in a LIVE upwelling must refill the bar (${clean.start.toFixed(1)} -> ${clean.end.toFixed(1)}), or this block proves nothing`)
    assert(fouled.end < fouled.start,
      `a fouled patch must stop recharging you — the bar must DRAIN while standing in it, got ${fouled.start.toFixed(1)} -> ${fouled.end.toFixed(1)}`)
    console.log(`PASS run MB.h (a fouled patch feeds nobody): live upwelling ${clean.start.toFixed(0)} -> ${clean.end.toFixed(0)} charge, fouled ${fouled.start.toFixed(0)} -> ${fouled.end.toFixed(0)} over the same 0.5s`)
  }

  // (i) THE DOWNWASH GATHERS, AND THE BURST IS THE PAYOFF. Four assertions, and every one of them
  // separates this card from the Mini Black Hole it shares run.holes with -- a distinction that is
  // invisible on screen and silent in every other test, because both are "a circle that pulls".
  {
    // WHERE IT LANDS. Five bodies in a knot to the east, one straggler to the west, and the column
    // must choose the knot. pickHoleSpot (the Black Hole's) picks UNIFORMLY AT RANDOM among bodies
    // in view, so a Downwash wired to it would land on the straggler one time in six and look
    // exactly the same doing it. This is the assertion that fails if pickDownwashSpot is deleted.
    const dw = boot('shelf', 'downwash', 5, null)
    const knotX = dw.player.x + 260
    for (let i = 0; i < 5; i++) {
      dw.enemies.push(makeStatusEnemy(dw, { x: knotX + i * 12, y: dw.player.y + i * 9, hp: 1e6, speed: 0 }))
    }
    const straggler = { x: dw.player.x - 300, y: dw.player.y }
    dw.enemies.push(makeStatusEnemy(dw, { ...straggler, hp: 1e6, speed: 0 }))
    assert(castUntil(dw, (r) => r.holes.length > 0), 'precondition: the downwash must cast within 12s')
    const col = dw.holes[0]
    assert.strictEqual(col.look, 'downwash', 'the column must carry look:downwash — the tag is what keeps the two weapons apart in stepHoles and in render.js')
    assert(Math.hypot(col.x - straggler.x, col.y - straggler.y) > 100,
      `the column landed on the lone straggler (${col.x.toFixed(0)},${col.y.toFixed(0)}) — pickDownwashSpot is not choosing the densest clump`)
    assert(Math.abs(col.x - knotX) < 80,
      `the column must land in the knot of 5 (x~${knotX.toFixed(0)}), landed at x=${col.x.toFixed(0)}`)

    // THE BURST IS THE DAMAGE. A body parked dead centre must lose more to the single expiry hit
    // than to the whole pour that preceded it. If `burst` is ever dropped from the push or the
    // expiry branch stops paying it, the weapon still pulls, still ticks and still looks right --
    // and this is the only thing that notices it became a weak vortex.
    const hit = boot('shelf', 'downwash', 5, null)
    hit.enemies.push(makeStatusEnemy(hit, { x: hit.player.x + 260, y: hit.player.y, hp: 1e6, speed: 0 }))
    assert(castUntil(hit, (r) => r.holes.length > 0), 'precondition: the downwash must cast within 12s')
    const victim = hit.enemies[0]
    const h = hit.holes[0]
    victim.x = h.x; victim.y = h.y
    const hpBeforePour = victim.hp
    // Step to just before expiry, pinning the body in the column so the pull cannot carry it out.
    const pinBody = (r) => { const c = r.holes[0]; if (c) { victim.x = c.x; victim.y = c.y } }
    advance(hit, h.life - 0.1, pinBody)
    const pourDmg = hpBeforePour - victim.hp
    const hpBeforeBurst = victim.hp
    advance(hit, 0.3, pinBody)
    const burstDmg = hpBeforeBurst - victim.hp
    assert.strictEqual(hit.holes.length, 0, 'the column must retire at the end of its pour')
    assert(burstDmg > pourDmg,
      `the burst must out-damage the whole pour: pour ${pourDmg.toFixed(1)}, burst ${burstDmg.toFixed(1)} — this card is a wind-up, not a vortex`)

    // IT NEVER INHERITS THE BLACK HOLE'S MODS. `hungryBonus`/`crunchBonus` are read once per frame
    // off run.weaponMods.hole and applied to every entry in run.holes, so a player holding both
    // cards would silently hand their Downwash a x10 CRUNCH_DMG_MUL detonation and a growing
    // radius. The guard is `h.look !== 'downwash'`; delete it and this block goes red.
    const both = boot('shelf', 'downwash', 5, null)
    Object.assign(both.weaponMods.hole, { crunch: 5, hungry: 3 })
    both.enemies.push(makeStatusEnemy(both, { x: both.player.x + 260, y: both.player.y, hp: 1e6, speed: 0 }))
    assert(castUntil(both, (r) => r.holes.length > 0), 'precondition: the downwash must cast within 12s')
    const v2 = both.enemies[0]
    const c2 = both.holes[0]
    // The radius is sampled at the LAST frame of the pour, not at the cast. Hungry Hole grows a
    // hole over its life, so reading it on the frame it lands measures the config value and passes
    // with the guard deleted — a gate with no bulb, and the mutation harness is what said so.
    let lastR = c2.radius
    const pin2 = (r) => { const c = r.holes[0]; if (c) { v2.x = c.x; v2.y = c.y; lastR = c.radius } }
    const hp2 = v2.hp
    advance(both, c2.life + 0.3, pin2)
    const withHoleMods = hp2 - v2.hp
    assert(Math.abs(lastR - WEAPONS.downwash.levels[4].radius) < 1e-9,
      `Hungry Hole grew the column: ${WEAPONS.downwash.levels[4].radius} -> ${lastR.toFixed(1)} by the end of the pour`)
    // Same fixture, same seed, no hole mods -> the same total. An inherited Big Crunch would be
    // h.dmg x CRUNCH_DMG_MUL x 6, i.e. hundreds of damage on a 7-damage tick, so the tolerance is
    // wide on purpose and still cannot be reached by the pathology.
    const alone = boot('shelf', 'downwash', 5, null)
    alone.enemies.push(makeStatusEnemy(alone, { x: alone.player.x + 260, y: alone.player.y, hp: 1e6, speed: 0 }))
    assert(castUntil(alone, (r) => r.holes.length > 0), 'precondition: the downwash must cast within 12s')
    const v3 = alone.enemies[0]
    const c3 = alone.holes[0]
    const pin3 = (r) => { const c = r.holes[0]; if (c) { v3.x = c.x; v3.y = c.y } }
    const hp3 = v3.hp
    advance(alone, c3.life + 0.3, pin3)
    const withoutHoleMods = hp3 - v3.hp
    assert(Math.abs(withHoleMods - withoutHoleMods) < 1e-6,
      `the Black Hole's mods leaked into the Downwash: ${withoutHoleMods.toFixed(1)} alone vs ${withHoleMods.toFixed(1)} while holding Big Crunch + Hungry Hole`)

    // PLUNGE ADDS A BURST AND KEEPS THE POUR. It used to set h.life = 0, which retired the column
    // on its early burst: measured over 324 columns (scripts/plunge-probe.mjs, shelf L5, 300s x 3
    // seeds) that fired on 69% of them and served a median 1.00s of a 2.00s pour for exactly ONE
    // burst -- the same burst the timer would have produced. The card traded half the gather for
    // nothing and looked identical either way, which is what the owner reported as "doesn't work".
    //
    // THREE THINGS, and each needs its own control because any one alone is satisfiable by a stub:
    //   - it fires EARLY (delay), or the mod is a no-op;
    //   - it fires TWICE (bursts), or it is the old strictly-worse column;
    //   - the column still serves its FULL pour, or the early burst is still being paid for.
    // Plus the too-few control, or the trigger is just a shorter fuse.
    const noMod = burstOf(null, DOWNWASH_PLUNGE_N + 1)
    const plunged = burstOf({ plunge: 1 }, DOWNWASH_PLUNGE_N + 1)
    const tooFew = burstOf({ plunge: 1 }, DOWNWASH_PLUNGE_N - 1)
    assert(noMod.delay > noMod.dur * 0.9,
      `control: without Plunge the column must burst at the end of its pour (${noMod.delay.toFixed(2)}s of ${noMod.dur}s)`)
    assert.strictEqual(noMod.bursts, 1, `control: an unmodded column must detonate once, got ${noMod.bursts}`)
    assert(plunged.delay < noMod.delay - 0.2,
      `Plunge must burst the column early: ${noMod.delay.toFixed(2)}s unmodded vs ${plunged.delay.toFixed(2)}s modded`)
    // NOT ZERO. The column lands on the clump it chose, so counting the whole radius would fire on
    // the cast frame and delete the gather entirely -- the card would be an instant blast where the
    // crowd already was. DOWNWASH_PLUNGE_FRAC is the distance the pull has to actually cover.
    assert(plunged.delay > 0,
      'Plunge fired on the cast frame — the trigger radius is back to the full column and the gather is gone')
    assert(tooFew.delay > noMod.dur * 0.9,
      `control: ${DOWNWASH_PLUNGE_N - 1} bodies must not trip a ${DOWNWASH_PLUNGE_N}-body trigger (burst at ${tooFew.delay.toFixed(2)}s)`)
    // TWICE, AND EXACTLY TWICE. The condition stays true for the rest of the pour, so `h.trigger = 0`
    // is the only thing stopping a detonation on every single frame -- delete it and this reads in
    // the dozens, restore h.life = 0 and it reads 1.
    assert.strictEqual(plunged.bursts, 2,
      `Plunge must add a burst and let the column finish on its own: want 2, got ${plunged.bursts}`)
    // ...and the pour is not shortened to pay for it. The second burst is the EXPIRY one, so it
    // lands at the end of a full-length pour.
    assert(plunged.lastDelay > noMod.dur * 0.9,
      `Plunge shortened the pour: last burst at ${plunged.lastDelay.toFixed(2)}s of a ${noMod.dur}s pour`)
    // IT CANNOT SCRAPE THE PLAYER IT GATHERS FOR. Owner from play, 2026-08-22: "enemies ragdolled
    // by the water column should not damage you". The column lands on the densest clump within
    // DOWNWASH_CAST_FRAC of the viewport and drags it inward, so the crowd this card gathers
    // arrives on top of the player who cast it -- the weapon was charging its own user for using it
    // correctly, and nothing on screen said the touch was the column's doing rather than the crowd's.
    //   FOUR ARMS, because every cheaper version of this check passes for the wrong reason.
    // "The player lost no HP" is also what a fixture with no damage in it reports (SB.a's lesson),
    // hence the ambient control; a body OUTSIDE the column is what proves the fixture can hurt at
    // all; and the BLACK HOLE arm is the one that fails if the guard is widened to `holePull > 0`
    // alone -- both weapons share run.holes, and disarming everything inside a vortex would turn a
    // Book 1 weapon into a safe bubble. That widening is invisible in every other assertion here.
    const W = 1.5   // shorter than either weapon's shortest L5 pour (downwash 2.0s, hole 2.6s)
    const scrape = (mode) => {
      const r = boot('shelf', mode === 'blackhole' ? 'hole' : 'downwash', 5, null)
      r.player.maxHP = r.player.hp = 5000
      if (mode === 'ambient') {
        advance(r, 3 * dt)          // the same prelude the other arms take, so the windows match
        const hp0 = r.player.hp
        advance(r, W)
        return hp0 - r.player.hp
      }
      // Cast with the body well clear of the player so the column lands THERE, not on top of us;
      // the body only moves onto the player afterwards, so the `out` arm starts genuinely outside.
      const body = makeStatusEnemy(r, { x: r.player.x + 260, y: r.player.y, hp: 1e6, speed: 0 })
      r.enemies.push(body)
      assert(castUntil(r, (x) => x.holes.length > 0), `precondition (${mode}): the weapon must cast within 12s`)
      assert(r.holes[0].life > W, `precondition (${mode}): the pour must outlive the ${W}s window, got ${r.holes[0].life.toFixed(2)}s`)
      const pin = (x) => {
        body.x = x.player.x; body.y = x.player.y
        const c = x.holes[0]
        if (c) { c.x = mode === 'out' ? x.player.x + 5000 : x.player.x; c.y = x.player.y }
      }
      // ONE SETTLING FRAME BEFORE THE CLOCK STARTS, and it is not a fudge. stepContactDamage runs
      // at stepSim's line 295 and stepHoles at 311 (inside stepWeapons), so contact always reads
      // the PREVIOUS frame's holePull -- a 16ms lag nobody can see in play, where a body walks into
      // a standing column. This fixture TELEPORTS the column onto the body instead, which
      // manufactures exactly that frame: without the prelude the `in` arm measures 8 HP of step
      // ordering and reads as the guard not working. Same prelude on every arm so they stay
      // comparable (it costs the `out` arm its first hit, which is why W is long enough for more).
      advance(r, 3 * dt, pin)
      const hp0 = r.player.hp
      advance(r, W, pin)
      return hp0 - r.player.hp
    }
    const ambient = scrape('ambient')
    const outside = scrape('out')
    const inColumn = scrape('in')
    const inVortex = scrape('blackhole')
    assert(outside > ambient,
      `control: a body parked on the player with the column moved away must still hurt (${outside} lost vs ${ambient} ambient) — ` +
      'if this reads 0 the fixture proves nothing about the arm below')
    assert.strictEqual(inColumn, ambient,
      `a body the water column has hold of took ${inColumn - ambient} HP off the player over ${W}s — ` +
      'contactHarmless is not seeing it (check e._holeLook is still written beside e.holePull in stepHoles)')
    assert(inVortex > ambient,
      `the Black Hole was disarmed too (${inVortex} lost vs ${ambient} ambient): the guard must be scoped by ` +
      '_holeLook === downwash, not by holePull alone — this is The Shelf\'s card, not a buff to Book 1\'s vortex')

    console.log(`PASS run MB.i (Downwash): lands in the knot of 5 not on the straggler, burst ${burstDmg.toFixed(0)} out-damages the whole pour ${pourDmg.toFixed(0)} (no core crush), Big Crunch + Hungry Hole leak nothing (${withoutHoleMods.toFixed(1)} both ways), Plunge fires at ${plunged.delay.toFixed(2)}s and again at ${plunged.lastDelay.toFixed(2)}s of a ${noMod.dur}s pour (2 bursts against the control's ${noMod.bursts}), and ${DOWNWASH_PLUNGE_N - 1} bodies do not trip it; a body the column has hold of costs the player ${inColumn} HP against the ${outside} it costs outside one, while the Black Hole's own bodies still cost ${inVortex}`)
  }

  console.log('PASS run MB (Book 2 chapters 1-2 mod budget): no inert cards across every weapon, four-plus apiece in both chapters, rate mods speed up, count mods land on bodies, and the three Pollution/clean-water cards pay the right way round — including that a fouled patch stops recharging you')
}
run(runModBudget)

// ─── run DB: the duo boons actually reach the player ─────────────────────────────────────────
// A DUO BOON is a weapon mod carrying `needs: '<weaponId>'` — a mod on weapon A that pays out
// through weapon B (The Shelf's Silt Plume and Silt Flush, both throwing up Silt Veil's own
// cloud). Holding the PAIR is already the card's whole scarcity, so the pool must not charge it
// the ordinary lottery on top of it.
// It shipped in v7.193.0 charging both, and was measured UNREACHABLE: offered on 0.6% of screens
// and ~16% of runs, and scripts/pool-probe.mjs reported 0.0% deliverability over 5 shelf runs
// that held the owning weapon in every single one. Nothing threw, no test went red, and the
// author only found out by asking why he had never seen his own card.
// Two mechanisms carry it now and EACH FAILS SILENTLY ON ITS OWN — a reserved candidate slot
// nobody can see from the cards, and a pity counter that simply stops advancing. Hence the four
// blocks below: the wiring, the pool, the guarantee, and the two ways the counter can be wrong.
function runDuoBoons() {
  // (a) WIRING. `needs` names a real weapon, and one the same chapter offers — a boon whose two
  // halves live in different pools can never be completed by playing, only by the dev menu.
  const duos = []
  for (const [wid, mods] of Object.entries(WEAPON_MODS)) {
    for (const [mid, cfg] of Object.entries(mods)) if (cfg.needs) duos.push([wid, mid, cfg.needs])
  }
  assert.ok(duos.length > 0, 'no mod in WEAPON_MODS declares `needs` — run DB is asserting on nothing')
  for (const [wid, mid, needs] of duos) {
    assert.ok(WEAPONS[needs], `${wid}.${mid} needs '${needs}', which is not a weapon id`)
    const chapters = Object.entries(CHAPTERS).filter(([, ch]) => ch.weapons?.includes(wid) && ch.weapons.includes(needs))
    assert.ok(chapters.length > 0,
      `${wid}.${mid} needs '${needs}' but no chapter's pool offers both — the pair cannot be completed by play`)
  }
  console.log(`PASS run DB.a (wiring): ${duos.length} duo boon(s), each naming a real weapon its own chapter also offers`)

  const shelfRun = (weapons, slots = 3) => {
    const r = createRun(makeMeta(), { chapter: 'shelf' })
    r.weapons = weapons.map((id) => ({ id, level: 3 }))
    r.choiceSlots = slots
    r.player.level = 12
    r.player.maxHP = 1e9
    r.player.hp = 1e9
    return r
  }

  // (b) THE RESERVED SLOT, asserted on the POOL rather than on the cards. Through
  // buildLevelUpChoices this could only ever be a rate with a band around it; here it is exact.
  // Silt Flush held 2 of Downwash's EIGHT candidate slots before this, so it was absent from three
  // pools in four before the rarity roll had even looked at it — and with four weapons owned the
  // MOD_POOL_MAX trim could then drop it again.
  Math.random = mulberry32(20260823)
  const POOLS = 300
  const full = shelfRun(['bubblePuff', 'siltVeil', 'ballast', 'downwash'])
  let bothInPool = 0
  for (let i = 0; i < POOLS; i++) {
    const cands = eligibleWeaponModCandidates(full)
    if (cands.some((c) => c.mod === 'siltPlume') && cands.some((c) => c.mod === 'siltFlush')) bothInPool++
  }
  assert.strictEqual(bothInPool, POOLS,
    `both duo boons must be RESERVED in every pool, saw both in ${bothInPool}/${POOLS} — either the per-weapon draw is not reserving them or the MOD_POOL_MAX trim is sampling them away`)
  // THE BUDGET, MEASURED WHERE THE TRIM CANNOT HIDE IT. Two weapons put 4 candidates in the pool,
  // under MOD_POOL_MAX, so nothing is sampled away and ballast's contribution is exactly what the
  // per-weapon draw gave it. Measured on the FOUR-weapon run above this reads 1.66 whether the
  // boon is reserved inside the budget or handed a slot on top of it — the trim washes the
  // difference out, and the mutation that widens the budget passed against it.
  Math.random = mulberry32(20260823)
  const untrimmed = shelfRun(['siltVeil', 'ballast'])
  let ballastEntries = 0
  for (let i = 0; i < POOLS; i++) {
    ballastEntries += eligibleWeaponModCandidates(untrimmed).filter((c) => c.weapon === 'ballast').length
  }
  const perPool = ballastEntries / POOLS
  assert.ok(perPool <= MOD_CANDIDATES_PER_WEAPON + 1e-9,
    `the reserved slot must come OUT OF the weapon's ${MOD_CANDIDATES_PER_WEAPON}-candidate budget, not on top of it — ballast contributed ${perPool.toFixed(2)} candidates per untrimmed pool, which is a stealth widening of the mod bucket`)
  // And the gate still holds in the other direction: no partner weapon, no candidate.
  Math.random = mulberry32(20260823)
  const half = shelfRun(['bubblePuff', 'ballast', 'downwash'])
  let leaked = 0
  for (let i = 0; i < POOLS; i++) {
    if (eligibleWeaponModCandidates(half).some((c) => c.mod === 'siltPlume' || c.mod === 'siltFlush')) leaked++
  }
  assert.strictEqual(leaked, 0, `a duo boon was a candidate in ${leaked}/${POOLS} pools of a run that does not hold Silt Veil — the reserved slot must not outrank the gate`)
  console.log(`PASS run DB.b (reserved): both boons in ${bothInPool}/${POOLS} trimmed pools, ${perPool.toFixed(2)} ballast candidates/untrimmed pool (cap ${MOD_CANDIDATES_PER_WEAPON}), 0/${POOLS} without the partner weapon`)

  // Drive real screens through the SHIPPED path — stepSim -> stepLevelUp -> buildLevelUpChoices —
  // because the pity counter is advanced in stepLevelUp and a fixture calling the builder directly
  // would never see it move. Returns the screen numbers a duo boon was offered on.
  const drive = (run, screens, modId) => {
    const at = []
    for (let i = 1; i <= screens; i++) {
      run.phase = 'playing'
      run.player.xp = run.player.xpNext
      stepSim(run, { x: 0, y: 0 }, 1 / 60)
      if (run.phase !== 'levelup') continue
      if (run.levelUpChoices.some((c) => c.kind === 'mod' && c.id === modId)) {
        at.push(i)
        // SPENT ON THE OFFER, not on the pick: nothing was taken here, and the credit is gone.
        assert.strictEqual(run._duoDry[modId], 0,
          `the boon was on screen ${i} and pity still reads ${run._duoDry[modId]} — the reset must run on the FINAL card list, below the anomaly swap and the new-weapon floor`)
      }
    }
    return at
  }

  // (c) THE GUARANTEE. Pity arms at DUO_PITY_SCREENS live screens and the boon then takes the next
  // mod card, so the arrival is bounded by "armed, plus however long the mod bucket takes to come
  // up". DRIVE is deliberately well past that: the property under test is that it ALWAYS lands
  // inside a real run's worth of screens, not the exact screen it lands on.
  const SEEDS = 12
  const DRIVE = 16
  let delivered = 0
  const firsts = []
  for (let s = 0; s < SEEDS; s++) {
    Math.random = mulberry32(20260823 + s)
    const r = shelfRun(['bubblePuff', 'siltVeil', 'ballast', 'downwash'])
    const at = drive(r, DRIVE, 'siltPlume')
    if (at.length > 0) { delivered++; firsts.push(at[0]) }
  }
  const meanFirst = firsts.reduce((a, b) => a + b, 0) / (firsts.length || 1)
  assert.strictEqual(delivered, SEEDS,
    `Silt Plume reached only ${delivered}/${SEEDS} runs holding the complete pair inside ${DRIVE} screens (pity is ${DUO_PITY_SCREENS}) — before the reserved slot and pity it was 0.6% of screens, which is what this asserts can never come back`)
  assert.ok(meanFirst <= DUO_PITY_SCREENS + 4,
    `the first Silt Plume averaged screen ${meanFirst.toFixed(1)} against a pity of ${DUO_PITY_SCREENS} — pity is arming but something downstream is swallowing the card`)
  console.log(`PASS run DB.c (guaranteed): Silt Plume in ${delivered}/${SEEDS} paired runs, first offer on screen ${meanFirst.toFixed(1)} of ${DRIVE} (pity ${DUO_PITY_SCREENS})`)

  // (d) THE TWO WAYS THE COUNTER GOES WRONG, and both are silent.
  // EARNED ONLY WHERE IT CAN BE SPENT: a run that completes the pair at level 20 must start
  // counting at level 20. Banking through the screens before that hands the boon over on the very
  // next card, which is the anomaly tier's own v6.7.9 lesson (credit earned on a schedule).
  Math.random = mulberry32(20260823)
  const unpaired = shelfRun(['bubblePuff', 'ballast', 'downwash'])
  const seenUnpaired = drive(unpaired, DRIVE * 2, 'siltPlume')
  assert.strictEqual(seenUnpaired.length, 0, `Silt Plume was offered ${seenUnpaired.length} time(s) to a run that never held Silt Veil`)
  assert.strictEqual(unpaired._duoDry?.siltPlume ?? 0, 0,
    `pity banked ${unpaired._duoDry?.siltPlume} dry screens for a boon whose partner weapon is not held — credit must be earned only on screens the pool could have spent it on`)

  // AND A PAID REROLL MUST NOT PUMP IT. The counter lives in stepLevelUp for exactly this reason:
  // rerollLevelUpChoices re-deals the screen by calling the builder again, so a counter kept in
  // the builder would step on every re-deal and let coins buy the guarantee early (the F5 defect,
  // in the same shape the anomaly tier had it).
  Math.random = mulberry32(20260823)
  const rr = shelfRun(['bubblePuff', 'siltVeil', 'ballast', 'downwash'])
  rr.coinsEarned = 100000
  rr.phase = 'playing'
  rr.player.xp = rr.player.xpNext
  stepSim(rr, { x: 0, y: 0 }, 1 / 60)
  assert.strictEqual(rr.phase, 'levelup', 'the reroll fixture never opened a screen')
  const beforeRerolls = rr._duoDry.siltPlume
  for (let i = 0; i < 5; i++) rerollLevelUpChoices(rr)
  // <=, not ===: a re-deal that OFFERS the boon legitimately spends the credit. Only an INCREASE
  // is the defect, and a counter moved into the builder would read beforeRerolls + 5 here.
  assert.ok(rr._duoDry.siltPlume <= beforeRerolls,
    `five paid rerolls took duo pity from ${beforeRerolls} to ${rr._duoDry.siltPlume} — the counter must be advanced by stepLevelUp, once per screen, or coins buy the guarantee`)
  console.log(`PASS run DB.d (pity is earned): 0 offers and 0 banked screens without the partner weapon, and 5 paid rerolls moved pity ${beforeRerolls} -> ${rr._duoDry.siltPlume}`)

  // (e) A REROLLED SCREEN IS NEVER SHORTER. The mod branch rolls CANDIDACY on the undecayed table
  // and SIZE on the decayed one, so once a reroll is paid for they are two different tiers — and a
  // `values` mod (both duo boons declare { epic: n }) accepts only the tiers it lists. Winning the
  // slot at epic and then being built at rare returns null, rollCard returns null, and
  // buildLevelUpChoices BREAKS out of the slot loop: the player pays for a re-deal and gets back
  // FEWER cards than they started with. Latent since v6.7.11 at 0.35% of rerolled shelf screens
  // while a values mod still had to win the candidate draw; reserving the duo boons puts one in
  // every shelf pool and took it to 1.36%, which is what makes this run DB's business.
  // Asserted at the REROLL CAP, where the two tables disagree most.
  const SCREENS = 4000
  Math.random = mulberry32(20260823)
  const shortRun = shelfRun(['bubblePuff', 'siltVeil', 'ballast', 'downwash'])
  shortRun._screenRerolls = REROLL_RARITY_CAP
  let short = 0
  for (let i = 0; i < SCREENS; i++) {
    const cards = buildLevelUpChoices(shortRun)
    if (cards.length < shortRun.choiceSlots && cards[0].kind !== 'heal') short++
  }
  assert.strictEqual(short, 0,
    `${short}/${SCREENS} rerolled screens came back with fewer than ${shortRun.choiceSlots} cards — a paid re-deal must never shorten the screen. The mod branch has to fall back to the tier the card won CANDIDACY at when the decayed tier declines it.`)
  console.log(`PASS run DB.e (no short screens): ${SCREENS}/${SCREENS} full screens at ${REROLL_RARITY_CAP} rerolls with both duo boons reserved in the pool`)
}
run(runDuoBoons)


// ---- Run ST: THE SHELF'S SPAWN TILT ----------------------------------------------------------
// Owner from play, 2026-08-21: "reduce top curve spawn numbers by 25% and increase bottom curve
// spawn by 25% (more mobs early, less late)". CHAPTERS.shelf.balance.spawnTilt is the first knob in
// this game that changes the SHAPE of a chapter's spawn curve rather than scaling all of it, so it
// has no existing guard to ride on.
//
// ASSERTED AS AN EFFECT AGAINST A TILT-0 CONTROL, and it has to be: reading run.mods.spawnTilt back
// passes with the multiply deleted from stepSpawning, which is the whole of the mechanic. And the
// control is the SAME chapter with the field cleared, not a different chapter — every other spawn
// input (spawnMul, maxAlive, the roster, the obstacle field) then cancels, so the only thing left
// that can move the counts is the tilt.
//
// Kill counting, not run.enemies.length: maxAliveFor caps the live array, so the cap absorbs the
// early surge and the ARRAY reads nearly flat while the SPAWN RATE is 25% up. That version of this
// test measured 61 against 60 and would have passed with the tilt at any value. Immortal player,
// one big weapon, so the crowd is consumed as fast as it arrives and total spawns show up as kills.
function runSpawnTilt() {
  const dt = 1 / 60
  const window = (tilt, from, to) => {
    Math.random = mulberry32(90210)
    const meta = makeMeta()
    ensureChapterMeta(meta, 'shelf')
    meta.chapters.shelf.unlocked = true
    const run = createRun(meta, { chapter: 'shelf', difficulty: 3 })
    assert.strictEqual(run.chapter, 'shelf', 'the tilt harness booted the wrong chapter')
    run.mods.spawnTilt = tilt
    run.player.maxHP = run.player.hp = 1e9
    run.weapons = [{ id: 'bubblePuff', level: 5 }]
    let kills = 0, prev = run.kills ?? 0
    while (run.time < to && run.phase !== 'dead') {
      if (run.phase === 'levelup') { run.phase = 'playing'; continue }
      stepSim(run, { x: 0, y: 0 }, dt)
      run.events.length = 0
      const now = run.kills ?? 0
      if (run.time >= from) kills += now - prev
      prev = now
    }
    return kills
  }
  const TILT = CHAPTERS.shelf.balance.spawnTilt
  assert.ok(TILT > 0, 'CHAPTERS.shelf.balance.spawnTilt is gone — this scenario has nothing to measure')

  // The FIRST 60s against the same 60s with the tilt off. spawnTiltMul is 1 + tilt at t=0 falling
  // to 1 at half a run, so the early window should sit around +19% (the mean of the ramp) — banded
  // wide because the two arms diverge into different worlds after the first extra spawn.
  const earlyOn = window(TILT, 0, 60), earlyOff = window(0, 0, 60)
  assert.ok(earlyOn > earlyOff * 1.06,
    `The Shelf's tilt must front-load the crowd: ${earlyOn} kills in the first 60s against a flat curve's ${earlyOff}`)

  // ...and the LAST 60s must go the other way, or the knob is a plain spawnMul with extra steps.
  const lateOn = window(TILT, 240, 300), lateOff = window(0, 240, 300)
  assert.ok(lateOn < lateOff * 0.94,
    `The Shelf's tilt must thin the late crowd: ${lateOn} kills over 240-300s against a flat curve's ${lateOff}`)

  // AND IT IS A TILT, NOT A CUT — the assertion the other two cannot make on their own. The RATIO
  // of early to late is what a reshape moves and what a flat spawnMul cannot touch at all: halving
  // every spawn in the run passes "fewer late" and would pass "more early" against a weaker control,
  // and leaves this number exactly where it started.
  //   NOT a total-conservation check. The first cut of this scenario asserted one and went red at
  // 527 against 603, correctly: spawnRate is back-loaded (a t^2 term past SPAWN_LATE_START), so a
  // symmetric +-25% takes more bodies out of the late half than it puts into the early one. The
  // tilt really does cut ~13% of the run's spawns, and that is recorded in spawnTiltMul's own block
  // rather than papered over here.
  const ratioOn = earlyOn / lateOn, ratioOff = earlyOff / lateOff
  assert.ok(ratioOn > ratioOff * 1.15,
    `the tilt changed the count but not the shape: early:late ${ratioOn.toFixed(3)} tilted against ${ratioOff.toFixed(3)} flat`)

  // The other six Undertow chapters must not have quietly acquired one.
  const tilted = Object.keys(CHAPTERS).filter((id) => (CHAPTERS[id].balance?.spawnTilt ?? 0) !== 0)
  assert.deepStrictEqual(tilted, ['shelf'],
    `spawnTilt is meant to be The Shelf's alone, found it on ${tilted.join(', ')}`)

  console.log(`PASS run ST (shelf spawn tilt): first 60s ${earlyOff} -> ${earlyOn} kills, last 60s ${lateOff} -> ${lateOn}, early:late ${ratioOff.toFixed(2)} -> ${ratioOn.toFixed(2)} — a pivot, not a flat cut, and 1 of ${Object.keys(CHAPTERS).length} chapters carries it`)
}
run(runSpawnTilt)


// ---- Run PY: THE WRECK, after the premise turned round (v7.x, owner directive) ----------------
// "about you, a shark, chasing after schools of fishes that run in fear. Turning around the premise
// of the game." Every other chapter in this game resolves to "walk at the player"; this one is the
// exception, and the exception has to be guarded on both of its halves.
//
// WHAT MAKES THIS WORTH A SCENARIO rather than a config assert: `skittish` is ONE flag saying TWO
// things, in two places, with no import between them — it inverts movement (stepPrey) and it
// disarms contact damage (contactHarmless). Delete either half and the chapter still runs, still
// spawns, and still looks approximately right in a screenshot, and it is a different game. A fish
// that flees but still bites is an aggro chapter with extra steps; a fish that bites nothing but
// walks at you is a piñata parade.
//
// Every block below asserts an EFFECT against a CONTROL with the feature removed, because an
// assertion that only reads a flag back passes with the mechanic deleted.
function runPrey() {
  const dt = 1 / 60
  const wkMeta = () => { const m = makeMeta(); m.dev = true; ensureChapterMeta(m); return m }
  // Immortal, weaponless, motionless by default. Weapons would kill the subject mid-measurement and
  // the fixture would then be reading an empty field, which is the "spawned nothing" trap in its
  // other direction.
  const mk = (seed = 20260817) => {
    Math.random = mulberry32(seed)
    const run = createRun(wkMeta(), { chapter: 'wreck', difficulty: 1 })
    // THE WATER OFF, for the whole scenario. Since v7.x the tide runs in every Undertow chapter but
    // The Reef rather than in The Surf alone (run TD owns that contract), so The Wreck drifts the
    // player AND the crowd up to ~100px on its own — and every block below reasons about where
    // things ARE:
    // PY.g asks whether a weapon moved them, PY.l whether a pool landed at their feet. Left on, it
    // reported all 38 weapons breaking the golden rule and 82 of 85 pools landing away from the
    // feet, i.e. it accused the arsenal of what the ambient mover did. tideSurgeMul 0 is the shipped
    // knob for the whole field, which is what the crowd needs too — stepTide pushes the ENEMIES by
    // the full vector whatever the player bought, so a player-only knob still drifts a pinned body.
    run.mods.tideSurgeMul = 0
    run.weapons = []
    run.player.maxHP = run.player.hp = 1e9
    run.enemies.length = 0
    return run
  }
  // PIN BY IDENTITY, NEVER BY INDEX — this chapter spawns hard (spawnMul 2.2), so a subject left in
  // the live array is one splice away from being some other fish, and nothing would say so.
  const only = (run, es) => { run.enemies.length = 0; run.enemies.push(...es) }
  const put = (run, o) => {
    const e = makeStatusEnemy(run, o)
    e.flags = o.flags ?? []
    return e
  }

  // -- PY.a: they RUN. The whole premise, with the flag removed as the control. -----------------
  {
    const measure = (flags) => {
      const run = mk()
      const p = run.player
      // Well inside PREY_SIGHT_R, so a skittish fish has seen the player from frame one.
      const e = put(run, { x: p.x + 120, y: p.y, hp: 1e6, speed: 90, flags })
      const d0 = Math.hypot(e.x - p.x, e.y - p.y)
      for (let i = 0; i < Math.round(2 / dt); i++) {
        only(run, [e])
        stepSim(run, { x: 0, y: 0 }, dt)
      }
      return Math.hypot(e.x - run.player.x, e.y - run.player.y) - d0
    }
    const prey = measure(['skittish'])
    const control = measure([])
    assert.ok(prey > 60, `a skittish fish must RUN: it ended ${prey.toFixed(0)}px further out over 2s, wanted > 60`)
    assert.ok(control < -60, `the control must still CHASE, or this block proves nothing about the flag (moved ${control.toFixed(0)}px)`)
    console.log(`PASS run PY.a (they run): skittish +${prey.toFixed(0)}px in 2s vs the same fish flagless at ${control.toFixed(0)}px`)
  }

  // -- PY.b: they CANNOT HURT YOU. The half that lives in a different function. -----------------
  // Sat ON the player, which is the worst case the chapter can produce and the one 620 concurrent
  // bodies will find on their own.
  {
    const measure = (flags) => {
      const run = mk()
      const p = run.player
      const e = put(run, { x: p.x, y: p.y, hp: 1e6, speed: 0, flags })
      const hp0 = p.hp
      for (let i = 0; i < Math.round(5 / dt); i++) {
        only(run, [e])
        e.x = run.player.x; e.y = run.player.y   // held on top of the player, not merely nearby
        stepSim(run, { x: 0, y: 0 }, dt)
      }
      return hp0 - run.player.hp
    }
    const prey = measure(['skittish'])
    const control = measure([])
    assert.strictEqual(prey, 0, `prey must deal EXACTLY zero contact damage; it dealt ${prey}. hurtPlayer floors a hit at 1, so a roster dmgMul of 0 is not enough on its own — this needs contactHarmless`)
    assert.ok(control > 0, `the control must still bite, or this block passes with contact damage deleted globally (took ${control})`)
    console.log(`PASS run PY.b (harmless): 5s sat on the player costs 0 HP, where the same fish flagless costs ${control}`)
  }

  // -- PY.c: they run as a SCHOOL. -------------------------------------------------------------
  // The cheap part of the design and the part most likely to be "simplified" away later: the shoal
  // is an id bucket, so two fish spawned together must break the same way and two from different
  // buckets must not. Without it the field scatters radially and there are no schools at all.
  // MEASURED OUTSIDE PREY_SIGHT_R, ON THE MILL, and that is the fixture decision that makes this
  // block mean anything. Inside the sight radius the heading is 70% "straight away from the player"
  // (PREY_FLEE_BLEND), so two fish a few px apart share a heading whatever the shoal says and the
  // assertion would pass with the bucket deleted. Worse, at that spacing they overlap, and the
  // separation pass shoves them apart hard enough to be the only thing the measurement sees — the
  // first cut of this block read 0.41 rad between two fish in ONE shoal for exactly that reason.
  // Out here the drift heading is the ONLY input, which is the one thing being tested.
  {
    const run = mk()
    const p = run.player
    const D = PREY_SIGHT_R + 160
    const a = put(run, { x: p.x + D, y: p.y, hp: 1e6, speed: 90, flags: ['skittish'] })
    const b = put(run, { x: p.x - D, y: p.y, hp: 1e6, speed: 90, flags: ['skittish'] })
    const c = put(run, { x: p.x, y: p.y + D, hp: 1e6, speed: 90, flags: ['skittish'] })
    // Ids PINNED, not inherited from the spawn counter: two consecutive ids land in different
    // buckets whenever the first is the last of its bucket, which is a 1-in-PREY_SHOAL_SIZE chance
    // of a mystery red on an unrelated edit.
    a.id = 2 * PREY_SHOAL_SIZE
    b.id = a.id + 1                        // same school as `a`
    c.id = a.id + PREY_SHOAL_SIZE          // deliberately the next school along
    const start = [a, b, c].map((e) => ({ x: e.x, y: e.y }))
    for (let i = 0; i < Math.round(1.5 / dt); i++) {
      only(run, [a, b, c])
      stepSim(run, { x: 0, y: 0 }, dt)
    }
    const head = (e, s) => Math.atan2(e.y - s.y, e.x - s.x)
    const gap = (u, v) => Math.abs(((u - v + Math.PI * 3) % (Math.PI * 2)) - Math.PI)
    const hA = head(a, start[0]), hB = head(b, start[1]), hC = head(c, start[2])
    assert.ok(gap(hA, hB) < 0.2, `two fish in one shoal must break together (headings ${gap(hA, hB).toFixed(2)} rad apart, wanted < 0.2)`)
    assert.ok(gap(hA, hC) > 0.4, `two fish in DIFFERENT shoals must not (headings ${gap(hA, hC).toFixed(2)} rad apart, wanted > 0.4) — if this fails the id bucket is not reaching the heading and the whole field is one school`)
    console.log(`PASS run PY.c (schools): same bucket breaks ${gap(hA, hB).toFixed(2)} rad apart, a neighbouring shoal ${gap(hA, hC).toFixed(2)} rad`)
  }

  // -- PY.d: GNASH pays for closing. -----------------------------------------------------------
  // The falloff runs backwards to every other reach number in the game, which is exactly the kind of
  // inversion a later editor "fixes".
  //
  // MEASURED ACROSS ONE CAST, NOT ACROSS TWO RUNS: two bodies on the same ray, struck by the same
  // sweep at different depths. That is the shape the ramp really has in play, and unlike two runs
  // it cannot be confounded by crits or spawns landing differently on either side.
  {
    const lv = WEAPONS.gnash.levels[0]
    const NEAR_F = 0.15, FAR_F = 0.9
    const run = mk(20260818)
    run.weapons = [{ id: 'gnash', level: 1 }]
    const p = run.player
    const x0 = p.x, y0 = p.y
    const near = put(run, { x: x0 + lv.range * NEAR_F, y: y0, hp: 1e12, speed: 0 })
    const far = put(run, { x: x0 + lv.range * FAR_F, y: y0, hp: 1e12, speed: 0 })
    let dNear = 0, dFar = 0
    for (let i = 0; i < Math.round(20 / dt); i++) {
      only(run, [near, far])
      run.player.x = x0; run.player.y = y0
      near.x = x0 + lv.range * NEAR_F; near.y = y0
      far.x = x0 + lv.range * FAR_F; far.y = y0
      const bn = near.hp, bf = far.hp
      stepSim(run, { x: 0, y: 0 }, dt)
      dNear += bn - near.hp
      dFar += bf - far.hp
    }
    assert.ok(dFar > 0, 'the far body must still be struck, or this is measuring a range cut rather than a falloff')
    const ratio = dNear / dFar
    const want = (1 + (1 - NEAR_F) * (GNASH_MAW_MUL - 1)) / (1 + (1 - FAR_F) * (GNASH_MAW_MUL - 1))
    // Wide enough for crit noise on one seed (GNASH_BASE_CRIT puts 10 points on every bite) and far
    // too narrow to survive the ramp being deleted, which lands the ratio at exactly 1.0.
    assert.ok(ratio > 1.30 && ratio < 2.05, `in one cast, a body at ${NEAR_F} of the reach must take ~${want.toFixed(2)}x what one at ${FAR_F} takes; measured ${ratio.toFixed(2)}x (${dNear} vs ${dFar})`)
    console.log(`PASS run PY.d (the bite pays for closing): one sweep deals ${ratio.toFixed(2)}x more to the near body than the far one over 20s (predicted ${want.toFixed(2)}x)`)
  }

  // -- PY.g: AN ATTACK NEVER MOVES THE PLAYER. -------------------------------------------------
  // Owner, 2026-08-18: "attacks = no movement that's the golden rule. The action though can make
  // you dash to nearest target." Stated over EVERY weapon in the game rather than over this
  // chapter's three, because it is a rule about attacks and gnash was merely where it got broken.
  //
  // The rule is not vacuous: sim.js has four sites that move the player outright, and the other
  // three are all things done TO you — the Blank's yank, the tide, an abduction beam. None is a
  // weapon. The one sanctioned exception is the BUTTON, which is PY.k's subject and is why this
  // block equips weapons only and sends no press.
  //
  // The chapter's own tide is switched off in mk() — see the note there; without it this block
  // accuses all 38 weapons of what the water did.
  {
    const ids = Object.keys(WEAPONS)
    const moved = []
    for (const id of ids) {
      const run = mk(20260819)
      run.weapons = [{ id, level: 1 }]
      const p = run.player
      const x0 = p.x, y0 = p.y
      // A body inside the shortest reach in the game, pinned every step so nothing the weapon does
      // to IT can be mistaken for something done to the player.
      const e = put(run, { x: x0 + 60, y: y0, hp: 1e12, speed: 0 })
      for (let i = 0; i < Math.round(2 / dt); i++) {
        only(run, [e])
        e.x = x0 + 60; e.y = y0
        stepSim(run, { x: 0, y: 0 }, dt)
      }
      const d = Math.hypot(p.x - x0, p.y - y0)
      if (d > 0.5) moved.push(`${id} ${d.toFixed(0)}px`)
    }
    assert.ok(ids.length > 20, `this sweep is only worth its name over the whole arsenal; it saw ${ids.length} weapons`)
    assert.deepStrictEqual(moved, [], `an attack must never move the player. These did: ${moved.join(', ')}`)
    console.log(`PASS run PY.g (attacks do not move you): all ${ids.length} weapons fired for 2s at a body in reach, every one of them left the player where it found them`)
  }

  // -- PY.e: THE LEAK is the only thing that can kill you, and it FOULS you. --------------------
  // Two effects on one hazard, and the second is the one with no other guard: the slow LINGERS past
  // the rim, which is the whole difference between a decision and a tax.
  {
    const soak = (withSlick) => {
      const run = mk()
      // One step first, so streamSlicks does its cell scan and then early-returns for good (the
      // player never leaves the cell). A spill pushed before that scan would be spliced out.
      stepSim(run, { x: 0, y: 0 }, dt)
      if (withSlick) run.slicks.push({ x: run.player.x, y: run.player.y, r: 400, shape: null, rot: 0, _cell: 'test' })
      const hp0 = run.player.hp
      const x0 = run.player.x
      for (let i = 0; i < Math.round(3 / dt); i++) {
        run.enemies.length = 0
        stepSim(run, { x: 1, y: 0 }, dt)
      }
      return { lost: hp0 - run.player.hp, moved: run.player.x - x0, run }
    }
    const inIt = soak(true)
    const out = soak(false)
    assert.ok(inIt.lost >= SLICK_DPS * 3 * 0.8, `3s in a spill must cost about ${SLICK_DPS * 3} HP; it cost ${inIt.lost}`)
    assert.strictEqual(out.lost, 0, `the same 3s outside one must cost nothing; it cost ${out.lost}`)
    const slowRatio = inIt.moved / out.moved
    assert.ok(slowRatio < SLICK_SLOW_MUL + 0.06, `oil must slow you to about x${SLICK_SLOW_MUL}; measured x${slowRatio.toFixed(2)}`)
    // THE LINGER. The spill is removed — the player has swum clear — and must still be fouled.
    const r = inIt.run
    r.slicks.length = 0
    const lx = r.player.x
    const secs = SLICK_SLOW_T * 0.6
    for (let i = 0; i < Math.round(secs / dt); i++) {
      r.enemies.length = 0
      stepSim(r, { x: 1, y: 0 }, dt)
    }
    const afterRatio = (r.player.x - lx) / (out.moved * secs / 3)
    assert.ok(afterRatio < SLICK_SLOW_MUL + 0.1, `the fouling must OUTLIVE the rim for ${SLICK_SLOW_T}s; measured x${afterRatio.toFixed(2)} of clean speed immediately after leaving`)
    console.log(`PASS run PY.e (the leak): 3s inside costs ${inIt.lost} HP and x${slowRatio.toFixed(2)} speed against 0 and x1 outside, and the fouling holds at x${afterRatio.toFixed(2)} once you are clear`)
  }

  // -- PY.f: a spill is NOT a refill circle. ---------------------------------------------------
  // The one-line guard on the decision that keeps run.slicks out of run.shafts. stepCharge loops
  // run.shafts handing out resource; if a slick ever lands in that array the chapter's bar THANKS
  // the player for standing in poison, and nothing throws.
  {
    const run = mk()
    stepSim(run, { x: 0, y: 0 }, dt)
    run.charge = 10
    run.slicks.push({ x: run.player.x, y: run.player.y, r: 400, shape: null, rot: 0, _cell: 'test' })
    const c0 = run.charge
    for (let i = 0; i < Math.round(2 / dt); i++) { run.enemies.length = 0; stepSim(run, { x: 0, y: 0 }, dt) }
    assert.ok(run.charge <= c0, `standing in a spill must never RAISE Bloodlust (${c0} -> ${run.charge}) — that is what putting slicks in run.shafts would do`)
    assert.strictEqual(run.shafts.length, 0, 'The Wreck declares no refill circle at all, so run.shafts must stay empty — a non-empty one means refillSpec() started recognising the leak')
    console.log(`PASS run PY.f (a spill is not a refill): 2s in one takes Bloodlust ${c0} -> ${run.charge.toFixed(1)}, and run.shafts stays empty`)
  }

  // -- PY.h: CHUM turns them round. -------------------------------------------------------------
  // The one card in the game that makes something already running come back, and it is one boolean
  // away from being its own opposite: the lure override sets the seek target and stepPrey FLEES the
  // seek target, so an untagged bait is a repellent that reads as a bug and throws nothing. The
  // control is the same decoy WITHOUT `bait`.
  {
    const gather = (bait) => {
      const run = mk()
      const p = run.player
      // The fish sits between the player and the bait, outside CHUM_PANIC_R of the player so its
      // nerve holds — inside that radius it bolts whatever the bait says, which is PY.i.
      // 220px from the bait, which is INSIDE PREY_SIGHT_R — the control has to be able to see the
      // decoy or it merely drifts, and a drift that happens to wander the right way passes a test
      // about repulsion. (It did: the first cut put the fish 360px out, past the 340px sight
      // radius, and the untagged control read +19px toward the thing it was supposed to flee.)
      // Also outside CHUM_PANIC_R of the PLAYER, or the baited case would bolt instead — PY.i.
      const e = put(run, { x: p.x + 400, y: p.y, hp: 1e6, speed: 90, flags: ['skittish'] })
      const bx = p.x + 620, by = p.y
      run.lures.length = 0
      run.lures.push({ x: bx, y: by, t: 0, dur: 99, aggro: 900, burstR: 0, burstDmg: 0, bait })
      const d0 = Math.hypot(e.x - bx, e.y - by)
      for (let i = 0; i < Math.round(2 / dt); i++) {
        only(run, [e])
        if (run.lures.length === 0) run.lures.push({ x: bx, y: by, t: 0, dur: 99, aggro: 900, burstR: 0, burstDmg: 0, bait })
        run.lures[0].t = 0
        stepSim(run, { x: 0, y: 0 }, dt)
      }
      return d0 - Math.hypot(e.x - bx, e.y - by)   // + = it closed on the bait
    }
    const baited = gather(true)
    const plain = gather(false)
    assert.ok(baited > 50, `a baited fish must come TO the chum; it closed ${baited.toFixed(0)}px in 2s`)
    assert.ok(plain < 0, `the same decoy untagged must still repel, or the tag is doing nothing and the card only appears to work (moved ${plain.toFixed(0)}px)`)
    console.log(`PASS run PY.h (chum gathers): a baited fish closes ${baited.toFixed(0)}px on it where the untagged decoy pushes it ${(-plain).toFixed(0)}px away`)
  }

  // -- PY.i: chum is not an off-switch. ----------------------------------------------------------
  // The panic override, which is the only thing stopping the card from parking the whole chapter in
  // one place: a fish that is baited AND close to the player bolts anyway.
  {
    const run = mk()
    const p = run.player
    // THE BAIT SITS BEHIND THE PLAYER, on the far side from the fish, and that geometry is the
    // whole test. With the bait BEYOND the fish, "swim to the bait" and "flee the player" both move
    // it the same way, so the fixture cannot tell the two apart — the mutation that deletes the
    // panic override survived exactly that. Here they point in opposite directions: panicking sends
    // the fish +x, and the broken behaviour sends it -x, back through the predator.
    // DERIVED FROM CHUM_PANIC_R, NOT A LITERAL. The fixture only works while the fish starts well
    // inside the panic radius with room to bolt before it exits — a hardcoded 60px silently became
    // a 20px runway when the radius came down from 150 to 80, and the assertion failed for the
    // geometry rather than for the behaviour it is guarding.
    const e = put(run, { x: p.x + CHUM_PANIC_R * 0.25, y: p.y, hp: 1e6, speed: 90, flags: ['skittish'] })
    const bx = p.x - 400, by = p.y
    const x0 = e.x
    const d0 = Math.hypot(e.x - p.x, e.y - p.y)
    for (let i = 0; i < Math.round(1.5 / dt); i++) {
      only(run, [e])
      run.lures.length = 0
      run.lures.push({ x: bx, y: by, t: 0, dur: 99, aggro: 900, burstR: 0, burstDmg: 0, bait: true })
      stepSim(run, { x: 0, y: 0 }, dt)
    }
    const gained = e.x - x0
    assert.ok(gained > CHUM_PANIC_R * 0.35, `a baited fish INSIDE ${CHUM_PANIC_R}px must still bolt AWAY from the player (+x), not back toward the bait behind it (-x); it moved ${gained.toFixed(0)}px`)
    console.log(`PASS run PY.i (chum is not an off-switch): a baited fish ${Math.round(d0)}px from the player still bolts, +${gained.toFixed(0)}px in 1.5s`)
  }

  // -- PY.j: BILGE is a wall to prey and a drag to everything else. ------------------------------
  // Both halves, because they look like they contradict each other and do not: prey refuse to enter,
  // so the slow is what happens to the things that CANNOT refuse.
  {
    // THE TWO CASES START IN DIFFERENT PLACES, and they have to: each body must be driven into the
    // oil BY ITS OWN BEHAVIOUR or the fixture proves nothing about the wall. Prey run away from the
    // player, so a slick beyond them is in their path; a chaser walks toward the player, so its
    // slick has to sit between the two. The first cut used one geometry for both and the control
    // simply walked off in the other direction, never touching the oil it was meant to walk into.
    const oil = (flags, startX) => {
      const run = mk()
      const p = run.player
      const e = put(run, { x: p.x + startX, y: p.y, hp: 1e6, speed: 90, flags })
      const bx = p.x + 420, by = p.y
      let deepest = Infinity
      for (let i = 0; i < Math.round(3 / dt); i++) {
        only(run, [e])
        run.blooms.length = 0
        // ⚠ `t` PAST THE GROW RAMP, AND IT IS LOAD-BEARING. stepBlooms rewrites bl.r from bl.t
        // every frame: this used to be pushed at t: 0 with dur 99, so growT was 34.65s and the
        // "150px slick" was a wall of radius 0.07px. Both arms passed with the mechanic entirely
        // absent — prey wandered past a point, a chaser walked through it. dur 200 / t 100 puts
        // every frame past the ramp, so the radius drawn here is the radius that acts.
        run.blooms.push({ x: bx, y: by, t: 100, r: 150, maxR: 150, dur: 200, dmgPerTick: 0, tick: 0, look: 'bilge', slow: 1 })
        stepSim(run, { x: 0, y: 0 }, dt)
        deepest = Math.min(deepest, Math.hypot(e.x - bx, e.y - by))
      }
      return deepest    // how close to the slick's CENTRE it ever got
    }
    const prey = oil(['skittish'], 150)   // fleeing +x takes it into the slick at +420
    const other = oil([], 600)            // chasing -x takes it through the same slick
    assert.ok(prey > 150 * 0.6, `prey must refuse the oil; the fish reached ${prey.toFixed(0)}px from the centre of a 150px slick`)
    assert.ok(other < 150, `a non-prey body must NOT be walled out, or the card is a barrier against everything and the slow half is unreachable (reached ${other.toFixed(0)}px)`)
    console.log(`PASS run PY.j (the oil is a wall to prey): a skittish fish never gets closer than ${prey.toFixed(0)}px to a 150px slick, where a flagless one walks to ${other.toFixed(0)}px`)
  }

  // -- PY.k: the button dashes at FOOD. ---------------------------------------------------------
  // Owner ruling 2026-08-18. The moray is `guard`-windowed, so a Lunge that picks it can spend the
  // bar on a body that refuses the damage and never pays LUNGE_KILL_REFILL back — and being the
  // SLOWEST thing in the chapter it is very often the nearest, so the untargeted button chose the
  // one wrong answer most of the time. The fixture puts the tank CLOSER, which is the case that
  // used to fail.
  {
    const run = mk()
    const p = run.player
    run.weapons = []
    run.charge = CHAPTERS.wreck.resource.max
    run.repulseCd = 0
    // Tank at 80px on the -x side; prey at 300px on the +x side. Nearest-anything picks the tank.
    const tank = put(run, { x: p.x - 80, y: p.y, hp: 1e9, speed: 0, flags: ['guard'] })
    tank.type = 'tank'
    const prey = put(run, { x: p.x + 300, y: p.y, hp: 1e9, speed: 0, flags: ['skittish'] })
    const x0 = p.x
    let first = true
    for (let i = 0; i < Math.round(0.4 / dt); i++) {
      only(run, [tank, prey])
      tank.x = x0 - 80; tank.y = p.y
      prey.x = x0 + 300; prey.y = p.y
      stepSim(run, { x: 0, y: 0, skill: first }, dt)
      first = false
    }
    const dx = run.player.x - x0
    assert.ok(dx > 30, `the Lunge must dash toward the PREY (+x) and not the nearer tank (-x); the player moved ${dx.toFixed(0)}px`)
    console.log(`PASS run PY.k (the button dashes at food): with a tank 80px away and prey at 300px, the press carried the player ${dx.toFixed(0)}px toward the prey`)
  }

  // -- PY.l: the OIL lands on a RANDOM VISIBLE body, not on your feet and not on the nearest. -----
  // Two owner corrections, one block, because the second only makes sense against the first:
  //   "the mazout is a small trap zone that takes time to expand, starting from you. by the time
  //   it's expanded, you're already far away. instead, it should spawn under an enemy"
  //   "no, this targets the closest enemy, which will be bitten in the next .5s. it should target
  //   a random visible enemy"
  // A pool takes dur * BLOOM_GROW_FRAC (1.6-2.2s) to reach full size and the player crosses ~350px
  // in that time, so WHERE it opens is the whole of whether it is ever touched. And the nearest
  // body is the one gnash's jaw and the Lunge are both already pointed at, so planting there buys
  // a kill the build had already bought — a card that looks like it fires and changes nothing.
  //
  // THREE PROPERTIES, and each has a control that fails on its own:
  //   on a body            — vs slickTrail, which must still lay the fence at the feet
  //   SPREAD over the crowd— vs "always the nearest", which passes every single-enemy fixture
  //   on screen only       — vs a body parked outside run.viewW, which must never be chosen
  {
    // ⚠ THE FENCE BRANCH HAS TO SWIM (v7.x). slickTrail is triggered by DISTANCE TRAVELLED, so a
    // fixture driving a zero input lays exactly one pool and `fence.every(...)` then passes over an
    // empty list — a check that reads green while checking nothing. `input` is the axis that keeps
    // it honest, and `still` below is the control that proves the trigger really is distance.
    const gather = (mods, input = { x: 0, y: 0 }) => {
      const run = mk(20260821)
      run.weapons = [{ id: 'bilge', level: 1 }]
      run.weaponMods.bilge = mods
      // ⚠ AND THE ORCA HAS TO BE PARKED (v7.x). Its commit wake shoves the PLAYER sideways, which is
      // real distance travelled and therefore real slickTrail pools — so `still` below stops being
      // still the moment the first visit lands inside this 120s window. Parked rather than loosened
      // in the assertion: the subject here is bilge's targeting, and an apex predator eating the
      // fixture's crowd mid-run is noise in all three branches, not only the control.
      run._orcaAcc = 1e9
      const p = run.player
      // Inside run.viewW/viewH (480/360 headless), at four clearly separated distances so "which
      // one was chosen" is readable from the pool's position alone. Pinned to the LIVE player each
      // frame rather than to the spawn point: the fence branch travels 26,000px, and a crowd left
      // behind at the origin would put every branch off-screen within a second.
      const at = [[120, 0], [240, 0], [360, 0], [0, 300]]
      const crowd = at.map(([dx, dy]) => put(run, { x: p.x + dx, y: p.y + dy, hp: 1e12, speed: 0, flags: ['skittish'] }))
      // Well outside the viewport. An effect that arrives from off-screen is worse than one that
      // arrives too close, so this must never be picked.
      const offScreen = put(run, { x: p.x + 2000, y: p.y, hp: 1e12, speed: 0, flags: ['skittish'] })
      const all = [...crowd, offScreen]
      const seen = new Set()
      const hits = []            // index into `all` for every pool planted, -1 for the feet
      for (let i = 0; i < Math.round(120 / dt); i++) {
        only(run, all)
        all.forEach((e, k) => { e.x = p.x + (k < 4 ? at[k][0] : 2000); e.y = p.y + (k < 4 ? at[k][1] : 0) })
        stepSim(run, input, dt)
        for (const bl of run.blooms) {
          if (bl.look !== 'bilge' || seen.has(bl)) continue
          seen.add(bl)
          const k = all.findIndex((e) => Math.hypot(bl.x - e.x, bl.y - e.y) < 1)
          hits.push(k >= 0 ? k : (Math.hypot(bl.x - p.x, bl.y - p.y) < 2 ? -1 : -2))
        }
      }
      return hits
    }

    const aimed = gather({})
    const fence = gather({ slickTrail: 1 }, { x: 1, y: 0 })
    const still = gather({ slickTrail: 1 })
    assert.ok(aimed.length >= 8, `bilge planted only ${aimed.length} pools in 120s — too few to say anything about their spread`)
    assert.ok(!aimed.includes(-2), 'every pool must open ON a body, not at some third place')
    assert.ok(!aimed.includes(-1), 'with the crowd on screen no pool may open at the player\'s feet')
    assert.ok(!aimed.includes(4), 'a body outside run.viewW must never be chosen — that is a zone arriving from off-screen')
    const distinct = new Set(aimed).size
    assert.ok(distinct >= 3, `the oil must SPREAD over the visible crowd; it used ${distinct} of 4 bodies across ${aimed.length} casts (targeting the nearest would read 1)`)
    assert.ok(fence.length >= 100, `slickTrail laid only ${fence.length} pools over 120s of swimming — a fence that does not get drawn is not a fence`)
    assert.ok(fence.every((k) => k === -1), `slickTrail draws a fence BEHIND you, so every trail pool must lay at the feet; got ${fence.filter((k) => k !== -1).length} of ${fence.length} elsewhere`)
    // THE TRIGGER IS DISTANCE, AND THIS IS THE ONLY ASSERTION THAT SAYS SO. On the shipped timer a
    // motionless player carpeted their own square in oil; one pool is the first-cast seed.
    assert.ok(still.length <= 1, `a player who never moves must not pour a fence; standing for 120s laid ${still.length} pools`)
    console.log(`PASS run PY.l (the oil lands on a random visible body): ${aimed.length} casts spread over ${distinct} of 4 on-screen bodies, never the off-screen one and never underfoot, where slickTrail lays ${fence.length} pools at the feet while swimming and ${still.length} while standing still`)
  }

  // -- PY.l2: the trail is a TRAIL, not a row of puddles. ----------------------------------------
  // Owner, 2026-08-23: "mazout is only puddles, when it trails behind you it should be a trail not
  // puddles." A chain of pools is a trail only if consecutive links OVERLAP ON SCREEN, and PY.l
  // above cannot see that at all — it only asks where each pool landed.
  //   TWO WAYS TO BREAK IT, and each needs its own half of the assertion:
  //   - SPACING. On the shipped cast timer the gap was the cast interval times the player's speed,
  //     two numbers with nothing holding them together: 333px between 139px-wide pools at this
  //     chapter's 220px/s. Distance triggering is what ties them.
  //   - GROWTH. A pool that is still growing is a point. On the shared BLOOM_GROW_FRAC ramp (1.6s
  //     here) every pool laid in the last 350px of travel is under a fifth of its radius, so the
  //     stretch directly behind the player — the only stretch they are looking at — is dotted
  //     however tightly it is spaced. BILGE_TRAIL_GROW is what closes it.
  // So the measurement is taken on the LIVE radii of the live chain, which is what the player sees.
  {
    const run = mk(20260823)
    run.weapons = [{ id: 'bilge', level: 1 }]
    run.weaponMods.bilge = { slickTrail: 1 }
    // Swim in a straight line for long enough that the oldest pools have started expiring, so the
    // chain under test is a steady-state one rather than the opening burst.
    for (let i = 0; i < Math.round(6 / dt); i++) {
      only(run, [])
      stepSim(run, { x: 1, y: 0 }, dt)
    }
    const chain = run.blooms.filter((b) => b.look === 'bilge')
    // A PRECONDITION, NOT THE ASSERTION — deliberately low. "Is a fence drawn at all" is PY.l's
    // question (it wants 100+ pools over the same kind of swim); this block only needs enough live
    // links to measure the joins between them, and a spacing pathology thins the chain as a side
    // effect. A floor set near the healthy count would abort here on exactly the cases the
    // continuity measurement below exists to catch.
    assert.ok(chain.length >= 5, `only ${chain.length} trail pools were alive after 6s of swimming — too short a chain to measure any join at all`)
    let worst = 0, worstAt = -1
    for (let k = 1; k < chain.length; k++) {
      const a = chain[k - 1], b = chain[k]
      // Ratio, not px: the pools scale with the weapon's level and Split Seam, and a px threshold
      // would pass or fail for reasons that have nothing to do with continuity.
      const ratio = Math.hypot(a.x - b.x, a.y - b.y) / Math.max(1e-6, a.r + b.r)
      if (ratio > worst) { worst = ratio; worstAt = k }
    }
    assert.ok(worst < 0.85, `the trail comes apart: link ${worstAt} of ${chain.length} sits ${(worst * 100).toFixed(0)}% of the two pools' radii apart, so there is clear water between them and the oil reads as puddles`)
    const grown = chain.filter((b) => b.r >= b.maxR * 0.9).length
    assert.ok(grown >= chain.length - 1, `${chain.length - grown} of ${chain.length} live trail pools are still growing; a chain laid faster than it blooms is a dotted line whatever the spacing is`)
    console.log(`PASS run PY.l2 (the trail is continuous): ${chain.length} live pools, worst link ${(worst * 100).toFixed(0)}% of the pair's radii apart, ${grown} of them at full size`)
  }

  // -- PY.l3: the build sheet does not print a cadence the weapon no longer has. -----------------
  // buildReadout exists so the pause screen never reports a weapon's PAPER numbers, and Trailing
  // Slick makes bilge the first weapon in the game with no interval at all — it lays by distance
  // travelled. `levels[].rate` is still in the table (the thrown cast needs it), so the row is
  // emitted from data that the modded fire site never reads: a real number, quietly fictional.
  //   Both arms, because "no `every` row" is also what an empty readout looks like.
  {
    const sheet = (mods) => {
      const run = mk(20260826)
      run.weapons = [{ id: 'bilge', level: 3 }]
      run.weaponMods.bilge = mods
      run.weaponModPicks.bilge = mods
      const w = buildReadout(run).weapons.find((x) => x.id === 'bilge')
      assert.ok(w, 'precondition: bilge must appear in its own build sheet')
      return w.stats.map((st) => st.key)
    }
    const thrown = sheet({})
    const poured = sheet({ slickTrail: 1 })
    assert.ok(thrown.includes('every'), `a thrown Bilge fires on a timer and must still report it; got [${thrown.join(', ')}]`)
    assert.ok(!poured.includes('every'), `under Trailing Slick the oil lays by distance, so the sheet must not quote an interval; got [${poured.join(', ')}]`)
    assert.ok(poured.length > 0, 'the guard must drop ONE row, not the whole sheet')
    console.log(`PASS run PY.l3 (no fictional cadence): a thrown Bilge reports [${thrown.join(', ')}], a poured one [${poured.join(', ')}]`)
  }

  // -- PY.v: a bait is a FIXED AMOUNT OF FOOD. ---------------------------------------------------
  // Owner ruling, 2026-08-23: chum should be "an amount of food that disappears if too many fishes
  // have come and eat it". Three effects, and each fails on its own with a different piece deleted:
  //   nobody comes  -> the bait lives its whole `dur`         (control: the food is not decaying)
  //   3 fish on a 5 -> 3 servings gone, the bait still there  (control: ONE serving per fish)
  //   5 fish on a 5 -> stripped, and gone long before `dur`   (control: zero food ends it)
  // The middle one is the one a naive radius test passes anyway: with no per-fish memory a single
  // body sitting in the cloud drains the whole bucket in five frames.
  {
    const feed = (nFish) => {
      const run = mk(20260824)
      run.weapons = [{ id: 'chum', level: 1 }]
      const fish = []
      for (let k = 0; k < nFish; k++) {
        fish.push(put(run, { x: run.player.x + 4000, y: run.player.y + k * 7, hp: 1e12, speed: 0, flags: ['skittish'] }))
      }
      let bait = null, born = 0, food0 = 0, left = 0, died = Infinity
      for (let i = 0; i < Math.round(9 / dt); i++) {
        only(run, fish)
        // Park every fish INSIDE the bait once one exists. They cannot swim (speed 0), so where
        // they are is the whole experiment and nothing else moves them.
        if (bait && died === Infinity) {
          fish.forEach((e, k) => { e.x = bait.x + Math.cos(k * 1.3) * 9; e.y = bait.y + Math.sin(k * 1.3) * 9 })
        }
        stepSim(run, { x: 0, y: 0 }, dt)
        if (!bait) {
          bait = run.lures.find((lu) => lu.bait) ?? null
          if (bait) { born = i; food0 = bait.food; left = bait.food }
        } else if (died === Infinity) {
          // Read the object, not the array: a stripped bait is spliced out on the same step its
          // last serving goes, so an array-gated read reports the count from the frame BEFORE and
          // the whole arm measures zero servings taken.
          left = bait.food
          if (!run.lures.includes(bait)) died = (i - born) * dt
        }
      }
      return { food0, taken: food0 - left, died }
    }
    const alone = feed(0)
    const some = feed(3)
    const swarm = feed(5)
    assert.strictEqual(alone.food0, WEAPONS.chum.levels[0].food, `the fixture must read the shipped L1 serving count, got ${alone.food0}`)
    assert.strictEqual(alone.taken, 0, 'a bait nobody reaches must not lose food on its own')
    assert.ok(alone.died > WEAPONS.chum.levels[0].dur * 0.9, `a bait nobody found must last its duration; it went at ${alone.died.toFixed(2)}s of ${WEAPONS.chum.levels[0].dur}s`)
    assert.strictEqual(some.taken, 3, `three fish must take three servings, not ${some.taken} — one per fish per bait`)
    assert.ok(some.died > WEAPONS.chum.levels[0].dur * 0.9, `three fish cannot strip a ${some.food0}-serving bait; it died at ${some.died.toFixed(2)}s`)
    assert.strictEqual(swarm.taken, swarm.food0, `five fish must strip a ${swarm.food0}-serving bait, got ${swarm.taken}`)
    assert.ok(swarm.died < WEAPONS.chum.levels[0].dur * 0.5, `a stripped bait must go the moment the food does, not wait out its ${WEAPONS.chum.levels[0].dur}s; it lasted ${swarm.died.toFixed(2)}s`)
    console.log(`PASS run PY.v (a bait is a fixed amount of food): ${alone.food0} servings — untouched it lasts ${alone.died.toFixed(1)}s, 3 fish take 3 and it survives, 5 fish strip it in ${swarm.died.toFixed(2)}s`)
  }

  // -- PY.x: reaching the bait PARKS the fish. ---------------------------------------------------
  // Owner ruling, 2026-08-23: a fish that reaches the bait pins head-down for roughly 1.5s while it
  // takes a bite. That hold is the whole trap — chum on its own only gathers, and a gathered shoal
  // is still a shoal moving at 103-223 px/s.
  //   Measured as PATH LENGTH over three windows on the SAME fish, because a pinned body and a
  // body swimming in a circle have the same net displacement and only one of them is held.
  {
    const swim = ({ gap = 900, puff = false, chase = false }) => {
      const run = mk(20260827)
      run.weapons = []
      const p = run.player
      // Bait far from the player, so the panic override is not what is being measured. aggro is
      // wide enough that the fish is baited from where it starts.
      const bait = { x: p.x + gap, y: p.y, t: 0, dur: 9999, aggro: 500, burstR: 0, burstDmg: 0, bait: true, food: 40, food0: 40, shape: 0, rot: 0 }
      run.lures = [bait]
      const e = put(run, { x: bait.x - 150, y: bait.y, hp: 1e12, speed: 120, flags: ['skittish'] })
      // The window opens when the fish ARRIVES at the bait, not when feedT is set — an arm in which
      // the hold never starts (the puffed one) must still be measured over the same window, or
      // "never pinned" and "never got there" are the same zero.
      let atBait = -1, before = 0, during = 0, after = 0
      let lx = e.x, ly = e.y
      for (let i = 0; i < Math.round(9 / dt); i++) {
        only(run, [e])
        if (puff) e.puffT = 9        // held inflated for the whole run: puffing must outrank eating
        if (chase) { p.x = e.x - 40; p.y = e.y }   // the shark right on top of it
        stepSim(run, { x: 0, y: 0 }, dt)
        const moved = Math.hypot(e.x - lx, e.y - ly)
        lx = e.x; ly = e.y
        if (atBait < 0) {
          before += moved
          if (Math.hypot(e.x - bait.x, e.y - bait.y) <= CHUM_FEED_R) atBait = i
        } else if ((i - atBait) * dt < 1.0) during += moved
        else if ((i - atBait) * dt < 1.0 + CHUM_FEED_HOLD) { /* the tail of the hold, unmeasured */ }
        else if ((i - atBait) * dt < 1.6 + CHUM_FEED_HOLD) after += moved
      }
      return { atBait, before, during, after }
    }
    const held = swim({})
    assert.ok(held.atBait >= 0 && held.before > 60,
      `precondition: the fish must swim to the bait; it covered ${held.before.toFixed(0)}px and arrived at frame ${held.atBait}`)
    assert.ok(held.during < 2, `a feeding fish must be PINNED; it swam ${held.during.toFixed(1)}px in the second after its bite`)
    assert.ok(held.after > 8, `the hold must LAPSE; the fish still had not moved (${held.after.toFixed(1)}px) well past CHUM_FEED_HOLD`)
    // The two things that break it early. Both are rulings, and each fails on its own.
    const bolted = swim({ chase: true })
    assert.ok(bolted.during > 20, `CHUM_PANIC_R must break the hold: with the shark on top of it the fish only moved ${bolted.during.toFixed(1)}px`)
    const puffed = swim({ puff: true })
    assert.ok(puffed.during > 5, `a fish mid-puff must not stop to eat — puffing outranks a mouthful; it moved ${puffed.during.toFixed(1)}px`)
    console.log(`PASS run PY.x (a bite parks the fish): ${held.during.toFixed(1)}px swum in the second after the bite against ${held.after.toFixed(1)}px once it lapses, ` +
      `${bolted.during.toFixed(0)}px with the shark on top of it and ${puffed.during.toFixed(0)}px mid-puff`)
  }

  // -- PY.y: oil STAINS, permanently, from both oils, and the stain is capped. -------------------
  // Owner ruling, 2026-08-23: "a fish going through mazout should be 'stained' visually, and be
  // slowed forever a bit, even when they get out of the mazout."
  //   PATH LENGTH again, measured AFTER the body is clear of the oil — "slowed while standing in a
  // cloud" is bloomSlowT and already shipped, so a measurement taken inside the zone cannot tell
  // the new mechanic from the old one. Four arms, and the ink one is the control that the stain is
  // OIL and not "any cloud": the squid's cloud carries slow: 0 and must leave the shoal untouched.
  {
    const soak = (kind, secs) => {
      const run = mk(20260828)
      run.weapons = []
      const p = run.player
      const ox = p.x + 4000, oy = p.y   // far from the player: this is about the oil, not about fear
      // ⚠ `t` PAST THE GROW RAMP, and `dur` short enough that it IS past. stepBlooms rewrites bl.r
      // from bl.t every frame against dur x BLOOM_GROW_FRAC, so a hand-built cloud with a huge dur
      // spends the whole fixture at a fraction of its maxR — which reads as "the stain does not
      // work", or worse passes anyway because the subject happens to sit on the exact centre.
      // dur 200 / t 100 clears the ramp (70s) on frame one and still outlives the 63s soak.
      if (kind === 'bilge' || kind === 'inkjet') {
        run.blooms.push({ x: ox, y: oy, r: 200, maxR: 200, t: 100, dur: 200, dmgPerTick: 0, tick: 0,
          look: kind, slow: kind === 'inkjet' ? 0 : 1, shape: 0, rot: 0 })
      }
      // ⚠ AND streamSlicks CULLS run.slicks BY DISTANCE FROM THE PLAYER every step, so a fixture
      // spill 4000px away is gone on frame one. Re-seeded each frame, and the array is cleared in
      // every arm so an ambient spill materialising near the player can never reach the arm.
      const slick = { x: ox, y: oy, r: 200, shape: 0, rot: 0, _cell: 'fixture' }
      const e = put(run, { x: ox, y: oy, hp: 1e12, speed: 120, flags: ['skittish'] })
      // Soak: pinned in the middle of the zone so the dose is the same in every arm.
      for (let i = 0; i < Math.round(secs / dt); i++) {
        only(run, [e])
        run.slicks.length = 0
        if (kind === 'slick') run.slicks.push(slick)
        e.x = ox; e.y = oy
        stepSim(run, { x: 0, y: 0 }, dt)
      }
      const oiled = e.oiled || 0
      // Now CLEAR of every zone, and measure how far it can swim in 3s.
      run.blooms.length = 0
      run.slicks.length = 0
      e.bloomSlowT = 0
      let path = 0, lx = e.x, ly = e.y
      for (let i = 0; i < Math.round(3 / dt); i++) {
        only(run, [e])
        run.slicks.length = 0
        stepSim(run, { x: 0, y: 0 }, dt)
        path += Math.hypot(e.x - lx, e.y - ly)
        lx = e.x; ly = e.y
      }
      return { oiled, path }
    }
    const clean = soak('none', 1)
    const oiled = soak('bilge', 1)
    const leak = soak('slick', 1)
    const inked = soak('inkjet', 1)
    const drenched = soak('bilge', 60)
    assert.ok(clean.oiled === 0 && clean.path > 20, `precondition: an unoiled fish must be clean and swimming, got oiled ${clean.oiled} over ${clean.path.toFixed(1)}px`)
    assert.ok(oiled.oiled > 0.1, `a second in the player's own oil must stain; got ${oiled.oiled.toFixed(3)}`)
    assert.ok(oiled.path < clean.path * 0.95, `the stain must SURVIVE the fish leaving the oil: ${oiled.path.toFixed(1)}px against a clean fish's ${clean.path.toFixed(1)}px over the same 3s clear of every zone`)
    assert.ok(leak.oiled > 0.1, `the chapter's OWN spill must stain too, not only the player's bilge; got ${leak.oiled.toFixed(3)}`)
    assert.strictEqual(inked.oiled, 0, `the squid's ink is not oil and must never stain; got ${inked.oiled}`)
    assert.ok(Math.abs(inked.path - clean.path) < 1, `an inked fish must swim exactly as far as a clean one; ${inked.path.toFixed(1)}px against ${clean.path.toFixed(1)}px`)
    // THE CAP IS THE SAFETY. A minute parked in oil — far past any real crossing — must land on the
    // ceiling exactly, and the speed loss must be that ceiling and no more.
    assert.strictEqual(drenched.oiled, OIL_STAIN_MAX, `a minute in oil must saturate at OIL_STAIN_MAX, not climb past it; got ${drenched.oiled}`)
    const ratio = drenched.path / clean.path
    assert.ok(Math.abs(ratio - (1 - OIL_STAIN_MAX)) < 0.03,
      `a saturated fish must move at exactly (1 - OIL_STAIN_MAX) of a clean one; measured x${ratio.toFixed(3)} against ${(1 - OIL_STAIN_MAX).toFixed(3)}`)
    console.log(`PASS run PY.y (oil stains forever, capped): 1s of bilge -> ${oiled.oiled.toFixed(3)} and ${oiled.path.toFixed(0)}px against a clean ${clean.path.toFixed(0)}px, ` +
      `the leak's own spill stains ${leak.oiled.toFixed(3)}, ink stains 0, and 60s saturates at ${drenched.oiled} for x${ratio.toFixed(3)} speed`)
  }

  // -- PY.z: panic beats avoidance. --------------------------------------------------------------
  // Owner ruling, 2026-08-23, taken having been shown the conflict. Prey refuse to enter oil — that
  // avoidance IS bilge's wall and PY.j guards it — but a fish being run down at close range does not
  // look where it is going, so driving the shoal through your own slick is the play.
  //   ONE fish, because cohesion is the confound: a shoal spreads as it flees, its outer bodies stay
  // far enough from the shark to keep watching, and the herd term then drags the blind ones back out
  // around the rim. That is correct behaviour and it makes a 12-body fixture measure the herd rather
  // than the clause. A single body needs no PREY_COHESION_MIN_N neighbours and steers on its own.
  //   The two arms are the SAME chase with the shark's distance the only thing changed: identical
  // fish, identical oil, identical 200px between them. HOW DEEP IT GETS, not whether it entered —
  // a threshold on "entered" turns a smooth ramp into a coin flip at the edge, and the depth is
  // what the clause actually moves. The fixture is deterministic (the drift heading is a function of
  // shoal id and run time, not of the RNG), so this is one run per arm and not a sample.
  {
    const R = 120
    const drive = (behind) => {
      const run = mk(20260829)
      run.weapons = []
      const p = run.player
      const fx = p.x + behind
      const oil = { x: fx + 200, y: p.y, r: R, maxR: R, t: 100, dur: 200, dmgPerTick: 0, tick: 0, look: 'bilge', slow: 1, shape: 0, rot: 0 }
      const e = put(run, { x: fx, y: p.y, hp: 1e12, speed: 150, flags: ['skittish'] })
      let best = Infinity
      for (let i = 0; i < Math.round(3.5 / dt); i++) {
        only(run, [e])
        run.blooms.length = 0
        run.blooms.push(oil)
        stepSim(run, { x: 0, y: 0 }, dt)
        best = Math.min(best, Math.hypot(e.x - oil.x, e.y - oil.y))
      }
      return best   // closest it ever got to the oil's CENTRE
    }
    const blind = drive(50)     // the shark on top of it: well inside PREY_PANIC_BLIND_R
    const watching = drive(300) // still fleeing (under PREY_SIGHT_R) but with room to look
    assert.ok(blind < R * 0.6, `driven at close range the fish must go WELL into the oil; it only reached ${blind.toFixed(0)}px from the centre of a ${R}px slick`)
    assert.ok(watching > R * 0.8, `at range the wall must still turn it — that avoidance is what the card IS; it got ${watching.toFixed(0)}px in`)
    assert.ok(watching - blind > R * 0.3, `the two arms must be a real difference, not noise: ${blind.toFixed(0)}px vs ${watching.toFixed(0)}px into a ${R}px slick`)
    console.log(`PASS run PY.z (panic beats avoidance): chased from 50px the fish drives ${(R - blind).toFixed(0)}px into a ${R}px slick, chased from 300px only ${(R - watching).toFixed(0)}px`)
  }

  // -- PY.w: the orca comes for FOOD, not for a bait being there. --------------------------------
  // Owner ruling, 2026-08-23: "the orca should be attracted to big appats or groups of fishes, the
  // more there is the more it attacks." orcaRush multiplies the visit countdown, so the effect to
  // measure is how much of that countdown a fixed window actually spends — a full bait must burn
  // it faster than a stripped one, and a stripped one must still beat no bait at all.
  //   Reading the multiplier back would pass with the whole weighting reverted to a flat count,
  // which is exactly the shape of the code this replaced.
  {
    const drain = (food) => {
      const run = mk(20260825)
      run.weapons = []
      const bait = { x: run.player.x + 600, y: run.player.y, t: 0, dur: 999, aggro: 150, burstR: 0, burstDmg: 0, bait: true, food, food0: 8, shape: 0, rot: 0 }
      run.lures = food > 0 ? [bait] : []
      const a0 = run._orcaAcc
      for (let i = 0; i < Math.round(2 / dt); i++) {
        only(run, [])            // an empty field, so run._feedN contributes nothing
        stepSim(run, { x: 0, y: 0 }, dt)
      }
      return a0 - run._orcaAcc
    }
    const full = drain(ORCA_BAIT_FULL_FOOD)
    const stripped = drain(1)
    const none = drain(0)
    assert.ok(none > 1.9 && none < 2.1, `precondition: with nothing in the water the countdown must tick in real time, got ${none.toFixed(3)}s over 2s`)
    assert.ok(full > stripped * 1.35, `a full bait must pull the orca in HARDER than a stripped one; ${full.toFixed(3)}s vs ${stripped.toFixed(3)}s of countdown over the same 2s`)
    assert.ok(stripped > none * 1.02, `a bait with food still in it must pull at all; ${stripped.toFixed(3)}s against ${none.toFixed(3)}s with no bait`)
    console.log(`PASS run PY.w (the orca comes for food): 2s of real time spends ${full.toFixed(2)}s of the countdown on a full bait, ${stripped.toFixed(2)}s on a stripped one and ${none.toFixed(2)}s on none`)
  }

  // -- PY.m: the bite CRITS SOMETIMES, not always. -----------------------------------------------
  // Owner, 2026-08-18: "bite has 100% crit chance i dont know why, so every bite mod is useless."
  // GNASH_BASE_CRIT is added straight onto p.critChance by applyDamage, so it is a FRACTION in the
  // same units as CLAW_BASE_CRIT (0.10 == "+10 points"). Shipped as `10` it made the comparison
  // `Math.random() < 10` unconditionally true.
  //
  // WHY THE RATE AND NOT THE CONSTANT: reading the constant back asserts nothing — it is one unit
  // conversion away from the thing that matters, which is exactly the step that was wrong. And the
  // damage column could not see this either, because the chapter's prey die in one bite: the extra
  // 40% went almost entirely into OVERKILL (census waste 53% -> 41% at L1 when it was fixed), so
  // effective dps moved 23 -> 21 and kills/min 77.9 -> 74.6. A bug worth 1.4x damage was invisible
  // in every number except the one the player actually sees, the crit flash on every single hit.
  {
    const run = mk(20260822)
    run.weapons = [{ id: 'gnash', level: 1 }]
    const p = run.player
    const x0 = p.x, y0 = p.y
    const bodies = [0, 1, 2, 3, 4].map((k) => put(run, { x: x0 + 40 + k * 12, y: y0 + (k - 2) * 8, hp: 1e12, speed: 0 }))
    let hits = 0, crits = 0
    for (let i = 0; i < Math.round(90 / dt); i++) {
      only(run, bodies)
      bodies.forEach((e, k) => { e.x = x0 + 40 + k * 12; e.y = y0 + (k - 2) * 8 })
      run.events.length = 0
      stepSim(run, { x: 0, y: 0 }, dt)
      for (const ev of run.events) {
        if (ev.type !== 'hit' || ev.dot) continue
        hits++
        if (ev.crit) crits++
      }
    }
    assert.ok(hits > 300, `need a real sample to talk about a rate; only ${hits} bites landed`)
    const rate = crits / hits
    // PLAYER.baseCritChance 0.05 + GNASH_BASE_CRIT 0.10 = 0.15. At n>300, 1 sigma is under 2pts, so
    // this band is >3 sigma either side of the truth and still excludes BOTH pathologies: the
    // shipped 1.00, and the 0.05 left behind if the bonus is dropped altogether.
    assert.ok(rate > 0.09 && rate < 0.24,
      `gnash must crit about 15% of the time (0.05 base + 0.10 of its own); measured ${(rate * 100).toFixed(1)}% over ${hits} bites — 100% means GNASH_BASE_CRIT is in percent where applyDamage wants a fraction`)
    console.log(`PASS run PY.m (the bite crits sometimes): ${(rate * 100).toFixed(1)}% of ${hits} bites crit, against the 15% its two sources add up to`)
  }

  // -- PY.n: BLOODRUSH builds on landed bites and drops when you stop. --------------------------
  // Owner: "biting an enemy increases speed by 5% for 2s". Three properties, each with the control
  // that makes it non-vacuous:
  //   it is a SPEED change   — vs the same 3s with the mod unbought
  //   it is paid for LANDING — vs biting open water, which must pay nothing at all
  //   it LAPSES              — vs holding the buff forever once earned
  // The middle one is the whole card: without it this is "+25% move speed" with a duration painted
  // on, because gnash fires 1.5-2.4 times a second and would refresh the window forever.
  {
    const travel = (mods, withBody) => {
      const run = mk(20260823)
      run.weapons = [{ id: 'gnash', level: 1 }]
      run.weaponMods.gnash = mods
      const p = run.player
      const x0 = p.x
      // Held at a fixed OFFSET from the player rather than at a fixed point, so a swimming player
      // keeps landing bites for the whole window. Pinned in world space instead, the player outruns
      // it in a fifth of a second and the rush has lapsed long before the loop ends — which is what
      // the first cut of this fixture did, and it read exactly like the card not working.
      // 50px is inside the 118px jaw; 900px is well outside it, so those bites land on water.
      const gap = withBody ? 50 : 900
      const e = put(run, { x: p.x + gap, y: p.y, hp: 1e12, speed: 0 })
      let peak = 0
      for (let i = 0; i < Math.round(5 / dt); i++) {
        only(run, [e])
        e.x = run.player.x + gap; e.y = run.player.y
        stepSim(run, { x: 1, y: 0 }, dt)
        peak = Math.max(peak, run._rushN ?? 0)
      }
      return { moved: run.player.x - x0, stacks: peak }
    }
    const off = travel({}, true)
    const on = travel({ bloodrush: 0.05 }, true)
    const miss = travel({ bloodrush: 0.05 }, false)
    assert.ok(on.stacks > 1, `biting must STACK the rush; it reached ${on.stacks}`)
    assert.ok(on.moved > off.moved * 1.05,
      `bloodrush must actually move the player faster: ${on.moved.toFixed(0)}px against ${off.moved.toFixed(0)}px unbought`)
    assert.strictEqual(miss.stacks, 0, 'biting open water must bank no rush at all, or the card is a flat speed bonus')
    assert.ok(Math.abs(miss.moved - off.moved) < 1,
      `a build that never lands a bite must move exactly like one without the card; ${miss.moved.toFixed(0)} vs ${off.moved.toFixed(0)}`)

    // ...and it LAPSES. Same run, bites stopped by emptying the field.
    const run = mk(20260823)
    run.weapons = [{ id: 'gnash', level: 1 }]
    run.weaponMods.gnash = { bloodrush: 0.05 }
    const p = run.player
    const e = put(run, { x: p.x + 50, y: p.y, hp: 1e12, speed: 0 })
    for (let i = 0; i < Math.round(3 / dt); i++) { only(run, [e]); e.x = p.x + 50; e.y = p.y; stepSim(run, { x: 0, y: 0 }, dt) }
    const peak = run._rushN ?? 0
    for (let i = 0; i < Math.round(3 / dt); i++) { only(run, []); stepSim(run, { x: 0, y: 0 }, dt) }
    assert.ok(peak > 0 && (run._rushN ?? 0) === 0 && (run._rushT ?? 0) === 0,
      `the rush must lapse once the bites stop: peaked at ${peak}, left ${run._rushN} stacks / ${(run._rushT ?? 0).toFixed(2)}s`)
    console.log(`PASS run PY.n (bloodrush): landing bites stacks to ${on.stacks} and carries the player ${on.moved.toFixed(0)}px against ${off.moved.toFixed(0)}px unbought, biting water banks nothing, and ${peak} stacks lapse to 0 when the crowd is gone`)
  }

  // -- PY.o: GORGE pays on an ELITE and only on an elite. ---------------------------------------
  // Owner: "eating elites replenish full hunger bar". It sits at the shared kill site in dealDamage
  // rather than inside biteGnash, so it pays however the elite actually died — the oil, the leak
  // and a Lunge all count as eating it. This fixture kills with the bite because that is the path
  // it can drive deterministically; the placement is what the two mutations in the table cover.
  //
  // THE KILL MUST BE REAL. Setting e._dead by hand never runs the site under test at all, which is
  // how the first cut of this block "passed" nothing — the body has to die THROUGH dealDamage.
  {
    const kill = (mods, elite) => {
      const run = mk(20260824)
      run.weapons = [{ id: 'gnash', level: 5 }]
      run.weaponMods.gnash = mods
      const e = put(run, { x: run.player.x + 40, y: run.player.y, hp: 40, speed: 0 })
      e.maxHP = 40
      e.elite = elite
      run.charge = 1
      const before = run.charge
      for (let i = 0; i < Math.round(8 / dt) && !e._dead; i++) {
        only(run, [e])
        e.x = run.player.x + 40; e.y = run.player.y
        stepSim(run, { x: 0, y: 0 }, dt)
      }
      assert.ok(e._dead, 'the fixture never killed the body, so it cannot say anything about a kill reward')
      return { before, after: run.charge, max: run.chargeMax }
    }
    const plain = kill({ gorge: 1 }, false)
    const elite = kill({ gorge: 1 }, true)
    const unbought = kill({}, true)
    assert.ok(elite.after >= elite.max - 1e-6,
      `an elite kill must fill Bloodlust outright; it went ${elite.before} -> ${elite.after.toFixed(1)} of ${elite.max}`)
    assert.ok(plain.after < plain.max * 0.9,
      `a NON-elite kill must not fill the bar, or the card is "kills fill Bloodlust"; it reached ${plain.after.toFixed(1)} of ${plain.max}`)
    assert.ok(unbought.after < unbought.max * 0.9,
      `without the card an elite kill must pay only the ordinary killBase; it reached ${unbought.after.toFixed(1)} of ${unbought.max}`)
    console.log(`PASS run PY.o (gorge): an elite kill takes Bloodlust to ${elite.after.toFixed(0)}/${elite.max}, where the same kill unbought reaches ${unbought.after.toFixed(1)} and a non-elite ${plain.after.toFixed(1)}`)
  }

  // -- PY.p: the OIL RING lays a ring, and it is a PEN rather than a puddle. ---------------------
  // Owner: "the mazout could have fun mods like mazout rings that traps groups of enemies".
  // Asserted as GEOMETRY, not as a count: RING_N pools that all landed on the same spot would pass
  // any count assert and be one ordinary pool wearing a bigger number (the documented per-cast
  // trap). So this measures the ring's radius spread AND that the middle is left open — the open
  // middle is the entire mechanic, since it is where the shoal ends up.
  {
    const cast = (mods) => {
      const run = mk(20260825)
      run.weapons = [{ id: 'bilge', level: 1 }]
      run.weaponMods.bilge = mods
      const p = run.player
      const x0 = p.x, y0 = p.y
      const e = put(run, { x: x0 + 300, y: y0, hp: 1e12, speed: 0, flags: ['skittish'] })
      let pools = []
      for (let i = 0; i < Math.round(10 / dt) && !pools.length; i++) {
        only(run, [e])
        e.x = x0 + 300; e.y = y0
        stepSim(run, { x: 0, y: 0 }, dt)
        pools = run.blooms.filter((b) => b.look === 'bilge')
      }
      assert.ok(pools.length, 'bilge never planted — the fixture proves nothing')
      return { pools, cx: e.x, cy: e.y }
    }
    const plain = cast({})
    const ring = cast({ oilRing: 1 })
    assert.strictEqual(plain.pools.length, 1, 'an ordinary cast is one pool')
    assert.strictEqual(ring.pools.length, RING_N, `the ring lays RING_N pools; got ${ring.pools.length}`)
    const radii = ring.pools.map((b) => Math.hypot(b.x - ring.cx, b.y - ring.cy))
    const spread = Math.max(...radii) - Math.min(...radii)
    assert.ok(Math.min(...radii) > 1, 'no ring pool may sit ON the target — the middle is the pen')
    assert.ok(spread < 1, `every ring pool must sit at the same radius, or it is a smear not a ring; spread ${spread.toFixed(1)}px`)
    // DISTINCT POSITIONS, not just a count.
    const spots = new Set(ring.pools.map((b) => `${Math.round(b.x)},${Math.round(b.y)}`))
    assert.strictEqual(spots.size, RING_N, `the ring's pools must be in ${RING_N} different places; they occupy ${spots.size}`)
    // The pen must be CLOSED at cast: neighbouring pools have to overlap, or prey walk straight out
    // of the gap and the card does nothing it says it does.
    const step = 2 * Math.PI / RING_N
    const gap = 2 * radii[0] * Math.sin(step / 2)          // centre-to-centre along the circle
    assert.ok(gap <= ring.pools[0].maxR * 2, `the ring must close: neighbours are ${gap.toFixed(0)}px apart but only ${(ring.pools[0].maxR * 2).toFixed(0)}px wide`)
    // AND IT ACTUALLY PENS. Everything above is geometry, and geometry is not the claim — the card
    // says it traps. Prey are dropped in the middle with the player far outside PREY_SIGHT_R, so
    // they are milling rather than fleeing, and the control is the identical drift with no ring at
    // all. Note WHY the centre holds them rather than squeezing them out: the six avoidance vectors
    // cancel exactly at the middle and point inward everywhere off it, so the pen is a stable well.
    {
      const penned = (withRing) => {
        const run = mk(20260826)
        run.weapons = []
        const p = run.player
        // INSIDE PREY_SIGHT_R (340), deliberately. A school with no reason to leave stays put with
        // or without a pen, which is a control that proves nothing — the first cut of this fixture
        // parked the player 900px away and read 6 of 6 on BOTH sides. The real case is the one the
        // card is for: you close in, they bolt, and the oil is what decides whether they get out.
        const cx = p.x + 300, cy = p.y
        const school = [0, 1, 2, 3, 4, 5].map((k) => {
          const a = (k / 6) * Math.PI * 2
          return put(run, { x: cx + Math.cos(a) * 18, y: cy + Math.sin(a) * 18, hp: 1e12, speed: 60, flags: ['skittish'] })
        })
        if (withRing) {
          const lv = WEAPONS.bilge.levels[0]
          const pr = lv.maxR * RING_POOL_MUL
          const rr = pr * RING_R_MUL
          for (let j = 0; j < RING_N; j++) {
            const t = (j / RING_N) * Math.PI * 2
            run.blooms.push({
              x: cx + Math.cos(t) * rr, y: cy + Math.sin(t) * rr,
              t: 0, r: pr, maxR: pr, dur: 99, dmgPerTick: 0, tick: 0, look: 'bilge', shape: 0, rot: 0, slow: 1,
            })
          }
        }
        const keep = run.blooms.slice()
        for (let i = 0; i < Math.round(5 / dt); i++) {
          run.enemies.length = 0; run.enemies.push(...school)
          run.blooms.length = 0; run.blooms.push(...keep)   // hold the pen open for the whole test
          for (const b of run.blooms) { b.t = 0; b.r = b.maxR }
          stepSim(run, { x: 0, y: 0 }, dt)
        }
        const rr = lvMaxR * RING_POOL_MUL * RING_R_MUL
        // THE SPREAD, NOT A HEAD COUNT. "How many are still inside" is vacuous in any fixture where
        // the control school does not leave either — it read 6 of 6 on both sides. What the pen
        // actually does is hold the school TIGHTER than open water would, and that is a number that
        // moves: it also catches the pathology the six-pool ring had, where the walls squeezed fish
        // OUT through the gaps and the spread grew instead of shrinking.
        return { spread: Math.max(...school.map((e) => Math.hypot(e.x - cx, e.y - cy))), rr }
      }
      const lvMaxR = WEAPONS.bilge.levels[0].maxR
      const pen = penned(true)
      const open = penned(false)
      assert.ok(pen.spread < open.spread,
        `the ring must hold the school TIGHTER than open water: spread ${pen.spread.toFixed(0)}px against ${open.spread.toFixed(0)}px unpenned`)
      assert.ok(pen.spread < pen.rr,
        `and it must hold them INSIDE the wall: the furthest fish reached ${pen.spread.toFixed(0)}px of a ${pen.rr.toFixed(0)}px ring`)
      console.log(`PASS run PY.p2 (the pen holds): a school bolting from the player spreads to ${pen.spread.toFixed(0)}px inside a ${pen.rr.toFixed(0)}px ring, against ${open.spread.toFixed(0)}px with no ring at all`)
    }
    console.log(`PASS run PY.p (the oil ring): ${RING_N} pools at ${radii[0].toFixed(0)}px around the target, ${gap.toFixed(0)}px apart against ${(ring.pools[0].maxR * 2).toFixed(0)}px of width, and nothing in the middle`)
  }

  // -- PY.q: the bite prefers FOOD that is in reach, but still eats a moray you closed on. -------
  // Owner: "i don't really see how the player is supposed to deal with murenes ... it's just that
  // they slow you down and clutter the screen", then "prefer food, like the dash does".
  // aimAngle takes the nearest body full stop. Every fish here flees while the moray neither flees
  // nor hurries, so the moray parks in your face and the chapter's ONLY damage source follows it:
  // measured at 32.8% of frames before this, 20.9% after.
  //
  // BOTH HALVES, because the owner also asked for morays to be a prize worth hunting and the two
  // answers fight unless the preference is gated on REACH. A fish in the jaw wins; a moray alone in
  // the jaw is still bitten, which is what happens when you break off the chase for one.
  {
    const aimedAt = (fishGap) => {
      const run = mk(20260827)
      run.weapons = [{ id: 'gnash', level: 1 }]
      const p = run.player
      const lv = WEAPONS.gnash.levels[0]
      // The tank is nearer than the fish in BOTH cases — that is the situation being tested.
      const tank = put(run, { x: p.x + 40, y: p.y, hp: 1e12, speed: 0 })
      tank.type = 'tank'
      const fish = put(run, { x: p.x, y: p.y + fishGap, hp: 1e12, speed: 0, flags: ['skittish'] })
      let hitTank = 0, hitFish = 0
      for (let i = 0; i < Math.round(6 / dt); i++) {
        only(run, [tank, fish])
        tank.x = p.x + 40; tank.y = p.y
        fish.x = p.x; fish.y = p.y + fishGap
        const t0 = tank.hp, f0 = fish.hp
        stepSim(run, { x: 0, y: 0 }, dt)
        if (tank.hp < t0) hitTank++
        if (fish.hp < f0) hitFish++
      }
      return { hitTank, hitFish, range: lv.range }
    }
    const inJaw = aimedAt(70)                    // fish inside the 118px jaw
    const outOfJaw = aimedAt(400)                // fish well beyond it: only the moray is in reach
    assert.ok(inJaw.hitFish > 0 && inJaw.hitTank === 0,
      `with food in the jaw the bite must go to the FOOD, even though the tank is nearer: fish ${inJaw.hitFish} hits, tank ${inJaw.hitTank}`)
    assert.ok(outOfJaw.hitTank > 0,
      `with no food in reach the bite must still eat the moray you closed on, or it stops being huntable: tank ${outOfJaw.hitTank} hits`)
    console.log(`PASS run PY.q (the bite prefers food in reach): a fish 70px away takes ${inJaw.hitFish} hits while a nearer tank takes ${inJaw.hitTank}; move the fish to 400px and the tank takes ${outOfJaw.hitTank}`)
  }

  // -- PY.r: a moray cannot hurt you, and eating one pays. ---------------------------------------
  // Two halves of "a prize worth hunting", each against a control.
  //   HARMLESS: the roster says dmgMul 0 and hurtPlayer floors every hit at Math.max(1, ...), so
  //   before contactHarmless honoured it the moray did 204 HP across three 300s runs — against the
  //   leak's 234, in the chapter whose premise is that the leak is the only thing that can kill you.
  //   WORTH EATING: tankRefill, on top of killBase, is the reason to break off a chase.
  {
    const res = CHAPTERS.wreck.resource
    // (a) harmless, against the same body given real contact damage
    const chip = (dmg) => {
      const run = mk(20260828)
      run.weapons = []
      const p = run.player
      p.maxHP = p.hp = 500
      const e = put(run, { x: p.x, y: p.y, hp: 1e12, speed: 0 })
      e.type = 'tank'
      e.dmg = dmg
      for (let i = 0; i < Math.round(5 / dt); i++) {
        only(run, [e])
        e.x = p.x; e.y = p.y
        stepSim(run, { x: 0, y: 0 }, dt)
      }
      return 500 - run.player.hp
    }
    const harmless = chip(0)
    const armed = chip(7)
    assert.strictEqual(harmless, 0, `a body declaring zero contact damage must cost nothing; it took ${harmless} HP`)
    assert.ok(armed > 0, `the control must actually hurt, or this block is vacuous; it took ${armed} HP`)

    // (b) eating one pays tankRefill on top of killBase, where an ordinary fish pays killBase alone
    const eat = (asTank) => {
      const run = mk(20260829)
      run.weapons = [{ id: 'gnash', level: 5 }]
      const e = put(run, { x: run.player.x + 40, y: run.player.y, hp: 40, speed: 0 })
      e.maxHP = 40
      if (asTank) e.type = 'tank'
      run.charge = 0
      for (let i = 0; i < Math.round(8 / dt) && !e._dead; i++) {
        only(run, [e])
        e.x = run.player.x + 40; e.y = run.player.y
        stepSim(run, { x: 0, y: 0 }, dt)
      }
      assert.ok(e._dead, 'the fixture never killed the body')
      return run.charge
    }
    const moray = eat(true)
    const fish = eat(false)
    assert.ok(moray >= fish + res.tankRefill * 0.9,
      `eating a moray must pay tankRefill (${res.tankRefill}) on top of the ordinary kill: ${moray.toFixed(1)} against a fish's ${fish.toFixed(1)}`)
    console.log(`PASS run PY.r (the moray is a harmless prize): 5s sat on one costs 0 HP where an armed body costs ${armed}, and eating it banks ${moray.toFixed(0)} Bloodlust against a fish's ${fish.toFixed(0)}`)
  }

  // -- PY.s: THE SQUID'S INK. Two halves, because either one alone passes with the card dead. -----
  // (a) the squid LAYS one, only when the player is close, and only once per INK_COOLDOWN;
  // (b) standing in one COSTS YOU SPEED.
  // Split deliberately: a cloud that never appears and a cloud that does nothing are different
  // bugs with the same symptom on screen, and each half has its own control.
  {
    // (a) THE TRIGGER. Same fish twice, once with the flag and once without — so this cannot pass
    // on some other thing in the chapter pushing a bloom.
    const lay = (flags, gap, secs) => {
      const run = mk(20260901)
      const p = run.player
      const e = put(run, { x: p.x + gap, y: p.y, hp: 1e6, speed: 0, flags })
      let clouds = 0
      for (let i = 0; i < Math.round(secs / dt); i++) {
        only(run, [e])
        e.x = p.x + gap; e.y = p.y      // pinned at the range under test, not left to flee out of it
        run.blooms.length = 0           // count EVENTS, not survivors: a cloud lives INK_DUR and
        stepSim(run, { x: 0, y: 0 }, dt) // would otherwise be recounted every frame
        clouds += run.blooms.filter((b) => b.look === 'inkjet').length
      }
      return clouds
    }
    const near = lay(['skittish', 'inkjet'], INK_TRIGGER_R * 0.5, 12)
    const far = lay(['skittish', 'inkjet'], INK_TRIGGER_R * 1.6, 12)
    const control = lay(['skittish'], INK_TRIGGER_R * 0.5, 12)
    assert.ok(near > 0, 'a squid with the player inside INK_TRIGGER_R must lay a cloud; it laid none')
    assert.strictEqual(control, 0, `the same fish without the flag must lay nothing; it laid ${control}`)
    assert.strictEqual(far, 0, `a squid ${(INK_TRIGGER_R * 1.6).toFixed(0)}px away must not ink — the trigger is a range, not an aura; it laid ${far}`)
    // ONE PER COOLDOWN, NOT ONE PER FRAME. Without the cooldown a single squid parked next to the
    // player lays 720 clouds in 12s, which is a wall rather than a defence, and nothing throws.
    const cap = Math.ceil(12 / INK_COOLDOWN) + 1
    assert.ok(near <= cap, `a squid must ink at most once per ${INK_COOLDOWN}s: ${near} clouds in 12s, cap ${cap}`)

    // (b) THE SLOW, measured exactly as PY.e measures the leak's: distance covered under full
    // input, against the identical run with no cloud in it. r is large so the player is still
    // inside at the end of the window — a 110px cloud is crossed in half a second at 220px/s and
    // the measurement would be mostly clean water.
    const soak = (withInk) => {
      const run = mk(20260902)
      stepSim(run, { x: 0, y: 0 }, dt)
      // `dur` SHORT and `t` past the growth window. stepBlooms recomputes r from
      // t / (dur * BLOOM_GROW_FRAC) every frame, so a long dur pins a hand-pushed cloud at a few px
      // forever and the measurement comes back as clean water — the first cut of this read x0.98.
      if (withInk) run.blooms.push({ x: run.player.x, y: run.player.y, t: 3, r: 900, maxR: 900, dur: 6, dmgPerTick: 0, tick: 0, look: 'inkjet', slow: 0 })
      const hp0 = run.player.hp
      const x0 = run.player.x
      for (let i = 0; i < Math.round(1.5 / dt); i++) {
        run.enemies.length = 0
        stepSim(run, { x: 1, y: 0 }, dt)
      }
      return { moved: run.player.x - x0, lost: hp0 - run.player.hp }
    }
    const inked = soak(true)
    const clean = soak(false)
    const ratio = inked.moved / clean.moved
    assert.ok(ratio < INK_SLOW_MUL + 0.06 && ratio > INK_SLOW_MUL - 0.06,
      `ink must slow the player to about x${INK_SLOW_MUL}; measured x${ratio.toFixed(2)}`)
    // IT IS NOT A DAMAGE ZONE. The card's whole shape is "a tax on your movement" — an ink that
    // also chipped you would be a second leak, in the chapter whose premise is one leak.
    assert.strictEqual(inked.lost, 0, `ink must deal no damage at all; it took ${inked.lost} HP`)
    console.log(`PASS run PY.s (the squid inks): ${near} cloud(s) in 12s at ${(INK_TRIGGER_R * 0.5).toFixed(0)}px against 0 at ${(INK_TRIGGER_R * 1.6).toFixed(0)}px and 0 without the flag, and standing in one costs x${ratio.toFixed(2)} speed and 0 HP`)
  }

  // -- PY.t: THE PUFFERFISH refuses ONE bite, not a window of them. ------------------------------
  // The moray's `guard` failed in this chapter for two reasons (see CHAPTERS.wreck.roster), and
  // both are asserted here rather than remembered: it refused so little it read as a miss, and a
  // body that neither fled nor hurried soaked a third of the jaw's aim. So: the first swing must
  // bounce, the fish must still DIE, and the number of refusals must be bounded by the CYCLE and
  // not by how fast the player swings — that last one is what separates a beat from a shield.
  {
    const chew = (flags, secs) => {
      const run = mk(20260903)
      run.weapons = [{ id: 'gnash', level: 5 }]
      const p = run.player
      const e = put(run, { x: p.x + 40, y: p.y, hp: 1e6, speed: 90, flags })
      e.maxHP = 1e6
      let blocks = 0, hits = 0, firstWasBlocked = null
      let moved = 0
      for (let i = 0; i < Math.round(secs / dt); i++) {
        only(run, [e])
        const before = { x: e.x, y: e.y }
        e.x = p.x + 40; e.y = p.y      // held in the jaw, so the swing always has a target
        const hp0 = e.hp
        stepSim(run, { x: 0, y: 0 }, dt)
        // DRAINED EVERY STEP, as main.js does. stepSim does not clear run.events — the frame loop
        // does — so a fixture that only reads it recounts the whole backlog every frame. The first
        // cut of this block reported 1292 refusals in 8s for a mechanic that fired 7 times.
        for (const ev of run.events.splice(0)) {
          if (ev.type === 'guardblock') { blocks++; if (firstWasBlocked === null) firstWasBlocked = true }
        }
        if (e.hp < hp0) { hits++; if (firstWasBlocked === null) firstWasBlocked = false }
        moved += Math.hypot(e.x - before.x, e.y - before.y)
        void moved
      }
      return { blocks, hits, firstWasBlocked }
    }
    const puffer = chew(['skittish', 'puffup'], 8)
    const plain = chew(['skittish'], 8)
    assert.strictEqual(plain.blocks, 0, `the same fish without the flag must refuse nothing; it refused ${plain.blocks}`)
    assert.strictEqual(puffer.firstWasBlocked, true,
      'the first swing that reaches an inflated puffer must be REFUSED — that is the whole card')
    assert.ok(puffer.hits > 0, `a puffer must still be eaten; it took ${puffer.hits} landed hits in 8s`)
    // ONE REFUSAL PER CYCLE. gnash at Lv5 swings several times a second, so a refusal window that
    // ran on a TIMER instead of ending on the first hit would block a multiple of this. The bound
    // is the number of times it can possibly re-inflate in the window, plus one for the first.
    const cycles = Math.ceil(8 / PUFFER_COOL_T) + 1
    assert.ok(puffer.blocks <= cycles,
      `a puffer must refuse at most one bite per ${PUFFER_COOL_T}s cycle, not one per swing: ${puffer.blocks} refusals in 8s against a cap of ${cycles} (it took ${puffer.hits} landed hits over the same window)`)

    // AND IT DRIFTS. The refusal is only half the beat; the other half is that the ball cannot run,
    // which is what makes the window a punish rather than an escape. Measured against the same fish
    // with the flag off, from the same distance, with nothing pinning it.
    const drift = (flags) => {
      const run = mk(20260904)
      run.weapons = []
      const p = run.player
      const e = put(run, { x: p.x + PUFFER_TRIGGER_R * 0.6, y: p.y, hp: 1e6, speed: 90, flags })
      const d0 = Math.hypot(e.x - p.x, e.y - p.y)
      for (let i = 0; i < Math.round(1.2 / dt); i++) {
        only(run, [e])
        stepSim(run, { x: 0, y: 0 }, dt)
      }
      return Math.hypot(e.x - run.player.x, e.y - run.player.y) - d0
    }
    const puffed = drift(['skittish', 'puffup'])
    const loose = drift(['skittish'])
    assert.ok(loose > 40, `the control must actually escape, or this proves nothing: it gained ${loose.toFixed(0)}px`)
    assert.ok(puffed < loose * (PUFFER_DRIFT_MUL + 0.25),
      `an inflated puffer must barely swim: it gained ${puffed.toFixed(0)}px where the same fish unflagged gained ${loose.toFixed(0)}px`)
    console.log(`PASS run PY.t (the puffer refuses one bite): first swing bounced, ${puffer.blocks} refusals in 8s under a ${cycles}-cycle cap against ${puffer.hits} landed hits, 0 without the flag, and it drifts ${puffed.toFixed(0)}px where a loose fish gains ${loose.toFixed(0)}px`)
  }

  // -- PY.u: THE SARDINE BALL. `tight` is a BRAKE, and that is what is asserted. -----------------
  // Measured, the blend barely changes the rms spread — stepEnemySeparation floors how tightly 16
  // bodies can pack whatever they steer — so an assertion on tightness would be testing the
  // separation pass. What the flag actually buys is that the ball SPENDS its speed on staying
  // together: at TIGHT_COHESION_BLEND a sardine converts 40% of its 183px/s into escape where an
  // untight one converts 69%. Same bodies, same speed, same ids, same start block; only the flag
  // moves, so the difference cannot be anything else.
  //   APPROACHED FROM OUTSIDE, not sat on. A predator standing IN a shoal correctly explodes it,
  // and every arm of a rig built that way measures the explosion rather than the flag.
  {
    const ball = (flags) => {
      const run = mk(20260905)
      run.weapons = []
      const p = run.player
      const es = []
      // ⚠ 160px AND 0.8s, AND BOTH NUMBERS ARE THE FIXTURE. Cohesion is THREAT-GATED, so a shoal
      // that leaves PREY_SIGHT_R (340) stops steering — and an UNTIGHT school is fast enough to do
      // that inside the window. The first cut ran 220px for 1.5s and the loose arm crossed the
      // radius at t=1.0, capping its travel at 95px against the tight arm's 90: a 2.4x separation
      // collapsed to 5%, and the block read as "the flag does nothing" when the flag was fine.
      for (let k = 0; k < 16; k++) {
        const e = put(run, { x: p.x + 160 + (k % 4) * 26, y: p.y - 39 + Math.floor(k / 4) * 26, hp: 1e6, speed: 165 * 0.82, flags })
        // Ids PINNED into ONE bucket, for the reason PY.c gives: two consecutive ids straddle a
        // bucket boundary once every PREY_SHOAL_SIZE, which is a mystery red on an unrelated edit.
        e.id = 4 * PREY_SHOAL_SIZE + k
        es.push(e)
      }
      const cen = () => [es.reduce((s, e) => s + e.x, 0) / 16, es.reduce((s, e) => s + e.y, 0) / 16]
      const [cx0, cy0] = cen()
      for (let i = 0; i < Math.round(0.8 / dt); i++) {
        only(run, es)
        stepSim(run, { x: 0, y: 0 }, dt)
      }
      const [cx, cy] = cen()
      const rms = Math.sqrt(es.reduce((s, e) => s + (e.x - cx) ** 2 + (e.y - cy) ** 2, 0) / 16)
      return { travel: Math.hypot(cx - cx0, cy - cy0), rms, together: es.filter((e) => Math.hypot(e.x - cx, e.y - cy) < BALL_R * 1.6).length }
    }
    const tight = ball(['skittish', 'tight'])
    const loose = ball(['skittish'])
    assert.ok(loose.travel > 60, `the control must actually run, or this block is vacuous: it covered ${loose.travel.toFixed(0)}px in 0.8s`)
    assert.ok(tight.travel < loose.travel * 0.9,
      `a tight ball must spend its speed on cohesion rather than on escape: it covered ${tight.travel.toFixed(0)}px against a loose school's ${loose.travel.toFixed(0)}px over the same 0.8s at the same speed`)
    assert.strictEqual(tight.together, 16,
      `"they never split" is the design: only ${tight.together} of 16 sardine ended within ${(BALL_R * 1.6).toFixed(0)}px of their own centroid`)
    console.log(`PASS run PY.u (the sardine ball): 16 bodies covered ${tight.travel.toFixed(0)}px in 0.8s against an untight school's ${loose.travel.toFixed(0)}px, all 16 still in one body at rms ${tight.rms.toFixed(0)}px`)
  }

  console.log('PASS run PY (The Wreck: prey): the roster runs from you in schools and cannot touch you, the bite prefers food in reach and crits only sometimes, the oil lands on the crowd and can be thrown as a pen, the moray is a harmless prize, the squid inks and the puffer bounces one bite and the sardine balls, and the leak is the only thing in the chapter that can kill you')
}
run(runPrey)

// ---- Run OR: THE ORCA (v7.x, The Wreck) -------------------------------------------------------
// Three owner rulings, all of which fail SILENTLY if their wiring rots, and none of which a
// grep-for-an-identifier could see:
//   1. "orca was supposed to start with a shadow passing underneath you several times" — the
//      opening must be HARMLESS and must not escalate. A `shadow` state that fell through to
//      `rising` would still contain the word `shadow` everywhere.
//   2. "the orca should be attracted to big appats or groups of fishes, the more there is the more
//      it attacks" — the countdown must run FASTER in a packed field, and must stop accelerating
//      at the cap. Delete the Math.min and nothing throws; the chapter just never gets its quiet
//      back.
//   3. "The shoal — you're collateral." The commit aims at the densest knot of prey and eats it,
//      UNCREDITED. Route those deaths through dealDamage by accident and every assertion about
//      where the orca went still passes while the player is quietly paid for its meal.
// Every block below therefore measures an EFFECT with a control arm, never the presence of a name.
function runOrca() {
  const dt = 0.05   // the ticker's own clamp; _orcaAcc is dt-exact, so the long walks use it
  const wkMeta = () => { const m = makeMeta(); m.dev = true; ensureChapterMeta(m); return m }
  // Immortal, weaponless, and with the chapter's two ambient killers held off: the tide moves every
  // body in the fixture (the reason run PY turns it off too) and a streamed slick underfoot would
  // bill the player for HP this scenario attributes to the orca.
  const mk = (seed = 20260823) => {
    Math.random = mulberry32(seed)
    const run = createRun(wkMeta(), { chapter: 'wreck', difficulty: 1 })
    run.mods.tideSurgeMul = 0
    run.weapons = []
    run.player.maxHP = run.player.hp = 1e9
    run.enemies.length = 0
    return run
  }
  // Held every frame: the spawner runs at spawnMul 2.2 here, so anything not pinned by identity is
  // measuring the crowd instead of the fixture (run PY's `only`, plus the slick clear).
  const hold = (run, es) => {
    run.enemies.length = 0
    run.enemies.push(...es)
    run.slicks.length = 0
  }
  const put = (run, o) => {
    const e = makeStatusEnemy(run, o)
    e.flags = o.flags ?? []
    return e
  }
  // A tight knot of prey pinned around a point. Tight enough that stepEnemySeparation gives every
  // member a `_shoalN` over BALL_TIGHT_N, which is what makes them count for _feedN — the density
  // term orcaRush reads to decide how soon the animal comes.
  const ball = (run, n, cx, cy, spread = 40) => {
    const es = []
    for (let i = 0; i < n; i++) {
      const a = (i / n) * Math.PI * 2
      es.push(put(run, {
        x: cx + Math.cos(a) * spread, y: cy + Math.sin(a) * spread,
        hp: 1e6, speed: 0, flags: ['skittish'],
      }))
    }
    return es
  }

  // -- OR.a: the opening is THREE HARMLESS PASSES, and then the danger. -------------------------
  // Walks a real run to just past the first real visit and records the state machine's whole
  // itinerary. The control is built in: the same walk must ALSO see the `rising` it escalates to,
  // or a broken orca that simply never spawns would satisfy "no damage before 100s" perfectly.
  {
    const run = mk()
    const seen = []          // one entry per visit: { state, t, dmg }
    let cur = null
    let hp0 = run.player.hp
    for (let i = 0; i * dt <= ORCA_FIRST_PASS + 6; i++) {
      hold(run, [])
      // Bloodlust held full for this block ALONE. 100s of empty water starves the bar, and the
      // starve DoT then bills the player HP that this block would otherwise read as the shadow
      // hurting them — it did, at 10 and 12 HP on passes 2 and 3, before this line existed.
      run.charge = run.chargeMax
      const before = run.orca ? run.orca.state : null
      stepSim(run, { x: 0, y: 0 }, dt)
      const now = run.orca ? run.orca.state : null
      if (now && !before) { cur = { state: now, t: i * dt, dmg: 0 }; hp0 = run.player.hp; seen.push(cur) }
      if (cur && now) cur.state = now                       // an escalation is a state CHANGE, and this catches it
      if (cur && !now) { cur.dmg = hp0 - run.player.hp; cur = null }
    }
    const shadows = seen.filter((v) => v.state === 'shadow')
    assert.strictEqual(shadows.length, ORCA_SHADOW_PASSES,
      `the opening must be exactly ORCA_SHADOW_PASSES (${ORCA_SHADOW_PASSES}) shadow passes; the walk saw ` +
      `${shadows.length} of them in ${seen.length} visits: [${seen.map((v) => v.state + '@' + v.t.toFixed(0) + 's').join(', ')}]`)
    // A shadow pass that ESCALATED would be recorded under its final state, not under 'shadow' —
    // which is exactly the failure a `state === 'shadow'` grep cannot see.
    assert.ok(seen.slice(0, ORCA_SHADOW_PASSES).every((v) => v.state === 'shadow'),
      `the first ${ORCA_SHADOW_PASSES} visits must each END as a shadow pass, not escalate into one: ` +
      `[${seen.map((v) => v.state).join(', ')}]`)
    assert.ok(shadows.every((v) => v.dmg === 0),
      `an opening pass is foreshadowing and must cost EXACTLY zero HP; they cost [${shadows.map((v) => v.dmg).join(', ')}]`)
    assert.ok(seen.length > ORCA_SHADOW_PASSES,
      'the walk never reached the first REAL visit, so "harmless before 100s" is passing on an orca that simply never arrives')
    const first = shadows[0].t, second = shadows[1].t
    assert.ok(Math.abs(first - ORCA_SHADOW_FIRST) < 1,
      `the first shadow must land at ORCA_SHADOW_FIRST (${ORCA_SHADOW_FIRST}s); it landed at ${first.toFixed(1)}s`)
    assert.ok(Math.abs((second - first) - (ORCA_SHADOW_GAP + ORCA_SHADOW_DUR)) < 1,
      `shadows must be ORCA_SHADOW_GAP apart (measured pass-clear to pass-clear); the gap was ${(second - first).toFixed(1)}s`)
    // The whole ladder must still put the DANGER where the chapter's design says it is. This is the
    // guard on ORCA_SHADOW_LAST_GAP being derived rather than typed: retune any shadow knob and a
    // literal would silently drag the first real visit off ORCA_FIRST_PASS.
    const real = seen[ORCA_SHADOW_PASSES].t
    assert.ok(Math.abs(real - ORCA_FIRST_PASS) < 1.5,
      `the first REAL visit must still arrive at ORCA_FIRST_PASS (${ORCA_FIRST_PASS}s); it arrived at ${real.toFixed(1)}s`)
    console.log(`PASS run OR.a (the opening): ${shadows.length} shadow passes at [${shadows.map((v) => v.t.toFixed(0) + 's').join(', ')}] costing ` +
      `${shadows.reduce((a, v) => a + v.dmg, 0)} HP between them, and the first real visit still at ${real.toFixed(0)}s`)
  }

  // -- OR.b: A CROWD BRINGS IT IN, and the cap stops it living here. ----------------------------
  // Three arms of the SAME fixture measuring when the first pass spawns. Empty water is the control
  // and pins real time; a half-full field must arrive proportionally sooner; a field that is full
  // AND baited must NOT arrive sooner than the cap allows — which is the assertion that dies when
  // the Math.min goes.
  {
    const arrival = (n, baits) => {
      const run = mk()
      const p = run.player
      const es = n ? ball(run, n, p.x + 60, p.y, 30) : []
      // ⚠ `food` IS LOAD-BEARING HERE, and 800px away from the crowd is too. Since v7.x a bait
      // pulls by how much food is left in it, so a bait built without the field counts as EMPTY and
      // the cap arm below quietly measures a full field alone — an assertion that reads green while
      // the Math.min it exists for is unreachable. Parked away from the ball because the ball would
      // otherwise eat it (CHUM_FEED_R) inside two frames and the arm would drift back to zero.
      for (let k = 0; k < baits; k++) run.lures.push({ x: p.x - 800, y: p.y + k * 60, t: 0, dur: 999, aggro: 200, burstR: 0, burstDmg: 0, bait: true, food: ORCA_BAIT_FULL_FOOD, food0: ORCA_BAIT_FULL_FOOD })
      for (let i = 1; i * dt <= ORCA_SHADOW_FIRST + 4; i++) {
        hold(run, es)
        for (const e of es) { e.fearT = 0 }   // the pass itself fears them; keep the density it measured
        stepSim(run, { x: 0, y: 0 }, dt)
        if (run.orca) return i * dt
      }
      return Infinity
    }
    const empty = arrival(0, 0)
    const half = arrival(Math.ceil(FEED_FULL_N / 2), 0)
    const gorged = arrival(FEED_FULL_N + 4, 2)
    assert.ok(Math.abs(empty - ORCA_SHADOW_FIRST) < 1,
      `empty water must tick in REAL time: the first pass came at ${empty.toFixed(1)}s against ORCA_SHADOW_FIRST ${ORCA_SHADOW_FIRST}s`)
    assert.ok(half < empty - 5,
      `a half-full field must bring it in EARLIER: ${half.toFixed(1)}s against ${empty.toFixed(1)}s in empty water — the density term is not being read`)
    // The cap, stated as arithmetic rather than as a literal so a retune of either knob carries.
    const capped = ORCA_SHADOW_FIRST / ORCA_RUSH_MAX
    const uncapped = ORCA_SHADOW_FIRST / (1 + ORCA_DENSITY_RUSH * (1 + 2 * ORCA_BAIT_PULL))
    assert.ok(Math.abs(gorged - capped) < 1.2,
      `a full field plus two baits must saturate at ORCA_RUSH_MAX: wanted ~${capped.toFixed(1)}s, got ${gorged.toFixed(1)}s ` +
      `(uncapped this rush would land at ${uncapped.toFixed(1)}s, which is what a deleted Math.min looks like)`)
    assert.ok(capped - uncapped > 1.5,
      'the cap arm proves nothing unless the uncapped rush would be measurably faster — raise the bait/density in this fixture')
    console.log(`PASS run OR.b (density brings it in): first pass at ${empty.toFixed(1)}s in empty water, ${half.toFixed(1)}s over a half-full field, ` +
      `${gorged.toFixed(1)}s gorged-and-baited — capped at ${capped.toFixed(1)}s, where uncapped it would be ${uncapped.toFixed(1)}s`)
  }

  // -- OR.c: it commits through the CENTRE OF ITS COIL, eats what is there, pays NOTHING. --------
  // Owner ruling 2026-08-23: "the orca attack should always be on the center of the spiral." Two
  // arms off a hand-built `circling` orca (stepOrca writes this exact shape), and they are each
  // other's control: park the coil's centre on a knot 400px off the player and the KNOT dies while
  // the player is untouched; park it on the player and the player is hit. Neither arm alone can
  // separate "aimed at the centre" from "aimed at the shoal" or from "aimed at the player" — the
  // pair can, because those three answers are 400px apart in the first arm and identical in the
  // second.
  {
    const commit = (off, withBall) => {
      const run = mk()
      const p = run.player
      // The centre LAGS the player by `off`, which is what the loose track in the circling state
      // leaves behind once the player has been swimming, and the knot sits ON it — where
      // ORCA_CIRCLE_DUR of tightening coil has been herding it. The line runs from the orca's ring
      // position through that centre, so it clears the player by `off`, well outside
      // ORCA_HIT_R + the player's radius (100).
      // ⚠ ONE LINE, NOT ORCA_COMMITS OF THEM. `passes: 1` is what makes this block measurable: a
      // full visit commits twice, and the second line re-rises, re-spirals and re-aims at wherever
      // the centre has drifted to by then — so `away.dmg === 0` below would be reading that second
      // aim, not this one.
      const cx = p.x, cy = p.y - off
      const es = withBall ? ball(run, 14, cx, cy, 45) : []
      run.orca = {
        // Two frames of circling, not 0.2s: the centre lerps toward the player while it runs, and
        // over 0.2s it would drag the aim point ~10% of `off` off the knot the arm is about to
        // measure. Short enough that the fixture's geometry is the one that commits.
        state: 'circling', t: dt * 1.5,
        cx, cy, r: ORCA_RING_MIN_R, ang: 0,
        x: cx + ORCA_RING_MIN_R, y: cy, dirX: 0, dirY: 0, hit: false, alpha: 1, passes: 1,
      }
      // Bloodlust parked at HALF, deliberately. At full, killBase (5/kill x 14 fish) would clamp
      // against chargeMax and a credited meal would be invisible; at zero the starve DoT would bill
      // the player HP this block attributes to the strike. Half is the only value that sees both.
      run.charge = run.chargeMax / 2
      const hp0 = p.hp, kills0 = run.kills, gems0 = run.gems.length, charge0 = run.charge
      let feeds = 0, killEvents = 0, splashes = []
      let brokeAt = null                                    // where the body was when it broke orbit
      // The centre AS IT STOOD AT THE LOCK — read after the step that flipped the state, not from
      // the fixture's literal: the centre lerps toward the player every circling frame, so the
      // fixture's own (cx, cy) is tens of px stale by the time the line is locked, and comparing
      // the splash against a stale point measures the lerp instead of the aim.
      let locked = null
      for (let i = 0; i < Math.round(12 / dt) && run.orca; i++) {
        hold(run, es)
        if (run.orca.state === 'circling') brokeAt = { x: run.orca.x, y: run.orca.y }
        stepSim(run, { x: 0, y: 0 }, dt)
        if (!locked && run.orca && run.orca.state === 'committing') locked = { x: run.orca.cx, y: run.orca.cy }
        feeds += run.events.filter((ev) => ev.type === 'orcaFeed').length
        killEvents += run.events.filter((ev) => ev.type === 'kill').length
        splashes = splashes.concat(run.events.filter((ev) => ev.type === 'orcaSplash'))
        run.events.length = 0
      }
      return {
        feeds, killEvents, splashes, brokeAt, locked, cx, cy,
        eaten: es.filter((e) => e._dead).length, of: es.length,
        dmg: hp0 - run.player.hp,
        kills: run.kills - kills0, gems: run.gems.length - gems0, charge: run.charge - charge0,
      }
    }
    const away = commit(400, true)
    const onYou = commit(0, false)
    assert.ok(away.eaten >= 4,
      `the commit must go THROUGH the coil's centre and eat what the coil herded there: ${away.eaten} of ${away.of} died. ` +
      `Aimed at the player instead, the line clears the knot by 400px and eats nobody`)
    assert.strictEqual(away.feeds, away.eaten,
      `every eaten fish must emit exactly one orcaFeed (render's only tell for it): ${away.feeds} events for ${away.eaten} deaths`)
    // The credit half. These are three separate ledgers and dealDamage pays all three — routing the
    // bite through it would leave every other assertion here green.
    assert.strictEqual(away.kills, 0, `the orca's meal must not count as player kills; run.kills moved by ${away.kills}`)
    assert.strictEqual(away.gems, 0, `the orca's meal must drop no XP; ${away.gems} gems appeared`)
    assert.strictEqual(away.killEvents, 0, `the orca's meal must emit no 'kill' events — that is the beat the player hears and sees for their OWN kill; ${away.killEvents} fired`)
    assert.ok(away.charge < 0,
      `the bar must still be FALLING through the orca's meal; it moved by ${away.charge >= 0 ? '+' : ''}${away.charge.toFixed(1)}. ` +
      `killBase is ${CHAPTERS.wreck.resource.killBase}/kill, so a credited sweep of ${away.eaten} fish would push it up instead`)
    assert.strictEqual(away.dmg, 0,
      `the player had outrun the coil by 400px and must take nothing: they lost ${away.dmg}`)
    assert.ok(onYou.dmg > 0,
      `with the centre ON the player the same line must hit them — it dealt ${onYou.dmg}, so this block cannot tell ` +
      `"aimed at the centre" from "always misses"`)
    // THE SPLASH, and it is the owner's sentence stated as geometry. Once per commit, and AT the
    // centre of the coil — which in the first arm is 400px from the player and ORCA_RING_MIN_R from
    // the body that threw it, so neither an aim at the player nor an emit at o.x/o.y satisfies it.
    for (const [nm, r] of [['knot 400px off', away], ['centre on the player', onYou]]) {
      assert.strictEqual(r.splashes.length, 1,
        `exactly one orcaSplash per commit line (${nm}); ${r.splashes.length} fired`)
      const s = r.splashes[0]
      // The centre must not have wandered off the fixture in the frames it circled, or "on the
      // centre" would be satisfied by a centre that has drifted onto the player anyway.
      const drift = Math.hypot(r.locked.x - r.cx, r.locked.y - r.cy)
      assert.ok(drift < ORCA_BITE_R,
        `the coil's centre drifted ${drift.toFixed(0)}px off the knot before it locked (${nm}), so this arm no longer separates ` +
        `"aimed at the centre" from "aimed at the player" — shorten the circling frames in the fixture`)
      const offBy = Math.hypot(s.x - r.locked.x, s.y - r.locked.y)
      assert.ok(offBy < 5,
        `the splash must land on the CENTRE OF THE SPIRAL (${nm}); it landed ${offBy.toFixed(0)}px off it`)
      const fromBody = Math.hypot(s.x - r.brokeAt.x, s.y - r.brokeAt.y)
      assert.ok(fromBody > ORCA_RING_MIN_R * 0.8,
        `the splash must be the point it was AIMED at, not where the body broke orbit (${nm}); ` +
        `those were only ${fromBody.toFixed(0)}px apart, against a ring radius of ${ORCA_RING_MIN_R}`)
    }
    console.log(`PASS run OR.c (it strikes the centre of its coil): a centre parked 400px off the player took ${away.eaten}/${away.of} fish ` +
      `for ${away.feeds} orcaFeed events, paying 0 kills / 0 gems / 0 Bloodlust and costing the player 0 HP, and threw ONE splash ` +
      `${Math.hypot(away.splashes[0].x - away.locked.x, away.splashes[0].y - away.locked.y).toFixed(1)}px from that centre and ` +
      `${Math.hypot(away.splashes[0].x - away.brokeAt.x, away.splashes[0].y - away.brokeAt.y).toFixed(0)}px from the body — ` +
      `where a centre on the player hits them for ${(onYou.dmg / 1e9).toFixed(2)}x max HP (bite swath ${ORCA_BITE_R}px)`)
  }

  // -- OR.d: the pass SCATTERS what it goes under, and still costs nothing. ----------------------
  // The subject is a NON-skittish body on purpose. Prey already flee the player, so a fleeing fish
  // proves nothing about the shadow; a body that normally CLOSES is the only one whose reversal is
  // attributable. fearT is the shipped contract field render.js already tints and poses off.
  {
    const measure = (withPass) => {
      const run = mk()
      const p = run.player
      const e = put(run, { x: p.x + 150, y: p.y, hp: 1e6, speed: 90, flags: [] })
      if (withPass) {
        run.orca = {
          state: 'shadow', t: ORCA_SHADOW_DUR,
          cx: p.x, cy: p.y, r: ORCA_RING_MIN_R, ang: 0,
          x: p.x - (run.viewRadius + ORCA_SHADOW_MARGIN), y: p.y, dirX: 1, dirY: 0, hit: false, alpha: 0,
        }
      }
      const d0 = Math.hypot(e.x - p.x, e.y - p.y)
      const hp0 = p.hp
      let peakFear = 0
      for (let i = 0; i < Math.round(ORCA_SHADOW_DUR / dt); i++) {
        hold(run, [e])
        stepSim(run, { x: 0, y: 0 }, dt)
        peakFear = Math.max(peakFear, e.fearT || 0)
      }
      return { moved: Math.hypot(e.x - run.player.x, e.y - run.player.y) - d0, peakFear, dmg: hp0 - run.player.hp, alive: !e._dead }
    }
    const passed = measure(true)
    const control = measure(false)
    assert.ok(passed.peakFear > 0, 'the pass must publish into e.fearT — the field render.js already reads; nothing else gives it a tell')
    assert.ok(passed.moved > 30,
      `a body the shadow went under must break AWAY: it moved ${passed.moved.toFixed(0)}px, wanted > 30`)
    assert.ok(control.moved < -30,
      `the control must still CLOSE, or this block passes with the chase deleted globally (it moved ${control.moved.toFixed(0)}px)`)
    assert.strictEqual(control.peakFear, 0, 'the control must not be feared by anything else in the chapter, or the fear is not attributable to the pass')
    assert.strictEqual(passed.dmg, 0, `a pass must cost the player nothing; it cost ${passed.dmg}`)
    assert.ok(passed.alive, 'a pass must not eat anything — only the commit sweep bites')
    console.log(`PASS run OR.d (the pass scatters): a chasing body went +${passed.moved.toFixed(0)}px away under the shadow at fearT ${passed.peakFear.toFixed(2)}, ` +
      `against ${control.moved.toFixed(0)}px unshadowed, for 0 HP and 0 deaths`)
  }

  // -- OR.e: the commit is a BOW WAVE, and a visit is ORCA_COMMITS lines. ------------------------
  // Owner ruling 2026-08-23: "it should have a massive impact on the battlefield, like pushing
  // everything to each side", and "currently it just circles a bit around you, then goes away, easy
  // to avoid". Two separate mechanisms answer that and this block guards both, because either one
  // failing silently leaves the other looking like the whole fix.
  //   THE SUBJECTS ARE NON-PREY ON PURPOSE. orcaBite deletes `skittish` bodies inside ORCA_BITE_R,
  // so a prey fixture cannot tell "thrown aside" from "eaten and gone"; a flagless body is immune to
  // the bite outright, which makes every px of displacement attributable to the wake alone.
  {
    const wake = (withOrca) => {
      const run = mk()
      const p = run.player
      // Strung along the line the orca will travel (+x through the player) at five perpendicular
      // offsets: two well inside ORCA_WAKE_R on OPPOSITE sides, one near its edge, one outside it,
      // and one sitting ON the line. Separated in x so stepEnemySeparation never has two of them in
      // reach of each other — otherwise the control arm drifts and the measurement is separation.
      //   ⚠ THE ONE ON THE LINE IS THE ONLY ARM THAT CAN SEE A RADIAL SHOVE, and that is a measured
      // correction, not a hunch. For a body offset PERPENDICULAR to a straight pass the two are
      // near-identical (176px vs 179px measured) — the orca's approach and its recession contribute
      // equal and opposite along-line pushes that cancel, leaving the same lateral throw. A body at
      // y=+10 separates them outright: a perpendicular wake gives it the full force for the whole
      // chord, a radial one has almost no lateral component to give until the orca is on top of it.
      const at = [[100, 70], [340, -70], [580, 180], [820, -430], [1060, 10]]
      const es = at.map(([dx, dy]) => put(run, { x: p.x + dx, y: p.y + dy, hp: 1e12, speed: 0, flags: [] }))
      // ⚠ WORLD y, NOT PLAYER-RELATIVE. The wake shoves the player as well, so an origin on the
      // player subtracts that drift from the body on one side and adds it to the body on the other
      // — which read as +48/-200 for a shove that is really symmetric, i.e. a false asymmetry
      // reported as a broken sign. Nothing else moves the world here (the tide is off in mk()).
      const y0 = es.map((e) => e.y)
      const py0 = p.y
      if (withOrca) {
        // Dropped straight into 'committing' rather than walked to it: the subject is the sweep, and
        // `hit: true` latches the player contact OFF so this block reads displacement and not HP.
        run.orca = {
          state: 'committing', t: 1.7,
          cx: p.x, cy: p.y, r: ORCA_RING_MIN_R, ang: 0,
          x: p.x - 400, y: p.y, dirX: 1, dirY: 0, hit: true, alpha: 1, passes: 1,
        }
      }
      // Long enough for the sweep to clear the last body AND for e.kb to decay out, so what is
      // measured is where the wake actually LEFT them and not a velocity still in flight.
      for (let i = 0; i < Math.round(3.5 / dt); i++) {
        for (const e of es) e.speed = 0
        hold(run, es)
        stepSim(run, { x: 0, y: 0 }, dt)
      }
      return { dy: es.map((e, k) => e.y - y0[k]), player: run.player.y - py0 }
    }
    const hit = wake(true)
    const still = wake(false)
    assert.ok(still.dy.every((v) => Math.abs(v) < 5),
      `the control must not move: without an orca the four bodies drifted [${still.dy.map((v) => v.toFixed(0)).join(', ')}]px`)
    // SIGN FIRST. A radial shove — the obvious wrong implementation — would push the two inner
    // bodies apart too, so magnitude alone cannot tell a bow wave from a bubble. What only a
    // PERPENDICULAR shove gives is each body leaving on the side it was already on.
    assert.ok(hit.dy[0] > 120 && hit.dy[1] < -120,
      `bodies either side of the line must be thrown AWAY from it, each on its own side; ` +
      `+70px went ${hit.dy[0].toFixed(0)}px and -70px went ${hit.dy[1].toFixed(0)}px`)
    // ⚠ A RATIO, NOT `dy[2] < dy[0]`. The far body is inside the swath for a SHORTER CHORD
    // (2√(R²-d²): 143px at 180 out against 438px at 70), so it takes less impulse even with the
    // falloff term deleted — measured 150/300 = 0.50 flat against 46/176 = 0.26 shipped. The bare
    // inequality is satisfied by the geometry alone and cannot see the term at all.
    assert.ok(hit.dy[2] > 20 && hit.dy[2] < hit.dy[0] * 0.4,
      `the wake must fall off with distance: at 180px out a body moved ${hit.dy[2].toFixed(0)}px against ` +
      `${hit.dy[0].toFixed(0)}px at 70px out, a ratio of ${(hit.dy[2] / hit.dy[0]).toFixed(2)} — wanted under 0.40 ` +
      `(a flat force reads 0.50 here on chord length alone)`)
    assert.ok(hit.dy[4] > 200,
      `a body sitting ON the strike line takes the wake at full force and must be hurled clear; it moved ` +
      `${hit.dy[4].toFixed(0)}px. A RADIAL shove reads 125px here (measured) — it has almost no lateral component ` +
      `to give a body it is heading straight at, which is the whole reason this arm exists`)
    assert.ok(Math.abs(hit.dy[3]) < 5,
      `nothing beyond ORCA_WAKE_R (${ORCA_WAKE_R}px) may be touched; a body 430px off the line moved ${hit.dy[3].toFixed(0)}px`)
    assert.ok(Math.abs(hit.player) > 15,
      `the player rides the wake too — standing on the line they must be shoved clear; they moved ${hit.player.toFixed(0)}px`)

    // THE SECOND LINE. Counts orcaStrike over one whole visit, walked from 'rising' so every state
    // transition is the shipped one. A visit that ends at the first overshoot reads 1 here.
    const run = mk()
    const p = run.player
    const bearing = 0
    run.orca = {
      state: 'rising', t: ORCA_RISE_DUR,
      cx: p.x, cy: p.y, r: ORCA_RING_R, ang: bearing,
      x: p.x + ORCA_RING_R, y: p.y, dirX: 0, dirY: 0, hit: false, alpha: 0, passes: ORCA_COMMITS,
    }
    let strikes = 0, rises = 0
    for (let i = 0; i < Math.round(40 / dt) && run.orca; i++) {
      hold(run, [])
      run.charge = run.chargeMax      // OR.a's rule: 40s of empty water would otherwise starve-bill the player
      stepSim(run, { x: 0, y: 0 }, dt)
      strikes += run.events.filter((ev) => ev.type === 'orcaStrike').length
      rises += run.events.filter((ev) => ev.type === 'orcaRise').length
      run.events.length = 0
    }
    assert.strictEqual(strikes, ORCA_COMMITS,
      `one visit must commit ORCA_COMMITS (${ORCA_COMMITS}) times; it struck ${strikes} time(s)`)
    // The re-arm has to be a REAL telegraph, not a second line fired out of the leave. orcaRise is
    // the event the shadow and the sfx both hang off, so counting it proves the second pass was
    // announced — a `leaving` that jumped straight back to `committing` would read 0 here.
    assert.strictEqual(rises, ORCA_COMMITS - 1,
      `every line after the first must re-rise with its own telegraph; saw ${rises} orcaRise for ${strikes} strikes`)
    assert.strictEqual(run.orca, null, 'the visit must still END — after its last line the object clears, or the orca lives here forever')
    console.log(`PASS run OR.e (the bow wave): the sweep threw bodies ${hit.dy[0].toFixed(0)}px and ${hit.dy[1].toFixed(0)}px to OPPOSITE sides of its line, ` +
      `${hit.dy[4].toFixed(0)}px for one stood on it and ${hit.dy[2].toFixed(0)}px at the swath edge (ratio ${(hit.dy[2] / hit.dy[0]).toFixed(2)}), ` +
      `moved the player ${hit.player.toFixed(0)}px clear and left a body 430px out untouched, ` +
      `where a visit commits ${strikes} lines with ${rises} re-rise and then clears`)
  }

  // -- OR.f: the stalk is a SPIRAL, and it is a shadow until the strike. -----------------------
  // Owner ruling 2026-08-23: "the spiraling looks just like it's circling", and what is wanted
  // instead is "a moment of tension build-up, like in jaws or whatever, where the SHADOW IS
  // SPIRALING IN FROM UNDERNEATH, just before the impact/attack" — plus "you know something big is
  // coming". The first cut was already an Archimedean spiral by construction and still read as
  // laps, which is why this block asserts the three things that actually carry the read rather than
  // the existence of a closing radius.
  {
    const renderSrc = readFileSync(new URL('../src/render.js', import.meta.url), 'utf8')
    const run = mk()
    const p = run.player
    run.orca = {
      state: 'circling', t: ORCA_CIRCLE_DUR,
      cx: p.x, cy: p.y, r: ORCA_RING_R, ang: 0,
      x: p.x + ORCA_RING_R, y: p.y, dirX: 0, dirY: 0, hit: false, alpha: 1, passes: 1, trail: [],
    }
    // ⚠ 1/60, NOT THE FILE'S 0.05. The trail cap below only BINDS at a real frame rate — a 4s
    // stalk is 240 points at 60fps against a 220 cap, and just 80 at the ticker's 0.05 clamp, where
    // deleting the cap entirely changes nothing and the assertion guards air. Sampled per frame so
    // the RATE can be differenced: a single before/after pair cannot tell a ramp from a faster
    // constant.
    const fdt = 1 / 60
    let swept = 0, prevAng = run.orca.ang, firstRate = 0, lastRate = 0, i = 0
    const radii = []
    let peakTrail = 0
    while (run.orca && run.orca.state === 'circling' && i++ < Math.round(20 / fdt)) {
      hold(run, [])
      stepSim(run, { x: 0, y: 0 }, fdt)
      const o = run.orca
      if (!o || o.state !== 'circling') break
      const d = o.ang - prevAng
      prevAng = o.ang
      swept += d
      if (!firstRate) firstRate = d / fdt
      lastRate = d / fdt
      radii.push(o.r)
      peakTrail = Math.max(peakTrail, (o.trail || []).length / 2)
    }
    const laps = swept / (Math.PI * 2)
    // 1. TWO LAPS IS THE FLOOR FOR READING A COIL. The shipped-and-rejected cut managed 1.2, which
    // is a corner that drifts inward — you cannot see a spiral in a single turn.
    assert.ok(laps >= 1.9,
      `the stalk must be at least two full laps or there is no coil to see; it swept ${laps.toFixed(2)}`)
    // 2. THE RATE RAMPS. A constant rate cannot express "tightening AND quickening", which is the
    // whole Jaws beat — and a faster constant would satisfy the lap count above on its own.
    assert.ok(lastRate > firstRate * (1 + ORCA_SPIRAL_ACCEL * 0.6),
      `the coil must QUICKEN into the strike: it started at ${firstRate.toFixed(2)} rad/s and ended at ` +
      `${lastRate.toFixed(2)}, a ratio of ${(lastRate / firstRate).toFixed(2)} against ORCA_SPIRAL_ACCEL ${ORCA_SPIRAL_ACCEL}`)
    // 3. AND IT ACTUALLY CLOSES, monotonically, all the way to the ring's floor.
    assert.ok(radii.every((r, k) => k === 0 || r <= radii[k - 1] + 1e-9),
      'the radius must close monotonically; it widened somewhere in the stalk')
    assert.ok(Math.abs(radii[radii.length - 1] - ORCA_RING_MIN_R) < 12,
      `the coil must finish at ORCA_RING_MIN_R (${ORCA_RING_MIN_R}); it ended at ${radii[radii.length - 1].toFixed(0)}`)
    // ⚠ AND IT MUST HOLD WIDE BEFORE PLUNGING (ORCA_SPIRAL_EASE), so the LAST lap is the one that
    // collapses. Monotonicity is blind to this and so was the first cut of this very assertion: it
    // sat at 0.22, which a linear close clears at 0.50 without trying, and the eased curve that
    // shipped was on the WRONG SIDE of linear anyway. 0.60 brackets the two — eased reads 0.71,
    // linear reads 0.50 — and the mutation table has the linear close in it for that reason.
    const mid = radii[Math.floor(radii.length / 2)]
    const midFrac = (mid - ORCA_RING_MIN_R) / (ORCA_RING_R - ORCA_RING_MIN_R)
    assert.ok(midFrac > 0.60,
      `the coil must still be WIDE at the halfway mark and plunge on the LAST lap; it was already at ${mid.toFixed(0)} ` +
      `of ${ORCA_RING_R}->${ORCA_RING_MIN_R}, i.e. ${midFrac.toFixed(2)} of the way out (a linear close reads exactly 0.50)`)
    // 4. THE COIL IS PUBLISHED, CAPPED, AND READ. Without the published path render draws a circle
    // at the current radius, which is the tell that made a real spiral look like laps — so this is
    // the contract field the whole fix hangs on.
    assert.ok(peakTrail > 20, `the swept path must be published for render to stroke; it peaked at ${peakTrail} points`)
    assert.ok(peakTrail <= ORCA_TRAIL_MAX,
      `the trail must stay capped at ORCA_TRAIL_MAX (${ORCA_TRAIL_MAX}) or a whole stalk is drawn as a scribble; it reached ${peakTrail}`)
    // The CLAUDE.md source-text idiom (run UG.k): a field sim publishes with no consumer in
    // render.js is indistinguishable on screen from the bug it was written to fix, and nothing
    // throws. Both halves are asserted because either one alone passes over a broken pair.
    assert.ok(/o\.trail/.test(renderSrc),
      'render.js must READ run.orca.trail — publishing the coil with nothing stroking it leaves the circle-tell bug exactly as it was, silently')
    assert.ok(!/orcaG\.circle\([^)]*\)\s*\n?\s*\.stroke\(\{ width: 3/.test(renderSrc),
      'the bright hairline ring tell must be GONE — a circle drawn at the current radius reads as a circle whatever moves inside it, which is the defect')

    // 5. IT IS A SHADOW UNTIL THE STRIKE. The body surfacing IS the attack; drawing it through the
    // stalk is what made a hunt read as a swim. render.js gates the sprite on the state list.
    // ⚠ THE FIRST MATCH IS THE POOL'S OWN `orcaSp.visible = false` at construction, not the gate.
    // Anchoring on it reports "gates it on: false" and fails a correct renderer, which is a test
    // that lies in the same direction as the bug — pick the assignment that reads o.state.
    const gates = [...renderSrc.matchAll(/orcaSp\.visible = ([^\n]*)/g)].map((m) => m[1])
    const gate = gates.find((g) => /o\.state/.test(g))
    assert.ok(gate && /committing/.test(gate) && /leaving/.test(gate) && !/!rising/.test(gate),
      `the surfaced body must be drawn for 'committing' and 'leaving' ONLY, so the whole build is a silhouette; ` +
      `render.js gates it on: ${gate ?? `(none of ${gates.length} orcaSp.visible assignments reads o.state)`}`)
    // 6. AND IT COMES UP FROM UNDER THE PLAYER. The rise used to fade the silhouette up already
    // parked out on the ring, which on a 390x844 phone (half-width 195, ring 440) is off screen for
    // the sideways part of every bearing — and no coil is drawn yet that early, so the opening beat
    // of the build was a genuinely empty frame on the device this game is played on. It slides out
    // from the ring's CENTRE now, so the beat that had nothing in it has the biggest thing in the
    // chapter directly underneath. Measured as a distance from the ring centre, not as a field.
    {
      const r2 = mk()
      const q = r2.player
      r2.orca = {
        state: 'rising', t: ORCA_RISE_DUR,
        cx: q.x, cy: q.y, r: ORCA_RING_R, ang: 0,
        x: q.x + ORCA_RING_R, y: q.y, dirX: 0, dirY: 0, hit: false, alpha: 0, passes: 1,
      }
      const off = []
      while (r2.orca && r2.orca.state === 'rising') {
        hold(r2, [])
        stepSim(r2, { x: 0, y: 0 }, dt)
        const o = r2.orca
        if (!o || o.state !== 'rising') break
        off.push(Math.hypot(o.x - o.cx, o.y - o.cy))
      }
      assert.ok(off.length > 4, `the rise must actually run; it lasted ${off.length} frames`)
      assert.ok(off[0] < ORCA_RING_R * 0.2,
        `the silhouette must SURFACE UNDER the player, not out on the ring: its first frame sat ${off[0].toFixed(0)}px ` +
        `from the ring centre of ${ORCA_RING_R}. Parked on the ring this reads ${ORCA_RING_R} and the opening beat is off screen on a phone`)
      assert.ok(off[off.length - 1] > ORCA_RING_R * 0.8,
        `...and must be out ON the ring by the time the spiral takes over, or the coil starts from the wrong radius; ` +
        `it ended ${off[off.length - 1].toFixed(0)}px out`)
      assert.ok(off.every((v, k) => k === 0 || v >= off[k - 1] - 1e-9),
        'the slide out must be monotone — a shadow that jitters in and out is a glitch, not a rise')
    }
    console.log(`PASS run OR.f (the shadow spirals in): ${laps.toFixed(2)} laps closing ${ORCA_RING_R}->${radii[radii.length - 1].toFixed(0)} ` +
      `(still ${mid.toFixed(0)} at halfway, so it plunges late) while the rate ramps ${firstRate.toFixed(2)}->${lastRate.toFixed(2)} rad/s, ` +
      `publishing a ${peakTrail}-point coil render strokes — and the silhouette surfaces UNDER the player before any of it, staying under until it commits`)
  }

  console.log('PASS run OR (The Wreck: the orca): three harmless shadow passes open the chapter and scatter what they go under, a packed or baited field brings the next visit in sooner up to a hard cap, the commit runs through the centre of the coil, splashing there and eating what it herded in for free, its bow wave throws the rest of the battlefield to both sides of a line it draws twice a visit, and the whole build is a shadow coiling in from underneath that only surfaces to strike')
}
run(runOrca)

// ---- Run WG: THE SUNKEN SHIP'S FIELD (WK is already Bloodlust — do not reuse it) — four numbers in two files that are ONE decision ----------
// The wreck grid's spacing is authored in config.js (`cell`, `len`) and its jitter and size spread
// in render.js (HULL_JITTER, HULL_SCALE_MAX). Nothing imports anything, so nothing throws when they
// drift — and the failure does not look like a spacing bug. Two sprites at alpha a stack to
// 1-(1-a)², so an overlap is a visibly BRIGHTER quadrilateral bounded by straight edges belonging to
// neither wreck, which reads as a rendering artefact rather than as a graveyard. The shipped pair
// (cell 2450, jitter ±0.25) allowed 1225px between two 1820px hulls, and it was in half the probe
// frames while the config comment two lines above it claimed two are never on screen together.
//
// This is the cheapest guard shape in this repo (see the six cross-file source-text lints in
// CLAUDE.md): it costs a file read and it is the only thing standing between a one-number tune and
// a field of interpenetrating ships.
function runWreckGrid() {
  const rSrc = readFileSync(new URL('../src/render.js', import.meta.url), 'utf8')
  const hull = CHAPTERS.wreck.render.hull

  // -- WK.a: the spacing invariant, cell * (1 - 2*jitter) >= len * maxScale --------------------
  const constOf = (name) => {
    const m = rSrc.match(new RegExp(`const ${name} = ([0-9.]+)`))
    assert.ok(m, `${name} must exist in render.js as a named const — run WG reads it as source text`)
    return Number(m[1])
  }
  const jitter = constOf('HULL_JITTER')
  const scaleMax = constOf('HULL_SCALE_MAX')
  // ⚠ THIS INVARIANT HAS BEEN STATED OVER THE WRONG LENGTH THREE TIMES AND WENT GREEN OVER A REAL
  // OVERLAP EACH TIME — the first ignored the jitter, the second used cfg.len when the TEXTURE is
  // longer than cfg.len, and the third still assumed the sprite was CENTRED on its cell when
  // HULL_LEAD had stopped centring it. The binding quantity is the max reach from the PLACEMENT
  // POINT, and the requirement is twice it, because two neighbours can lean their long ends
  // together. HULL_REACH is load-bearing in render.js (the cull margins read it), so it cannot rot
  // into a number that only this assert believes.
  const reach = constOf('HULL_REACH')
  const minGap = hull.cell * (1 - 2 * jitter)
  const maxLen = 2 * hull.len * reach * scaleMax
  assert.ok(minGap >= maxLen,
    `two neighbouring wrecks can be ${minGap.toFixed(0)}px apart while together they reach ${maxLen.toFixed(0)}px — ` +
    'they interpenetrate, and at hull.alpha that is a bright quadrilateral, not a wreck. ' +
    'Raise cell, or lower HULL_JITTER / HULL_SCALE_MAX / HULL_LEAD (render.js)')
  console.log(`PASS run WG.a (spacing): cell ${hull.cell} x (1 - 2x${jitter}) = ${minGap.toFixed(0)}px clear ` +
    `>= 2 x len ${hull.len} x reach ${reach} x ${scaleMax} = ${maxLen.toFixed(0)}px, so no two hulls can overlap`)

  // -- WK.b: both halves of the invariant are actually WIRED -----------------------------------
  // A named constant nothing reads is a comment. Both position axes must consume HULL_JITTER, and
  // HULL_SCALE_MAX must equal the arithmetic of the scale line rather than merely sitting near it —
  // widening `hash(...) * 0.18` and leaving HULL_SCALE_MAX at 1.08 makes WK.a a guard over air.
  const jitterUses = (rSrc.match(/cs \* HULL_JITTER \* 2/g) || []).length
  assert.equal(jitterUses, 2,
    `HULL_JITTER must be read on BOTH position axes in updateWreckHull, found ${jitterUses} — ` +
    'a re-inlined literal is how the invariant above stops describing the code')
  const sc = rSrc.match(/const sc = \(cfg\.len \/ \(HULL_REF \* 2\)\) \* \(([0-9.]+) \+ hash\([^)]*\) \* ([0-9.]+)\)/)
  assert.ok(sc, 'updateWreckHull must set `sc` from cfg.len with a hashed spread — run WG reads its two numbers')
  const drawnMax = Number(sc[1]) + Number(sc[2])
  assert.ok(Math.abs(drawnMax - scaleMax) < 1e-9,
    `HULL_SCALE_MAX is ${scaleMax} but the scale line tops out at ${drawnMax.toFixed(3)} — ` +
    'WK.a is then checking a number the renderer does not use')
  console.log(`PASS run WG.b (wired): HULL_JITTER read on ${jitterUses} axes, and HULL_SCALE_MAX ${scaleMax} ` +
    `is exactly the scale line's ${sc[1]} + ${sc[2]}`)

  // -- WK.c: the field's grain and the chapter's tide are ONE fact ------------------------------
  // The hulls settle into the current, so hull.grain IS the tide bearing. Both come from
  // WRECK_TIDE_DEG; this asserts the wiring rather than the literal, so moving the tide moves the
  // graveyard with it.
  assert.equal(hull.grain, CHAPTERS.wreck.tide.axis,
    'hull.grain must BE the chapter tide axis — wrecks scour into the flow, and a second literal ' +
    'here is one fact authored twice with nothing importing anything')
  assert.ok(/sp\.rotation = cfg\.grain \+/.test(rSrc),
    'updateWreckHull must build its heading off cfg.grain — a bare full-circle hash ignores the grain entirely')
  console.log(`PASS run WG.c (grain): hull.grain = tide.axis = ${hull.grain.toFixed(3)} rad, and render.js reads it`)

  // -- WG.d: HULL_EXTENT and HULL_LEAD are both CONSUMED --------------------------------------
  // WG.a leans on HULL_REACH, so it has to be the renderer's own number rather than a figure
  // parked next to the guard. It is read by the cull margins (a value too small pops hulls in at
  // the screen edge, which is visible), and HULL_LEAD is what stops the grid centring the FRACTURE
  // — the bake's origin is the tear, so at lead 0 the modal crop is the empty gap and the report is
  // "the ship is invisible".
  const reachUses = (rSrc.match(/cfg\.len \* HULL_REACH \* HULL_SCALE_MAX/g) || []).length
  assert.equal(reachUses, 2,
    `HULL_REACH must be read by BOTH cull margins in updateWreckHull, found ${reachUses} — ` +
    'unread, it is a number WG.a trusts and nothing keeps true')
  assert.ok(/HULL_LEAD \* HULL_REF \* sc/.test(rSrc),
    'updateWreckHull must offset the sprite by HULL_LEAD along its heading — without it the cell ' +
    'centre lands on the fracture, i.e. on the one part of the drawing that is deliberately empty')
  console.log(`PASS run WG.d (consumed): HULL_REACH read on ${reachUses} cull margins, HULL_LEAD applied along the heading`)

  console.log('PASS run WG (The Wreck: the sunken ship field): the grid can never stack two hulls into one bright ' +
    'quadrilateral, every constant the invariant names is one the renderer actually reads, and the field lies ' +
    'along the same bearing as the water that put it there')
}
run(runWreckGrid)

// ---- Run DK: THE DARK (v7.x Book 2, owner directive) --------------------------------------
// "if we're stealing light, then our surroundings should be dark, and darker the less light we
// have", plus a drawback while you are down there — move speed, chosen over damage and accuracy
// because weapons auto-fire, so a slow player still kills and the state stays escapable.
//
// The thing worth guarding is not the arithmetic of darkness() but that ONE curve drives BOTH the
// dimming and the slow. They are separately implemented (render.js reads it for a scrim alpha,
// sim.js for a speed multiplier) and a drift between them is invisible in every screenshot: the
// world would dim on a different schedule from the one your legs are on, and the player would have
// no way to tell what state they are in.
function runDark() {
  const res = CHAPTERS.twilight.resource
  const d = res.dark
  const twilightMeta = () => ({
    coins: 0, shop: {}, best: {}, runs: 0, choiceSlots: 2, chapter: 'twilight', dev: true,
    chapters: Object.fromEntries(['body', 'pond', 'twilight', 'beyond']
      .map((id) => [id, { unlocked: true, maxDifficulty: 5, difficulty: 1 }])),
  })

  // (a) the curve. 0 at and above the threshold (so most of a well-played run is untouched), 1 at
  // an empty bar, and linear between — no thresholds for the player to learn.
  {
    assert.strictEqual(darkness(res.max, res), 0, 'a full bar must be fully lit')
    assert.strictEqual(darkness(res.max * d.from, res), 0, 'exactly at the threshold is still fully lit')
    assert.strictEqual(darkness(res.max * (d.from + 0.01), res), 0, 'above the threshold is fully lit')
    assert.strictEqual(darkness(0, res), 1, 'an empty bar must be maximally dark')
    const mid = darkness(res.max * d.from * 0.5, res)
    assert.ok(Math.abs(mid - 0.5) < 1e-9, `halfway to empty must read 0.5, got ${mid}`)
    // A chapter with no `dark` block must return 0 for every charge, not NaN — every chapter runs
    // this function through the renderer once a frame.
    assert.strictEqual(darkness(0, CHAPTERS.pond.resource ?? undefined), 0, 'no resource -> no darkness')
    assert.strictEqual(darkness(50, { max: 100 }), 0, 'a resource with no dark block -> no darkness')

    // TASK 9 FIX ROUND (2026-08-16, coordinator review) — the optional 3rd `max` parameter. Deep
    // Lungs raises a run's own ceiling above res.max, and darkness() has no `run` to read (config.js
    // is pure data + pure helpers, imports nothing), so a caller holding a run passes ITS ceiling in
    // explicitly. Omitted, it must still mean res.max — every existing 2-arg call above depends on
    // that default never changing.
    assert.strictEqual(darkness(70, res), darkness(70, res, res.max),
      'omitting max must still mean res.max, or every 2-arg call site above just changed meaning')
    // The regression itself: the THRESHOLD moves with the ceiling (d.from x max), so a charge that
    // reads fully lit against the OLD max must read DARK once the run's raised ceiling is supplied —
    // a caller still dividing by res.max cannot see this, which is exactly how the chapter's dark
    // fell silent for the whole band Deep Lungs added.
    const bigMax = res.max * (1 + BOOK_SHOP.undertow.deepLungs.perLevel * lineMax('deepLungs'))   // Deep Lungs at max level
    assert.strictEqual(darkness(70, res, res.max), 0,
      'precondition: 70 against the OLD max of 100 must read fully lit (70/100=0.7 >= the 0.5 threshold)')
    assert.ok(darkness(70, res, bigMax) > 0,
      `70 against a Deep-Lungs-raised ceiling of ${bigMax} must read DARK (70/${bigMax}=${(70 / bigMax).toFixed(2)} < 0.5) — a caller still defaulting to res.max cannot see this`)
  }

  // (a2) THE LIGHT YOU EMIT rides the SAME curve, which is the whole reason it is written as a
  // function of darkness() and not of charge/max. Owner: "you are the source light, you emit the
  // light, but the less light you have, the less far you emit." If this interpolated on raw charge
  // instead, the light would start closing in at a full bar while the slow waited until half — two
  // schedules, and the player unable to tell which state they are in from the picture.
  {
    // MEASURED AGAINST THE SCREEN'S LONGEST SIDE, and LINEAR IN THE RAW BAR. Owner spec, after
    // three shipped attempts that all anchored on the half-diagonal and gated on `from`: "base
    // light radius at 100% bar filled is the biggest dimension of the screen, then it reduces down
    // linearly to 10% that radius".
    const PHONE = Math.max(390, 844)      // 844px
    const DESK = Math.max(1280, 800)      // 1280px
    assert.strictEqual(lightRadius(res.max, res, PHONE), d.radiusFull * PHONE, 'a full bar lights radiusFull x the longest side')
    assert.strictEqual(lightRadius(0, res, PHONE), d.radiusEmpty * PHONE, 'an empty bar lights only radiusEmpty')
    // NOT GATED ON `from`. This is the assertion the whole chapter's legibility rests on, and the
    // one every previous version failed: a light pinned at full reach until half a bar spends the
    // top half of the range showing nothing, because a radius that covers the screen's CORNERS is
    // 2.38x the one that covers its nearest EDGE (465px vs 195px on a phone) and every radius in
    // that band looks identical. Measured then: 85.5 mean luminance at 50% of the bar, 85.3 at 40%.
    // Spending Light must move the picture at 90% of the bar as surely as at 20%.
    assert.ok(lightRadius(res.max * 0.9, res, PHONE) < lightRadius(res.max, res, PHONE) - 1,
      'the light must already be shrinking at 90% of the bar — gating it on `from` is what made three versions unreadable')
    // ...and LINEARLY, so the rate never surprises: the midpoint of the bar lights the midpoint
    // radius, to floating-point.
    const mid = lightRadius(res.max * 0.5, res, PHONE)
    assert.ok(Math.abs(mid - ((d.radiusFull + d.radiusEmpty) / 2) * PHONE) < 1e-9,
      `half a bar must light the midpoint radius, got ${mid}`)
    // DEVICE PARITY: at every level of the bar the two screens must light the same FRACTION of
    // their own longest side. Asserting px would pass the original world-px version at exactly one
    // screen size and fail it everywhere else, which is how that bug shipped.
    for (let c = res.max; c >= 0; c -= res.max / 20) {
      assert.ok(Math.abs(lightRadius(c, res, PHONE) / PHONE - lightRadius(c, res, DESK) / DESK) < 1e-9,
        `phone and desktop must light the same fraction of the screen (charge ${c})`)
    }
    // radiusFull >= 1: at a full bar the rim is at least a screen away, so the chapter opens with
    // no dark on it whatever the aspect ratio.
    assert.ok(d.radiusFull >= 1, 'a full bar must put the light\'s rim off-screen on any aspect ratio')
    // Monotone shrinking, sampled — a non-monotone radius would read as the light flickering back
    // out as you get worse, and no endpoint check can catch it.
    let prev = Infinity
    for (let c = res.max; c >= 0; c -= res.max / 40) {
      const r = lightRadius(c, res, PHONE)
      assert.ok(r <= prev + 1e-9, `light radius must never grow as the bar empties (charge ${c})`)
      prev = r
    }
    assert.ok(d.radiusEmpty > 0 && d.radiusEmpty < d.radiusFull, 'an empty bar must still light SOMETHING, and less than a full one')
    // Out-of-range charge must not invert the light (a refill overshoot past res.max would otherwise
    // grow the radius past radiusFull, and a negative would push it under radiusEmpty).
    assert.strictEqual(lightRadius(res.max * 2, res, PHONE), d.radiusFull * PHONE, 'an overfull bar clamps to radiusFull')
    assert.strictEqual(lightRadius(-10, res, PHONE), d.radiusEmpty * PHONE, 'a negative bar clamps to radiusEmpty')
    // A chapter with no dark lights everything. Infinity and not 0: the renderer's "does my light
    // already cover the corner" early-out has to say yes, and a 0 would black the screen out.
    assert.strictEqual(lightRadius(0, CHAPTERS.pond.resource ?? undefined, PHONE), Infinity, 'no resource -> unbounded light')
    assert.strictEqual(lightRadius(50, { max: 100 }, PHONE), Infinity, 'a resource with no dark block -> unbounded light')

    // TASK 9 FIX ROUND (2026-08-16, coordinator review) — the optional 4th `max` parameter, same
    // default-preserving idiom as darkness() above (maxDim already owns position 3).
    assert.strictEqual(lightRadius(res.max * 0.9, res, PHONE), lightRadius(res.max * 0.9, res, PHONE, res.max),
      'omitting max must still mean res.max, or every 3-arg call site above just changed meaning')
    // THE ACTUAL BUG: lightRadius's frac clamps to 1, so against the OLD max, two DIFFERENT charges
    // both above it read the SAME radius (radiusFull) — this is the "HUD/light pinned at full and
    // motionless" defect Finding 1 reported. Prove the collapse first (so this is provably testing
    // the regression, not asserting two arbitrary unequal numbers), then prove the run's own
    // (raised) ceiling un-collapses it.
    const bigMax2 = res.max * (1 + BOOK_SHOP.undertow.deepLungs.perLevel * lineMax('deepLungs'))
    assert.strictEqual(lightRadius(res.max * 1.1, res, PHONE, res.max), lightRadius(res.max * 1.7, res, PHONE, res.max),
      'precondition: against the OLD max, two different charges above it must both saturate at radiusFull — that saturation is the bug')
    assert.notStrictEqual(lightRadius(res.max * 1.1, res, PHONE, bigMax2), lightRadius(res.max * 1.7, res, PHONE, bigMax2),
      'two different charges above the OLD max must light DIFFERENT radii once the run\'s own (raised) ceiling is passed as the 4th arg — a caller still defaulting to res.max would see these collapse to one value')
  }

  // (b) THE SLOW IS REAL, and measured as DISTANCE TRAVELLED rather than by reading a multiplier
  // back out. Asserting the knob would pass with the feature deleted; asserting the distance is
  // what fails if stepPlayer stops consulting the curve.
  const travel = (charge, extra) => {
    Math.random = mulberry32(4242)
    const run = createRun(twilightMeta(), { chapter: 'twilight', difficulty: 1 })
    run.shafts.length = 0              // no refill: the bar must hold where it is put
    run.charge = charge
    if (extra) extra(run)
    const x0 = run.player.x, y0 = run.player.y
    for (let i = 0; i < 60; i++) {
      run.charge = charge              // re-pin: stepCharge drains it, and this measures ONE level
      stepSim(run, { x: 1, y: 0, skill: false }, 1 / 60)
      run.events.length = 0
    }
    return Math.hypot(run.player.x - x0, run.player.y - y0)
  }
  {
    const lit = travel(res.max)
    const empty = travel(0)
    const ratio = empty / lit
    assert.ok(Math.abs(ratio - d.speedFloor) < 0.02,
      `an empty bar must move at x${d.speedFloor} of a full one, measured x${ratio.toFixed(3)} (${empty.toFixed(1)}px vs ${lit.toFixed(1)}px)`)
    // Above the threshold nothing happens at all — the chapter plays like any other.
    const atThreshold = travel(res.max * d.from)
    assert.ok(Math.abs(atThreshold - lit) < 0.01,
      `at the threshold the player must move at FULL speed, got ${atThreshold.toFixed(1)}px vs ${lit.toFixed(1)}px`)
    // ...and halfway down, halfway to the floor. A curve applied as a step rather than a ramp
    // passes both endpoints above and fails here.
    const half = travel(res.max * d.from * 0.5) / lit
    const want = 1 - (1 - d.speedFloor) * 0.5
    assert.ok(Math.abs(half - want) < 0.02, `halfway dark must move at x${want}, measured x${half.toFixed(3)}`)
  }

  // (c) it joins the slow MIN, it does not multiply into it. The strongest slow wins, so standing
  // in a web while dark is exactly as slow as the worse of the two — never the product. Without
  // this, every web and every latch in this chapter is silently nastier than the same web anywhere
  // else, which is a difficulty change nobody asked for and which no test would otherwise notice.
  //
  // Composed against the LATCH slow rather than a web: latch is a plain player field (slowT) with
  // no entity shape to get wrong, and the two constants differ (0.55 vs the 0.6 floor), so this
  // still tells MIN from a product. A hand-built run.webs fixture measured x0.993 — the fixture was
  // not slowing anything, which would have made the assertion vacuous rather than failing loudly.
  {
    const latched = (charge) => travel(charge, (run) => { run.player.slowT = 10 })
    const lit = travel(res.max)
    const latchLit = latched(res.max) / lit
    const latchDark = latched(0) / lit
    assert.ok(Math.abs(latchLit - LATCH_SLOW_MUL) < 0.02,
      `a latch alone must slow to x${LATCH_SLOW_MUL}, got x${latchLit.toFixed(3)} — if this is 1 the fixture is not slowing and the next assertion proves nothing`)
    const strongest = Math.min(LATCH_SLOW_MUL, d.speedFloor)
    assert.ok(Math.abs(latchDark - strongest) < 0.02,
      `latch + dark must be the STRONGEST of the two (x${strongest}), not the product (x${(LATCH_SLOW_MUL * d.speedFloor).toFixed(3)}) — measured x${latchDark.toFixed(3)}`)
  }

  // (d) a chapter with no resource is untouched. The Pond shares stepPlayer, and the guard that
  // keeps it out of this is one optional-chain away from being deleted by accident.
  {
    Math.random = mulberry32(4242)
    const pond = createRun(twilightMeta(), { chapter: 'pond', difficulty: 1 })
    const x0 = pond.player.x
    for (let i = 0; i < 60; i++) { pond.charge = 0; stepSim(pond, { x: 1, y: 0 }, 1 / 60); pond.events.length = 0 }
    const dist = pond.player.x - x0
    Math.random = mulberry32(4242)
    const pond2 = createRun(twilightMeta(), { chapter: 'pond', difficulty: 1 })
    const x1 = pond2.player.x
    for (let i = 0; i < 60; i++) { pond2.charge = 100; stepSim(pond2, { x: 1, y: 0 }, 1 / 60); pond2.events.length = 0 }
    assert.ok(Math.abs(dist - (pond2.player.x - x1)) < 1e-9,
      'a chapter with no resource must move identically whatever its (inert) charge field says')
  }

  // (e) the RENDER side reads the same curve, and every light SUBTRACTS. render.js is not importable
  // here (Vite-only import.meta.glob), so this is the run UG.k source-text trick. A dark that
  // invented its own ramp would pass every assertion above and still drift from the slow on screen,
  // which is the entire failure this run exists to prevent.
  {
    const src = readFileSync(new URL('../src/render.js', import.meta.url), 'utf8')
    // TWO quantities ride the bar, not one. The radius alone cannot be read for the top half of the
    // drainable range: at `from` the lit core exactly covers the screen by construction, so nothing
    // shows until it shrinks below the half-diagonal — measured at under 4% of mean screen luminance
    // between a half bar and 30% on a phone, which the owner reported twice as "only full dark or
    // full light". The far field's alpha must therefore ramp too, on the SAME curve so the two cues
    // and the move-speed slow can never come apart.
    // The far field's alpha is a CONSTANT. Owner, 2026-08-13, rejecting a ramped one in play: "I
    // want the light radius to fade, not the whole screen." Ramping it also measured as a no-op —
    // at a large radius there is barely any far field for an alpha to act on, and the mid-bar came
    // back LIGHTER than without it (84.3 mean luminance at 30% against 82.5).
    assert.ok(/const a = res\?\.dark \? res\.dark\.dim : 0/.test(src),
      'the far field must be a flat dim — ramping it was rejected in play and measured as a no-op')
    // ...and dim 1: an empty bar's far field is the tint and nothing else (owner, 2026-08-13,
    // "much darker when light = 0", picked near-black off a 4-way shot). Retuning this is a
    // decision, not a detail — if it moves, it moves here too, on purpose.
    assert.ok(d.dim >= 1, `the far field must be fully opaque (owner ruling), got dim ${d.dim}`)
    // run.chargeMax (v7.x Book 2 Task 9 fix round): the 4th arg is the run's OWN ceiling, not the
    // config max — omitting it pins the light at radiusFull for the whole band a Deep-Lungs run
    // spends above the old res.max, which is exactly the bug this fix round exists to close.
    // run.sightCharge (v7.x, The Shelf's Clear): the FIRST argument is what the player can see, not
    // the raw bar — sim.js's stepCharge publishes it, and it IS run.charge on every frame of every
    // chapter but the ones where a Clear window is open. Reading run.charge here instead would leave
    // the button's whole payload invisible while the sim happily counted it down, which is the
    // frozen-enemies scar's exact shape and the reason this line is asserted as source text at all.
    assert.ok(/const R = lightRadius\(run\.sightCharge \?\? run\.charge, res, Math\.max\(w, h\), run\.chargeMax\)/.test(src),
      "render.js must size the light from lightRadius(run.sightCharge ?? run.charge, res, longest side, run.chargeMax) — sightCharge is the field the Clear lends sight through, the screen's longest side is the unit the chapter states its light in, and chargeMax is the ceiling that light saturates against")
    // NO ALPHA ANYWHERE IN THE PATH, and this is the assertion the chapter's existence rests on.
    // The lightmap used to be a white canvas with the lights punched out by `destination-out`, drawn
    // as a translucent tinted sprite — the whole effect lived in a canvas ALPHA channel that then had
    // to survive being uploaded as a texture. On the owner's phone it did not: at 88/100 Light the
    // screen was solid black with no lit disc at all, while the sun shafts (arc+fill) rendered
    // perfectly. Four releases were spent moving where the layer switches on, which only moved where
    // the blackout started. Darkness is carried as OPAQUE COLOUR and composited with multiply.
    assert.ok(/darkSprite\.blendMode = 'multiply'/.test(src),
      'the lightmap must be composited with multiply — white leaves the scene alone, the tint crushes it')
    assert.ok(/getContext\('2d', \{ alpha: false \}\)/.test(src),
      'the lightmap canvas must be opaque: an alpha channel here is the thing that did not survive on the owner\'s device')
    assert.ok(/darkSprite\.alpha = 1/.test(src) && /darkSprite\.tint = 0xffffff/.test(src),
      'the dark sprite must be neither faded nor tinted — the colour IS the darkness, and doing either puts the effect back on the broken channel')
    // NO OPERATOR THAT CAN WRITE TRANSPARENCY. This used to be a blanket ban on
    // globalCompositeOperation, and the ban was aimed at the wrong noun: what broke on the owner's
    // device was not "an operator" but the effect living in the ALPHA channel, which then had to
    // survive a texture upload. Every operator below can put transparency into an opaque canvas's
    // pixels — `destination-out` is the one that actually shipped the blackout — so they stay
    // banned by name. `lighten` is a pure per-channel max on colour and cannot reach alpha at all,
    // which is exactly why the lure glow is allowed to use it: light ADDS, and a plain fill would
    // stamp a dimmer disc into the middle of the player's own lamp instead.
    const ALPHA_OPS = /globalCompositeOperation\s*=\s*'(destination-out|destination-in|destination-atop|source-in|source-out|source-atop|xor|copy)'/
    assert.ok(!ALPHA_OPS.test(src),
      'no alpha-writing canvas operator may come back: destination-out is what carried the effect in alpha, and this canvas is opaque by contract')
    // And whatever operator IS set must be put back. A leaked 'lighten' would survive into the next
    // frame's opening fillRect — which paints the dark — so the background could only ever get
    // brighter and the chapter would wash out over a few seconds. Silent, and untraceable by eye.
    const opSets = src.match(/globalCompositeOperation\s*=\s*'[a-z-]+'/g) || []
    const resets = opSets.filter((o) => /'source-over'/.test(o)).length
    assert.strictEqual(opSets.length, resets * 2,
      `every globalCompositeOperation must be paired with a reset to 'source-over' — found ${opSets.length} set(s) and ${resets} reset(s), so one leaks into the next frame's background fill`)
    assert.ok(!/LIGHT_BLOB/.test(src),
      'the pre-baked offscreen lamp must stay deleted — its drawImage is the operation that produced nothing on the owner\'s device')
    // The player's lamp and the shafts must both be plain fills, i.e. the SAME primitive that was
    // observed to render there. A stamp of any kind reintroduces the failure.
    assert.ok(/createRadialGradient\(px \* s, py \* s, 0, px \* s, py \* s, lampR\)/.test(src),
      'the player lamp must be a per-frame radial gradient centred on the player')
    assert.ok(/arc\(px \* s, py \* s, lampR, 0, Math\.PI \* 2\)/.test(src),
      'the lamp must be filled as a DISC — a radial gradient clamps past its outer radius, so a rect would paint the rim colour into the corners')
    assert.ok(/arc\(sx \* s, sy \* s, sh\.r \* s/.test(src),
      'each shaft must be filled at its OWN radius, or standing in one stops clearing the dark')
    // DARK_RAMP is still the darkness profile, now read as a COLOUR ramp: rgbAt(1 - d) runs white at
    // the core to the tint at the rim. Inverted, the lamp would paint a dark disc on a lit field.
    assert.ok(/const DARK_RAMP = \[0, [\d., ]*1\]/.test(src),
      'DARK_RAMP is the DARKNESS profile and must run 0 at the core to 1 at the rim')
    assert.ok(/grad\.addColorStop\(t, rgbAt\(1 - d\)\)/.test(src),
      'the ramp must be read as 1 - DARK_RAMP: rgbAt takes how LIT a stop is, not how dark')
    // The sharpness knob has two readers and they must not drift: it positions the bake's ramp, and
    // it turns the chapter's core radius into the outer one the stamp is drawn at. Two hardcoded
    // copies is what this file used to have. It must NOT reach the early-out any more — the whole
    // point of stating the light as a fraction of the screen is that "is the screen lit?" is one
    // comparison in one unit, so a sharpness change cannot move how much of the screen is dark.
    assert.ok(/const LIGHT_CORE_FRAC = /.test(src)
      && /LIGHT_CORE_FRAC \+ \(1 - LIGHT_CORE_FRAC\)/.test(src)
      && /R \* LIGHT_CORE_FRAC >= corner/.test(src),
      'ONE LIGHT_CORE_FRAC must both position the falloff ramp and gate the early-out')
    // The construct this replaced, kept as a tripwire: Graphics.cut() cannot take holes that overlap
    // each other, and the player's circle overlapping a shaft's is the chapter, not an edge case.
    // It shipped at v7.55 as a hard-edged wedge of night across the whole viewport.
    assert.ok(!/\.cut\(\)/.test(src.replace(/^\s*\/\/.*$/gm, '')),
      'no Graphics.cut() in render.js: overlapping holes triangulate into straight-edged garbage, which is how the dark shipped broken')
    // The clause this protects is "the dark is over the WORLD and under the safety cues", NOT a
    // literal adjacency — a literal one has already gone red twice for changes that kept the
    // contract perfectly (The Surf's water wash, then its above-the-waterline layer, both of which
    // belong between the two). Assert the ORDER, which is the actual rule.
    const stage = src.slice(src.indexOf('app.stage.addChild('))
    const at = (name) => {
      const i = stage.indexOf(name)
      assert.ok(i >= 0, `${name} is not on the stage — the layer order assertion below cannot see it`)
      return i
    }
    assert.ok(at('world,') < at('darkLayer,'), 'the dark must sit above `world`')
    assert.ok(at('darkLayer,') < at('idleLayer,'), 'the dark must stay below the damage numbers')
    assert.ok(at('darkLayer,') < at('lightningFlash,') && at('darkLayer,') < at('vignette'),
      'the dark must stay below the damage vignette/flash, or it takes the safety cues with it')
  }

  console.log(`PASS run DK (the dark): two schedules on purpose — the light you emit closes LINEARLY from ${d.radiusFull}x to ${d.radiusEmpty}x the screen longest side across the WHOLE bar while the player slows to x${d.speedFloor} only below ${(d.from * 100).toFixed(0)}/${res.max}, MIN-composed with the latch slow, pond untouched, player and shafts filled into an OPAQUE lightmap composited by multiply (no alpha, no bake, no cut)`)
}
run(runDark)

// ---- Run RA: every creature in a roster has art, and every chapter card has a thumbnail ---------
// TWO SILENT FAILURES, both already documented in render.js's own comments and neither one caught
// by anything until now:
//   - a roster id with no ROSTER_LOOKS entry does NOT throw. syncEnemies falls through to the
//     generic archetype blob, so a new chapter's creatures simply render as Chapter 1's kawaii
//     cells, with no error anywhere. render.js says exactly this above the beyond block, having
//     been bitten by it in v5.18.
//   - src/cast/*.png is GENERATED (scripts/bake-cast.mjs) and HAND-RUN. A chapter whose
//     render.cast names a new id keeps showing the old drawing on its title card, and bake-cast's
//     own header calls this out as a ponytail: nothing warns you.
// v7.x walked straight through both: The Twilight's roster went amoeba/tadpole/tardigrade ->
// copepod/krill/jelly, which is exactly the diff that strands a look key or a stale thumbnail.
// render.js is not importable here (Vite-only import.meta.glob), so the look table is read as
// SOURCE TEXT — the run UG.k trick.
function runRosterArt() {
  const src = readFileSync(new URL('../src/render.js', import.meta.url), 'utf8')
  const start = src.indexOf('const ROSTER_LOOKS = {')
  assert.ok(start > 0, 'render.js must still declare ROSTER_LOOKS (this whole run reads it as text)')
  const end = src.indexOf('\n  }\n', start)
  assert.ok(end > start, 'could not find the end of the ROSTER_LOOKS object')
  const block = src.slice(start, end)
  // Entries sit one indent level inside the object literal. Matching `key: {` and NOT
  // `key: { archetype:` on purpose — the multi-line entries (toad) carry archetype on the next line.
  const looks = new Set([...block.matchAll(/^ {4}(\w+):\s*\{/gm)].map((m) => m[1]))
  assert.ok(looks.size >= 30, `expected a full look table, parsed only ${looks.size} keys — the regex has drifted from the file`)

  // EVERY chapter that exists, not CHAPTER_ORDER — which is BOOKS.book1.chapters and therefore
  // excludes both the hidden Blank and the whole `undertow` book. The first cut of this run used
  // CHAPTER_ORDER and silently skipped The Shelf, i.e. the exact chapter it was written for: a
  // mutation deleting the copepod's look passed it green. Object.keys is the honest denominator.
  const ALL_IDS = Object.keys(CHAPTERS)
  assert.ok(ALL_IDS.includes('shelf') && ALL_IDS.includes('blank'),
    'this run must sweep the WIP book and the hidden chapter too — they are exactly where a missing look hides')
  let rosters = 0
  for (const id of ALL_IDS) {
    for (const e of CHAPTERS[id].roster ?? []) {
      rosters++
      assert.ok(looks.has(e.id),
        `chapter '${id}' rosters '${e.id}' but ROSTER_LOOKS has no entry for it — it would render as a generic archetype blob, silently`)
    }
  }
  assert.ok(rosters >= 20, `expected every chapter's roster, counted only ${rosters}`)

  let thumbs = 0
  for (const id of ALL_IDS) {
    for (const cid of CHAPTERS[id].render?.cast ?? []) {
      thumbs++
      assert.ok(looks.has(cid), `chapter '${id}' puts '${cid}' on its title card, but no ROSTER_LOOKS entry can draw it`)
      assert.ok(existsSync(new URL(`../src/cast/${cid}.png`, import.meta.url)),
        `chapter '${id}' casts '${cid}' but src/cast/${cid}.png is missing — re-run node scripts/bake-cast.mjs`)
    }
  }
  assert.ok(thumbs >= 12, `expected a cast per chapter card, counted only ${thumbs}`)

  // THE JELLY IS THE ONE SIDE-ELEVATION BODY IN THE GAME, AND IT ONLY WORKS AT lean 90.
  // Everything else is drawn in plan view, so the pair (view, lean) is normally decided once and
  // never revisited. Here it is load-bearing: the art puts the apex at +x and streams the mouth,
  // the oral arms and every tentacle to -x, which is legal ONLY because lean 90 lets syncEnemies
  // aim that axis at the player. Drop it back to 0 — the value every other radial body uses, and
  // the value this entry itself carried until the redesign — and the bell stops turning while the
  // tentacles keep pointing one fixed compass direction regardless of where the animal is going.
  // Nothing else in the suite or the renderer would notice: no throw, no missing texture, just a
  // creature swimming sideways forever. Hence a text assert, the run UG.k trick.
  const jelly = block.match(/^ {4}jelly:\s*\{[^}]*\}/m)
  assert.ok(jelly, 'ROSTER_LOOKS must still declare a jelly entry')
  assert.ok(/lean:\s*90/.test(jelly[0]),
    'the jelly is drawn in side elevation with its apex at +x — it must be lean 90, or the body never turns and the tentacles trail in a fixed screen direction')
  const jd = src.slice(src.indexOf('function drawJelly('))
  const jdEnd = jd.indexOf('\n  }\n')
  assert.ok(jdEnd > 0, 'could not find the end of drawJelly')
  const jbody = jd.slice(0, jdEnd)
  // The apex must be FORWARD and the mouth AFT. Swap the signs and the art is still a jellyfish,
  // still renders, and now swims backwards — tentacles first into the player.
  assert.ok(/const xf = r \* 0\.\d+/.test(jbody) && /const xa = -r \* 0\.\d+/.test(jbody),
    'drawJelly must keep the apex at +x (xf) and the mouth plane at -x (xa) — reversed, it swims tentacles-first')

  console.log(`PASS run RA (roster art): ${looks.size} baked looks cover all ${rosters} roster entries across ${ALL_IDS.length} chapters, all ${thumbs} title-card thumbnails exist on disk, and the side-on jelly is lean 90 with its apex forward`)
}
run(runRosterArt)

// ---- Run SC: the sacrifice seam (v7.x) ---------------------------------------------------------
// SCAVENGER WAS REMOVED, AND ITS MACHINERY STAYED. It was the only BOOK_UNLOCKS entry the game ever
// had; the table, its three helpers, sacTargets' loop and onSacrifice's non-'slot' branch are all
// book-agnostic and none of them names a key, so they were kept as the seam the next unlock arrives
// through. That leaves two ways to be wrong, and this scenario covers both:
//   - the removal is only PARTLY done — a chapter still declaring a per-kill refill nothing reads,
//     or sim.js still reaching for the deleted run.killRefill;
//   - the seam rots while it is empty, and the next unlock added to the table is unpurchasable in
//     exactly the way the first one was (see (c)).
// This replaced run LT, which measured what the unlock paid per kill.
function runSacrificeSeam() {
  // (a) THE REMOVAL IS COMPLETE, CONFIG SIDE. A chapter left declaring `killRefill` is inert config
  // that reads as live balance — this repo's single largest defect class — and no import binds the
  // two, so nothing throws. Object.keys(CHAPTERS) is the honest denominator (CLAUDE.md):
  // CHAPTER_ORDER is Book 1 only and would silently skip every chapter this removal touched.
  const chapterIds = Object.keys(CHAPTERS)
  const withResource = chapterIds.filter((id) => CHAPTERS[id].resource)
  {
    const stillDeclared = withResource.filter((id) => 'killRefill' in CHAPTERS[id].resource)
    assert.deepStrictEqual(stillDeclared, [],
      `chapter resource(s) still declaring killRefill: [${stillDeclared.join(', ')}] — Scavenger was the only reader and it is gone, so this is a number that looks like balance and is not`)
    // `killBase` is what survived, and only where a chapter has no refill circle at all. If a second
    // chapter grows one, that is a real design decision and this line is where it gets stated.
    const withKillBase = withResource.filter((id) => (CHAPTERS[id].resource.killBase ?? 0) > 0)
    assert.deepStrictEqual(withKillBase, ['wreck'],
      `killBase is meant to be The Wreck's alone (it is the one bar with no place to stand in); found [${withKillBase.join(', ')}]`)
  }

  // (b) THE REMOVAL IS COMPLETE, SIM SIDE — and this one fails SILENTLY rather than loudly. There is
  // no run.killRefill any more, so a surviving `run.charge + run.killRefill` is `x + undefined` =
  // NaN: the bar does not error, it disappears, and every downstream read (the dark, the Pulse's
  // ammo, drowning) quietly goes with it.
  {
    const src = readFileSync(new URL('../src/sim.js', import.meta.url), 'utf8')
    assert.ok(!/\brun\.killRefill\b/.test(src),
      'sim.js still reads run.killRefill — the field went with Scavenger, so this adds undefined to the bar and NaNs it silently')
    assert.ok(/_res\?\.killBase \?\? 0/.test(src),
      "sim.js must still read the chapter's own killBase at the kill site — that is the only per-kill refill left")
    // The rule sim.js has always had, and the reason the snapshot existed in the first place: sim
    // plays what it is handed. Worth keeping now that the field it guarded is gone.
    assert.ok(!/\bmeta\.\w+/.test(src.replace(/^\s*\/\/.*$/gm, '')),
      'sim.js must never read meta — it plays what createRun handed it (the plan\'s R1)')
  }

  // (c) THE SEAM IS STILL CORRECTLY SHAPED. All source-text, because ui.js cannot be imported here
  // (initUI calls document.getElementById on its first line and there is no jsdom) — same trick run
  // UG.k uses for render.js's hooks.
  //
  // RULING 1 (Task 6, 2026-08-16) is what these guard, and it is worth restating because the empty
  // table cannot: sacTargets once hand-rolled its own branch with a hardcoded id: 'thief' behind a
  // bare meta.dev check, reading a legacy top-level field for "already bought". Two silent bugs at
  // once — onSacrifice resolves a non-'slot' target through BOOK_UNLOCKS[bookId], and the real key
  // was 'lightThief', so the unlock was permanently unpurchasable (cost resolved null, the button
  // never lit) AND would never have disappeared after a purchase. An empty table makes all of that
  // unreachable, which is exactly why it needs a structural guard rather than a behavioural one:
  // the next person to add a row inherits either the shape or the bug.
  {
    const ui = readFileSync(new URL('../src/ui.js', import.meta.url), 'utf8')
    const start = ui.indexOf('function sacTargets(bookId) {')
    assert.ok(start > 0, 'ui.js must still declare function sacTargets(bookId) { — this block reads it as text')
    const end = ui.indexOf('\n  }\n', start)
    assert.ok(end > start, 'could not find the end of sacTargets')
    const body = ui.slice(start, end)

    assert.doesNotMatch(body, /meta\.dev/,
      'sacTargets must not gate on meta.dev directly — reachability already gates a book-specific target (see the ruling comment above sacTargets in ui.js)')
    assert.doesNotMatch(body, /meta\.lightThief/,
      'sacTargets must not read the legacy top-level meta.lightThief — onSacrifice writes bm.unlocks[target], and reading the old field is exactly why the button never disappeared after a purchase')
    assert.ok(/const cost = unlockCost\(bookId, id, unlockLevel\(bm, bookId, id\)\)/.test(body),
      "sacTargets must price the next rung from THIS book's purse via unlockLevel(bm, …), not a Book-1-shaped legacy field")
    assert.ok(/if \(cost == null\) continue/.test(body),
      'sacTargets must drop an unlock whose ladder is finished — that null IS the already-bought gate')
    assert.ok(/for \(const \[id, u\] of Object\.entries\(BOOK_UNLOCKS\[bookId\] \?\? \{\}\)\)/.test(body),
      'sacTargets must iterate Object.entries(BOOK_UNLOCKS[bookId] ?? {}) by its own keys — the ?? {} is what makes an EMPTY table a no-op instead of a throw')
    assert.ok(/out\.push\(\{ id, cost,/.test(body),
      "the BOOK_UNLOCKS branch must push the LOOP's own `id` binding — a separately-typed id here (however named) can silently stop matching the table's real key")
    const idLiterals = [...body.matchAll(/\bid:\s*'([^']+)'/g)].map((m) => m[1])
    assert.deepStrictEqual(idLiterals, ['slot'],
      `sacTargets may only hardcode 'slot' as a literal id; every other emitted id must come from the BOOK_UNLOCKS loop above — found literal id(s): ${JSON.stringify(idLiterals)}`)
  }

  // (d) onSacrifice's half of the same seam. 'slot' is the only target the shipped UI can send while
  // the table is empty, so every one of these is guarding the future row rather than today's screen.
  {
    const main = readFileSync(new URL('../src/main.js', import.meta.url), 'utf8')
    assert.ok(/onSacrifice\(picks, target = 'slot', bookId = BOOK_ORDER\[0\]\)/.test(main),
      "onSacrifice must default target to 'slot' and bookId to BOOK_ORDER[0], so an older caller keeps meaning what it used to")
    assert.ok(/cost = unlockCost\(bookId, target, unlockLevel\(bm, bookId, target\)\)/.test(main),
      'onSacrifice must price the NEXT rung from the ladder — a finished ladder prices null and is refused here rather than by the button being absent')
    assert.ok(/\(bm\.unlocks \?\?= \{\}\)\[target\] = unlockLevel\(bm, bookId, target\) \+ 1/.test(main),
      'onSacrifice must store the new LEVEL, not `true` — writing true would jump a part-bought ladder straight to the top')
    assert.doesNotMatch(main, /meta\.lightThief\s*=\s*true/,
      'onSacrifice must never write the legacy top-level meta.lightThief — an unlock goes to bookMeta(meta,bookId).unlocks[target] only')
  }

  // (e) THE HELPERS SURVIVE AN EMPTY TABLE. Every one of them is called on today's shop screen with
  // a book that has no unlocks at all, so "returns a sane zero" is live behaviour, not a hypothetical
  // — purseSwitchHtml sums unlockMax/unlockLevel over the (empty) id list on every render.
  {
    assert.strictEqual(Object.keys(BOOK_UNLOCKS).length, 0,
      'BOOK_UNLOCKS is expected to be empty since Scavenger was removed — if a row was added back, give it a real behavioural test and update this scenario')
    assert.strictEqual(unlockMax('undertow', 'lightThief'), 0, 'unlockMax must read a removed unlock as 0 rungs, never throw')
    assert.strictEqual(unlockCost('undertow', 'lightThief', 0), null, 'unlockCost must price a removed unlock as null, which is what keeps it out of sacTargets')
    assert.strictEqual(unlockLevel({ unlocks: { lightThief: true } }, 'undertow', 'lightThief'), 0,
      'a save still carrying the old flag must resolve to level 0 — the unlock is gone, and `true` must not read as "owned" against a table that no longer describes it')
    // The card-slot ladder is what the screen sells now, and it must be untouched by all of this.
    assert.ok(SACRIFICE_COSTS.length > 0, 'the card-slot ladder is the only sacrifice target left — an empty one would leave the screen selling nothing')
    assert.deepStrictEqual([...SACRIFICE_COSTS].sort((x, y) => x - y), SACRIFICE_COSTS,
      'a ladder must get more expensive, not less — a cheaper later rung makes the earlier one a trap')
  }

  console.log(`PASS run SC (sacrifice seam): 0 BOOK_UNLOCKS entries, ${withResource.length} of ${chapterIds.length} chapters carry a resource and none declares killRefill, killBase is The Wreck's alone, sim.js reads neither run.killRefill nor meta, sacTargets emits only 'slot' or a real BOOK_UNLOCKS key, onSacrifice prices and stores a LEVEL, and the helpers read a removed unlock as 0/null`)
}
run(runSacrificeSeam)

// ---- Run U: per-chapter runs, weapon pools, chapter unlock (v5.0 task 2) -----------------
// Chapter unlock itself (endRun in main.js) is untestable glue here (no DOM/main.js import) —
// this covers what sim/state own: createRun's chapter snapshot + starter weapon, and
// weaponCandidates/buildLevelUpChoices scoping level-up weapon OFFERS to the run's chapter
// (mods/elements stay global — see the run.chapter doc block in state.js).
function testChapterRuns() {
  // (a) Default chapter is 'body'; starting weapon is CHAPTERS.body.starter (star), level 1.
  {
    const run = createRun(makeMeta())
    assert.strictEqual(run.chapter, 'body', "expected createRun's default chapter to be 'body'")
    assert.strictEqual(run.weapons.length, 1, 'expected exactly one starting weapon')
    assert.strictEqual(run.weapons[0].id, CHAPTERS.body.starter, `expected the body starter (${CHAPTERS.body.starter}), got ${run.weapons[0].id}`)
    assert.strictEqual(run.weapons[0].level, 1, 'expected the starting weapon at level 1')
  }

  // (b) chapter: 'pond' starts with the pond starter (flagella) instead of body's star.
  {
    const run = createRun(makeMeta(), { chapter: 'pond' })
    assert.strictEqual(run.chapter, 'pond', "expected run.chapter === 'pond'")
    assert.strictEqual(run.weapons[0].id, CHAPTERS.pond.starter, `expected the pond starter (${CHAPTERS.pond.starter}), got ${run.weapons[0].id}`)
  }

  // The charged consumable still bumps the CHAPTER'S OWN starter to level 2, not hardcoded star.
  {
    const run = createRun(makeMeta(), { chapter: 'pond', consumables: ['charged'] })
    assert.strictEqual(run.weapons[0].id, CHAPTERS.pond.starter, 'expected charged core to keep the chapter starter id')
    assert.strictEqual(run.weapons[0].level, 2, 'expected charged core to bump the chapter starter to level 2')
  }

  // (b2) The Blank's starter is an ARRAY (config.js), so every run rolls one out of its own pool
  // instead of always handing over the shard. 60 runs x 23 candidates: seeing 4 or fewer distinct
  // ids has probability < 1e-20, so the floor only trips on a starter that stopped rolling.
  {
    const ids = new Set()
    for (let i = 0; i < 60; i++) {
      const run = createRun(makeMeta(), { chapter: 'blank', difficulty: 1 })
      assert.strictEqual(run.weapons.length, 1, 'expected exactly one starting weapon in The Blank')
      assert.ok(CHAPTERS.blank.weapons.includes(run.weapons[0].id),
        `The Blank rolled '${run.weapons[0].id}', which is not in its own weapon pool`)
      ids.add(run.weapons[0].id)
    }
    assert.ok(ids.size >= 5, `expected The Blank's starter to vary across 60 runs, saw ${ids.size} distinct: [${[...ids]}]`)
    console.log(`PASS run U.b2 (the blank rolls its starter): 60 runs -> ${ids.size} distinct starters, all inside its ${CHAPTERS.blank.weapons.length}-weapon pool`)
  }

  // (c) A pond run's level-up pool never offers other-chapter/vaulted weapons (star=body,
  // boomerang=garden, hole/rainbow still vaulted) as 'weapon' cards — only CHAPTERS.pond.weapons
  // can appear. Sampled generously (500 pools x up to 4 cards) to catch any leak.
  {
    const pond = createRun(makeMeta(), { chapter: 'pond' })
    pond.choiceSlots = 4 // more cards per pool -> more chances to catch a leak
    const forbidden = new Set(['star', 'boomerang', 'hole', 'rainbow'])
    let sawWeaponCard = false
    for (let i = 0; i < 500; i++) {
      for (const c of buildLevelUpChoices(pond)) {
        if (c.kind !== 'weapon') continue
        sawWeaponCard = true
        assert(!forbidden.has(c.id), `expected a pond run to never offer '${c.id}' as a weapon card`)
        assert(CHAPTERS.pond.weapons.includes(c.id), `expected every pond weapon card to be a pond native, got '${c.id}'`)
      }
    }
    assert(sawWeaponCard, 'expected at least one weapon card to appear over 500 pond pools')
    console.log('PASS run U.c (pond pool never offers body/vaulted weapons)')
  }

  // (d) A body run's level-up pool never offers mines (a pond native) — the flip side of (c).
  {
    const body = createRun(makeMeta())
    body.choiceSlots = 4
    let sawWeaponCard = false
    for (let i = 0; i < 500; i++) {
      for (const c of buildLevelUpChoices(body)) {
        if (c.kind !== 'weapon') continue
        sawWeaponCard = true
        assert.notStrictEqual(c.id, 'mines', "expected a body run to never offer 'mines' as a weapon card")
        assert(CHAPTERS.body.weapons.includes(c.id), `expected every body weapon card to be a body native, got '${c.id}'`)
      }
    }
    assert(sawWeaponCard, 'expected at least one weapon card to appear over 500 body pools')
    console.log('PASS run U.d (body pool never offers pond weapons)')
  }

  console.log('PASS run U (per-chapter runs + weapon pool filtering): default chapter, pond starter, charged bump, pool filtering both directions')
}

// ---- Run V: chapter behavior flags, drift currents, field obstacles (v5.0 task 3) -------
function testChapterBehaviors() {
  const dt = 1 / 60

  // (a) latch: contact sets the player's movement debuff, and the latch enemy dies (spends
  // itself) instead of dealing normal contact damage.
  {
    const run = createRun(makeMeta())
    run.weapons = []
    run.player.x = 0; run.player.y = 0
    const e = makeStatusEnemy(run, { x: 0, y: 0, hp: 50, speed: 0 })
    e.flags = ['latch']
    run.enemies.push(e)
    const killsBefore = run.kills
    stepSim(run, { x: 0, y: 0 }, dt)
    assert(run.player.slowT > 0, `expected latch contact to set player.slowT, got ${run.player.slowT}`)
    assert(run.kills > killsBefore, 'expected the latch enemy to die on contact')

    // The debuff actually slows movement (not just bookkeeping).
    const slowed = createRun(makeMeta())
    slowed.weapons = []
    slowed.player.x = 0; slowed.player.y = 0
    slowed.player.slowT = LATCH_SLOW_T
    stepSim(slowed, { x: 1, y: 0 }, dt)
    const slowedDist = Math.hypot(slowed.player.x, slowed.player.y)

    const plain = createRun(makeMeta())
    plain.weapons = []
    plain.player.x = 0; plain.player.y = 0
    stepSim(plain, { x: 1, y: 0 }, dt)
    const plainDist = Math.hypot(plain.player.x, plain.player.y)

    assert(slowedDist < plainDist, `expected the latch debuff to slow movement (slowed=${slowedDist}, plain=${plainDist})`)
    console.log(`PASS run V.a (latch): slowT=${run.player.slowT.toFixed(2)} slowedDist=${slowedDist.toFixed(2)} plainDist=${plainDist.toFixed(2)}`)
  }

  // (b) split: death spawns SPLIT_CHILD_COUNT children at reduced hp/radius; children never re-split.
  {
    const run = createRun(makeMeta())
    run.weapons = [{ id: 'star', level: 1 }]
    setElements(run, { fire: 5 })
    run.player.x = 0; run.player.y = 0
    run.player.hp = 1e9; run.player.maxHP = 1e9
    // hp 20: same burn budget as run G.a — see the note there.
    const parent = makeStatusEnemy(run, { x: 100, y: 0, hp: 20, speed: 0 })
    parent.flags = ['split']
    run.enemies.push(parent)

    let hitOnce = false
    for (let i = 0; i < Math.round(2 / dt) && !hitOnce; i++) {
      if (run.phase === 'levelup') { declineLevelUp(run); continue }
      stepSim(run, { x: 0, y: 0 }, dt)
      if (run.events.some((e) => e.type === 'hit')) hitOnce = true
    }
    assert(hitOnce, 'expected the split target to take at least one hit')
    run.weapons = []
    run.bullets = []

    let killed = false
    for (let i = 0; i < Math.round(4 / dt) && !killed; i++) {
      if (run.phase === 'levelup') { declineLevelUp(run); continue }
      stepSim(run, { x: 0, y: 0 }, dt)
      if (run.kills > 0) killed = true
    }
    assert(killed, 'expected the ignite DoT to finish off the split target')

    // BORN BETWEEN STEPS, not mid-step. 63 loops in sim.js walk run.enemies with for...of while
    // dealing damage, and for...of re-reads length every iteration — so a child appended during one
    // of them used to be struck by the very cast that killed its parent. Measured over 3 seeded 300s
    // Shelf runs with the whip alone: 495 of 657 children hit by their own spawning swing, 378 of
    // 526 child deaths in the birth frame. That is the `split` flag inert 72% of the time, and on
    // screen it is three damage numbers inside 20px in one instant.
    assert.strictEqual(run.enemies.filter((e) => e._splitChild).length, 0,
      'a split child must NOT be in run.enemies during the step that spawned it — it would be hittable by the cast that killed its parent')
    assert.strictEqual(run._spawnQueue.length, SPLIT_CHILD_COUNT, 'the children must be queued for the next step')
    stepSim(run, { x: 0, y: 0 }, dt)   // ...and arrive when the next step begins
    // ...and the queue DRAINS. A flush that copies without clearing re-adds the same two children
    // every step forever, which is an unbounded enemy leak that the count below cannot see (it is
    // still correct on the step the flush first runs).
    assert.strictEqual(run._spawnQueue.length, 0, 'flushSpawns must empty the queue, or every child is re-added on every later step')
    const children = run.enemies.filter((e) => e._splitChild)
    assert.strictEqual(children.length, SPLIT_CHILD_COUNT, `expected ${SPLIT_CHILD_COUNT} split children, got ${children.length}`)
    // v6.9.2: rounded, like every enemy HP assignment — a fractional maxHP leaves a sub-1 remainder
    // that dealDamage's integer subtraction can never clear (see roundHP in sim.js).
    const expectedHp = Math.max(1, Math.round(parent.maxHP * SPLIT_HP_FRAC))
    const expectedRadius = parent.radius * SPLIT_RADIUS_FRAC
    // XP scales with the child's health, like every other stat it inherits. A child carrying the
    // parent's FULL xp made a splitter worth 3 kills of xp for 1.9 kills of health — the only
    // enemy in the game whose xp-per-point-of-health is not 1, and it front-loaded its chapters
    // hard enough to be reported from play (The Shelf at level 10.5 by 180s against undergrowth's
    // 8.5, then 5 levels behind by 300s).
    const expectedXp = parent.xp * SPLIT_HP_FRAC
    for (const c of children) {
      assert(Math.abs(c.maxHP - expectedHp) < 1e-6, `expected child maxHP ${expectedHp}, got ${c.maxHP}`)
      assert(Math.abs(c.radius - expectedRadius) < 1e-6, `expected child radius ${expectedRadius}, got ${c.radius}`)
      assert(Math.abs(c.xp - expectedXp) < 1e-6,
        `expected child xp ${expectedXp} (the parent's ${parent.xp} scaled by SPLIT_HP_FRAC), got ${c.xp} — ` +
        `a child worth its parent's whole xp on ${SPLIT_HP_FRAC} of its health is ` +
        `${((1 + SPLIT_CHILD_COUNT) / (1 + SPLIT_CHILD_COUNT * SPLIT_HP_FRAC)).toFixed(2)}x the xp per point of health`)
    }

    // No re-split: isolate one child (drop its sibling so nothing else can be hit), kill it the
    // same way, and confirm no further _splitChild enemies appear (a broken guard adds 2 more).
    const [child, sibling] = children
    run.enemies = run.enemies.filter((e) => e.id !== sibling.id)
    run.player.x = child.x; run.player.y = child.y
    run.weapons = [{ id: 'star', level: 5 }]
    run.events = [] // drain stale 'hit' events from the parent's death so this check is fresh
    let childHit = false
    for (let i = 0; i < Math.round(2 / dt) && !childHit; i++) {
      if (run.phase === 'levelup') { declineLevelUp(run); continue }
      stepSim(run, { x: 0, y: 0 }, dt)
      if (run.events.some((e) => e.type === 'hit')) childHit = true
    }
    assert(childHit, 'expected the split child to take at least one hit')
    run.weapons = []
    run.bullets = []
    let childDead = false
    for (let i = 0; i < Math.round(4 / dt) && !childDead; i++) {
      if (run.phase === 'levelup') { declineLevelUp(run); continue }
      stepSim(run, { x: 0, y: 0 }, dt)
      if (!run.enemies.find((e) => e.id === child.id)) childDead = true
    }
    assert(childDead, 'expected the split child to die from the ignite DoT')
    assert.strictEqual(run.enemies.filter((e) => e._splitChild).length, 0,
      "expected a split child's own death to spawn no further children (no re-split)")
    console.log(`PASS run V.b (split): children=${children.length} hp=${children[0].maxHP.toFixed(1)} radius=${children[0].radius.toFixed(1)}`)
  }

  // (c) dashBurst: displacement over the dash window far exceeds the idle window.
  {
    const run = createRun(makeMeta())
    run.weapons = []
    // ON SCREEN, and on the x axis so the seek direction is a fixed +x for the whole window — the
    // property this block actually needs. It used to be parked at 5000px for that, which stopped
    // working when the dash grew its canCommitFrom gate (v7.x): out there the machine never leaves
    // idle, and the assert below read idleRate === dashRate === full speed. 400 is inside the
    // default headless viewport's half-width (viewW 480 - COMMIT_EDGE_PAD 28 = 452) with room to
    // spare, and far enough that nothing ever contacts. See V.c3 for the off-screen half.
    run.player.x = 400; run.player.y = 0
    const e = makeStatusEnemy(run, { x: 0, y: 0, hp: 1e6, speed: 100 })
    e.flags = ['dashBurst']
    run.enemies.push(e)

    const idleStart = { x: e.x, y: e.y }
    const idleSteps = Math.round(DASH_IDLE_T / dt)
    for (let i = 0; i < idleSteps; i++) stepSim(run, { x: 0, y: 0 }, dt)
    const afterIdle = run.enemies.find((en) => en.id === e.id)
    const idleDist = Math.hypot(afterIdle.x - idleStart.x, afterIdle.y - idleStart.y)

    const dashStart = { x: afterIdle.x, y: afterIdle.y }
    const dashSteps = Math.round(DASH_T / dt)
    for (let i = 0; i < dashSteps; i++) stepSim(run, { x: 0, y: 0 }, dt)
    const afterDash = run.enemies.find((en) => en.id === e.id)
    const dashDist = Math.hypot(afterDash.x - dashStart.x, afterDash.y - dashStart.y)

    const idleRate = idleDist / DASH_IDLE_T
    const dashRate = dashDist / DASH_T
    assert(dashRate > idleRate * 3, `expected dash-phase speed >> idle-phase speed (idleRate=${idleRate.toFixed(1)}, dashRate=${dashRate.toFixed(1)})`)
    console.log(`PASS run V.c (dashBurst): idleRate=${idleRate.toFixed(1)}px/s dashRate=${dashRate.toFixed(1)}px/s`)
  }

  // (c3) dashBurst does NOT commit from off screen, and does not loiter out there either.
  // Owner, 2026-08-16, about The Surf's Sea Roach: "like all other dashers in the game, they should
  // [not] dash on you from outside your screen." diveBomb and pounce got that gate in v6.6.24 on the
  // same complaint about the garden's wasps; dashBurst never did, because it is the one dash machine
  // with NO distance test at all — a pure DASH_IDLE_T timer that fires wherever the body happens to
  // be. Enemies spawn at run.viewRadius + SPAWN_RING, i.e. always off screen, so a fresh dasher
  // could complete its whole wind-up out of sight and arrive already dashing.
  //
  // BOTH HALVES ARE ASSERTED, because fixing only the first would be worse than the bug. Gating the
  // commit while leaving the idle phase at DASH_IDLE_SPEED_MUL (0.4) means the crowd crawls just out
  // of view — the spawn ring is a RADIUS and the gate is a RECTANGLE, so on a phone's short axis
  // that is several seconds of an empty-looking chapter. So: no dash off screen, AND full approach
  // speed while it is out there.
  {
    const run = createRun(makeMeta())
    run.weapons = []
    run.player.x = 5000; run.player.y = 0 // far outside viewW (480) — cannot be on screen
    const e = makeStatusEnemy(run, { x: 0, y: 0, hp: 1e6, speed: 100 })
    e.flags = ['dashBurst']
    run.enemies.push(e)

    // Four full idle periods: on the old code this dashes three times over that window.
    const steps = Math.round((DASH_IDLE_T * 4) / dt)
    const startX = e.x
    let sawDash = false
    for (let i = 0; i < steps; i++) {
      stepSim(run, { x: 0, y: 0 }, dt)
      const cur = run.enemies.find((en) => en.id === e.id)
      if (cur && cur._dashPhase === 'dash') sawDash = true
    }
    const after = run.enemies.find((en) => en.id === e.id)
    assert(!sawDash, 'a dasher must never enter its dash phase while it is off screen')
    // ...and it closed at full speed rather than the 0.4x idle crawl. Compared against the RATE, not
    // a px literal, so the band survives a change to DASH_IDLE_T or to the window length above.
    const rate = (after.x - startX) / (DASH_IDLE_T * 4)
    assert(rate > 90, `an off-screen dasher must walk in at full speed, not the idle crawl (got ${rate.toFixed(1)}px/s of 100)`)
    console.log(`PASS run V.c3 (dashBurst off-screen gate): no dash in ${(DASH_IDLE_T * 4).toFixed(1)}s out of view, closed at ${rate.toFixed(1)}px/s`)
  }

  // (c2) dashBurst COMMITS its heading: a dash must never track a player who sidesteps out of it.
  // V.c above cannot catch this — it parks the player 5000px away, so the seek direction barely
  // moves, which is exactly the one case a homing dash and a committed dash agree on. The dash runs
  // at DASH_SPEED_MUL of the enemy's speed, well over PLAYER.baseSpeed, so if it re-aims there is
  // no counterplay at all: you can neither outrun it nor step out of it.
  {
    const run = createRun(makeMeta())
    run.weapons = []
    run.player.x = 300; run.player.y = 0
    const e = makeStatusEnemy(run, { x: 0, y: 0, hp: 1e6, speed: 100 })
    e.flags = ['dashBurst']
    run.enemies.push(e)
    // walk it through the idle phase so the heading locks onto the player, out at +x
    const idleSteps = Math.round(DASH_IDLE_T / dt) + 1
    for (let i = 0; i < idleSteps; i++) stepSim(run, { x: 0, y: 0 }, dt)
    const mid = run.enemies.find((en) => en.id === e.id)
    assert.strictEqual(mid._dashPhase, 'dash', 'expected the enemy to be mid-dash after the idle phase')

    // now sidestep hard — the player leaves the dash lane entirely
    run.player.x = 0; run.player.y = 400
    const from = { x: mid.x, y: mid.y }
    for (let i = 0; i < Math.round((DASH_T / dt) * 0.6); i++) stepSim(run, { x: 0, y: 0 }, dt)
    const after = run.enemies.find((en) => en.id === e.id)
    const mvx = after.x - from.x, mvy = after.y - from.y
    assert(mvx > 0, `expected the dash to keep flying along its locked +x heading (moved ${mvx.toFixed(1)}px)`)
    const steer = Math.abs(mvy) / Math.max(1e-6, Math.abs(mvx))
    assert(steer < 0.02, `a dash must not steer toward a sidestepping player (|dy|/|dx| = ${steer.toFixed(3)})`)
    console.log(`PASS run V.c2 (dashBurst commits): flew ${mvx.toFixed(0)}px along the locked heading, steered ${(steer * 100).toFixed(1)}% toward the sidestep`)
  }

  // (d) acidPool (elite flag): death leaves a pool that damages a standing player and expires.
  {
    const run = createRun(makeMeta())
    run.weapons = [{ id: 'star', level: 3 }]
    run.player.x = 100; run.player.y = 0
    run.player.hp = 1e9; run.player.maxHP = 1e9
    const e = makeStatusEnemy(run, { x: 100, y: 0, hp: 10, speed: 0, elite: true })
    e.flags = ['acidPool']
    run.enemies.push(e)

    let killed = false
    for (let i = 0; i < Math.round(2 / dt) && !killed; i++) {
      if (run.phase === 'levelup') { declineLevelUp(run); continue }
      stepSim(run, { x: 0, y: 0 }, dt)
      if (run.kills > 0) killed = true
    }
    assert(killed, 'expected the acidPool elite to die')
    assert(run.pools.length > 0, 'expected an acidPool death to leave a pool')
    const pool = run.pools[0]
    assert.strictEqual(pool.r, ACID_R, `expected pool radius ${ACID_R}, got ${pool.r}`)
    assert.strictEqual(pool.dps, ACID_DPS, `expected pool dps ${ACID_DPS}, got ${pool.dps}`)

    const hpBefore = run.player.hp
    let dotHit = false
    for (let i = 0; i < Math.round(1 / dt) && !dotHit; i++) {
      if (run.phase === 'levelup') { declineLevelUp(run); continue }
      stepSim(run, { x: 0, y: 0 }, dt)
      if (run.events.some((ev) => ev.type === 'hurt' && ev.dot)) dotHit = true
    }
    assert(dotHit, 'expected the acid pool to deal at least one dot-flagged hurt event')
    assert(run.player.hp < hpBefore, `expected the acid pool to damage a standing player (before=${hpBefore}, after=${run.player.hp})`)

    for (let i = 0; i < Math.round((ACID_DUR + 0.5) / dt); i++) {
      if (run.phase === 'levelup') { declineLevelUp(run); continue }
      stepSim(run, { x: 0, y: 0 }, dt)
    }
    assert.strictEqual(run.pools.length, 0, 'expected the acid pool to expire')
    console.log('PASS run V.d (acidPool): pool damages standing player and expires')
  }

  // (e) soapTrail (elite flag): drops trail nodes into run.pools periodically while alive.
  {
    const run = createRun(makeMeta())
    run.weapons = []
    run.player.x = 5000; run.player.y = 0 // far away: never contacts, never dies
    const e = makeStatusEnemy(run, { x: 0, y: 0, hp: 1e6, speed: 80, elite: true })
    e.flags = ['soapTrail']
    run.enemies.push(e)

    const steps = Math.round(1.5 / dt)
    for (let i = 0; i < steps; i++) stepSim(run, { x: 0, y: 0 }, dt)
    assert(run.pools.length >= 3, `expected a soapTrail elite to leave >= 3 pool nodes over 1.5s, got ${run.pools.length}`)
    for (const p of run.pools) {
      assert.strictEqual(p.r, SOAP_R, `expected soap pool radius ${SOAP_R}, got ${p.r}`)
      assert.strictEqual(p.t <= SOAP_DUR, true, `expected soap pool duration <= ${SOAP_DUR}, got ${p.t}`)
    }
    console.log(`PASS run V.e (soapTrail): nodes=${run.pools.length}`)
  }

  // (f) currents signature: a stationary pond player drifts, a stationary body player never does.
  //
  // SEEDED, and the threshold is 5 rather than 20. This block drew no seed of its own, so it ran
  // on whatever Math.random state the scenarios before it happened to leave — and the quantity it
  // measures is violently phase-dependent: across 16 seeds the same code drifts 18.1px to 158.9px,
  // and "> 20" fails on 2 of them. It passed only because the full-suite ORDER lands on a phase
  // where it passes, which means any edit anywhere that changes how many randoms get drawn had a
  // ~12% chance of turning this red with nothing wrong. That is the false-red trap CLAUDE.md
  // documents, sitting inside the suite rather than being caused by it, and it is what made
  // running a subset of scenarios impossible.
  //
  // The pathology this guards is "the currents signature does nothing", and its signal is drift
  // EXACTLY 0 — the body arm asserts that on the next line. So the threshold has no reason to sit
  // near the measured range at all: 5 is unreachable by noise (the floor over 16 seeds is 18.1)
  // and still fails completely if currents stop moving the player.
  {
    Math.random = mulberry32(20250815)
    const pond = createRun(makeMeta(), { chapter: 'pond' })
    pond.weapons = []
    pond.player.x = 0; pond.player.y = 0
    const steps = Math.round(3 / dt)
    for (let i = 0; i < steps; i++) stepSim(pond, { x: 0, y: 0 }, dt)
    const pondDrift = Math.hypot(pond.player.x, pond.player.y)

    const body = createRun(makeMeta())
    body.weapons = []
    body.player.x = 0; body.player.y = 0
    for (let i = 0; i < steps; i++) stepSim(body, { x: 0, y: 0 }, dt)
    const bodyDrift = Math.hypot(body.player.x, body.player.y)

    assert(pondDrift > 5, `expected a stationary pond-run player to drift > 5px over 3s, got ${pondDrift.toFixed(1)} — the currents signature is not moving the player at all`)
    assert.strictEqual(bodyDrift, 0, `expected a stationary body-run player to never drift (no signature), got ${bodyDrift}`)
    console.log(`PASS run V.f (currents): pondDrift=${pondDrift.toFixed(1)}px bodyDrift=${bodyDrift.toFixed(1)}px`)
  }

  // (f2) currentForce pure query (v5.2, powers the render visualization): nonzero + continuous for
  // a pond run, {0,0} for a body run, and the applied drift == currentForce * dt (same field).
  {
    const pondF = createRun(makeMeta(), { chapter: 'pond' })
    // nonzero somewhere across a few spread world points (a ~55px/s sine-sum field won't vanish everywhere)
    const pts = [[200, 200], [-400, 900], [1500, -600]]
    const maxMag = Math.max(...pts.map(([x, y]) => { const f = currentForce(pondF, x, y); return Math.hypot(f.fx, f.fy) }))
    assert(maxMag > 1, `expected the pond drift field to be nonzero, got maxMag=${maxMag.toFixed(3)}`)
    // continuity: a 1px step barely changes the force (smooth field, no discontinuities)
    const a = currentForce(pondF, 100, 100)
    const b = currentForce(pondF, 101, 100)
    const jump = Math.hypot(a.fx - b.fx, a.fy - b.fy)
    assert(jump < 1, `expected a continuous field (small step -> small change), got jump=${jump.toFixed(4)}`)

    // body run: no currents signature -> exactly the zero vector everywhere
    const bodyF = createRun(makeMeta())
    const bz = currentForce(bodyF, 300, -200)
    assert.strictEqual(bz.fx, 0, `expected body-run currentForce fx=0, got ${bz.fx}`)
    assert.strictEqual(bz.fy, 0, `expected body-run currentForce fy=0, got ${bz.fy}`)

    // the sim applies exactly this field: a lone player's one-frame drift == currentForce * dt.
    const run = createRun(makeMeta(), { chapter: 'pond' })
    run.weapons = []; run.obstacles = []; run._obstacleSeed = null; run.enemies = []
    run.player.x = 123; run.player.y = -456
    const x0 = run.player.x, y0 = run.player.y
    stepSim(run, { x: 0, y: 0 }, dt) // run.time is advanced by the step; sample the field after so it matches
    const f = currentForce(run, x0, y0)
    const dx = run.player.x - x0, dy = run.player.y - y0
    assert(Math.abs(dx - f.fx * dt) < 1e-6 && Math.abs(dy - f.fy * dt) < 1e-6,
      `expected drift == currentForce*dt, got d=(${dx.toFixed(4)},${dy.toFixed(4)}) vs f*dt=(${(f.fx * dt).toFixed(4)},${(f.fy * dt).toFixed(4)})`)
    console.log(`PASS run V.f2 (currentForce): maxMag=${maxMag.toFixed(1)}px/s continuityJump=${jump.toFixed(4)} bodyZero drift==force*dt`)
  }

  // (g) obstacles STREAM (v5.6.13): present around the spawn, present ANYWHERE the player roams
  // (the old origin-only field left the world beyond 900px empty — "obstacles are only in the
  // beginning zone"), deterministic per run (walk away and back -> the SAME rocks), dropped when
  // far, spawn ring kept clear, no overlaps. Body still has none.
  {
    const pond = createRun(makeMeta(), { chapter: 'pond' })
    stepSim(pond, { x: 0, y: 0 }, dt)
    const nearSpawn = pond.obstacles.length
    assert(nearSpawn > 0, 'expected streamed obstacles around the spawn after one step')
    for (const o of pond.obstacles) {
      assert(Math.hypot(o.x, o.y) >= CHAPTERS.pond.obstacles.minDist - 1e-6,
        `spawn clear ring violated: obstacle at ${Math.hypot(o.x, o.y).toFixed(0)}px from origin`)
    }
    for (let i = 0; i < pond.obstacles.length; i++) {
      for (let j = i + 1; j < pond.obstacles.length; j++) {
        const a = pond.obstacles[i], b = pond.obstacles[j]
        const gap = Math.hypot(a.x - b.x, a.y - b.y) - a.r - b.r
        assert(gap >= -1e-6, `expected no two pond obstacles to overlap, got gap=${gap}`)
      }
    }
    // roam far beyond the old 900px field: obstacles must exist there too
    pond.player.x = 5000; pond.player.y = -3000
    stepSim(pond, { x: 0, y: 0 }, dt)
    const farKey = (o) => `${o.x.toFixed(2)},${o.y.toFixed(2)},${o.r.toFixed(2)}`
    const farOnes = pond.obstacles.filter((o) => Math.hypot(o.x - 5000, o.y + 3000) <= OBSTACLE_STREAM_RADIUS)
    assert(farOnes.length > 0, 'expected obstacles far from the origin — the old field left this empty')
    const snapshot = farOnes.map(farKey).sort().join('|')
    // leave (everything old drops)...
    pond.player.x = 20000; pond.player.y = 20000
    stepSim(pond, { x: 0, y: 0 }, dt)
    assert(pond.obstacles.every((o) => Math.hypot(o.x - 20000, o.y - 20000) <= OBSTACLE_DROP_RADIUS + 1e-6),
      'expected far-behind obstacles to be dropped')
    // ...and come back: the SAME cells regenerate the SAME rocks
    pond.player.x = 5000; pond.player.y = -3000
    stepSim(pond, { x: 0, y: 0 }, dt)
    const again = pond.obstacles.filter((o) => Math.hypot(o.x - 5000, o.y + 3000) <= OBSTACLE_STREAM_RADIUS).map(farKey).sort().join('|')
    assert.strictEqual(again, snapshot, 'expected the same cells to regenerate the same obstacles')

    const body = createRun(makeMeta())
    stepSim(body, { x: 0, y: 0 }, dt)
    assert.strictEqual(body.obstacles.length, 0, 'expected a body run to have no obstacles')

    // Push-out: steer a player straight into a nearby (manually placed) obstacle for 1s.
    const run = createRun(makeMeta(), { chapter: 'pond' })
    run.weapons = []
    run.player.x = 0; run.player.y = 0
    const obstacle = { x: 150, y: 0, r: 40 }
    run.obstacles = [obstacle]; run._obstacleSeed = null // manual field: keep streaming out of it
    const minSep = obstacle.r + PLAYER.radius
    const steps2 = Math.round(1 / dt)
    for (let i = 0; i < steps2; i++) stepSim(run, { x: 1, y: 0 }, dt)
    const dist = Math.hypot(run.player.x - obstacle.x, run.player.y - obstacle.y)
    assert(dist >= minSep - 0.5, `expected the player pushed out of the obstacle (dist=${dist.toFixed(1)}, min=${minSep.toFixed(1)})`)
    console.log(`PASS run V.g (obstacles stream): nearSpawn=${nearSpawn} far=${farOnes.length} deterministic revisit, body=0, pushed dist=${dist.toFixed(1)}`)
  }

  console.log('PASS run V (chapter behavior flags, drift currents, field obstacles): latch, split, dashBurst, acidPool, soapTrail, currents, obstacles')
}

// ---- Run W: new pond weapons — Flagella Whip + Toxin Bloom (v5.0 task 4) -----------------
function testPondWeapons() {
  const dt = 1 / 60

  // (a) the whip aims at the NEAREST enemy (v5.1.2 fix), not the player's move direction: the arc
  // locks onto a near enemy in front (it dies), while a far one beyond range stays untouched even
  // after the near one dies (range check excludes it).
  {
    const run = createRun(makeMeta())
    run.weapons = [{ id: 'flagella', level: MAX_WEAPON_LEVEL }]
    run.mods.spawnMul = 0
    run.player.x = 0; run.player.y = 0
    run.player.hp = 1e9; run.player.maxHP = 1e9
    run.player.facingAngle = 0 // moved +x (kiting away) — no longer where the whip aims
    const ahead = makeStatusEnemy(run, { x: 100, y: 0, hp: 20, speed: 0 })
    const farBehind = makeStatusEnemy(run, { x: -500, y: 0, hp: 1e6, speed: 0 }) // beyond range
    run.enemies.push(ahead, farBehind)

    let sawWhip = false
    for (let i = 0; i < Math.round(1.5 / dt); i++) {
      if (run.phase === 'levelup') { declineLevelUp(run); continue }
      run.player.facingAngle = 0 // pin the (now-irrelevant) move direction
      stepSim(run, { x: 0, y: 0 }, dt)
      if (run.events.some((e) => e.type === 'whip')) sawWhip = true
    }
    assert(!run.enemies.find((e) => e.id === ahead.id), 'expected the near in-front enemy to die to the whip')
    const farNow = run.enemies.find((e) => e.id === farBehind.id)
    assert(farNow && farNow.hp === 1e6, `expected the out-of-range enemy untouched (hp ${farNow && farNow.hp})`)
    // (b) whip event emitted, carrying the render fields.
    assert(sawWhip, 'expected at least one whip event')
    console.log('PASS run W.a/b (whip aims at nearest; out-of-range foe untouched + whip event)')
  }

  // (a1) the sector test is against the enemy's BODY, not its centre — inSector, the same test
  // clawRake/roar/tailLash already used. A foe the fan plainly sweeps, whose CENTRE sits a few px
  // past `range`, used to take nothing; that disagreement between the drawing and the damage is the
  // whole bug this weapon was reported for. Asserted as an EFFECT (hp fell) on a foe placed inside
  // reach but outside a centre test, with a control past reach that must still take nothing — so
  // reverting inSector fails the first assert and widening it without limit fails the second.
  {
    const R = WEAPONS.flagella.levels[MAX_WEAPON_LEVEL - 1].range
    const run = createRun(makeMeta())
    run.weapons = [{ id: 'flagella', level: MAX_WEAPON_LEVEL }]
    run.mods.spawnMul = 0
    run.player.x = 0; run.player.y = 0
    run.player.hp = 1e9; run.player.maxHP = 1e9
    // radius 16 (makeStatusEnemy): clipped is 8px past range and so 8px INSIDE reach; control is
    // 24px past range, clear of reach by 8px. Both dead ahead, so only the radial test separates them.
    const clipped = makeStatusEnemy(run, { x: R + 8, y: 0, hp: 1e6, speed: 0 })
    const control = makeStatusEnemy(run, { x: R + 24, y: 0, hp: 1e6, speed: 0 })
    run.enemies.push(clipped, control)
    for (let i = 0; i < Math.round(1.5 / dt); i++) {
      if (run.phase === 'levelup') { declineLevelUp(run); continue }
      clipped.x = R + 8; control.x = R + 24   // re-pin: the whip knocks back what it hits
      stepSim(run, { x: 0, y: 0 }, dt)
    }
    assert(clipped.hp < 1e6, `expected a foe clipped by the sector edge to be hit (centre ${R + 8} vs range ${R}, radius 16), hp=${clipped.hp}`)
    assert.strictEqual(control.hp, 1e6, `expected a foe past range+radius to stay untouched, hp=${control.hp}`)
    console.log(`PASS run W.a1 (sector tests the BODY): centre ${R + 8}px hit through a ${R}px reach, ${R + 24}px still untouched`)
  }

  // (a2) THE FIX: a lone enemy directly BEHIND a player who moved forward is now HIT, because the
  // whip aims at the nearest enemy rather than the move direction (which would swing the arc away).
  {
    const run = createRun(makeMeta())
    run.weapons = [{ id: 'flagella', level: MAX_WEAPON_LEVEL }]
    run.mods.spawnMul = 0
    run.player.x = 0; run.player.y = 0
    run.player.hp = 1e9; run.player.maxHP = 1e9
    run.player.facingAngle = 0 // faces +x, but the only enemy is behind at -x
    const behind = makeStatusEnemy(run, { x: -100, y: 0, hp: 20, speed: 0 })
    run.enemies.push(behind)
    for (let i = 0; i < Math.round(1.5 / dt); i++) {
      if (run.phase === 'levelup') { declineLevelUp(run); continue }
      run.player.facingAngle = 0
      stepSim(run, { x: 0, y: 0 }, dt)
    }
    assert(!run.enemies.find((e) => e.id === behind.id), 'expected the behind enemy to be hit now the whip aims at nearest')
    console.log('PASS run W.a2 (fix: whip hits an enemy behind the player\'s move direction)')
  }

  // (c) cyclone: every 3rd swing is a full 360°. A never-dying anchor in front keeps the aim locked
  // to +x, so an in-range enemy behind sits OUTSIDE the normal arc and is reached only by cyclone.
  {
    function behindHp(cyclone) {
      const run = createRun(makeMeta())
      run.weapons = [{ id: 'flagella', level: MAX_WEAPON_LEVEL }]
      run.mods.spawnMul = 0
      run.player.x = 0; run.player.y = 0
      run.player.hp = 1e9; run.player.maxHP = 1e9
      if (cyclone) run.weaponMods.flagella.cyclone = 1
      // Anchor (nearest, never dies) pins the aim forward; behind is in range but outside the arc.
      const anchor = makeStatusEnemy(run, { x: 60, y: 0, hp: 1e9, speed: 0 })
      run.enemies.push(anchor)
      const behind = makeStatusEnemy(run, { x: -100, y: 0, hp: 1e6, speed: 0 })
      run.enemies.push(behind)
      // Enough time for well past FLAGELLA_CYCLONE_EVERY swings (rate ~0.58s at max level).
      for (let i = 0; i < Math.round((FLAGELLA_CYCLONE_EVERY + 2) * 0.9 / dt); i++) {
        if (run.phase === 'levelup') { declineLevelUp(run); continue }
        stepSim(run, { x: 0, y: 0 }, dt)
        // v6.2 melee knockback shoves the anchor; re-pin it so the aim stays locked +x (the
        // scenario tests ARC selection, not target drift).
        anchor.x = 60; anchor.y = 0; anchor.kb.x = 0; anchor.kb.y = 0
      }
      return run.enemies.find((e) => e.id === behind.id).hp
    }
    const withCyclone = behindHp(true)
    const without = behindHp(false)
    assert(without === 1e6, `expected no cyclone to never hit the behind enemy (hp ${without})`)
    assert(withCyclone < 1e6, `expected cyclone's 360° swing to hit the behind enemy (hp ${withCyclone})`)
    console.log(`PASS run W.c (cyclone): behind hp with=${withCyclone.toFixed(0)} without=${without.toFixed(0)}`)
  }

  // (d) bloom: the weapon plants a cloud; a hand-placed cloud expands from 0, ticks dot-flagged
  // damage to enemies inside, and expires at dur.
  {
    // d1: the weapon actually plants a cloud on a nearby enemy within castRange.
    const planter = createRun(makeMeta())
    planter.weapons = [{ id: 'bloom', level: 1 }]
    planter.mods.spawnMul = 0
    planter.player.x = 0; planter.player.y = 0
    planter.player.hp = 1e9; planter.player.maxHP = 1e9
    planter.enemies.push(makeStatusEnemy(planter, { x: 100, y: 0, hp: 1e6, speed: 0 }))
    let planted = false
    for (let i = 0; i < Math.round(4 / dt) && !planted; i++) {
      if (planter.phase === 'levelup') { declineLevelUp(planter); continue }
      stepSim(planter, { x: 0, y: 0 }, dt)
      if (planter.blooms.length > 0) planted = true
    }
    assert(planted, 'expected the bloom weapon to plant a cloud within 4s')

    // d2: lifecycle of a hand-placed cloud — grows, ticks dot-flagged damage, expires.
    const run = createRun(makeMeta())
    run.weapons = [] // no re-planting; isolate this one cloud
    run.mods.spawnMul = 0
    run.player.x = 5000; run.player.y = 0 // far from the cloud/enemies (no contact damage)
    run.player.hp = 1e9; run.player.maxHP = 1e9
    const target = makeStatusEnemy(run, { x: 0, y: 0, hp: 1e6, speed: 0 })
    run.enemies.push(target)
    run.blooms.push({ x: 0, y: 0, r: 0, maxR: 90, t: 0, dur: 3, dmgPerTick: 6 })

    let sawDotHit = false
    let grew = false
    const hpBefore = target.hp
    for (let i = 0; i < Math.round(1.5 / dt); i++) {
      stepSim(run, { x: 0, y: 0 }, dt)
      if (run.blooms[0] && run.blooms[0].r > 0) grew = true
      if (run.events.some((e) => e.type === 'hit' && e.dot)) sawDotHit = true
    }
    assert(grew, 'expected the cloud radius to grow from 0')
    assert(sawDotHit, 'expected the bloom to tick dot-flagged hit events')
    assert(target.hp < hpBefore, `expected the bloom to damage an enemy inside it (before=${hpBefore}, after=${target.hp})`)

    // Expiry: step past dur; the cloud is gone (no weapon re-plants).
    for (let i = 0; i < Math.round(3 / dt); i++) stepSim(run, { x: 0, y: 0 }, dt)
    assert.strictEqual(run.blooms.length, 0, 'expected the cloud to expire at dur')
    console.log('PASS run W.d (bloom plants, expands, ticks dot damage, expires)')
  }

  // (e) sporeburst: a foe killed by a (non-mini) cloud emits a mini-cloud; a mini-cloud's own
  // kill emits NOTHING (no chaining).
  {
    // Positive: parent cloud kills an enemy inside -> a _mini cloud appears at SPOREBURST_FRAC size.
    const run = createRun(makeMeta())
    run.weapons = []
    run.mods.spawnMul = 0
    run.weaponMods.bloom.sporeburst = 1
    run.player.x = 5000; run.player.y = 0
    run.player.hp = 1e9; run.player.maxHP = 1e9
    run.enemies.push(makeStatusEnemy(run, { x: 0, y: 0, hp: 5, speed: 0 }))
    run.blooms.push({ x: 0, y: 0, r: 0, maxR: 60, t: 0, dur: 3, dmgPerTick: 100 })
    let miniSeen = null
    for (let i = 0; i < Math.round(1 / dt) && !miniSeen; i++) {
      stepSim(run, { x: 0, y: 0 }, dt)
      miniSeen = run.blooms.find((b) => b._mini)
    }
    assert(miniSeen, 'expected sporeburst to emit a mini-cloud on an in-bloom death')
    assert(Math.abs(miniSeen.maxR - 60 * SPOREBURST_FRAC) < 1e-6, `expected mini maxR ${60 * SPOREBURST_FRAC}, got ${miniSeen.maxR}`)

    // Negative: a _mini cloud that kills an enemy spawns no further cloud (never chains).
    const noChain = createRun(makeMeta())
    noChain.weapons = []
    noChain.mods.spawnMul = 0
    noChain.weaponMods.bloom.sporeburst = 1
    noChain.player.x = 5000; noChain.player.y = 0
    noChain.player.hp = 1e9; noChain.player.maxHP = 1e9
    noChain.enemies.push(makeStatusEnemy(noChain, { x: 0, y: 0, hp: 5, speed: 0 }))
    noChain.blooms.push({ x: 0, y: 0, r: 0, maxR: 40, t: 0, dur: 3, dmgPerTick: 100, _mini: true })
    let maxBlooms = noChain.blooms.length
    for (let i = 0; i < Math.round(1 / dt); i++) {
      stepSim(noChain, { x: 0, y: 0 }, dt)
      maxBlooms = Math.max(maxBlooms, noChain.blooms.length)
    }
    assert.strictEqual(maxBlooms, 1, `expected a mini-cloud kill to spawn no further clouds, saw up to ${maxBlooms}`)
    console.log('PASS run W.e (sporeburst emits a mini-cloud but never chains)')
  }

  // (f) a pond run's mod pool offers ONLY flagella/mines/bloom weapon mods (never a body weapon's).
  {
    const pond = createRun(makeMeta(), { chapter: 'pond' })
    pond.weapons = [{ id: 'flagella', level: 3 }, { id: 'mines', level: 3 }, { id: 'bloom', level: 3 }]
    pond.choiceSlots = 4
    const pondMods = new Set(CHAPTERS.pond.weapons)
    let sawPondMod = false
    for (let i = 0; i < 500; i++) {
      for (const c of buildLevelUpChoices(pond)) {
        if (c.kind !== 'mod') continue
        assert(pondMods.has(c.weapon), `expected only pond weapon mods, got a '${c.weapon}' mod`)
        sawPondMod = true
      }
    }
    assert(sawPondMod, 'expected pond weapon mods to appear over 500 pools')
    console.log('PASS run W.f (pond mod pool offers only pond weapon mods)')
  }

  // (g) mines re-theme is copy-only: the display name is now 'Toxin Cysts'.
  {
    assert.strictEqual(WEAPONS.mines.name, 'Toxin Cysts', `expected mines re-themed to 'Toxin Cysts', got '${WEAPONS.mines.name}'`)
    console.log('PASS run W.g (mines re-themed to Toxin Cysts)')
  }

  // Balance band (run P style, kill-time on a realistic ring — not an immortal-ring DPS race,
  // per the v4.4 lesson): a fully-leveled flagella + 2 mods must clear the ring no slower than
  // 3.5x the pond-median kill-time of the OTHER pond natives (mines, bloom).
  {
    function measureTTK(weaponId, applyMods) {
      const run = createRun(makeMeta()) // body chapter: no currents/obstacles skewing the clear
      run.weapons = [{ id: weaponId, level: MAX_WEAPON_LEVEL }]
      run.mods.spawnMul = 0
      run.player.hp = 1e9; run.player.maxHP = 1e9
      if (applyMods) applyMods(run)
      const N = 14, radius = 150, hp = 50
      for (let i = 0; i < N; i++) {
        const a = (i / N) * Math.PI * 2
        run.enemies.push(makeStatusEnemy(run, { x: Math.cos(a) * radius, y: Math.sin(a) * radius, hp, speed: 45 }))
      }
      let t = 0
      const cap = 60
      for (let i = 0; i < Math.round(cap / dt); i++) {
        if (run.phase === 'levelup') { declineLevelUp(run); continue }
        t += dt
        run.player.x = 0; run.player.y = 0        // pin: enemies converge on the origin
        stepSim(run, { x: 0, y: 0 }, dt)          // whip auto-aims at the nearest of the ring
        if (run.enemies.length === 0) return t
      }
      return cap
    }
    const flagellaTTK = measureTTK('flagella', (r) => { r.weaponMods.flagella.heavyLash = 0.40; r.weaponMods.flagella.barbed = 0.50 })
    const minesTTK = measureTTK('mines', (r) => { r.weaponMods.mines.heavyCharge = 0.20; r.weaponMods.mines.bigBoom = 0.20 })
    const bloomTTK = measureTTK('bloom', (r) => { r.weaponMods.bloom.virulent = 0.35; r.weaponMods.bloom.quickCast = 0.25 })
    const others = [minesTTK, bloomTTK].sort((a, b) => a - b)
    const median = others[Math.floor(others.length / 2)]
    assert(flagellaTTK < 60, `expected flagella to clear the ring within the cap, got ${flagellaTTK.toFixed(1)}s`)
    assert(flagellaTTK <= median * 3.5, `expected flagella kill-time within 3.5x the pond-median (flagella=${flagellaTTK.toFixed(1)}s, median=${median.toFixed(1)}s, ratio=${(flagellaTTK / median).toFixed(2)})`)
    console.log(`PASS run W (balance band): flagellaTTK=${flagellaTTK.toFixed(1)}s minesTTK=${minesTTK.toFixed(1)}s bloomTTK=${bloomTTK.toFixed(1)}s ratio=${(flagellaTTK / median).toFixed(2)}x`)
  }
}

// ---- Run X: garden roster flags + Stinger/Pheromone Lure weapons (v5.3) ------------------
function testGarden() {
  const dt = 1 / 60

  // (a) trailFollow: a garden ant standing near a live pheromone node moves faster (accelerates on
  // the trail) than the same ant with no node nearby — gated on the chapter's pheromones signature.
  {
    function antDist(withTrail) {
      const run = createRun(makeMeta(), { chapter: 'garden' })
      run.weapons = []; run.obstacles = []; run._obstacleSeed = null; run.mods.spawnMul = 0
      run.player.x = 2000; run.player.y = 0 // far away: a fixed +x seek direction, never contacts
      const e = makeStatusEnemy(run, { x: 0, y: 0, hp: 1e6, speed: 100 })
      e.flags = ['trailFollow']
      run.enemies.push(e)
      if (withTrail) run.trails.push({ x: 0, y: 0, t: 10 }) // node right on the ant (stays in range)
      const x0 = e.x
      for (let i = 0; i < Math.round(0.3 / dt); i++) stepSim(run, { x: 0, y: 0 }, dt)
      return run.enemies.find((en) => en.id === e.id).x - x0
    }
    const withT = antDist(true)
    const without = antDist(false)
    assert(withT > without * 1.2, `expected an ant on a pheromone trail to accelerate (withTrail=${withT.toFixed(1)}, without=${without.toFixed(1)})`)
    console.log(`PASS run X.a (trailFollow): withTrail=${withT.toFixed(1)}px without=${without.toFixed(1)}px`)
  }

  // (b) diveBomb: a wasp's displacement during its dive window far exceeds its hover window.
  {
    const run = createRun(makeMeta(), { chapter: 'garden' })
    run.weapons = []; run.obstacles = []; run._obstacleSeed = null; run.mods.spawnMul = 0
    run.player.x = 3000; run.player.y = 0
    run.player.hp = 1e9; run.player.maxHP = 1e9
    const e = makeStatusEnemy(run, { x: 3000 - DIVE_STANDOFF, y: 0, hp: 1e6, speed: 120 }) // starts at standoff
    e.flags = ['diveBomb']
    run.enemies.push(e)

    const hoverStart = { x: e.x, y: e.y }
    for (let i = 0; i < Math.round(DIVE_HOVER_T / dt); i++) stepSim(run, { x: 0, y: 0 }, dt)
    const afterHover = run.enemies.find((en) => en.id === e.id)
    const hoverDist = Math.hypot(afterHover.x - hoverStart.x, afterHover.y - hoverStart.y)

    // advance through the telegraph pause into the dive
    for (let i = 0; i < Math.round((DIVE_TELEGRAPH_T + 0.02) / dt); i++) stepSim(run, { x: 0, y: 0 }, dt)
    const diveStart = { x: afterHover.x, y: afterHover.y }
    for (let i = 0; i < Math.round(DIVE_T / dt); i++) stepSim(run, { x: 0, y: 0 }, dt)
    const afterDive = run.enemies.find((en) => en.id === e.id)
    const diveDist = Math.hypot(afterDive.x - diveStart.x, afterDive.y - diveStart.y)

    assert(hoverDist < 10, `expected a wasp at standoff to hover nearly in place, moved ${hoverDist.toFixed(1)}px`)
    assert(diveDist > hoverDist * 3 && diveDist > 80, `expected the dive window to displace far more than hover (hover=${hoverDist.toFixed(1)}, dive=${diveDist.toFixed(1)})`)
    console.log(`PASS run X.b (diveBomb): hoverDist=${hoverDist.toFixed(1)}px diveDist=${diveDist.toFixed(1)}px`)
  }

  // (c) webZone: a player standing in a web moves slower; the web slow STACKS with the latch debuff
  // via a MIN (the stronger of the two multipliers wins — LATCH_SLOW_MUL < WEB_SLOW_MUL, so both == latch).
  {
    function moveDist(setup) {
      const run = createRun(makeMeta(), { chapter: 'garden' })
      run.weapons = []; run.obstacles = []; run._obstacleSeed = null; run.mods.spawnMul = 0
      run.player.x = 0; run.player.y = 0
      setup(run)
      stepSim(run, { x: 1, y: 0 }, dt)
      return Math.hypot(run.player.x, run.player.y)
    }
    const plain = moveDist(() => {})
    const web = moveDist((r) => r.webs.push({ x: 0, y: 0, r: 72, t: 10 }))
    const latch = moveDist((r) => { r.player.slowT = LATCH_SLOW_T })
    const both = moveDist((r) => { r.webs.push({ x: 0, y: 0, r: 72, t: 10 }); r.player.slowT = LATCH_SLOW_T })
    assert(web < plain, `expected a web to slow the player (web=${web.toFixed(2)}, plain=${plain.toFixed(2)})`)
    assert(both <= web + 1e-9, `expected latch+web to be no faster than web alone (min-mul stack): both=${both.toFixed(3)}, web=${web.toFixed(3)}`)
    assert(Math.abs(both - latch) < 1e-6, `expected latch+web == latch alone (the stronger slow wins): both=${both.toFixed(3)}, latch=${latch.toFixed(3)}`)
    console.log(`PASS run X.c (webZone): plain=${plain.toFixed(2)} web=${web.toFixed(2)} latch=${latch.toFixed(2)} both=${both.toFixed(2)}`)
  }

  // (d) run.strips, the generic contract: a marked strip deals NO damage during its fuse
  // (telegraph), then dot-flagged damage to the player standing inside it once the fuse elapses.
  // v6.6.14: this used to be the garden's pesticide spray, which no longer exists — its elite
  // drives a visible mower now (run MW). The Blank's erasure bands, eraser wakes and immuneMemory
  // residue are the only remaining producers, so the fixture uses their numbers and the scenario
  // covers what it actually still guards. Kept in place rather than appended: it rewrites an
  // existing scenario's fixture without adding or removing a seeded draw.
  {
    const run = createRun(makeMeta(), { chapter: 'garden' })
    run.weapons = []; run.obstacles = []; run._obstacleSeed = null; run.mods.spawnMul = 0
    run.player.x = 0; run.player.y = 0
    run.player.hp = 1e9; run.player.maxHP = 1e9
    const FUSE = 0.9, ACTIVE = 1.2
    run.strips.push({ x: 0, y: 0, angle: 0, len: 340, w: 92, fuse: FUSE, t: ACTIVE, dps: 10, look: 'erase' })

    let hurtDuringFuse = false
    for (let i = 0; i < Math.round((FUSE - 0.05) / dt); i++) {
      stepSim(run, { x: 0, y: 0 }, dt)
      if (run.events.some((e) => e.type === 'hurt')) hurtDuringFuse = true
    }
    assert(!hurtDuringFuse, 'expected no damage during the strip telegraph (fuse)')
    const hpAfterFuse = run.player.hp

    let dotHurt = false
    for (let i = 0; i < Math.round((FUSE + 0.6) / dt) && !dotHurt; i++) {
      stepSim(run, { x: 0, y: 0 }, dt)
      if (run.events.some((e) => e.type === 'hurt' && e.dot)) dotHurt = true
    }
    assert(dotHurt, 'expected the live strip to deal dot-flagged damage after the fuse')
    assert(run.player.hp < hpAfterFuse, `expected the live strip to damage the standing player (before=${hpAfterFuse}, after=${run.player.hp})`)
    console.log('PASS run X.d (strips): no damage during fuse, dot damage after')
  }

  // (e) Pheromone Lure: an enemy inside a lure's aggro radius paths toward the DECOY (away from the
  // player), and the lure's burst damages a nearby enemy + emits an explode event (+ stickyScent web).
  {
    function enemyDx(withLure) {
      const run = createRun(makeMeta(), { chapter: 'garden' })
      run.weapons = []; run.obstacles = []; run._obstacleSeed = null; run.mods.spawnMul = 0
      run.player.x = 500; run.player.y = 0 // player to the +x; the lure sits to the -x
      const e = makeStatusEnemy(run, { x: 0, y: 0, hp: 1e6, speed: 100 })
      run.enemies.push(e)
      if (withLure) run.lures.push({ x: -150, y: 0, t: 0, dur: 10, aggro: 250, burstR: 100, burstDmg: 10, sticky: false })
      const x0 = e.x
      for (let i = 0; i < Math.round(0.3 / dt); i++) stepSim(run, { x: 0, y: 0 }, dt)
      return run.enemies.find((en) => en.id === e.id).x - x0
    }
    const lured = enemyDx(true)
    const normal = enemyDx(false)
    assert(normal > 0, `expected an un-lured enemy to move toward the player (+x), got dx=${normal.toFixed(1)}`)
    assert(lured < 0, `expected a lured enemy to move toward the decoy (-x), got dx=${lured.toFixed(1)}`)

    // burst: a decoy expiring damages a nearby enemy and emits an explode; stickyScent leaves a web.
    const burst = createRun(makeMeta(), { chapter: 'garden' })
    burst.weapons = []; burst.obstacles = []; burst._obstacleSeed = null; burst.mods.spawnMul = 0
    burst.player.x = 3000; burst.player.y = 0; burst.player.hp = 1e9; burst.player.maxHP = 1e9
    const victim = makeStatusEnemy(burst, { x: 0, y: 0, hp: 500, speed: 0 })
    burst.enemies.push(victim)
    burst.lures.push({ x: 0, y: 0, t: 0, dur: 0.25, aggro: 10, burstR: 100, burstDmg: 200, sticky: true })
    const hp0 = victim.hp
    let exploded = false
    for (let i = 0; i < Math.round(0.6 / dt); i++) {
      stepSim(burst, { x: 0, y: 0 }, dt)
      if (burst.events.some((ev) => ev.type === 'explode')) exploded = true
    }
    assert(exploded, 'expected a lure burst to emit an explode event')
    assert(victim.hp < hp0, `expected the lure burst to damage the nearby enemy (before=${hp0}, after=${victim.hp})`)
    assert(burst.webs.length > 0, 'expected stickyScent to leave a web slow zone on burst')
    console.log(`PASS run X.e (lure): luredDx=${lured.toFixed(1)} normalDx=${normal.toFixed(1)}, burst damages + sticky web`)
  }

  // (f) Stinger: a volley fires `count` needles in a tight cone (each tagged 'stinger', pierce off
  // the levels[] ladder); the hive mod makes every 4th volley fire in all directions (reaching a
  // foe outside the cone).
  // v6.6.26: this used to assert a hard-coded pierce of 1. That 1 WAS the bug (see the note on
  // WEAPONS.stinger.levels), so the assertion now tracks the ladder — run SN owns the ladder's
  // values and the mod that raises it.
  {
    const run = createRun(makeMeta(), { chapter: 'garden' })
    run.weapons = [{ id: 'stinger', level: MAX_WEAPON_LEVEL }]
    run.obstacles = []; run._obstacleSeed = null; run.mods.spawnMul = 0
    run.player.x = 0; run.player.y = 0; run.player.hp = 1e9; run.player.maxHP = 1e9
    run.enemies.push(makeStatusEnemy(run, { x: 200, y: 0, hp: 1e6, speed: 0 }))
    const lvl = WEAPONS.stinger.levels[MAX_WEAPON_LEVEL - 1]
    let volley = []
    for (let i = 0; i < Math.round(2 / dt) && volley.length === 0; i++) {
      stepSim(run, { x: 0, y: 0 }, dt)
      if (run.bullets.length > 0) volley = run.bullets.slice()
    }
    assert.strictEqual(volley.length, lvl.count, `expected a volley of ${lvl.count} needles, got ${volley.length}`)
    for (const b of volley) {
      const ang = Math.atan2(b.vy, b.vx)
      assert(Math.abs(ang) <= lvl.spread + 1e-6, `expected each needle within the ±${lvl.spread} cone, got angle ${ang.toFixed(3)}`)
      assert.strictEqual(b.pierce, lvl.pierce, `expected needle pierce ${lvl.pierce} from the levels[] ladder`)
      assert.strictEqual(b.weapon, 'stinger', 'expected the needle tagged weapon:stinger')
    }
    console.log(`PASS run X.f1 (stinger cone): ${volley.length} needles within ±${lvl.spread}rad, pierce ${lvl.pierce}`)

    // hive: an enemy well outside the cone (pinned there by a nearer anchor) is only reached by the
    // every-4th-volley all-directions burst.
    function behindHp(hive) {
      const r = createRun(makeMeta(), { chapter: 'garden' })
      r.weapons = [{ id: 'stinger', level: MAX_WEAPON_LEVEL }]
      r.obstacles = []; r._obstacleSeed = null; r.mods.spawnMul = 0
      r.player.x = 0; r.player.y = 0; r.player.hp = 1e9; r.player.maxHP = 1e9
      if (hive) r.weaponMods.stinger.hive = 1
      r.enemies.push(makeStatusEnemy(r, { x: 80, y: 0, hp: 1e9, speed: 0 })) // anchor: nearest, pins aim +x
      const behind = makeStatusEnemy(r, { x: -140, y: 0, hp: 1e6, speed: 0 })
      behind.radius = 100 // big enough that an all-directions needle passing left reaches it
      r.enemies.push(behind)
      for (let i = 0; i < Math.round((STINGER_HIVE_EVERY + 2) * 0.7 / dt); i++) stepSim(r, { x: 0, y: 0 }, dt)
      return r.enemies.find((e) => e.id === behind.id).hp
    }
    const withHive = behindHp(true)
    const without = behindHp(false)
    assert(without === 1e6, `expected no hive to never reach the behind enemy (hp ${without})`)
    assert(withHive < 1e6, `expected hive's all-directions volley to reach the behind enemy (hp ${withHive})`)
    console.log(`PASS run X.f2 (hive): behind hp with=${withHive.toFixed(0)} without=${without.toFixed(0)}`)
  }

  // (g) A garden run's level-up pool offers ONLY its natives (boomerang/stinger/lure) as weapon
  // AND mod cards — the flip side of run U.c / run W.f, extended to the garden pool.
  {
    const allowed = new Set(CHAPTERS.garden.weapons)
    const garden = createRun(makeMeta(), { chapter: 'garden' })
    garden.choiceSlots = 4
    let sawWeapon = false
    for (let i = 0; i < 500; i++) {
      for (const c of buildLevelUpChoices(garden)) {
        if (c.kind !== 'weapon') continue
        sawWeapon = true
        assert(allowed.has(c.id), `expected a garden run to only offer its natives, got weapon '${c.id}'`)
      }
    }
    assert(sawWeapon, 'expected at least one weapon card over 500 garden pools')

    const g2 = createRun(makeMeta(), { chapter: 'garden' })
    g2.weapons = [{ id: 'boomerang', level: 3 }, { id: 'stinger', level: 3 }, { id: 'lure', level: 3 }]
    g2.choiceSlots = 4
    let sawMod = false
    for (let i = 0; i < 500; i++) {
      for (const c of buildLevelUpChoices(g2)) {
        if (c.kind !== 'mod') continue
        assert(allowed.has(c.weapon), `expected only garden weapon mods, got a '${c.weapon}' mod`)
        sawMod = true
      }
    }
    assert(sawMod, 'expected garden weapon mods to appear over 500 pools')
    console.log('PASS run X.g (garden pool offers only boomerang/stinger/lure weapons + mods)')
  }

  // (h) garden sits after pond in the arc.
  {
    assert(CHAPTER_ORDER.includes('garden'), 'expected garden in CHAPTER_ORDER')
    assert.strictEqual(nextChapter('pond'), 'garden', "expected nextChapter('pond') === 'garden'")
    console.log('PASS run X.h (garden in arc)')
  }

  // Balance band (run W style): a fully-leveled Stinger + 2 mods clears a realistic converging ring
  // no slower than 3.5x the garden-median kill-time of the other natives (Leaf Blade, Pheromone Lure).
  {
    function measureTTK(weaponId, applyMods) {
      const run = createRun(makeMeta()) // body chapter: no garden obstacles/pheromones skewing the clear
      run.weapons = [{ id: weaponId, level: MAX_WEAPON_LEVEL }]
      run.mods.spawnMul = 0
      run.player.hp = 1e9; run.player.maxHP = 1e9
      if (applyMods) applyMods(run)
      const N = 14, radius = 150, hp = 50
      for (let i = 0; i < N; i++) {
        const a = (i / N) * Math.PI * 2
        run.enemies.push(makeStatusEnemy(run, { x: Math.cos(a) * radius, y: Math.sin(a) * radius, hp, speed: 45 }))
      }
      let t = 0
      const cap = 60
      for (let i = 0; i < Math.round(cap / dt); i++) {
        if (run.phase === 'levelup') { declineLevelUp(run); continue }
        t += dt
        run.player.x = 0; run.player.y = 0 // pin: enemies converge on the origin
        stepSim(run, { x: 0, y: 0 }, dt)
        if (run.enemies.length === 0) return t
      }
      return cap
    }
    const leafTTK = measureTTK('boomerang', (r) => { r.weaponMods.boomerang.heavyBlade = 0.20; r.weaponMods.boomerang.longThrow = 0.20 })
    const stingerTTK = measureTTK('stinger', (r) => { r.weaponMods.stinger.sharper = 0.25; r.weaponMods.stinger.volley = 2 })
    const lureTTK = measureTTK('lure', (r) => { r.weaponMods.lure.bigBurst = 0.30; r.weaponMods.lure.widerTaunt = 0.30 })
    const others = [leafTTK, lureTTK].sort((a, b) => a - b)
    const median = others[Math.floor(others.length / 2)]
    assert(stingerTTK < 60, `expected stinger to clear the ring within the cap, got ${stingerTTK.toFixed(1)}s`)
    assert(stingerTTK <= median * 3.5, `expected stinger kill-time within 3.5x the garden-median (stinger=${stingerTTK.toFixed(1)}s, median=${median.toFixed(1)}s, ratio=${(stingerTTK / median).toFixed(2)})`)
    console.log(`PASS run X (balance band): leafTTK=${leafTTK.toFixed(1)}s stingerTTK=${stingerTTK.toFixed(1)}s lureTTK=${lureTTK.toFixed(1)}s ratio=${(stingerTTK / median).toFixed(2)}x`)
  }
}

// ---- Run Y: v5.4 behavior flags (undergrowth/city/skies/beyond rosters) ------------------
// One focused check per flag that carries phase state, in run V/X's idiom: drive the machine for a
// known window and assert the phase it should be in actually behaves differently from its neighbour.
function testV54Flags() {
  const dt = 1 / 60

  // Spawns one flagged enemy into a quiet run (no spawns, no weapons, immortal player) so the only
  // thing moving is the machine under test. `at` is its distance from the player along -x.
  function flagRun(chapter, flags, { at = 300, speed = 100, hp = 1e6, elite = false } = {}) {
    const run = createRun(makeMeta(), { chapter })
    run.weapons = []; run.obstacles = []; run._obstacleSeed = null; run.mods.spawnMul = 0
    run.player.x = 0; run.player.y = 0
    run.player.hp = 1e9; run.player.maxHP = 1e9
    const e = makeStatusEnemy(run, { x: -at, y: 0, hp, speed, elite })
    e.flags = flags
    run.enemies.push(e)
    return { run, e }
  }
  // Displacement of `e` over `seconds` of stepping.
  function moved(run, e, seconds) {
    const x0 = e.x, y0 = e.y
    for (let i = 0; i < Math.round(seconds / dt); i++) stepSim(run, { x: 0, y: 0 }, dt)
    return Math.hypot(e.x - x0, e.y - y0)
  }

  // (a) pounce: a cat inside POUNCE_RANGE stops dead for the aim telegraph, then leaps far — and
  // the 'land' window that follows is a punish window (frozen AND unable to deal contact damage).
  {
    const { run, e } = flagRun('undergrowth', ['pounce'], { at: POUNCE_RANGE - 40 })
    stepSim(run, { x: 0, y: 0 }, dt) // first step: in range -> 'aim'
    assert.strictEqual(e._pounceState, 'aim', `expected a cat in range to enter 'aim', got '${e._pounceState}'`)
    const aimDist = moved(run, e, POUNCE_AIM_T - 0.05)
    const leapDist = moved(run, e, POUNCE_LEAP_T + 0.1) // +0.1: past the leap, into the land window
    assert(aimDist < 1, `expected the aim telegraph to be a dead stop, moved ${aimDist.toFixed(2)}px`)
    assert(leapDist > 100, `expected the leap to cover ground, moved ${leapDist.toFixed(1)}px`)
    assert.strictEqual(e._pounceState, 'land', `expected 'land' after the leap, got '${e._pounceState}'`)

    // land: parked on top of the player, it still can't hurt them (that's the free-hits window).
    e.x = run.player.x; e.y = run.player.y
    run.player.invuln = 0
    const hp0 = run.player.hp
    for (let i = 0; i < Math.round((POUNCE_LAND_T - 0.05) / dt); i++) stepSim(run, { x: 0, y: 0 }, dt)
    assert.strictEqual(run.player.hp, hp0, 'expected a landed cat to deal no contact damage')
    console.log(`PASS run Y.a (pounce): aim=${aimDist.toFixed(2)}px leap=${leapDist.toFixed(1)}px, land deals no contact damage`)
  }

  // (b) aerialStrike: v6.3 DELETES AERIAL_UNTOUCHABLE — the flag's new home (city's patrol drone)
  // is a ranged chapter, so a circling enemy is an ordinary, killable target now (damageImmune
  // drops its aerial branch entirely). The state-machine timing itself is untouched: it circles
  // for AERIAL_CIRCLE_T, then marks, then strikes — assert that shape still holds.
  //
  // Uses 'wave' (a centered, EXPANDING ring nova) rather than 'star' (a ballistic bolt aimed at
  // the target's position AT FIRE TIME, never re-aimed): against a fast circular orbiter that is a
  // CONSTANT, deterministic miss (a fixed lag angle every shot), not a flake. wave's ring is
  // centered on the player and grows every cast, so it sweeps through AERIAL_RADIUS regardless of
  // the drone's angle on the circle.
  {
    const run = createRun(makeMeta(), { chapter: 'undergrowth' })
    run.weapons = [{ id: 'wave', level: MAX_WEAPON_LEVEL }]
    run.weaponTimers.wave = 0 // force the first cast on frame 1 instead of waiting a full interval
    run.obstacles = []; run._obstacleSeed = null; run.mods.spawnMul = 0; run.traps = []
    run.player.x = 0; run.player.y = 0; run.player.hp = 1e9; run.player.maxHP = 1e9
    const owl = makeStatusEnemy(run, { x: 100, y: 0, hp: 1e6, speed: 100 })
    owl.flags = ['aerialStrike']
    run.enemies.push(owl)

    for (let i = 0; i < Math.round((AERIAL_CIRCLE_T - 0.1) / dt); i++) {
      if (run.phase === 'levelup') { declineLevelUp(run); continue }
      stepSim(run, { x: 0, y: 0 }, dt)
    }
    assert.strictEqual(owl._airState, 'circle', `expected the owl still circling, got '${owl._airState}'`)
    assert(owl.hp < 1e6, `expected a circling drone to TAKE damage now that AERIAL_UNTOUCHABLE is gone, hp=${owl.hp}`)

    // ...through mark and into the strike, where it's still fightable (it never regains immunity).
    for (let i = 0; i < Math.round((AERIAL_MARK_T + AERIAL_STRIKE_T + 0.4) / dt); i++) {
      if (run.phase === 'levelup') { declineLevelUp(run); continue }
      stepSim(run, { x: 0, y: 0 }, dt)
    }
    assert(owl.hp < 1e6, `expected a marking/striking drone to still be hittable, hp=${owl.hp}`)
    console.log(`PASS run Y.b (aerialStrike): circling drones are killable now (hp=${owl.hp.toFixed(0)})`)
  }

  // (b2) 'climb' is the owl's PUNISH window: hittable, but still harmless — the ONE special
  // contact rule left standing after v6.3 deletes AERIAL_UNTOUCHABLE (Y.b above: 'circle'/'mark'/
  // 'strike' are now ordinary, ungated both ways). contactHarmless keeps this clause
  // UNCONDITIONALLY (the `AERIAL_UNTOUCHABLE &&` guard is gone, but the clause itself survives):
  // it's peeling away and its strike already had its hit, so a second free hit on the way out
  // would just punish the player for standing their ground — the same shape as pounce's 'land'
  // and lineCharge's 'stall'. Pre-v6.3 this used to be the ONLY window an owl could be killed in
  // at all (circling was fully immune too); measured over a 180s standing run back then: 56/57/
  // 51/56/63 owls alive at the end before this fix, 13/15/11/15/10 after.
  {
    const run = createRun(makeMeta(), { chapter: 'undergrowth' })
    run.weapons = [{ id: 'star', level: MAX_WEAPON_LEVEL }]
    run.obstacles = []; run._obstacleSeed = null; run.mods.spawnMul = 0; run.traps = []
    run.player.x = 0; run.player.y = 0; run.player.hp = 1e9; run.player.maxHP = 1e9
    const owl = makeStatusEnemy(run, { x: 100, y: 0, hp: 1e6, speed: 100 })
    owl.flags = ['aerialStrike']
    run.enemies.push(owl)
    // fly it all the way round to 'climb'
    const toClimb = Math.round((AERIAL_CIRCLE_T + AERIAL_MARK_T + AERIAL_STRIKE_T + 0.05) / dt)
    for (let i = 0; i < toClimb; i++) {
      if (run.phase === 'levelup') { declineLevelUp(run); continue }
      stepSim(run, { x: 0, y: 0 }, dt)
    }
    assert.strictEqual(owl._airState, 'climb', `expected the owl climbing, got '${owl._airState}'`)

    // hittable on the way out...
    owl.hp = 1e6
    owl.x = run.player.x; owl.y = run.player.y
    const hpBefore = owl.hp
    const pHp0 = run.player.hp
    run.player.invuln = 0
    for (let i = 0; i < 20; i++) {
      if (run.phase === 'levelup') { declineLevelUp(run); continue }
      stepSim(run, { x: 0, y: 0 }, dt)
      owl.x = run.player.x; owl.y = run.player.y // pin it on top of the player
    }
    assert(owl.hp < hpBefore, `a climbing owl must be hittable — this is the punish window (hp=${owl.hp})`)
    // ...but still can't hurt you: its strike already had its hit.
    assert.strictEqual(run.player.hp, pHp0, 'a climbing owl must deal NO contact damage')
    console.log(`PASS run Y.b2 (aerialStrike climb): punish window — owl took ${(hpBefore - owl.hp).toFixed(0)} dmg while climbing, dealt 0`)
  }

  // (c) lineCharge: a vacuum lines up, stops for the lock telegraph, then charges much further.
  {
    const { run, e } = flagRun('city', ['lineCharge'], { at: LINE_CHARGE_RANGE - 40 })
    run._laneAcc = 1e6 // park the traffic signature: this case is about the flag alone
    stepSim(run, { x: 0, y: 0 }, dt)
    assert.strictEqual(e._chargeState, 'lock', `expected a vacuum in range to 'lock', got '${e._chargeState}'`)
    const lockDist = moved(run, e, LINE_CHARGE_LOCK_T - 0.05)
    const chargeDist = moved(run, e, LINE_CHARGE_T + 0.1) // +0.1: past the charge, into the stall
    assert(lockDist < 1, `expected the lock telegraph to be a dead stop, moved ${lockDist.toFixed(2)}px`)
    assert(chargeDist > lockDist * 10 && chargeDist > 200, `expected the charge to be a rush (lock=${lockDist.toFixed(1)}, charge=${chargeDist.toFixed(1)})`)
    assert.strictEqual(e._chargeState, 'stall', `expected 'stall' after the charge, got '${e._chargeState}'`)
    console.log(`PASS run Y.c (lineCharge): lock=${lockDist.toFixed(2)}px charge=${chargeDist.toFixed(1)}px`)
  }

  // (d) spawner: a van elite disgorges the chapter's 'fast' archetype through the normal spawn
  // path — non-elite, correctly skinned — and never pushes past MAX_ALIVE.
  {
    const { run, e } = flagRun('city', ['spawner'], { at: 400, elite: true })
    run._laneAcc = 1e6
    const before = run.enemies.length
    for (let i = 0; i < Math.round((SPAWNER_INTERVAL + 0.2) / dt); i++) stepSim(run, { x: 0, y: 0 }, dt)
    const spawned = run.enemies.filter((en) => en.id !== e.id)
    assert.strictEqual(run.enemies.length - before, SPAWNER_COUNT, `expected ${SPAWNER_COUNT} spawns, got ${run.enemies.length - before}`)
    for (const s of spawned) {
      assert.strictEqual(s.elite, false, 'expected spawned minions to never be elites')
      // The van disgorges the chapter's SPAWNER_ARCHETYPE through the normal spawnEnemy path, so it
      // hands it that archetype's spawn TYPE (see ARCHETYPE_TYPE in config.js).
      // NOTE (pre-existing, v5.0, deliberately not fixed here): spawnEnemy maps the spawn type BACK
      // to an archetype with `ARCHETYPE_TYPE[type]` — but ARCHETYPE_TYPE is keyed by ARCHETYPE, not
      // type, so the lookup misses for drone/wisp and every 'fast' roster entry falls back to the
      // 'normal' skin. That's why this asserts the type (what the spawner controls) rather than
      // rosterId. Repairing the lookup would re-roll every shipped chapter's roster distribution.
      assert.strictEqual(s.type, ARCHETYPE_TYPE[SPAWNER_ARCHETYPE], `expected the chapter's '${SPAWNER_ARCHETYPE}' archetype spawn type, got '${s.type}'`)
      assert(Math.hypot(s.x - e.x, s.y - e.y) <= SPAWNER_SCATTER + 1e-6, 'expected minions scattered around the van')
    }
    assert(run.events.some((ev) => ev.type === 'explode'), 'expected each spawn point to pop an explode event')
    console.log(`PASS run Y.d (spawner): ${spawned.length} × type '${spawned[0].type}' (non-elite) around the van`)
  }

  // (e) strafe: a jet banks out to its standoff, holds still for a TELEGRAPH, then flies a straight
  // pass — the run window covers far more ground than the bank, and it ends up PAST the player.
  //
  // v5.9.1: the telegraph is new, and it is the point of this test now. The user reported jets were
  // "not avoidable when they cross the screen": bank ended and the jet was instantly on you at
  // STRAFE_RUN_SPEED_MUL (4.5x) with no tell at all. The wind-up is what makes the pass dodgeable,
  // so assert it exists, that the jet HOLDS POSITION through it (a telegraph that drifts is a lie
  // about where the pass lands), and that it announces itself so render can draw the line.
  {
    const { run, e } = flagRun('skies', ['strafe'], { at: 500 })
    const bankDist = moved(run, e, STRAFE_BANK_T)
    assert.strictEqual(e._strafeState, 'telegraph', `expected 'telegraph' after the bank, got '${e._strafeState}'`)
    assert(run.events.some((ev) => ev.type === 'strafeLock'), 'expected the lock to announce itself for render')

    const telegraphDist = moved(run, e, STRAFE_TELEGRAPH_T)
    assert(telegraphDist < 1, `expected the jet to hold still through the telegraph, moved ${telegraphDist.toFixed(1)}px`)
    // one more frame to cross the boundary: the state flips on `_strafeT <= 0`, and stepping
    // exactly STRAFE_TELEGRAPH_T lands ON zero, where float accumulation decides the winner.
    stepSim(run, { x: 0, y: 0 }, dt)
    assert.strictEqual(e._strafeState, 'run', `expected 'run' after the telegraph, got '${e._strafeState}'`)

    // the wind-up has to buy enough time to actually step out of the lane, or it is decoration.
    const dodgePx = PLAYER.baseSpeed * STRAFE_TELEGRAPH_T
    assert(dodgePx > e.radius * 2, `expected the telegraph to buy a real dodge, only ${dodgePx.toFixed(0)}px`)

    const runDist = moved(run, e, STRAFE_RUN_T)
    assert(runDist > bankDist * 2, `expected the strafing run to outpace the bank (bank=${bankDist.toFixed(1)}, run=${runDist.toFixed(1)})`)
    console.log(`PASS run Y.e (strafe): bank=${bankDist.toFixed(1)}px telegraph=hold(${dodgePx.toFixed(0)}px dodge window) run=${runDist.toFixed(1)}px`)
  }

  // (f) missileVolley: a helicopter holds its standoff and fires MISSILE_COUNT run.enemyShots per
  // volley; a missile that reaches the player damages the PLAYER (and nothing else).
  {
    const { run } = flagRun('skies', ['missileVolley'], { at: 300 })
    for (let i = 0; i < Math.round((MISSILE_INTERVAL + 0.6) / dt); i++) stepSim(run, { x: 0, y: 0 }, dt)
    assert(run.enemyShots.length >= MISSILE_COUNT, `expected a volley of ${MISSILE_COUNT} missiles, got ${run.enemyShots.length}`)

    const hit = createRun(makeMeta(), { chapter: 'skies' })
    hit.weapons = []; hit.obstacles = []; hit._obstacleSeed = null; hit.mods.spawnMul = 0
    hit.player.x = 0; hit.player.y = 0; hit.player.hp = 1e9; hit.player.maxHP = 1e9; hit.player.invuln = 0
    const victim = makeStatusEnemy(hit, { x: 0, y: 0, hp: 1e6, speed: 0 })
    hit.enemies.push(victim)
    hit.enemyShots.push({ x: 40, y: 0, vx: -240, vy: 0, r: MISSILE_R, dmg: MISSILE_DMG, life: 4, turnRate: 1.6 })
    const hp0 = hit.player.hp
    let exploded = false
    for (let i = 0; i < Math.round(0.5 / dt); i++) {
      stepSim(hit, { x: 0, y: 0 }, dt)
      if (hit.events.some((ev) => ev.type === 'explode')) exploded = true
    }
    assert(hit.player.hp < hp0, 'expected a missile to damage the player')
    assert(exploded, 'expected a missile impact to emit an explode event')
    assert.strictEqual(victim.hp, 1e6, 'expected an enemy missile to never damage enemies')
    assert.strictEqual(hit.enemyShots.length, 0, 'expected the missile consumed on impact')
    console.log('PASS run Y.f (missileVolley): volley fired, missile hurts the player only')

    // v5.6.15 invariants — the skies was reported "impossible" and both of these were violated:
    // (1) a missile must be OUTRUNNABLE (its own comment always claimed running was the
    //     counterplay, but SPEED was 240 vs the player's 220); (2) the helicopter's standoff must
    //     sit inside the chapter starter's reach, or the common spawn is unkillable and
    //     accumulates into a missile hell (217 alive at t=180 — the owl bug at chapter scale).
    assert(MISSILE_SPEED < PLAYER.baseSpeed,
      `a missile (${MISSILE_SPEED}) must be slower than the player (${PLAYER.baseSpeed}) — outrunning is the stated counterplay`)
    assert(MISSILE_STANDOFF < WEAPONS.roar.levels[0].range,
      `the helicopter standoff (${MISSILE_STANDOFF}) must sit inside the skies starter's L1 reach (${WEAPONS.roar.levels[0].range})`)
  }

  // (g) artillery: a tank column shells the player's PREDICTED position (velocity × ARTILLERY_LEAD)
  // into run.bombs — the shared volatile-bomb array, so the blast damages BOTH sides. Elites shell
  // wider (ARTILLERY_ELITE_RADIUS). v5.7.5: only while within ARTILLERY_FIRE_RANGE, and never past
  // SHELL_MAX_LIVE live telegraphs — so the tank sits AHEAD of the +x-running player (at: -300 →
  // x=+300) to stay in range for the full interval.
  {
    const { run } = flagRun('skies', ['artillery'], { at: -300, speed: 20 })
    run._bombardAcc = 1e6 // park the bombardment signature: this case is about the flag's own shells
    // Break on the FIRING frame: the shell is pushed after stepPlayerMovement, so the player's
    // position/velocity at the end of that frame are exactly the ones it aimed with.
    for (let i = 0; i < Math.round((ARTILLERY_INTERVAL + 0.5) / dt) && run.bombs.length === 0; i++) {
      stepSim(run, { x: 1, y: 0 }, dt)
    }
    const shell = run.bombs.find((b) => b.radius === ARTILLERY_RADIUS)
    assert(shell, `expected an artillery shell of radius ${ARTILLERY_RADIUS}, got ${run.bombs.map((b) => b.radius)}`)
    const lead = shell.x - run.player.x
    assert(Math.abs(lead - run.player.vx * ARTILLERY_LEAD) < 1e-6,
      `expected the shell led by vx*${ARTILLERY_LEAD} (=${(run.player.vx * ARTILLERY_LEAD).toFixed(1)}), got ${lead.toFixed(1)}`)
    assert(lead > 0, 'expected the shell aimed AHEAD of a player moving +x')

    // v7.22: `at` was 600 — inside ARTILLERY_FIRE_RANGE but OUTSIDE the 480px half-view, which the
    // new visibility gate (below) correctly refuses. This case is about the elite's wider RADIUS,
    // so park it where it can see the player and the radius is the only thing under test.
    const el = flagRun('skies', ['artillery'], { at: 300, speed: 20, elite: true })
    el.run._bombardAcc = 1e6 // park the bombardment signature: this is about the elite's own shells
    for (let i = 0; i < Math.round(2.0 / dt); i++) stepSim(el.run, { x: 0, y: 0 }, dt)
    assert(el.run.bombs.some((b) => b.radius === ARTILLERY_ELITE_RADIUS), 'expected an AA elite to shell with the wider elite radius')

    // v5.7.5 range gate: a tank parked beyond ARTILLERY_FIRE_RANGE never fires, however long it waits.
    const far = flagRun('skies', ['artillery'], { at: ARTILLERY_FIRE_RANGE + 200, speed: 0 })
    far.run._bombardAcc = 1e6
    for (let i = 0; i < Math.round((ARTILLERY_INTERVAL + 1.0) / dt); i++) stepSim(far.run, { x: 0, y: 0 }, dt)
    assert.strictEqual(far.run.bombs.length, 0, `expected an out-of-range tank to hold fire, got ${far.run.bombs.length} shells`)

    // v7.22 VISIBILITY gate (owner: "tanks are shooting at me from outside the screen"). The radial
    // gate cannot express the phone: ARTILLERY_FIRE_RANGE is 640 and a portrait phone's horizontal
    // half-view is ~195, so a tank 400px to the SIDE was in range and off the edge of the screen.
    // Same viewport-rectangle rule v6.6.24 gave the wasps, applied to shells. Both halves matter —
    // an over-tight gate that silenced tanks everywhere would pass the first assert alone.
    const PHONE = { viewW: 195, viewH: 375, viewRadius: Math.hypot(390, 750) / 2 }
    const shellsFrom = (dx, dy) => {
      const { run: r } = flagRun('skies', ['artillery'], { at: 0, speed: 0 })
      Object.assign(r, PHONE)
      r._bombardAcc = 1e6
      r.enemies[0].x = dx; r.enemies[0].y = dy
      for (let i = 0; i < Math.round((ARTILLERY_INTERVAL + 1.0) / dt); i++) {
        r.enemies[0].x = dx; r.enemies[0].y = dy // speed 0 still drifts on separation; re-pin it
        stepSim(r, { x: 0, y: 0 }, dt)
      }
      return r.bombs.length
    }
    const sideDist = Math.hypot(400, 0)
    assert(sideDist < ARTILLERY_FIRE_RANGE, `this case is only meaningful inside the radial gate (${sideDist} vs ${ARTILLERY_FIRE_RANGE})`)
    assert.strictEqual(shellsFrom(400, 0), 0,
      `a tank 400px to the side of a ${PHONE.viewW * 2}px-wide phone screen is NOT on screen and must hold fire, got ${shellsFrom(400, 0)} shells`)
    const onScreen = shellsFrom(150, 0)
    assert(onScreen > 0, 'a tank 150px away is plainly on screen and must still shell — the gate must not silence artillery outright')

    // v5.7.5 live cap: with SHELL_MAX_LIVE telegraphs already up, neither artillery nor the
    // bombardment signature adds another (the barrage backstop).
    const cap = flagRun('skies', ['artillery'], { at: 300, speed: 0 })
    for (let i = 0; i < SHELL_MAX_LIVE; i++) cap.run.bombs.push({ x: 9000, y: 9000, radius: 1, fuse: 99, duration: 99, dmg: 0 })
    for (let i = 0; i < Math.round((ARTILLERY_INTERVAL + 1.0) / dt); i++) stepSim(cap.run, { x: 0, y: 0 }, dt)
    assert.strictEqual(cap.run.bombs.length, SHELL_MAX_LIVE, `expected the shell cap to hold at ${SHELL_MAX_LIVE}, got ${cap.run.bombs.length}`)

    console.log(`PASS run Y.g (artillery): shell led ${lead.toFixed(1)}px ahead; elites shell wider; range gate + ${SHELL_MAX_LIVE}-shell cap hold`)
  }

  // (h) flyover (v6.9, city's pigeon): buildings are not terrain to a bird. It is ONLY that — same
  // speed, same seek — so the check is a matched pair walking the same line into the same wall.
  // This replaces the `blink` scenario: that flag was retired after two attempts to make a
  // crawl-then-burst mover read as anything but teleporting (see config.js's retirement note).
  {
    const wall = { x: -300, y: 0, r: 70, _cell: 'test', kind: 'rock', rot: 0 }
    function walkIntoWall(flags) {
      const { run, e } = flagRun('city', flags, { at: 460, speed: 120 })
      run.obstacles = [{ ...wall }]
      run._obstacleSeed = null
      for (let i = 0; i < Math.round(4 / dt); i++) {
        run.obstacles = [{ ...wall }]   // streamObstacles would otherwise drop/rebuild the field
        stepSim(run, { x: 0, y: 0 }, dt)
      }
      return Math.hypot(e.x - run.player.x, e.y - run.player.y)
    }
    const bird = walkIntoWall(['flyover'])
    const walker = walkIntoWall([])
    assert(bird < walker - 20, `expected a flyover enemy to cross the obstacle a walker is held up by (bird ${bird.toFixed(0)}px vs walker ${walker.toFixed(0)}px from the player)`)
    console.log(`PASS run Y.h (flyover): the bird crossed the building and closed to ${bird.toFixed(0)}px; the same enemy without the flag stalled at ${walker.toFixed(0)}px`)
  }

  // (i) phase: a ghosted flicker takes NO damage and deals none; a solid one is an ordinary enemy.
  {
    const run = createRun(makeMeta(), { chapter: 'beyond' })
    run.weapons = [{ id: 'star', level: MAX_WEAPON_LEVEL }]
    run.obstacles = []; run._obstacleSeed = null; run.wells = []; run.mods.spawnMul = 0
    run.player.x = 0; run.player.y = 0; run.player.hp = 1e9; run.player.maxHP = 1e9
    const e = makeStatusEnemy(run, { x: 120, y: 0, hp: 1e6, speed: 0 })
    e.flags = ['phase']
    run.enemies.push(e)

    stepSim(run, { x: 0, y: 0 }, dt)
    e._phaseSolid = false; e._phaseT = PHASE_SOLID_T // force the ghost window
    const ghostHp0 = e.hp
    for (let i = 0; i < Math.round(0.8 / dt); i++) {
      if (run.phase === 'levelup') { declineLevelUp(run); continue }
      stepSim(run, { x: 0, y: 0 }, dt)
      e._phaseSolid = false // pin the window open for the measurement
    }
    assert.strictEqual(e.hp, ghostHp0, `expected a ghosted flicker to take no damage, hp ${ghostHp0} -> ${e.hp}`)

    e._phaseSolid = true
    for (let i = 0; i < Math.round(0.8 / dt); i++) {
      if (run.phase === 'levelup') { declineLevelUp(run); continue }
      stepSim(run, { x: 0, y: 0 }, dt)
      e._phaseSolid = true
    }
    assert(e.hp < ghostHp0, `expected a solid flicker to take damage, hp=${e.hp}`)

    // Le Large (The Shelf): its starter is a nova ring on the player and its tank is the phasing
    // moon jelly. stepNovas skipped only `_dead`, so a ghosted jelly was SHOVED by a ring that
    // could not hurt it — and was added to `n.hit`, burning its one hit on the window where the
    // damage was refused. Both halves are asserted; the second is the silent one.
    e._phaseSolid = false; e._phaseT = PHASE_SOLID_T
    e.kb.x = 0; e.kb.y = 0
    const hpBefore = e.hp
    const nova = { x: e.x, y: e.y, r: 0, maxR: 400, dmg: 1e6, knockback: 900, fear: 0, life: NOVA_LIFE, hit: new Set() }
    run.novas.push(nova)
    for (let i = 0; i < Math.round(0.3 / dt); i++) {
      if (run.phase === 'levelup') { declineLevelUp(run); continue }
      stepSim(run, { x: 0, y: 0 }, dt)
      e._phaseSolid = false
    }
    const kb = Math.hypot(e.kb.x, e.kb.y)
    assert(kb < 1, `expected a ghosted flicker to take no shove from a nova ring, kb=${kb.toFixed(1)}`)
    assert(!nova.hit.has(e.id), 'expected the ring not to spend its one hit on a ghost it could not damage')
    assert.strictEqual(e.hp, hpBefore, `expected the ring to deal no damage to a ghost, hp ${hpBefore} -> ${e.hp}`)
    console.log(`PASS run Y.i (phase): ghost immune (hp=${ghostHp0}), solid hittable, and a nova ring neither shoved it (kb=${kb.toFixed(1)}) nor consumed its hit`)
  }

  // (j) pullBeam: a UFO's beam drags the player in and ticks dot damage — but at PULL_BEAM_FORCE
  // (< PLAYER.baseSpeed), so walking away still nets outward movement. That's the whole design.
  {
    // v5.18: 'city', not 'beyond' — same reason as the flag cases above. Beyond is a lane now,
    // so its player advances up-screen every frame and cannot "stand still" for a drag test. The
    // lane's own y-axis rule for this beam (it drags sideways only there) is asserted in run CF.
    const { run, e } = flagRun('city', ['pullBeam'], { at: -200, speed: 0, elite: true }) // UFO at +200
    run.wells = []
    e.x = 200; e.y = 0
    let dragged = false
    let dotHurt = false
    for (let i = 0; i < Math.round((PULL_BEAM_INTERVAL + 0.5) / dt); i++) {
      const x0 = run.player.x
      stepSim(run, { x: 0, y: 0 }, dt)
      if (run.player.x > x0 + 1e-9) dragged = true
      if (run.events.some((ev) => ev.type === 'hurt' && ev.dot)) dotHurt = true
    }
    assert(dragged, 'expected an open abduction beam to drag a standing player toward the UFO')
    assert(dotHurt, 'expected an open abduction beam to tick dot-flagged damage')
    assert(Math.hypot(run.player.x - e.x, run.player.y - e.y) <= PULL_BEAM_RANGE, 'expected the drag to have happened in range')

    // Walk out: input away from the UFO beats the beam, since PULL_BEAM_FORCE < PLAYER.baseSpeed.
    const x1 = run.player.x
    for (let i = 0; i < Math.round(0.5 / dt); i++) stepSim(run, { x: -1, y: 0 }, dt)
    assert(run.player.x < x1, `expected the player to out-walk the beam (${x1.toFixed(1)} -> ${run.player.x.toFixed(1)})`)
    assert(PULL_BEAM_FORCE < PLAYER.baseSpeed, 'expected PULL_BEAM_FORCE under the player base speed by design')
    console.log(`PASS run Y.j (pullBeam): drags + ticks, and a walking player still escapes (${PULL_BEAM_FORCE} < ${PLAYER.baseSpeed} px/s)`)
  }

  // (k) flashlightCone: an exterminator elite's cone ENRAGES other enemies (faster + harder contact)
  // and damages NOTHING itself — no hit, no hurt, ever.
  {
    const run = createRun(makeMeta(), { chapter: 'undergrowth' })
    run.weapons = []; run.obstacles = []; run._obstacleSeed = null; run.traps = []; run.mods.spawnMul = 0
    run.player.x = 0; run.player.y = 0; run.player.hp = 1e9; run.player.maxHP = 1e9
    const elite = makeStatusEnemy(run, { x: -300, y: 0, hp: 1e6, speed: 0, elite: true })
    elite.flags = ['flashlightCone']
    const rat = makeStatusEnemy(run, { x: -200, y: 0, hp: 1e6, speed: 100 }) // between the elite and the player
    rat.flags = []
    run.enemies.push(elite, rat)

    for (let i = 0; i < Math.round(0.2 / dt); i++) stepSim(run, { x: 0, y: 0 }, dt)
    assert(rat.enrageT > 0, `expected a rat in the cone to be enraged, enrageT=${rat.enrageT}`)
    assert(Math.abs(rat.enrageT - FLASHLIGHT_ENRAGE_T) < 0.02, `expected enrageT refreshed to ${FLASHLIGHT_ENRAGE_T}, got ${rat.enrageT}`)
    assert(typeof elite._coneAngle === 'number', 'expected the elite to expose _coneAngle for render')
    assert(!run.events.some((ev) => ev.type === 'hit' || ev.type === 'hurt'), 'expected the cone itself to damage NOTHING')

    // The enrage is real: an enraged rat closes faster than a plain one over the same window.
    function ratDx(enraged) {
      const r = createRun(makeMeta(), { chapter: 'undergrowth' })
      r.weapons = []; r.obstacles = []; r._obstacleSeed = null; r.traps = []; r.mods.spawnMul = 0
      r.player.x = 2000; r.player.y = 0
      const en = makeStatusEnemy(r, { x: 0, y: 0, hp: 1e6, speed: 100 })
      en.flags = []
      if (enraged) en.enrageT = 10
      r.enemies.push(en)
      for (let i = 0; i < Math.round(0.3 / dt); i++) stepSim(r, { x: 0, y: 0 }, dt)
      return en.x
    }
    const fast = ratDx(true), plain = ratDx(false)
    assert(Math.abs(fast / plain - FLASHLIGHT_SPEED_MUL) < 0.01, `expected an enraged rat at ${FLASHLIGHT_SPEED_MUL}x speed, got ${(fast / plain).toFixed(3)}x`)
    console.log(`PASS run Y.k (flashlightCone): enrages at ${(fast / plain).toFixed(2)}x speed, damages nothing`)
  }

  console.log('PASS run Y (v5.4 behavior flags): pounce, aerialStrike, lineCharge, spawner, strafe, missileVolley, artillery, flyover, phase, pullBeam, flashlightCone')
}

// ---- Run Z: v5.4 signature mechanics (predators/traffic/bombardment/gravity) --------------
function testV54Signatures() {
  const dt = 1 / 60

  // (a) predators: v6.5 — the trap field STREAMS around the player (sim.js streamTraps, no longer
  // seeded once at createRun, which went dead the moment a run walked away from the origin), and
  // an armed trap damages BOTH sides — the player AND enemies — then re-arms. Damaging both IS the
  // mechanic.
  {
    const seeded = createRun(makeMeta(), { chapter: 'undergrowth' })
    seeded.mods.spawnMul = 0 // isolate the streaming assertion from spawn/enemy noise
    stepSim(seeded, { x: 0, y: 0 }, dt) // one step: streamTraps runs right after streamEddies
    assert(seeded.traps.length > 0, 'expected the streamed field to materialize traps around the origin')
    const minDist = CHAPTERS.undergrowth.signature.traps.minDist
    for (const tr of seeded.traps) {
      assert(Math.hypot(tr.x, tr.y) >= minDist, `expected traps >= ${minDist}px from the origin, got ${Math.hypot(tr.x, tr.y).toFixed(1)}`)
      assert(Math.hypot(tr.x - seeded.player.x, tr.y - seeded.player.y) <= OBSTACLE_STREAM_RADIUS,
        `expected a materialized trap within OBSTACLE_STREAM_RADIUS, got ${Math.hypot(tr.x - seeded.player.x, tr.y - seeded.player.y).toFixed(1)}`)
      assert.strictEqual(tr.armed, true, 'expected a freshly streamed trap armed')
      assert.strictEqual(tr.r, SNAP_TRAP_R, `expected trap radius ${SNAP_TRAP_R}, got ${tr.r}`)
    }
    // Other chapters never stream one (the array exists and stays empty).
    const city = createRun(makeMeta(), { chapter: 'city' })
    city.mods.spawnMul = 0
    stepSim(city, { x: 0, y: 0 }, dt)
    assert.strictEqual(city.traps.length, 0, 'expected a non-predators chapter to stream no traps')

    // Player side: standing on an armed trap springs it, hurts, and puts it on cooldown.
    // Hand-placed (_obstacleSeed null, no _cell) — streamTraps no-ops so this trap stays exactly
    // as placed, isolated from the streaming field above.
    const run = createRun(makeMeta(), { chapter: 'undergrowth' })
    run.weapons = []; run.obstacles = []; run._obstacleSeed = null; run.mods.spawnMul = 0
    run.player.x = 0; run.player.y = 0; run.player.hp = 500; run.player.maxHP = 500; run.player.invuln = 0
    run.traps = [{ x: 0, y: 0, r: SNAP_TRAP_R, armed: true, rearmAt: 0 }]
    const hp0 = run.player.hp
    stepSim(run, { x: 0, y: 0 }, dt)
    assert(run.player.hp < hp0, `expected a snap trap to damage the player (${hp0} -> ${run.player.hp})`)
    assert.strictEqual(run.traps[0].armed, false, 'expected a sprung trap to disarm')
    assert.strictEqual(run.traps[0].rearmAt, run.time + SNAP_TRAP_REARM,
      `expected rearmAt ${run.time + SNAP_TRAP_REARM}, got ${run.traps[0].rearmAt}`)
    assert(run.events.some((ev) => ev.type === 'explode'), 'expected a sprung trap to emit an explode event')

    // ...and it re-arms rather than expiring (permanent furniture) once run.time passes rearmAt.
    for (let i = 0; i < Math.round((SNAP_TRAP_REARM + 0.1) / dt); i++) {
      run.player.invuln = 1e9 // hold the player harmless so it re-arms instead of instantly re-springing
      stepSim(run, { x: 0, y: 0 }, dt)
    }
    assert.strictEqual(run.traps.length, 1, 'expected a trap to never expire')
    assert.strictEqual(run.traps[0].armed, true, 'expected a sprung trap to re-arm after SNAP_TRAP_REARM')

    // Enemy side (the kite mechanic): the same trap damages an enemy that walks onto it, scaled by
    // hpScale(run.time) — negligible this early (rounds away), but the formula is exercised.
    const kite = createRun(makeMeta(), { chapter: 'undergrowth' })
    kite.weapons = []; kite.obstacles = []; kite._obstacleSeed = null; kite.mods.spawnMul = 0
    kite.player.x = 5000; kite.player.y = 0; kite.player.hp = 1e9; kite.player.maxHP = 1e9
    const e = makeStatusEnemy(kite, { x: 0, y: 0, hp: 500, speed: 0 })
    kite.enemies.push(e)
    kite.traps = [{ x: 0, y: 0, r: SNAP_TRAP_R, armed: true, rearmAt: 0 }]
    stepSim(kite, { x: 0, y: 0 }, dt)
    const expectedDmg = Math.round(SNAP_TRAP_DMG * hpScale(kite.time))
    assert.strictEqual(e.hp, 500 - expectedDmg, `expected the trap to deal ${expectedDmg} to the enemy, hp=${e.hp}`)
    assert.strictEqual(kite.traps[0].armed, false, 'expected the enemy to spring the trap too')
    console.log(`PASS run Z.a (predators): ${seeded.traps.length} traps streamed around the origin, snaps on BOTH sides, re-arms`)
  }

  // (b) traffic: 'warn' is a harmless telegraph; the 'sweep' vehicle damages BOTH sides + knocks back.
  {
    function laneRun() {
      const run = createRun(makeMeta(), { chapter: 'city' })
      run.weapons = []; run.obstacles = []; run._obstacleSeed = null; run.mods.spawnMul = 0
      run._laneAcc = 1e6 // park the roller: this case drives one hand-placed lane
      run.player.x = 0; run.player.y = 0; run.player.hp = 1e9; run.player.maxHP = 1e9; run.player.invuln = 0
      run.lanes = [{
        x: 0, y: 0, angle: 0, len: TRAFFIC_LEN, w: TRAFFIC_W,
        phase: 'warn', t: TRAFFIC_WARN, carT: 0, dmg: TRAFFIC_DMG, hitIds: new Set(),
      }]
      return run
    }
    const warn = laneRun()
    // In the lane, but well clear of the player — otherwise its own CONTACT damage, not the lane,
    // is what the "telegraph is harmless" assertion would be measuring.
    const victimW = makeStatusEnemy(warn, { x: 300, y: 0, hp: 1e6, speed: 0 })
    victimW.flags = []
    warn.enemies.push(victimW)
    for (let i = 0; i < Math.round((TRAFFIC_WARN - 0.05) / dt); i++) stepSim(warn, { x: 0, y: 0 }, dt)
    assert.strictEqual(warn.player.hp, 1e9, 'expected the lane telegraph to damage nobody')
    assert.strictEqual(victimW.hp, 1e6, 'expected the lane telegraph to damage no enemies either')
    assert.strictEqual(warn.lanes[0].phase, 'warn', 'expected the lane still telegraphing')

    const sweep = laneRun()
    const victim = makeStatusEnemy(sweep, { x: 300, y: 0, hp: 1e6, speed: 0 })
    victim.flags = []
    sweep.enemies.push(victim)
    const hp0 = sweep.player.hp
    for (let i = 0; i < Math.round((TRAFFIC_WARN + TRAFFIC_SWEEP + 0.1) / dt); i++) stepSim(sweep, { x: 0, y: 0 }, dt)
    assert(sweep.player.hp < hp0, `expected the car to flatten the player (${hp0} -> ${sweep.player.hp})`)
    assert(victim.hp < 1e6, `expected the car to flatten enemies too (BOTH sides), hp=${victim.hp}`)
    assert(victim.x > 301, `expected the car to knock the enemy along the lane (+x), moved to ${victim.x.toFixed(1)}px`)
    assert.strictEqual(sweep.lanes.length, 0, 'expected the lane removed once the sweep ends')

    // v6.9.3 (owner: "car one shots drones. it should do 50% hp damage"). The TRAFFIC_SQUASH
    // roadkill list is GONE: a drone takes the same share of its own max hp as anything else, and
    // an elite of the same species takes it too. What this pins is that there is exactly ONE rule
    // left — the thing the old list quietly made untrue for four rosterIds.
    const frac = laneRun()
    frac.lanes[0].enemyFrac = TRAFFIC_ENEMY_HP_FRAC
    const mk = (x, rosterId, elite) => {
      const e = makeStatusEnemy(frac, { x, y: 0, hp: 1e6, speed: 0 })
      e.flags = []; e.rosterId = rosterId; e.elite = elite; e.maxHP = 1e6
      frac.enemies.push(e)
      return e
    }
    const drone = mk(300, 'ratDrone', false)
    const pigeon = mk(200, 'pigeon', false)       // v6.10.3 roadkill
    const rat = mk(150, 'rat', false)             // v6.10.3 roadkill
    const eliteDrone = mk(-300, 'ratDrone', true)
    const elitePigeon = mk(-150, 'pigeon', true)  // elites are exempt from roadkill
    const tank = mk(-200, 'vacuum', false)
    for (let i = 0; i < Math.round((TRAFFIC_WARN + TRAFFIC_SWEEP + 0.1) / dt); i++) stepSim(frac, { x: 0, y: 0 }, dt)
    // The FRACTION rule still governs everything that is not light street life. This is the half of
    // the contract that v6.9.3 was reported about ("car one shots drones") — drones must survive.
    for (const [name, e] of [['drone', drone], ['elite drone', eliteDrone], ['vacuum', tank], ['elite pigeon', elitePigeon]]) {
      const took = 1e6 - e.hp
      assert(Math.abs(took - 1e6 * TRAFFIC_ENEMY_HP_FRAC) < 1,
        `expected the van to take ${TRAFFIC_ENEMY_HP_FRAC * 100}% of the ${name}'s max hp, took ${took}`)
      assert(!e._dead, `expected the ${name} to SURVIVE one pass at full health`)
    }
    // v6.10.3 (owner: "cars should 1 shot birds and rats always"): the light street life does not.
    for (const [name, e] of [['pigeon', pigeon], ['rat', rat]]) {
      assert(e._dead, `expected the van to kill the ${name} outright, hp=${e.hp}`)
    }

    // The signature actually rolls lanes on its own in a city run (capped by signature.lanes).
    const auto = createRun(makeMeta(), { chapter: 'city' })
    auto.weapons = []; auto.mods.spawnMul = 0; auto.player.hp = 1e9; auto.player.maxHP = 1e9
    let maxAlive = 0
    let rolled = null
    for (let i = 0; i < Math.round(12 / dt); i++) {
      stepSim(auto, { x: 0, y: 0 }, dt)
      if (auto.lanes[0]) rolled = rolled ?? auto.lanes[0]
      maxAlive = Math.max(maxAlive, auto.lanes.length)
    }
    assert(maxAlive > 0, 'expected a city run to roll traffic lanes on its own')
    assert(maxAlive <= CHAPTERS.city.signature.lanes, `expected at most ${CHAPTERS.city.signature.lanes} lanes alive, saw ${maxAlive}`)
    assert.strictEqual(rolled.enemyFrac, TRAFFIC_ENEMY_HP_FRAC, 'a rolled taxi lane carries the enemy hp fraction')
    assert.strictEqual(rolled.squash, undefined, 'and carries NO roadkill list — v6.9.3 retired it')
    console.log(`PASS run Z.b (traffic): warn harmless, sweep flattens BOTH sides + knockback, ${(TRAFFIC_ENEMY_HP_FRAC * 100).toFixed(0)}% max-hp to EVERY enemy incl. drones and elites, <= ${maxAlive} lane(s) live`)
  }

  // (c) bombardment: telegraphed circles rain on the player's area continuously, and (being run.bombs)
  // they damage BOTH sides.
  {
    const run = createRun(makeMeta(), { chapter: 'skies' })
    run.weapons = []; run.obstacles = []; run._obstacleSeed = null; run.mods.spawnMul = 0
    run.player.x = 0; run.player.y = 0; run.player.hp = 1e9; run.player.maxHP = 1e9; run.player.invuln = 0
    const victim = makeStatusEnemy(run, { x: 0, y: 0, hp: 1e6, speed: 0 })
    run.enemies.push(victim)

    let sawBombs = 0
    for (let i = 0; i < Math.round(9 / dt); i++) {
      stepSim(run, { x: 0, y: 0 }, dt)
      sawBombs = Math.max(sawBombs, run.bombs.length)
      for (const b of run.bombs) {
        assert.strictEqual(b.radius, BOMBARDMENT_RADIUS, `expected bombardment radius ${BOMBARDMENT_RADIUS}, got ${b.radius}`)
        assert(Math.hypot(b.x - run.player.x, b.y - run.player.y) <= BOMBARDMENT_SPREAD + 1e-6, 'expected bombs scattered within BOMBARDMENT_SPREAD of the player')
      }
    }
    assert(sawBombs >= BOMBARDMENT_COUNT, `expected >= ${BOMBARDMENT_COUNT} bombs alive at once, saw ${sawBombs}`)
    // v5.7.5: the scatter is area-uniform across a wide disc now (a storm, not a sniper), so a 9s
    // run may legitimately never roll a strike onto the origin — plant one dead-center to test the
    // both-sides damage contract (that part is stepBombs's job, not the scatter's).
    run.bombs.length = 0
    run.player.invuln = 0
    let hurt = false
    run.bombs.push({ x: 0, y: 0, radius: BOMBARDMENT_RADIUS, fuse: 0.1, duration: BOMBARDMENT_FUSE, dmg: BOMBARDMENT_DMG })
    for (let i = 0; i < Math.round(0.5 / dt); i++) {
      stepSim(run, { x: 0, y: 0 }, dt)
      if (run.events.some((ev) => ev.type === 'hurt')) hurt = true
    }
    assert(hurt, 'expected a strike landing on the player to damage them')
    assert(victim.hp < 1e6, `expected the bombardment to damage enemies too (BOTH sides), hp=${victim.hp}`)
    // Only the skies get shelled by the sky.
    const quiet = createRun(makeMeta(), { chapter: 'city' })
    quiet.weapons = []; quiet.mods.spawnMul = 0; quiet.player.hp = 1e9; quiet.player.maxHP = 1e9
    for (let i = 0; i < Math.round(9 / dt); i++) stepSim(quiet, { x: 0, y: 0 }, dt)
    assert.strictEqual(quiet.bombs.length, 0, 'expected a non-bombardment chapter never to rain bombs')
    console.log(`PASS run Z.c (bombardment): >= ${sawBombs} telegraphed circles, damages BOTH sides`)
  }

  // (d) gravity: the wells are seeded at createRun, they BEND projectiles WITHOUT changing their
  // speed (curvature, not acceleration), and they leave bodies alone.
  {
    const seeded = createRun(makeMeta(), { chapter: 'beyond' })
    assert.strictEqual(seeded.wells.length, CHAPTERS.beyond.signature.wells,
      `expected ${CHAPTERS.beyond.signature.wells} wells seeded, got ${seeded.wells.length}`)
    for (const w of seeded.wells) {
      assert(Math.hypot(w.x, w.y) >= GRAVITY_MIN_DIST, `expected wells >= ${GRAVITY_MIN_DIST}px from the origin, got ${Math.hypot(w.x, w.y).toFixed(1)}`)
      assert.strictEqual(w.r, GRAVITY_WELL_R, `expected well radius ${GRAVITY_WELL_R}, got ${w.r}`)
      assert.strictEqual(w.g, GRAVITY_FORCE, `expected well force ${GRAVITY_FORCE}, got ${w.g}`)
    }
    for (let i = 0; i < seeded.wells.length; i++) {
      for (let j = i + 1; j < seeded.wells.length; j++) {
        const a = seeded.wells[i], b = seeded.wells[j]
        const gap = Math.hypot(a.x - b.x, a.y - b.y) - a.r - b.r
        assert(gap >= GRAVITY_MIN_GAP - 1e-6, `expected wells spaced >= ${GRAVITY_MIN_GAP}px edge-to-edge, got ${gap.toFixed(1)}`)
      }
    }
    assert.strictEqual(createRun(makeMeta(), { chapter: 'skies' }).wells.length, 0, 'expected a non-gravity chapter to seed no wells')

    // THE contract: a well bends a bullet's path and its speed is preserved exactly.
    const run = createRun(makeMeta(), { chapter: 'beyond' })
    run.weapons = []; run.obstacles = []; run._obstacleSeed = null; run.mods.spawnMul = 0
    run.player.x = 0; run.player.y = 0; run.player.hp = 1e9; run.player.maxHP = 1e9
    run.wells = [{ x: 0, y: 160, r: GRAVITY_WELL_R, g: GRAVITY_FORCE }] // straddles the flight path
    const speed = 480
    run.bullets.push({
      x: -150, y: 0, vx: speed, vy: 0, dmg: 1, pierce: 1, life: 5, r: 10, speed,
      hitIds: new Set(), weapon: 'quill', _shard: false, _splitDone: true, _chainsLeft: 0,
    })
    const b = run.bullets[0]
    let maxSpeedErr = 0
    for (let i = 0; i < Math.round(0.5 / dt); i++) {
      stepSim(run, { x: 0, y: 0 }, dt)
      if (!run.bullets.includes(b)) break
      maxSpeedErr = Math.max(maxSpeedErr, Math.abs(Math.hypot(b.vx, b.vy) - speed))
    }
    assert(maxSpeedErr < 1e-6, `expected a well to preserve projectile SPEED exactly (curvature, not acceleration), max error ${maxSpeedErr}`)
    assert(b.vy > 20, `expected the well to bend the bullet toward it (+y), vy=${b.vy.toFixed(1)}`)
    assert(b.y > 1, `expected the bent path to actually curve, y=${b.y.toFixed(1)}`)

    // ...and it bends nothing else: bodies, beams, orbitals and zones are not projectiles.
    const bodies = createRun(makeMeta(), { chapter: 'beyond' })
    bodies.weapons = []; bodies.obstacles = []; bodies._obstacleSeed = null; bodies.mods.spawnMul = 0
    bodies.player.x = 0; bodies.player.y = 0; bodies.player.hp = 1e9; bodies.player.maxHP = 1e9
    bodies.wells = [{ x: 60, y: 0, r: GRAVITY_WELL_R, g: GRAVITY_FORCE }]
    const still = makeStatusEnemy(bodies, { x: 0, y: 60, hp: 1e6, speed: 0 })
    still.flags = []
    bodies.enemies.push(still)
    const px0 = bodies.player.x, py0 = bodies.player.y
    for (let i = 0; i < Math.round(0.5 / dt); i++) stepSim(bodies, { x: 0, y: 0 }, dt)
    assert.strictEqual(still.x, 0, `expected a well to never move an enemy body, x=${still.x}`)
    assert.strictEqual(still.y, 60, `expected a well to never move an enemy body, y=${still.y}`)
    // v5.18: beyond is a lane, so the player ADVANCES up it every frame by design. What a well must
    // never do is move them off their strafe line — so pin x exactly, and pin y to exactly the
    // lane's own scroll (which doubles as the lane invariant: nothing may change the scroll rate).
    assert.strictEqual(bodies.player.x, px0, 'expected a well to never move the player sideways')
    const laneDrift = py0 - bodies.player.y
    const expectDrift = LANE_SCROLL_SPEED * Math.round(0.5 / dt) * dt
    assert(Math.abs(laneDrift - expectDrift) < 1e-6,
      `expected the player to advance at exactly LANE_SCROLL_SPEED and nothing else, drifted ${laneDrift.toFixed(2)} vs ${expectDrift.toFixed(2)}`)
    assert(!bodies.events.some((ev) => ev.type === 'hurt' || ev.type === 'hit'), 'expected wells to damage nothing')
    console.log(`PASS run Z.d (gravity): ${seeded.wells.length} wells seeded, bullet bent to vy=${b.vy.toFixed(0)} with speed error ${maxSpeedErr.toExponential(1)}, bodies untouched`)
  }

  console.log('PASS run Z (v5.4 signatures): predators traps, traffic lanes, bombardment, gravity wells')
}

// ---- Run ZR: v5.21 repulsion + asteroids ----------------------------------------------------
// The lane's two answers to "strafe-only means sometimes you can't do anything". Repulsion buys
// space you cannot walk to; asteroids are a hazard that hurts BOTH sides, so the pair is a combo
// (shove a rank into a rock) rather than two unrelated buttons.
function testLaneSkills() {
  const dt = 1 / 60

  function laneRun() {
    const run = createRun(makeMeta(), { chapter: 'beyond' })
    run.weapons = []; run.obstacles = []; run._obstacleSeed = null; run.mods.spawnMul = 0
    run._formationT = 1e6; run._rockAcc = 1e6   // park both spawners; these cases place things by hand
    run.rocks = []
    run.player.x = 0; run.player.y = 0
    run.player.hp = 1e9; run.player.maxHP = 1e9
    return run
  }

  // (a) Repulsion shoves nearby enemies away and stuns them, costs no HP, and respects its cooldown.
  {
    const run = laneRun()
    const near = makeStatusEnemy(run, { x: 120, y: 0, speed: 0 })
    const far = makeStatusEnemy(run, { x: REPULSE_RADIUS + 200, y: 0, speed: 0 })
    run.enemies.push(near, far)
    const nearHp = near.hp, farX0 = far.x

    stepSim(run, { x: 0, y: 0, skill: true }, dt)
    assert(run.events.some((e) => e.type === 'repulse'), 'expected a repulse event')
    assert(near.stunT > 0, `expected the near enemy stunned, got ${near.stunT}`)
    assert.strictEqual(near.hp, nearHp, 'expected repulsion to deal NO damage — it buys space, not kills')
    assert(Math.abs(run.repulseCd - REPULSE_CD) < 1e-6, `expected the cooldown armed, got ${run.repulseCd}`)

    for (let i = 0; i < Math.round(0.5 / dt); i++) stepSim(run, { x: 0, y: 0 }, dt)
    assert(near.x > 120 + 40, `expected the near enemy shoved outward, x 120->${near.x.toFixed(0)}`)
    assert(Math.abs(far.x - farX0) < 1e-6, `expected an enemy beyond REPULSE_RADIUS untouched, moved to ${far.x.toFixed(1)}`)

    // On cooldown: pressing again does nothing at all.
    const cdBefore = run.repulseCd
    const evs0 = run.events.length
    stepSim(run, { x: 0, y: 0, skill: true }, dt)
    assert(run.repulseCd < cdBefore, 'expected the cooldown to keep ticking down, not re-arm')
    assert(!run.events.slice(evs0).some((e) => e.type === 'repulse'), 'expected no second repulse while on cooldown')
    console.log(`PASS run ZR.a (repulsion): shoved to x=${near.x.toFixed(0)}, stunned, 0 dmg, cd ${REPULSE_CD}s respected`)
  }

  // (b) An asteroid grinds enemies that overlap it — this is what makes shoving things into one worth
  // doing — and it hurts the player on contact.
  {
    const run = laneRun()
    const victim = makeStatusEnemy(run, { x: 0, y: -600, hp: 1e6, speed: 0 })
    run.enemies.push(victim)
    run.rocks.push({ x: 0, y: -600, r: 60, vCross: 0, rot: 0, spin: 0, _acc: 0 })
    const hp0 = victim.hp
    for (let i = 0; i < Math.round(0.5 / dt); i++) stepSim(run, { x: 0, y: 0 }, dt)
    assert(victim.hp < hp0, `expected the rock to grind an overlapping enemy, hp ${hp0}->${victim.hp}`)
    console.log(`PASS run ZR.b (asteroid grinds enemies): ${(hp0 - victim.hp).toFixed(0)} dmg over 0.5s`)
  }

  // (c) ...and the same rock damages the PLAYER. Sat directly on them, with invuln cleared so the
  // gate cannot mask it — the point is that a rock is neutral, not that it is enemy-only.
  {
    const run = laneRun()
    run.player.hp = 500; run.player.maxHP = 500
    run.player.invuln = 0
    run.rocks.push({ x: run.player.x, y: run.player.y, r: 70, vCross: 0, rot: 0, spin: 0, _acc: 0 })
    const hp0 = run.player.hp
    stepSim(run, { x: 0, y: 0 }, dt)
    assert(run.player.hp < hp0, `expected a rock overlapping the player to hurt, hp ${hp0}->${run.player.hp}`)
    assert(run.events.some((e) => e.type === 'rockhit'), 'expected a rockhit event')
    console.log(`PASS run ZR.c (asteroid hurts the player): hp ${hp0}->${run.player.hp}`)
  }

  // (e) v5.22: the Pulsar Sweep fans FORWARD in a lane. It used to rake a full circle from an
  // angle picked by nearestEnemy, so in a scrolled level most of its duty cycle pointed at empty
  // space behind the player — and the cast could lock onto a straggler that had already gone past.
  {
    const run = laneRun()
    run.weapons = [{ id: 'pulsarSweep', level: 1 }]
    // A decoy BEHIND the player: under the old aimAngle path this is what the beam aimed at.
    run.enemies.push(makeStatusEnemy(run, { x: 0, y: 400, speed: 0 }))
    let fired = null
    for (let i = 0; i < Math.round(9 / dt) && !fired; i++) {
      stepSim(run, { x: 0, y: 0 }, dt)
      if (run.beams.length > 0) fired = run.beams[0]
    }
    assert(fired, 'expected the pulsar sweep to fire within 9s (L1 rate is 6.5s)')
    assert(fired.fan > 0, 'expected fan mode in a lane chapter')
    // Every arm, across the whole sweep, must have a forward (negative-y) component.
    let worst = -Infinity
    for (let i = 0; i < Math.round(fired.duration / dt); i++) {
      stepSim(run, { x: 0, y: 0 }, dt)
      const b = run.beams[0]
      if (!b) break
      const arms = []
      for (let k = 0; k < b.arms; k++) arms.push(b.angle - b.fan / 2 + (k / (b.arms - 1)) * b.fan)
      for (const a of arms) worst = Math.max(worst, Math.sin(a)) // +sin = pointing DOWN = behind
    }
    assert(worst < 0, `expected every pulsar arm to point forward; worst sin(angle)=${worst.toFixed(3)}`)
    console.log(`PASS run ZR.e (pulsar fans forward): no arm ever pointed behind (worst sin=${worst.toFixed(2)})`)
  }

  // (f) v5.22: a vortex has to FIT on a phone. The binding constraint is half the screen WIDTH
  // (~215 CSS px), not run.viewRadius (~535, which is half the diagonal) — reading the diagonal is
  // what let 300-460px radii look defensible while rendering as a flat wash with a blob in it.
  {
    const PHONE_HALF_WIDTH = 215
    for (let lv = 0; lv < WEAPONS.hole.levels.length; lv++) {
      const r = WEAPONS.hole.levels[lv].radius
      assert(r <= PHONE_HALF_WIDTH, `hole L${lv + 1} radius ${r} exceeds a phone's half-width ${PHONE_HALF_WIDTH} — it cannot render as a circle`)
    }
    console.log(`PASS run ZR.f (vortex fits a phone): radii ${WEAPONS.hole.levels.map((l) => l.radius).join('/')} all <= ${PHONE_HALF_WIDTH}`)
  }

  // (d) Neither system exists outside a lane chapter — both gate on CHAPTERS[chapter].lane.
  {
    const run = createRun(makeMeta(), { chapter: 'city' })
    run.weapons = []; run.mods.spawnMul = 0
    run.player.hp = 1e9; run.player.maxHP = 1e9
    for (let i = 0; i < Math.round(8 / dt); i++) stepSim(run, { x: 0, y: 0, skill: true }, dt)
    assert.strictEqual(run.rocks.length, 0, `expected no asteroids outside a lane chapter, got ${run.rocks.length}`)
    assert.strictEqual(run.repulseCd, 0, `expected repulsion inert outside a lane chapter, cd=${run.repulseCd}`)
    assert(!run.events.some((e) => e.type === 'repulse'), 'expected no repulse outside a lane chapter')
    console.log('PASS run ZR.d (both gate on `lane`): city sees no rocks and no repulse over 8s')
  }
}

// ---- Run ZM: v5.19 march homing ------------------------------------------------------------
// A marcher used to advance straight down the lane and slide harmlessly past a player who never
// moved. It now converges on the player's column too — but SLOWLY, which is the whole contract:
// fast enough that ignoring a rank costs you, slow enough that committing to a gap still beats it.
// Both halves are asserted here, because only the pair is the design (either alone is a bug).
function testLaneMarch() {
  const dt = 1 / 60

  function marchRun(offsetX) {
    const run = createRun(makeMeta(), { chapter: 'beyond' })
    run.weapons = []; run.obstacles = []; run._obstacleSeed = null; run.mods.spawnMul = 0
    run._formationT = 1e6 // park the rank spawner: this case is about one marcher
    run.player.x = 0; run.player.y = 0
    run.player.hp = 1e9; run.player.maxHP = 1e9
    // Placed well ahead up-lane so it never reaches contact range during the window.
    const e = makeStatusEnemy(run, { x: offsetX, y: -1200, speed: 90 })
    e.flags = ['march']
    run.enemies.push(e)
    return { run, e }
  }

  // Both cases step for EXACTLY one sway period. The shuffle is a cosine with amplitude
  // MARCH_SWAY_PX (~46px of excursion) against a homing rate of only ~17px/s, so over an arbitrary
  // window the sway swamps the signal — a 4s window happens to cancel the homing almost exactly.
  // Over one whole period the cosine integrates to zero and what's left IS the homing.
  const period = (Math.PI * 2) / MARCH_SWAY_RATE

  // (a) It closes the horizontal gap on an idle player, and still descends while doing it.
  {
    const { run, e } = marchRun(400)
    const gap0 = Math.abs(e.x - run.player.x)
    const y0 = e.y
    for (let i = 0; i < Math.round(period / dt); i++) stepSim(run, { x: 0, y: 0 }, dt)
    const gap1 = Math.abs(e.x - run.player.x)
    assert(gap1 < gap0 - 60, `expected a marcher to converge on an idle player, gap ${gap0.toFixed(0)}->${gap1.toFixed(0)}px`)
    assert(e.y > y0 + 50, `expected a marcher to keep descending while homing, y ${y0.toFixed(0)}->${e.y.toFixed(0)}`)

    // ...and slowly. The closure rate must stay far under the player's own strafe, or "commit to a
    // gap" stops working and the rank is just a wall that follows you (rev.1's failure).
    const closeRate = (gap0 - gap1) / period
    const strafe = PLAYER.baseSpeed * LANE_STRAFE_MUL
    assert(closeRate < strafe * 0.25, `expected homing well under a strafe: ${closeRate.toFixed(0)}px/s vs strafe ${strafe.toFixed(0)}px/s`)
    console.log(`PASS run ZM.a (march homes): gap ${gap0.toFixed(0)}->${gap1.toFixed(0)}px at ${closeRate.toFixed(0)}px/s (strafe ${strafe.toFixed(0)}px/s), descended ${(e.y - y0).toFixed(0)}px`)
  }

  // (b) The fairness contract: a player who strafes AWAY outruns the convergence outright. Same
  // marcher, same window — only the input differs, and the gap must grow instead of shrink.
  {
    const { run, e } = marchRun(-200) // enemy to the player's left, so strafe right to flee
    const gap0 = Math.abs(e.x - run.player.x)
    for (let i = 0; i < Math.round(period / dt); i++) stepSim(run, { x: 1, y: 0 }, dt)
    const gap1 = Math.abs(e.x - run.player.x)
    assert(gap1 > gap0 + 100, `expected strafing away to beat the homing, gap ${gap0.toFixed(0)}->${gap1.toFixed(0)}px`)
    console.log(`PASS run ZM.b (strafe beats homing): gap ${gap0.toFixed(0)}->${gap1.toFixed(0)}px while fleeing`)
  }
}

// ---- Run AA: v5.4 weapons + per-chapter balance bands (run W/X style) ---------------------
function testV54Weapons() {
  const dt = 1 / 60

  // A quiet run in a chapter, with one weapon at max level and nothing else moving.
  function weaponRun(chapter, id, level = MAX_WEAPON_LEVEL) {
    const run = createRun(makeMeta(), { chapter })
    run.weapons = [{ id, level }]
    run.obstacles = []; run._obstacleSeed = null; run.traps = []; run.wells = []; run.mods.spawnMul = 0
    run._laneAcc = 1e6; run._bombardAcc = 1e6 // park the signatures: these cases are about the weapon
    run.player.x = 0; run.player.y = 0; run.player.hp = 1e9; run.player.maxHP = 1e9
    return run
  }
  function stepQuiet(run, seconds, input = { x: 0, y: 0 }) {
    for (let i = 0; i < Math.round(seconds / dt); i++) {
      if (run.phase === 'levelup') { declineLevelUp(run); continue }
      stepSim(run, input, dt)
    }
  }

  // (a) clawRake: a narrow sector rake at the nearest foe that NEVER moves the player (v5.5 — see
  // the CLAW_* block in config.js). doubleSlash adds a follow-up slash; bleedClaws bleeds.
  {
    const run = weaponRun('undergrowth', 'clawRake')
    const target = makeStatusEnemy(run, { x: 100, y: 0, hp: 1e6, speed: 0 })
    target.flags = []
    run.enemies.push(target)
    let sawRake = null
    for (let i = 0; i < Math.round(2 / dt) && !sawRake; i++) {
      if (run.phase === 'levelup') { declineLevelUp(run); continue }
      stepSim(run, { x: 0, y: 0 }, dt)
      sawRake = run.events.find((ev) => ev.type === 'clawRake')
    }
    assert(sawRake, 'expected a clawRake event')
    assert(target.hp < 1e6, `expected the rake to damage the foe, hp=${target.hp}`)

    // THE regression (v5.5): the cast must not move the player. This weapon was "Pounce Claws" and
    // dashed them onto the target — an auto-cast stealing the only input the game has, and feeding
    // them into contact damage. Zero input + many casts must leave the player exactly where it was.
    {
      const still = weaponRun('undergrowth', 'clawRake')
      still.weaponMods.clawRake.doubleSlash = 1 // the follow-up slash must not move them either
      const foe = makeStatusEnemy(still, { x: 60, y: 0, hp: 1e9, speed: 0 })
      foe.flags = []
      still.enemies.push(foe)
      const x0 = still.player.x, y0 = still.player.y
      let rakes = 0
      for (let i = 0; i < Math.round(4 / dt); i++) {
        if (still.phase === 'levelup') { declineLevelUp(still); continue }
        still.events = []
        stepSim(still, { x: 0, y: 0 }, dt)
        rakes += still.events.filter((ev) => ev.type === 'clawRake').length
      }
      assert(rakes >= 8, `expected many rakes to have fired, got ${rakes}`)
      assert.strictEqual(still.player.x, x0, `expected clawRake to NEVER move the player (x moved ${still.player.x - x0} over ${rakes} rakes)`)
      assert.strictEqual(still.player.y, y0, `expected clawRake to NEVER move the player (y moved ${still.player.y - y0} over ${rakes} rakes)`)
    }

    // doubleSlash: every CLAW_DOUBLE_EVERY-th rake queues a follow-up slash, so slashes outnumber casts.
    const dbl = weaponRun('undergrowth', 'clawRake')
    dbl.weaponMods.clawRake.doubleSlash = 1
    dbl.enemies.push(makeStatusEnemy(dbl, { x: 60, y: 0, hp: 1e9, speed: 0 }))
    let slashes = 0
    for (let i = 0; i < Math.round((CLAW_DOUBLE_EVERY + 1) * 1.0 / dt); i++) {
      if (dbl.phase === 'levelup') { declineLevelUp(dbl); continue }
      dbl.events = [] // main.js drains events every frame; tests must too, or counts compound
      stepSim(dbl, { x: 0, y: 0 }, dt)
      slashes += dbl.events.filter((ev) => ev.type === 'clawRake').length
    }
    assert(dbl._clawRakes >= CLAW_DOUBLE_EVERY, `expected several casts, got ${dbl._clawRakes}`)
    assert(slashes > dbl._clawRakes, `expected doubleSlash to add slashes beyond the casts (casts=${dbl._clawRakes}, slashes=${slashes})`)

    // bleedClaws: a raked foe bleeds (flagella's barbed DoT, verbatim).
    const bleed = weaponRun('undergrowth', 'clawRake')
    bleed.weaponMods.clawRake.bleedClaws = 0.5
    const bleeder = makeStatusEnemy(bleed, { x: 60, y: 0, hp: 1e6, speed: 0 })
    bleeder.flags = []
    bleed.enemies.push(bleeder)
    stepQuiet(bleed, 1.0)
    assert(bleeder.bleed > 0 && bleeder.bleedDps > 0, `expected bleedClaws to bleed a raked foe (bleed=${bleeder.bleed}, dps=${bleeder.bleedDps})`)
    console.log(`PASS run AA.a (clawRake): rakes the nearest foe and NEVER moves the player; doubleSlash chains (${slashes} slashes / ${dbl._clawRakes} casts); bleedClaws bleeds`)
  }

  // (b) quillBurst: a ring of quills in every direction (never aimed — the panic button), tagged
  // weapon:'quill'; retaliate fires a free burst the instant the player is hurt.
  {
    const run = weaponRun('undergrowth', 'quillBurst')
    run.enemies.push(makeStatusEnemy(run, { x: 200, y: 0, hp: 1e6, speed: 0 }))
    const lvl = WEAPONS.quillBurst.levels[MAX_WEAPON_LEVEL - 1]
    let burst = []
    for (let i = 0; i < Math.round(2 / dt) && burst.length === 0; i++) {
      if (run.phase === 'levelup') { declineLevelUp(run); continue }
      stepSim(run, { x: 0, y: 0 }, dt)
      if (run.bullets.length > 0) burst = run.bullets.slice()
    }
    assert.strictEqual(burst.length, lvl.count, `expected ${lvl.count} quills per burst, got ${burst.length}`)
    for (const b of burst) {
      assert.strictEqual(b.weapon, 'quill', 'expected each quill tagged weapon:quill')
      assert.strictEqual(b._chainsLeft, 0, "expected star's chain disabled on quills")
    }
    // Evenly around the full circle: the headings span way more than any cone.
    const angles = burst.map((b) => Math.atan2(b.vy, b.vx)).sort((a, z) => a - z)
    assert(angles[angles.length - 1] - angles[0] > Math.PI, `expected quills all around, span=${(angles[angles.length - 1] - angles[0]).toFixed(2)}rad`)

    // retaliate: taking a hit fires a free burst off the weapon timer (once per QUILL_RETALIATE_CD).
    const ret = weaponRun('undergrowth', 'quillBurst')
    ret.weaponMods.quillBurst.retaliate = 1
    ret.player.hp = 500; ret.player.maxHP = 500; ret.player.invuln = 0
    ret.weaponTimers.quillBurst = 1e6 // park the timer: any burst now can only be the retaliation
    ret.traps = [{ x: 0, y: 0, r: SNAP_TRAP_R, armed: true, rearmAt: 0 }] // a trap under the player = a free hit
    stepSim(ret, { x: 0, y: 0 }, dt)
    assert(ret.bullets.length > 0, 'expected retaliate to fire a free burst when the player is hurt')
    assert.strictEqual(ret.bullets.length, lvl.count + 1, `expected the level's count + 1 retaliate pick, got ${ret.bullets.length}`)
    // The cd is set when the hit lands, then stepQuillWeapon ticks it down later in the same frame.
    assert(ret._quillRetalCd > 0 && ret._quillRetalCd <= QUILL_RETALIATE_CD,
      `expected retaliate on cooldown (0, ${QUILL_RETALIATE_CD}], got ${ret._quillRetalCd}`)
    console.log(`PASS run AA.b (quillBurst): ${burst.length} quills all around; retaliate fires ${lvl.count + 1} on being hit`)
  }

  // (c) chitterShriek: the ring FEARS what it hits — a feared enemy runs AWAY (inverted seek) at
  // FEAR_SPEED_MUL. It KEEPS dealing contact damage (v7.16). panicRout amplifies damage on fleeing foes.
  {
    const run = weaponRun('undergrowth', 'chitterShriek')
    const victim = makeStatusEnemy(run, { x: 100, y: 0, hp: 1e6, speed: 100 })
    victim.flags = []
    run.enemies.push(victim)
    let feared = false
    for (let i = 0; i < Math.round(4 / dt) && !feared; i++) {
      if (run.phase === 'levelup') { declineLevelUp(run); continue }
      stepSim(run, { x: 0, y: 0 }, dt)
      if (victim.fearT > 0) feared = true
    }
    assert(feared, 'expected the shriek to fear the enemies it hits')

    // A feared enemy flees at FEAR_SPEED_MUL of its own speed (vs seeking at 1x).
    function fleeDx(fear) {
      const r = weaponRun('undergrowth', 'chitterShriek')
      r.weapons = []
      r.player.x = 1000; r.player.y = 0 // player to the +x
      const e = makeStatusEnemy(r, { x: 0, y: 0, hp: 1e6, speed: 100 })
      e.flags = []
      if (fear) e.fearT = 10
      r.enemies.push(e)
      const x0 = e.x
      stepQuiet(r, 0.3)
      return e.x - x0
    }
    const flee = fleeDx(true), seek = fleeDx(false)
    assert(seek > 0, `expected a calm enemy to seek the player (+x), got ${seek.toFixed(1)}`)
    assert(flee < 0, `expected a feared enemy to FLEE (-x), got ${flee.toFixed(1)}`)
    assert(Math.abs(Math.abs(flee / seek) - FEAR_SPEED_MUL) < 0.01, `expected fleeing at ${FEAR_SPEED_MUL}x, got ${Math.abs(flee / seek).toFixed(3)}x`)

    // A feared enemy STILL DEALS CONTACT DAMAGE (v7.16, owner's call). It used to be disarmed, and
    // that was half of the machine-gun lock: a x5 fire rate pinned fear at 100% field-wide, so
    // every enemy on screen was simultaneously fleeing AND unable to touch you. Fear moves them;
    // it does not make them harmless. STUN still disarms — asserted right after, because deleting
    // the fear clause from contactHarmless by hand is one keystroke away from deleting both.
    const touch = (status) => {
      const r = weaponRun('undergrowth', 'chitterShriek')
      r.weapons = []
      r.player.hp = 500; r.player.maxHP = 500; r.player.invuln = 0
      const e = makeStatusEnemy(r, { x: 0, y: 0, hp: 1e6, speed: 0 })
      e.flags = []
      Object.assign(e, status)
      r.enemies.push(e)
      stepQuiet(r, 0.5)
      return 500 - r.player.hp
    }
    assert.ok(touch({ fearT: 10 }) > 0, 'a feared enemy dealt no contact damage — fear moves enemies, it does not disarm them (v7.16)')
    assert.strictEqual(touch({ stunT: 10 }), 0, 'a STUNNED enemy dealt contact damage — stun still disarms; only the fear clause was removed')

    // THE REFRACTORY (v7.16). The lock this closes: fear refreshed with Math.max, so any cadence
    // shorter than the duration held it at 100% — MACHINE GUN's x5 fire rate made an untouchable
    // 189px wall (0 contact hits over 150s, measured). Asserted as UPTIME under a ring firing every
    // frame, which is the worst case any fire rate can reach: it must land well under 100%.
    {
      const r = weaponRun('undergrowth', 'chitterShriek')
      r.weapons = []
      const e = makeStatusEnemy(r, { x: 0, y: 0, hp: 1e9, speed: 0 })
      e.flags = []
      r.enemies.push(e)
      let feared = 0
      const FRAMES = 60 * 12
      for (let i = 0; i < FRAMES; i++) {
        // A fresh full-strength ring ON the enemy every single frame — no weapon can do better.
        r.novas.push({ x: 0, y: 0, r: 0, maxR: 400, dmg: 0, knockback: 0, fear: 1.8, life: 1, hit: new Set() })
        stepQuiet(r, 1 / 60)
        if ((e.fearT || 0) > 0) feared++
      }
      const uptime = feared / FRAMES
      // Two caps compose here and the assertion must not pin either one's exact value, or it breaks
      // every time the other moves: FEAR_REFRACTORY bounds it at 1.8/(1.8+2) = 47%, and v7.17's
      // diminishing returns shorten each application on top of that. What must stay true is that a
      // ring firing EVERY FRAME — better than any real fire rate — cannot approach a permanent
      // lock, and that fear still does something.
      assert.ok(uptime > 0.05 && uptime < 0.55,
        `fear uptime ${(100 * uptime).toFixed(0)}% under a ring firing EVERY FRAME — at ~100% the machine-gun lock is back, at ~0% fear has stopped working entirely`)
    }

    // ...AND THE FIRST HIT IS NEVER TAXED. Diminishing returns must charge CADENCE, not weapons: a
    // slow heavy weapon hitting a recovered enemy gets the full duration, or every un-stacked fear
    // in the game was quietly nerfed too.
    {
      const r = weaponRun('undergrowth', 'chitterShriek')
      r.weapons = []
      const e = makeStatusEnemy(r, { x: 0, y: 0, hp: 1e9, speed: 0 })
      e.flags = []
      r.enemies.push(e)
      r.novas.push({ x: 0, y: 0, r: 0, maxR: 400, dmg: 0, knockback: 0, fear: 1.8, life: 1, hit: new Set() })
      stepQuiet(r, 1 / 60)
      assert.ok(e.fearT > 1.7,
        `a single ring on a fully recovered enemy feared it for ${e.fearT.toFixed(2)}s, want the full 1.8 — DR must tax cadence, not the first hit`)
    }

    // GLOBAL CROWD-CONTROL PRICING (v7.17). Two rules, asserted by EFFECT on the same enemy:
    //   A. diminishing returns — the Nth application on one enemy is worth far less than the first;
    //   B. p.ccMul — MACHINE GUN's x0.2 pays for its x5 rate in control, not just in dps.
    // Measured as knockback actually imparted, because that is the one CC whose magnitude is a
    // plain number: a state check on _ccDR would pass with every call site left unscaled.
    {
      const shove = (n, gun) => {
        const r = weaponRun('undergrowth', 'chitterShriek')
        r.weapons = []
        // Through applyChoice, not by setting ccMul by hand: the thing under test is that the CARD
        // sets it. Assigning the field directly tests only that ccScale reads it, and a mutant that
        // deletes the card's own line passes happily (it did).
        if (gun) { r.levelUpChoices = [{ kind: 'anomaly', id: 'soyMilk' }]; applyChoice(r, 0) }
        const e = makeStatusEnemy(r, { x: 0, y: 0, hp: 1e9, speed: 0 })
        e.flags = []
        r.enemies.push(e)
        let last = 0
        for (let i = 0; i < n; i++) {
          e.kb.x = e.kb.y = 0
          r.novas.push({ x: 0, y: 0, r: 0, maxR: 400, dmg: 0, knockback: 300, fear: 0, life: 1, hit: new Set() })
          stepQuiet(r, 1 / 60)
          last = Math.hypot(e.kb.x, e.kb.y)
        }
        return last
      }
      const first = shove(1, false), fifth = shove(5, false)
      assert.ok(first > 250, `the FIRST shove imparted ${first.toFixed(0)}, want ~300 — DR must tax cadence, not weapons`)
      // Band, not a point: CC_DR_STEP is a tuning knob (0.5 -> 0.7 from play), so pinning the exact
      // ratio would make every retune a red test. What must hold is that stacked applications are
      // worth a fraction of the first — the no-DR mutant reads 1.00.
      assert.ok(fifth < first * 0.5,
        `the 5th shove in 5 frames imparted ${fifth.toFixed(0)} against the first's ${first.toFixed(0)} — without diminishing returns any fire rate buys unlimited control`)
      // B: the same FIRST hit, under MACHINE GUN, priced at x0.2.
      const firstGun = shove(1, true)
      assert.ok(Math.abs(firstGun / first - SOY_MILK_CC_MUL) < 0.02,
        `MACHINE GUN's first shove was x${(firstGun / first).toFixed(2)} of baseline, want x${SOY_MILK_CC_MUL} — its x5 rate is free control otherwise`)
    }

    // UNSHAKEABLE — one tank per chapter RESISTS crowd control, and is never immune to it. Owner
    // ruling 2026-08-17: only the `anchored` ELITE AFFIX may ignore CC outright; a roster tank is
    // "harder to proc, but never impossible". The roster half is asserted on the shipped entry, not
    // on a hand-set flag — the flag being absent from config is the failure this must catch.
    //
    // DENOMINATOR: shippedChapterIds(), not CHAPTER_ORDER — which is BOOKS.book1.chapters and so
    // cannot see The Blank at all (CLAUDE.md's run RA trap). Widening it to every key of CHAPTERS
    // reports the honest state of Book 2: the Moray, the Sea Lion and the Gulper Eel were all
    // designed WITHOUT the flag, and only The Shelf and The Surf carry it. That is a live design
    // question for `undertow`, not a regression this change introduces, and flipping three tanks in
    // an unshipped book to satisfy an assertion would be a balance change smuggled in as a test
    // fix. shippedChapterIds() is derived from BOOKS[].wip, so it widens by itself the day undertow
    // ships and demands an answer then — before a player sees it, not after.
    {
      const chapterIds = [...new Set(shippedChapterIds())]
      for (const id of chapterIds) {
        const tank = CHAPTERS[id].roster.find((x) => x.archetype === 'tank' && !x.formationOnly)
        assert.ok(tank && tank.flags.includes('unshakeable'),
          `${id}'s tank (${tank ? tank.name : 'none'}) is not unshakeable — that chapter has no heavy that leans into a fear/knockback wall`)
      }

      // One shriek ring, three bodies at EQUAL range so the shove is the same magnitude for each:
      // a plain drone, an `unshakeable` tank, and an `anchored` elite.
      const NOVA_FEAR = 1.8
      const r = weaponRun('undergrowth', 'chitterShriek')
      r.weapons = []
      const plain = makeStatusEnemy(r, { x: 0, y: -30, hp: 1e9, speed: 0 })
      const tank = makeStatusEnemy(r, { x: 0, y: 30, hp: 1e9, speed: 0 })
      const rock = makeStatusEnemy(r, { x: 30, y: 0, hp: 1e9, speed: 0, elite: true, affixes: ['anchored'] })
      plain.flags = []; rock.flags = []
      tank.flags = ['unshakeable']
      r.enemies.push(plain, tank, rock)
      r.novas.push({ x: 0, y: 0, r: 0, maxR: 400, dmg: 0, knockback: 500, fear: NOVA_FEAR, life: 1, hit: new Set() })
      let frames = 0
      while ((plain.fearT || 0) <= 0 && frames < 40) { stepQuiet(r, 1 / 60); frames++ }
      assert.ok((plain.fearT || 0) > 0, 'the ring never reached the plain drone — this block proves nothing')

      const kb = (e) => Math.hypot(e.kb.x, e.kb.y)
      // THE RULING, and the half that would silently regress: never zero.
      assert.ok((tank.fearT || 0) > 0,
        'an `unshakeable` tank was not feared AT ALL — only the `anchored` elite affix may be immune to CC')
      assert.ok(kb(tank) > 0, 'an `unshakeable` tank was not knocked back AT ALL')
      // ...and resisted by exactly the declared amount. fearT decays SUBTRACTIVELY, so the ratio
      // moves every frame while the DIFFERENCE does not — assert the decay-invariant quantity.
      assert.ok(Math.abs((plain.fearT - tank.fearT) - (1 - UNSHAKEABLE_CC_MUL) * NOVA_FEAR) < 1e-6,
        `an \`unshakeable\` tank's fear was ${tank.fearT.toFixed(3)}s against a drone's ${plain.fearT.toFixed(3)}s — want a gap of ` +
        `${((1 - UNSHAKEABLE_CC_MUL) * NOVA_FEAR).toFixed(3)}s (UNSHAKEABLE_CC_MUL ${UNSHAKEABLE_CC_MUL})`)
      // Knockback decays MULTIPLICATIVELY, so here the ratio is the invariant one.
      assert.ok(Math.abs(kb(tank) / kb(plain) - UNSHAKEABLE_CC_MUL) < 1e-6,
        `an \`unshakeable\` tank took x${(kb(tank) / kb(plain)).toFixed(3)} of the shove, want x${UNSHAKEABLE_CC_MUL}`)
      // The elite affix is still an OUTRIGHT immunity — that is what makes it the elite one.
      assert.strictEqual(rock.fearT || 0, 0, 'an `anchored` elite was feared')
      assert.ok(kb(rock) < 1e-9, `an \`anchored\` elite was knocked back (${kb(rock).toFixed(0)})`)
      console.log(`PASS run CC (unshakeable resists, never immune): ${chapterIds.length} chapters' tanks flagged, ` +
        `tank feared ${tank.fearT.toFixed(2)}s vs drone ${plain.fearT.toFixed(2)}s, shove x${(kb(tank) / kb(plain)).toFixed(2)}, anchored 0`)
    }

    // TANK KNOCKBACK REFRACTORY. CC_DR prices each shove but nothing prices the CADENCE, so a ring
    // firing faster than the time a slow tank needs to walk one FLOORED shove back pushes it out
    // without bound. The pair that sets the constant is The Deep's gulper against a maxed Chitter
    // Shriek (0.342s); the case that first found it was The Shelf's Bubble Puff, which no longer
    // shoves at all (see WEAPONS.bubblePuff) and is asserted ABSENT from the walk below.
    // Asserted by EFFECT, not by the timer: a mutant that ticks _kbCd but never gates on it passes
    // any state check. The drone arm is the one that pins the SCOPE — tanks only.
    {
      const twoShoves = (type) => {
        // A shelf run is just a quiet world here — the ring is pushed by hand, not cast.
        const r = weaponRun('shelf', 'bubblePuff')
        r.weapons = []
        const e = makeStatusEnemy(r, { x: 10, y: 0, hp: 1e9, speed: 0, type })  // inside the ring on frame 1: n.r starts at 0
        e.flags = []
        r.enemies.push(e)
        const ring = () => r.novas.push({ x: 0, y: 0, r: 0, maxR: 400, dmg: 0, knockback: 300, fear: 0, life: 1, hit: new Set() })
        ring(); stepQuiet(r, 1 / 60)
        const first = Math.hypot(e.kb.x, e.kb.y)
        e.kb.x = 0; e.kb.y = 0                 // zero it, so `second` is what the SECOND ring imparted
        ring(); stepQuiet(r, 1 / 60)           // far inside TANK_KB_REFRACTORY
        return { first, second: Math.hypot(e.kb.x, e.kb.y) }
      }
      const tank = twoShoves('tank'), drone = twoShoves('drone')
      assert.ok(tank.first > 0, 'the FIRST shove on a tank must land in full — this taxes cadence, not weapons')
      assert.ok(tank.second < 1e-9,
        `a tank took a second shove (${tank.second.toFixed(1)}) inside its ${TANK_KB_REFRACTORY}s knockback window`)
      assert.ok(drone.second > 0,
        'a drone was refused its second shove — the refractory is TANKS ONLY, they are the only archetype slow enough to lose the race')

      // THE WINDOW MUST OUTLAST THE RACE IT EXISTS TO STOP, for every tank a shove weapon can
      // actually reach. A floored shove displaces kb x ccResist x CC_DR_FLOOR / KB_DECAY_RATE px;
      // below (that / speed) seconds per ring, each shove out-runs the walk back and compounds.
      // KB_DECAY_RATE is a sim.js-local const, so it is read as SOURCE TEXT rather than guessed —
      // a stale copy here would silently move every threshold.
      const simSrc = readFileSync(new URL('../src/sim.js', import.meta.url), 'utf8')
      const m = simSrc.match(/const KB_DECAY_RATE = ([\d.]+)/)
      assert.ok(m, 'KB_DECAY_RATE not found in sim.js — the thresholds below cannot be derived')
      const KB_DECAY = Number(m[1])
      const pairs = []
      for (const [cid, ch] of Object.entries(CHAPTERS)) {
        for (const rr of ch.roster ?? []) {
          if (rr.archetype !== 'tank') continue
          const speed = ENEMIES.tank.speed * (rr.speedMul ?? 1)
          const cc = (rr.flags ?? []).includes('unshakeable') ? UNSHAKEABLE_CC_MUL : 1
          for (const wid of ch.weapons ?? []) {
            for (const [i, lv] of (WEAPONS[wid]?.levels ?? []).entries()) {
              if (!lv.knockback) continue
              pairs.push({ what: `${cid}/${rr.id} vs ${wid} L${i + 1}`, thr: lv.knockback * cc * CC_DR_FLOOR / KB_DECAY / speed })
            }
          }
        }
      }
      // THE SECOND SHOVE SITE. There are exactly two player-sourced ones — the nova ring (asserted
      // by effect above) and `shoveFromPlayer`, which every melee sector weapon routes through
      // (roar, whip, claw rake). The melee half has no cheap behavioural fixture, so it is guarded
      // as SOURCE TEXT instead: without this, deleting its claimKb gate is a silent no-test change.
      assert.ok(/function shoveFromPlayer\([^)]*\)\s*\{\s*\n\s*if \(resistsCC\(e\) \|\| !claimKb\(e\)\) return/.test(simSrc),
        'shoveFromPlayer no longer gates on claimKb — every melee shove weapon can re-lock a tank at high fire rate')

      assert.ok(pairs.length > 100, `only ${pairs.length} tank x shove-weapon pairs enumerated — the walk found nothing`)
      // Pinned to the WORST pair in the game rather than to one named chapter/weapon: a weapon that
      // loses its shove drops out of this walk silently, and a `find` on its name then fails as a
      // missing fixture rather than saying what actually changed (which is how the Bubble Puff's
      // deletion first showed up here).
      const worst = pairs.reduce((a, b) => (b.thr > a.thr ? b : a))
      assert.ok(TANK_KB_REFRACTORY > worst.thr * 1.2,
        `TANK_KB_REFRACTORY ${TANK_KB_REFRACTORY}s has no margin over the worst pair in the game ` +
        `(${worst.what}, ${worst.thr.toFixed(3)}s)`)
      // THE BUBBLE PUFF MUST STAY OUT OF IT. Its `knockback` was deleted (owner, 2026-08-19) because
      // the shove is what made standing perfectly still the best way to play The Shelf — 29% of runs
      // won without moving against a walker's 0%. Re-adding the stat puts the shove back with
      // nothing thrown and no other test red, so its ABSENCE is what gets asserted.
      assert.ok(!pairs.some((x) => x.what.includes('bubblePuff')),
        'bubblePuff is back in the tank x shove walk — it has a `knockback` stat on its ladder again')
      // EVERY reachable pair must be covered — the list is empty and must stay empty. It was three
      // entries at the first cut's 0.25s (The Deep's gulper vs Chitter Shriek L3-L5, which needs
      // 0.342s); 1s closes them with margin. Widen the constant, never extend this list.
      const uncovered = pairs.filter((x) => x.thr >= TANK_KB_REFRACTORY).map((x) => x.what).sort()
      assert.deepStrictEqual(uncovered, [],
        `${uncovered.length} tank x weapon pair(s) can still out-cadence the ${TANK_KB_REFRACTORY}s window: ${uncovered.join(', ')}`)
      console.log(`PASS run CC.kb (tank shove refractory): first shove ${tank.first.toFixed(0)}, second 0 inside ${TANK_KB_REFRACTORY}s; ` +
        `drone still shoved twice; ${pairs.length - uncovered.length}/${pairs.length} reachable tank x shove pairs covered ` +
        `(worst pair ${worst.what} needs ${worst.thr.toFixed(3)}s), ${uncovered.length} known-uncovered, bubblePuff absent`)
    }

    // panicRout: the same hit lands harder on a fleeing foe.
    function routHp(rout) {
      // Reseed per run, exactly like runStarOnly: these two calls are a BASELINE vs MODDED
      // comparison, and without this they draw from one continuous stream and play different
      // games — the crit rolls diverge, so the assert passes or fails on luck rather than on
      // panicRout. (It passed at 150 vs 140 only because the PLAIN run happened to crit.)
      Math.random = mulberry32(20260714)
      const r = weaponRun('undergrowth', 'chitterShriek')
      r.weapons = []
      if (rout) r.weaponMods.chitterShriek.panicRout = 0.40
      const e = makeStatusEnemy(r, { x: 0, y: 0, hp: 1e6, speed: 0 })
      e.flags = []; e.fearT = 10
      r.enemies.push(e)
      r.novas.push({ x: 0, y: 0, r: 0, maxR: 200, dmg: 100, knockback: 0, fear: 0, life: NOVA_LIFE, hit: new Set() })
      stepQuiet(r, NOVA_LIFE + 0.1)
      return 1e6 - e.hp
    }
    const routed = routHp(true), plainHit = routHp(false)
    assert(routed > plainHit, `expected panicRout to amplify damage on a fleeing foe (${plainHit} -> ${routed})`)
    console.log(`PASS run AA.c (chitterShriek): fears + inverts the seek at ${FEAR_SPEED_MUL}x, no contact damage, panicRout ${plainHit} -> ${routed}`)
  }

  // (d) trashTornado (v6.8): the funnels HUNT. Idle they orbit at `radius` (the pre-v6.8 look, now
  // only the idle state); prey inside `hunt` px of the PLAYER pulls funnels off the ring; a kill
  // sends them home. One funnel per foe is a PREFERENCE, not a veto — with more prey than funnels
  // every funnel takes a different target (the fan-out), and with fewer the pack doubles up rather
  // than idling. Both halves are guarded below, along with the two rules that make doubling up
  // worth anything: the leash reaches a foe's BODY (`hunt + e.radius`), and a tick is worth every
  // funnel standing on it. sweepLoot reels gems/coins in.
  {
    const lvl = WEAPONS.trashTornado.levels[MAX_WEAPON_LEVEL - 1]
    const onRing = (r, d) => Math.abs(Math.hypot(d.x - r.player.x, d.y - r.player.y) - lvl.radius) < 1e-6

    // idle: nothing to hunt, so the whole pack sits on the ring
    const idle = weaponRun('city', 'trashTornado')
    stepQuiet(idle, 1.0)
    assert.strictEqual(idle.debris.length, lvl.chunks, `expected ${lvl.chunks} funnels, got ${idle.debris.length}`)
    for (const d of idle.debris) assert(onRing(idle, d), 'expected an idle pack on the orbit ring')

    // hunt: one foe inside the leash but far off the ring, so a funnel has to LEAVE to reach it
    const run = weaponRun('city', 'trashTornado')
    const victim = makeStatusEnemy(run, { x: lvl.hunt - 20, y: 0, hp: 1e6, speed: 0 })
    victim.flags = []
    run.enemies.push(victim)
    stepQuiet(run, 2.0)
    // The WHOLE pack commits: with one foe in reach there is nothing to fan out over, and a pack
    // that leaves all but one funnel circling the player is the "only one attacks at a time" bug.
    const caught = run.debris.filter((d) => Math.hypot(d.x - victim.x, d.y - victim.y) < DEBRIS_R + victim.radius)
    assert.strictEqual(caught.length, lvl.chunks, `expected all ${lvl.chunks} funnels on a lone foe, got ${caught.length}`)
    assert(victim.hp < 1e6, `expected the funnels that caught it to grind it, hp=${victim.hp}`)
    const stayedHome = run.debris.filter((d) => onRing(run, d)).length
    assert.strictEqual(stayedHome, 0, `expected no funnel still orbiting with prey in reach, got ${stayedHome}`)

    // ...and when it dies the hunters spiral back home on their own. 5s, not 3: the whole pack
    // now commits to a lone foe, so it comes home fully bunched and TORNADO_RESPACE measures 3.05s
    // to bring the worst gap inside the band below (it was ~instant when 5 of 6 never left).
    victim.hp = 1
    stepQuiet(run, 5.0)
    assert.strictEqual(run.enemies.length, 0, 'expected the victim dead')
    for (const d of run.debris) assert(onRing(run, d), 'expected every funnel back on the ring after the kill')
    // ...and the ring re-spaces itself (TORNADO_RESPACE), so two hunts running don't leave the pack
    // bunched on one side. Gaps between neighbours should all be near 2pi/chunks.
    const angles = run.debris.map((d) => Math.atan2(d.y - run.player.y, d.x - run.player.x)).sort((a, b) => a - b)
    const want = (Math.PI * 2) / lvl.chunks
    const gaps = angles.map((a, i) => (i === 0 ? angles[0] + Math.PI * 2 - angles.at(-1) : a - angles[i - 1]))
    const worst = Math.max(...gaps.map((g) => Math.abs(g - want)))
    assert(worst < want * 0.15, `expected the ring to re-space after a hunt, worst gap error ${worst.toFixed(3)} rad`)

    // leash: a foe beyond `hunt` is invisible — the pack never wanders off after it
    const far = weaponRun('city', 'trashTornado')
    const ghost = makeStatusEnemy(far, { x: lvl.hunt + 120, y: 0, hp: 1e6, speed: 0 })
    ghost.flags = []
    far.enemies.push(ghost)
    stepQuiet(far, 2.0)
    assert.strictEqual(ghost.hp, 1e6, 'expected a foe outside the hunt radius to be ignored')
    for (const d of far.debris) assert(onRing(far, d), 'expected the pack home while the only foe is out of leash')

    // ...but the leash reaches a foe's BODY, not its centre. A big foe whose CENTRE is beyond
    // `hunt` while its hide is well inside must still be hunted: The Blank's antibody is radius 80
    // holding a 240px standoff, so a centre-only leash left the whole pack circling the player with
    // the boss in plain sight (measured 0.0 dps at L1, 7.7 at L5 — the bug this guards).
    const big = weaponRun('city', 'trashTornado')
    const whale = makeStatusEnemy(big, { x: lvl.hunt + 40, y: 0, hp: 1e6, speed: 0 })
    whale.flags = []
    whale.radius = 80
    big.enemies.push(whale)
    stepQuiet(big, 2.5)
    assert(whale.hp < 1e6, `expected a radius-80 foe at hunt+40 to be hunted by its BODY, hp=${whale.hp}`)

    // ...and a tick is worth EVERY funnel standing on the target, not just the first one the loop
    // reached. Without this the 2nd..Nth funnel is free of charge to the enemy — the pack converges,
    // the health bar moves at one funnel's rate, and `moreTrash` buys nothing single-target.
    // Driven through the real `moreTrash` fold rather than by trimming run.debris by hand — the
    // step RESIZES the list back to `chunks` every frame, so a hand-trimmed pack silently grows
    // back and the fixture compares chunks against chunks (it read 1716 vs 1404 and proved
    // nothing). This is also the honest statement of the card: +tornadoes now buys single-target
    // damage, which is exactly what it never did.
    function loneFoeDmg(moreTrash) {
      const r = weaponRun('city', 'trashTornado')
      if (moreTrash) r.weaponMods.trashTornado.moreTrash = moreTrash
      const e = makeStatusEnemy(r, { x: lvl.hunt - 20, y: 0, hp: 1e6, speed: 0 })
      e.flags = []
      r.enemies.push(e)
      stepQuiet(r, 2.0)                       // let the pack arrive and settle onto it
      const before = e.hp
      stepQuiet(r, 4.0)
      return { dmg: before - e.hp, funnels: r.debris.length }
    }
    const one = loneFoeDmg(0), all = loneFoeDmg(lvl.chunks)
    assert.strictEqual(all.funnels, lvl.chunks * 2, `expected moreTrash to double the pack, got ${all.funnels}`)
    assert(all.dmg > one.dmg * 1.7,
      `expected 2x the funnels on ONE foe to deal ~2x the damage, got ${all.dmg} from ${all.funnels} vs ${one.dmg} from ${one.funnels}`)

    // more prey than funnels: every funnel ends up on a DIFFERENT enemy
    const many = weaponRun('city', 'trashTornado')
    const flock = lvl.chunks + 2
    for (let i = 0; i < flock; i++) {
      const a = (i / flock) * Math.PI * 2
      const e = makeStatusEnemy(many, { x: Math.cos(a) * 150, y: Math.sin(a) * 150, hp: 1e6, speed: 0 })
      e.flags = []
      many.enemies.push(e)
    }
    stepQuiet(many, 2.0)
    const claimedFoes = new Set()
    for (const d of many.debris) {
      for (const e of many.enemies) {
        if (Math.hypot(e.x - d.x, e.y - d.y) < DEBRIS_R) { claimedFoes.add(e); break }
      }
    }
    assert.strictEqual(claimedFoes.size, lvl.chunks, `expected ${lvl.chunks} distinct targets, got ${claimedFoes.size}`)

    // Street Sweeper (v6.9, replaces the enemy-pulling suction): a gem near a FUNNEL — not near the
    // player, and well outside magnet range — is marked _vac and reels in. Without the mod it sits.
    function sweptGem(on) {
      const r = weaponRun('city', 'trashTornado')
      if (on) r.weaponMods.trashTornado.sweepLoot = 1
      r.player.magnet = 10           // so nothing here can be explained by the ordinary magnet
      stepQuiet(r, 1.0)              // let the pack settle onto its idle ring
      const t = r.debris[0]
      const gem = { x: t.x + 20, y: t.y, r: 6, xp: 1 }
      r.gems.push(gem)
      const d0 = Math.hypot(gem.x - r.player.x, gem.y - r.player.y)
      stepQuiet(r, 0.5)
      return { vac: !!gem._vac, closed: d0 - Math.hypot(gem.x - r.player.x, gem.y - r.player.y) }
    }
    const swept = sweptGem(true), unswept = sweptGem(false)
    assert(swept.vac, 'expected a gem beside a funnel to be marked _vac by Street Sweeper')
    assert(!unswept.vac, 'expected no _vac marking without the mod')
    assert(swept.closed > unswept.closed + 20,
      `expected the swept gem to reel in past magnet range (closed ${swept.closed.toFixed(0)}px vs ${unswept.closed.toFixed(0)}px)`)
    console.log(`PASS run AA.d (trashTornado): ${lvl.chunks} funnels idle on the ring, all ${lvl.chunks} pile on a lone foe (${all.funnels} funnels deal ${all.dmg} vs ${one.dmg} from ${one.funnels}) and come home, ${claimedFoes.size} take ${claimedFoes.size} distinct targets, ${lvl.hunt}px leash holds (and reaches a r80 body at hunt+40) + sweeps loot (${swept.closed.toFixed(0)}px vs ${unswept.closed.toFixed(0)}px)`)
  }

  // (e) burstHydrant: telegraph (harmless) -> eruption -> the hydrant runs as a TURRET -> gone.
  // Enemies only, never the player. Cap Blast flings and stuns; the turret hoses only the nearest
  // `streams` foes, and a zone with no jetDur (a tornSeam seam) still pops once and vanishes.
  {
    const run = weaponRun('city', 'burstHydrant')
    const lvl = WEAPONS.burstHydrant.levels[MAX_WEAPON_LEVEL - 1]
    const victim = makeStatusEnemy(run, { x: 200, y: 0, hp: 1e6, speed: 0 }) // in castRange, clear of the player
    victim.flags = []
    run.enemies.push(victim)
    let planted = null
    for (let i = 0; i < Math.round(4 / dt) && !planted; i++) {
      if (run.phase === 'levelup') { declineLevelUp(run); continue }
      stepSim(run, { x: 0, y: 0 }, dt)
      planted = run.zones[0]
    }
    assert(planted, 'expected the weapon to plant a zone')
    assert.strictEqual(planted.dur, lvl.fuse, 'expected dur to snapshot the starting fuse (render grows the warning ring from fuse/dur)')
    const hpAtPlant = victim.hp
    stepQuiet(run, 0.02)
    assert.strictEqual(victim.hp, hpAtPlant, 'expected the hydrant fuse to be a harmless telegraph')
    stepQuiet(run, lvl.fuse + 0.2)
    assert(victim.hp < hpAtPlant, `expected the eruption to damage the enemy, hp=${victim.hp}`)

    // Enemies only, NEVER the player: a hydrant erupting right on top of them does nothing at all.
    const safe = weaponRun('city', 'burstHydrant')
    safe.weapons = [] // no re-planting, no enemies: the hand-placed zone is the only thing live
    safe.player.hp = 500; safe.player.maxHP = 500; safe.player.invuln = 0
    safe.zones.push({ x: 0, y: 0, r: 150, fuse: 0.05, dur: 0.05, dmg: 999 })
    stepQuiet(safe, 0.3)
    assert.strictEqual(safe.player.hp, 500, 'expected a hydrant zone to NEVER damage the player')
    assert.strictEqual(safe.zones.length, 0, 'expected the hydrant to erupt ONCE and be removed')

    // launch: the eruption flings and stuns.
    const launch = weaponRun('city', 'burstHydrant')
    launch.weapons = []
    launch.weaponMods.burstHydrant.launch = 1
    const caught = makeStatusEnemy(launch, { x: 40, y: 0, hp: 1e6, speed: 0 })
    caught.flags = []
    launch.enemies.push(caught)
    launch.zones.push({ x: 0, y: 0, r: 100, fuse: 0.05, dur: 0.05, dmg: 10 })
    stepQuiet(launch, 0.2)
    assert(caught.stunT > 0, `expected launch to stun what it catches, stunT=${caught.stunT}`)
    assert(caught.x > 40, `expected launch to fling the enemy outward, x=${caught.x.toFixed(1)}`)

    // v6.10 TURRET: an open hydrant hoses only the nearest `nStreams` foes in range. This is the
    // property the whole rework turns on — r is a RANGE, not a damage area — so it is asserted
    // against a line of foes at known distances rather than against a count.
    const turret = weaponRun('city', 'burstHydrant')
    turret.weapons = []
    const line = [60, 120, 180, 240].map((x) => {
      const e = makeStatusEnemy(turret, { x, y: 0, hp: 1e6, speed: 0 })
      e.flags = []
      e.affixes = ['anchored']   // the streams shove what they hit; keep the distances fixed
      turret.enemies.push(e)
      return e
    })
    turret.zones.push({ x: 0, y: 0, r: 300, fuse: 0.02, dur: 0.02, dmg: 40, jetDur: 1.0, tick: 0.1, nStreams: 2 })
    // The ERUPTION is still radial — the cap blowing off is a blast, and it hits everything in r
    // once. Only the SUSTAINED hosing is aimed, so the measurement window has to start after the
    // eruption or it reads the blast and concludes the turret is a zone.
    stepQuiet(turret, 0.1)
    const hp0 = line.map((e) => e.hp)
    for (let i = 0; i < 4; i++) assert(hp0[i] < 1e6, `expected the eruption blast to hit all four in r, foe ${i} untouched`)
    stepQuiet(turret, 0.4)
    assert(line[0].hp < hp0[0] && line[1].hp < hp0[1], 'expected the two NEAREST foes to keep being hosed')
    assert.strictEqual(line[2].hp, hp0[2], 'expected the 3rd-nearest foe to take NOTHING after the blast with nStreams=2 (r is a range, not a damage area)')
    assert.strictEqual(line[3].hp, hp0[3], 'expected the 4th-nearest foe to take nothing after the blast with nStreams=2')
    // ...and it damages repeatedly over its life, not once.
    const midHp = line[0].hp
    stepQuiet(turret, 0.3)
    assert(line[0].hp < midHp, 'expected an open hydrant to keep hosing its target, not fire once')
    // ...then the main runs dry and the zone is gone.
    stepQuiet(turret, 1.2)
    assert.strictEqual(turret.zones.length, 0, 'expected the hydrant to be removed once jetDur ran out')

    // A wider nozzle reaches further down the same line: nStreams=4 hoses all four.
    const wide = weaponRun('city', 'burstHydrant')
    wide.weapons = []
    const line2 = [60, 120, 180, 240].map((x) => {
      const e = makeStatusEnemy(wide, { x, y: 0, hp: 1e6, speed: 0 })
      e.flags = []
      e.affixes = ['anchored']
      wide.enemies.push(e)
      return e
    })
    wide.zones.push({ x: 0, y: 0, r: 300, fuse: 0.02, dur: 0.02, dmg: 40, jetDur: 1.0, tick: 0.1, nStreams: 4 })
    stepQuiet(wide, 0.1)
    const hp2 = line2.map((e) => e.hp)      // after the blast, as above
    stepQuiet(wide, 0.4)
    for (let i = 0; i < 4; i++) assert(line2[i].hp < hp2[i], `expected nStreams=4 to hose foe ${i} after the blast, hp unchanged at ${line2[i].hp}`)

    // ...and Split Nozzle is what raises it: the mod must reach the PLANTED zone, which snapshots
    // stats.streams at cast time. Asserting on the zone rather than on a stats object keeps this
    // honest about the whole path (WEAPON_STAT_MODS -> effectiveWeaponStats -> the cast site).
    const nozzle = weaponRun('city', 'burstHydrant')
    nozzle.weaponMods.burstHydrant.moreStreams = 2
    const baseStreams = WEAPONS.burstHydrant.levels[MAX_WEAPON_LEVEL - 1].streams
    const foe = makeStatusEnemy(nozzle, { x: 200, y: 0, hp: 1e6, speed: 0 })
    foe.flags = []
    nozzle.enemies.push(foe)
    let plantedN = null
    for (let i = 0; i < Math.round(4 / dt) && !plantedN; i++) {
      if (nozzle.phase === 'levelup') { declineLevelUp(nozzle); continue }
      stepSim(nozzle, { x: 0, y: 0 }, dt)
      plantedN = nozzle.zones[0]
    }
    assert(plantedN, 'expected a hydrant to be planted with Split Nozzle held')
    assert.strictEqual(plantedN.nStreams, baseStreams + 2,
      `expected Split Nozzle x2 to fold into streams (${baseStreams} -> ${baseStreams + 2}), got ${plantedN.nStreams}`)
    console.log(`PASS run AA.e (burstHydrant): telegraph -> erupt (enemies only) -> turret hoses the nearest 2 of 4 in range -> dry; Cap Blast stuns; Split Nozzle ${baseStreams} -> ${plantedN.nStreams} streams`)
  }

  // (f) roar: a narrow sector sweep aimed at the NEAREST enemy that shoves; stagger stuns;
  // resonance opens every ROAR_RESONANCE_EVERY-th roar to a full circle (flagella's cyclone shape).
  {
    const run = weaponRun('skies', 'roar')
    const foe = makeStatusEnemy(run, { x: 100, y: 0, hp: 1e6, speed: 0 })
    foe.flags = []
    run.enemies.push(foe)
    let sawRoar = false
    for (let i = 0; i < Math.round(1.5 / dt); i++) {
      if (run.phase === 'levelup') { declineLevelUp(run); continue }
      stepSim(run, { x: 0, y: 0 }, dt)
      if (run.events.some((ev) => ev.type === 'roar')) sawRoar = true
    }
    assert(sawRoar, 'expected a roar event')
    assert(foe.hp < 1e6, 'expected the roar to damage what it hits')
    assert(foe.x > 100, `expected the roar to shove the foe away, x=${foe.x.toFixed(1)}`)

    // stagger: roared foes are stunned FOR THE DURATION THE CARD PROMISES. `stunT > 0` was the old
    // assertion here and it is the shape that passes with the feature broken — it held just as
    // happily at the previous 0.25s, and would hold at 0.001s. The banked bonus IS the seconds now
    // (no ROAR_STUN multiplier), so the card's number and this number are the same number, and that
    // identity is the thing worth pinning: the owner's complaint was that nothing in the game
    // stated it. First application only, where _ccDR is still 1, so ccScale contributes exactly 1.
    function peakStun(picks) {
      const r = weaponRun('skies', 'roar')
      r.weaponMods.roar.stagger = STAGGER_STUN_PER_PICK * picks
      const foe2 = makeStatusEnemy(r, { x: 100, y: 0, hp: 1e6, speed: 0 })
      foe2.flags = []
      r.enemies.push(foe2)
      let peak = 0
      for (let i = 0; i < Math.round(1.5 / dt); i++) {
        if (r.phase === 'levelup') { declineLevelUp(r); continue }
        stepSim(r, { x: 0, y: 0 }, dt)
        r.events.length = 0
        peak = Math.max(peak, foe2.stunT ?? 0)
      }
      return peak
    }
    // LITERAL expectations, deliberately not derived from STAGGER_STUN_PER_PICK. Deriving them made
    // this a tautology — halving the constant moved the expectation with it and the mutation passed.
    // 0.35s per pick is an owner directive, so it is pinned here; changing it should require editing
    // this line too, which is the point.
    assert.strictEqual(STAGGER_STUN_PER_PICK, 0.35, 'Stagger is specified at 0.35s per normal pick')
    // Sampled after stepSim, so the observed peak has already ticked down by up to one frame.
    for (const [picks, want] of [[1, 0.35], [2, 0.70], [4, 1.40]]) {
      const got = peakStun(picks)
      assert(got > want - 2 * dt && got <= want + 1e-9,
        `expected ${picks} Stagger pick(s) to stun for ${want.toFixed(2)}s, got ${got.toFixed(3)}s`)
    }
    // Stagger is the gate — the roar does not stun on its own. NOT mutation-provable (a zero bonus
    // yields a zero duration whatever the gate does), so this is documentation of intent, and it
    // becomes load-bearing the moment anyone gives the roar a base stun.
    assert.strictEqual(peakStun(0), 0, 'the roar must not stun without the Stagger mod')

    // resonance: an in-range foe BEHIND the aim anchor is only ever reached by the 360° roar.
    function behindHp(resonance) {
      const r = weaponRun('skies', 'roar')
      if (resonance) r.weaponMods.roar.resonance = 1
      // The anchor pins the aim +x. It must be 'anchored': the roar's own shove would otherwise
      // walk it past the behind foe, which would flip "nearest" and hand the aim to the wrong side.
      r.enemies.push(makeStatusEnemy(r, { x: 60, y: 0, hp: 1e9, speed: 0, affixes: ['anchored'] }))
      const behind = makeStatusEnemy(r, { x: -100, y: 0, hp: 1e6, speed: 0 })
      behind.flags = []
      r.enemies.push(behind)
      stepQuiet(r, (ROAR_RESONANCE_EVERY + 2) * 0.7)
      return behind.hp
    }
    const withRes = behindHp(true), without = behindHp(false)
    assert.strictEqual(without, 1e6, `expected no resonance to never reach the behind foe (hp ${without})`)
    assert(withRes < 1e6, `expected resonance's 360° roar to reach the behind foe (hp ${withRes})`)
    console.log(`PASS run AA.f (roar): sweeps + shoves, stagger stuns, resonance reaches behind (${withRes.toFixed(0)} vs ${without.toFixed(0)})`)
  }

  // (g) tailLash (v7.23, replaces Tail Swipe): a long thin line at the FARTHEST target, which drags
  // aircraft down to be crushed and leaves everything else exactly where it stands. wreckingBall
  // makes the dragged body hurt what it passes; counterLash lashes for free when the player is hit.
  {
    const run = weaponRun('skies', 'tailLash')
    const plane = makeStatusEnemy(run, { x: 300, y: 0, hp: 1e6, speed: 0 })
    plane.flags = ['crushable']
    run.enemies.push(plane)
    let sawTail = false
    for (let i = 0; i < Math.round(2 / dt); i++) {
      if (run.phase === 'levelup') { declineLevelUp(run); continue }
      stepSim(run, { x: 0, y: 0 }, dt)
      if (run.events.some((ev) => ev.type === 'tail')) sawTail = true
    }
    assert(sawTail, 'expected a tail event')
    assert(plane.hp < 1e6, 'expected the lash to damage what the line crosses')
    assert(plane.x < 300, `expected the lash to DRAG the aircraft inward, x=${plane.x.toFixed(1)}`)

    // THE OWNER'S CONSTRAINT, and the assertion that must never regress: "it should not pull tanks
    // since they deal dmg". Ground armour takes the line damage and does not move one pixel.
    // Both halves are asserted — a gate that silenced the weapon entirely would pass "did not move".
    {
      const r = weaponRun('skies', 'tailLash')
      const tank = makeStatusEnemy(r, { x: 300, y: 0, hp: 1e6, speed: 0 })
      tank.flags = ['unshakeable']   // a tank column: NOT crushable
      r.enemies.push(tank)
      const x0 = tank.x, y0 = tank.y
      stepQuiet(r, 2.0)
      assert(tank.hp < 1e6, 'expected the lash to still DAMAGE a tank it crosses — it just must not move it')
      assert.strictEqual(tank.x, x0, `a tank was dragged to x=${tank.x.toFixed(1)} from ${x0} — it deals contact damage, so pulling it to the player is self-harm`)
      assert.strictEqual(tank.y, y0, `a tank was dragged off its line to y=${tank.y.toFixed(1)}`)
    }

    // Aims at the FARTHEST, not the nearest — the inverse of every other weapon, and the whole
    // point of the rework (the chapter's enemies are built to stand off).
    {
      const r = weaponRun('skies', 'tailLash')
      const near = makeStatusEnemy(r, { x: 0, y: 60, hp: 1e6, speed: 0 })
      const far = makeStatusEnemy(r, { x: 320, y: 0, hp: 1e6, speed: 0 })
      near.flags = ['crushable']; far.flags = ['crushable']
      r.enemies.push(near, far)
      stepQuiet(r, 2.0)
      assert(far.x < 320, `expected the FARTHEST aircraft hooked, but it sat still at x=${far.x.toFixed(1)}`)
    }

    // wreckingBall: a bystander standing along the drag path takes collateral it otherwise would not.
    function bystanderHp(wrecking) {
      const r = weaponRun('skies', 'tailLash')
      if (wrecking) r.weaponMods.tailLash.wreckingBall = 0.40
      // The aircraft is hooked at 320px and reeled to the player; the bystander sits at y=45, off
      // the lash line itself (so the line can never hit it) but inside LASH_DRAG_R of the path home.
      const plane2 = makeStatusEnemy(r, { x: 320, y: 0, hp: 1e9, speed: 0 })
      plane2.flags = ['crushable']
      const bystander = makeStatusEnemy(r, { x: 160, y: 30, hp: 1e6, speed: 0 })
      bystander.flags = ['unshakeable']
      r.enemies.push(plane2, bystander)
      stepQuiet(r, 2.0)
      return bystander.hp
    }
    const wrecked = bystanderHp(true), clean = bystanderHp(false)
    assert(wrecked < clean, `expected wreckingBall collateral along the drag path (${clean} -> ${wrecked})`)

    // counterLash: getting hurt lashes for free, off the weapon timer.
    const ctr = weaponRun('skies', 'tailLash')
    ctr.player.hp = 500; ctr.player.maxHP = 500; ctr.player.invuln = 0
    ctr.weaponMods.tailLash.counterLash = 1
    ctr.weaponTimers.tailLash = 1e6 // park the timer: any lash now can only be the counter
    const hitMe = makeStatusEnemy(ctr, { x: 200, y: 0, hp: 1e6, speed: 0 })
    hitMe.flags = []
    ctr.enemies.push(hitMe)
    ctr.bombs.push({ x: 0, y: 0, radius: 60, fuse: 0.01, duration: 0.01, dmg: 5 }) // hurt the player
    stepQuiet(ctr, 0.1)
    assert(ctr.events.some((ev) => ev.type === 'tail') || hitMe.hp < 1e6, 'expected counterLash to lash when the player is hurt')
    console.log(`PASS run AA.g (tailLash): drags aircraft only, tanks never move, aims farthest, wreckingBall (${clean} -> ${wrecked}), counterLash`)
  }

  // (g2) atomicBreath (v7.23): charges, then FORKS from body to body, rebuilding the chain every
  // tick. Asserts the effects, never that a field moved — a count of live arcs would pass with the
  // damage deleted.
  {
    // A line of enemies 120px apart: the root is nearest, then each fork reaches the next.
    const chainRun = (jumps, n = 6) => {
      const r = weaponRun('skies', 'atomicBreath')
      r.weapons = [{ id: 'atomicBreath', level: 5 }]   // L5: jumps 5, arcRange 200
      const foes = []
      for (let i = 0; i < n; i++) {
        const e = makeStatusEnemy(r, { x: 120 * (i + 1), y: 0, hp: 1e9, speed: 0 })
        e.flags = []
        foes.push(e)
      }
      r.enemies.push(...foes)
      if (jumps != null) r.weapons[0].level = jumps
      return { r, foes }
    }

    // The charge is DEAD TIME: nothing takes damage during BREATH_CHARGE_T.
    {
      const { r, foes } = chainRun(null, 3)
      r.weaponTimers.atomicBreath = 0.0001   // fire almost immediately
      stepQuiet(r, 0.0001 + BREATH_CHARGE_T * 0.6)
      assert(foes.every((e) => e.hp === 1e9),
        `an enemy took damage during the breath's charge — the wind-up must be a real telegraph, not decoration`)
    }

    // It forks: with 6 enemies chained inside arcRange, more than one takes damage, and the reach
    // stops at jumps + 1 bodies.
    {
      const { r, foes } = chainRun(null, 6)
      stepQuiet(r, 8)
      const touched = foes.filter((e) => e.hp < 1e9).length
      assert(touched > 1, `the breath hit ${touched} of 6 chained enemies — it is not forking at all`)
      // Damage DECAYS along the chain: the root must take strictly more than the last body reached.
      const reached = foes.filter((e) => e.hp < 1e9)
      const first = 1e9 - reached[0].hp, last = 1e9 - reached[reached.length - 1].hp
      assert(first > last, `the fork dealt ${first.toFixed(0)} at the root and ${last.toFixed(0)} at the tail — damage is not decaying per jump`)
    }

    // Out of arcRange is out of the fork: a body parked past the gap takes nothing.
    {
      const r = weaponRun('skies', 'atomicBreath')
      r.weapons = [{ id: 'atomicBreath', level: 5 }]
      const near = makeStatusEnemy(r, { x: 100, y: 0, hp: 1e9, speed: 0 })
      const island = makeStatusEnemy(r, { x: 900, y: 0, hp: 1e9, speed: 0 })  // >> arcRange 200 from anything
      near.flags = []; island.flags = []
      r.enemies.push(near, island)
      stepQuiet(r, 8)
      assert(near.hp < 1e9, 'the breath never connected at all — this fixture proves nothing')
      assert.strictEqual(island.hp, 1e9, 'a body far beyond arcRange took fork damage — the fork range gate is not holding')
    }
    // v7.25, the owner's three corrections. All three shipped wrong in v7.23 and NONE of them was
    // guarded, which is why they reached him: every assertion above is about what happens once a
    // fork exists, and all three faults are about whether one ever does.
    {
      // (1) "It should charge even if no enemies around." An EMPTY world must still wind up.
      const r = weaponRun('skies', 'atomicBreath')
      r.weapons = [{ id: 'atomicBreath', level: 5 }]
      r.enemies.length = 0
      r.mods.spawnMul = 0
      // Comfortably past one full cycle (interval 1.90 at L5) — fireOnTimer starts its timer at a
      // full interval, so a window shorter than that proves nothing either way. Generous on purpose
      // so THIS case keeps testing "charges with no target" rather than incidentally testing the
      // cadence; the idle-fraction case below is what owns the cadence.
      stepQuiet(r, 5.0)
      assert(r.arcs.length > 0, 'the breath must charge with no enemies around — it waited for a target instead')
      assert(r.enemies.length === 0, 'the empty-world fixture spawned enemies — it is no longer testing an empty world')
    }
    {
      // (2) "Discharge to closest enemy." A lone enemy well beyond arcRange (200 at L5) but inside
      // the weapon's own `range` (340) must still be struck. This is the actual v7.23 bug: the ROOT
      // was picked within arcRange of the player, so the breath discharged into empty ground.
      const L5 = WEAPONS.atomicBreath.levels[4]
      const r = weaponRun('skies', 'atomicBreath')
      r.weapons = [{ id: 'atomicBreath', level: 5 }]
      const far = makeStatusEnemy(r, { x: 300, y: 0, hp: 1e9, speed: 0 })
      far.flags = []
      r.enemies.push(far)
      assert(300 > L5.arcRange && 300 < L5.range,
        `this case is only meaningful BETWEEN arcRange (${L5.arcRange}) and range (${L5.range}) — the fixture has drifted`)
      stepQuiet(r, 6)
      assert(far.hp < 1e9,
        `a lone enemy at 300px — outside arcRange but inside the weapon's ${L5.range}px range — took nothing. arcRange governs the JUMPS between bodies, not how far the breath reaches for its FIRST target`)
    }
    {
      // (3) "Start charging again as soon as it finished firing." No dead air: sample every frame
      // over several cycles and assert the weapon is never idle for long. Asserted as an EFFECT
      // (frames with no live breath) rather than by reading the timer, which would pass with the
      // cycle broken. The small allowance is the single frame where one expires before the next
      // starts.
      const r = weaponRun('skies', 'atomicBreath')
      r.weapons = [{ id: 'atomicBreath', level: 5 }]
      const foe = makeStatusEnemy(r, { x: 120, y: 0, hp: 1e12, speed: 0 })
      foe.flags = []
      r.enemies.push(foe)
      stepQuiet(r, 2) // let the first cycle settle
      let idle = 0, frames = 0, maxLive = 0
      for (let i = 0; i < Math.round(10 / dt); i++) {
        stepSim(r, { x: 0, y: 0 }, dt); r.events.length = 0
        frames++
        if (r.arcs.length === 0) idle++
        maxLive = Math.max(maxLive, r.arcs.length)
      }
      assert(idle / frames < 0.05,
        `the breath was idle on ${(100 * idle / frames).toFixed(0)}% of frames — it must re-charge the moment it finishes firing, not wait out an interval`)
      assert.strictEqual(maxLive, 1, `${maxLive} breaths were live at once at base rate`)
    }
    {
      // ...and the guard that makes a zero-gap cycle SAFE, which needs a FAST build to expose. At
      // base rate `interval` equals charge + duration exactly, so nothing overlaps whether the
      // guard exists or not — deleting it passed every assertion above. quickBreath divides the
      // interval below the cycle length, and without the guard a second breath then starts on top
      // of one still burning: double damage from one weapon, drawn as a single thicker fork, which
      // is precisely the "same hit, bigger" shape that is invisible in a screenshot.
      const r = weaponRun('skies', 'atomicBreath')
      r.weapons = [{ id: 'atomicBreath', level: 5 }]
      r.weaponMods.atomicBreath = { quickBreath: 1.0 }   // interval 1.90 -> 0.95, well under the cycle
      const foe = makeStatusEnemy(r, { x: 120, y: 0, hp: 1e12, speed: 0 })
      foe.flags = []
      r.enemies.push(foe)
      let maxLive = 0
      for (let i = 0; i < Math.round(12 / dt); i++) {
        stepSim(r, { x: 0, y: 0 }, dt); r.events.length = 0
        maxLive = Math.max(maxLive, r.arcs.length)
      }
      assert.strictEqual(maxLive, 1,
        `${maxLive} breaths were live at once on a fast build — overlapping forks are double damage from one weapon, and they draw as one`)
    }
    console.log('PASS run AA.g2 (atomicBreath): charges with no enemies, reaches the closest on screen past arcRange, cycles with no dead air and never overlaps, charge is dead time, damage decays per jump')
  }

  // (h) debrisToss: chunks arc onto foes (run.lobs, t counting UP to flight) and burst ONCE on
  // landing — enemies only. shrapnel scatters splinters as run.bullets tagged 'debris'.
  {
    const run = weaponRun('skies', 'debrisToss')
    const victim = makeStatusEnemy(run, { x: 200, y: 0, hp: 1e6, speed: 0 }) // in castRange, clear of the player
    victim.flags = []
    run.enemies.push(victim)
    let lob = null
    for (let i = 0; i < Math.round(4 / dt) && !lob; i++) {
      if (run.phase === 'levelup') { declineLevelUp(run); continue }
      stepSim(run, { x: 0, y: 0 }, dt)
      lob = run.lobs[0]
    }
    assert(lob, 'expected the weapon to lob a chunk')
    assert(lob.t >= 0 && lob.t < lob.flight, `expected t counting UP toward flight, t=${lob.t}`)
    const hpAtLob = victim.hp
    stepQuiet(run, lob.flight + 0.1)
    assert(victim.hp < hpAtLob, `expected the chunk to burst on the enemy, hp=${victim.hp}`)

    // Enemies only, NEVER the player: a chunk landing right on them does nothing at all.
    const safe = weaponRun('skies', 'debrisToss')
    safe.weapons = [] // no re-throwing, no enemies: the hand-placed lob is the only thing live
    safe.player.hp = 500; safe.player.maxHP = 500; safe.player.invuln = 0
    safe.lobs.push({ x: 0, y: 0, fromX: 0, fromY: 0, tx: 0, ty: 0, t: 0, flight: 0.05, r: 150, dmg: 999 })
    stepQuiet(safe, 0.3)
    assert.strictEqual(safe.player.hp, 500, 'expected a lob to NEVER damage the player')
    assert.strictEqual(safe.lobs.length, 0, 'expected the chunk to burst ONCE and be removed')

    // shrapnel: the impact scatters splinters.
    const shr = weaponRun('skies', 'debrisToss')
    shr.weapons = []
    shr.weaponMods.debrisToss.shrapnel = 3
    shr.lobs.push({ x: 0, y: 0, fromX: 0, fromY: 0, tx: 100, ty: 0, t: 0, flight: 0.05, r: 80, dmg: 30 })
    stepQuiet(shr, 0.2)
    const splinters = shr.bullets.filter((b) => b.weapon === 'debris')
    assert.strictEqual(splinters.length, 3, `expected 3 shrapnel splinters, got ${splinters.length}`)
    console.log('PASS run AA.h (debrisToss): lobs arc + burst on enemies only; shrapnel scatters')
  }

  // (i) realityShard: shards SKIP through space (a blink jumps blinkDist along the heading without
  // sweeping the gap). tornSeam cuts a _chained SEAM spanning that skip; recursion forks a shard
  // whose LIFE expired.
  {
    const run = weaponRun('beyond', 'realityShard')
    run.enemies.push(makeStatusEnemy(run, { x: 400, y: 0, hp: 1e9, speed: 0 }))
    let shard = null
    for (let i = 0; i < Math.round(2 / dt) && !shard; i++) {
      if (run.phase === 'levelup') { declineLevelUp(run); continue }
      stepSim(run, { x: 0, y: 0 }, dt)
      shard = run.bullets.find((b) => b.weapon === 'shard')
    }
    assert(shard, 'expected the weapon to fire shards')
    const lvl = WEAPONS.realityShard.levels[MAX_WEAPON_LEVEL - 1]
    // Across one blinkEvery window a shard covers its own flight PLUS a whole blinkDist jump.
    const x0 = shard.x
    stepQuiet(run, lvl.blinkEvery + 0.02)
    const covered = shard.x - x0
    const flown = lvl.speed * (lvl.blinkEvery + 0.02)
    assert(covered > flown + lvl.blinkDist * 0.9, `expected a blink to skip ~${lvl.blinkDist}px on top of the flight (covered=${covered.toFixed(1)}, flown=${flown.toFixed(1)})`)

    // tornSeam: each blink splits the gap it skipped into a _chained seam.
    const rift = weaponRun('beyond', 'realityShard')
    rift.weaponMods.realityShard.tornSeam = 0.50
    rift.enemies.push(makeStatusEnemy(rift, { x: 400, y: 0, hp: 1e9, speed: 0 }))
    // Sample WHILE stepping: a rift's whole life is SHARD_RIFT_FUSE, so it plants, erupts and is
    // gone well inside any window long enough to have produced one.
    let rifts = []
    for (let i = 0; i < Math.round(2 / dt) && rifts.length === 0; i++) {
      if (rift.phase === 'levelup') { declineLevelUp(rift); continue }
      stepSim(rift, { x: 0, y: 0 }, dt)
      rifts = rift.zones.slice()
    }
    assert(rifts.length > 0, 'expected tornSeam to leave seams at blink departure points')
    for (const g of rifts) assert.strictEqual(g._chained, true, 'expected seams flagged _chained (the "not a Burst Hydrant cast" marker)')
    for (const g of rifts) assert(g.d > 0, 'expected each seam to carry the skip length it spans')

    // v7.29: the SEAM is the hitbox, not a disc at the departure point. Both probes below are
    // OUTSIDE any disc the old shape could have drawn (SHARD_RIFT_W is 32, and the disc it replaced
    // was 55), so this passes only if stepZones really hit-tests the capsule:
    //   far — standing where the shard came OUT, 100px along the seam. Cut.
    //   off — 90px off to the side of that same seam, level with its middle. Untouched.
    // Mutation-proved: reverting stepZones to the plain disc leaves `far` on full HP.
    const cut = weaponRun('beyond', 'realityShard')
    cut.weapons = []
    const far = makeStatusEnemy(cut, { x: 100, y: 0, hp: 1e9, speed: 0 })
    const off = makeStatusEnemy(cut, { x: 50, y: 90, hp: 1e9, speed: 0 })
    cut.enemies.push(far, off)
    cut.zones.push({
      x: 0, y: 0, r: SHARD_RIFT_W, fuse: SHARD_RIFT_FUSE, dur: SHARD_RIFT_FUSE,
      dmg: 100, _chained: true, a: 0, d: 100,
    })
    const farHP = far.hp, offHP = off.hp
    stepQuiet(cut, SHARD_RIFT_FUSE + 0.05)
    assert(far.hp < farHP, 'expected the seam to cut at its far mouth, 100px from the zone origin')
    assert.strictEqual(off.hp, offHP, 'expected an enemy 90px off the seam to be untouched')

    // recursion: a shard that runs out of LIFE forks into _fork shards.
    const rec = weaponRun('beyond', 'realityShard')
    rec.weapons = []
    rec.weaponMods.realityShard.recursion = 2
    rec.bullets.push({
      x: 0, y: 0, vx: 380, vy: 0, dmg: 13, pierce: 1, life: 0.02, r: 9, speed: 380,
      hitIds: new Set(), weapon: 'shard', _blinkCd: 99, _blinkEvery: 0.28, _blinkDist: 70, _life0: 0.8,
      _shard: false, _splitDone: true, _chainsLeft: 0,
    })
    stepQuiet(rec, 0.05)
    const forks = rec.bullets.filter((b) => b._fork)
    assert.strictEqual(forks.length, 2, `expected recursion to fork 2 shards on life expiry, got ${forks.length}`)
    stepQuiet(rec, 1.0)
    assert.strictEqual(rec.bullets.filter((b) => b._fork).length, 0, 'expected forks to expire without re-forking')
    console.log(`PASS run AA.i (realityShard): blink skips ${(covered - flown).toFixed(0)}px, tornSeam cuts a ${rifts[0].d}px seam that reaches its far mouth and not 90px off it, recursion forks once`)
  }

  // (j) pulsarSweep: ONE swept run.beams entry sweeping PULSAR_ARMS arms at once (a plain
  // Neon Beam rakes only the one it points at); collapse damages + yanks everything in any arm.
  {
    const run = weaponRun('beyond', 'pulsarSweep')
    const front = makeStatusEnemy(run, { x: 150, y: 0, hp: 1e9, speed: 0 }) // aim anchor
    const back = makeStatusEnemy(run, { x: -150, y: 0, hp: 1e6, speed: 0 }) // the FOLD's other arm
    front.flags = []; back.flags = []
    run.enemies.push(front, back)
    let beam = null
    for (let i = 0; i < Math.round(6 / dt) && !beam; i++) { // the cast cadence is ~4.5s at max
      if (run.phase === 'levelup') { declineLevelUp(run); continue }
      stepSim(run, { x: 0, y: 0 }, dt)
      beam = run.beams[0]
    }
    assert(beam, 'expected the weapon to cast a beam')
    assert.strictEqual(beam.swept, true, 'expected the cast flagged swept')
    assert.strictEqual(beam.arms, PULSAR_ARMS, `expected ${PULSAR_ARMS} arms on a plain cast, got ${beam.arms}`)

    // The opposed pair itself, isolated: a non-rotating swept beam aimed +x rakes BOTH sides at once,
    // where the plain (unswept) Neon Beam of the same shape only ever rakes the side it points at.
    // (Left to sweep, any beam eventually crosses everything — that would prove nothing.)
    function farSideHp(swept) {
      const r = weaponRun('beyond', 'pulsarSweep')
      r.weapons = []
      const far = makeStatusEnemy(r, { x: -150, y: 0, hp: 1e6, speed: 0 })
      far.flags = []
      r.enemies.push(far)
      r.beams.push({
        angle: 0, life: 0.5, duration: 0.5, dmg: 22, tick: 0.05, width: 46, length: 430,
        rotSpeed: 0, acc: 0, ...(swept ? { swept: true, arms: PULSAR_ARMS } : {}),
      })
      stepQuiet(r, 0.3)
      return far.hp
    }
    const sweptFar = farSideHp(true), plainFar = farSideHp(false)
    assert.strictEqual(plainFar, 1e6, `expected an unswept beam to never reach the far side (hp ${plainFar})`)
    assert(sweptFar < 1e6, `expected the opposite arm to rake the far side too, hp=${sweptFar}`)

    // hyperSweep adds arms; collapse detonates + yanks when the sweep ends.
    const col = weaponRun('beyond', 'pulsarSweep')
    col.weapons = []
    col.weaponMods.pulsarSweep.collapse = 0.80
    const caught = makeStatusEnemy(col, { x: 150, y: 0, hp: 1e6, speed: 0 })
    caught.flags = []
    col.enemies.push(caught)
    col.beams.push({
      angle: 0, life: 0.05, duration: 2, dmg: 22, tick: 99, width: 46, length: 430,
      rotSpeed: 0, acc: 0, swept: true, arms: PULSAR_ARMS, collapseBonus: 0.80,
    })
    stepQuiet(col, 0.1)
    assert(caught.hp < 1e6, `expected collapse to detonate on what the sweep held, hp=${caught.hp}`)
    assert(caught.kb.x < 0, `expected collapse to yank the foe toward the player, kb.x=${caught.kb.x.toFixed(1)}`)
    assert(col.events.some((ev) => ev.type === 'explode'), 'expected collapse to emit an explode at the player')

    const hyper = weaponRun('beyond', 'pulsarSweep')
    hyper.weaponMods.pulsarSweep.hyperSweep = 2
    stepQuiet(hyper, 6.0)
    assert(hyper.beams.length > 0, 'expected the hyperSweep cast to land')
    assert.strictEqual(hyper.beams[0].arms, PULSAR_ARMS + 2, `expected hyperSweep to add arms, got ${hyper.beams[0].arms}`)
    console.log(`PASS run AA.j (pulsarSweep): ${beam.arms} arms rake at once, hyperSweep adds more, collapse detonates + yanks`)
  }

  // (k) each v5.4 chapter's level-up pool offers ONLY its own natives, as weapon AND mod cards
  // (run U.c / W.f / X.g, extended to the four new chapters — this is what routes the new weapons
  // through weaponCandidates/buildLevelUpChoices at all).
  {
    for (const chapter of ['undergrowth', 'city', 'skies', 'beyond']) {
      const allowed = new Set(CHAPTERS[chapter].weapons)
      const fresh = createRun(makeMeta(), { chapter })
      fresh.choiceSlots = 4
      let sawWeapon = false
      for (let i = 0; i < 400; i++) {
        for (const c of buildLevelUpChoices(fresh)) {
          if (c.kind !== 'weapon') continue
          sawWeapon = true
          assert(allowed.has(c.id), `expected a ${chapter} run to only offer its natives, got weapon '${c.id}'`)
        }
      }
      assert(sawWeapon, `expected at least one weapon card over 400 ${chapter} pools`)

      const owned = createRun(makeMeta(), { chapter })
      owned.weapons = CHAPTERS[chapter].weapons.map((id) => ({ id, level: 3 }))
      owned.choiceSlots = 4
      let sawMod = false
      for (let i = 0; i < 400; i++) {
        for (const c of buildLevelUpChoices(owned)) {
          if (c.kind !== 'mod') continue
          assert(allowed.has(c.weapon), `expected only ${chapter} weapon mods, got a '${c.weapon}' mod`)
          sawMod = true
        }
      }
      assert(sawMod, `expected ${chapter} weapon mods to appear over 400 pools`)
    }
    console.log('PASS run AA.k (pools): undergrowth/city/skies/beyond each offer only their own natives + mods')
  }

  // Balance bands (run W/X style): in every new chapter, the starter + 2 mods must clear a realistic
  // converging ring no slower than 3.5x that chapter's median native. Kill-time on a converging ring,
  // NOT an immortal-ring DPS race (the v4.4 lesson).
  {
    function measureTTK(weaponId, applyMods) {
      const run = createRun(makeMeta()) // body chapter: no signature/obstacles skewing the clear
      run.weapons = [{ id: weaponId, level: MAX_WEAPON_LEVEL }]
      run.mods.spawnMul = 0
      run.player.hp = 1e9; run.player.maxHP = 1e9
      if (applyMods) applyMods(run)
      const N = 14, radius = 150, hp = 50
      for (let i = 0; i < N; i++) {
        const a = (i / N) * Math.PI * 2
        run.enemies.push(makeStatusEnemy(run, { x: Math.cos(a) * radius, y: Math.sin(a) * radius, hp, speed: 45 }))
      }
      let t = 0
      const cap = 60
      for (let i = 0; i < Math.round(cap / dt); i++) {
        if (run.phase === 'levelup') { declineLevelUp(run); continue }
        t += dt
        // Pin the player: enemies converge on the origin, and no weapon may drift them off it.
        run.player.x = 0; run.player.y = 0
        stepSim(run, { x: 0, y: 0 }, dt)
        if (run.enemies.length === 0) return t
      }
      return cap
    }
    // { chapter: [[weaponId, mods], ...] } — the first entry of each is that chapter's STARTER.
    const bands = {
      undergrowth: [
        ['clawRake', (r) => { r.weaponMods.clawRake.rend = 0.35; r.weaponMods.clawRake.wideRake = 0.30 }],
        ['quillBurst', (r) => { r.weaponMods.quillBurst.sharpQuills = 0.25; r.weaponMods.quillBurst.moreQuills = 2 }],
        ['chitterShriek', (r) => { r.weaponMods.chitterShriek.shrill = 0.30; r.weaponMods.chitterShriek.shockwave = 0.30 }],
      ],
      city: [
        ['rainbow', (r) => { r.weaponMods.rainbow.wideBeam = 0.20; r.weaponMods.rainbow.longBeam = 0.20 }],
        ['trashTornado', (r) => { r.weaponMods.trashTornado.heavyTrash = 0.25; r.weaponMods.trashTornado.moreTrash = 1 }],
        ['burstHydrant', (r) => { r.weaponMods.burstHydrant.pressure = 0.30; r.weaponMods.burstHydrant.longHose = 0.30 }],
      ],
      skies: [
        ['roar', (r) => { r.weaponMods.roar.bellow = 0.30; r.weaponMods.roar.wideRoar = 0.30 }],
        ['tailLash', (r) => { r.weaponMods.tailLash.heavyTail = 0.30; r.weaponMods.tailLash.longTail = 0.30 }],
        ['debrisToss', (r) => { r.weaponMods.debrisToss.heavyDebris = 0.30; r.weaponMods.debrisToss.bigImpact = 0.30 }],
      ],
      beyond: [
        ['realityShard', (r) => { r.weaponMods.realityShard.keenShard = 0.25; r.weaponMods.realityShard.moreShards = 1 }],
        ['hole', (r) => { r.weaponMods.hole.biggerHole = 0.20; r.weaponMods.hole.denser = 0.20 }],
        ['pulsarSweep', (r) => { r.weaponMods.pulsarSweep.wideSweep = 0.20; r.weaponMods.pulsarSweep.longFold = 0.20 }],
      ],
    }
    for (const [chapter, entries] of Object.entries(bands)) {
      const ttks = entries.map(([id, mods]) => [id, measureTTK(id, mods)])
      const [starterId, starterTTK] = ttks[0]
      const others = ttks.slice(1).map(([, t]) => t).sort((a, b) => a - b)
      const median = others[Math.floor(others.length / 2)]
      for (const [id, t] of ttks) {
        assert(t < 60, `expected ${chapter}'s ${id} to clear the ring within the cap, got ${t.toFixed(1)}s`)
      }
      assert(starterTTK <= median * 3.5,
        `expected ${chapter}'s starter within 3.5x the chapter median (${starterId}=${starterTTK.toFixed(1)}s, median=${median.toFixed(1)}s, ratio=${(starterTTK / median).toFixed(2)})`)
      console.log(`PASS run AA (${chapter} balance band): ${ttks.map(([id, t]) => `${id}TTK=${t.toFixed(1)}s`).join(' ')} ratio=${(starterTTK / median).toFixed(2)}x`)
    }
  }
}

// Skies procedural districts (v5.7.x piece 4): districtAt/districtTintAt are pure world-XY
// helpers with no Pixi/DOM deps (they live in config.js precisely so they're testable here).
// Checks per the design doc: deterministic per (x, y, seed); varied across a wide sweep (not one
// constant type, and sea shows up somewhere); and the floor tint is CONTINUOUS crossing a border
// (no jump bigger than a small epsilon in one small step) rather than hard-cutting.
function testDistricts() {
  const seed = 1234567

  // deterministic: same (x, y, seed) -> same district, called twice
  for (const [x, y] of [[0, 0], [15000, -8000], [-3000, 40000], [999999, 999999]]) {
    assert.strictEqual(districtAt(x, y, seed), districtAt(x, y, seed), `expected districtAt(${x},${y}) to be deterministic`)
  }
  assert.strictEqual(districtTintAt(5000, -5000, seed), districtTintAt(5000, -5000, seed), 'expected districtTintAt to be deterministic')

  // varied: a wide sweep across world-XY should hit more than one district type (not a constant),
  // every type returned must be a real DISTRICTS key, and sea must show up somewhere (the
  // low-frequency clustering bias shouldn't make it vanish).
  const seen = new Set()
  // v5.11: the sweep is sized against CITY_GRID (the terrain generator's coarsest feature lattice)
  // rather than the retired Voronoi DISTRICT_GRID. The step is deliberately NOT a divisor of any
  // generator wavelength, so the sample can't accidentally ride one phase of the noise.
  const SPAN = CITY_GRID * 7
  const STEP = CITY_GRID * 0.31
  for (let x = -SPAN; x <= SPAN; x += STEP) {
    for (let y = -SPAN; y <= SPAN; y += STEP) seen.add(districtAt(x, y, seed))
  }
  assert(seen.size > 1, `expected districtAt to return varied types across a wide sweep, got only ${[...seen]}`)
  for (const t of seen) assert(t in DISTRICTS, `unexpected district type from districtAt: ${t}`)
  assert(seen.has('sea'), `expected sea to appear somewhere over a wide sweep, got ${[...seen]}`)
  // v5.9 top-down region overhaul grew DISTRICTS from 4 types to 6 (farms, hills) — pin both
  // reachable over the same sweep, the same way sea already was above, so a future weight/bias
  // change that starves one of them out doesn't slip past silently.
  assert(seen.has('farms'), `expected farms to appear somewhere over a wide sweep, got ${[...seen]}`)
  assert(seen.has('hills'), `expected hills to appear somewhere over a wide sweep, got ${[...seen]}`)
  // v5.11 added two biomes (desert, beach) and the report asked for deserts by name. Pin them the
  // same way, so a threshold change in terrain.js that quietly starves one out fails here.
  assert(seen.has('desert'), `expected desert to appear somewhere over a wide sweep, got ${[...seen]}`)
  assert(seen.has('beach'), `expected beach to appear somewhere over a wide sweep, got ${[...seen]}`)
  assert(seen.has('downtown'), `expected downtown to appear somewhere over a wide sweep, got ${[...seen]}`)

  // continuous blend: walk a straight line crossing several district borders in small steps;
  // districtTintAt must never jump by more than a small epsilon per step (no hard pop at a
  // Voronoi edge). Decompose the packed int to RGB channels since that's what "jump" means here.
  const channel = (c, shift) => (c >> shift) & 255
  let prev = districtTintAt(-SPAN, 777, seed)
  let maxJump = 0
  const lineStep = 8 // px — much smaller than DISTRICT_BLEND_PX, so a real border shows as many small steps, not one leap
  for (let x = -SPAN + lineStep; x <= SPAN; x += lineStep) {
    const cur = districtTintAt(x, 777, seed)
    for (const shift of [16, 8, 0]) maxJump = Math.max(maxJump, Math.abs(channel(cur, shift) - channel(prev, shift)))
    prev = cur
  }
  assert(maxJump <= 50, `expected districtTintAt to blend continuously across borders, got a ${maxJump}-level (of 255) jump in one ${lineStep}px step`)

  console.log(`PASS run BB (districts): ${seen.size} distinct types over the sweep (${[...seen].join(',')}), sea present, max per-step tint jump ${maxJump}/255`)
}

// ---- Run CC: v5.8 kaiju redesign (skies crushing, rampage, density) ---------------------
// Design doc §7 flags that the EXISTING suite is structurally blind to all of this: run W/X/AA's
// balance bands run `createRun(makeMeta())` (the body chapter, no obstacles), makeStatusEnemy
// bypasses spawnEnemy, and every skies behavior check in run Y/AA drives `flagRun`, which does
// `run.obstacles = []; run._obstacleSeed = null` — blanking the exact field stepCrush/stepRampage
// are gated on. None of those tests can see crushing, rampage, or the new density, because all
// three only exist for CHAPTERS[chapter].crush, and every existing skies test nulls it out.
// These scenarios build real `createRun(meta, {chapter:'skies'})` runs and let the field stream
// for real — NOT flagRun.
function testSkiesKaiju() {
  const dt = 1 / 60

  // A quiet, LIVE skies run: real chapter (obstacles stream for real, crush/rampage are gated on),
  // no weapons/spawns/bombardment noise. The obstacle field itself is left completely alone.
  function skiesRun() {
    const run = createRun(makeMeta(), { chapter: 'skies' })
    run.weapons = []; run.mods.spawnMul = 0; run._bombardAcc = 1e6 // park the signature, not the field
    run.player.x = 0; run.player.y = 0; run.player.hp = 1e9; run.player.maxHP = 1e9
    return run
  }

  // (a) crush on contact: a live structure overlapping the player is destroyed OUTRIGHT — spliced
  // from run.obstacles, _obstacleRev bumped (so render knows to rebuild), a {type:'crush'} event
  // carrying the structure's kind, xp dropped into run.gems via the same path a kill uses, and the
  // rampage meter fed (sim.js stepCrush, design doc §2/§3).
  {
    Math.random = mulberry32(20260714)
    const run = skiesRun()
    stepSim(run, { x: 0, y: 0 }, dt) // streams in the REAL field around the origin (streamObstacles)
    assert(run.obstacles.length > 0, 'expected a live skies run to stream in real obstacles')
    const target = run.obstacles[0]
    assert(STRUCTURE_KINDS.includes(target.kind), `expected a real structure kind, got '${target.kind}'`)
    const revBefore = run._obstacleRev
    const xpBefore = run.player.xp

    run.player.x = target.x; run.player.y = target.y // dead-center overlap
    stepSim(run, { x: 0, y: 0 }, dt)

    assert(!run.obstacles.includes(target), 'expected the overlapped structure spliced from run.obstacles')
    assert(run._obstacleRev > revBefore, `expected _obstacleRev to bump (was ${revBefore}, now ${run._obstacleRev})`)
    const crushEv = run.events.find((ev) => ev.type === 'crush' && ev.x === target.x && ev.y === target.y)
    assert(crushEv, 'expected a crush event at the structure\'s position')
    assert.strictEqual(crushEv.kind, target.kind, `expected the crush event's kind to match the structure (${target.kind}), got ${crushEv.kind}`)
    // The dropped gem spawns dead-center on the structure — exactly where we just teleported the
    // player — so stepPickups (same frame) collects it INSTANTLY (distance 0 is inside
    // PLAYER.pickupRadius) rather than leaving it sitting in run.gems. Check the effect of the
    // pickup instead: player.xp went up by the gem's value, and a 'gem' event fired, proving the
    // xp really did flow through the same run.gems.push -> stepPickups path a kill uses (not some
    // shortcut that hands the player xp directly).
    assert(run.player.xp >= xpBefore + CRUSH_XP * GEM_VALUE - 1e-9,
      `expected the crush's xp (CRUSH_XP=${CRUSH_XP} * GEM_VALUE=${GEM_VALUE}) collected into player.xp, went ${xpBefore}->${run.player.xp}`)
    assert(run.events.some((ev) => ev.type === 'gem'), 'expected the crush\'s xp to flow through the gem pickup path (a gem event)')
    assert(run.rampage >= RAMPAGE_GAIN - 0.01, `expected the crush to feed the rampage meter (RAMPAGE_GAIN=${RAMPAGE_GAIN}), got ${run.rampage.toFixed(3)}`)
    console.log(`PASS run CC.a (crush on contact): kind=${target.kind} _obstacleRev ${revBefore}->${run._obstacleRev}, xp ${xpBefore}->${run.player.xp}, rampage=${run.rampage.toFixed(3)}`)
  }

  // (b) crushables don't block the PLAYER, but DO block ENEMIES — the design doc calls this "the
  // load-bearing line": stepObstacles' player-push loop is skipped ENTIRELY for a crush chapter
  // (chapter-gated, not per-obstacle), while the enemy loop is untouched. Both custom structures
  // are APPENDED to the real streamed field from (a) (never replaced), placed inside the disc
  // CHAPTERS.skies.obstacles.minDist keeps every real structure out of (with margin for maxR, so
  // nothing organic can wander in and contaminate the push-distance check).
  {
    Math.random = mulberry32(20260714)
    const run = skiesRun()
    stepSim(run, { x: 0, y: 0 }, dt) // real field streams in around the origin, same as (a)

    const wallA = { x: 32, y: 0, r: 15, _cell: 'test-a', kind: 'tower' } // overlaps the PLAYER
    const wallB = { x: 0, y: 60, r: 15, _cell: 'test-b', kind: 'house' } // overlaps only the ENEMY
    run.obstacles.push(wallA, wallB)

    const px0 = run.player.x, py0 = run.player.y // (0, 0) — already overlapping wallA by 5px
    const e = makeStatusEnemy(run, { x: 0, y: wallB.y + (wallB.r + 16 - 5), hp: 1e6, speed: 0 })
    run.enemies.push(e)
    const ey0 = e.y

    stepSim(run, { x: 0, y: 0 }, dt)

    assert.strictEqual(run.player.x, px0, 'expected the player to pass through a crushable structure unpushed (x)')
    assert.strictEqual(run.player.y, py0, 'expected the player to pass through a crushable structure unpushed (y)')
    assert(e.y > ey0, `expected the enemy pushed OUT of its structure, moved ${(e.y - ey0).toFixed(2)}px`)
    const dist = Math.hypot(e.x - wallB.x, e.y - wallB.y)
    assert(dist >= wallB.r + 16 - 1e-6, `expected the enemy no longer overlapping after the push, dist=${dist.toFixed(2)}`)
    console.log(`PASS run CC.b (asymmetric collision): player passed through unpushed, enemy shoved out to dist=${dist.toFixed(1)}`)
  }

  // (c) rampage lifecycle: fills on crush ((a) already covers that), decays on its own otherwise,
  // triggers RAMPAGE at 1.0, genuinely widens the crush radius while active, then drains back to
  // EXACTLY 0 with no residue (sim.js stepRampage, design doc §3).
  {
    // (c1) decays continuously with no crushing and no input.
    {
      Math.random = mulberry32(20260714)
      const run = skiesRun()
      run.rampage = 0.5; run.rampageT = 0
      const steps = Math.round(1 / dt)
      for (let i = 0; i < steps; i++) stepSim(run, { x: 0, y: 0 }, dt)
      const expected = 0.5 - RAMPAGE_DECAY * (steps * dt)
      assert(Math.abs(run.rampage - expected) < 1e-3, `expected rampage to decay to ~${expected.toFixed(3)} after 1s idle, got ${run.rampage.toFixed(3)}`)
      assert.strictEqual(run.rampageT, 0, 'expected rampageT to stay inactive while merely decaying')
    }

    // (c2) reaching 1.0 triggers RAMPAGE on the very next step (the trigger check runs BEFORE
    // decay — see stepRampage's own comment on why: decaying first could knock a just-clamped 1.0
    // fractionally under before the >=1 check ever saw it).
    {
      Math.random = mulberry32(20260714)
      const run = skiesRun()
      run.rampage = 1; run.rampageT = 0
      stepSim(run, { x: 0, y: 0 }, dt)
      assert.strictEqual(run.rampageT, RAMPAGE_DURATION, `expected a full meter to trigger RAMPAGE_DURATION (${RAMPAGE_DURATION}s), got rampageT=${run.rampageT}`)
      assert.strictEqual(run.rampage, 1, 'expected the meter to stay at 1 on the triggering frame itself (no decay yet)')
    }

    // (c3) the crush radius genuinely widens while rampageT > 0: a structure placed beyond the
    // NORMAL crush radius (PLAYER.radius) but inside the WIDENED one (PLAYER.radius *
    // RAMPAGE_CRUSH_MUL) survives outside rampage and is destroyed only once rampage is active.
    {
      Math.random = mulberry32(20260714)
      const run = skiesRun()
      const normalR = PLAYER.radius
      const wideR = PLAYER.radius * RAMPAGE_CRUSH_MUL
      const structR = CHAPTERS.skies.obstacles.minR
      const dist = (normalR + structR + wideR + structR) / 2 // straddles the midpoint of the two thresholds
      const wall = { x: dist, y: 0, r: structR, _cell: 'test-c', kind: 'tower' }
      run.obstacles.push(wall)

      // not rampaging: outside the normal radius, survives.
      run.rampage = 0; run.rampageT = 0
      stepSim(run, { x: 0, y: 0 }, dt)
      assert(run.obstacles.includes(wall), 'expected a structure beyond the normal crush radius to survive OUTSIDE rampage')

      // trigger rampage — this SAME frame's stepCrush still runs at the OLD rampageT=0 (it flips
      // AFTER stepCrush, inside stepRampage), so the wall survives this frame too.
      run.rampage = 1
      stepSim(run, { x: 0, y: 0 }, dt)
      assert(run.obstacles.includes(wall), 'expected the wall to survive the triggering frame itself (rampageT widens AFTER stepCrush runs that frame)')
      assert.strictEqual(run.rampageT, RAMPAGE_DURATION, 'expected rampage to be active now')

      // next frame: rampageT > 0 entering stepCrush -> the widened radius reaches the wall.
      stepSim(run, { x: 0, y: 0 }, dt)
      assert(!run.obstacles.includes(wall), `expected the widened crush radius (${wideR}) to reach a structure ${dist}px out (normal reach was only ${normalR + structR}px)`)
      const crushEv = run.events.find((ev) => ev.type === 'crush' && ev.x === wall.x && ev.y === wall.y)
      assert(crushEv, 'expected a crush event for the wall destroyed by the widened rampage radius')
    }

    // (c4) drains across RAMPAGE_DURATION and resets to EXACTLY 0 — no residue once the buff ends.
    {
      Math.random = mulberry32(20260714)
      const run = skiesRun()
      run.rampage = 1; run.rampageT = RAMPAGE_DURATION
      const half = Math.round((RAMPAGE_DURATION / 2) / dt)
      for (let i = 0; i < half; i++) stepSim(run, { x: 0, y: 0 }, dt)
      assert(run.rampageT > 0, 'expected rampage still active at the halfway point')
      assert(Math.abs(run.rampage - 0.5) < 0.05, `expected the meter roughly half-drained at the halfway point, got ${run.rampage.toFixed(3)}`)

      const rest = Math.round((RAMPAGE_DURATION / 2 + 0.5) / dt) // past the end of the duration
      for (let i = 0; i < rest; i++) stepSim(run, { x: 0, y: 0 }, dt)
      assert.strictEqual(run.rampageT, 0, 'expected rampageT to reset to EXACTLY 0 once the duration elapses')
      assert.strictEqual(run.rampage, 0, 'expected rampage to reset to EXACTLY 0 — no residue')

      // and it stays there — no lingering partial-widen effect after the buff has ended.
      for (let i = 0; i < Math.round(1 / dt); i++) stepSim(run, { x: 0, y: 0 }, dt)
      assert.strictEqual(run.rampage, 0, 'expected rampage to remain 0 with no residue after the buff has fully ended')
      assert.strictEqual(run.rampageT, 0, 'expected rampageT to remain 0 with no residue after the buff has fully ended')
    }

    console.log(`PASS run CC.c (rampage lifecycle): decays idle, triggers at 1.0, widens ${PLAYER.radius}->${PLAYER.radius * RAMPAGE_CRUSH_MUL} while active, drains to exactly 0`)
  }

  // (c5) v5.14 rampage PAYLOAD: invulnerable + faster + harder-hitting while rampageT > 0, and
  // — the assertion that actually matters — NOTHING LEAKS once it ends. Rev.1 of the v5.8 redesign
  // cut these buffs precisely because it granted them by ASSIGNING to p.speed/p.damageMul, which
  // are set once in createRun and never written again, so a re-trigger or a death mid-buff left the
  // multiplier stuck on forever. They are read-time multipliers now; this pins that they stay so.
  {
    Math.random = mulberry32(20260714)
    const run = skiesRun()
    const p = run.player
    const baseSpeed = p.speed, baseDmg = p.damageMul, baseFire = p.fireRateMul
    p.hp = 100; p.maxHP = 100

    // INVULNERABLE: a direct hit from a full-strength contact enemy costs nothing while rampaging.
    run.rampage = 1; run.rampageT = RAMPAGE_DURATION
    const hitter = makeStatusEnemy(run, { x: 0, y: 0, hp: 50, speed: 0 })
    hitter.dmg = 40; hitter.flags = []
    run.enemies.push(hitter)
    stepSim(run, { x: 0, y: 0 }, dt)
    assert.strictEqual(p.hp, 100, `expected rampage to be INVULNERABLE, took ${100 - p.hp} damage`)

    // MOVES FASTER: same input, further travelled, by RAMPAGE_SPEED_MUL.
    run.enemies.length = 0
    const x0 = p.x
    stepSim(run, { x: 1, y: 0 }, dt)
    const rampStep = p.x - x0
    run.rampageT = 0; run.rampage = 0
    const x1 = p.x
    stepSim(run, { x: 1, y: 0 }, dt)
    const normStep = p.x - x1
    assert(Math.abs(rampStep / normStep - RAMPAGE_SPEED_MUL) < 0.02,
      `expected rampage movement to be ${RAMPAGE_SPEED_MUL}x, got ${(rampStep / normStep).toFixed(3)}x`)

    // NO RESIDUE: the buff ended above, so every source value must be untouched. This is the whole
    // point of deriving instead of assigning — if any of these three drifted, the buff leaked.
    assert.strictEqual(p.speed, baseSpeed, 'rampage LEAKED into player.speed')
    assert.strictEqual(p.damageMul, baseDmg, 'rampage LEAKED into player.damageMul')
    assert.strictEqual(p.fireRateMul, baseFire, 'rampage LEAKED into player.fireRateMul')

    // ...and it must still leak nothing after a SECOND rampage runs its full course (the re-trigger
    // case that made rev.1's in-place version compound).
    run.rampage = 1; run.rampageT = RAMPAGE_DURATION
    for (let i = 0; i < Math.round((RAMPAGE_DURATION + 1) / dt); i++) stepSim(run, { x: 0, y: 0 }, dt)
    assert.strictEqual(p.speed, baseSpeed, 'rampage LEAKED into player.speed on re-trigger')
    assert.strictEqual(p.damageMul, baseDmg, 'rampage LEAKED into player.damageMul on re-trigger')
    assert.strictEqual(p.fireRateMul, baseFire, 'rampage LEAKED into player.fireRateMul on re-trigger')

    console.log(`PASS run CC.c5 (rampage payload): invulnerable, ${(rampStep / normStep).toFixed(2)}x move speed, and zero leak into player.speed/damageMul/fireRateMul across two rampages`)
  }

  // (c6) v5.14 'crushable' (skies' aircraft): flying into the kaiju kills the aircraft and costs
  // the player NOTHING — no damage and no invuln window spent. A whole flight dies in one frame,
  // which is what the `continue`-instead-of-`return` in stepContactDamage's branch buys.
  {
    Math.random = mulberry32(20260714)
    const run = skiesRun()
    const p = run.player
    p.hp = 100; p.maxHP = 100; p.invuln = 0
    for (let i = 0; i < 3; i++) {
      const jet = makeStatusEnemy(run, { x: 4 * i - 4, y: 0, hp: 30, speed: 0 })
      jet.dmg = 25; jet.flags = ['strafe', 'crushable']
      run.enemies.push(jet)
    }
    stepSim(run, { x: 0, y: 0 }, dt)
    assert.strictEqual(p.hp, 100, `expected ramming aircraft to cost the kaiju nothing, took ${100 - p.hp}`)
    assert.strictEqual(p.invuln, 0, 'expected no invuln window to be spent on a crushable contact')
    const alive = run.enemies.filter((e) => !e._dead && (e.flags || []).includes('crushable'))
    assert.strictEqual(alive.length, 0, `expected all 3 rammed aircraft dead in ONE frame, ${alive.length} survived`)

    // ...and a NON-crushable enemy on the same contact path still hurts normally, so the branch
    // above is scoped to the flag and has not quietly disarmed contact damage for everything else.
    const run2 = skiesRun()
    run2.player.hp = 100; run2.player.maxHP = 100; run2.player.invuln = 0
    const tank = makeStatusEnemy(run2, { x: 0, y: 0, hp: 30, speed: 0 })
    tank.dmg = 25; tank.flags = ['artillery']
    run2.enemies.push(tank)
    stepSim(run2, { x: 0, y: 0 }, dt)
    assert(run2.player.hp < 100, 'expected a NON-crushable enemy to still deal contact damage')

    console.log('PASS run CC.c6 (crushable aircraft): 3 rammed aircraft died in one frame for 0 damage; a tank on the same path still hurt')
  }

  // (d) structure `kind` is deterministic for a given (cell, obstacleSeed, districtSeed) — and it
  // MATCHES the district it stands in.
  //
  // v5.9.1: this assertion was inverted. It used to require kind to be INDEPENDENT of
  // _districtSeed, because v5.8 derived kind from a bare obstacleCellHash salt specifically so sim
  // would never read the then-render-only _districtSeed. Playtest killed that design: you got
  // houses standing in open sea and piers in farmland. _districtSeed is now a documented read-only
  // sim contract (state.js), kind is picked from DISTRICT_STRUCTURE_KINDS[district], and the thing
  // worth guarding is the opposite of what this test used to say — so it now pins the district
  // match (no land buildings at sea) and keeps only the repeat-visit stability check.
  {
    function seededSkiesRun(obstacleSeed, districtSeed) {
      const run = createRun(makeMeta(), { chapter: 'skies' })
      run.weapons = []; run.mods.spawnMul = 0; run._bombardAcc = 1e6
      run.player.x = 0; run.player.y = 0; run.player.hp = 1e9; run.player.maxHP = 1e9
      run._obstacleSeed = obstacleSeed
      run._districtSeed = districtSeed
      return run
    }
    Math.random = mulberry32(20260714)
    const seed = 424242

    // v6.9.2: world seeds whose ORIGIN IS DOWNTOWN. Obstacle density is a function of the biome
    // (BIOME_BUILD_DENSITY), so a seed that opens at sea streams a handful of piers and nothing
    // else — 111 used to clear this "> 5" by one or two, and the v6.9.2 road widening shaved that
    // margin away without anything actually being wrong. A downtown origin is both what this test
    // is about and 10x clear of the threshold, so it measures the generator rather than the luck of
    // where one seed's streaming disc landed.
    const runA = seededSkiesRun(seed, 4321)
    stepSim(runA, { x: 0, y: 0 }, dt)
    const kindsA = Object.fromEntries(runA.obstacles.map((o) => [o._cell, o.kind]))
    assert(Object.keys(kindsA).length > 5, 'expected the forced seed to stream in a real set of obstacles')

    // v5.11 DELIBERATELY RETIRED the invariant that used to be asserted here ("the same obstacle
    // seed streams the exact same set of cells regardless of _districtSeed"). It was true because
    // the per-cell build probability was a flat constant everywhere, which is precisely the property
    // that made a city impossible to see: a pier every 200px across open ocean at the same spacing
    // as towers downtown. Density is now a function of the biome (BIOME_BUILD_DENSITY, terrain.js),
    // so the cell set MUST move with the world seed.
    //
    // What replaces it is the property that actually matters, and the one the "no building" half of
    // the playtest report was about: A CITY IS DENSER THAN OPEN COUNTRY. Measured directly on the
    // generator over equal-area samples rather than on a live run, so it can't be confounded by
    // where the streaming disc happens to sit.
    const runB = seededSkiesRun(seed, 5150)
    stepSim(runB, { x: 0, y: 0 }, dt)
    assert(runB.obstacles.length > 5, 'expected the second world seed to stream in a real set of obstacles too')

    {
      const wseed = pickWorldSeed(31337)
      const tally = {}
      for (let i = 0; i < 24000; i++) {
        const x = (i * 173) % 26000 - 13000
        const y = (i * 1097) % 26000 - 13000
        const b = districtAt(x, y, wseed)
        tally[b] = (tally[b] || 0) + 1
      }
      // Sanity: the sample has to actually contain both kinds of place before comparing them.
      assert((tally.downtown || 0) > 50 && (tally.sea || 0) > 50,
        `expected the sample to cover both downtown and sea, got ${JSON.stringify(tally)}`)
      const dDown = BIOME_BUILD_DENSITY.downtown, dSea = BIOME_BUILD_DENSITY.sea
      assert(dDown > dSea * 10,
        `expected downtown to build far denser than open sea, got ${dDown} vs ${dSea}`)
      assert(BIOME_BUILD_DENSITY.downtown > BIOME_BUILD_DENSITY.suburbs
        && BIOME_BUILD_DENSITY.suburbs > BIOME_BUILD_DENSITY.farms
        && BIOME_BUILD_DENSITY.farms > BIOME_BUILD_DENSITY.desert,
        'expected build density to fall monotonically downtown > suburbs > farms > desert')
    }

    // ...and every structure must be legal for the district it stands in. This is the playtest bug
    // ("there are houses in sea biome") in assertion form: sea may hold piers and nothing else.
    let checked = 0
    for (const run of [runA, runB]) {
      for (const o of run.obstacles) {
        const d = districtAt(o.x, o.y, run._districtSeed)
        const allowed = DISTRICT_STRUCTURE_KINDS[d]
        assert(allowed.includes(o.kind),
          `expected a '${d}' cell to hold one of [${allowed}], got '${o.kind}' at (${o.x.toFixed(0)},${o.y.toFixed(0)})`)
        checked++
      }
    }
    assert(checked > 10, `expected a real sample of structures to district-check, got ${checked}`)

    // repeat visit: walk far enough away to drop the origin's cells, then walk back — the SAME
    // cell must re-roll the SAME kind (sim.js's ponytail note on stepCrush: "walk away and back,
    // same building").
    const runC = seededSkiesRun(seed, 111)
    stepSim(runC, { x: 0, y: 0 }, dt)
    const firstVisit = Object.fromEntries(runC.obstacles.map((o) => [o._cell, o.kind]))
    runC.player.x = OBSTACLE_DROP_RADIUS * 3; runC.player.y = OBSTACLE_DROP_RADIUS * 3
    stepSim(runC, { x: 0, y: 0 }, dt) // drops the origin's cells — now far beyond OBSTACLE_DROP_RADIUS
    assert(!runC.obstacles.some((o) => o._cell in firstVisit), 'expected walking far away to drop the origin cells')
    runC.player.x = 0; runC.player.y = 0
    stepSim(runC, { x: 0, y: 0 }, dt) // walk back — origin cells re-roll
    const secondVisit = Object.fromEntries(runC.obstacles.map((o) => [o._cell, o.kind]))
    for (const cell of Object.keys(firstVisit)) {
      assert.strictEqual(secondVisit[cell], firstVisit[cell],
        `expected cell ${cell} to re-roll the SAME kind on a repeat visit (first=${firstVisit[cell]}, second=${secondVisit[cell]})`)
    }

    console.log(`PASS run CC.d (kind matches district): ${checked} structures all legal for their district, ${Object.keys(kindsA).length} cells stable on a repeat visit`)
  }

  // (e) density guard: THIS specific test exists because rev.1 of this redesign silently did
  // nothing — streamObstacles' per-cell probability is `prob = count*cs^2 /
  // (pi*OBSTACLE_FIELD_RADIUS^2)` (sim.js/1157), which is INVARIANT under cell size alone.
  // Shrinking `cell` 420->260 while leaving `count` at the old 13 would have produced the exact
  // same density wearing a finer grid. Both numbers had to move together (config.js: count
  // 13->34, cell 420->260) to actually reach the intended ~150-obstacle density. Drive an ACTUAL
  // wandering skies run (not a frozen spawn-frame snapshot) long enough for the streaming field's
  // materialize-at-1400/drop-at-1900 hysteresis to settle (empirically stable within a couple
  // obstacles by 30s), then assert a RANGE — loose enough to not chase exact density-formula
  // arithmetic, but tight enough that the rev.1 no-op (which settles under 40 obstacles by this
  // same measurement, verified directly against this file's seed) can't sneak back in. Do not
  // delete this in the name of simplifying: it is the ONLY test that would have caught rev.1's bug.
  //
  // v5.9 top-down region overhaul addendum: roads now carve ~17% of the world out of the
  // buildable area (roadAt/ROAD_* in config.js) — the reason config.js bumped count 34->40 (see
  // CHAPTERS.skies.obstacles' own comment). Checked by hand against this file's seed: reverting to
  // the old count=34 with roads still on settles at 76 live obstacles — inside the ORIGINAL 70-170
  // floor, so that floor could no longer tell "the v5.9 density bump got reverted" apart from
  // "working as intended". Raising the floor 70->80 sits strictly between 76 (the reverted value)
  // and 88 (today's, below) — still comfortably clear of the rev.1 no-op (<40) but now also catches
  // a silent count 40->34 revert.
  {
    Math.random = mulberry32(20260714)
    const run = skiesRun()
    let t = 0
    for (let i = 0; i < Math.round(30 / dt); i++) {
      t += dt
      stepSim(run, { x: Math.cos(t), y: Math.sin(t) }, dt)
    }
    const n = run.obstacles.length
    assert(n >= 80 && n <= 170, `expected roughly the intended ~150 live obstacles after wandering, got ${n} (the rev.1 cell/count no-op settles under 40, and a reverted v5.9 count settles at 76, by this same measurement)`)
    console.log(`PASS run CC.e (density guard): ${n} live obstacles after 30s of wandering (~88 expected since roads carve ~17% of the buildable grid; floor guards the rev.1 cell/count no-op)`)
  }

  // (f) a crushed structure STAYS crushed. v5.9.1, and this one shipped broken because it had no
  // test: v5.8 deliberately kept no record of what had been flattened, on the reasoning that a
  // crushed cell couldn't re-roll until the player walked OBSTACLE_DROP_RADIUS (1900px) away. That
  // reasoning described the DROP path. The RE-ADD path never consults the drop radius — it skips a
  // cell only while that cell is still in `run.obstacles`, and crushing splices it out. So the next
  // scan (any cell-boundary crossing: 260px cells at 220px/s ≈ 1.2s) rebuilt the identical
  // building. The user's report was "crushed assets reappear 1s after being crushed" — exactly the
  // arithmetic. run._crushed is what makes it stick, so pin it hard.
  {
    Math.random = mulberry32(20260714)
    const run = createRun(makeMeta(), { chapter: 'skies' })
    run.weapons = []; run.mods.spawnMul = 0; run._bombardAcc = 1e6
    run.player.hp = 1e9; run.player.maxHP = 1e9
    run.player.x = 0; run.player.y = 0
    stepSim(run, { x: 0, y: 0 }, dt)

    // stand on the nearest structure and flatten it
    const target = run.obstacles.slice().sort((a, b) => Math.hypot(a.x, a.y) - Math.hypot(b.x, b.y))[0]
    assert(target, 'expected a streamed structure to crush')
    const cell = target._cell
    run.player.x = target.x; run.player.y = target.y
    stepSim(run, { x: 0, y: 0 }, dt)
    assert(!run.obstacles.some((o) => o._cell === cell), `expected cell ${cell} to be crushed`)

    // now pace back and forth across cell boundaries — the exact motion that used to resurrect it.
    // Well over the ~1.2s the user measured, and it must never come back.
    let reappeared = 0
    for (let lap = 0; lap < 6; lap++) {
      for (const [dx, dy] of [[600, 0], [0, 600], [-600, 0], [0, -600]]) {
        run.player.x += dx; run.player.y += dy
        stepSim(run, { x: 0, y: 0 }, dt)
        if (run.obstacles.some((o) => o._cell === cell)) reappeared++
      }
    }
    assert.strictEqual(reappeared, 0, `expected the crushed cell to stay flat, it came back ${reappeared}x`)
    assert(run._crushed.has(cell), 'expected the crushed cell to be recorded in run._crushed')
    console.log(`PASS run CC.f (crush sticks): cell ${cell} stayed flat across 24 cell-crossing re-scans`)
  }
}

// ---- Run DD: v5.9 top-down region overhaul (roads) -------------------------------------------
// roadAt (config.js) grew alongside DISTRICTS (run BB above already covers all 6 district types,
// farms/hills included) and STRUCTURE_KINDS (run CC.d already covers kind determinism/independence
// from _districtSeed). What's untested so far is the road grid itself: that it's actually
// deterministic and non-degenerate, and — the load-bearing one — that streamObstacles' own
// road-rejection (sim.js) and roadAt (config.js) genuinely agree on what counts as roadway,
// not just that both happen to compile.
function testRoads() {
  const dt = 1 / 60

  // (a) roadAt determinism: same (x, y, seed) always gives the same result (a pure function, no
  // RNG stream, no run state); a DIFFERENT seed must actually move the grid (the per-seed ox/oy
  // offset config.js's own comment calls out as "keeps different runs' grids from all sitting on
  // literally the same world-space lines").
  {
    const seed = 777
    for (const [x, y] of [[0, 0], [733, -212], [15000, 8000], [-4001, 6002]]) {
      assert.deepStrictEqual(roadAt(x, y, seed), roadAt(x, y, seed), `expected roadAt(${x},${y},${seed}) to be deterministic`)
    }
    // Sample enough points that "different seed, identical grid" (a broken/no-op per-seed offset)
    // would be caught, not just get lucky on one probe.
    let sawDifference = false
    for (let i = 0; i < 200; i++) {
      const x = i * 37, y = i * 53
      if (roadAt(x, y, seed).onRoad !== roadAt(x, y, seed + 1).onRoad) { sawDifference = true; break }
    }
    assert(sawDifference, 'expected a different seed to produce a different road layout somewhere over a 200-point sample')
    console.log('PASS run DD.a (roadAt determinism): same (x,y,seed) repeats every time, a different seed moves the grid')
  }

  // (b) road geometry is sane: sweep a DIAGONAL line (irrational-ish slope, so it can never ride
  // parallel to an axis-aligned street the whole way — a sweep along a fixed y or x WOULD
  // occasionally land exactly on a street's centreline and read as constantly-on-road for that one
  // probe, a sampling artifact of picking an unlucky line, not a real roadAt bug) and require it to
  // cross roadway sometimes and open ground sometimes, with many transitions — guards against a
  // degenerate roadAt that always (or never) returns onRoad true, which run DD.c below could not
  // distinguish from "roads are working" (an always-false roadAt would trivially pass "no obstacle
  // is on a road" too).
  {
    const seed = 20260714
    let onCount = 0, total = 0, transitions = 0, prevOn = null
    for (let t = 0; t < 20000; t += 5) {
      const r = roadAt(t, t * 0.37 + 53, seed)
      if (r.onRoad) onCount++
      total++
      if (prevOn !== null && prevOn !== r.onRoad) transitions++
      prevOn = r.onRoad
    }
    const frac = onCount / total
    assert(frac > 0.02 && frac < 0.5, `expected roadway to cover a modest slice of a long diagonal sweep, got ${(frac * 100).toFixed(1)}% (a degenerate roadAt reads as ~0% or ~100%)`)
    // The floor is derived from the GRID PITCH, not a magic number: this sweep crosses roughly
    // 20000/BLOCK_U vertical streets and 7400/BLOCK_V horizontal ones where it happens to be inside
    // a city, so the old hardcoded 20 silently encoded the pre-v6.9.2 300x380 blocks and failed the
    // moment the grid was widened. What the assertion is actually for is catching a DEGENERATE
    // roadAt (always-on or always-off), and any positive transition count well clear of zero does
    // that; a quarter of the vertical crossings is a comfortable margin either way.
    const floor = Math.max(6, Math.round(20000 / BLOCK_U / 4))
    assert(transitions > floor, `expected many road/non-road transitions along a long diagonal sweep, got ${transitions} (floor ${floor})`)
    console.log(`PASS run DD.b (road geometry): ${(frac * 100).toFixed(1)}% of a diagonal sweep on-road across ${transitions} transitions (neither constantly on nor off)`)
  }

  // (c) roads are actually clear: drive a REAL live skies run — createRun with a real chapter and
  // a live obstacle field, NOT flagRun (flagRun sets run.obstacles = []; run._obstacleSeed = null,
  // which would make "no obstacle is on a road" vacuously true and prove nothing). Let the field
  // stream in for real, then assert no live obstacle's CENTRE sits on roadway per roadAt fed the
  // run's own _obstacleSeed — the same seed streamObstacles used to reject those cells in the first
  // place (sim.js). This is the one check that would actually catch sim and roadAt drifting apart.
  {
    Math.random = mulberry32(20260714)
    const run = createRun(makeMeta(), { chapter: 'skies' })
    run.weapons = []; run.mods.spawnMul = 0; run._bombardAcc = 1e6
    run.player.x = 0; run.player.y = 0; run.player.hp = 1e9; run.player.maxHP = 1e9
    let t = 0
    for (let i = 0; i < Math.round(30 / dt); i++) {
      t += dt
      stepSim(run, { x: Math.cos(t), y: Math.sin(t) }, dt)
    }
    assert(run.obstacles.length > 0, 'expected a live skies run to stream in real obstacles')
    // v5.11: roads are queried on run._districtSeed (the WORLD seed) — the old separate
    // run._obstacleSeed road lattice is gone, along with the reason streets used to cross open sea.
    const onRoad = run.obstacles.filter((o) => roadAt(o.x, o.y, run._districtSeed).onRoad)
    assert.strictEqual(onRoad.length, 0,
      `expected no live obstacle centred on roadway, found ${onRoad.length}/${run.obstacles.length}: ${JSON.stringify(onRoad.slice(0, 3))}`)
    console.log(`PASS run DD.c (roads are clear): 0/${run.obstacles.length} live obstacles centred on roadway`)
  }

  // (d) STRUCTURE_KINDS grew 4 -> 6 in the same v5.9 overhaul (config.js: 'tower'/'house'/'tree'/
  // 'pier' plus new 'barn'/'silo') — run CC.d above already proves kind is stable per (cell, seed)
  // and independent of _districtSeed; this just pins the COUNT so a future edit can't silently
  // shrink the ladder back down without any test noticing.
  {
    assert.strictEqual(STRUCTURE_KINDS.length, 6, `expected 6 structure kinds (v5.9 grew this from 4), got ${STRUCTURE_KINDS.length}: ${STRUCTURE_KINDS}`)
    console.log(`PASS run DD.d (structure kind count): ${STRUCTURE_KINDS.length} kinds (${STRUCTURE_KINDS.join(',')})`)
  }

  // (e) STREETS ARE CONTINUOUS — the direct regression test for the v5.11 playtest report, "roads
  // are 10 meters long". Nothing in the suite could catch that: DD.b only counts how OFTEN a
  // diagonal sweep is on roadway, and a road chopped into 600px stubs scores exactly the same
  // coverage as an unbroken one. The bug was never about coverage, it was about CONTINUITY.
  //
  // So walk ALONG a street instead of across it: find a point on a city street, take the heading
  // roadAt reports there, and follow it. A real street stays under your feet for its whole length.
  // The old build failed this instantly — render only drew pavement inside the urban districts of a
  // 600px Voronoi cell, so following any street walked off the paving within a few hundred px.
  {
    const seed = pickWorldSeed(4242)
    // Start from the home city's centre (terrain.js guarantees a city at the origin) and search
    // outward for a street to stand on.
    let start = null
    for (let probe = 0; probe < 4000 && !start; probe++) {
      const px = (probe % 63) * 17 - 500, py = Math.floor(probe / 63) * 17 - 500
      const r = roadAt(px, py, seed)
      if (r.onRoad && r.kind === 'street') start = { x: px, y: py, angle: r.angle }
    }
    assert(start, 'expected to find a city street near the origin to walk along')

    // Follow the street's own heading. Re-centre onto the centreline each step (roadAt reports the
    // perpendicular distance) so accumulated float drift can't walk us into the kerb and read as a
    // discontinuity that isn't one.
    const STEP = 12
    let x = start.x, y = start.y, walked = 0, offRoad = 0
    for (let i = 0; i < 60; i++) {
      const r = roadAt(x, y, seed)
      if (!r.onRoad) { offRoad++; break }
      // recentre: nudge perpendicular, keep whichever direction reduced `dist`
      const px = Math.sin(r.angle), py = Math.cos(r.angle)
      const probe = roadAt(x + px * 3, y + py * 3, seed)
      const sign = (probe.onRoad && probe.dist < r.dist) ? 1 : -1
      x += px * r.dist * sign; y += py * r.dist * sign
      x += Math.cos(r.angle) * STEP; y += Math.sin(r.angle) * STEP
      walked += STEP
    }
    assert.strictEqual(offRoad, 0, `expected a city street to stay continuous under a walk along its own heading; left the roadway after ${walked}px`)
    assert(walked >= 700, `expected to walk at least 700px along one street, managed ${walked}px`)
    console.log(`PASS run DD.e (streets are continuous): walked ${walked}px along one street without leaving the roadway`)
  }

  // (f) ROADS BELONG TO CITIES. The v5.10 grid was global and infinite, so roadway existed in the
  // middle of the ocean and halfway up a mountain — which is what forced render to gate drawing per
  // district and produced the stubs DD.e now guards. Assert the structural property that replaced
  // it: every street is inside a city's own radius. (Highways are exempt by construction — their
  // whole job is to run between cities — so they're excluded, not ignored: DD.e already proves the
  // street case, and a highway with no city at either end cannot be generated.)
  {
    const seed = pickWorldSeed(90210)
    let streets = 0, orphans = 0
    for (let i = 0; i < 6000; i++) {
      const x = (i * 137) % 20000 - 10000
      const y = (i * 991) % 20000 - 10000
      const r = roadAt(x, y, seed)
      if (!r.onRoad || r.kind !== 'street') continue
      streets++
      // The right property is "this place is urban", not "this point is within the city's nominal
      // radius": cityEdgeWobble (terrain.js) deliberately makes the urban boundary ragged, pushing
      // it out past r in places and pulling it in elsewhere, which is what stops cities rendering as
      // perfect circles. Testing the raw radius would therefore fail on exactly the feature it is
      // meant to protect (it did — 10/261 "orphans" that were all inside their own city's wobbled
      // edge). urbanAt is the same question roadAt itself asks before laying a street.
      if (urbanAt(x, y, seed) <= 0) orphans++
    }
    assert(streets > 20, `expected the sample to land on a decent number of city streets, got ${streets}`)
    assert.strictEqual(orphans, 0, `expected every city street to lie inside its own city's radius, found ${orphans}/${streets} orphaned in open country`)
    console.log(`PASS run DD.f (roads belong to cities): ${streets} sampled streets, 0 outside a city`)
  }

  // (g) THE RUN OPENS IN A CITY. terrain.js puts the home city at the world origin unconditionally,
  // and state.js walks the world seed forward until the origin is buildable land. Both halves have
  // to hold or the chapter's opening image — a kaiju standing downtown — silently becomes "a kaiju
  // in an empty field", which is exactly the kind of regression that only shows up in a screenshot.
  {
    for (const raw of [1, 2, 3, 99, 12345, 777777]) {
      const seed = pickWorldSeed(raw)
      const t = terrainAt(0, 0, seed)
      assert(t.biome === 'downtown', `expected the world origin to be downtown for raw seed ${raw}, got ${t.biome}`)
      const e = elevationAt(0, 0, seed)
      assert(e > 0.40 && e < 0.71, `expected the origin to be buildable land for raw seed ${raw}, elevation ${e.toFixed(3)}`)
    }
    console.log('PASS run DD.g (spawn is downtown): 6 raw seeds all resolve to a buildable origin inside the home city')
  }
}

// ---- Run EE: v5.24 The Blank (scripted boss chapter) -------------------------------------------
// The chapter has no ordinary spawner at all — stepBossScript (sim.js) is the ONLY thing that
// ever pushes to run.enemies, driven by BLANK_SCRIPT (config.js). Since dealDamage isn't exported,
// every "kill this enemy now" step below reuses the file's own idiom: drag the target onto the
// player, drop its hp to 1, and let an equipped weapon (real sim code) finish it — same as
// makeStatusEnemy's hp:1 elsewhere, just through spawnEnemy's normal path instead of a hand-built
// enemy. Death is detected the same way sim.js's own doc block says it must be: absence from
// run.enemies (or its _dead flag) on a later frame, never a returned id.
function testTheBlank() {
  const dt = 1 / 60

  // (a) Wave 1 + no ordinary spawning: every enemy alive, at spawn and after 30s of idling, must
  // be wave-tagged (stepSpawning early-returns entirely for a scripted chapter) and non-elite
  // (forceNormal, not just an empty eliteFlags list — see the contract's recon notes).
  {
    const run = createRun(makeMeta(), { chapter: 'blank', difficulty: 1 })
    run.player.hp = run.player.maxHP = 1e6 // survive whatever reaches it during the idle window below
    // No weapons: a real (unstripped) starter weapon can clear wave 1 well inside 30s and carry the
    // script all the way into the boss stage, whose antibody is deliberately NOT _wave-tagged (see
    // (c)/(d) below) — that would break this scenario's invariant for reasons unrelated to what it's
    // actually checking (stepSpawning gates off, at every point, for the whole idle window).
    run.weapons = []
    stepSim(run, { x: 0, y: 0 }, dt) // one frame: stepBossScript spawns wave 1 synchronously
    const wave0 = BLANK_SCRIPT[0].waves[0]
    assert.strictEqual(run.enemies.length, wave0.n, `expected wave 1 to spawn ${wave0.n} enemies, got ${run.enemies.length}`)
    assert(run.enemies.every((e) => wave0.ids.includes(e.rosterId)), "expected every wave-1 enemy's rosterId in the wave block's ids")
    assert(run.enemies.every((e) => e._wave), 'expected every wave-1 enemy tagged _wave')
    assert(run.enemies.every((e) => !e.elite), 'expected zero elites in a scripted chapter')

    advance(run, 30, dt, { x: 0, y: 0 })
    assert(run.enemies.every((e) => e._wave), 'expected every enemy alive after 30s idle to still be wave-tagged — no ordinary spawner ever ran')
    assert(run.enemies.every((e) => !e.elite), 'expected zero elites after 30s idle')
    console.log(`PASS run EE.a (wave 1 + no ordinary spawning): ${wave0.n} spawned, ${run.enemies.length} alive after 30s idle, all wave-tagged`)
  }

  // (a2) The door: a wave ring leaves one BLANK_WAVE_GAP-wide wedge empty, so an encircled player
  // always has an opening to aim for. Measured as the largest angular spacing between consecutive
  // spawn bearings (exact — no binning). This cannot pass by luck: for n uniform bearings the
  // chance of a spacing that big is n(1 - gap/2pi)^(n-1), which at the shipped 90° door is 2e-14
  // at wave 1's n=128 and 3e-30 by the 256-body wave (it was 5e-6 / 6e-11 at the original 45°, so
  // widening the door only strengthens this) — a real assertion, not a coin flip.
  // Every wave in the script is checked, since the gap is re-rolled per wave.
  {
    const gaps = []
    for (let b = 0; b < BLANK_SCRIPT.length; b += 2) {
      for (let w = 0; w < BLANK_SCRIPT[b].waves.length; w++) {
        const run = createRun(makeMeta(), { chapter: 'blank', difficulty: 1 })
        run.player.hp = run.player.maxHP = 1e6
        run.weapons = []
        Object.assign(run.script, { stage: b, waveIdx: w, waveT: 0, spawned: false })
        stepSim(run, { x: 0, y: 0 }, dt)
        const p = run.player
        const bearings = run.enemies.map((e) => Math.atan2(e.y - p.y, e.x - p.x)).sort((m, n) => m - n)
        let widest = bearings[0] + Math.PI * 2 - bearings[bearings.length - 1] // the wrap-around span
        for (let i = 1; i < bearings.length; i++) widest = Math.max(widest, bearings[i] - bearings[i - 1])
        // The measurement is taken one frame AFTER the spawn (stepSim runs movement + separation
        // on the fresh ring before it returns), so the door has already narrowed by a fraction of
        // a degree. 2° of slack covers that without weakening anything: the null hypothesis this
        // rejects would have to produce a 43° spacing by chance, which is rarer still.
        assert(widest >= BLANK_WAVE_GAP - 0.035,
          `expected wave ${b}/${w} (${bearings.length} bodies) to leave a >= ${(BLANK_WAVE_GAP * 180 / Math.PI).toFixed(0)}° door, widest empty arc was ${(widest * 180 / Math.PI).toFixed(1)}°`)
        gaps.push(widest * 180 / Math.PI)
      }
    }
    console.log(`PASS run EE.a2 (the door): every one of the ${gaps.length} scripted waves left an escape wedge — widest empty arcs ${gaps.map((g) => g.toFixed(0)).join('/')}° against a ${(BLANK_WAVE_GAP * 180 / Math.PI).toFixed(0)}° door (2° of post-spawn drift allowed)`)
  }

  // (b) Clear-advance: hard-kill every wave-1 enemy -> wave 2 arrives immediately (rosterIds from
  // the block's second wave). Timeout-advance, isolated in its own run with no weapons at all (so
  // nothing can die and only a timeout can move the script): idling past BLANK_WAVE_TIMEOUT
  // advances anyway, with wave-1's leftovers still alive alongside wave 2.
  {
    const run = createRun(makeMeta(), { chapter: 'blank', difficulty: 1 })
    run.player.hp = run.player.maxHP = 1e6
    run.weapons = [{ id: 'wave', level: MAX_WEAPON_LEVEL }]
    stepSim(run, { x: 0, y: 0 }, dt) // wave 1 spawns
    assert.strictEqual(run.script.waveIdx, 0)
    for (const e of run.enemies) { e.x = run.player.x; e.y = run.player.y; e.hp = e.maxHP = 1 }
    advance(run, 3, dt, { x: 0, y: 0 })
    assert.strictEqual(run.script.waveIdx, 1, `expected wave-clear to advance waveIdx to 1, got ${run.script.waveIdx}`)
    const wave1 = BLANK_SCRIPT[0].waves[1]
    const alive = run.enemies.filter((e) => !e._dead)
    assert(alive.length > 0 && alive.every((e) => wave1.ids.includes(e.rosterId)), "expected wave 2 to have arrived with rosterIds from the block's second wave")
    console.log(`PASS run EE.b1 (clear-advance): wave 1 hard-killed -> waveIdx=1, ${alive.length} wave-2 enemies alive`)
  }
  {
    const run = createRun(makeMeta(), { chapter: 'blank', difficulty: 1 })
    run.player.hp = run.player.maxHP = 1e6
    run.weapons = [] // isolate the timeout path — nothing can die, so only a timeout can advance
    stepSim(run, { x: 0, y: 0 }, dt) // wave 1 spawns
    const wave0n = run.enemies.length
    advance(run, BLANK_WAVE_TIMEOUT + 1, dt, { x: 0, y: 0 })
    assert.strictEqual(run.script.waveIdx, 1, `expected timeout to advance waveIdx to 1 even with leftovers alive, got ${run.script.waveIdx}`)
    const stillAlive = run.enemies.filter((e) => !e._dead)
    assert(stillAlive.length > wave0n, `expected wave-1's ${wave0n} leftovers to still linger alongside wave 2, got ${stillAlive.length} alive total`)
    console.log(`PASS run EE.b2 (timeout-advance): waveIdx=1 after idling past ${BLANK_WAVE_TIMEOUT}s, ${wave0n} leftovers still alive (${stillAlive.length} total)`)
  }

  // (c) Boss stage: hard-kill through all 3 waves of the first block -> an antibody1 exists at
  // BLANK_BOSS_R, knockback-immune, with run.bossBar mirroring it; the phase ends ONLY on kill —
  // stripped of weapons, it survives idling well past BLANK_WAVE_TIMEOUT (a wave-stage-only
  // mechanic that must not leak into a boss phase).
  {
    const run = createRun(makeMeta(), { chapter: 'blank', difficulty: 1 })
    run.player.hp = run.player.maxHP = 1e6
    run.weapons = [{ id: 'wave', level: MAX_WEAPON_LEVEL }]
    stepSim(run, { x: 0, y: 0 }, dt) // wave 1 spawns
    for (let w = 0; w < 3; w++) {
      for (const e of run.enemies) {
        if (e._wave && !e._dead) { e.x = run.player.x; e.y = run.player.y; e.hp = e.maxHP = 1 }
      }
      advance(run, 3, dt, { x: 0, y: 0 })
    }
    assert.strictEqual(run.script.stage, 1, `expected the script to reach the boss stage after 3 waves cleared, got stage=${run.script.stage}`)
    const boss = run.enemies.find((e) => e.rosterId === 'antibody1')
    assert(boss, 'expected an antibody1 to have spawned entering the boss stage')
    assert.strictEqual(boss.radius, BLANK_BOSS_R, `expected the boss's radius pinned to BLANK_BOSS_R, got ${boss.radius}`)
    assert(boss.affixes.includes('anchored'), 'expected the boss to carry the anchored (knockback-immune) affix')
    assert(run.bossBar && run.bossBar.stage === 1 && run.bossBar.hp === Math.max(0, boss.hp) && run.bossBar.max === boss.maxHP,
      `expected run.bossBar to mirror the boss, got ${JSON.stringify(run.bossBar)}`)

    run.weapons = [] // isolate the timer check below from the combat that just cleared the waves
    advance(run, BLANK_WAVE_TIMEOUT * 3, dt, { x: 0, y: 0 })
    assert(run.enemies.some((e) => e.id === boss.id && !e._dead), 'expected the boss to survive idling well past BLANK_WAVE_TIMEOUT — only a kill ends a boss phase')
    assert.strictEqual(run.phase, 'playing')
    console.log(`PASS run EE.c (boss stage): antibody1 spawned (r=${boss.radius}, anchored), bossBar mirrors it, survives ${(BLANK_WAVE_TIMEOUT * 3).toFixed(0)}s idle`)
  }

  // (d) Victory: kill antibody1/2/3 through the script (hard-set hp, jumping run.script straight
  // to each boss stage the way (c) reaches stage 1 organically) -> phase flips to 'victory'.
  // Separately: a scripted run idling to t=305s (>= RUN_DURATION) with no weapons at all (so the
  // only way it could reach 'victory' is a timer bug, never a real kill) must NOT auto-victory —
  // the whole RUN_DURATION check is skipped for a scripted chapter (see stepSim's gate).
  {
    const run = createRun(makeMeta(), { chapter: 'blank', difficulty: 1 })
    run.player.hp = run.player.maxHP = 1e6
    run.weapons = [{ id: 'star', level: MAX_WEAPON_LEVEL }]
    for (const stage of [1, 3, 5]) {
      Object.assign(run.script, { stage, waveIdx: 0, waveT: 0, spawned: false, bossId: null })
      stepSim(run, { x: 0, y: 0 }, dt) // spawns this phase's antibody
      const boss = run.enemies[run.enemies.length - 1]
      boss.x = run.player.x; boss.y = run.player.y; boss.hp = boss.maxHP = 1
      advance(run, 2, dt, { x: 0, y: 0 })
      assert(!run.enemies.some((e) => e.id === boss.id && !e._dead), `expected stage ${stage}'s antibody dead within 2s`)
    }
    assert.strictEqual(run.phase, 'victory', `expected phase 'victory' after antibody3 dies, got '${run.phase}'`)
    console.log('PASS run EE.d1 (victory): antibody1/2/3 killed through the script -> phase victory')
  }
  {
    const run = createRun(makeMeta(), { chapter: 'blank', difficulty: 1 })
    run.player.hp = run.player.maxHP = 1e9
    run.weapons = [] // nothing can die — the only way this run reaches 'victory' is a timer bug
    advance(run, 305, dt, { x: 0, y: 0 })
    assert.notStrictEqual(run.phase, 'victory', `expected no timer victory in a scripted chapter, got phase='${run.phase}' at t=${run.time.toFixed(1)}s`)
    console.log(`PASS run EE.d2 (no timer victory): phase='${run.phase}' at t=${run.time.toFixed(1)}s (>= RUN_DURATION)`)
  }

  // (e) Meta: a fresh save starts blank locked at maxDifficulty 1; ensureChapterMeta clamps the
  // PLAYED difficulty into the chapter's own 3-rung ladder (chapterMaxDifficulty('blank') === 3,
  // not the game-wide MAX_DIFFICULTY of 5) while PRESERVING a stray/future maxDifficulty (R3).
  {
    const meta = makeMeta()
    const entry = ensureChapterMeta(meta, 'blank')
    assert.strictEqual(entry.unlocked, false, `expected blank to start locked, got unlocked=${entry.unlocked}`)
    assert.strictEqual(entry.maxDifficulty, 1, `expected a fresh blank entry's maxDifficulty to start at 1, got ${entry.maxDifficulty}`)

    meta.chapters.blank.maxDifficulty = 99
    meta.chapters.blank.difficulty = 99
    const clamped = ensureChapterMeta(meta, 'blank')
    assert.strictEqual(chapterMaxDifficulty('blank'), 3, `expected chapterMaxDifficulty('blank') === 3, got ${chapterMaxDifficulty('blank')}`)
    assert.strictEqual(clamped.maxDifficulty, 99, `expected blank's stray maxDifficulty to be preserved (R3), got ${clamped.maxDifficulty}`)
    assert.strictEqual(clamped.difficulty, 3, `expected blank's PLAYED difficulty to clamp to its own 3-rung cap, got ${clamped.difficulty}`)
    console.log('PASS run EE.e (meta): blank starts locked at maxDifficulty 1; the PLAYED difficulty clamps to its own 3-rung cap')
  }

  console.log('PASS run EE (The Blank): script spawner, clear/timeout advance, boss-phase-ends-only-on-kill, victory, no timer victory, difficulty-3 cap')
}

// ---- Run FF: The Blank's boss mechanics (v5.24 review regressions) ----------------------------
// Locks in the adversarial-review fixes: the victory frame is FINAL even under lethal pressure
// (the review's blocker — hurtPlayer overwriting 'victory' with 'dead' on the detection frame),
// the P1 trail read actually produces src:'trail' bombs, the P2 yank fires/drains/drags, and
// immuneMemory drops erase residue at a wave enemy's corpse.
function testTheBlankBoss() {
  const dt = 1 / 60

  // (a) Victory under fire: kill antibody3 while the player stands at 1 HP inside a live erasure
  // strip. The frame that detects the boss's death must end the run as 'victory' — before the
  // fix, the strip's next damage tick the same frame flipped it to 'dead'.
  {
    const run = createRun(makeMeta(), { chapter: 'blank', difficulty: 1 })
    run.player.hp = run.player.maxHP = 1e6
    run.weapons = [{ id: 'star', level: MAX_WEAPON_LEVEL }]
    Object.assign(run.script, { stage: 5, waveIdx: 0, waveT: 0, spawned: false, bossId: null })
    stepSim(run, { x: 0, y: 0 }, dt) // spawns antibody3
    const boss = run.enemies[run.enemies.length - 1]
    boss.x = run.player.x + 60; boss.y = run.player.y; boss.hp = boss.maxHP = 1
    advance(run, 2, dt, { x: 0, y: 0 })
    assert(!run.enemies.some((e) => e.id === boss.id && !e._dead), 'expected antibody3 dead within 2s')
    // The kill landed but 'victory' may be a frame away (death is detected by id-absence). Pin the
    // lethal situation NOW — a live strip covering the player, 1 HP, no invuln — and step on.
    run.player.hp = 1
    run.player.invuln = 0
    run.strips.push({ x: run.player.x, y: run.player.y, angle: 0, len: 400, w: 400, fuse: 0, t: 5, dps: 1000, look: 'erase' })
    for (let i = 0; i < 10 && run.phase === 'playing'; i++) stepSim(run, { x: 0, y: 0 }, dt)
    assert.strictEqual(run.phase, 'victory', `expected the boss kill to end the run as 'victory' even under lethal strip damage, got '${run.phase}'`)
    console.log('PASS run FF.a (victory under fire): final kill wins even with a lethal strip on the player')
  }

  // (b) P1 trail read: idle in phase 1 past BLANK_READ1_T — the boss detonates the player's trail
  // as src:'trail' bombs (the telegraph->blast machinery), not some other array.
  {
    const run = createRun(makeMeta(), { chapter: 'blank', difficulty: 1 })
    run.player.hp = run.player.maxHP = 1e6
    run.weapons = [] // keep the boss (and the read loop) alive — nothing dies, nothing advances
    Object.assign(run.script, { stage: 1, waveIdx: 0, waveT: 0, spawned: false, bossId: null })
    let sawTrailBomb = false
    const steps = Math.round((BLANK_READ1_T + 1) / dt)
    for (let i = 0; i < steps && run.phase === 'playing'; i++) {
      stepSim(run, { x: 1, y: 0 }, dt) // keep moving so the trail has distinct points
      if (run.bombs.some((b) => b.src === 'trail')) sawTrailBomb = true
    }
    assert(sawTrailBomb, `expected src:'trail' bombs within ${(BLANK_READ1_T + 1).toFixed(1)}s of phase 1`)
    console.log('PASS run FF.b (P1 trail read): trail detonations arrive as src:\'trail\' bombs')
  }

  // (c) P2 yank: age a binding node past BLANK_YANK_T — the player is dragged toward the boss,
  // takes BLANK_YANK_DMG, every node is spent, and a 'yank' event fires.
  {
    const run = createRun(makeMeta(), { chapter: 'blank', difficulty: 1 })
    run.player.hp = run.player.maxHP = 1e6
    run.weapons = [] // nodes must survive to age
    Object.assign(run.script, { stage: 3, waveIdx: 0, waveT: 0, spawned: false, bossId: null })
    stepSim(run, { x: 0, y: 0 }, dt) // spawns antibody2
    // Wait for the first node, then age it artificially instead of idling BLANK_YANK_T real seconds.
    let node = null
    for (let i = 0; i < Math.round((BLANK_NODE_T + 1) / dt) && !node; i++) {
      stepSim(run, { x: 0, y: 0 }, dt)
      node = run.enemies.find((e) => e.rosterId === 'bindnode' && !e._dead) ?? null
    }
    assert(node, 'expected a bindnode within BLANK_NODE_T + 1s of phase 2')
    const hpBefore = run.player.hp
    const px = run.player.x, py = run.player.y
    const boss = run.enemies.find((e) => e.id === run.script.bossId)
    const dBefore = Math.hypot(boss.x - px, boss.y - py)
    node._bindT = BLANK_YANK_T + 1
    run.events.length = 0
    stepSim(run, { x: 0, y: 0 }, dt)
    assert(run.events.some((e) => e.type === 'yank'), 'expected a yank event')
    assert(run.player.hp <= hpBefore - BLANK_YANK_DMG + 1e-9, `expected the yank to cost ${BLANK_YANK_DMG} hp`)
    const dAfter = Math.hypot(boss.x - run.player.x, boss.y - run.player.y)
    assert(dAfter < dBefore - 1, `expected the player dragged toward the boss (${dBefore.toFixed(0)} -> ${dAfter.toFixed(0)}px)`)
    assert(!run.enemies.some((e) => e.rosterId === 'bindnode' && !e._dead), 'expected every node spent by the yank')
    console.log(`PASS run FF.c (P2 yank): dragged ${(dBefore - dAfter).toFixed(0)}px bossward, ${BLANK_YANK_DMG} hp, nodes spent`)
  }

  // (d) immuneMemory: with the difficulty-3 modifier active, a wave enemy's death drops erase
  // residue (a look:'erase' strip) at the corpse.
  {
    const run = createRun(makeMeta(), { chapter: 'blank', difficulty: 3, mutators: ['accelResponse', 'immuneMemory'] })
    run.player.hp = run.player.maxHP = 1e6
    run.weapons = [{ id: 'star', level: MAX_WEAPON_LEVEL }]
    stepSim(run, { x: 0, y: 0 }, dt) // wave 1 spawns
    for (const e of run.enemies) { e.x = run.player.x; e.y = run.player.y; e.hp = e.maxHP = 1 }
    advance(run, 2, dt, { x: 0, y: 0 })
    assert(run.strips.some((s) => s.look === 'erase'), "expected immuneMemory to leave look:'erase' residue at wave corpses")
    console.log('PASS run FF.d (immuneMemory): wave deaths leave erase residue')
  }

  console.log('PASS run FF (The Blank boss mechanics): victory-under-fire, trail bombs, yank, memory residue')
}

// ---- Run GG: chapter-scoped anomalies (v5.25) -------------------------------------------------
// The roll pool respects `chapters` (an anomaly tied to a signature only rolls where that
// signature runs) and `exclude` (sticky's magnet upside is a lie in the beyond's infinite-magnet
// lane; v6.4 adds pond — a flat player-slow stacked on the currents/eddy chapter breaks the
// escape-margin math), and the new signature knobs actually land in run.mods / the seeded world.
function testChapterAnomalies() {
  // Over-asking returns the whole (shuffled) pool — an order-independent membership probe.
  const all = (ch) => randomMutators(99, ch)
  assert(!all('beyond').includes('sticky'), 'sticky must not roll in the beyond')
  assert(all('beyond').includes('supermassive'), 'supermassive must roll in the beyond')
  assert(!all('pond').includes('supermassive'), 'supermassive must not roll outside the beyond')
  assert(all('pond').includes('riptide'), 'pond rolls riptide')
  assert(!all('pond').includes('sticky'), 'v6.4: sticky must not roll in the pond either (MUTATORS.sticky.exclude)')
  assert(!all(undefined).includes('riptide'), 'a chapterless roll excludes every scoped anomaly')
  for (const ch of CHAPTER_ORDER) assert(!all(ch).includes('accelResponse'), 'hidden entries never roll anywhere')
  const rolled = randomMutators(2, 'beyond')
  assert(!rolled.includes('sticky') && !rolled.includes('riptide'), "randomMutators' pool is chapter-scoped too")

  const r1 = createRun(makeMeta(), { chapter: 'beyond', mutators: ['supermassive'] })
  assert.strictEqual(r1.mods.wellForceMul, 1.8, 'supermassive lands in run.mods.wellForceMul')
  assert.strictEqual(createRun(makeMeta(), { chapter: 'pond' }).mods.currentForceMul, 1, 'knobs default neutral')
  // v6.5: traps STREAM (sim.js streamTraps) instead of being seeded once at createRun — trapseason
  // widens the per-cell occupancy chance via mods.trapCountMul, so the assertion pins the same
  // _obstacleSeed on both runs and compares streamed counts after one step, rather than reading
  // run.traps straight off createRun (which is now always []).
  {
    const dt = 1 / 60
    const base = createRun(makeMeta(), { chapter: 'undergrowth' })
    base.mods.spawnMul = 0
    base._obstacleSeed = 0xC0FFEE
    stepSim(base, { x: 0, y: 0 }, dt)
    const baseCount = base.traps.length

    const more = createRun(makeMeta(), { chapter: 'undergrowth', mutators: ['trapseason'] })
    more.mods.spawnMul = 0
    more._obstacleSeed = 0xC0FFEE
    stepSim(more, { x: 0, y: 0 }, dt)
    const moreCount = more.traps.length

    assert(moreCount > baseCount, `expected trap season's higher occupancy chance to stream more traps (${baseCount} -> ${moreCount})`)
    // DEAD WATER (The Shelf's own, 2026-08-20). Two knobs that have to move in OPPOSITE directions
    // or the mutator is a pure nerf wearing a trade's name, and neither is observable from config:
    // `refillChanceMul` thins a streamed field and `refillSpendMul` stretches a clock read in three
    // separate files. Both are asserted as EFFECTS — circles that actually materialise, and charge
    // that actually arrives — because reading run.mods back passes with either consumer deleted.
    {
      // (1) A THIRD AS MANY CIRCLES. Swept over a wide box rather than one cell: at chance 0.62 vs
      // 0.20 a handful of cells can agree by luck while the fields at large differ threefold.
      const fieldSize = (mutators) => {
        Math.random = mulberry32(20260820)
        const r = createRun(makeMeta(), { chapter: 'shelf', difficulty: 1, mutators })
        r.mods.spawnMul = 0
        r._obstacleSeed = 0xC0FFEE
        const cells = new Set()
        for (let y = -4000; y <= 4000; y += 380) {
          for (let x = -4000; x <= 4000; x += 380) {
            r.player.x = x; r.player.y = y
            streamShafts(r)
            for (const sh of r.shafts) cells.add(sh._cell)
          }
        }
        return cells.size
      }
      const wide = fieldSize([])
      const thin = fieldSize(['deadWater'])
      assert(wide > 60, `need a populated field to thin — got ${wide} upwellings`)
      // The ruling is x0.33. The occupancy roll is a hash per cell, so the realised share is
      // binomial around it; the band is wide enough to survive that and far too tight for a
      // multiplier that was dropped on the floor (which lands at 1.0).
      const share = thin / wide
      assert(share > 0.20 && share < 0.50,
        `Dead Water must leave about a third of the upwellings standing: ${thin}/${wide} = ${share.toFixed(2)}`)

      // (2) …AND EACH ONE IS WORTH THREE TIMES AS MUCH. Measured as charge ARRIVING, which is the
      // only thing the player experiences. The drawdown clock is read in stepCharge, in Foul
      // Spring's foulUpwelling and in render.js's fade; a mutator that reached one of the three
      // would show a circle emptying on a schedule the bar disagrees with.
      const oneCircle = (mutators) => {
        Math.random = mulberry32(20260820)
        const r = createRun(makeMeta(), { chapter: 'shelf', difficulty: 1, mutators })
        r.mods.spawnMul = 0
        r.enemies.length = 0
        r.player.maxHP = r.player.hp = 1e9
        r._obstacleSeed = 0xC0FFEE
        r.charge = 0
        streamShafts(r)
        assert(r.shafts.length > 0, 'precondition: need an upwelling to stand in')
        let peak = 0
        for (let i = 0; i < Math.round(12 / dt); i++) {
          // Re-pin every frame: the field DRIFTS (driftAmp 60), so a player parked on a circle's
          // launch position walks out of it without moving. Well inside one cell (760), so this
          // never re-streams the field underneath the measurement.
          const sh = r.shafts[0]
          r.player.x = sh.x; r.player.y = sh.y
          stepSim(r, { x: 0, y: 0 }, dt)
          peak = Math.max(peak, r.charge)
        }
        return peak
      }
      const plain = oneCircle([])
      const dead = oneCircle(['deadWater'])
      assert(plain > 20 && plain < 45,
        `control: one ordinary upwelling is a third of the bar — got ${plain.toFixed(1)} of ${CHAPTERS.shelf.resource.max}`)
      assert(dead > plain * 2.4,
        `Dead Water's circles must be worth about three times as much: ${plain.toFixed(1)} -> ${dead.toFixed(1)}`)
      // The owner's number: three thirds of the bar is the WHOLE bar, and res.max is 100.
      assert(dead > CHAPTERS.shelf.resource.max * 0.9,
        `one Dead Water upwelling must fill essentially the whole bar: ${dead.toFixed(1)} of ${CHAPTERS.shelf.resource.max}`)
      // The mutator is the CHAPTER's, not the book's — Spring Tide names every id with a tide and
      // may never be counted as The Shelf's own (see the ideation bar in verifying-chapter-stage).
      assert.deepStrictEqual(MUTATORS.deadWater.chapters, ['shelf'], 'Dead Water is scoped to The Shelf alone')
      assert(MUTATORS.springtide.chapters.length > 1, "Spring Tide is the book's, so it cannot be any one chapter's own")
      console.log(`PASS run GG.b (Dead Water): ${wide} -> ${thin} upwellings (${share.toFixed(2)}x), one circle worth ${plain.toFixed(0)} -> ${dead.toFixed(0)} of a ${CHAPTERS.shelf.resource.max} bar`)
    }

    console.log(`PASS run GG (chapter anomalies): scoped pools, wellForceMul 1.8, traps ${baseCount}->${moreCount}`)
  }
}

// ---- Run HH: The Blank pacing pass (v6.0.0) --------------------------------------------------
// Locks in the pacing rework: a non-final phase kill banks BLANK_PHASE_LEVELS level-ups, P3's
// antibody chases at its own speed (no standoff flag), fires band CROSSES (two strips ~90° apart
// at the extrapolated point) plus straight BLANK_FAN_N-shot fans, and its recruit pulse keeps an
// endless mixed xp faucet flowing.
function testTheBlankPacing() {
  const dt = 1 / 60

  // (a) Phase-kill levels: killing antibody1 banks at least BLANK_PHASE_LEVELS level-ups.
  {
    const run = createRun(makeMeta(), { chapter: 'blank', difficulty: 1 })
    run.player.hp = run.player.maxHP = 1e6
    run.weapons = [{ id: 'star', level: MAX_WEAPON_LEVEL }]
    Object.assign(run.script, { stage: 1, waveIdx: 0, waveT: 0, spawned: false, bossId: null })
    stepSim(run, { x: 0, y: 0 }, dt) // spawns antibody1
    const before = run.player.level
    const boss = run.enemies[run.enemies.length - 1]
    boss.x = run.player.x; boss.y = run.player.y; boss.hp = boss.maxHP = 1
    advance(run, 3, dt, { x: 0, y: 0 }) // kill + auto-resolve the chained levelups
    assert(run.player.level >= before + BLANK_PHASE_LEVELS,
      `expected a phase kill to bank >= ${BLANK_PHASE_LEVELS} levels (${before} -> ${run.player.level})`)
    console.log(`PASS run HH.a (phase-kill levels): antibody1 kill leveled ${before} -> ${run.player.level}`)
  }

  // (b) P3 chases: antibody3 spawns at BLANK_BOSS_SPEED_P3 with no standoff flag, and actually
  // closes distance on a stationary player. (c) Its reads land as CROSSES — two full-length
  // erase bands ~90° apart (wake residue is short, so filter by BLANK_BAND_LEN) — and (d) its
  // fans as BLANK_FAN_N straight shots per volley.
  {
    const run = createRun(makeMeta(), { chapter: 'blank', difficulty: 1 })
    run.player.hp = run.player.maxHP = 1e6
    run.weapons = [] // keep the boss alive through the whole observation window
    Object.assign(run.script, { stage: 5, waveIdx: 0, waveT: 0, spawned: false, bossId: null })
    stepSim(run, { x: 0, y: 0 }, dt) // spawns antibody3
    const boss = run.enemies.find((e) => e.id === run.script.bossId)
    assert.strictEqual(boss.speed, BLANK_BOSS_SPEED_P3, `expected antibody3 at BLANK_BOSS_SPEED_P3, got ${boss.speed}`)
    assert(!boss.flags.includes('standoff'), 'expected antibody3 without the standoff flag — it chases')
    // Stationary player, boss parked 800px out: the chase closes 170 px/s (never to contact inside
    // the window), and the fan is sampled IN FLIGHT — a shot that reaches the player pops out of
    // run.enemyShots, so an end-of-window length check would race the projectile.
    boss.x = run.player.x + 800; boss.y = run.player.y
    const dBefore = Math.hypot(boss.x - run.player.x, boss.y - run.player.y)
    let fanSeen = 0, allStraight = true
    const steps = Math.round((BLANK_READ3_T + 1) / dt)
    for (let i = 0; i < steps && run.phase === 'playing'; i++) {
      stepSim(run, { x: 0, y: 0 }, dt)
      fanSeen = Math.max(fanSeen, run.enemyShots.length)
      if (run.enemyShots.some((s) => s.turnRate !== 0)) allStraight = false
    }
    // (_lenFull ?? len): a LIVE band is mid-sweep and shorter than the constant it was authored
    // with (BLANK_BAND_GROW) — stepStrips stashes the authored length on the first live frame.
    const bands = run.strips.filter((s) => s.look === 'erase' && (s._lenFull ?? s.len) === BLANK_BAND_LEN)
    assert(bands.length >= 2, `expected a cross (>= 2 full-length bands) within ${(BLANK_READ3_T + 1).toFixed(1)}s, got ${bands.length}`)
    const perp = Math.abs(Math.atan2(Math.sin(bands[0].angle - bands[1].angle), Math.cos(bands[0].angle - bands[1].angle)))
    assert(Math.abs(perp - Math.PI / 2) < 0.01, `expected the cross's bands ~90° apart, got ${(perp * 180 / Math.PI).toFixed(1)}°`)
    assert(fanSeen >= BLANK_FAN_N, `expected a ${BLANK_FAN_N}-shot fan in flight, saw at most ${fanSeen}`)
    assert(allStraight, 'expected P3 fan shots to fly straight (turnRate 0)')
    const dAfter = Math.hypot(boss.x - run.player.x, boss.y - run.player.y)
    assert(dAfter < dBefore - 100, `expected the P3 boss to close on the player (${dBefore.toFixed(0)} -> ${dAfter.toFixed(0)}px)`)
    console.log(`PASS run HH.b-d (P3): chases at ${BLANK_BOSS_SPEED_P3} (${dBefore.toFixed(0)} -> ${dAfter.toFixed(0)}px), cross ${(perp * 180 / Math.PI).toFixed(0)}° apart, ${fanSeen}-shot straight fan`)
  }

  // (d2) The sweep (BLANK_BAND_GROW): a live band REACHES its authored length over `grow` seconds
  // from its centre, so the far end of an arm arrives later than the near end — the fix for "the
  // star hits too soon". Asserted as an EFFECT, not as a length: a player parked 120px out along a
  // 320px band (i.e. 75% of the way to the tip) must not be touched until the arm has swept that
  // far, where the same band without `grow` bites on its first tick. Driven through stepSim in the
  // body chapter, whose only strip producer is this test — enemies spawn a screen away and cannot
  // cross it inside the window, and are cleared each frame anyway.
  {
    const OUT = 120 // px from the band's centre, along its axis: 0.75 of the 160px half-length
    const firstHitAt = (grow) => {
      const run = createRun(makeMeta(), { chapter: 'body', difficulty: 1 })
      run.player.hp = run.player.maxHP = 1e6
      run.weapons = []
      const p = run.player
      run.strips.push({
        x: p.x - OUT, y: p.y, angle: 0, len: BLANK_BAND_LEN, w: BLANK_BAND_W,
        fuse: 0, t: 3, dps: BLANK_BAND_DPS, look: 'erase', ...(grow ? { grow } : {}),
      })
      const hp0 = run.player.hp
      for (let i = 1; i <= Math.round(2.5 / dt) && run.phase === 'playing'; i++) {
        run.enemies.length = 0
        stepSim(run, { x: 0, y: 0 }, dt)
        if (run.player.hp < hp0) return i * dt
      }
      return Infinity
    }
    const swept = firstHitAt(BLANK_BAND_GROW)
    const instant = firstHitAt(0)
    // The arm needs grow x 0.75 to reach OUT, then one STATUS_TICK inside it to land a tick.
    const expect = BLANK_BAND_GROW * (OUT / (BLANK_BAND_LEN / 2)) + STATUS_TICK
    assert(Math.abs(swept - expect) < 0.05, `expected a growing band to reach 120px out at ~${expect.toFixed(2)}s, first hit landed at ${swept.toFixed(2)}s`)
    assert(instant <= STATUS_TICK + 0.02, `expected the same band without grow to bite on its first tick (~${STATUS_TICK}s), got ${instant.toFixed(2)}s`)
    console.log(`PASS run HH.d2 (the star sweeps): 120px out along the arm, a growing band first bit at ${swept.toFixed(2)}s vs ${instant.toFixed(2)}s ungrown — ${(swept - instant).toFixed(2)}s of extra warning at that range`)
  }

  // (e) P3 recruit faucet: idling in the duel keeps spawning mixed fodder — after 10s there are
  // multiple recruits alive and more than one rosterId among them.
  {
    const run = createRun(makeMeta(), { chapter: 'blank', difficulty: 1 })
    run.player.hp = run.player.maxHP = 1e6
    run.weapons = []
    Object.assign(run.script, { stage: 5, waveIdx: 0, waveT: 0, spawned: false, bossId: null })
    stepSim(run, { x: 0, y: 0 }, dt)
    advance(run, 10, dt, { x: 0, y: 0 })
    const recruits = run.enemies.filter((e) => !e._dead && e.id !== run.script.bossId)
    const rids = new Set(recruits.map((e) => e.rosterId))
    assert(recruits.length >= 10, `expected an endless P3 faucet (>= 10 recruits after 10s), got ${recruits.length}`)
    assert(rids.size >= 2, `expected a mixed P3 recruit pulse, got only ${[...rids].join(',')}`)
    console.log(`PASS run HH.e (P3 faucet): ${recruits.length} recruits after 10s idle, mix of ${[...rids].join('/')}`)
  }

  console.log('PASS run HH (The Blank pacing): phase-kill levels, P3 chase, band crosses, straight fans, endless faucet')
}

// ---- Run II: anti-kite straggler recycling (v6.0.1) -------------------------------------------
// Nothing in the game outruns the player, so a committed runner used to shed the whole horde and
// win the survival clock untouched (measured: a weaving diagonal runner beat body/pond/garden at
// 92-95% hp, level 1). stepStragglers recycles any chaser left beyond KITE_DROP_MUL × spawn
// distance behind a MOVING player onto the spawn ring ahead of the heading. Locked here: the
// recycle itself, the stationary exemption, and the lane/scripted chapter exemptions.
function testAntiKite() {
  const dt = 1 / 60
  const place = (run, dist) => {
    const e = makeStatusEnemy(run, { x: run.player.x - dist, y: run.player.y, hp: 50, speed: 0 })
    run.enemies.push(e)
    return e
  }

  // (a) Moving player: a straggler 3000px behind lands on the spawn ring, ahead of the heading.
  {
    const run = createRun(makeMeta(), { chapter: 'body', difficulty: 1 })
    run.player.hp = run.player.maxHP = 1e6
    const e = place(run, 3000)
    stepSim(run, { x: 1, y: 0 }, dt)
    const d = Math.hypot(e.x - run.player.x, e.y - run.player.y)
    const spawnD = run.viewRadius + SPAWN_RING
    assert(Math.abs(d - spawnD) < spawnD * 0.05, `expected the straggler recycled to ~${spawnD.toFixed(0)}px, got ${d.toFixed(0)}`)
    assert(e.x > run.player.x, `expected the recycled straggler AHEAD of a +x runner, got dx=${(e.x - run.player.x).toFixed(0)}`)
    console.log(`PASS run II.a (recycle): straggler 3000px behind -> ${d.toFixed(0)}px ahead of the heading`)
  }

  // (b) Stationary player: the same straggler is never touched.
  {
    const run = createRun(makeMeta(), { chapter: 'body', difficulty: 1 })
    run.player.hp = run.player.maxHP = 1e6
    const e = place(run, 3000)
    stepSim(run, { x: 0, y: 0 }, dt)
    assert(Math.abs(e.x - (run.player.x - 3000)) < 1, 'expected no recycling around a stationary player')
    console.log('PASS run II.b (stationary exemption): distant enemy untouched')
  }

  // (c) Lane and scripted chapters are exempt (they own their spawn geometry).
  for (const chapter of ['beyond', 'blank']) {
    const run = createRun(makeMeta(), { chapter, difficulty: 1 })
    run.player.hp = run.player.maxHP = 1e6
    const e = place(run, 3000)
    stepSim(run, { x: 1, y: 0 }, dt)
    assert(e.x < run.player.x - 2000, `expected the ${chapter} straggler still far behind, got dx=${(e.x - run.player.x).toFixed(0)}`)
    console.log(`PASS run II.c (${chapter} exemption): straggler stays where it was left`)
  }

  console.log('PASS run II (anti-kite): stragglers recycle ahead, stationary/lane/scripted exempt')
}

// ---- Run JJ: v6.2 Remaster (melee parity, toxic shock, new events, reword tables) -------------
function testRemaster() {
  const dt = 1 / 60
  // (a) Melee parity: a flagella sweep shoves — the enemy gains outward push it never had before.
  {
    const run = createRun(makeMeta(), { chapter: 'pond', difficulty: 1 })
    run.player.hp = run.player.maxHP = 1e6
    run.weapons = [{ id: 'flagella', level: 1 }]
    const e = makeStatusEnemy(run, { x: 60, y: 0, hp: 1e6, speed: 0 })
    run.enemies.push(e)
    advance(run, 2, dt, { x: 0, y: 0 })
    assert(Math.abs(e.kb.x) + Math.abs(e.kb.y) > 0 || Math.hypot(e.x, e.y) > 70,
      'expected the flagella sweep to shove the enemy (knockback parity with roar)')
    console.log('PASS run JJ.a (melee parity): flagella hit shoves')
  }
  // (b) Toxic Shock: rolls only in body, lands in run.mods, scales the acid pool's dps.
  {
    assert(randomMutators(99, 'body').includes('toxicShock'), 'toxicShock must roll in body')
    assert(!randomMutators(99, 'pond').includes('toxicShock'), 'toxicShock must not roll outside body')
    const run = createRun(makeMeta(), { chapter: 'body', mutators: ['toxicShock'] })
    assert.strictEqual(run.mods.acidPotencyMul, 1.6, 'toxicShock lands in run.mods.acidPotencyMul')
    console.log('PASS run JJ.b (toxic shock): body-scoped, acidPotencyMul 1.6')
  }
  // (c) New events: chitterShriek emits 'shriek' (not a generic shoot); shard blinks emit 'blink'.
  {
    const run = createRun(makeMeta(), { chapter: 'undergrowth', difficulty: 1 })
    run.player.hp = run.player.maxHP = 1e6
    run.weapons = [{ id: 'chitterShriek', level: 1 }]
    run.enemies.push(makeStatusEnemy(run, { x: 80, y: 0, hp: 1e6, speed: 0 }))
    const seen = advance(run, 4, dt, { x: 0, y: 0 })
    assert(seen.has('shriek'), "expected a 'shriek' event within 4s")
    const run2 = createRun(makeMeta(), { chapter: 'beyond', difficulty: 1 })
    run2.player.hp = run2.player.maxHP = 1e6
    run2.weapons = [{ id: 'realityShard', level: 1 }]
    run2.enemies.push(makeStatusEnemy(run2, { x: 400, y: 0, hp: 1e6, speed: 0 }))
    const seen2 = advance(run2, 4, dt, { x: 0, y: 0 })
    assert(seen2.has('blink'), "expected a 'blink' event within 4s")
    console.log('PASS run JJ.c (new events): shriek + blink emitted')
  }
  // (d) Reword tables: every chapter (incl. blank) has both ending lines; unlock lines cover
  // every non-first CHAPTER_ORDER chapter.
  {
    const shipped = shippedChapterIds()
    // The denominator must be DERIVED, and this is what proves it still is. A full-suite mutation
    // cannot reach here — raising undertow's wipFrom trips two earlier guards in runBooks
    // (`wip.length > 0`, isWipChapter) — so assert the relationship
    // directly: every wip chapter is excluded, and there is at least one, or the exclusion is
    // vacuous and someone could hardcode this list again without a single test noticing.
    const wipIds = wipChapterIds()
    assert(wipIds.length > 0, 'no chapter is wip, so this sweep cannot show its denominator responds to anything')
    for (const id of wipIds) {
      assert(!shipped.includes(id), `wip chapter '${id}' is inside the shipped denominator`)
      assert(Object.hasOwn(CHAPTERS, id), `wip chapter '${id}' is not a real CHAPTERS entry`)
    }
    for (const id of shipped) {
      assert(CHAPTER_ENDINGS[id]?.victory && CHAPTER_ENDINGS[id]?.death,
        `CHAPTER_ENDINGS missing ${id} — a player who wins or dies there gets the generic 'You escaped! 🎉' fallback`)
    }
    // THE FLAVOUR LINE IS OPTIONAL NOW; THE BADGE IS NOT. Owner, 2026-08-22: "I don't like the
    // phrase. Just display New level Unlocked : 2-2 le large." So a chapter with no
    // CHAPTER_UNLOCK_LINES row falls back to the plain numbered badge, and what has to hold for
    // every arrival-chapter is that the FALLBACK resolves — a null number renders the literal
    // word "null" onto the summary screen, which throws nothing and reads as a bug to a player.
    //
    // Asserting the fallback rather than the table is the whole point of the change: the old
    // assertion demanded a row per chapter, so it could only ever have gone red for The Shelf
    // — the chapter whose row the owner then asked to delete.
    //
    // Every book's first rung, with no wip filter of its own: `shipped` has already dropped any
    // book whose opener is still gated, so filtering here too would only be a second chance to
    // disagree with it. The Surf is Undertow's opener, so nothing unlocks it and it owes no badge.
    const openers = new Set(Object.values(BOOKS).map((b) => b.chapters[0]))
    const arrivals = shipped.filter((i) => i !== 'blank' && !openers.has(i))
    for (const id of arrivals) {
      const n = chapterNumber(id)
      assert(n && /^\d+-\d+$/.test(n), `chapterNumber('${id}') is ${JSON.stringify(n)} — the unlock badge would print it verbatim`)
    }
    // The number is DERIVED, so prove it tracks the ladder rather than agreeing with it by luck:
    // The Shelf is Undertow's second rung and Undertow is the second book, which is the owner's
    // own '2-2'. A hardcoded string passes the shape check above and fails this one.
    assert.strictEqual(chapterNumber('shelf'), '2-2', "The Shelf is book 2's second rung — the badge must say 2-2")
    assert.strictEqual(chapterNumber('body'), '1-1', 'The Body is book 1 rung 1')
    assert.strictEqual(chapterNumber('blank'), null, 'a hidden chapter has no rung to number, and gets its own badge')
    assert.strictEqual(chapterNumber('nope'), null, 'an id no book claims must not resolve to a number')
    // The badge's own template, which lives as a tt() literal in ui.js and is therefore INVISIBLE
    // to run XX's config-table walk by construction — the exemption CLAUDE.md says has shipped
    // untranslated copy four times. Asserted here by hand because nothing else can see it.
    assert(FR['New level unlocked: {n} {name}'], 'the plain unlock badge has no French — every non-Book-1 chapter would announce itself in English')
    for (const key of Object.keys(CHAPTER_UNLOCK_LINES)) {
      assert(Object.hasOwn(CHAPTERS, key), `CHAPTER_UNLOCK_LINES has a row for '${key}', which is not a chapter — dead copy run XX will still demand French for`)
    }
    console.log(`PASS run JJ.d (reword tables): endings complete across ${shipped.length} shipped chapters [${shipped.join(' ')}], ${arrivals.length} arrival chapters all number for the badge, ${Object.keys(CHAPTER_UNLOCK_LINES).length} optional flavour lines all name a real chapter`)
  }
  console.log('PASS run JJ (Remaster): melee parity, toxic shock, new events, reword tables')
}

// ---- Run KK: v6.3 city terrain wiring (world seed, road exclusion, curb snapping, density floor)
// CHAPTERS.city gains roads:true and shares the WORLD seed (run._districtSeed) with skies — but
// city's is DERIVED from run._obstacleSeed (state.js) rather than a fresh Math.random() draw, so
// no seeded test's RNG stream can shift (the AA.c/runStarOnly scar, third time). KK.a proves that
// derivation: non-null, deterministic, and free (zero extra draws). KK.b proves streamObstacles
// actually exercises the new gates for a live city run: road exclusion and the post-snap minDist
// re-check (blockSnap can shove a structure back into the spawn clearing).
function testCityTerrainWiring() {
  // (a) world seed: non-null for city, deterministic given the same _obstacleSeed path, skies
  // unaffected, and CHAPTERS.city.roads costs exactly zero Math.random() draws in createRun.
  {
    Math.random = mulberry32(20260714)
    const run1 = createRun(makeMeta(), { chapter: 'city' })
    assert(run1._districtSeed != null, 'expected a city run to get a non-null _districtSeed (v6.3: roads-only chapters derive one from _obstacleSeed)')

    Math.random = mulberry32(20260714)
    const run2 = createRun(makeMeta(), { chapter: 'city' })
    assert.strictEqual(run2._districtSeed, run1._districtSeed, 'expected _districtSeed to be deterministic given the same _obstacleSeed path (same Math.random stream in)')

    Math.random = mulberry32(20260714)
    const skiesRun = createRun(makeMeta(), { chapter: 'skies' })
    assert(skiesRun._districtSeed != null, 'expected skies to keep its own non-null _districtSeed (districts path untouched by v6.3)')

    // RNG-neutrality: reseed identically, create a city run with roads on vs off, and compare the
    // NEXT Math.random() draw after createRun returns — if roads consumed a draw internally, the
    // two streams would have diverged and this next value would differ.
    Math.random = mulberry32(20260714)
    createRun(makeMeta(), { chapter: 'city' })
    const nextWithRoads = Math.random()

    Math.random = mulberry32(20260714)
    const savedRoads = CHAPTERS.city.roads
    CHAPTERS.city.roads = false
    createRun(makeMeta(), { chapter: 'city' })
    CHAPTERS.city.roads = savedRoads
    const nextWithoutRoads = Math.random()

    assert.strictEqual(nextWithRoads, nextWithoutRoads, 'expected CHAPTERS.city.roads to cost zero Math.random() draws in createRun (RNG-neutrality invariant)')
    console.log('PASS run KK.a (city world seed): non-null + deterministic for city, skies unaffected, roads costs zero draws')
  }

  // (b) a live city run: obstacles actually stream in, none centred on roadway, none inside the
  // spawn-ring minDist (including post-blockSnap — the case the pre-snap check alone would miss).
  {
    Math.random = mulberry32(20260714)
    const run = createRun(makeMeta(), { chapter: 'city' })
    run.weapons = []; run.mods.spawnMul = 0
    run.player.hp = run.player.maxHP = 1e9
    const dt = 1 / 60
    let t = 0
    for (let i = 0; i < Math.round(10 / dt); i++) { t += dt; stepSim(run, { x: Math.cos(t), y: Math.sin(t) }, dt) }
    // Teleport well clear of OBSTACLE_CELL (420px) so the next step forces a fresh cell scan —
    // streamObstacles early-returns while the player stays inside the same streaming cell.
    run.player.x += 1200; run.player.y += 1200
    for (let i = 0; i < Math.round(5 / dt); i++) { t += dt; stepSim(run, { x: 0, y: 0 }, dt) }
    assert(run.obstacles.length > 0, 'expected a live city run to stream in real obstacles')

    const cfg = CHAPTERS.city.obstacles
    const onRoad = run.obstacles.filter((o) => roadAt(o.x, o.y, run._districtSeed).onRoad)
    assert.strictEqual(onRoad.length, 0,
      `expected no city obstacle centred on roadway, found ${onRoad.length}/${run.obstacles.length}: ${JSON.stringify(onRoad.slice(0, 3))}`)
    const tooClose = run.obstacles.filter((o) => Math.hypot(o.x, o.y) < cfg.minDist - 1e-6)
    assert.strictEqual(tooClose.length, 0,
      `expected every city obstacle to respect minDist=${cfg.minDist} from spawn (post-snap re-check included), found ${tooClose.length} inside it`)
    console.log(`PASS run KK.b (city road exclusion + post-snap minDist): ${run.obstacles.length} live obstacles, 0 on roadway, 0 inside minDist=${cfg.minDist}`)
  }

  // (c) v6.3 roster rework: weight/minT gate spawnEnemy's pool pick (still the same single
  // Math.random() draw), AERIAL_STRIKE_MAX_LIVE caps concurrent aerial enemies out of 'circle',
  // and (v6.9) the fast lane's post-blink shape: the pigeon carries `flyover` and both it and the
  // rat took the owner's 15% speed cut.
  {
    Math.random = mulberry32(20260714)
    const dt = 1 / 60

    // c1: patrolDrone (minT:60, weight:0.3) is ABSENT from the 'normal' archetype pool before
    // t=60, and settles near its weighted share (0.3/(1+0.3) ≈ 0.23) once eligible. Drives the
    // REAL spawn path — spawnEnemy itself isn't exported, so run._spawnAcc is forced high and
    // consumed in one stepSim call (run.mods.spawnMul=0 keeps the forced value exact; MAX_ALIVE
    // caps it, so `_spawnAcc` is kept comfortably under that) with run.time pinned beforehand, so
    // every spawn in the batch sees the same wave-table/minT window.
    const run = createRun(makeMeta(), { chapter: 'city' })
    run.weapons = []; run.obstacles = []; run._obstacleSeed = null; run.mods.spawnMul = 0
    run.player.x = 0; run.player.y = 0; run.player.hp = run.player.maxHP = 1e9
    run._laneAcc = 1e6 // park traffic: this block is about the roster pool, not the signature

    run.time = 0
    run._spawnAcc = 300
    stepSim(run, { x: 0, y: 0 }, 1e-6)
    const early = run.enemies.filter((e) => e.rosterId === 'ratDrone' || e.rosterId === 'patrolDrone')
    assert(early.length > 0, 'expected at least one normal-archetype spawn before t=60 to make the next assert meaningful')
    const earlyPatrol = early.filter((e) => e.rosterId === 'patrolDrone').length
    assert.strictEqual(earlyPatrol, 0, `expected ZERO patrolDrone spawns before minT=60, got ${earlyPatrol}/${early.length}`)

    run.enemies = []
    run.time = 120
    run._spawnAcc = 400
    stepSim(run, { x: 0, y: 0 }, 1e-6)
    const late = run.enemies.filter((e) => e.rosterId === 'ratDrone' || e.rosterId === 'patrolDrone')
    const latePatrol = late.filter((e) => e.rosterId === 'patrolDrone').length
    const patrolShare = latePatrol / late.length
    assert(late.length >= 150, `expected a sample of ~200+ normal-archetype picks at t=120, got ${late.length}`)
    assert(patrolShare >= 0.15 && patrolShare <= 0.32,
      `expected patrolDrone's share of the normal pool in [0.15, 0.32] (weight 0.3/1.3≈0.23) at t=120, got ${patrolShare.toFixed(3)} (${latePatrol}/${late.length})`)

    // c2: AERIAL_STRIKE_MAX_LIVE — plant more circling aerial enemies than the cap, all with
    // _airT about to expire (every one of them wants to transition this very frame), step once,
    // and assert at most the cap actually left 'circle'.
    const cap = createRun(makeMeta(), { chapter: 'city' })
    cap.weapons = []; cap.obstacles = []; cap._obstacleSeed = null; cap.mods.spawnMul = 0
    cap.player.x = 0; cap.player.y = 0; cap.player.hp = cap.player.maxHP = 1e9
    cap._laneAcc = 1e6
    const n = AERIAL_STRIKE_MAX_LIVE + 3
    const drones = []
    for (let i = 0; i < n; i++) {
      const a = (i / n) * Math.PI * 2
      const d = makeStatusEnemy(cap, { x: Math.cos(a) * 200, y: Math.sin(a) * 200, hp: 1e6, speed: 100 })
      d.flags = ['aerialStrike']
      d._airState = 'circle'
      d._airAngle = a
      d._airT = 0.001 // about to expire
      cap.enemies.push(d)
      drones.push(d)
    }
    stepSim(cap, { x: 0, y: 0 }, 1 / 60)
    const outOfCircle = drones.filter((d) => d._airState !== 'circle').length
    assert(outOfCircle > 0, 'expected the cap to actually let some drones through, not hold everyone')
    assert(outOfCircle <= AERIAL_STRIKE_MAX_LIVE,
      `expected at most AERIAL_STRIKE_MAX_LIVE=${AERIAL_STRIKE_MAX_LIVE} aerial enemies out of 'circle' in one frame, got ${outOfCircle}/${n}`)

    // c3: v6.9 — the pigeon is an ordinary chaser with `flyover` now (blink retired, see the note
    // in config.js), so what's worth pinning here is that the roster entry actually carries it and
    // that both fast-lane speeds took the owner's 15% cut. The flag's BEHAVIOUR is run Y.h's job.
    const fast = CHAPTERS.city.roster.filter((r) => r.archetype === 'fast')
    const pigeonCfg = fast.find((r) => r.id === 'pigeon')
    const ratCfg = fast.find((r) => r.id === 'rat')
    assert(pigeonCfg && ratCfg, 'expected city to keep both fast-lane entries')
    assert.deepStrictEqual(pigeonCfg.flags, ['flyover'], `expected the pigeon to carry only flyover, got ${JSON.stringify(pigeonCfg.flags)}`)
    for (const r of CHAPTERS.city.roster) {
      assert(!r.flags.includes('blink'), `expected no city roster entry to still carry the retired blink flag (${r.id})`)
    }
    // x0.85 of the pre-v6.9 values (pigeon 1.2, rat 1.15), to 2dp.
    assert(Math.abs(pigeonCfg.speedMul - 1.02) < 0.005, `pigeon speedMul ${pigeonCfg.speedMul}`)
    assert(Math.abs(ratCfg.speedMul - 0.98) < 0.005, `rat speedMul ${ratCfg.speedMul}`)

    console.log(`PASS run KK.c (roster v6.3): weight/minT (0 patrolDrone pre-t60 n=${early.length}, share ${patrolShare.toFixed(3)} at t=120 n=${late.length}), strike cap (${outOfCircle}/${n} out of 'circle', cap=${AERIAL_STRIKE_MAX_LIVE}), fast lane cut 15% (pigeon ${pigeonCfg.speedMul} flyover, rat ${ratCfg.speedMul})`)
  }
}

// (d) minimal signed difference between two angles modulo `mod`, folded into [0, mod/2] — used to
// compare a lane's angle against a road's heading (mod pi: either direction of travel is valid) or
// a city's grid (mod pi/2: any of the 4 axes is valid).
function angleModDiff(a, b, mod) {
  let d = a - b
  d -= mod * Math.round(d / mod)
  return Math.abs(d)
}

// ---- Run KK.d: v6.3 street-snapped traffic lanes ------------------------------------------
// stepLanes' roll now reads the real street grid (see TRAFFIC_SNAP_R's doc block, config.js) but
// must still draw EXACTLY the same two Math.random() calls, and the band must ALWAYS contain the
// player regardless of which tier fired. Run Z.b (hand-built lanes, never rolled) is untouched by
// this — if it starts failing, the lane entry SHAPE drifted, which it must not.
function testTrafficLaneSnap() {
  const dt = 1 / 60

  function laneRun() {
    const run = createRun(makeMeta(), { chapter: 'city' })
    run.weapons = []; run.obstacles = []; run._obstacleSeed = null; run.mods.spawnMul = 0
    run.player.hp = run.player.maxHP = 1e9; run.player.invuln = 0
    return run
  }

  // Containment check shared by (a) and (b): the player must sit inside the band the lane just
  // rolled, in the lane's own along/perp frame (mirrors stepLanes' own `inCar` construction).
  function assertPlayerInBand(run, lane, label) {
    const cos = Math.cos(lane.angle), sin = Math.sin(lane.angle)
    const dx = run.player.x - lane.x, dy = run.player.y - lane.y
    const along = dx * cos + dy * sin
    const perp = -dx * sin + dy * cos
    assert(Math.abs(perp) <= TRAFFIC_W / 2 + TRAFFIC_OFFSET + 1e-6,
      `${label}: expected the player within the band's width, perp=${perp.toFixed(2)}`)
    assert(Math.abs(along) <= TRAFFIC_LEN / 2 + 1e-6,
      `${label}: expected the player within the band's length, along=${along.toFixed(2)}`)
  }

  // (1) Tier 1 — on-road snap: scan for a real on-road point, teleport the player onto it, force
  // a roll, and assert the lane landed back on that same road (angle mod pi — either direction of
  // travel is a valid roll) and (3) still crosses the player.
  {
    Math.random = mulberry32(20260714)
    const run = laneRun()
    const seed = run._districtSeed
    let spot = null
    for (let i = -50; i <= 50 && !spot; i++) {
      for (let j = -50; j <= 50; j++) {
        const x = i * 40, y = j * 40
        const ra = roadAt(x, y, seed)
        if (!ra.onRoad) continue
        // Reject a candidate right at a city's own urban-falloff edge: the centerline correction
        // (below, and in sim.js) nudges the point by up to `half` px along the perpendicular, and
        // roadAt gates city streets on urbanAt >= STREET_MIN_URBAN — a spot that's on-road but only
        // barely inside that gate can have its corrected centerline point fall just outside it.
        // That is a real (if rare) property of the terrain at a city's edge, not a bug in the
        // snap math, so the fix is picking a candidate the correction round-trips cleanly, exactly
        // like the sim code below will.
        const probePx = -Math.sin(ra.angle), probePy = Math.cos(ra.angle)
        const probe = roadAt(x + probePx * 8, y + probePy * 8, seed)
        const sgn = probe.onRoad && probe.dist < ra.dist ? 1 : -1
        const cx = x + probePx * sgn * ra.dist, cy = y + probePy * sgn * ra.dist
        if (!roadAt(cx, cy, seed).onRoad) continue
        spot = { x, y, ra }; break
      }
    }
    assert(spot, 'expected to find at least one on-road point (whose centerline correction also lands on-road) scanning a 40px grid over +/-2000px')

    run.player.x = spot.x; run.player.y = spot.y
    run._laneAcc = 0.001
    run.lanes = []
    stepSim(run, { x: 0, y: 0 }, dt)
    assert.strictEqual(run.lanes.length, 1, `expected exactly one lane rolled, got ${run.lanes.length}`)
    const lane = run.lanes[0]

    const laneRoad = roadAt(lane.x, lane.y, seed)
    assert.strictEqual(laneRoad.onRoad, true, `expected the snapped lane to land back on the road, roadAt=${JSON.stringify(laneRoad)}`)
    const angleErr = angleModDiff(lane.angle, spot.ra.angle, Math.PI)
    assert(angleErr < 1e-6, `expected the lane's angle to match the road's heading mod pi, err=${angleErr}`)

    assertPlayerInBand(run, lane, 'tier 1 (on-road snap)')
    console.log(`PASS run KK.d.1/.3 (traffic tier 1: on-road snap + still crosses player): lane at (${lane.x.toFixed(0)},${lane.y.toFixed(0)}) on road, angle err=${angleErr.toExponential(2)}`)
  }

  // (2) Tier 2 — mid-block: an off-road point inside the city. angle snaps to the city's grid
  // (mod pi/2) but position keeps the ordinary player-crossing offset — the band must still
  // contain the player exactly like tier 1 (and tier 3) does.
  {
    Math.random = mulberry32(20260714)
    const run = laneRun()
    const seed = run._districtSeed
    let spot = null
    for (let i = -50; i <= 50 && !spot; i++) {
      for (let j = -50; j <= 50; j++) {
        const x = i * 40, y = j * 40
        if (roadAt(x, y, seed).onRoad) continue
        const near = nearestCity(x, y, seed)
        if (near) { spot = { x, y, city: near.city }; break }
      }
    }
    assert(spot, 'expected to find an off-road, in-city point scanning a 40px grid over +/-2000px')

    run.player.x = spot.x; run.player.y = spot.y
    run._laneAcc = 0.001
    run.lanes = []
    stepSim(run, { x: 0, y: 0 }, dt)
    assert.strictEqual(run.lanes.length, 1, `expected exactly one lane rolled, got ${run.lanes.length}`)
    const lane = run.lanes[0]

    assertPlayerInBand(run, lane, 'tier 2 (mid-block curb-jump)')
    // v6.9.2: the street grid is the WORLD's and axis-aligned, so "aligned with the grid" is now
    // "aligned with the axes" — a city carries no rotation of its own to compare against.
    const angleErr = angleModDiff(lane.angle, 0, Math.PI / 2)
    assert(angleErr < 1e-6, `expected the lane's angle to align with the world grid mod pi/2, err=${angleErr}`)
    console.log(`PASS run KK.d.2 (traffic tier 2: mid-block curb-jump still crosses player): angle err=${angleErr.toExponential(2)}`)
  }

  // (4) RNG discipline: exactly 2 Math.random() draws for one forced roll, whichever tier fires.
  // The proxy is restored in `finally` even if an assertion below throws, so a failure here can't
  // leave every later test in the file drawing from a wrapped Math.random.
  {
    Math.random = mulberry32(20260714)
    const run = laneRun()
    run._laneAcc = 0.001
    run.lanes = []
    const orig = Math.random
    let calls = 0
    Math.random = () => { calls++; return orig() }
    try {
      stepSim(run, { x: 0, y: 0 }, dt)
    } finally {
      Math.random = orig
    }
    assert.strictEqual(run.lanes.length, 1, `expected exactly one lane rolled, got ${run.lanes.length}`)
    assert.strictEqual(calls, 2, `expected exactly 2 Math.random() draws for one lane roll, got ${calls}`)
    console.log('PASS run KK.d.4 (traffic RNG discipline): exactly 2 Math.random() draws per lane roll')
  }
}

// ---- Run KK.e: v6.3 cover — telegraphed, destructible, player-only ---------------------------
// stepLanes' sweep branch now consults findCover (sim.js) before hurting the player: a big enough
// obstacle (o.r >= COVER_MIN_R) standing on the car-center -> player segment is destroyed instead,
// once per lane pass (lane._coverUsed). Same {type:'crush'}/run._crushed contract stepCrush uses
// (skies), reused rather than duplicated. All obstacles here are placed with enough clearance from
// the player (>= o.r + PLAYER.radius) so stepObstacles' ordinary terrain push-out (which runs
// BEFORE stepLanes every frame, and treats city obstacles as solid — CHAPTERS.city has no `crush`
// flag) never relocates the player out from under the hand-placed geometry.
function testCoverDestructible() {
  const dt = 1 / 60

  // A fresh city run with obstacles blanked (both fields, per the file's convention) and the lane
  // roller parked, so the only lane ever alive is the one hand-placed below.
  function coverRun() {
    const run = createRun(makeMeta(), { chapter: 'city' })
    run.weapons = []; run.obstacles = []; run._obstacleSeed = null; run.mods.spawnMul = 0
    run._laneAcc = 1e6
    run.player.hp = run.player.maxHP = 1e9; run.player.invuln = 0
    return run
  }

  // A sweep-phase lane on the world x-axis (angle 0 — the car travels +x, "approaching the player
  // along +x") tuned so that after exactly ONE dt of travel the car's center lands at world x = cx.
  // lane.carT is recomputed from lane.t every step (stepLanes), so seeding `t` (not `carT`) is what
  // actually controls where the car ends up on the NEXT step.
  function sweepLaneAt(cx) {
    const carT = 0.5 + cx / TRAFFIC_LEN
    return {
      x: 0, y: 0, angle: 0, len: TRAFFIC_LEN, w: TRAFFIC_W,
      phase: 'sweep', t: TRAFFIC_SWEEP * (1 - carT) + dt, carT: 0,
      dmg: TRAFFIC_DMG, hitIds: new Set(),
    }
  }

  // (1) + (2): a big enough obstacle between the car and the player takes the hit instead — then,
  // continuing the SAME lane pass, a second (otherwise-valid) shield does NOT save the player again.
  {
    Math.random = mulberry32(20260714)
    const run = coverRun()
    const cx = 200            // car center this step
    const D = 74              // car -> player distance (<= TRAFFIC_CAR_LEN/2=75, so still "in the car")
    run.player.x = cx + D; run.player.y = 0
    const lane = sweepLaneAt(cx)
    run.lanes = [lane]
    // t=0.15 along the car->player segment, well inside the required (0.05, 0.95) window, AND far
    // enough from the player (D*(1-0.15) ≈ 62.9px) to clear r(30)+PLAYER.radius(22)=52 — no terrain
    // push-out before stepLanes ever sees it.
    run.obstacles.push({ x: cx + 0.15 * D, y: 0, r: 30, _cell: 'c1', kind: 'tower' })

    let crushEvents = 0
    stepSim(run, { x: 0, y: 0 }, dt)
    crushEvents += run.events.filter((e) => e.type === 'crush').length
    run.events = [] // drain, mirroring main.js

    assert.strictEqual(run.player.hp, 1e9, 'expected cover to fully absorb the hit — player hp unchanged')
    assert.strictEqual(run.obstacles.length, 0, 'expected the shielding obstacle to be destroyed')
    assert(run._crushed.has('c1'), 'expected the shielding cell recorded into run._crushed')
    assert.strictEqual(lane._coverUsed, true, 'expected lane._coverUsed set after the save')

    // Continuing the SAME pass: the car has advanced by speed*dt: plant a SECOND obstacle that
    // would ALSO validly shield (same t/clearance reasoning as above, against the new car position)
    // to prove the one-save-per-pass rule, not merely "there happened to be no cover left".
    const speed = TRAFFIC_LEN / TRAFFIC_SWEEP // px/s the car travels along the lane
    const cx2 = cx + speed * dt
    const D2 = run.player.x - cx2 // still <= 75: the same lane pass keeps crossing the player
    run.obstacles.push({ x: cx2 + 0.06 * D2, y: 0, r: COVER_MIN_R, _cell: 'c2', kind: 'house' })
    const hpBefore = run.player.hp

    stepSim(run, { x: 0, y: 0 }, dt)
    crushEvents += run.events.filter((e) => e.type === 'crush').length
    run.events = []

    assert(run.player.hp < hpBefore,
      `expected continued overlap to damage the player once cover is spent (${hpBefore} -> ${run.player.hp})`)
    assert.strictEqual(run.obstacles.length, 1, 'expected the second obstacle to survive — cover is one save per pass')
    assert.strictEqual(crushEvents, 1, `expected exactly one crush event across the whole lane pass, got ${crushEvents}`)
    console.log(`PASS run KK.e.1/.2 (cover: shield absorbs the hit, one save per pass): player hp unchanged then ${hpBefore} -> ${run.player.hp}, ${crushEvents} crush event`)
  }

  // (3) COVER_MIN_R: an obstacle just under the threshold never shields — cones don't stop cars.
  {
    Math.random = mulberry32(20260714)
    const run = coverRun()
    const cx = 200, D = 74
    run.player.x = cx + D; run.player.y = 0
    run.lanes = [sweepLaneAt(cx)]
    assert(COVER_MIN_R - 2 < COVER_MIN_R, 'test setup: r must be under COVER_MIN_R')
    run.obstacles.push({ x: cx + 0.15 * D, y: 0, r: COVER_MIN_R - 2, _cell: 'c3', kind: 'tower' })

    const hp0 = run.player.hp
    stepSim(run, { x: 0, y: 0 }, dt)
    assert(run.player.hp < hp0, `expected a sub-COVER_MIN_R obstacle to NOT shield, player hp ${hp0} -> ${run.player.hp}`)
    assert.strictEqual(run.obstacles.length, 1, 'expected the undersized obstacle to survive untouched')
    console.log('PASS run KK.e.3 (COVER_MIN_R gate): an obstacle under the size threshold never shields')
  }

  // (4) An obstacle PAST the player on the car->player segment (t > 0.95, "behind" the player from
  // the car's point of view) never shields either — cover has to stand genuinely BETWEEN the two.
  {
    Math.random = mulberry32(20260714)
    const run = coverRun()
    const cx = 200, D = 74
    run.player.x = cx + D; run.player.y = 0
    run.lanes = [sweepLaneAt(cx)]
    // t=2: twice as far from the car as the player is, i.e. well past them — also far enough from
    // the player itself (D=74px clearance) to avoid the terrain push-out.
    run.obstacles.push({ x: cx + 2 * D, y: 0, r: COVER_MIN_R + 4, _cell: 'c4', kind: 'tower' })

    const hp0 = run.player.hp
    stepSim(run, { x: 0, y: 0 }, dt)
    assert(run.player.hp < hp0, `expected an obstacle behind the player to NOT shield, player hp ${hp0} -> ${run.player.hp}`)
    assert.strictEqual(run.obstacles.length, 1, 'expected the obstacle behind the player to survive untouched')
    console.log('PASS run KK.e.4 (behind the player): an obstacle past the player on the segment never shields')
  }
}

// ---- Run KK.f: v6.3 trafficMain — the lane-aware hydrant mod ------------------------------------
// burstHydrant's trafficMain mod: an eruption centered inside a LIVE lane band (warn telegraph OR
// sweep — pointInLane doesn't care which) deals (1+tm)x damage, resolved once per zone at its own
// (g.x, g.y) — panicRout's "multiply at the damage site" idiom, not a stat fold (WEAPON_STAT_MODS
// never gains a trafficMain entry). The placement bias (pickHydrantSpot, read by stepHydrantWeapon's
// cast) prefers a lane-covered enemy over the plain unbiased pick when the mod is held.
function testTrafficMainHydrant() {
  const dt = 1 / 60

  // A quiet city run: no auto-spawns, no auto-rolled lanes (the roller is parked so the ONLY lane
  // ever live is the one hand-placed per case below), deterministic hit damage (zero crit chance —
  // the AA-series weapon tests' convention).
  function hydrantRun() {
    const run = createRun(makeMeta(), { chapter: 'city' })
    run.weapons = []; run.obstacles = []; run._obstacleSeed = null; run.mods.spawnMul = 0
    run._laneAcc = 1e6
    run.player.x = 0; run.player.y = 0; run.player.hp = run.player.maxHP = 1e9; run.player.invuln = 0
    run.player.critChance = 0 // keep hit damage deterministic (no crit roll)
    return run
  }

  // A static warn-phase band centered on the origin, along the world x-axis — never transitions to
  // 'sweep' within the short windows below, so it never touches the (parked, harmless-anyway) car
  // logic; pointInLane treats warn and sweep identically, so this exercises the same band a sweep
  // lane would.
  function warnLane() {
    return {
      x: 0, y: 0, angle: 0, len: TRAFFIC_LEN, w: TRAFFIC_W,
      phase: 'warn', t: TRAFFIC_WARN, carT: 0, dmg: TRAFFIC_DMG, hitIds: new Set(),
    }
  }

  function stepQuiet(run, seconds) {
    for (let i = 0; i < Math.round(seconds / dt); i++) {
      if (run.phase === 'levelup') { declineLevelUp(run); continue }
      stepSim(run, { x: 0, y: 0 }, dt)
    }
  }

  // (1) Conditional damage: a hand-placed zone centered on a planted enemy INSIDE the band erupts
  // for base*1.4; the identical zone (same dmg) centered on an enemy well outside any band erupts
  // for plain base damage, even with the mod held.
  {
    Math.random = mulberry32(20260714)
    const run = hydrantRun()
    run.weaponMods.burstHydrant.trafficMain = 0.40
    run.lanes = [warnLane()]
    const inLane = makeStatusEnemy(run, { x: 50, y: 0, hp: 1e6, speed: 0 }) // |along|=50<=550, |perp|=0<=65: inside the band
    inLane.flags = []
    run.enemies.push(inLane)
    run.zones.push({ x: 50, y: 0, r: 100, fuse: 0.05, dur: 0.05, dmg: 40 })
    const hp0 = inLane.hp
    stepQuiet(run, 0.1) // clears the fuse
    const dealt = hp0 - inLane.hp
    const expected = Math.round(40 * 1.4)
    assert.strictEqual(dealt, expected, `expected an in-lane eruption to deal base*1.4=${expected}, got ${dealt}`)

    const run2 = hydrantRun()
    run2.weaponMods.burstHydrant.trafficMain = 0.40
    run2.lanes = [warnLane()]
    const outOfLane = makeStatusEnemy(run2, { x: 5000, y: 5000, hp: 1e6, speed: 0 }) // nowhere near the band
    outOfLane.flags = []
    run2.enemies.push(outOfLane)
    run2.zones.push({ x: 5000, y: 5000, r: 100, fuse: 0.05, dur: 0.05, dmg: 40 })
    const hp0b = outOfLane.hp
    stepQuiet(run2, 0.1)
    const dealtB = hp0b - outOfLane.hp
    assert.strictEqual(dealtB, 40, `expected an out-of-lane eruption to deal plain base damage (40), got ${dealtB}`)
    console.log(`PASS run KK.f.1 (trafficMain damage): in-lane dealt ${dealt} (base*1.4=${expected}), out-of-lane dealt ${dealtB} (base)`)
  }

  // (2) Placement bias: two enemies in castRange, only one inside a live band. With the mod held,
  // repeated casts land on the in-lane enemy only; with the mod absent, both get chosen over enough
  // casts (the ordinary unbiased pickBloomSpot pick).
  {
    function runCasts(withMod) {
      Math.random = mulberry32(20260714)
      const run = hydrantRun()
      run.weapons = [{ id: 'burstHydrant', level: MAX_WEAPON_LEVEL }]
      if (withMod) run.weaponMods.burstHydrant.trafficMain = 0.40
      const laneSpot = makeStatusEnemy(run, { x: 100, y: 0, hp: 1e6, speed: 0 })   // in castRange AND in the band
      const clearSpot = makeStatusEnemy(run, { x: 100, y: 200, hp: 1e6, speed: 0 }) // in castRange, outside the band (perp=200 > w/2=65)
      laneSpot.flags = []; clearSpot.flags = []
      // v6.10: an open jet shoves what stands in it outward every frame (HYDRANT_JET_PUSH), so these
      // speed-0 fixtures would drift off their marks and the placement this test is about would
      // read as a miss. 'anchored' is the affix the push already exempts — this test is about WHERE
      // a cast lands, not about the drift, which run AA.e.jet covers directly.
      laneSpot.affixes = ['anchored']; clearSpot.affixes = ['anchored']
      run.enemies.push(laneSpot, clearSpot)
      const spots = []
      for (let i = 0; i < Math.round(11 / dt); i++) {
        run.lanes = [warnLane()] // re-planted every frame: the band never expires mid-test
        if (run.phase === 'levelup') { declineLevelUp(run); continue }
        const before = run.zones.length
        stepSim(run, { x: 0, y: 0 }, dt)
        if (run.zones.length > before || run.zones.some((g) => !g._seenKKf)) {
          for (const g of run.zones) {
            if (!g._seenKKf) { g._seenKKf = true; spots.push({ x: g.x, y: g.y }) }
          }
        }
      }
      return spots
    }

    // v6.10 leads the mark by how far the TARGET travels while the fuse burns (leadSpot: speed x
    // fuse, toward the player). These fixtures are speed 0, so the lead is 0 and the mark lands on
    // the enemy exactly as before — which is the point of a speed-scaled lead and is what makes the
    // original coordinates still the right assertion here. Run AA.e.lead covers a moving target.
    // The band is |y| <= TRAFFIC_W/2 = 65: the in-lane foe qualifies, the clear one (y=200) does
    // not. In-lane placement is the property that matters, since trafficMain's damage bonus is
    // resolved at the ZONE's position, not the target's.
    const LANE_HALF = TRAFFIC_W / 2
    const biased = runCasts(true)
    assert(biased.length >= 3, `expected several hydrants planted over the test window, got ${biased.length}`)
    assert(biased.every((s) => Math.abs(s.y) <= LANE_HALF),
      `expected every hydrant to land INSIDE the band with trafficMain held (|y| <= ${LANE_HALF}), got ${JSON.stringify(biased)}`)
    assert(biased.every((s) => s.x === 100 && s.y === 0),
      `expected every hydrant on the in-lane enemy (speed 0, so no lead), got ${JSON.stringify(biased)}`)

    const unbiased = runCasts(false)
    assert(unbiased.length >= 3, `expected several hydrants planted over the test window, got ${unbiased.length}`)
    const hitLane = unbiased.some((s) => s.x === 100 && s.y === 0)
    const hitClear = unbiased.some((s) => s.x === 100 && s.y === 200)
    assert(hitLane && hitClear, `expected the unbiased pick to land on BOTH enemies across ${unbiased.length} casts, got ${JSON.stringify(unbiased)}`)

    console.log(`PASS run KK.f.2 (trafficMain placement bias): ${biased.length}/${biased.length} in-lane with the mod; unbiased spread across both over ${unbiased.length} casts`)
  }
}

// ---- Run KK.g: v6.3 rain + the dispatch beat ---------------------------------------------------
// Two independent contracts (plan Task 6): (1) a REAL elite born through the ordinary spawn timer
// (spawnEnemy, sim.js — never a hand-placed `elite:true` test fixture) in a chapter carrying
// CHAPTERS[chapter].dispatch (city) pushes exactly one {type:'dispatch'} event; the identical spawn
// path in a chapter WITHOUT the flag (garden) pushes none. (2) stepLanes' cover-emit crush event
// carries kind:'dumpster' unconditionally — never the shielding obstacle's own o.kind — reusing
// KK.e's lane fixture pattern inline.
function testDispatchAndCoverKind() {
  const dt = 1 / 60

  // Force exactly ONE spawn through the REAL spawnEnemy path by priming _spawnAcc directly and
  // zeroing spawnMul, so stepSpawning's `while (_spawnAcc >= 1)` body runs exactly once (1 -> 0,
  // then stops) instead of depending on spawnRate(0)'s actual value. _nextEliteAt = 0 <= run.time
  // (0 on a fresh run) makes that one spawn a genuine elite (isElite, sim.js).
  function spawnOneElite(chapter) {
    Math.random = mulberry32(20260714)
    const run = createRun(makeMeta(), { chapter })
    run.weapons = []; run.obstacles = []; run._obstacleSeed = null
    run.player.hp = run.player.maxHP = 1e9
    run._laneAcc = 1e6 // park city's traffic roller — irrelevant noise for this test
    run._spawnAcc = 1
    run.mods.spawnMul = 0
    run._nextEliteAt = 0
    stepSim(run, { x: 0, y: 0 }, dt)
    const spawned = run.enemies.find((e) => e.elite)
    assert(spawned, `expected the forced spawn to be elite (chapter=${chapter})`)
    return run
  }

  {
    const run = spawnOneElite('city')
    const dispatches = run.events.filter((e) => e.type === 'dispatch')
    assert.strictEqual(dispatches.length, 1, `expected exactly one dispatch event for a city elite spawn, got ${dispatches.length}`)
    console.log('PASS run KK.g.1 (dispatch beat): a city elite spawn pushes exactly one dispatch event')
  }

  {
    const run = spawnOneElite('garden')
    const dispatches = run.events.filter((e) => e.type === 'dispatch')
    assert.strictEqual(dispatches.length, 0, `expected zero dispatch events for a garden elite spawn (CHAPTERS.garden has no dispatch flag), got ${dispatches.length}`)
    console.log('PASS run KK.g.2 (dispatch beat, negative): a garden elite spawn pushes none')
  }

  // (3) cover-crush kind override — KK.e's lane fixture, reused inline. The obstacle is tagged
  // kind:'tower' on purpose: proves the event's kind is FORCED to 'dumpster' at the emit site, not
  // read from the obstacle itself (which stays an ordinary STRUCTURE_KINDS pick elsewhere).
  {
    Math.random = mulberry32(20260714)
    const run = createRun(makeMeta(), { chapter: 'city' })
    run.weapons = []; run.obstacles = []; run._obstacleSeed = null; run.mods.spawnMul = 0
    run._laneAcc = 1e6
    run.player.hp = run.player.maxHP = 1e9; run.player.invuln = 0
    const cx = 200, D = 74
    run.player.x = cx + D; run.player.y = 0
    const carT = 0.5 + cx / TRAFFIC_LEN
    run.lanes = [{
      x: 0, y: 0, angle: 0, len: TRAFFIC_LEN, w: TRAFFIC_W,
      phase: 'sweep', t: TRAFFIC_SWEEP * (1 - carT) + dt, carT: 0,
      dmg: TRAFFIC_DMG, hitIds: new Set(),
    }]
    run.obstacles.push({ x: cx + 0.15 * D, y: 0, r: 30, _cell: 'ckk', kind: 'tower' })

    stepSim(run, { x: 0, y: 0 }, dt)
    const crushEvents = run.events.filter((e) => e.type === 'crush')
    assert.strictEqual(crushEvents.length, 1, `expected exactly one crush event, got ${crushEvents.length}`)
    assert.strictEqual(crushEvents[0].kind, 'dumpster', `expected the cover-kill crush event's kind forced to 'dumpster', got '${crushEvents[0].kind}'`)
    console.log("PASS run KK.g.3 (cover-crush flavor): the shield's crush event carries kind 'dumpster' regardless of its own o.kind")
  }
}

// ---- Run LL: v6.3.1 blank difficulty pass (doubled waves, ×4 boss HP, faster P1, fight-wide
// desperation, crossReactive d2+, affinityMature d3) ----------------------------------------------
// Locks in the owner-directed difficulty pass: waves twice as big, the boss four times as tough
// with desperation felt in every phase (not just P3), a faster P1 whose catch-up gear is capped so
// fleeing never stops working, and two new hidden ladder mutators built entirely from existing
// bombs/enemyShots/strips machinery.
function testTheBlankDifficulty() {
  const dt = 1 / 60

  // (a) P1 borrowed shot (crossReactive, d2+): idling in phase 1 with the mutator active fires
  // P2's exact homing shot on its own timer. Control at d1 (no mutators): none.
  {
    const run = createRun(makeMeta(), { chapter: 'blank', difficulty: 2, mutators: ['accelResponse', 'crossReactive'] })
    run.player.hp = run.player.maxHP = 1e6
    run.weapons = []
    Object.assign(run.script, { stage: 1, waveIdx: 0, waveT: 0, spawned: false, bossId: null })
    stepSim(run, { x: 0, y: 0 }, dt) // spawns antibody1
    const steps = Math.round((BLANK_SHOT_T * BLANK_ACCEL_MUL + 0.5) / dt)
    for (let i = 0; i < steps && run.phase === 'playing'; i++) stepSim(run, { x: 0, y: 0 }, dt)
    assert(run.enemyShots.length > 0, 'expected P1 to fire a borrowed homing shot with crossReactive active at d2')
    assert(run.enemyShots.every((s) => s.turnRate === BLANK_SHOT_TURN), `expected the borrowed shot's turnRate === BLANK_SHOT_TURN, got ${run.enemyShots.map((s) => s.turnRate)}`)
    console.log(`PASS run LL.a.1 (P1 borrowed shot): ${run.enemyShots.length} enemyShots, turnRate=${BLANK_SHOT_TURN}`)
  }
  {
    const run = createRun(makeMeta(), { chapter: 'blank', difficulty: 1 })
    run.player.hp = run.player.maxHP = 1e6
    run.weapons = []
    Object.assign(run.script, { stage: 1, waveIdx: 0, waveT: 0, spawned: false, bossId: null })
    stepSim(run, { x: 0, y: 0 }, dt)
    const steps = Math.round((BLANK_SHOT_T * BLANK_ACCEL_MUL + 0.5) / dt)
    for (let i = 0; i < steps && run.phase === 'playing'; i++) stepSim(run, { x: 0, y: 0 }, dt)
    assert.strictEqual(run.enemyShots.length, 0, `expected zero P1 shots without crossReactive at d1, got ${run.enemyShots.length}`)
    console.log('PASS run LL.a.2 (control, d1): no P1 borrowed shot without crossReactive')
  }

  // (b) P2 borrowed read (crossReactive, d2+): moving in a slow circle, P2 detonates a SPREAD
  // trail read (P1's read, sampled every BLANK_XREACT_STRIDE-th point) on its own cadence. Control
  // at d1: no trail bombs during P2. Then: a bindnode that survives to the boss's death is
  // force-killed the same frame (phase-advance node cleanup) — no live node lingers into the next
  // block.
  {
    const run = createRun(makeMeta(), { chapter: 'blank', difficulty: 2, mutators: ['accelResponse', 'crossReactive'] })
    run.player.hp = run.player.maxHP = 1e6
    run.weapons = []
    Object.assign(run.script, { stage: 3, waveIdx: 0, waveT: 0, spawned: false, bossId: null })
    stepSim(run, { x: 0, y: 0 }, dt) // spawns antibody2
    const steps = Math.round((BLANK_READ1_T * BLANK_XREACT_READ1_MUL * BLANK_ACCEL_MUL + 2) / dt)
    // Sample DURING the loop, not after: a trail bomb's own fuse+stagger is short (~1-2s) next to
    // the read cadence (~5.6s here), so by loop's end the whole batch has already self-detonated
    // and been filtered out of run.bombs — checking only the final state would always see zero.
    let sawTrailBomb = false
    for (let i = 0; i < steps && run.phase === 'playing'; i++) {
      const a = i * dt * 0.5
      stepSim(run, { x: Math.cos(a), y: Math.sin(a) }, dt)
      if (run.bombs.some((b) => b.src === 'trail')) sawTrailBomb = true
    }
    assert(sawTrailBomb, "expected P2's borrowed trail read to push src:'trail' bombs with crossReactive at d2")
    console.log('PASS run LL.b.1 (P2 borrowed read): src:\'trail\' bombs seen during the window')
  }
  {
    const run = createRun(makeMeta(), { chapter: 'blank', difficulty: 1 })
    run.player.hp = run.player.maxHP = 1e6
    run.weapons = []
    Object.assign(run.script, { stage: 3, waveIdx: 0, waveT: 0, spawned: false, bossId: null })
    stepSim(run, { x: 0, y: 0 }, dt)
    const steps = Math.round((BLANK_READ1_T * BLANK_XREACT_READ1_MUL + 2) / dt)
    for (let i = 0; i < steps && run.phase === 'playing'; i++) {
      const a = i * dt * 0.5
      stepSim(run, { x: Math.cos(a), y: Math.sin(a) }, dt)
    }
    assert.strictEqual(run.bombs.filter((b) => b.src === 'trail').length, 0, 'expected zero P2 trail bombs without crossReactive at d1')
    console.log('PASS run LL.b.2 (control, d1): no P2 borrowed read without crossReactive')
  }
  {
    const run = createRun(makeMeta(), { chapter: 'blank', difficulty: 2, mutators: ['accelResponse', 'crossReactive'] })
    run.player.hp = run.player.maxHP = 1e6
    run.weapons = []
    Object.assign(run.script, { stage: 3, waveIdx: 0, waveT: 0, spawned: false, bossId: null })
    stepSim(run, { x: 0, y: 0 }, dt) // spawns antibody2
    let node = null
    for (let i = 0; i < Math.round((BLANK_NODE_T + 1) / dt) && !node; i++) {
      stepSim(run, { x: 0, y: 0 }, dt)
      node = run.enemies.find((e) => e.rosterId === 'bindnode' && !e._dead) ?? null
    }
    assert(node, 'expected a bindnode to spawn during P2 idle')
    const boss = run.enemies.find((e) => e.id === run.script.bossId)
    boss.x = run.player.x; boss.y = run.player.y; boss.hp = boss.maxHP = 1
    run.weapons = [{ id: 'star', level: MAX_WEAPON_LEVEL }]
    advance(run, 2, dt, { x: 0, y: 0 }) // kill the boss + auto-resolve any chained levelups
    assert(!run.enemies.some((e) => e.id === boss.id && !e._dead), 'expected the P2 boss dead within 2s')
    assert(!run.enemies.some((e) => e.rosterId === 'bindnode' && !e._dead), 'expected no live bindnode surviving the P2 boss\'s death (phase-advance node cleanup)')
    console.log("PASS run LL.b.3 (node cleanup on phase death): a surviving bindnode is force-killed with the boss")
  }

  // (c) P3 star + fan + echo (affinityMature at d3, crossReactive at d2+): at d3 the cross becomes
  // an 8-arm star (BLANK_BAND_ANGLES_MATURE), the fan grows to BLANK_FAN_N_MATURE shots, and a
  // borrowed short trail echo (<= BLANK_XREACT_READ3_K bombs) appears. At d2 (crossReactive only,
  // no affinityMature) the cross stays a plain cross and the fan stays BLANK_FAN_N.
  {
    const run = createRun(makeMeta(), { chapter: 'blank', difficulty: 3, mutators: ['accelResponse', 'crossReactive', 'immuneMemory', 'affinityMature'] })
    run.player.hp = run.player.maxHP = 1e6
    run.weapons = []
    Object.assign(run.script, { stage: 5, waveIdx: 0, waveT: 0, spawned: false, bossId: null })
    stepSim(run, { x: 0, y: 0 }, dt) // spawns antibody3
    let stripsAtRead = 0, fanSeen = 0, echoSeen = 0
    const steps = Math.round((BLANK_READ1_T * BLANK_ACCEL_MUL + 1) / dt)
    for (let i = 0; i < steps && run.phase === 'playing'; i++) {
      const before = run.strips.length
      const beforeShots = run.enemyShots.length
      stepSim(run, { x: 0, y: 0 }, dt)
      const added = run.strips.length - before
      if (added > 0 && stripsAtRead === 0) stripsAtRead = added
      // Per-FRAME shot delta, not live count: volleys outlive the fan cadence, so a live count
      // accumulates across volleys and can't tell a 5-shot fan from two overlapping 3-shot ones.
      fanSeen = Math.max(fanSeen, run.enemyShots.length - beforeShots)
      echoSeen = Math.max(echoSeen, run.bombs.filter((b) => b.src === 'trail').length)
    }
    assert.strictEqual(stripsAtRead, BLANK_BAND_ANGLES_MATURE.length, `expected an ${BLANK_BAND_ANGLES_MATURE.length}-arm star at d3, got ${stripsAtRead} strips in the first read`)
    assert.strictEqual(fanSeen, BLANK_FAN_N_MATURE, `expected a ${BLANK_FAN_N_MATURE}-shot fan volley at d3, biggest volley was ${fanSeen}`)
    assert(echoSeen > 0 && echoSeen <= BLANK_XREACT_READ3_K, `expected 1..${BLANK_XREACT_READ3_K} borrowed trail-echo bombs at d3, saw ${echoSeen}`)
    console.log(`PASS run LL.c.1 (P3 star+fan+echo, d3): ${stripsAtRead} strips/read, ${fanSeen}-shot fan, ${echoSeen} echo bombs`)
  }
  {
    const run = createRun(makeMeta(), { chapter: 'blank', difficulty: 2, mutators: ['accelResponse', 'crossReactive'] })
    run.player.hp = run.player.maxHP = 1e6
    run.weapons = []
    Object.assign(run.script, { stage: 5, waveIdx: 0, waveT: 0, spawned: false, bossId: null })
    stepSim(run, { x: 0, y: 0 }, dt)
    let stripsAtRead = 0, fanSeen = 0
    const steps = Math.round((BLANK_READ1_T * BLANK_ACCEL_MUL + 1) / dt)
    for (let i = 0; i < steps && run.phase === 'playing'; i++) {
      const before = run.strips.length
      const beforeShots = run.enemyShots.length
      stepSim(run, { x: 0, y: 0 }, dt)
      const added = run.strips.length - before
      if (added > 0 && stripsAtRead === 0) stripsAtRead = added
      fanSeen = Math.max(fanSeen, run.enemyShots.length - beforeShots)
    }
    assert.strictEqual(stripsAtRead, BLANK_BAND_ANGLES.length, `expected a plain ${BLANK_BAND_ANGLES.length}-band cross at d2 (no affinityMature), got ${stripsAtRead}`)
    assert.strictEqual(fanSeen, BLANK_FAN_N, `expected the base ${BLANK_FAN_N}-shot fan volley at d2, biggest volley was ${fanSeen}`)
    console.log(`PASS run LL.c.2 (control, d2): ${stripsAtRead} strips/read (plain cross), ${fanSeen}-shot fan (no mature growth)`)
  }

  // (d) Mature P1 read depth: at d3 a full trail (walked past BLANK_TRAIL_MAX samples) yields
  // BLANK_READ1_K_MATURE bombs per read instead of the base BLANK_READ1_K.
  {
    const run = createRun(makeMeta(), { chapter: 'blank', difficulty: 3, mutators: ['accelResponse', 'crossReactive', 'immuneMemory', 'affinityMature'] })
    run.player.hp = run.player.maxHP = 1e6
    run.weapons = []
    Object.assign(run.script, { stage: 1, waveIdx: 0, waveT: 0, spawned: false, bossId: null })
    stepSim(run, { x: 0, y: 0 }, dt) // spawns antibody1
    const fillSteps = Math.round((BLANK_TRAIL_MAX * BLANK_TRAIL_DT + 1) / dt)
    for (let i = 0; i < fillSteps; i++) stepSim(run, { x: 1, y: 0 }, dt)
    let bombsAtRead = 0
    const readSteps = Math.round((BLANK_READ1_T * BLANK_ACCEL_MUL + 1) / dt)
    for (let i = 0; i < readSteps && bombsAtRead === 0; i++) {
      const before = run.bombs.filter((b) => b.src === 'trail').length
      stepSim(run, { x: 1, y: 0 }, dt)
      const added = run.bombs.filter((b) => b.src === 'trail').length - before
      if (added > 0) bombsAtRead = added
    }
    assert.strictEqual(bombsAtRead, BLANK_READ1_K_MATURE, `expected ${BLANK_READ1_K_MATURE} bombs in one P1 read at d3, got ${bombsAtRead}`)
    console.log(`PASS run LL.d.1 (mature P1 read K): ${bombsAtRead} bombs in one full-trail read at d3`)
  }
  {
    const run = createRun(makeMeta(), { chapter: 'blank', difficulty: 1 })
    run.player.hp = run.player.maxHP = 1e6
    run.weapons = []
    Object.assign(run.script, { stage: 1, waveIdx: 0, waveT: 0, spawned: false, bossId: null })
    stepSim(run, { x: 0, y: 0 }, dt)
    const fillSteps = Math.round((BLANK_TRAIL_MAX * BLANK_TRAIL_DT + 1) / dt)
    for (let i = 0; i < fillSteps; i++) stepSim(run, { x: 1, y: 0 }, dt)
    let bombsAtRead = 0
    const readSteps = Math.round((BLANK_READ1_T + 1) / dt)
    for (let i = 0; i < readSteps && bombsAtRead === 0; i++) {
      const before = run.bombs.filter((b) => b.src === 'trail').length
      stepSim(run, { x: 1, y: 0 }, dt)
      const added = run.bombs.filter((b) => b.src === 'trail').length - before
      if (added > 0) bombsAtRead = added
    }
    assert.strictEqual(bombsAtRead, BLANK_READ1_K, `expected the base ${BLANK_READ1_K} bombs in one P1 read at d1, got ${bombsAtRead}`)
    console.log(`PASS run LL.d.2 (control, d1): ${bombsAtRead} bombs in one full-trail read (base K)`)
  }

  // (e) Speed/HP pins + catch-up cap: P1 spawns at BLANK_BOSS_SPEED_P1 with BLANK_BOSS_HP[0] maxHP
  // (d1, enemyHpMul 1); P2 spawns at the base BLANK_BOSS_SPEED. A P1 boss teleported far away and
  // left to pursue closes distance faster than its base speed (the catch-up gear engaging) but
  // never faster than BLANK_CATCHUP_MAX (fleeing must always work).
  {
    const run = createRun(makeMeta(), { chapter: 'blank', difficulty: 1 })
    run.player.hp = run.player.maxHP = 1e6
    run.weapons = []
    Object.assign(run.script, { stage: 1, waveIdx: 0, waveT: 0, spawned: false, bossId: null })
    stepSim(run, { x: 0, y: 0 }, dt)
    const boss = run.enemies.find((e) => e.id === run.script.bossId)
    assert.strictEqual(boss.speed, BLANK_BOSS_SPEED_P1, `expected antibody1 speed pinned to BLANK_BOSS_SPEED_P1, got ${boss.speed}`)
    assert.strictEqual(boss.maxHP, BLANK_BOSS_HP[0], `expected antibody1 maxHP pinned to BLANK_BOSS_HP[0] (d1, enemyHpMul 1), got ${boss.maxHP}`)
    console.log(`PASS run LL.e.1 (P1 speed+HP pins): speed=${boss.speed}, maxHP=${boss.maxHP}`)

    boss.x = run.player.x + 2000; boss.y = run.player.y
    const before = { x: boss.x, y: boss.y }
    for (let i = 0; i < Math.round(1 / dt); i++) stepSim(run, { x: 0, y: 0 }, dt)
    const boss2 = run.enemies.find((e) => e.id === run.script.bossId)
    const moved = Math.hypot(boss2.x - before.x, boss2.y - before.y)
    assert(moved <= BLANK_CATCHUP_MAX * 1 + 5, `expected the capped pursuit to move <= ${BLANK_CATCHUP_MAX}px + slack in 1s, moved ${moved.toFixed(1)}px`)
    assert(moved > BLANK_BOSS_SPEED_P1 * 1, `expected the catch-up gear to engage (faster than base ${BLANK_BOSS_SPEED_P1}px/s), moved ${moved.toFixed(1)}px`)
    console.log(`PASS run LL.e.2 (catch-up cap): boss moved ${moved.toFixed(1)}px in 1s (base ${BLANK_BOSS_SPEED_P1}, cap ${BLANK_CATCHUP_MAX})`)
  }
  {
    const run = createRun(makeMeta(), { chapter: 'blank', difficulty: 1 })
    run.player.hp = run.player.maxHP = 1e6
    run.weapons = []
    Object.assign(run.script, { stage: 3, waveIdx: 0, waveT: 0, spawned: false, bossId: null })
    stepSim(run, { x: 0, y: 0 }, dt)
    const boss = run.enemies.find((e) => e.id === run.script.bossId)
    assert.strictEqual(boss.speed, BLANK_BOSS_SPEED, `expected antibody2 speed pinned to the base BLANK_BOSS_SPEED, got ${boss.speed}`)
    console.log(`PASS run LL.e.3 (P2 speed pin): speed=${boss.speed}`)
  }

  // (f) Fight-wide desperation: a phase below BLANK_DESPERATE_FRAC hp accelerates its read cadence
  // to BLANK_READ1_T × BLANK_DESPERATE_MUL (was P3-only before v6.3.1). The FIRST read still fires
  // at the un-scaled arm value (armed once at boss spawn, before hp is forced down); the interval
  // AFTER that first read is the one that reflects the desperate re-arm, so that's the gap measured.
  {
    function measureSecondGap(hpFrac) {
      const run = createRun(makeMeta(), { chapter: 'blank', difficulty: 1 })
      run.player.hp = run.player.maxHP = 1e6
      run.weapons = []
      Object.assign(run.script, { stage: 1, waveIdx: 0, waveT: 0, spawned: false, bossId: null })
      stepSim(run, { x: 0, y: 0 }, dt) // spawns antibody1
      const boss = run.enemies.find((e) => e.id === run.script.bossId)
      boss.hp = boss.maxHP * hpFrac
      // Detect each read by the 0 -> >0 EDGE of the trail-bomb count, not a running peak: a read's
      // own bombs self-detonate (~1-2s, well under the ~5s/~3.1s cadence) and get filtered out of
      // run.bombs well before the next read fires, so a later read pushing the SAME count (e.g. 8
      // again) would never look like an "increase" over the first read's already-recorded peak.
      let lastCount = 0, gaps = [], sinceLast = 0
      const steps = Math.round((BLANK_READ1_T * 3 + 2) / dt)
      for (let i = 0; i < steps; i++) {
        stepSim(run, { x: 0, y: 0 }, dt)
        sinceLast += dt
        const count = run.bombs.filter((b) => b.src === 'trail').length
        if (count > 0 && lastCount === 0) {
          gaps.push(sinceLast)
          sinceLast = 0
        }
        lastCount = count
      }
      return gaps
    }
    const desperateGaps = measureSecondGap(0.1)
    const fullGaps = measureSecondGap(1.0)
    assert(desperateGaps.length >= 2, `expected >= 2 reads to measure a desperate-cadence gap, got ${desperateGaps.length}`)
    assert(fullGaps.length >= 2, `expected >= 2 reads to measure a full-hp gap, got ${fullGaps.length}`)
    const tol = dt * 2
    const expectDesperate = BLANK_READ1_T * BLANK_DESPERATE_MUL
    const expectFull = BLANK_READ1_T
    assert(Math.abs(desperateGaps[1] - expectDesperate) < tol, `expected the desperate-phase read gap ~= ${expectDesperate.toFixed(3)}s (±${tol.toFixed(3)}), got ${desperateGaps[1].toFixed(3)}s`)
    assert(Math.abs(fullGaps[1] - expectFull) < tol, `expected the full-hp read gap ~= ${expectFull.toFixed(3)}s (±${tol.toFixed(3)}), got ${fullGaps[1].toFixed(3)}s`)
    console.log(`PASS run LL.f (fight-wide desperation): P1's read gap ${fullGaps[1].toFixed(2)}s at full hp -> ${desperateGaps[1].toFixed(2)}s at 10% hp`)
  }

  // (g) Residue widening + variant tag: immuneMemory (d3) now drops erase residue at ANY
  // scripted-chapter corpse, not just _wave ones — including P1's recruit faucet — tagged
  // variant:'residue'. Control at d1 (no immuneMemory): none. The boss's own P3 bands carry no
  // variant tag at all (they must read as visually distinct from the dimmed residue).
  {
    const run = createRun(makeMeta(), { chapter: 'blank', difficulty: 3, mutators: ['accelResponse', 'crossReactive', 'immuneMemory', 'affinityMature'] })
    run.player.hp = run.player.maxHP = 1e6
    run.weapons = []
    Object.assign(run.script, { stage: 1, waveIdx: 0, waveT: 0, spawned: false, bossId: null })
    stepSim(run, { x: 0, y: 0 }, dt) // spawns antibody1
    let recruit = null
    for (let i = 0; i < Math.round(8 / dt) && !recruit; i++) {
      stepSim(run, { x: 0, y: 0 }, dt)
      recruit = run.enemies.find((e) => !e._dead && !e._wave && e.id !== run.script.bossId) ?? null
    }
    assert(recruit, 'expected the P1 recruit drip to spawn a non-_wave enemy within 8s')
    recruit.x = run.player.x; recruit.y = run.player.y; recruit.hp = recruit.maxHP = 1
    run.weapons = [{ id: 'star', level: MAX_WEAPON_LEVEL }]
    advance(run, 1, dt, { x: 0, y: 0 })
    const residue = run.strips.find((s) => s.look === 'erase' && s.variant === 'residue')
    assert(residue, "expected immuneMemory to drop a variant:'residue' strip at a non-wave recruit's corpse")
    console.log("PASS run LL.g.1 (residue widening): a non-wave recruit's death leaves variant:'residue' erase residue")
  }
  {
    const run = createRun(makeMeta(), { chapter: 'blank', difficulty: 1 })
    run.player.hp = run.player.maxHP = 1e6
    run.weapons = []
    Object.assign(run.script, { stage: 1, waveIdx: 0, waveT: 0, spawned: false, bossId: null })
    stepSim(run, { x: 0, y: 0 }, dt)
    let recruit = null
    for (let i = 0; i < Math.round(8 / dt) && !recruit; i++) {
      stepSim(run, { x: 0, y: 0 }, dt)
      recruit = run.enemies.find((e) => !e._dead && !e._wave && e.id !== run.script.bossId) ?? null
    }
    assert(recruit, 'expected the P1 recruit drip to spawn a non-_wave enemy within 8s (control)')
    recruit.x = run.player.x; recruit.y = run.player.y; recruit.hp = recruit.maxHP = 1
    run.weapons = [{ id: 'star', level: MAX_WEAPON_LEVEL }]
    advance(run, 1, dt, { x: 0, y: 0 })
    assert(!run.strips.some((s) => s.variant === 'residue'), 'expected no residue-tagged strips without immuneMemory at d1')
    console.log('PASS run LL.g.2 (control, d1): no residue strips without immuneMemory')
  }
  {
    const run = createRun(makeMeta(), { chapter: 'blank', difficulty: 3, mutators: ['accelResponse', 'crossReactive', 'immuneMemory', 'affinityMature'] })
    run.player.hp = run.player.maxHP = 1e6
    run.weapons = []
    Object.assign(run.script, { stage: 5, waveIdx: 0, waveT: 0, spawned: false, bossId: null })
    stepSim(run, { x: 0, y: 0 }, dt) // spawns antibody3
    advance(run, BLANK_READ3_T * BLANK_ACCEL_MUL + 1, dt, { x: 0, y: 0 })
    const bands = run.strips.filter((s) => s.look === 'erase' && (s._lenFull ?? s.len) === BLANK_BAND_LEN)
    assert(bands.length > 0, 'expected P3 star/cross bands to appear within the window')
    assert(bands.every((s) => s.variant === undefined), "expected the boss's own P3 bands to carry NO variant tag")
    console.log(`PASS run LL.g.3 (boss bands untagged): ${bands.length} P3 bands, none tagged variant`)
  }

  // (h) Doubled waves + the blank's own cap: BLANK_SCRIPT's wave-1 size is confirmed doubled, and
  // padding the field to BLANK_MAX_ALIVE - 1 leaves exactly one slot free for the next wave spawn —
  // spawnBlankEnemy nulls out past that without stepSim throwing.
  {
    const wave0 = BLANK_SCRIPT[0].waves[0]
    assert.strictEqual(wave0.n, 128, `expected wave 1's size at the v6.3.3 horde scale (128), got ${wave0.n}`)

    const run = createRun(makeMeta(), { chapter: 'blank', difficulty: 1 })
    run.player.hp = run.player.maxHP = 1e6
    run.weapons = []
    for (let i = 0; i < BLANK_MAX_ALIVE - 1; i++) {
      run.enemies.push(makeStatusEnemy(run, { x: 5000 + i, y: 5000, hp: 1e6, speed: 0 }))
    }
    assert.strictEqual(run.enemies.length, BLANK_MAX_ALIVE - 1)
    stepSim(run, { x: 0, y: 0 }, dt) // wave 1 spawn attempt: 32 requested, only 1 slot free
    assert.strictEqual(run.enemies.length, BLANK_MAX_ALIVE, `expected exactly one more enemy admitted at the blank cap, got ${run.enemies.length}`)
    assert(run.script.spawned, 'expected the wave to be marked spawned even though most of its spawns were capped out')
    console.log(`PASS run LL.h (doubled waves + blank cap): wave0.n=${wave0.n}, padded to ${BLANK_MAX_ALIVE - 1} -> capped cleanly at ${run.enemies.length}`)
  }

  // (i) v6.3.3 wave xp cut: a _wave-tagged body is worth a third of its roster xp; the boss-phase
  // recruit drip (same rosterId, no _wave tag) keeps full value.
  {
    const run = createRun(makeMeta(), { chapter: 'blank', difficulty: 1 })
    run.player.hp = run.player.maxHP = 1e6
    run.weapons = []
    stepSim(run, { x: 0, y: 0 }, dt) // spawns wave 1 (all probes)
    const waveProbe = run.enemies.find((e) => e._wave && e.rosterId === 'probe')
    assert(waveProbe, 'expected a wave probe')
    Object.assign(run.script, { stage: 1, waveIdx: 0, waveT: 0, spawned: false, bossId: null })
    stepSim(run, { x: 0, y: 0 }, dt) // spawns antibody1, arms the recruit timer
    advance(run, BLANK_RECRUIT_T[0] + 1, dt, { x: 0, y: 0 })
    const recruitProbe = run.enemies.find((e) => !e._wave && e.rosterId === 'probe' && e.id !== run.script.bossId)
    assert(recruitProbe, 'expected a P1 recruit probe within the drip window')
    assert(Math.abs(waveProbe.xp - recruitProbe.xp * BLANK_WAVE_XP_MUL) < 1e-9,
      `expected wave xp = recruit xp × ${BLANK_WAVE_XP_MUL.toFixed(3)}, got wave ${waveProbe.xp} vs recruit ${recruitProbe.xp}`)
    console.log(`PASS run LL.i (wave xp cut): wave probe worth ${waveProbe.xp.toFixed(2)}, recruit probe worth ${recruitProbe.xp}`)
  }

  console.log('PASS run LL (blank difficulty pass): P1 borrowed shot, P2 borrowed read + node cleanup, P3 star/fan/echo, mature read depth, speed/HP pins + catch-up cap, fight-wide desperation, residue widening, horde waves at a third xp + blank cap')
}

// ---- Run MM: v6.3.4 anti-turtle pass (enemy dmg scales with time+difficulty, armor/regen
// capped to fixed per-rarity values normal/rare/legendary only, single-hit cap) ------------------
// "Full armor + waiting it out" cheesed every timer chapter: flat armor floored hits to 1, the
// global invuln window capped intake at ~1.33 hits/s, regen outhealed that, and enemy damage
// never scaled with time (only HP did). Fixed by (A) enemy contact damage scaling with
// dmgScale(run.time) and the difficulty ladder (difficultyDmgMul), and (B) armor/regen rolling
// only normal/rare/legendary at fixed flat amounts (never epic/mythic) — plus a HURT_CAP_FRAC
// guard so no single non-dot hit can one-shot regardless of how the multipliers compose.
function testAntiTurtle() {
  const dt = 1 / 60

  // (a) dmg carries dmgScale(run.time) at spawn (checked against a non-elite d1 spawn, so
  // ELITE.dmgMul/enemyDmgMul stay at their neutral values and isolate the time curve), and the
  // difficulty ladder folds difficultyDmgMul into mods.enemyDmgMul exactly, once, at createRun.
  // v6.4.5: pinned to garden — body/pond now carry a chapter-wide balance.enemyDmgMul, so the
  // default chapter no longer has the neutral mods this scenario's whole point is to isolate.
  {
    const run = createRun(makeMeta(), { chapter: 'garden', difficulty: 1 })
    run.weapons = [] // isolate: no kills/xp/levelup, just the spawn-time dmg property
    run.player.hp = run.player.maxHP = 1e9
    run.player.x = 0; run.player.y = 0

    let e0 = null
    for (let i = 0; i < Math.round(10 / dt) && !e0; i++) {
      stepSim(run, { x: 0, y: 0 }, dt)
      e0 = run.enemies.find((e) => !e.elite)
    }
    assert(e0, 'expected a natural spawn near t≈0')
    const ratio0 = e0.dmg / ENEMIES[e0.type].dmg
    assert(Math.abs(ratio0 - 1) < 0.02, `expected dmg/ENEMIES[type].dmg ≈1 near t≈0 (dmgScale(0)=1), got ${ratio0.toFixed(3)} at t=${run.time.toFixed(2)}`)

    // Jump run.time forward (to 299, not 300: stepSim flips phase to 'victory' and stops
    // spawning the instant run.time >= RUN_DURATION, so 300 exactly is a dead end) and reset the
    // elite-cadence pointer along with it: a stale _nextEliteAt=40 left behind by the jump would
    // read run.time(299) >= _nextEliteAt(40) as true for every spawn until the pointer's own
    // +eliteEveryAt steps walk it back past 299 — an avalanche that's an artifact of jumping
    // run.time in a test, not anything a real (continuously-advancing) run would ever hit.
    run.time = 299
    run._nextEliteAt = run.time + eliteEveryAt(run.time)
    const before = run.enemies.length
    let e1 = null
    for (let i = 0; i < Math.round(0.5 / dt) && !e1 && run.phase === 'playing'; i++) {
      stepSim(run, { x: 0, y: 0 }, dt)
      e1 = run.enemies.slice(before).find((e) => !e.elite)
    }
    assert(e1, `expected a natural spawn after jumping run.time to 299 (phase=${run.phase})`)
    const ratio1 = e1.dmg / ENEMIES[e1.type].dmg
    assert(Math.abs(ratio1 - 2) < 0.02, `expected dmg/ENEMIES[type].dmg ≈2 at t≈300 (dmgScale(300)=2), got ${ratio1.toFixed(3)} at t=${run.time.toFixed(2)}`)
    console.log(`PASS run MM.a.1 (time scaling): ratio@t≈0=${ratio0.toFixed(3)} ratio@t≈300=${ratio1.toFixed(3)}`)
  }
  {
    // v6.4.5: garden here too — same neutral-mods isolation as (a) above.
    const run = createRun(makeMeta(), { chapter: 'garden', difficulty: 5 })
    assert.strictEqual(run.mods.enemyDmgMul, difficultyDmgMul(5), `expected mods.enemyDmgMul === difficultyDmgMul(5), got ${run.mods.enemyDmgMul}`)
    assert.strictEqual(run.mods.enemyDmgMul, 1.6, `expected difficultyDmgMul(5) === 1.6 (1 + ${DIFFICULTY_DMG_PER_LEVEL}*4), got ${run.mods.enemyDmgMul}`)
    console.log(`PASS run MM.a.2 (difficulty scaling): d5 mods.enemyDmgMul=${run.mods.enemyDmgMul}`)
  }

  // (b) defensive rarity property: sample ~200 level-up pools (run E's style — fresh run each
  // time so pools aren't depleted) and check every armor/regen card seen never exceeds legendary
  // and matches its values table exactly (no base*mult math for these two ids anymore).
  {
    const seen = []
    for (let i = 0; i < 200; i++) {
      const run = createRun(makeMeta())
      for (const c of buildLevelUpChoices(run)) {
        if (c.kind === 'passive' && (c.id === 'armor' || c.id === 'regen')) seen.push(c)
      }
    }
    assert(seen.length > 0, 'expected at least one armor/regen card across 200 level-up pools')
    for (const c of seen) {
      assert(['normal', 'rare', 'legendary'].includes(c.rarity), `[${c.id}] expected rarity in {normal,rare,legendary}, got ${c.rarity}`)
      assert.strictEqual(c.bonus, PASSIVES[c.id].values[c.rarity], `[${c.id}] bonus ${c.bonus} != values[${c.rarity}] ${PASSIVES[c.id].values[c.rarity]}`)
    }
    console.log(`PASS run MM.b (defensive rarity capped): ${seen.length} armor/regen cards seen across 200 pools, all normal/rare/legendary and exact`)
  }

  // (c) the turtle dies: a heavily-armored/regenerating stationary build that would have been a
  // near-stalemate under the old flat formula (armor floors most hits to 1, regen ~keeps pace)
  // measurably loses ground once dmgScale ramps contact damage up late-run. run.time is jumped
  // instead of simulated from 0 (300s of real-time stepping per sub-test would make the suite
  // slow), so — same as (a) — the elite-cadence pointer is reset with it.
  // v6.4.5: pinned to garden. The owner-directed body/pond balance.enemyDmgMul (0.75) re-admits
  // the stationary turtle on those two chapters (accepted trade-off, flagged at ship time — the
  // 999 coin cap bounds what afk-farming there can extract); this scenario now pins the
  // anti-turtle machinery on a balance-neutral chapter, where the invariant still holds.
  {
    const run = createRun(makeMeta(), { chapter: 'garden', difficulty: 1 })
    run.weapons = []
    run.passives.armor = 7
    run.passives.regen = 3.2
    run.player.maxHP = run.player.hp = 400
    run.player.x = 0; run.player.y = 0
    run.time = 250
    run._nextEliteAt = run.time + eliteEveryAt(run.time)

    const samples = []
    const steps = Math.round(40 / dt)
    for (let i = 0; i < steps; i++) {
      if (run.phase === 'levelup') { applyChoice(run, pickNonElementIndex(run)); run.phase = 'playing'; continue }
      if (run.phase !== 'playing') break
      stepSim(run, { x: 0, y: 0 }, dt)
      if (i % Math.round(3 / dt) === 0) samples.push({ t: run.time, hp: run.player.hp })
    }
    const died = run.phase === 'dead'
    assert(samples.length >= 3, `expected the turtle build to survive long enough to sample a trend, got ${samples.length} samples (died=${died} at t=${run.time.toFixed(1)})`)
    const first = samples[0], last = samples[samples.length - 1]
    assert(died || last.hp < first.hp,
      `expected net HP to be falling late-run (turtle dies): hp@t=${first.t.toFixed(1)} was ${first.hp.toFixed(1)}, hp@t=${last.t.toFixed(1)} is ${last.hp.toFixed(1)} (died=${died})`)
    console.log(`PASS run MM.c (the turtle dies): hp@t=${first.t.toFixed(1)}=${first.hp.toFixed(1)} -> hp@t=${last.t.toFixed(1)}=${last.hp.toFixed(1)}${died ? ' (died)' : ''} — regen no longer outheals contact`)
  }

  // (d) blank re-pin: spawnBlankEnemy's scripted-fight bodies skip dmgScale (and the difficulty
  // tax stays applied via enemyDmgMul) exactly like they already skip hpScale/speedCreep — a
  // wave body's dmg must equal its archetype's flat ENEMIES[].dmg at d1 (mods.enemyDmgMul=1),
  // with no time-curve inflation no matter how long the fight runs past 300s.
  {
    const run = createRun(makeMeta(), { chapter: 'blank', difficulty: 1 })
    run.player.hp = run.player.maxHP = 1e6
    run.weapons = []
    run.time = 200
    Object.assign(run.script, { stage: 0, waveIdx: 0, waveT: 0, spawned: false, bossId: null })
    stepSim(run, { x: 0, y: 0 }, dt) // spawns wave 1 (all probes)
    const wave = run.enemies.find((e) => e._wave)
    assert(wave, 'expected a wave enemy to spawn')
    const roster = CHAPTERS.blank.roster.find((r) => r.id === wave.rosterId)
    const archBase = ENEMIES[ARCHETYPE_TYPE[roster.archetype]]
    assert.strictEqual(wave.dmg, archBase.dmg, `expected blank wave dmg to skip dmgScale exactly (d1, mods.enemyDmgMul=1), got ${wave.dmg} vs archetype base ${archBase.dmg}`)
    console.log(`PASS run MM.d (blank re-pin: dmg): wave dmg=${wave.dmg} === archetype base=${archBase.dmg} at run.time=${run.time}`)
  }

  // (e) hit cap: a hand-placed enemy touching the player with an absurd dmg (10000) still costs
  // at most HURT_CAP_FRAC of maxHP — the guard that keeps glass/difficulty/late-run/enrage
  // multipliers from composing into a one-shot.
  {
    const run = createRun(makeMeta())
    run.weapons = []
    run.player.x = 0; run.player.y = 0
    run.player.hp = run.player.maxHP = 100
    const e = makeStatusEnemy(run, { x: 0, y: 0, hp: 1e6, speed: 0 })
    e.dmg = 10000
    run.enemies.push(e)
    stepSim(run, { x: 0, y: 0 }, dt)
    const lost = 100 - run.player.hp
    const cap = 100 * HURT_CAP_FRAC
    assert(lost <= cap + 0.5, `expected a single hit to cost at most HURT_CAP_FRAC*maxHP (${cap}), lost ${lost.toFixed(2)}`)
    console.log(`PASS run MM.e (hit cap): 10000 raw dmg -> lost ${lost.toFixed(2)} hp (cap ${cap})`)
  }

  console.log('PASS run MM (anti-turtle pass): time+difficulty dmg scaling, armor/regen rarity-capped at fixed values, the turtle dies, blank re-pin skips the time curve, single-hit cap')
}

// ---- Run NN: v6.4 "Pond identity" — eddies, tardigrade phase, bloom slow, mine stun, tideCarried
// -------------------------------------------------------------------------------------------
function testPondIdentity() {
  const dt = 1 / 60

  // (a) eddy streaming determinism: same seed -> identical run.eddies; zero Math.random() consumed
  // by a streaming step; minDist (spawn-ring clearance) and drop radius both honored. Same idiom
  // as run V.g's obstacle streaming test.
  {
    Math.random = mulberry32(20260714)
    const runA = createRun(makeMeta(), { chapter: 'pond' })
    stepSim(runA, { x: 0, y: 0 }, dt)

    Math.random = mulberry32(20260714)
    const runB = createRun(makeMeta(), { chapter: 'pond' })
    stepSim(runB, { x: 0, y: 0 }, dt)

    assert(runA.eddies.length > 0, 'expected at least one eddy to stream in near the spawn')
    const key = (ed) => `${ed.x.toFixed(3)},${ed.y.toFixed(3)},${ed.r},${ed.dir},${ed._cell}`
    assert.strictEqual(runB.eddies.map(key).sort().join('|'), runA.eddies.map(key).sort().join('|'),
      'expected two identically-seeded pond runs to stream identical eddies')

    const minDist = CHAPTERS.pond.signature.eddies.minDist
    for (const ed of runA.eddies) {
      assert(Math.hypot(ed.x, ed.y) >= minDist - 1e-6,
        `expected every eddy outside the ${minDist}px spawn-ring clearance, got one at ${Math.hypot(ed.x, ed.y).toFixed(0)}px`)
    }

    // Zero Math.random() consumed: a fully quiet pond run (no weapons/spawns/enemies — nothing
    // else in stepSim has anything left to roll) crossing a fresh eddy/obstacle cell boundary.
    Math.random = mulberry32(20260714)
    const quiet = createRun(makeMeta(), { chapter: 'pond' })
    quiet.weapons = []; quiet.enemies = []; quiet.mods.spawnMul = 0
    quiet.player.hp = quiet.player.maxHP = 1e9
    stepSim(quiet, { x: 0, y: 0 }, dt) // prime the first scan
    quiet.player.x += 2000; quiet.player.y += 2000 // cross both the eddy (1000px) and obstacle (420px) grids
    const real = Math.random
    let calls = 0
    Math.random = (...a) => { calls++; return real(...a) }
    stepSim(quiet, { x: 0, y: 0 }, dt)
    Math.random = real
    assert.strictEqual(calls, 0, `expected a streaming step in a fully quiet pond run to consume zero Math.random() draws, got ${calls}`)

    // Drop radius: eddies near the old spot are gone once the player walks far away.
    const farKey = (ed) => `${ed.x.toFixed(2)},${ed.y.toFixed(2)}`
    const nearOld = new Set(runA.eddies.filter((ed) => Math.hypot(ed.x, ed.y) <= OBSTACLE_STREAM_RADIUS).map(farKey))
    runA.player.x = 30000; runA.player.y = 30000
    stepSim(runA, { x: 0, y: 0 }, dt)
    assert(!runA.eddies.some((ed) => nearOld.has(farKey(ed))), 'expected the old spawn-area eddies to be dropped after walking far away')
    assert(runA.eddies.every((ed) => Math.hypot(ed.x - 30000, ed.y - 30000) <= OBSTACLE_DROP_RADIUS + 1e-6),
      'expected every remaining eddy within OBSTACLE_DROP_RADIUS of the player')

    console.log(`PASS run NN.a (eddy streaming): ${runA.eddies.length} near spawn, deterministic, zero-RNG, minDist + drop radius honored`)
  }

  // (b) force contract: a hand-placed eddy's inward pull and tangential swirl match the formula at
  // d=r/2, isolated from the ambient drift by subtracting a same-position sample with eddies
  // emptied; pull is unaffected by currentForceMul, swirl doubles with it (the escape invariant).
  {
    const run = createRun(makeMeta(), { chapter: 'pond' })
    run.player.x = 50000; run.player.y = 50000 // far away — its own position doesn't matter here
    const ed = { x: 500, y: 0, r: 170, dir: 1, _cell: 'nn-b' }
    run.eddies = [ed]
    const sx = ed.x - ed.r / 2, sy = 0 // d = r/2 = 85

    function residual() {
      const withEddy = currentForce(run, sx, sy)
      const saved = run.eddies
      run.eddies = []
      const ambient = currentForce(run, sx, sy)
      run.eddies = saved
      return { x: withEddy.fx - ambient.fx, y: withEddy.fy - ambient.fy }
    }

    const r1 = residual()
    const pull = CHAPTERS.pond.signature.eddies.pull * 0.5           // 1 - d/r = 0.5 at d=r/2
    const swirl = CHAPTERS.pond.signature.eddies.swirl * Math.sin(Math.PI * 0.5) // sin(pi/2) = 1
    assert(Math.abs(r1.x - pull) < 0.01, `expected inward residual ${pull}, got ${r1.x}`)
    assert(Math.abs(r1.y - swirl) < 0.01, `expected tangential residual ${swirl} (dir=1), got ${r1.y}`)

    run.mods.currentForceMul = 2
    const r2 = residual()
    assert(Math.abs(r2.x - pull) < 0.01, `expected pull unchanged under currentForceMul=2 (the escape invariant), got ${r2.x}`)
    assert(Math.abs(r2.y - swirl * 2) < 0.01, `expected swirl doubled under currentForceMul=2, got ${r2.y}`)

    console.log(`PASS run NN.b (force contract): pull=${r1.x.toFixed(2)} swirl=${r1.y.toFixed(2)}, mul=2 -> pull=${r2.x.toFixed(2)} swirl=${r2.y.toFixed(2)}`)
  }

  // (c) escape invariant + sticky exclusion: config-level assertions, no run needed.
  {
    const eddies = CHAPTERS.pond.signature.eddies
    const margin = eddies.pull + 2 * Math.sqrt(2) * (CHAPTERS.pond.signature.strength * 0.5 * 2)
    assert(margin < PLAYER.baseSpeed, `expected the escape invariant to hold under Riptide: pull+2√2·(strength·0.5·2)=${margin.toFixed(1)} < PLAYER.baseSpeed=${PLAYER.baseSpeed}`)
    assert(MUTATORS.sticky.exclude.includes('pond'), 'expected MUTATORS.sticky.exclude to include pond (v6.4)')
    console.log(`PASS run NN.c (invariants): escape margin ${margin.toFixed(1)} < ${PLAYER.baseSpeed}, sticky excludes pond`)
  }

  // (d) phase contract: the tardigrade's cryptobiosis flicker, exercised in the pond. Every
  // sub-scenario neutralizes the pond's own ambient drift (mods.currentForceMul = 0, no obstacle
  // seed) so it isolates the phase mechanic rather than fighting the currents.
  {
    // (d1) natural ghosting: a freshly-flagged enemy starts solid with a randomised _phaseT and
    // must flip to ghosted within PHASE_SOLID_T (bounded loop, generous margin).
    const timing = createRun(makeMeta(), { chapter: 'pond' })
    timing.weapons = []; timing.obstacles = []; timing._obstacleSeed = null; timing.mods.spawnMul = 0
    timing.mods.currentForceMul = 0
    timing.player.x = 0; timing.player.y = 0; timing.player.hp = timing.player.maxHP = 1e9
    const te = makeStatusEnemy(timing, { x: 100, y: 0, hp: 1e6, speed: 0 })
    te.flags = ['phase']
    timing.enemies.push(te)
    let ghostedAt = -1
    for (let i = 0; i < Math.round(3 / dt) && ghostedAt < 0; i++) {
      stepSim(timing, { x: 0, y: 0 }, dt)
      if (te._phaseSolid === false) ghostedAt = timing.time
    }
    assert(ghostedAt >= 0 && ghostedAt <= PHASE_SOLID_T + 0.1,
      `expected a fresh phase flicker to ghost within PHASE_SOLID_T=${PHASE_SOLID_T}s, got ${ghostedAt}`)

    // (d2) damage-immune while ghosted, hittable once solid again — same idiom as run Y.i.
    const dmgRun = createRun(makeMeta(), { chapter: 'pond' })
    dmgRun.weapons = [{ id: 'star', level: MAX_WEAPON_LEVEL }]
    dmgRun.obstacles = []; dmgRun._obstacleSeed = null; dmgRun.mods.spawnMul = 0; dmgRun.mods.currentForceMul = 0
    dmgRun.player.x = 0; dmgRun.player.y = 0; dmgRun.player.hp = dmgRun.player.maxHP = 1e9
    const de = makeStatusEnemy(dmgRun, { x: 120, y: 0, hp: 1e6, speed: 0 })
    de.flags = ['phase']
    dmgRun.enemies.push(de)
    de._phaseSolid = false; de._phaseT = 999 // pinned ghosted, well past this window's length
    const ghostHp0 = de.hp
    for (let i = 0; i < Math.round(0.8 / dt); i++) {
      if (dmgRun.phase === 'levelup') { declineLevelUp(dmgRun); continue }
      stepSim(dmgRun, { x: 0, y: 0 }, dt)
    }
    assert.strictEqual(de.hp, ghostHp0, `expected a ghosted flicker to take no damage from a live weapon, hp ${ghostHp0} -> ${de.hp}`)

    de._phaseSolid = true; de._phaseT = 999
    for (let i = 0; i < Math.round(0.8 / dt); i++) {
      if (dmgRun.phase === 'levelup') { declineLevelUp(dmgRun); continue }
      stepSim(dmgRun, { x: 0, y: 0 }, dt)
    }
    assert(de.hp < ghostHp0, `expected damage to land once solid again, hp=${de.hp}`)

    // (d3) contact-harmless while ghosted: parked directly on the player.
    const contact = createRun(makeMeta(), { chapter: 'pond' })
    contact.weapons = []; contact.obstacles = []; contact._obstacleSeed = null; contact.mods.spawnMul = 0
    contact.mods.currentForceMul = 0
    contact.player.x = 0; contact.player.y = 0; contact.player.hp = contact.player.maxHP = 1e9
    const ce = makeStatusEnemy(contact, { x: 0, y: 0, hp: 1e6, speed: 0 })
    ce.flags = ['phase']
    contact.enemies.push(ce)
    ce._phaseSolid = false; ce._phaseT = 999
    contact.player.invuln = 0
    const pHp0 = contact.player.hp
    for (let i = 0; i < Math.round(0.5 / dt); i++) stepSim(contact, { x: 0, y: 0 }, dt)
    assert.strictEqual(contact.player.hp, pHp0, 'expected a ghosted flicker parked on the player to deal no contact damage')

    // (d4) obstacle pass-through while ghosted: dead-center overlap never gets pushed out.
    const obs = createRun(makeMeta(), { chapter: 'pond' })
    obs.weapons = []; obs.mods.spawnMul = 0; obs.mods.currentForceMul = 0
    obs.player.x = 5000; obs.player.y = 0; obs.player.hp = obs.player.maxHP = 1e9
    const wall = { x: 0, y: 0, r: 50, _cell: 'nn-d-wall' }
    obs.obstacles = [wall]; obs._obstacleSeed = null
    const oe = makeStatusEnemy(obs, { x: 0, y: 0, hp: 1e6, speed: 0 })
    oe.flags = ['phase']
    obs.enemies.push(oe)
    oe._phaseSolid = false; oe._phaseT = 999
    for (let i = 0; i < Math.round(0.3 / dt); i++) stepSim(obs, { x: 0, y: 0 }, dt)
    const obsDist = Math.hypot(oe.x - wall.x, oe.y - wall.y)
    assert(obsDist < wall.r, `expected a ghosted flicker to keep overlapping the obstacle instead of being pushed out (dist=${obsDist.toFixed(1)}, r=${wall.r})`)

    // (d5) soapTrail + ghost: an elite carrying both flags drops zero pool nodes while ghosted,
    // then resumes at SOAP_INTERVAL cadence once solid again.
    const soap = createRun(makeMeta(), { chapter: 'pond' })
    soap.weapons = []; soap.obstacles = []; soap._obstacleSeed = null; soap.mods.spawnMul = 0
    soap.mods.currentForceMul = 0
    soap.player.x = 5000; soap.player.y = 0; soap.player.hp = soap.player.maxHP = 1e9
    const se = makeStatusEnemy(soap, { x: 0, y: 0, hp: 1e6, speed: 0, elite: true })
    se.flags = ['phase', 'soapTrail']
    soap.enemies.push(se)
    se._phaseSolid = false; se._phaseT = 999
    for (let i = 0; i < Math.round((SOAP_INTERVAL * 3) / dt); i++) stepSim(soap, { x: 0, y: 0 }, dt)
    assert.strictEqual(soap.pools.length, 0, `expected a ghosted phase+soapTrail elite to drop zero pool nodes, got ${soap.pools.length}`)

    se._phaseSolid = true; se._phaseT = 999
    for (let i = 0; i < Math.round((SOAP_INTERVAL + 0.1) / dt); i++) stepSim(soap, { x: 0, y: 0 }, dt)
    assert(soap.pools.length >= 1, `expected a solid phase+soapTrail elite to drop >= 1 pool node, got ${soap.pools.length}`)

    console.log(`PASS run NN.d (phase contract): ghosted naturally at t=${ghostedAt.toFixed(2)}s; damage-immune/hittable, contact-harmless, obstacle pass-through, soapTrail gated by phase`)
  }

  // (e) mine stun: a detonation stuns every solid enemy in radius (MINE_STUN) and skips a
  // ghosted phase enemy entirely (no stun, no damage) — same damageImmune guard as everywhere else.
  {
    const run = createRun(makeMeta(), { chapter: 'pond' })
    run.weapons = []; run.obstacles = []; run._obstacleSeed = null; run.mods.spawnMul = 0
    run.mods.currentForceMul = 0
    run.player.x = 5000; run.player.y = 0; run.player.hp = run.player.maxHP = 1e9

    const solid = makeStatusEnemy(run, { x: 0, y: 0, hp: 1e6, speed: 0 })
    const ghost = makeStatusEnemy(run, { x: 10, y: 0, hp: 1e6, speed: 0 })
    ghost.flags = ['phase']
    ghost._phaseSolid = false; ghost._phaseT = 999
    run.enemies.push(solid, ghost)
    run.mines.push({ x: 0, y: 0, arm: 0, dmg: 40, radius: 100 })

    const solidHp0 = solid.hp, ghostHp0 = ghost.hp
    stepSim(run, { x: 0, y: 0 }, dt)

    assert.strictEqual(solid.stunT, MINE_STUN, `expected the solid enemy stunned for MINE_STUN=${MINE_STUN}, got ${solid.stunT}`)
    assert(solid.hp < solidHp0, `expected the solid enemy to take mine damage, hp ${solidHp0} -> ${solid.hp}`)
    assert.strictEqual(ghost.stunT || 0, 0, `expected the ghosted enemy to take no stun, got ${ghost.stunT}`)
    assert.strictEqual(ghost.hp, ghostHp0, `expected the ghosted enemy to take no mine damage, hp ${ghostHp0} -> ${ghost.hp}`)
    console.log(`PASS run NN.e (mine stun): solid stunT=${solid.stunT} took ${solidHp0 - solid.hp}dmg; ghosted stunT=${ghost.stunT || 0} took 0`)
  }

  // (f) bloom slow: two identical seekers at mirrored positions/distances, one starting inside a
  // (damageless) cloud, one outside — over 1s the inside one covers roughly (1-BLOOM_SLOW) the
  // ground. currentForceMul=0 removes the pond's own ambient drift so it isolates the bloom slow.
  {
    const run = createRun(makeMeta(), { chapter: 'pond' })
    run.weapons = []; run.obstacles = []; run._obstacleSeed = null; run.mods.spawnMul = 0
    run.mods.currentForceMul = 0
    run.player.x = 0; run.player.y = -1000
    run.player.hp = run.player.maxHP = 1e9

    // Cloud centered exactly on the "inside" seeker's start, already past its grow window (t=40
    // of a dur=100 cloud, growT=35 — see BLOOM_GROW_FRAC) so it's sitting at maxR=300 from frame
    // one instead of still expanding from ~0. Over 1s at full speed the seeker can't travel far
    // enough to exit it, so it stays inside for the whole window.
    run.blooms.push({ x: 500, y: 0, r: 300, maxR: 300, t: 40, dur: 100, dmgPerTick: 0 })
    const inside = makeStatusEnemy(run, { x: 500, y: 0, hp: 1e9, speed: 100 })
    const outside = makeStatusEnemy(run, { x: -500, y: 0, hp: 1e9, speed: 100 }) // mirrored, same distance to target
    run.enemies.push(inside, outside)
    const i0 = { x: inside.x, y: inside.y }, o0 = { x: outside.x, y: outside.y }

    for (let i = 0; i < Math.round(1 / dt); i++) stepSim(run, { x: 0, y: 0 }, dt)

    const insideDist = Math.hypot(inside.x - i0.x, inside.y - i0.y)
    const outsideDist = Math.hypot(outside.x - o0.x, outside.y - o0.y)
    const ratio = insideDist / outsideDist
    const expected = 1 - BLOOM_SLOW
    assert(Math.abs(ratio - expected) < 0.15,
      `expected the inside seeker to cover ~${expected.toFixed(2)}x the ground, got ratio=${ratio.toFixed(3)} (inside=${insideDist.toFixed(1)}px outside=${outsideDist.toFixed(1)}px)`)
    assert(inside.bloomSlowT > 0, 'expected the inside seeker to carry a live bloomSlowT')
    assert.strictEqual(outside.bloomSlowT || 0, 0, 'expected the outside seeker to carry no bloomSlowT')
    console.log(`PASS run NN.f (bloom slow): inside=${insideDist.toFixed(1)}px outside=${outsideDist.toFixed(1)}px ratio=${ratio.toFixed(3)} (expected ~${expected.toFixed(2)})`)
  }

  // (g) tideCarried: with picks held, a cloud drifts along currentForce and ticks harder; without
  // the mod it stays put. Reseeded per run (two-run comparisons must reseed — file rule).
  {
    Math.random = mulberry32(20260714)
    const tideRun = createRun(makeMeta(), { chapter: 'pond' })
    tideRun.weapons = []; tideRun.obstacles = []; tideRun._obstacleSeed = null; tideRun.mods.spawnMul = 0
    tideRun.player.x = 5000; tideRun.player.y = 0; tideRun.player.hp = tideRun.player.maxHP = 1e9
    // 5 stacked picks (a legitimate value — tideCarried is a flat, unbounded-picks mod): the
    // ambient field's magnitude at any one point/time varies with the sine sum's phase (it can be
    // near-zero there without being zero everywhere — run V.f2 already established the field is
    // nonzero SOMEWHERE, not everywhere), so a single pick's drift isn't a robust >10px bet at an
    // arbitrary sample point/time. 5 picks make the check robust without touching the mechanism.
    tideRun.weaponMods.bloom.tideCarried = 5
    tideRun.blooms.push({ x: 0, y: 0, r: 90, maxR: 90, t: 40, dur: 100, dmgPerTick: 6 })
    const f0 = currentForce(tideRun, 0, 0)
    for (let i = 0; i < Math.round(1 / dt); i++) stepSim(tideRun, { x: 0, y: 0 }, dt)
    const bl = tideRun.blooms[0]
    const moved = Math.hypot(bl.x, bl.y)
    assert(moved > 10, `expected a tide-carried cloud to drift more than 10px over 1s, moved ${moved.toFixed(1)}px`)
    // Rough direction check: over a step this small the field barely changes (run V.f2 already
    // established currentForce's continuity), so the net drift should point roughly along the
    // field sampled at the start.
    const dot = bl.x * f0.fx + bl.y * f0.fy
    assert(dot > 0, `expected the cloud's drift to point roughly along currentForce's direction at its start, dot=${dot.toFixed(1)}`)

    Math.random = mulberry32(20260714)
    const plainRun = createRun(makeMeta(), { chapter: 'pond' })
    plainRun.weapons = []; plainRun.obstacles = []; plainRun._obstacleSeed = null; plainRun.mods.spawnMul = 0
    plainRun.player.x = 5000; plainRun.player.y = 0; plainRun.player.hp = plainRun.player.maxHP = 1e9
    plainRun.blooms.push({ x: 0, y: 0, r: 90, maxR: 90, t: 40, dur: 100, dmgPerTick: 6 })
    for (let i = 0; i < Math.round(1 / dt); i++) stepSim(plainRun, { x: 0, y: 0 }, dt)
    assert.strictEqual(plainRun.blooms[0].x, 0, 'expected an unmodded cloud to stay put (x)')
    assert.strictEqual(plainRun.blooms[0].y, 0, 'expected an unmodded cloud to stay put (y)')

    // Tick damage bonus: pin currentForceMul=0 here so the cloud (and comparison) is about
    // damage, not motion — an enemy parked in it takes ~(1+TIDE_DMG_BONUS)x the plain tick damage.
    function tickedDamage(tide) {
      Math.random = mulberry32(20260714)
      const run = createRun(makeMeta(), { chapter: 'pond' })
      run.weapons = []; run.obstacles = []; run._obstacleSeed = null; run.mods.spawnMul = 0
      run.mods.currentForceMul = 0
      run.player.x = 5000; run.player.y = 0; run.player.hp = run.player.maxHP = 1e9
      if (tide > 0) run.weaponMods.bloom.tideCarried = tide
      const e = makeStatusEnemy(run, { x: 0, y: 0, hp: 1e9, speed: 0 })
      run.enemies.push(e)
      run.blooms.push({ x: 0, y: 0, r: 90, maxR: 90, t: 40, dur: 100, dmgPerTick: 6 })
      for (let i = 0; i < Math.round(2 / dt); i++) stepSim(run, { x: 0, y: 0 }, dt) // several BLOOM_TICKs
      return e.maxHP - e.hp
    }
    const plainDmg = tickedDamage(0)
    const tideDmg = tickedDamage(1)
    const expectedMul = 1 + TIDE_DMG_BONUS
    assert(plainDmg > 0, 'expected the unmodded cloud to have dealt some damage')
    assert(Math.abs(tideDmg / plainDmg - expectedMul) < 0.05,
      `expected tide-carried tick damage ~${expectedMul}x the unmodded amount, got ${(tideDmg / plainDmg).toFixed(3)}x (plain=${plainDmg} tide=${tideDmg})`)

    console.log(`PASS run NN.g (tideCarried): drift=${moved.toFixed(1)}px (dot=${dot.toFixed(1)}), tick dmg ratio=${(tideDmg / plainDmg).toFixed(3)} (expected ${expectedMul})`)
  }

  console.log('PASS run NN (v6.4 Pond identity): eddy streaming + force contract + escape invariant, tardigrade phase contract, mine stun, bloom slow, tideCarried')
}

// v6.4.1/v6.4.3 (owner directives, Run OO): explicit difficulty-1 runs of the three onboarding
// chapters (EARLY_CALM: body/pond/garden) spawn fewer enemies and pay proportionally more xp
// per kill, per chapter (body is the gentlest) — gated on opts.difficulty === 1 EXPLICITLY, not
// the defaulted local, since (almost) every test calls createRun without a
// difficulty and must keep baseline density. v6.4.5: body/pond additionally carry a
// CHAPTERS[id].balance block (Run RR) that eases spawn/dmg AND fattens xp (compensating the
// thinner swarm) at EVERY difficulty with no gate at all — every spawnMul/xpMul expectation below
// composes EARLY_CALM[chapter] (may be absent) with CHAPTERS[chapter].balance (may be absent)
// since both can be live at once.
function testEarlyCalm() {
  const EPS = 1e-9
  const EARLY_CALM_CHAPTERS = Object.keys(EARLY_CALM)
  const balSpawnMul = (chapter) => CHAPTERS[chapter].balance?.spawnMul ?? 1
  const balXpMul = (chapter) => CHAPTERS[chapter].balance?.xpMul ?? 1

  // (a) explicit difficulty 1 on each onboarding chapter: spawnMul and xpMul both hit calm ×
  // balance (both may apply at once — body/pond carry both, garden only carries calm).
  {
    Math.random = mulberry32(20260714)
    for (const chapter of EARLY_CALM_CHAPTERS) {
      const run = createRun(makeMeta(), { chapter, difficulty: 1 })
      const expectedSpawn = EARLY_CALM[chapter].spawnMul * balSpawnMul(chapter)
      const expectedXp = EARLY_CALM[chapter].xpMul * balXpMul(chapter)
      assert(Math.abs(run.mods.spawnMul - expectedSpawn) < EPS,
        `expected ${chapter} d1 mods.spawnMul ≈ ${expectedSpawn}, got ${run.mods.spawnMul}`)
      assert(Math.abs(run.mods.xpMul - expectedXp) < EPS,
        `expected ${chapter} d1 mods.xpMul ≈ ${expectedXp}, got ${run.mods.xpMul}`)
    }
    console.log('PASS run OO.a (early-calm composes with chapter balance): body/pond/garden at explicit d1 get spawnMul/xpMul = EARLY_CALM×balance')
  }

  // (b) same chapters at difficulty 2: EARLY_CALM doesn't fire (d1-only gate) and difficulty tax
  // multipliers don't touch spawn/xp either — but CHAPTERS[chapter].balance has no difficulty gate
  // at all, so body/pond's spawnMul/xpMul now equal the balance factors alone (garden has none,
  // stays 1/1).
  {
    Math.random = mulberry32(20260714)
    for (const chapter of EARLY_CALM_CHAPTERS) {
      const run = createRun(makeMeta(), { chapter, difficulty: 2 })
      const expectedSpawn = balSpawnMul(chapter)
      const expectedXp = balXpMul(chapter)
      assert(Math.abs(run.mods.spawnMul - expectedSpawn) < EPS,
        `expected ${chapter} d2 mods.spawnMul ≈ ${expectedSpawn}, got ${run.mods.spawnMul}`)
      assert(Math.abs(run.mods.xpMul - expectedXp) < EPS,
        `expected ${chapter} d2 mods.xpMul ≈ ${expectedXp}, got ${run.mods.xpMul}`)
    }
    console.log('PASS run OO.b (difficulty 2: calm gone, balance stays): body/pond keep balance-only spawnMul/xpMul, garden baseline 1/1')
  }

  // (c) a chapter outside EARLY_CALM (and declaring no spawn/xp balance) at explicit difficulty 1
  // stays baseline — i.e. EARLY_CALM does not leak to chapters it was never listed for.
  // v6.6.28: the subject used to be hard-coded to 'undergrowth', and rotted the moment undergrowth
  // gained a `balance: { spawnMul: 0.8 }` block (owner: "20% less enemies"). The claim under test
  // is about the EARLY_CALM gate, not about any one chapter, so the subject is now DERIVED: the
  // first chapter that is neither in EARLY_CALM nor declares a spawn/xp balance factor.
  {
    Math.random = mulberry32(20260714)
    const subject = CHAPTER_ORDER.find((id) =>
      !EARLY_CALM_CHAPTERS.includes(id) && balSpawnMul(id) === 1 && balXpMul(id) === 1)
    assert.ok(subject, 'no chapter left outside both EARLY_CALM and spawn/xp balance — OO.c has nothing to test')
    const run = createRun(makeMeta(), { chapter: subject, difficulty: 1 })
    assert.strictEqual(run.mods.spawnMul, 1, `expected ${subject} d1 mods.spawnMul === 1, got ${run.mods.spawnMul}`)
    assert.strictEqual(run.mods.xpMul, 1, `expected ${subject} d1 mods.xpMul === 1, got ${run.mods.xpMul}`)
    console.log(`PASS run OO.c (chapter not in EARLY_CALM or spawn/xp balance): ${subject} at d1 keeps baseline spawnMul/xpMul=1`)
  }

  // (d) difficulty omitted entirely (the test shape) — the local `difficulty` defaults to 1
  // internally, but opts.difficulty stays undefined, so the EARLY_CALM gate must NOT fire. The
  // chapter balance block, unlike EARLY_CALM, has no gate — it fires here too, so pond's
  // spawnMul/xpMul are the balance factors alone (0.75/1.25), not baseline 1/1.
  {
    Math.random = mulberry32(20260714)
    const run = createRun(makeMeta(), { chapter: 'pond' })
    const expectedSpawn = balSpawnMul('pond')
    const expectedXp = balXpMul('pond')
    assert(Math.abs(run.mods.spawnMul - expectedSpawn) < EPS,
      `expected pond (no difficulty opt) mods.spawnMul ≈ ${expectedSpawn}, got ${run.mods.spawnMul}`)
    assert(Math.abs(run.mods.xpMul - expectedXp) < EPS,
      `expected pond (no difficulty opt) mods.xpMul ≈ ${expectedXp}, got ${run.mods.xpMul}`)
    console.log(`PASS run OO.d (difficulty omitted): pond with no opts.difficulty keeps EARLY_CALM off but balance on (spawnMul≈${expectedSpawn}, xpMul≈${expectedXp}) — test shape`)
  }

  // (e) mutator stack: overtime (spawnMul:1.4, xpMul:1.3, see MUTATORS in config.js) composes
  // with BOTH the early-calm gate and the chapter balance block rather than being overwritten.
  {
    Math.random = mulberry32(20260714)
    const run = createRun(makeMeta(), { chapter: 'body', difficulty: 1, mutators: ['overtime'] })
    const expectedSpawn = 1.4 * EARLY_CALM.body.spawnMul * balSpawnMul('body')
    const expectedXp = 1.3 * EARLY_CALM.body.xpMul * balXpMul('body')
    assert(Math.abs(run.mods.spawnMul - expectedSpawn) < EPS,
      `expected body d1+overtime mods.spawnMul ≈ ${expectedSpawn}, got ${run.mods.spawnMul}`)
    assert(Math.abs(run.mods.xpMul - expectedXp) < EPS,
      `expected body d1+overtime mods.xpMul ≈ ${expectedXp}, got ${run.mods.xpMul}`)
    console.log(`PASS run OO.e (mutator composition): body d1+overtime spawnMul=${run.mods.spawnMul.toFixed(4)} (expected ${expectedSpawn.toFixed(4)}), xpMul=${run.mods.xpMul.toFixed(4)} (expected ${expectedXp.toFixed(4)})`)
  }

  console.log('PASS run OO (v6.4.1/v6.4.3 early-calm): explicit-d1 onboarding chapters thin spawns and fatten xp per chapter, gated correctly on opts.difficulty and chapter membership, composes with mutators and the v6.4.5 chapter balance block')
}

// v6.4.2 (owner directive): run.coinsEarned never exceeds COIN_CAP_PER_RUN, and re-earning after
// a mid-run spend (reroll) climbs back up to but never past the same cap.
function testCoinCap() {
  Math.random = mulberry32(20260714)
  const dt = 1 / 60

  // (a) a pickup that would carry coinsEarned well past the cap clamps to exactly the cap.
  {
    const run = createRun(makeMeta(), { chapter: 'body' })
    run.weapons = []            // nothing to fire, nothing to kill, no extra coin drops
    run.mods.spawnMul = 0       // no organic enemy spawns to interfere
    run.player.x = 0; run.player.y = 0
    run.coinsEarned = 990
    run.coins.push({ x: 0, y: 0, value: 500 }) // far more than the 9 coins of headroom left
    for (let i = 0; i < 5; i++) stepSim(run, { x: 0, y: 0 }, dt)
    assert.strictEqual(run.coinsEarned, COIN_CAP_PER_RUN,
      `expected run.coinsEarned clamped to COIN_CAP_PER_RUN (${COIN_CAP_PER_RUN}), got ${run.coinsEarned}`)
    console.log(`PASS run PP.a (coin cap clamps on pickup): coinsEarned=${run.coinsEarned}`)
  }

  // (b) re-earn after a mid-run spend (reroll shape: main.js's onReroll subtracts the reroll cost
  // directly from run.coinsEarned) climbs back up to, but never past, the same cap.
  {
    const run = createRun(makeMeta(), { chapter: 'body' })
    run.weapons = []
    run.mods.spawnMul = 0
    run.player.x = 0; run.player.y = 0
    run.coinsEarned = COIN_CAP_PER_RUN
    run.coinsEarned -= 50 // simulate a reroll spend, like onReroll in main.js
    run.coins.push({ x: 0, y: 0, value: 500 }) // far more than the 50 coins of headroom left
    for (let i = 0; i < 5; i++) stepSim(run, { x: 0, y: 0 }, dt)
    assert.strictEqual(run.coinsEarned, COIN_CAP_PER_RUN,
      `expected run.coinsEarned to re-earn back up to COIN_CAP_PER_RUN (${COIN_CAP_PER_RUN}) exactly, got ${run.coinsEarned}`)
    console.log(`PASS run PP.b (coin cap re-earn after spend): coinsEarned=${run.coinsEarned}`)
  }

  // (c) the end-of-run bonus is floor(sqrt(kills) + level). The `level` argument DEFAULTS to 1, so
  // a caller that forgets to pass it still returns a plausible number and nothing throws — grep
  // main.js's one call site (run UG.k's trick) rather than trusting the formula alone.
  {
    assert.strictEqual(runBonusCoins(400, 25), 45, 'runBonusCoins(400, 25) should be sqrt(400)+25 = 45')
    assert.strictEqual(runBonusCoins(0, 1), 1, 'a level-1 run with no kills still banks its level')
    assert.ok(runBonusCoins(100, 10) > runBonusCoins(100, 5), 'the level term must move the bonus')
    const src = readFileSync(new URL('../src/main.js', import.meta.url), 'utf8')
    assert.ok(/runBonusCoins\(run\.kills,\s*run\.player\.level\)/.test(src),
      'endRun (main.js) must pass run.player.level to runBonusCoins — the default of 1 hides the omission')
    console.log('PASS run PP.c (end-of-run bonus): floor(sqrt(kills) + level), and main.js forwards the level')
  }

  console.log('PASS run PP (v6.4.2 coin cap): run.coinsEarned clamps to COIN_CAP_PER_RUN on pickup and re-earns back up to it (never past) after a mid-run spend')
}

// v6.4.3 (owner directive, Run QQ): stepSpawning banks SPAWN_OPENING_CREDIT into _spawnAcc once,
// on a run's first ordinary-spawn step, so a run opens with enemies already walking in instead of
// trickling in after ~1.7-4.2s of dead air.
function testOpeningCredit() {
  Math.random = mulberry32(20260714)
  const dt = 1 / 60

  // (a) fresh body run (no difficulty — baseline mods): one stepSim frame banks exactly
  // SPAWN_OPENING_CREDIT enemies (spawnRate(0)*dt is far below 1, so it doesn't add a 4th within
  // the same frame), and the one-time flag is now set.
  {
    const run = createRun(makeMeta(), { chapter: 'body' })
    stepSim(run, { x: 0, y: 0 }, dt)
    assert.strictEqual(run.enemies.length, SPAWN_OPENING_CREDIT,
      `expected ${SPAWN_OPENING_CREDIT} enemies after the first frame (opening credit), got ${run.enemies.length}`)
    assert.strictEqual(run._openingSpawned, true, 'expected run._openingSpawned === true after the first ordinary-spawn step')
    console.log(`PASS run QQ.a (opening credit banks enemies): enemies=${run.enemies.length} (expected ${SPAWN_OPENING_CREDIT}), _openingSpawned=${run._openingSpawned}`)
  }

  // (b) a silenced run (mods.spawnMul = 0, the tests/probes shape) stays perfectly quiet — the
  // credit is skipped, not banked-then-ignored.
  {
    const run = createRun(makeMeta(), { chapter: 'body' })
    run.mods.spawnMul = 0
    for (let i = 0; i < 10; i++) stepSim(run, { x: 0, y: 0 }, dt)
    assert.strictEqual(run.enemies.length, 0, `expected 0 enemies with mods.spawnMul=0, got ${run.enemies.length}`)
    console.log('PASS run QQ.b (silenced run stays quiet): mods.spawnMul=0 skips the opening credit, enemies.length=0')
  }

  // (c) a scripted chapter (The Blank) never reaches stepSpawning's credit line — its early return
  // fires first, so _openingSpawned stays falsy even after a step.
  {
    const run = createRun(makeMeta(), { chapter: 'blank', difficulty: 1 })
    stepSim(run, { x: 0, y: 0 }, dt)
    assert(!run._openingSpawned, `expected run._openingSpawned to stay falsy for a scripted chapter, got ${run._openingSpawned}`)
    console.log('PASS run QQ.c (scripted chapter skips the credit): The Blank never sets _openingSpawned')
  }

  console.log('PASS run QQ (v6.4.3 opening credit): the first ordinary-spawn step banks SPAWN_OPENING_CREDIT once, skips it when silenced, and never runs for scripted chapters')
}

// v6.4.5 (owner directive, Run RR): CHAPTERS[id].balance eases body/pond spawn AND enemy contact
// damage, while fattening xp to compensate the thinner swarm, at EVERY difficulty, dailies
// included — unlike EARLY_CALM (Run OO, d1-only, explicit-gate only) this block has no gate at
// all, so it stacks on top of EARLY_CALM, difficulty taxes, and mutators. Other chapters carry no
// balance key (absent = neutral, see config.js).
function testChapterBalance() {
  const EPS = 1e-9

  // (a) body, difficulty omitted entirely (the test shape — EARLY_CALM never fires without
  // an explicit opts.difficulty): balance alone thins spawn, softens contact damage, and fattens xp.
  {
    Math.random = mulberry32(20260714)
    const run = createRun(makeMeta(), { chapter: 'body' })
    assert(Math.abs(run.mods.spawnMul - 0.75) < EPS,
      `expected body (no difficulty opt) mods.spawnMul ≈ 0.75, got ${run.mods.spawnMul}`)
    assert(Math.abs(run.mods.enemyDmgMul - 0.75) < EPS,
      `expected body (no difficulty opt) mods.enemyDmgMul ≈ 0.75, got ${run.mods.enemyDmgMul}`)
    assert(Math.abs(run.mods.xpMul - 1.25) < EPS,
      `expected body (no difficulty opt) mods.xpMul ≈ 1.25, got ${run.mods.xpMul}`)
    // v6.4.9 (owner directive): body enemies also carry 25% less HP — body-only, pond keeps hp 1.
    assert(Math.abs(run.mods.enemyHpMul - 0.75) < EPS,
      `expected body (no difficulty opt) mods.enemyHpMul ≈ 0.75, got ${run.mods.enemyHpMul}`)
    console.log(`PASS run RR.a (body baseline balance, omitted-difficulty shape): spawnMul=${run.mods.spawnMul}, enemyDmgMul=${run.mods.enemyDmgMul}, enemyHpMul=${run.mods.enemyHpMul}, xpMul=${run.mods.xpMul}`)
  }

  // (b) pond, explicit difficulty 3: EARLY_CALM doesn't fire (d1-only), but balance has no gate at
  // all — enemyDmgMul stacks 0.75 (balance) × difficultyDmgMul(3) (the d3 tax), spawnMul is the
  // balance factor alone since nothing else touches spawn at d3.
  {
    Math.random = mulberry32(20260714)
    const run = createRun(makeMeta(), { chapter: 'pond', difficulty: 3 })
    const expectedDmg = 0.75 * difficultyDmgMul(3)
    assert(Math.abs(run.mods.spawnMul - 0.75) < EPS,
      `expected pond d3 mods.spawnMul ≈ 0.75, got ${run.mods.spawnMul}`)
    assert(Math.abs(run.mods.enemyDmgMul - expectedDmg) < EPS,
      `expected pond d3 mods.enemyDmgMul ≈ ${expectedDmg}, got ${run.mods.enemyDmgMul}`)
    // v6.4.10 per-chapter HP ladder: pond 0.85, stacking with the d3 tax.
    assert(Math.abs(run.mods.enemyHpMul - 0.85 * difficultyHpMul(3)) < EPS,
      `expected pond d3 mods.enemyHpMul ≈ 0.85 × difficulty tax ${0.85 * difficultyHpMul(3)}, got ${run.mods.enemyHpMul}`)
    console.log(`PASS run RR.b (pond d3 stacks balance with the difficulty tax): enemyDmgMul=${run.mods.enemyDmgMul.toFixed(4)} (expected ${expectedDmg.toFixed(4)})`)
  }

  // (c) garden's balance block. v6.4.10 made it HP-only (0.95); v6.6.15 (owner: "reduce 20% the
  // number of enemies") added spawnMul 0.8, so it is no longer HP-only; v6.6.23 (owner: "5% less
  // monster hp and 5% less monster quantity in chapter 3") took both down 5% again, to 0.76/0.9 —
  // rewritten in place each time because these are DIRECTED changes, not breaks. Damage and xp still stay baseline 1, and the
  // EARLY_CALM thinning still does NOT apply here, because calm needs difficulty 1 stated
  // EXPLICITLY and this call omits it (the v6.4.1 gate).
  {
    Math.random = mulberry32(20260714)
    const run = createRun(makeMeta(), { chapter: 'garden' })
    assert(Math.abs(run.mods.spawnMul - 0.76) < EPS, `expected garden mods.spawnMul ≈ 0.76, got ${run.mods.spawnMul}`)
    assert.strictEqual(run.mods.enemyDmgMul, 1, `expected garden mods.enemyDmgMul === 1, got ${run.mods.enemyDmgMul}`)
    assert.strictEqual(run.mods.xpMul, 1, `expected garden mods.xpMul === 1, got ${run.mods.xpMul}`)
    assert(Math.abs(run.mods.enemyHpMul - 0.9) < EPS, `expected garden mods.enemyHpMul ≈ 0.9, got ${run.mods.enemyHpMul}`)
    // The spider carries its own roster multiplier UNDER the chapter one, so it is thinned twice.
    const spider = CHAPTERS.garden.roster.find((r) => r.id === 'spider')
    assert(Math.abs(spider.hpMul - 1.2) < EPS, `expected the spider's roster hpMul 1.2, got ${spider.hpMul}`)
    // v6.6.16 (owner): ants and spiders 25% smaller, the wasp 25% bigger. Asserted on the SPAWNED
    // enemy, not just the table — radiusMul has to survive spawnEnemy's archetype/elite maths.
    const sizes = { ant: 0.75, wasp: 1.25, spider: 0.75 }
    for (const [id, mul] of Object.entries(sizes)) {
      const entry = CHAPTERS.garden.roster.find((r) => r.id === id)
      assert(Math.abs(entry.radiusMul - mul) < EPS, `expected ${id} radiusMul ${mul}, got ${entry.radiusMul}`)
      const base = ENEMIES[ARCHETYPE_TYPE[entry.archetype]].radius
      const spawnRun = createRun(makeMeta(), { chapter: 'garden' })
      spawnRun.mods.spawnMul = 0
      spawnRun.enemies.length = 0
      forceSpawn(spawnRun, entry.archetype, id)
      const e = spawnRun.enemies.find((x) => x.rosterId === id)
      if (e) assert(Math.abs(e.radius - base * mul) < 0.001, `${id} spawns at radius ${e.radius}, expected ${base * mul}`)
    }
    console.log(`PASS run RR.c (garden balance): spawnMul 0.76, enemyHpMul 0.9, spider roster hpMul 1.2, dmg/xp baseline`)
  }

  // (c2) v6.4.10 per-chapter enemy HP ladder, the full sweep: body 0.75, pond 0.85, garden 0.9,
  // undergrowth 1 (no block), city 1.05, skies 1.15, beyond 1 (no block).
  {
    const LADDER = { body: 0.75, pond: 0.85, garden: 0.9, undergrowth: 1, city: 1.05, skies: 1.15, beyond: 1 }
    for (const [ch, hp] of Object.entries(LADDER)) {
      Math.random = mulberry32(20260714)
      const run = createRun(makeMeta(), { chapter: ch })
      assert(Math.abs(run.mods.enemyHpMul - hp) < EPS,
        `expected ${ch} mods.enemyHpMul ≈ ${hp}, got ${run.mods.enemyHpMul}`)
    }
    console.log('PASS run RR.c2 (HP ladder sweep): body 0.75 / pond 0.85 / garden 0.9 / undergrowth 1 / city 1.05 / skies 1.15 / beyond 1')
  }

  // (d) blank (the scripted boss chapter) has no balance block either — untouched.
  {
    Math.random = mulberry32(20260714)
    const run = createRun(makeMeta(), { chapter: 'blank' })
    assert.strictEqual(run.mods.enemyDmgMul, 1, `expected blank (no balance block) mods.enemyDmgMul === 1, got ${run.mods.enemyDmgMul}`)
    console.log('PASS run RR.d (blank has no balance block): enemyDmgMul stays baseline 1')
  }

  // (e) the balance block actually reaches spawned enemies, not just run.mods: a fresh body run's
  // opening-credit enemies (spawnEnemy, sim.js ~934) carry dmg = base.dmg * dmgScale(t) *
  // (isElite ? ELITE.dmgMul : 1) * mods.enemyDmgMul. Difficulty omitted (no EARLY_CALM), t is still
  // under the first elite window (_nextEliteAt starts at 40), so every credit enemy is a
  // non-elite drone (WAVE_TABLE[0] = {drone:1}) and dmg reduces to base.dmg * dmgScale(t) * 0.75.
  {
    Math.random = mulberry32(20260714)
    const run = createRun(makeMeta(), { chapter: 'body' })
    stepSim(run, { x: 0, y: 0 }, 1 / 60)
    assert(run.enemies.length > 0, 'expected the opening credit to have spawned at least one enemy')
    for (const e of run.enemies) {
      assert.strictEqual(e.elite, false, `expected an early credit enemy to be non-elite, got elite=${e.elite}`)
      const base = ENEMIES[e.type]
      const expectedDmg = base.dmg * dmgScale(run.time) * run.mods.enemyDmgMul
      assert(Math.abs(e.dmg - expectedDmg) < EPS,
        `expected ${e.type} dmg ≈ ${expectedDmg} (base ${base.dmg} × dmgScale(${run.time}) × balance 0.75), got ${e.dmg}`)
    }
    console.log(`PASS run RR.e (spawned enemies carry the balance dmg mul): ${run.enemies.length} enemies, dmg ≈ base×dmgScale×0.75`)
  }

  console.log('PASS run RR (v6.4.5 chapter-wide balance): body/pond ease spawn+dmg and fatten xp at EVERY difficulty (dailies included, no gate), composes with EARLY_CALM and difficulty taxes, garden/blank untouched, spawned enemies carry the eased dmg')
}

// v6.4.6 (owner directive, Run SS): save slots — SAVE_SLOTS independent profiles, each its own
// localStorage key (state.js's slotKey), a pointer key says which is active (activeSlot/
// setActiveSlot), slot 1 IS the legacy SAVE_KEY (existing saves become slot 1 for free), and a
// module-level boundKey pins any save that fires before the caller's reload to the slot the
// in-memory meta was actually loaded from — never the slot the pointer was JUST flipped to. This
// scenario stubs localStorage (plain node has none) and consumes zero Math.random, so it's safe
// to run last without disturbing the shared seeded stream the rest of the file relies on.
function testSaveSlots() {
  const LEGACY_KEY = 'charming-anomaly-save-v1'
  const _store = new Map()
  globalThis.localStorage = {
    getItem: (k) => (_store.has(k) ? _store.get(k) : null),
    setItem: (k, v) => _store.set(k, String(v)),
    removeItem: (k) => _store.delete(k),
  }

  // (a) empty store -> activeSlot() defaults to 1.
  assert.strictEqual(activeSlot(), 1, `expected activeSlot() to default to 1 on an empty store, got ${activeSlot()}`)
  console.log('PASS run SS.a (default slot): activeSlot() === 1 with an empty store')

  // (b) loadMeta() binds boundKey to the active slot's key; slot 1 IS the legacy key, so a
  // subsequent saveMeta writes there — the "existing save becomes slot 1 for free" guarantee.
  let m = loadMeta()
  saveMeta(m)
  assert(_store.has(LEGACY_KEY), `expected saveMeta to write the legacy key ${LEGACY_KEY}`)
  console.log('PASS run SS.b (slot 1 = legacy key): loadMeta + saveMeta writes charming-anomaly-save-v1')

  // (c) race guard: setActiveSlot(2) writes ONLY the pointer. The meta loaded in (b) is still
  // bound to the legacy key, so a save firing in the window before the caller's reload must still
  // land there, never bleed into the slot the pointer was just flipped to.
  setActiveSlot(2)
  saveMeta(m)
  assert(_store.has(LEGACY_KEY), 'expected saveMeta to still write the legacy key after setActiveSlot(2) (boundKey race guard)')
  assert(!_store.has(`${LEGACY_KEY}:2`), `expected ${LEGACY_KEY}:2 to stay absent before the reload rebinds`)
  console.log('PASS run SS.c (race guard): saveMeta still targets the legacy key right after setActiveSlot(2), :2 key absent')

  // (d) a fresh loadMeta() rebinds boundKey to the now-active slot (2) — saveMeta now targets :2.
  m = loadMeta()
  saveMeta(m)
  assert(_store.has(`${LEGACY_KEY}:2`), `expected a fresh loadMeta() to rebind to ${LEGACY_KEY}:2`)
  console.log('PASS run SS.d (rebind on reload): a fresh loadMeta() + saveMeta now writes charming-anomaly-save-v1:2')

  // (e) slotSummary is a display-only peek, no mutation: slot 3 was never written -> null; slot 2
  // (just saved in (d)) is a real summary shaped { coins, unlocked, total }.
  assert.strictEqual(slotSummary(3), null, 'expected slotSummary(3) to be null (never written)')
  const s2 = slotSummary(2)
  assert(s2 && typeof s2.coins === 'number' && typeof s2.unlocked === 'number',
    `expected slotSummary(2) to be a non-null summary with numeric coins/unlocked, got ${JSON.stringify(s2)}`)
  assert.strictEqual(s2.total, CHAPTER_ORDER.length, `expected slotSummary(2).total === CHAPTER_ORDER.length (${CHAPTER_ORDER.length}), got ${s2.total}`)
  console.log(`PASS run SS.e (slotSummary): slot 3 null (empty), slot 2 = {coins:${s2.coins}, unlocked:${s2.unlocked}, total:${s2.total}}`)

  // (f) a garbage/out-of-range pointer clamps activeSlot() back into [1, SAVE_SLOTS] rather than
  // propagating the garbage value.
  setActiveSlot(99)
  const clamped = activeSlot()
  assert(clamped >= 1 && clamped <= SAVE_SLOTS, `expected activeSlot() to clamp into [1, ${SAVE_SLOTS}], got ${clamped}`)
  console.log(`PASS run SS.f (clamp): setActiveSlot(99) -> activeSlot() = ${clamped} (clamped into [1, ${SAVE_SLOTS}])`)

  // (g) v6.4.7: tampered string coins (an adversarial probe injected '<img onerror=…>' here)
  // coerce to a number — the slot modal interpolates summary.coins into innerHTML, so slotSummary
  // must never pass a string through.
  _store.set(`${LEGACY_KEY}:3`, JSON.stringify({ coins: '<img src=x onerror=1>', chapters: {} }))
  const s3 = slotSummary(3)
  assert.strictEqual(s3.coins, 0, `expected tampered string coins to coerce to 0, got ${JSON.stringify(s3.coins)}`)
  console.log('PASS run SS.g (coins coercion): tampered string coins summarize as 0, never raw into innerHTML')

  // (h) v6.6.10: the SAME hardening on loadMeta, which SS.g never covered. slotSummary feeds only
  // the slot modal; loadMeta feeds the title coins badge (ui.js), the shop balance (:717), the
  // reroll button (:1132) and shopFootHtml's `owned` sum (:560) — all interpolated into innerHTML.
  // Every value below survived loadMeta verbatim before this fix.
  setActiveSlot(1)
  _store.set(LEGACY_KEY, JSON.stringify({
    coins: '<img src=x onerror=1>',
    runs: '<svg onload=2>',
    shop: { [Object.keys(SHOP)[0]]: '<b>X</b>' },
    chapters: {},
  }))
  const tampered = loadMeta()
  assert.strictEqual(tampered.coins, 0, `expected loadMeta to coerce tampered coins to 0, got ${JSON.stringify(tampered.coins)}`)
  assert.strictEqual(tampered.runs, 0, `expected loadMeta to coerce tampered runs to 0, got ${JSON.stringify(tampered.runs)}`)
  const owned = Object.values(tampered.shop).reduce((sum, l) => sum + l, 0) // shopFootHtml's exact expression
  assert.strictEqual(owned, 0, `expected shop levels to sum as a number, got ${JSON.stringify(owned)}`)
  assert(Object.values(tampered.shop).every((l) => typeof l === 'number'), 'expected every shop level to be a number after loadMeta')
  console.log('PASS run SS.h (loadMeta coercion): tampered coins/runs/shop levels all load as numbers, never raw into innerHTML')

  console.log('PASS run SS (v6.4.6 save slots): default slot, slot 1 = legacy key, boundKey race guard across setActiveSlot, rebind on reload, slotSummary null/real, garbage-pointer clamp')
}

// ---- Run TT: v6.5 undergrowth streamed traps + predator interactions ------------------------
// Traps moved from a one-shot origin scatter (state.js's deleted generateTraps) to sim.js's
// deterministic cell-hash streaming (streamTraps, the streamEddies idiom, salts 15/16/17), with
// sprung state persisted across streaming via run._trapRearm (a Map, cell -> absolute re-arm
// time). This locks in: (a) determinism + zero Math.random() at stream time, (b) a sprung trap's
// state surviving the trap object itself streaming out of range and back, (c) the cat's pounce
// land-slam (predators-gated) vs the leap-skip that lets it fly OVER traps mid-air, (d) claw
// rake's ambushPredator mod (armed OR sprung, not armed-only), and (e) dartRat's minT/weight gate
// on the undergrowth roster.
function testStreamedTrapPredators() {
  const dt = 1 / 60

  // (a) determinism + zero-RNG: streamTraps is a pure hash of (cell, _obstacleSeed, salt), so two
  // runs pinned to the SAME _obstacleSeed literal materialize byte-identical trap fields, and
  // re-scanning a fresh neighborhood (crossing a full cell width) draws NOT ONE Math.random() call
  // — the AA.c/runStarOnly scar this whole streaming idiom exists to avoid (mirrors Run NN.a's
  // eddy version of the same check).
  {
    Math.random = mulberry32(20260714)
    const SEED = 0xBADC0DE
    const runA = createRun(makeMeta(), { chapter: 'undergrowth' })
    runA.mods.spawnMul = 0
    runA._obstacleSeed = SEED
    stepSim(runA, { x: 0, y: 0 }, dt)

    const runB = createRun(makeMeta(), { chapter: 'undergrowth' })
    runB.mods.spawnMul = 0
    runB._obstacleSeed = SEED
    stepSim(runB, { x: 0, y: 0 }, dt)

    assert(runA.traps.length > 0, 'expected the pinned seed to stream at least one trap')
    const key = (tr) => `${tr._cell}:${tr.x.toFixed(3)}:${tr.y.toFixed(3)}:${tr.armed}`
    assert.strictEqual(runB.traps.map(key).sort().join('|'), runA.traps.map(key).sort().join('|'),
      'expected two runs pinned to the same _obstacleSeed to stream IDENTICAL trap fields')

    // Cross a full cell (signature.traps.cell px) so streamTraps' cursor forces a re-scan, wrapped
    // in a counting Math.random proxy.
    const cellPx = CHAPTERS.undergrowth.signature.traps.cell
    const before = Math.random
    let calls = 0
    Math.random = (...a) => { calls++; return before(...a) }
    try {
      runA.player.x += cellPx
      stepSim(runA, { x: 0, y: 0 }, dt)
    } finally {
      Math.random = before
    }
    assert.strictEqual(calls, 0, `expected streamTraps' re-scan to consume ZERO Math.random() draws, got ${calls}`)
    console.log(`PASS run TT.a (determinism + zero-RNG): ${runA.traps.length} identical traps across two pinned-seed runs; re-scan after crossing a cell drew ${calls} draws`)
  }

  // (b) sprung persistence across streaming: springing a streamed trap writes run._trapRearm keyed
  // by _cell; the trap ITSELF can stream out of range (dropped) and back (rematerialized) while the
  // ledger remembers it was recently sprung, only clearing (lazily) once it's read back armed.
  {
    Math.random = mulberry32(20260714)
    const run = createRun(makeMeta(), { chapter: 'undergrowth' })
    run.mods.spawnMul = 0
    run._obstacleSeed = 0xC0FFEE
    run.player.hp = run.player.maxHP = 1e9
    stepSim(run, { x: 0, y: 0 }, dt) // materialize the field around the origin
    assert(run.traps.length > 0, 'expected at least one streamed trap to pick as the test subject')
    const target = run.traps[0]
    const cellKey = target._cell

    // Spring it: stand on it with invuln cleared.
    run.player.invuln = 0
    run.player.x = target.x; run.player.y = target.y
    stepSim(run, { x: 0, y: 0 }, dt)
    assert(run._trapRearm.has(cellKey), 'expected the ledger to hold the sprung cell')
    const rearmAt = run._trapRearm.get(cellKey)
    assert(rearmAt > run.time, `expected rearmAt in the future, got ${rearmAt} at run.time=${run.time}`)

    // Walk far enough away to drop the trap object itself (crossing cells forces the re-scan).
    run.player.x = target.x + OBSTACLE_DROP_RADIUS + 5000
    run.player.y = target.y
    stepSim(run, { x: 0, y: 0 }, dt)
    assert(!run.traps.some((tr) => tr._cell === cellKey), 'expected the sprung trap to despawn once out of range')
    assert(run._trapRearm.has(cellKey), 'expected the ledger entry to SURVIVE the trap streaming out of range')
    assert.strictEqual(run._trapRearm.get(cellKey), rearmAt, 'expected the ledger to keep the SAME rearmAt while out of range')

    // Walk back before rearmAt (crossing cells again, so the re-scan actually runs): the SAME cell
    // rematerializes a trap, reading its armed state back off the ledger rather than defaulting armed.
    run.player.x = target.x; run.player.y = target.y
    stepSim(run, { x: 0, y: 0 }, dt)
    const back = run.traps.find((tr) => tr._cell === cellKey)
    assert(back, 'expected the same cell to rematerialize a trap on return')
    assert.strictEqual(back.armed, false, 'expected the rematerialized trap to come back UNARMED (still on cooldown)')
    assert.strictEqual(back.rearmAt, rearmAt, 'expected the rematerialized trap to carry the ledger rearmAt exactly')
    assert(run._trapRearm.has(cellKey), 'expected the ledger entry to still be present before rearmAt')

    // Advance run.time past rearmAt (resetting the elite-cadence pointer per the file's jump-time
    // idiom) — it re-arms in place and the ledger entry is lazily deleted.
    run.time = rearmAt + 0.1
    run._nextEliteAt = run.time + eliteEveryAt(run.time)
    stepSim(run, { x: 0, y: 0 }, dt)
    const rearmed = run.traps.find((tr) => tr._cell === cellKey)
    assert(rearmed, 'expected the trap to still be present after re-arming')
    assert.strictEqual(rearmed.armed, true, 'expected the trap to re-arm once run.time passes rearmAt')
    assert(!run._trapRearm.has(cellKey), 'expected the ledger entry to be deleted once read back armed')

    console.log(`PASS run TT.b (sprung persistence across streaming): cell ${cellKey} sprung -> despawned (ledger survived) -> rematerialized unarmed -> re-armed + ledger cleared`)
  }

  // (c) leap-skip + land-slam: an airborne cat (_pounceState 'leap') flies OVER an armed trap
  // untouched — stepTraps' enemy loop explicitly skips any enemy mid-leap — but its LANDING slams
  // any armed trap under it (combined radius tr.r+e.radius) for
  // max(SNAP_TRAP_DMG*2, maxHP*POUNCE_TRAP_HP_FRAC), gated on the chapter's 'predators' signature.
  {
    Math.random = mulberry32(20260714)
    const run = createRun(makeMeta(), { chapter: 'undergrowth' })
    run.weapons = []; run.obstacles = []; run._obstacleSeed = null; run.mods.spawnMul = 0
    run.player.x = 5000; run.player.y = 5000 // far away — this is about the trap, not contact damage
    run.player.hp = run.player.maxHP = 1e9
    // Hand-placed trap: NO _cell, exercising springTrap's `_cell != null` ledger guard.
    run.traps = [{ x: 0, y: 0, r: SNAP_TRAP_R, armed: true, rearmAt: 0 }]
    const trap = run.traps[0]

    const maxHP = 2000
    const cat = makeStatusEnemy(run, { x: 0, y: 0, hp: maxHP, speed: 60 })
    cat.flags = ['pounce']
    cat._pounceState = 'leap'
    cat._pounceT = 0.2 // stays leaping through this whole frame
    cat._pounceDirX = 1; cat._pounceDirY = 0
    run.enemies.push(cat)

    stepSim(run, { x: 0, y: 0 }, dt)
    assert.strictEqual(cat._pounceState, 'leap', `expected the cat still airborne, got '${cat._pounceState}'`)
    assert.strictEqual(trap.armed, true, 'expected an armed trap under an airborne (leap) cat to stay armed (leap-skip)')
    assert.strictEqual(cat.hp, maxHP, 'expected the leap-skip to deal no damage')

    // Expire _pounceT this frame so the land transition fires while still inside tr.r + e.radius.
    cat._pounceT = 0.001
    stepSim(run, { x: 0, y: 0 }, dt)
    assert.strictEqual(cat._pounceState, 'land', `expected the cat to land, got '${cat._pounceState}'`)
    assert.strictEqual(trap.armed, false, 'expected the landing to spring the trap')
    const expectedDmg = Math.max(SNAP_TRAP_DMG * 2, maxHP * POUNCE_TRAP_HP_FRAC)
    assert.strictEqual(cat.hp, maxHP - expectedDmg, `expected the land-slam to deal ${expectedDmg}, cat hp=${cat.hp} (maxHP ${maxHP})`)

    // Gated on the chapter's 'predators' signature: an identical landing in a non-predators chapter
    // (city — traffic) never scans run.traps at all.
    const cityRun = createRun(makeMeta(), { chapter: 'city' })
    cityRun.weapons = []; cityRun.obstacles = []; cityRun._obstacleSeed = null; cityRun.mods.spawnMul = 0
    cityRun._laneAcc = 1e6 // park traffic — irrelevant noise here
    cityRun.player.x = 5000; cityRun.player.y = 5000
    cityRun.player.hp = cityRun.player.maxHP = 1e9
    cityRun.traps = [{ x: 0, y: 0, r: SNAP_TRAP_R, armed: true, rearmAt: 0 }]
    const cityTrap = cityRun.traps[0]
    const cityCat = makeStatusEnemy(cityRun, { x: 0, y: 0, hp: maxHP, speed: 60 })
    cityCat.flags = ['pounce']
    cityCat._pounceState = 'leap'
    cityCat._pounceT = 0.001 // lands THIS frame, right on the trap
    cityCat._pounceDirX = 1; cityCat._pounceDirY = 0
    cityRun.enemies.push(cityCat)
    stepSim(cityRun, { x: 0, y: 0 }, dt)
    assert.strictEqual(cityCat._pounceState, 'land', `expected the city cat to land too, got '${cityCat._pounceState}'`)
    assert.strictEqual(cityTrap.armed, true, 'expected a non-predators chapter to leave the trap untouched by the land-slam')
    assert.strictEqual(cityCat.hp, maxHP, 'expected a non-predators chapter to deal no land-slam damage')

    console.log(`PASS run TT.c (leap-skip + land-slam): airborne cat over an armed trap took 0 dmg (still armed), landing sprung it for ${expectedDmg} dmg (maxHP ${maxHP}); a non-predators landing left the trap untouched`)
  }

  // (d) ambushPredator: clawRake hits harder near ANY trap — armed OR sprung (a SPRUNG trap here
  // deliberately pins that contract: springing your own trap must not switch the buff off) —
  // within AMBUSH_R of the PLAYER. Each variant reseeds identically so the crit roll (Math.random
  // in applyDamage) lines up between them; passives.damage=3 (a flat x4 multiplier) inflates the
  // raw numbers so integer rounding can't blur the ratio.
  {
    function ambushRun(trapDist) {
      Math.random = mulberry32(20260714)
      const run = createRun(makeMeta(), { chapter: 'undergrowth' })
      run.weapons = [{ id: 'clawRake', level: MAX_WEAPON_LEVEL }]
      run.obstacles = []; run._obstacleSeed = null; run.mods.spawnMul = 0
      run.passives.damage = 3
      run.weaponMods.clawRake = { ambushPredator: 0.45 }
      run.player.x = 0; run.player.y = 0; run.player.hp = 1e9; run.player.maxHP = 1e9
      run.traps = [{ x: trapDist, y: 0, r: SNAP_TRAP_R, armed: false, rearmAt: 1e9 }] // SPRUNG, not armed
      const target = makeStatusEnemy(run, { x: 100, y: 0, hp: 1e9, speed: 0 })
      target.flags = []
      run.enemies.push(target)
      let sawRake = null
      for (let i = 0; i < Math.round(2 / dt) && !sawRake; i++) {
        if (run.phase === 'levelup') { declineLevelUp(run); continue }
        stepSim(run, { x: 0, y: 0 }, dt)
        sawRake = run.events.find((ev) => ev.type === 'clawRake')
      }
      assert(sawRake, `expected a clawRake slash within 2s (trapDist=${trapDist})`)
      return 1e9 - target.hp
    }

    const near = ambushRun(AMBUSH_R - 10)
    const far = ambushRun(AMBUSH_R + 200)
    const ratio = near / far
    assert(Math.abs(ratio - 1.45) < 0.02,
      `expected a sprung trap within AMBUSH_R to hit ~1.45x harder than one beyond it, got x${ratio.toFixed(3)} (near=${near}, far=${far})`)
    console.log(`PASS run TT.d (ambushPredator): sprung trap inside AMBUSH_R -> ${near} dmg, outside -> ${far} dmg (x${ratio.toFixed(3)}, armed-or-sprung contract pinned via the sprung trap)`)
  }

  // (e) v6.6.28 (owner: "mice should not 'jump' only walk"). This slot used to cover the v6.5
  // `dartRat` entry's minT/weight gate. That entry is GONE — `dashBurst` is idle-then-committed-
  // lunge with no leap drawn for it, which on screen is a rat teleporting at you. So the slot now
  // carries the owner's rule as a TRIPWIRE, and re-homes the generic minT/weight coverage the
  // deleted assertions used to provide onto city's `patrolDrone`, which is still built on it.
  {
    // (e1) the tripwire: nothing in undergrowth may re-acquire a dash/leap movement flag. Written
    // against the flag VOCABULARY rather than against the one id that carried it, so re-adding the
    // behaviour under a different roster id still trips this.
    const JUMPY = ['dashBurst', 'pounce', 'diveBomb', 'blink', 'aerialStrike']
    for (const entry of CHAPTERS.undergrowth.roster) {
      if (entry.id === 'toad') continue // the one deliberate exception — asserted positively below
      for (const flag of entry.flags ?? []) {
        assert.ok(!JUMPY.includes(flag),
          `undergrowth roster '${entry.id}' carries '${flag}' — the owner's rule is that its rodents WALK. ` +
          'The cat keeps `pounce` because it is the chapter signature and is telegraphed; nothing else may leap.')
      }
    }
    // The cat is the one deliberate exception, and it must still be there — otherwise the loop
    // above is vacuously true and the chapter has silently lost its signature predator.
    const pouncer = CHAPTERS.undergrowth.roster.find((e) => e.id === 'toad')
    assert.ok(pouncer?.flags?.includes('pounce'), 'undergrowth lost the toad\'s telegraphed pounce — that IS the chapter signature')
    assert.strictEqual(CHAPTERS.undergrowth.roster.length, 3,
      'undergrowth roster changed size — if an entry was added, decide whether it may leap and update JUMPY above')
    console.log(`PASS run TT.e1 (rodents walk): 0/${CHAPTERS.undergrowth.roster.length} undergrowth entries carry a leap flag, cat keeps its telegraphed pounce`)

    // (e2) the minT/weight machinery itself, re-homed to city's patrolDrone (minT 60, weight 0.3).
    // Same forced-batch approach the dartRat version used: prime _spawnAcc, silence spawnMul, pin
    // run.time, and let the REAL spawn path pick out of the roster pool for that window.
    Math.random = mulberry32(20260714)
    const drone = CHAPTERS.city.roster.find((e) => e.id === 'patrolDrone')
    assert.ok(drone?.minT > 0 && drone.weight > 0, 'city patrolDrone lost its minT/weight gate — TT.e2 has nothing to test')
    const run = createRun(makeMeta(), { chapter: 'city' })
    run.weapons = []; run.obstacles = []; run._obstacleSeed = null; run.mods.spawnMul = 0
    run.player.x = 0; run.player.y = 0; run.player.hp = run.player.maxHP = 1e9

    run.time = drone.minT - 20
    run._spawnAcc = 40
    stepSim(run, { x: 0, y: 0 }, 1e-6)
    const early = run.enemies.filter((e) => e.rosterId === 'ratDrone' || e.rosterId === 'patrolDrone')
    assert(early.length > 0, 'expected at least one normal-archetype spawn before minT to make the next assert meaningful')
    const earlyGated = early.filter((e) => e.rosterId === 'patrolDrone').length
    assert.strictEqual(earlyGated, 0, `expected ZERO patrolDrone spawns before minT=${drone.minT}, got ${earlyGated}/${early.length}`)

    run.enemies = []
    run.time = drone.minT + 60
    run._nextEliteAt = run.time + eliteEveryAt(run.time)
    run._spawnAcc = 80
    stepSim(run, { x: 0, y: 0 }, 1e-6)
    const late = run.enemies.filter((e) => e.rosterId === 'ratDrone' || e.rosterId === 'patrolDrone')
    const plain = late.filter((e) => e.rosterId === 'ratDrone')
    const gated = late.filter((e) => e.rosterId === 'patrolDrone')
    assert(plain.length > 0, `expected plain rat-catcher drones to still spawn past minT, got ${plain.length}/${late.length}`)
    assert(gated.length > 0, `expected patrolDrone spawns once minT=${drone.minT} has passed, got ${gated.length}/${late.length}`)
    assert(gated.length < late.length, `weight=${drone.weight} must keep patrolDrone a MINORITY of the normal pool, got ${gated.length}/${late.length}`)
    for (const d of gated) {
      // v6.10.3 (owner: "some drones circle and dash, remove that"). The patrol drone dropped
      // `aerialStrike` and is a plain chaser now. Asserted as an ABSENCE so the behaviour cannot
      // creep back in unnoticed — the weight/minT gating below is the part still under test.
      assert(!d.flags.includes('aerialStrike'), `expected the patrolDrone to have NO aerialStrike, got [${d.flags.join(',')}]`)
    }
    console.log(`PASS run TT.e2 (minT/weight machinery): 0/${early.length} patrolDrone before t=${drone.minT}, ${gated.length}/${late.length} after (all carrying aerialStrike)`)
  }

  console.log('PASS run TT (v6.5 undergrowth streamed traps): determinism + zero-RNG, sprung persistence across streaming, leap-skip + land-slam, ambushPredator armed-or-sprung, rodents-walk tripwire + minT/weight')
}

// ---- Run UU: v6.5.1 enemy separation — no more 100% stacks (owner directive) -----------------
// stepEnemySeparation (sim.js, called every stepSim right before stepObstacles) pushes overlapping
// enemies apart via a spatial-hash pair search: two enemies may overlap until their centers are
// within ENEMY_SEP_FRAC of their combined radii but never past it, snapped to minSep per frame
// (ENEMY_SEP_RESOLVE 1 — a soft resolve loses to convergence pressure, see config.js). Every
// assert derives from the constants, so retunes (0.2 -> 0.4 -> 0.65 across the owner's
// successive "less clustered" passes) go through untouched. This locks in: (a) an exactly-coincident pair (the stacked-spawn case) converges
// to >= minSep apart via the deterministic golden-angle tiebreak, and the same pair-finding also
// resolves a pair straddling a spatial-hash cell boundary (the neighbor-bucket search), (b) a pair
// already legally spaced is left bit-for-bit untouched, (c) rosterId 'bindnode' (the blank's
// stationary binding nodes) is excluded outright, and (d) the whole pass draws ZERO Math.random()
// (the counting-proxy idiom from Run TT.a) — this runs every frame on every tested path.
function testEnemySeparation() {
  const dt = 1 / 60

  // (a) exactly-coincident pair: converges to >= minSep apart (not merely closer), and a second
  // pair straddling a ENEMY_SEP_CELL boundary (different buckets, adjacent cells) resolves too —
  // proving the forward-neighbor-bucket search, not just the same-bucket path.
  {
    Math.random = mulberry32(20260714)
    const run = createRun(makeMeta())
    run.weapons = []; run.obstacles = []; run._obstacleSeed = null; run.mods.spawnMul = 0
    run.player.x = 5000; run.player.y = 5000 // far away — this is about the pair, not contact damage
    run.player.hp = run.player.maxHP = 1e9

    const a = makeStatusEnemy(run, { x: 0, y: 0, hp: 1e9, speed: 0 })
    const b = makeStatusEnemy(run, { x: 0, y: 0, hp: 1e9, speed: 0 })
    run.enemies.push(a, b)
    const minSep = ENEMY_SEP_FRAC * (a.radius + b.radius)

    // Straddles the cell boundary at x = ENEMY_SEP_CELL: c sits just inside the lower cell, d just
    // inside the next one, close enough to overlap past minSep but bucketed into DIFFERENT cells.
    const c = makeStatusEnemy(run, { x: ENEMY_SEP_CELL - 3, y: 5 * ENEMY_SEP_CELL, hp: 1e9, speed: 0 })
    const d = makeStatusEnemy(run, { x: ENEMY_SEP_CELL + 3, y: 5 * ENEMY_SEP_CELL, hp: 1e9, speed: 0 })
    run.enemies.push(c, d)
    assert.notStrictEqual(Math.floor(c.x / ENEMY_SEP_CELL), Math.floor(d.x / ENEMY_SEP_CELL),
      'expected c/d to sit in different spatial-hash cells (test setup check)')

    for (let i = 0; i < 100; i++) stepSim(run, { x: 0, y: 0 }, dt)

    const distAB = Math.hypot(b.x - a.x, b.y - a.y)
    assert(distAB > 1e-6, 'expected the coincident pair to no longer be coincident')
    assert(distAB >= minSep - 1e-6, `expected the coincident pair to reach >= minSep=${minSep}, got ${distAB}`)

    const distCD = Math.hypot(d.x - c.x, d.y - c.y)
    assert(distCD >= minSep - 1e-6, `expected the cross-cell pair to reach >= minSep=${minSep}, got ${distCD}`)

    console.log(`PASS run UU.a (coincident + cross-cell convergence): same-point pair -> ${distAB.toFixed(3)}px apart (minSep ${minSep}), cell-boundary pair -> ${distCD.toFixed(3)}px apart`)
  }

  // (b) already-legal spacing: a pair placed just OVER minSep apart is left bit-for-bit untouched
  // (no drift when nothing is actually stacked).
  {
    Math.random = mulberry32(20260714)
    const run = createRun(makeMeta())
    run.weapons = []; run.obstacles = []; run._obstacleSeed = null; run.mods.spawnMul = 0
    run.player.x = 5000; run.player.y = 5000
    run.player.hp = run.player.maxHP = 1e9

    const a = makeStatusEnemy(run, { x: 0, y: 0, hp: 1e9, speed: 0 })
    const minSep = ENEMY_SEP_FRAC * (a.radius + a.radius)
    const b = makeStatusEnemy(run, { x: minSep + 1, y: 0, hp: 1e9, speed: 0 })
    run.enemies.push(a, b)
    const ax0 = a.x, ay0 = a.y, bx0 = b.x, by0 = b.y

    for (let i = 0; i < 20; i++) stepSim(run, { x: 0, y: 0 }, dt)

    assert.strictEqual(a.x, ax0, 'expected a legally-spaced enemy to be left untouched (x)')
    assert.strictEqual(a.y, ay0, 'expected a legally-spaced enemy to be left untouched (y)')
    assert.strictEqual(b.x, bx0, 'expected a legally-spaced enemy to be left untouched (x)')
    assert.strictEqual(b.y, by0, 'expected a legally-spaced enemy to be left untouched (y)')
    console.log(`PASS run UU.b (already-legal spacing untouched): pair at minSep+1=${(minSep + 1).toFixed(1)}px stayed bit-for-bit unchanged across 20 frames`)
  }

  // (c) bindnode exclusion: a rosterId 'bindnode' enemy stacked with two ordinary mobs never
  // moves — the mobs still separate from EACH OTHER (proving the pass is actually running, not
  // merely a no-op scenario), while the bindnode is skipped outright.
  {
    Math.random = mulberry32(20260714)
    const run = createRun(makeMeta())
    run.weapons = []; run.obstacles = []; run._obstacleSeed = null; run.mods.spawnMul = 0
    run.player.x = 5000; run.player.y = 5000
    run.player.hp = run.player.maxHP = 1e9

    const node = makeStatusEnemy(run, { x: 0, y: 0, hp: 1e9, speed: 0 })
    node.rosterId = 'bindnode'
    const mobA = makeStatusEnemy(run, { x: 0, y: 0, hp: 1e9, speed: 0 })
    const mobB = makeStatusEnemy(run, { x: 0, y: 0, hp: 1e9, speed: 0 })
    run.enemies.push(node, mobA, mobB)

    for (let i = 0; i < 100; i++) stepSim(run, { x: 0, y: 0 }, dt)

    assert.strictEqual(node.x, 0, 'expected the bindnode to be excluded from separation (x)')
    assert.strictEqual(node.y, 0, 'expected the bindnode to be excluded from separation (y)')
    const mobDist = Math.hypot(mobB.x - mobA.x, mobB.y - mobA.y)
    assert(mobDist > 1e-6, 'expected the two ordinary mobs to still separate from each other (pass is active)')
    console.log(`PASS run UU.c (bindnode exclusion): bindnode stayed at its spawn point while the two stacked mobs separated to ${mobDist.toFixed(3)}px apart`)
  }

  // (d) zero Math.random(): the entire pass — both the regular unit-delta push and the coincident
  // golden-angle tiebreak — is pure arithmetic, wrapped in the counting-proxy idiom (Run TT.a).
  {
    Math.random = mulberry32(20260714)
    const run = createRun(makeMeta())
    run.weapons = []; run.obstacles = []; run._obstacleSeed = null; run.mods.spawnMul = 0
    run.player.x = 5000; run.player.y = 5000
    run.player.hp = run.player.maxHP = 1e9

    // One exactly-coincident pair (exercises the tiebreak branch) and one merely-overlapping pair
    // (exercises the regular unit-delta branch) in the same frame.
    const a = makeStatusEnemy(run, { x: 0, y: 0, hp: 1e9, speed: 0 })
    const b = makeStatusEnemy(run, { x: 0, y: 0, hp: 1e9, speed: 0 })
    const c = makeStatusEnemy(run, { x: 1000, y: 1000, hp: 1e9, speed: 0 })
    const d = makeStatusEnemy(run, { x: 1003, y: 1000, hp: 1e9, speed: 0 })
    run.enemies.push(a, b, c, d)

    const before = Math.random
    let calls = 0
    Math.random = (...args) => { calls++; return before(...args) }
    try {
      for (let i = 0; i < 10; i++) stepSim(run, { x: 0, y: 0 }, dt)
    } finally {
      Math.random = before
    }
    assert.strictEqual(calls, 0, `expected stepEnemySeparation's pass (tiebreak + regular branch) to consume ZERO Math.random() draws, got ${calls}`)
    console.log(`PASS run UU.d (zero-RNG): 10 frames over a coincident pair + an overlapping pair drew ${calls} Math.random() calls`)
  }

  // (e) a DEEP knot disperses — the case two-enemy tests cannot see. With the tiebreak keyed on
  // the pair's FIRST index alone (the first-draft bug, found live in the blank's probe swarm),
  // pairs (A,B), (A,C), (A,D)... all push B/C/D along the SAME angle: the knot's members land on
  // one new shared point every frame and the pile never disperses. The per-PAIR angle (i and j
  // both feed it) must spread a 30-deep stack into a disc with the pairwise floor held.
  {
    Math.random = mulberry32(20260714)
    const run = createRun(makeMeta())
    run.weapons = []; run.obstacles = []; run._obstacleSeed = null; run.mods.spawnMul = 0
    run.player.hp = run.player.maxHP = 1e9
    // Stacked SEEKERS chasing the player from 300px out — the convergence pressure is part of
    // the scenario (a static stack is easier than the real blank knot).
    for (let i = 0; i < 30; i++) run.enemies.push(makeStatusEnemy(run, { x: 300, y: 0, hp: 1e9, speed: 90 }))
    for (let f = 0; f < 120; f++) stepSim(run, { x: 0, y: 0 }, dt)
    const es = run.enemies.filter((e) => !e._dead)
    assert.strictEqual(es.length, 30, `expected all 30 knot enemies alive, got ${es.length}`)
    const minSep = ENEMY_SEP_FRAC * (16 + 16)
    let minD = Infinity, cx = 0, cy = 0
    for (const e of es) { cx += e.x / es.length; cy += e.y / es.length }
    let spread = 0
    for (let a2 = 0; a2 < es.length; a2++) {
      spread = Math.max(spread, Math.hypot(es[a2].x - cx, es[a2].y - cy))
      for (let b2 = a2 + 1; b2 < es.length; b2++) {
        minD = Math.min(minD, Math.hypot(es[a2].x - es[b2].x, es[a2].y - es[b2].y))
      }
    }
    // 0.75x tolerance: single-iteration pair resolution leaves a Gauss-Seidel residual below the
    // exact floor in a crowd; what matters is the pile is a DISC, not a point.
    assert(minD >= minSep * 0.75, `expected the knot's pairwise floor to hold (>= ${(minSep * 0.75).toFixed(1)}), got ${minD.toFixed(2)}`)
    assert(spread >= minSep * 3, `expected a 30-knot to disperse into a disc (radius >= ${(minSep * 3).toFixed(1)}), got ${spread.toFixed(1)}`)
    console.log(`PASS run UU.e (deep-knot dispersal): 30 stacked seekers -> min pair ${minD.toFixed(2)}px (floor ${minSep.toFixed(1)}), disc radius ${spread.toFixed(1)}px`)
  }

  console.log('PASS run UU (v6.5.1 enemy separation): coincident + cross-cell convergence, already-legal spacing untouched, bindnode exclusion, deep-knot dispersal, zero-RNG')
}

// ---- Run VV: v6.6.4 per-chapter concurrent-enemy cap (owner directive) ----------------------
// CHAPTERS[id].balance.maxAliveMul thins how many enemies may be ALIVE AT ONCE (a different knob
// from spawnMul, which is how fast they arrive): a ladder of 180/240/300 for the three onboarding
// chapters (v6.6.6 + v6.6.7), full 400 from undergrowth on, everyone else
// untouched. createRun folds it into run.mods like every other chapter-balance key, and every
// MAX_ALIVE gate in sim.js reads maxAliveFor(run.mods), so this pins (a) the multipliers the owner
// asked for, (b) that the cap is actually ENFORCED by a saturating run rather than merely stored,
// and (c) that a late chapter is left at the global cap.
function testChapterDensityCap() {
  // (a) the three multipliers, and that no other chapter carries one
  const want = { body: 0.45, pond: 0.6, garden: 0.75 }
  for (const id of CHAPTER_ORDER) {
    const mul = CHAPTERS[id].balance?.maxAliveMul ?? 1
    assert.strictEqual(mul, want[id] ?? 1, `expected ${id} maxAliveMul ${want[id] ?? 1}, got ${mul}`)
  }
  // v6.6.7 (owner directive "smooth out the chapter curve"): the ladder must climb in even RATIO
  // steps, which is the property a future one-chapter tweak breaks silently — the pre-v6.6.7
  // ladder was +78% then +13% then +11% and every individual number in it looked reasonable.
  const ladder = CHAPTER_ORDER.map((id) => Math.round(MAX_ALIVE * (CHAPTERS[id].balance?.maxAliveMul ?? 1)))
  for (let i = 1; i < ladder.length; i++) {
    assert(ladder[i] >= ladder[i - 1], `expected the density ladder to never step DOWN, got ${JSON.stringify(ladder)}`)
    assert(ladder[i] / ladder[i - 1] <= 1.4,
      `expected no density step past +40%, ${CHAPTER_ORDER[i - 1]} ${ladder[i - 1]} -> ${CHAPTER_ORDER[i]} ${ladder[i]} in ${JSON.stringify(ladder)}`)
  }
  assert.strictEqual(maxAliveFor({ maxAliveMul: 0.7 }), Math.round(MAX_ALIVE * 0.7))
  assert.strictEqual(maxAliveFor({}), MAX_ALIVE, 'a mods object without the key must fall back to the global cap')
  assert.strictEqual(maxAliveFor(undefined), MAX_ALIVE, 'no mods at all must fall back to the global cap')

  // (b) createRun folds it into run.mods, and a saturating run never exceeds it. Weapons stripped
  // so nothing dies and the field can only grow; difficulty omitted so EARLY_CALM stays out of it
  // and this measures the balance block alone.
  const dt = 1 / 60
  const peaks = {}
  for (const id of ['body', 'pond', 'garden', 'city']) {
    Math.random = mulberry32(20260804)
    const run = createRun(makeMeta(), { chapter: id })
    run.weapons = []
    // v6.9.2: stripping weapons is not enough to stop things dying in the CITY — its signature
    // hazard kills on its own, and the taxi one-shots the light roster. That confound was invisible
    // until roundHP landed, because a fractional maxHP meant the squash branch dealt round(hp) and
    // left frac(maxHP) behind, so ~half of everything it hit survived and the field saturated
    // anyway. With the taxi actually killing again, city peaks at ~211 of its 400 cap. Park the
    // traffic signature for the measurement so this still tests the SPAWN cap and nothing else.
    run.mods.trafficIntervalMul = 1e9
    run.player.hp = run.player.maxHP = 1e9
    const cap = maxAliveFor(run.mods)
    assert.strictEqual(cap, Math.round(MAX_ALIVE * (CHAPTERS[id].balance?.maxAliveMul ?? 1)),
      `expected ${id} run cap to match its chapter multiplier`)
    // v7.8: STOP SOON AFTER SATURATION rather than always running the full 300s. This one scenario
    // was 58% of the suite's runtime (56.6s of 98s), and nearly all of it simulated a field that had
    // already reached its cap — city saturates at t=131s and then sits at 400 alive for 170 more
    // seconds, proving nothing it had not proved by t=146.
    //   THE TAIL LENGTH IS THE ENTIRE SAFETY ARGUMENT, so it was measured against a mutant rather
    // than guessed. With the cap gate deleted from stepSim's spawn loop, a 5s tail still PASSES on
    // body, garden and city — they overshoot by only 4.4%, under the 5% split-children allowance
    // below — so the obvious trim quietly guts the test while the peaks still look right. 10s is the
    // first tail that fails all four chapters; 15s is used for margin, taking the tightest (body)
    // from 9.4% over the threshold to 15.6%.
    //   Given up knowingly: this no longer proves the cap HOLDS for the rest of the run — a leak
    // starting after ~t=146 would now pass. Nothing time-varying feeds maxAliveFor today, so that is
    // a cheap thing to stop paying 40s per suite run for. Note the loop must keep its 300s bound as
    // the outer limit: garden does not saturate until t=266s, so a fixed shorter run fails outright.
    const TAIL_FRAMES = Math.round(15 / dt)
    let peak = 0
    let stopAt = Math.round(300 / dt)
    for (let i = 0; i < stopAt; i++) {
      if (run.phase === 'levelup') { declineLevelUp(run); continue }
      if (run.phase !== 'playing') break
      stepSim(run, { x: 0, y: 0 }, dt)
      run.player.hp = run.player.maxHP
      if (run.enemies.length > peak) peak = run.enemies.length
      if (peak >= cap) stopAt = Math.min(stopAt, i + TAIL_FRAMES)
    }
    peaks[id] = peak
  }
  // The cap gates SPAWNING, it is not a hard ceiling: spawnSplitChildren pushes a dying enemy's
  // clones unconditionally (a corpse's children must appear), so a saturated field can sit a few
  // over. Assert each chapter reaches its cap and never runs meaningfully past it.
  for (const [id, peak] of Object.entries(peaks)) {
    const cap = Math.round(MAX_ALIVE * (CHAPTERS[id].balance?.maxAliveMul ?? 1))
    assert(peak >= cap, `expected ${id} to saturate its cap ${cap}, peaked at ${peak}`)
    assert(peak <= cap * 1.05, `expected ${id} to stay at its cap ${cap} (only split children may exceed), peaked at ${peak}`)
  }
  // (c) ordering: the eased chapters are strictly thinner than each other and than baseline
  assert(peaks.body < peaks.pond && peaks.pond < peaks.garden && peaks.garden < peaks.city,
    `expected body < pond < garden < city peaks, got ${JSON.stringify(peaks)}`)

  console.log(`PASS run VV (v6.6.4 per-chapter density cap): peak alive body ${peaks.body} / pond ${peaks.pond} / garden ${peaks.garden} / city ${peaks.city} (global ${MAX_ALIVE})`)
}

// ---- Run XX: v6.6.8 French dictionary integrity ----------------------------------------------
// fr.js is the one module that is pure data with no Pixi/DOM, so it IS testable here, and the
// v6.6.8 localisation pass found three failure modes that are all invisible by inspection:
//   (a) a DUPLICATE KEY. `FR = { ...UI, ...CONFIG }` means the CONFIG copy silently wins, so a
//       hand-written UI translation becomes unreachable dead code. Ten keys were duplicated and
//       two had drifted apart, i.e. the wording someone maintained was not the wording shipped.
//       Nothing throws, nothing warns, and reading either section alone looks completely correct.
//   (b) a key that no English source string can produce. Keys ARE the English source (i18n.js:
//       `t = (s) => DICTS[lang]?.[s] ?? s`), so any drift means a silent fall back to English —
//       and the French typography sweep in (c) makes this a live risk, since a no-break space
//       looks identical to a normal one in an editor.
//   (c) French spacing before `: ; ! ?`, which must be U+00A0 in VALUES and must never appear in
//       a key. A plain space there is the single most visible marker of an unproofed French build.
function testFrenchDictionary() {
  const src = readFileSync(new URL('../src/fr.js', import.meta.url), 'utf8')
  // Key literals, both quote styles (one entry uses "…" because its value contains an apostrophe).
  const keys = [...src.matchAll(/^\s*'((?:[^'\\]|\\.)*)':/gm)].map((m) => m[1])
    .concat([...src.matchAll(/^\s*"((?:[^"\\]|\\.)*)":/gm)].map((m) => m[1]))
  const dupes = keys.filter((k, i) => keys.indexOf(k) !== i)
  assert.deepStrictEqual(dupes, [], `fr.js has duplicate keys — the later section silently wins and the earlier translation is dead: ${JSON.stringify(dupes)}`)

  const NBSP = ' '
  const badKeys = Object.keys(FR).filter((k) => k.includes(NBSP))
  assert.deepStrictEqual(badKeys, [], `a key contains U+00A0 — it can never match an English source string, so it falls back to English: ${JSON.stringify(badKeys)}`)
  const badValues = Object.values(FR).filter((v) => / [:;!?]/.test(v))
  assert.deepStrictEqual(badValues, [], `French values must use U+00A0 before : ; ! ? — plain space found in: ${JSON.stringify(badValues)}`)

  // Every player-visible string config.js owns must have an entry. This is what caught the two
  // City enemies added in v6.3 after the original translation pass.
  const missing = new Set()
  // Every string the config TABLES actually hand to the translator at runtime. Collected here so
  // check (d) below can tell a dead key from a COMPOSED one: v7.2's anomaly descs are template
  // literals interpolating their own tuning constants (`x${BRITTLE_DMG_MUL} damage`), so the
  // finished string exists only at runtime and never appears as a literal in any src/*.js.
  const produced = new Set()
  const need = (s) => { if (typeof s !== 'string' || !s) return; produced.add(s); if (!FR[s]) missing.add(s) }
  // Derived, not written down — see shippedChapterIds. A roster name is player-visible copy, and
  // this walk is the only thing that requires French for one.
  const frChapters = shippedChapterIds()
  for (const id of frChapters) {
    const ch = CHAPTERS[id]
    if (!ch) continue
    need(ch.name); need(ch.tagline)
    for (const r of ch.roster ?? []) need(r.name)
  }
  // v6.7.7: ANOMALIES joins the walk, and `from` joins the fields read. Two separate holes: a new
  // table of player-visible strings is exempt from this assert until someone adds it (the tier
  // shipped in v6.7.6 with three untranslated strings and this test green), and `from` is a field
  // no other table has — a walk that only reads name/desc/title covers two thirds of an anomaly
  // card. This is the same shape as the WEAPON_MODS hole below, three releases apart.
  for (const table of [WEAPONS, ELEMENTS, MUTATORS, CONSUMABLES, RARITIES, SHOP, PASSIVES, ANOMALIES]) {
    for (const v of Object.values(table ?? {})) { need(v?.name); need(v?.desc); need(v?.title); need(v?.from) }
  }
  // v6.6.26: WEAPON_MODS is TWO levels deep (WEAPON_MODS[weaponId][modId]), so the flat walk above
  // silently checked nothing for it — Object.values() yielded the per-weapon dicts, whose own
  // .name/.desc are undefined, and `need` skips undefined. Every weapon mod in the game was
  // exempt from this assert while appearing to be covered by it. Found when piercingNeedles was
  // added with no French entry and run XX still passed.
  for (const byMod of Object.values(WEAPON_MODS ?? {})) {
    for (const v of Object.values(byMod ?? {})) { need(v?.name); need(v?.desc); need(v?.title) }
  }
  // BOOK_SHOP and BOOK_UNLOCKS are the SAME two-levels-deep shape as WEAPON_MODS above
  // (BOOK_SHOP[bookId][lineId], BOOK_UNLOCKS[bookId][unlockId]) — verbatim the WEAPON_MODS hole
  // this walk documents eight lines above itself. The flat form (`for (const v of
  // Object.values(table)) need(v?.name)`) would yield the per-book dicts, read `.name` as
  // undefined off THOSE, and skip — a green coverage assert that covers nothing for either table.
  // A hand-rolled French-coverage check for these two tables already exists in run BP
  // (testBookProgression) — this is the CANONICAL config-table walk gaining the same coverage, so
  // a future table added here for an unrelated reason (the `dead`-key reverse check below, the
  // {placeholder} consistency check) covers Book copy too, not just "is it missing".
  for (const [table, fields] of [[BOOK_SHOP, ['name', 'desc']], [BOOK_UNLOCKS, ['name', 'desc']]]) {
    for (const byBook of Object.values(table ?? {})) {
      for (const v of Object.values(byBook ?? {})) for (const f of fields) need(v?.[f])
    }
  }
  // ELITE_AFFIXES is shown on the elite itself and no walk above reached it, so all seven names
  // had always shipped in English — found while translating the Codex line that names one of them.
  for (const v of Object.values(ELITE_AFFIXES ?? {})) need(v?.name)
  // The anomaly EFFECT CHIP labels — the words on the brief screen's trade, e.g. '+25% coins'.
  // They lived in a bare const inside ui.js until v7.x, which is the exemption this walk documents
  // three times above: it enumerates config TABLES, so a const in a function is invisible to it and
  // ships in English with the suite green. Tuple-shaped ([label, goodUp]), so it needs its own line
  // rather than the generic name/desc walk — same as CHAPTER_SPINE and DMG_SRC_NAME below.
  for (const [label] of Object.values(MUTATOR_EFFECT_LABELS ?? {})) need(label)
  // ...and the labels must COVER the key list exactly. effectChipList falls back to `[key, true]`,
  // so an unlabelled key does not throw and does not fall out of the walk above — it renders the
  // raw JS identifier to the player ('+80% tideSurgeMul') and calls it a GAIN whichever way it
  // points. Two shipped that way (springtide, deadWater) precisely because nothing tied the two
  // lists together. The reverse direction matters as much: a label for a key mergeMutatorMods can
  // never produce is copy that reaches no screen, and run XX's `dead` check cannot see it because
  // the string is live in this table.
  assert.deepStrictEqual(
    MUTATOR_MOD_KEYS.filter((k) => !MUTATOR_EFFECT_LABELS[k]), [],
    'MUTATOR_MOD_KEYS entries with no MUTATOR_EFFECT_LABELS row — the chip renders the raw key to the player')
  assert.deepStrictEqual(
    Object.keys(MUTATOR_EFFECT_LABELS).filter((k) => !MUTATOR_MOD_KEYS.includes(k)), [],
    'MUTATOR_EFFECT_LABELS rows for a key no mutator effect can produce — dead copy')
  for (const v of Object.values(CHAPTER_ENDINGS ?? {})) { need(v?.victory); need(v?.death) }
  for (const v of Object.values(CHAPTER_UNLOCK_LINES ?? {})) need(v)
  // Same flat id -> string shape, one book down. Joined here the day the table landed rather than
  // the day someone noticed the badge was English — the whole point of this walk.
  for (const v of Object.values(BOOK_UNLOCK_LINES ?? {})) need(v)
  for (const v of Object.values(CHAPTERS ?? {})) { need(v?.name); need(v?.tagline) }
  // ROSTER NAMES (v7.x). One level deeper than the walk above, so `Object.values(CHAPTERS)` reading
  // `.name` never reached them — and a creature's name had NO French-facing surface until the summary
  // screen's "Killed by ..." line and its damage breakdown put it on a screen. Three of the game's 46
  // entries turned out to be English (The Reef's, the newest roster); they were found by SHOOTING the
  // French panel, not by any assert, which is the whole argument for joining them to this walk.
  for (const ch of Object.values(CHAPTERS ?? {})) for (const r of ch?.roster ?? []) need(r?.name)
  // RESOURCE NAMES (v7.x, owner 2026-08-18). Same one-level-deeper shape as the roster above, and
  // the same story: Book 2's bars were named in config from the day they shipped, but the field had
  // no French-facing surface until the HUD rail put the word on screen beside the number. A new
  // screen can CREATE an i18n gap, not only reveal one — six chapters' worth here.
  for (const ch of Object.values(CHAPTERS ?? {})) need(ch?.resource?.name)
  // BOOKS[].name is on screen from v7.x (the shelf's brass plate) and no walk above reached it —
  // both Books would have shipped in English the day the bookcase landed.
  for (const v of Object.values(BOOKS ?? {})) need(v?.name)
  // The spine names. A flat id -> string table, so the generic name/desc walk above cannot see it.
  for (const v of Object.values(CHAPTER_SPINE ?? {})) need(v)
  // What killed you (v7.x). Same flat id -> string shape, joined the day the table landed — the
  // summary screen's killer line and every row of its damage breakdown resolve through here, so a
  // missing entry is a French screen with English causes of death on it.
  for (const v of Object.values(DMG_SRC_NAME ?? {})) need(v)
  // The pause build sheet's stat labels. These were unreachable by this walk until STAT_KEYS became
  // a config TABLE: the words lived in a bare const inside ui.js, and this walk enumerates tables,
  // so five of them shipped rendering in English on the French sheet. Merging the two registries
  // into one table is what makes them visible here at all — the coverage came free with the
  // deduplication, which is the argument for doing that kind of merge rather than guarding a split.
  for (const s of STAT_KEYS ?? []) need(s?.label)
  // The elements redesign's copy lives in FUNCTIONS, not a table, so every walk above is blind to
  // it — the third time this exemption has bitten (two City enemies in v6.3, every weapon mod in
  // v6.6.26). It shipped to the live URL with the card and the whole Codex untranslated, and this
  // assert was green the entire time. What is needed is the TEMPLATE, not the sentence: elements
  // interpolate their own numbers, so a composed string has a different key at every potency and
  // could never be translated at all (see elText/tt). Walking the ladder covers the `P > 0` lines.
  const maxP = MAX_ELEMENT_PICKS * Math.max(...Object.values(EL_VALUES))
  for (const id of Object.keys(ELEMENTS)) {
    for (let P = 0; P <= maxP; P++) {
      need(elementCardDesc(id, P).s)
      for (const l of elementCodex(id, P)) need(l.s)
    }
  }
  for (const s of ELEMENT_CODEX_INTRO) need(s)
  assert.deepStrictEqual([...missing], [], `config.js strings with no French entry (they ship in English): ${JSON.stringify([...missing])}`)

  // A translated TEMPLATE must carry the SAME placeholders as its key. tt() fills {k} from the
  // params the call site passes, so a dropped or misspelled one either prints literal braces to
  // the player or silently loses the number — and the sentence still reads fine in review, which
  // is why this needs a machine. Checked across the whole dictionary, not just the new keys.
  const holes = (str) => [...str.matchAll(/\{(\w+)\}/g)].map((m) => m[1]).sort().join(',')
  const badTemplates = Object.entries(FR).filter(([k, val]) => holes(k) !== holes(val))
    .map(([k, val]) => `${k}  ->  ${val}`)
  assert.deepStrictEqual(badTemplates, [], `French values whose {placeholders} do not match their key: ${JSON.stringify(badTemplates, null, 1)}`)

  // (d) the reverse direction (v6.6.9, owner directive "remove unused / shadowed keys"): a key no
  // source file can produce is dead weight that reads as coverage. It costs nothing at runtime,
  // which is exactly why it accumulates — the pre-v6.6.8 dictionary still carried the explainer
  // line from a sacrifice screen deleted three releases earlier. Keys are matched as literals
  // against every src/*.js but fr.js itself, testing both the raw key and the backslash-escaped
  // form a single-quoted source literal would use. If a key is ever legitimately BUILT rather
  // than written (concatenation, a template literal), this assert is the wrong shape for it and
  // the fix is to exempt that key here by name, not to delete a live translation.
  const srcDir = new URL('../src/', import.meta.url)
  const blob = readdirSync(srcDir).filter((f) => f.endsWith('.js') && f !== 'fr.js')
    .map((f) => readFileSync(new URL(f, srcDir), 'utf8')).join('\n')
  // v6.6.19: matched as a COMPLETE quoted literal, not a substring. A substring test cannot see a
  // dead key that is a prefix of a live one — 'Reroll' stayed invisible the moment 'Reroll this
  // anomaly ({n}🪙)' existed, and only came out because it was being tracked by hand. Every
  // wrapper the source could use is tried, with the escaping that wrapper would force.
  const literals = (k) => [
    `'${k.replace(/\\/g, '\\\\').replace(/'/g, "\\'")}'`,
    `'${k}'`,                                   // an apostrophe-free key, or one in a "…" value
    `"${k.replace(/\\/g, '\\\\').replace(/"/g, '\\"')}"`,
    `"${k}"`,
    `\`${k}\``,
  ]
  // `produced` is the second door, and it is NOT a loophole: a key that only matches through it is
  // one config.js currently composes, so it is live by construction. It also keeps the pair of
  // checks honest under a retune — change BRITTLE_DMG_MUL and the composed desc changes with it,
  // which drops out of `produced`, lands in `missing`, and turns check (c) RED naming the new
  // string. The alternative the comment above suggests (exempt each built key by name) would need
  // that list re-edited on every balance change, and would go quietly stale instead.
  const dead = Object.keys(FR).filter((k) => !produced.has(k) && !literals(k).some((lit) => blob.includes(lit)))
  assert.deepStrictEqual(dead, [], `fr.js keys no source string can produce — delete them: ${JSON.stringify(dead)}`)

  console.log(`PASS run XX (v6.6.8 French dictionary): ${keys.length} keys, no duplicates, none dead, no NBSP in keys, ${Object.values(FR).filter((v) => v.includes(NBSP)).length} values with French NBSP, full config.js coverage`)
}

// ---- Run SY: the sync wiring nothing else can see --------------------------------------------
//
// sync.js is unit-testable; the things that CONNECT it are not. main.js and ui.js cannot be
// imported here, so these are source-text contracts in the style of run UG.k and run MB.a — and
// every one of them fails SILENTLY: a missing trigger is a handoff that quietly does not happen,
// which is precisely the symptom this whole feature exists to remove.
function testSyncWiring() {
  const main = readFileSync(new URL('../src/main.js', import.meta.url), 'utf8')
  const ui = readFileSync(new URL('../src/ui.js', import.meta.url), 'utf8')
  const sw = readFileSync(new URL('../public/sw.js', import.meta.url), 'utf8')
  const vite = readFileSync(new URL('../vite.config.js', import.meta.url), 'utf8')
  // Same two clauses, same reason, as run UR's — see the long note there. ui.js is exactly the file
  // that proves it: two import.meta.glob('./cast/*.png') calls were blanking 1012 of its lines.
  const strip = (src) => src
    .replace(/(^|[^:])\/\/[^\n]*/g, '$1 ')
    .replace(/(^|[\s(,;={[])\/\*[\s\S]*?\*\//g, '$1 ')
  const m = strip(main)
  const u = strip(ui)

  // (a) THE SAFETY INVARIANT BEHIND EVERY ADOPT. `run` is a `let` local inside boot(), unreachable
  // from sync.js, so main.js must hand the predicate in — and it must actually read `run === null`,
  // not something that merely looks like it. sync.js's own default REFUSES, so a missing wire fails
  // closed rather than adopting over a live run; this asserts the wire exists at all.
  assert.ok(/isIdle:\s*\(\)\s*=>\s*run === null/.test(m),
    'run SY: main.js does not pass `isIdle: () => run === null` to initSync — without it the ' +
    'invariant that an adopt never lands mid-run is prose with no implementation')

  // (b) ALL SEVEN TRIGGERS (§6.3). Named individually rather than counted, because "6 of 7" and
  // "7 of 7" print identically in a count and the missing one is always the interesting one.
  const TRIGGERS = [
    ['pull on boot', /\n\s*syncEvaluate\(\)/],
    ['pull on visible', /visibilityState === 'visible'\) syncEvaluate\(\)/],
    ['pull on run becoming null (onQuit)', /run = null[\s\S]{0,400}?syncEvaluate\(\{ force: true \}\)/],
    ['push at run end', /saveMeta\(meta\)\s*pushNow\(\)/],
    ['push on hidden', /else pushNow\(\)/],
    ['push on pagehide', /addEventListener\('pagehide'[\s\S]{0,80}?pushNow\(\)/],
    ['push debounce via the save hook', /setSaveHook\(noteSave\)/],
  ]
  const absent = TRIGGERS.filter(([, re]) => !re.test(m)).map(([n]) => n)
  assert.deepStrictEqual(absent, [],
    `run SY: main.js is missing sync trigger(s) ${JSON.stringify(absent)} — each one is a handoff ` +
    `that silently does not happen, with nothing thrown and no other test red`)

  // (c) THE THIRD PULL TRIGGER IS THE ONE THAT RESCUES THE OWNER'S USE CASE, and it is the one an
  // earlier draft of §6.3 left out. `run` is set to null in exactly ONE place, so the summary and
  // pause screens both have run !== null: without a trigger tied to leaving them, a laptop closed
  // on the summary screen re-opens, pulls once (bumping the throttle), never adopts, and plays a
  // whole session on a stale generation before 409ing into the destructive prompt.
  // THE DECLARATION IS EXCLUDED. `let run = null` at the top of boot() is not a mid-session
  // transition to idle, and counting it is how the first cut of this assert went red on correct
  // code — the measured answer is 1 assignment, not the 2 a bare substring finds.
  const toIdle = (m.match(/(?<!let\s)\brun = null/g) ?? []).length
  assert.strictEqual(toIdle, 1,
    `run SY: run is assigned null at ${toIdle} sites, not 1 — the pull trigger is wired to onQuit ` +
    `alone, so a second one is a path that leaves the sim idle without ever re-evaluating sync`)

  // (d) ui.js owns the pixels and NONE of the protocol (design §3.1).
  assert.ok(!/from '\.\/sync\.js'/.test(ui),
    'run SY: ui.js imports sync.js — main.js must hand the module in as a hook, or ui.js has ' +
    'learned the protocol and the boundary that makes the renderer swappable is gone')
  // ⚠ THE CALL SITE, NOT THE NAME. The first cut of this asserted /syncRowHtml\(\)/ against the whole
  // file, which matches the FUNCTION DECLARATION — so deleting the `${syncRowHtml()}` line out of the
  // settings template left the feature with no entry point and this check green. A mutation proved
  // it: "the settings row is dropped" was the one pathology of eighteen that got through. Scope the
  // search to settingsSheetHtml's own body.
  const sheet = u.slice(u.indexOf('function settingsSheetHtml'))
  const sheetBody = sheet.slice(0, sheet.indexOf('\n  }'))
  assert.ok(/\$\{syncRowHtml\(\)\}/.test(sheetBody),
    'run SY: settingsSheetHtml no longer CALLS syncRowHtml — the cloud-sync row is gone from the ' +
    'only sheet that opens it, so the feature has no entry point at all')
  assert.ok(/settings-slots" data-act="sync-open"/.test(u),
    'run SY: the sync row is no longer a .settings-slots button opening the sheet')

  // (e) PUBLIC, AND THIS IS THE ASSERT THAT KEEPS IT THAT WAY. The row spent one release behind
  // meta.dev so the flow could be walked on a phone against the live URL. It is every player's
  // now, and the only switch that may still remove it is an empty SYNC_URL (asserted below).
  const row = u.slice(u.indexOf('function syncRowHtml'))
  const rowBody = row.slice(0, row.indexOf('\n  }'))
  // The isolation first: a NEGATIVE assert against an empty slice passes while checking nothing.
  assert.ok(rowBody.length > 200 && rowBody.length < 1200 && /data-act="sync-open"/.test(rowBody),
    `run SY: could not isolate syncRowHtml in ui.js (${rowBody.length} chars, measured 723) — the assert below would be measuring nothing`)
  // meta.dev is the game's ONE dev switch, so its absence from this function IS "every player can
  // reach cloud sync". Comments stripped, per run MB.a: the flag is discussed by name right here,
  // and a raw search is satisfied by the prose alone.
  assert.ok(!/meta\.dev/.test(rowBody.replace(/^\s*\/\/.*$/gm, '')),
    'run SY: syncRowHtml gates on the dev flag again — cloud sync is invisible to every ordinary ' +
    'player, with nothing thrown and the rest of the feature still wired and syncing')

  // ONE DEV SWITCH, NOT TWO. CLAUDE.md records what a second one cost: the coin badge used to carry
  // its own seven-tap burst, so the game had two answers to "is this a dev run", the leaderboard was
  // wired to only one of them, and a run played to reach a WIP chapter submitted to the public board
  // (v7.161.0). meta.dev is that one switch; this asserts the sync gate did not invent another.
  assert.ok(!/sync[A-Za-z]*Dev|devSync|_devSync/.test(u),
    'run SY: ui.js has grown a sync-specific dev flag — meta.dev is the ONE dev switch, and a second ' +
    'one is how the leaderboard came to disagree with itself about what a dev run is')

  // The kill switch still removes every pixel when SYNC_URL is empty, which is the rollback story.
  assert.ok(/reason === 'disabled' && !import\.meta\.env\.DEV.*return ''/.test(u),
    'run SY: ui.js renders the sync row in a build with no SYNC_URL — the kill switch leaves a dead ' +
    'control behind instead of removing the feature')
  assert.ok(/__SYNC_URL__:\s*JSON\.stringify/.test(vite),
    'run SY: vite.config.js no longer defines __SYNC_URL__, so sync.js falls back to the disabled ' +
    'branch in EVERY build and the feature can never be turned on')
  // And it must actually point somewhere, or "shipped behind the dev gate" is a claim about a
  // feature that cannot work at all.
  assert.ok(/https:\/\/[a-z0-9.-]+\/v1\/save/.test(vite),
    'run SY: vite.config.js no longer carries a sync endpoint — the dev-gated flow has nothing to ' +
    'talk to, so walking it on a phone would fail for a reason the UI cannot explain')

  // (g) THE SLOTS SHEET'S DELETE BUTTON (v7.x). ui.js owns the confirm and NONE of the
  // consequences; main.js owns both, and every one of them fails silently.
  const slotFn = u.slice(u.indexOf('function slotRowHtml'))
  const slotBody = slotFn.slice(0, slotFn.indexOf('\n  }'))
  assert.ok(slotBody.length > 0 && slotBody.length < 1800,
    `run SY: could not isolate slotRowHtml in ui.js (${slotBody.length} chars, measured 1277) — the asserts below would be measuring nothing`)
  assert.ok(/data-act="slot-delete"/.test(slotBody),
    'run SY: the save-slot row has no delete button — the only control that erases one profile is gone')
  // THE CLOUD MARK, AND THE SLOT IT IS KEYED ON. The ⚙ sheet states the fact once it is open;
  // this row is where a player CHOOSING a save meets it. The keying is the subtler half: `st.slot` is the SYNCED slot and
  // activeSlot() is the one being played, they are routinely different (that is the whole point of
  // a per-slot pairing), and swapping them puts a confident cloud on the wrong save.
  assert.ok(/icoCloud\(t\('Synced'\)\)/.test(slotBody),
    'run SY: the save-slot row no longer marks the synced save — nothing on the screen where a ' +
    'player CHOOSES a save says which one follows them between devices')
  assert.ok(/cloud = summary && st\.on && st\.slot === n/.test(slotBody) && !/activeSlot\(\) === n/.test(slotBody),
    'run SY: the cloud mark is no longer gated on `summary && st.on && st.slot === n`. Each ' +
    'clause is a different lie on screen: without `summary` an EMPTY row claims to sync, without ' +
    '`st.on` every row does, and keyed on activeSlot() rather than st.slot the mark lands on the ' +
    'slot being PLAYED — which is routinely not the one that syncs, since the pairing is per-slot')
  // An inline <svg> with no intrinsic size and no CSS rule lays out at 300x150 and takes the sheet
  // apart, so this is a blank-screen guard, not a styling one. Matched on a declaration the rule
  // OWNS (run BP.q4's reason: a bare selector test is satisfied by any later override).
  assert.ok(/\.slot-row-cloud \{[^}]*width:/.test(readFileSync(new URL('../src/styles.css', import.meta.url), 'utf8')),
    'run SY: .slot-row-cloud has no sizing rule — an inline svg with no intrinsic size renders at ' +
    '300x150 and blows the slots sheet apart')
  assert.ok(/onDeleteSlot\?\.\(/.test(u),
    'run SY: nothing in ui.js calls onDeleteSlot — the confirm sheet still opens and its Delete button does nothing')
  // NOT ON THE DESTINATION PICKER. That list asks WHERE THIS SAVE SHOULD GO; a delete glyph on it
  // erases a save from the one screen whose whole job is choosing somewhere to put one.
  assert.ok(/act: 'sync-pick', manage: false/.test(u),
    'run SY: the §5.3 destination picker renders the row-management glyphs — a delete button on ' +
    '"Where should this save go?" destroys a save from the screen that is asking where to put one')

  const del = m.slice(m.indexOf('onDeleteSlot(n) {'))
  const delBody = del.slice(0, del.indexOf('\n  },'))
  assert.ok(delBody.length > 0 && delBody.length < 600,
    'run SY: main.js has no onDeleteSlot hook — ui.js calls it optionally, so the button is inert with nothing thrown')
  // UNLINK FIRST, AND ONLY FOR THE SYNCED SLOT. With the blob gone `dirty` derives false, so
  // nothing is ever pushed and the cloud row survives holding the save — the next generation
  // another device writes reads as `pull`, adopts, and the save the player just deleted REAPPEARS
  // and reloads the page under them. Unlinking unconditionally is the opposite failure: erasing
  // slot 2 silently stops slot 1 syncing.
  assert.ok(/st\.on && st\.slot === n\) syncUnlink\(\)/.test(delBody),
    'run SY: onDeleteSlot no longer unlinks exactly when the slot it erases is the SYNCED one — ' +
    'either the deleted save comes back on the next pull, or an unrelated slot silently unlinks')
  // AND RELOAD, ONLY FOR THE SLOT BEING PLAYED. `meta` is live in main.js's closure and every later
  // saveMeta writes it straight back over the erase — deleting the save you are playing would
  // simply not happen, with the row redrawing empty until the next write puts it back.
  assert.ok(/n !== activeSlot\(\)\) return/.test(delBody),
    'run SY: onDeleteSlot no longer distinguishes the ACTIVE slot — it either reloads on every ' +
    'delete or on none, and on none the live meta is written straight back over the erase')
  assert.ok(/freezeSaves\(\)/.test(delBody) && /location\.reload\(\)/.test(delBody),
    'run SY: onDeleteSlot must freezeSaves() before location.reload() — a queued navigation does ' +
    'not stop script execution, and a stale handler rewrites the slot that was just erased')

  // (f) the service worker must never intercept the sync API. Cross-origin today, so the existing
  // origin check already covers it — this is the line that survives a custom-domain move.
  assert.ok(/pathname\.startsWith\('\/v1\/'\)/.test(sw),
    'run SY: public/sw.js does not skip /v1/ — on a custom domain the sync API becomes same-origin ' +
    'and starts being cached and replayed')

  console.log(`PASS run SY (sync wiring): isIdle reads run === null, all ${TRIGGERS.length} pull/push ` +
    `triggers present at their named sites, ui.js holds no protocol, the entry point carries no dev ` +
    `gate, the kill switch still removes every pixel, and the slots sheet's ` +
    `delete button unlinks the synced slot, reloads only the active one, stays off the ` +
    `destination picker, and the row marks the SYNCED slot with a sized cloud`)
}

// ---- Run ZY: the pairing code, and what the adopt path tolerates ------------------------------
function testSyncCode() {
  // (a) the alphabet is Crockford's, and it must equal the Worker's CODE_RE character class — the
  // one-fact-two-places trap, across a network boundary this time, where the symptom is a code the
  // player typed correctly being answered 401.
  const worker = readFileSync(new URL('../worker/src/index.js', import.meta.url), 'utf8')
  assert.ok(/\[0-9A-HJKMNP-TV-Z\]\{16\}/.test(worker),
    'run ZY: the Worker no longer validates a 16-char Crockford code — client and server disagree ' +
    'about what a code IS, and the failure is a 401 on a correctly typed code')

  // (b) 1000 minted codes are all 16 chars of that alphabet, and no character falls outside it.
  const seen = new Set()
  for (let i = 0; i < 1000; i++) {
    const c = newCode()
    assert.match(c, /^[0-9A-HJKMNP-TV-Z]{16}$/, `run ZY: minted a code outside the alphabet: ${c}`)
    seen.add(c)
  }
  assert.strictEqual(seen.size, 1000, 'run ZY: 1000 mints produced a collision — the entropy is not what it claims')

  // (c) THE CANONICALIZER IS WHY CROCKFORD WAS CHOSEN. Every one of these is a real thing a player
  // does when copying sixteen characters off another screen.
  const OK = 'A7K39WQM2FTXB4NE'
  const TABLE = [
    ['exact', 'A7K39WQM2FTXB4NE', OK],
    ['grouped', 'A7K3-9WQM-2FTX-B4NE', OK],
    ['lowercase', 'a7k39wqm2ftxb4ne', OK],
    ['spaces', 'A7K3 9WQM 2FTX B4NE', OK],
    ['I reads as 1', 'IIII9WQM2FTXB4NE', '11119WQM2FTXB4NE'],
    ['L reads as 1', 'LLLL9WQM2FTXB4NE', '11119WQM2FTXB4NE'],
    ['O reads as 0', 'OOOO9WQM2FTXB4NE', '00009WQM2FTXB4NE'],
    ['too short', 'A7K3', null],
    ['too long', OK + 'X', null],
    ['U is not remappable', 'UUUU9WQM2FTXB4NE', null],
    ['punctuation', 'A7K3/9WQM2FTXB4N!', null],
    ['empty', '', null],
    ['null', null, null],
  ]
  for (const [what, input, want] of TABLE) {
    assert.strictEqual(canonicalize(input), want,
      `run ZY: canonicalize(${JSON.stringify(input)}) [${what}] gave ${JSON.stringify(canonicalize(input))}, wanted ${JSON.stringify(want)}`)
  }

  // (d) U IS DELIBERATELY NOT REMAPPED and that is worth its own line, because "be generous about
  // what the player types" invites mapping it to something. Crockford omits U to avoid accidental
  // obscenity, not because it collides with another glyph — there is nothing to map it TO, and
  // inventing one would accept a code that is genuinely wrong.
  assert.strictEqual(canonicalize('UUUU9WQM2FTXB4NE'), null, 'run ZY: a typed U was accepted')

  // (e) the display grouping round-trips.
  assert.strictEqual(groupCode(OK), 'A7K3-9WQM-2FTX-B4NE')
  assert.strictEqual(canonicalize(groupCode(OK)), OK)

  // (f) PER-BOOK PROGRESSION LANDED AFTER THIS FEATURE WAS DESIGNED. importSlot validates `shop`
  // and `chapters` and knows nothing about `books`/`grants`, so a synced blob carrying them must
  // still import — loadMeta's own guard (run BP.ad) covers the shapes, but the ADOPT path deserves
  // its own assertion rather than inheriting one from a test about something else.
  const store = {}
  globalThis.localStorage = {
    getItem: (k) => store[k] ?? null,
    setItem: (k, v) => { store[k] = String(v) },
    removeItem: (k) => { delete store[k] },
  }
  const withBooks = JSON.stringify({
    schema: 1, coins: 5, shop: {}, chapters: {},
    books: { undertow: { coins: 40, shop: {}, choiceSlots: 2, unlocks: {} } },
    grants: { undertow: true },
  })
  assert.ok(importSlot(1, withBooks), 'run ZY: importSlot refused a blob carrying per-book progression')
  const back = JSON.parse(exportSlot(1))
  assert.strictEqual(back.books.undertow.coins, 40,
    'run ZY: a synced blob lost its Book 2 purse on import — books are additive and must survive verbatim')
  assert.strictEqual(back.grants.undertow, true, 'run ZY: a synced blob lost its unlock grants on import')

  console.log(`PASS run ZY (pairing code): 1000 mints all in Crockford's alphabet with no collision, ` +
    `${TABLE.length} canonicalizer cases including I/L->1 and O->0 with U correctly refused, ` +
    `and an adopted blob keeps its per-book purses`)
}

// ---- Run XU: every LITERAL string ui.js hands to t()/tt() has French ---------------------------
//
// THE HOLE run XX CANNOT SEE, and it has now shipped untranslated copy four separate times (two
// City enemies in v6.3, every weapon mod in v6.6.26, the whole elements redesign in v7.55, and the
// three creature names found in v7.120 by SHOOTING the French panel). run XX walks config TABLES
// reading name/desc/title one level deep — so copy that lives in a ui.js FUNCTION is exempt from it
// by construction, which is where every screen's own chrome lives. The cloud-sync sheet added 45
// such strings and the full suite stayed green over every one of them.
//
// The check is the other direction from run XX's: not "is this table covered" but "does every string
// this file actually asks to translate exist in the dictionary". Only LITERALS — `t(ch.name)` is a
// table value and run XX owns it.
//
// ⚠ COMMENTS ARE STRIPPED FIRST, load-bearing for the same reason run MB.a strips them: this file
// discusses its own copy in prose right beside the wiring, and a raw scan would collect sentences
// out of comments and demand French for them.
//
// ⚠⚠ AND THE STRIPPER MUST BE run UR's TWO-CLAUSE FORM, NOT run MB.a's. MB.a's is written for
// sim.js, which has no globs; this file has `import.meta.glob('./cast/*.png', …)`, and the `/*`
// inside that PATH opens a block comment for a naive scan. The first cut of run XU used MB.a's
// version and was therefore reading 2935 of ui.js's 4010 lines: 1075 lines blanked, and the 35
// literals in them — the whole save-slots sheet, the whole settings sheet, Play, Shop, Boosters,
// every leaderboard string — were never checked by the assert whose entire job is checking them.
// It still printed "all 124 literals resolve" and cleared its own floor of 100 by 24, which is
// precisely the shape CLAUDE.md warns about: a confident answer to a question it never asked.
// The guarded clause requires a delimiter before the `/*`, so a path inside a string cannot open
// one. CLAUDE.md names this exact trap against this exact file; run UR and run SY already carry it.
function testUiStringsTranslated() {
  const raw = readFileSync(new URL('../src/ui.js', import.meta.url), 'utf8')
  const code = raw
    .replace(/(^|[^:])\/\/[^\n]*/g, '$1 ')
    .replace(/(^|[\s(,;={[])\/\*[\s\S]*?\*\//g, '$1 ')

  // THE DENOMINATOR THAT ACTUALLY CATCHES A DESYNCED STRIPPER, and the one the first cut lacked.
  // A literal count cannot: 124 out of a possible 159 looks like a healthy number and reads as a
  // pass. Lines can — an eaten file loses them in bulk. Block comments legitimately consume ~115
  // lines here (4010 -> 3895, 97%), while the naive stripper left 73%.
  const rawLines = raw.split('\n').length
  const keptLines = code.split('\n').length
  assert.ok(keptLines >= rawLines * 0.9,
    `run XU: the comment stripper ate ${rawLines - keptLines} of ui.js's ${rawLines} lines (kept ` +
    `${Math.round((keptLines / rawLines) * 100)}%, floor 90%) — every t() in the blanked region is ` +
    `unchecked, and "nothing missing" below would be a scan that never read them`)

  const keys = new Set()
  for (const m of code.matchAll(/\btt?\(\s*'((?:\\.|[^'\\])*)'/g)) keys.add(m[1].replace(/\\'/g, "'"))
  for (const m of code.matchAll(/\btt?\(\s*"((?:\\.|[^"\\])*)"/g)) keys.add(m[1].replace(/\\"/g, '"'))

  // A FLOOR ON THE COUNT TOO, measured not guessed (159 today, was 124 while 1075 lines were
  // being blanked). The line check above is the sharper instrument; this one still catches a
  // stripper that eats a little rather than a lot, and a regex that stops matching t() entirely.
  assert.ok(keys.size >= 150,
    `run XU: only ${keys.size} t()/tt() literals found in ui.js against a floor of 150 — the comment ` +
    `stripper has desynced, so "nothing missing" below would be a scan that checked nothing`)

  const missing = [...keys].filter((k) => !(k in FR))
  assert.deepStrictEqual(missing, [],
    `run XU: ui.js asks t()/tt() to translate ${missing.length} string(s) with no fr.js entry, so they ` +
    `render in ENGLISH on a French screen with nothing thrown and no test red: ${JSON.stringify(missing)}`)

  // Placeholder parity, for the same reason run XX asserts it across the dictionary: a misspelt
  // {n} prints literal braces to the player and reads perfectly in review.
  const ph = (v) => [...String(v).matchAll(/\{(\w+)\}/g)].map((m) => m[1]).sort().join(',')
  const skew = [...keys].filter((k) => ph(k) !== ph(FR[k]))
  assert.deepStrictEqual(skew, [],
    `run XU: English and French disagree about placeholders — the French renders literal braces: ${JSON.stringify(skew)}`)

  console.log(`PASS run XU (ui.js copy is translated): all ${keys.size} t()/tt() literals in ui.js ` +
    `resolve to an fr.js entry, placeholders agree on every one`)
}

// ---- Run WW: v6.6.5 early spawn boost (owner directive) --------------------------------------
// "have early monsters (<1min in) spawn a bit faster". spawnRate is multiplied by spawnEarlyMul,
// which is 1 + SPAWN_EARLY_BOOST at t=0 and decays LINEARLY to exactly 1 at SPAWN_EARLY_UNTIL.
// The decay is the point: a flat boost that switched off at 60s would drop the spawn rate ~25%
// mid-fight, so the load-bearing assert here is that the rate never decreases anywhere — that is
// what a cliff at the boundary would break, and it is invisible to a spot check at t=0 and t=60.
function testEarlySpawnBoost() {
  // (a) the taper's shape, at both ends and the midpoint
  assert(Math.abs(spawnEarlyMul(0) - (1 + SPAWN_EARLY_BOOST)) < 1e-9, `expected full boost at t=0, got ${spawnEarlyMul(0)}`)
  assert(Math.abs(spawnEarlyMul(SPAWN_EARLY_UNTIL / 2) - (1 + SPAWN_EARLY_BOOST / 2)) < 1e-9, 'expected half the boost at the midpoint')
  assert.strictEqual(spawnEarlyMul(SPAWN_EARLY_UNTIL), 1, 'expected the boost to be spent exactly at SPAWN_EARLY_UNTIL')
  assert.strictEqual(spawnEarlyMul(SPAWN_EARLY_UNTIL + 30), 1, 'expected no boost after the window')

  // (b) NO CLIFF: the rate is strictly increasing across the whole early+mid game, so nothing
  // drops when the boost runs out. (A flat boost would step down ~25% at the 60s boundary.)
  let prev = -Infinity
  for (let t = 0; t <= 120; t += 0.25) {
    const r = spawnRate(t)
    assert(r >= prev - 1e-9, `expected spawnRate to never decrease, dropped at t=${t} (${prev} -> ${r})`)
    prev = r
  }
  const atBoundary = Math.abs(spawnRate(SPAWN_EARLY_UNTIL) - spawnRate(SPAWN_EARLY_UNTIL - 0.01))
  assert(atBoundary < 0.05, `expected a seamless boundary at t=${SPAWN_EARLY_UNTIL}, jumped ${atBoundary}`)

  // (c) it is faster than the unboosted curve inside the window, and identical outside it
  const plain = (t) => SPAWN_RATE_BASE + t * SPAWN_RATE_LINEAR
  for (const t of [0, 10, 30, 50]) assert(spawnRate(t) > plain(t), `expected a boost at t=${t}`)
  for (const t of [SPAWN_EARLY_UNTIL, 90, 120]) {
    assert(Math.abs(spawnRate(t) - plain(t)) < 1e-9, `expected the plain curve at t=${t}, got ${spawnRate(t)} vs ${plain(t)}`)
  }
  assert(spawnRate(300) >= 15, 'late-game curve must be untouched (Run I pins this too)')

  // (d) a real run actually lands more enemies in the first minute. Weapons stripped so nothing
  // dies and the count is pure arrivals; spawnMul forced to 1 so chapter easing is not the
  // variable under test, and the density cap neutralised so it cannot clip the comparison.
  const dt = 1 / 60
  const arrivalsInFirstMinute = (rateMul) => {
    Math.random = mulberry32(20260805)
    const run = createRun(makeMeta(), { chapter: 'city' })
    run.weapons = []
    run.mods.spawnMul = rateMul
    run.mods.maxAliveMul = 1
    run.player.hp = run.player.maxHP = 1e9
    for (let i = 0; i < Math.round(60 / dt); i++) {
      if (run.phase === 'levelup') { declineLevelUp(run); continue }
      if (run.phase !== 'playing') break
      stepSim(run, { x: 0, y: 0 }, dt)
      run.player.hp = run.player.maxHP
    }
    return run._nextId - 1
  }
  const boosted = arrivalsInFirstMinute(1)
  // the unboosted baseline, reconstructed by integrating the plain curve over the same window
  let plainExpected = 0
  for (let i = 0; i < Math.round(60 / dt); i++) plainExpected += plain(i * dt) * dt
  assert(boosted > plainExpected * 1.08,
    `expected the first minute to land meaningfully more enemies than the unboosted curve (plain ~${plainExpected.toFixed(0)}, got ${boosted})`)

  console.log(`PASS run WW (v6.6.5 early spawn boost): rate ${plain(0).toFixed(2)}->${spawnRate(0).toFixed(2)}/s at t=0, seamless at t=${SPAWN_EARLY_UNTIL}, first-minute arrivals ~${plainExpected.toFixed(0)} -> ${boosted}`)
}

// ---- Run WL: The Beyond's denser opening (LANE_EARLY_BOOST) -----------------------------------
// "33% more enemies at the start, but finish at the same rate." The lane has TWO spawners and the
// ranks are the majority of its early arrivals, so a boost wired into only one of them delivers
// roughly half the ask while every existing test still passes. Both halves are asserted as ARRIVAL
// COUNTS from a real run, split by source, against a baseline integrated from the shipped constants
// — not against eyeballed literals, so a retune of the boost moves the test with the config.
function testLaneOpening() {
  // (a) the taper's shape. The far end is the whole "finish at the same rate" half of the ask.
  assert(Math.abs(laneEarlyMul(0) - (1 + LANE_EARLY_BOOST)) < 1e-9, `expected the full boost at t=0, got ${laneEarlyMul(0)}`)
  assert(Math.abs(laneEarlyMul(LANE_EARLY_UNTIL / 2) - (1 + LANE_EARLY_BOOST / 2)) < 1e-9, 'expected half the boost at the midpoint')
  assert.strictEqual(laneEarlyMul(LANE_EARLY_UNTIL), 1, 'expected the boost spent exactly at LANE_EARLY_UNTIL')
  assert.strictEqual(laneEarlyMul(300), 1, 'the end of a run must be untouched — that is the constraint')

  const dt = 1 / 60
  const WINDOW = 30
  // Weapons stripped so nothing dies and the count is pure arrivals; the player is immortal so the
  // run cannot end early. Enemies are split by rosterId: the lane's `march` entries are the ranks
  // (stepFormations), everything else came through ordinary ring spawning (stepSpawning).
  const arrivals = (secs) => {
    Math.random = mulberry32(20260811)
    const run = createRun(makeMeta(), { chapter: 'beyond' })
    run.weapons = []
    run.player.hp = run.player.maxHP = 1e9
    const seen = new Set()
    let ring = 0, rank = 0
    for (let i = 0; i < Math.round(secs / dt); i++) {
      if (run.phase === 'levelup') { declineLevelUp(run); continue }
      if (run.phase !== 'playing') break
      stepSim(run, { x: 0, y: 0 }, dt)
      run.events.length = 0
      run.player.hp = run.player.maxHP
      for (const e of run.enemies) {
        if (seen.has(e.id)) continue
        seen.add(e.id)
        if (e.rosterId === 'invader' || e.rosterId === 'hulk') rank++; else ring++
      }
    }
    return { ring, rank }
  }
  const got = arrivals(WINDOW)

  // (b) THE RING STREAM. Baseline = the shipped curve integrated over the same window at the lane's
  // own rate, i.e. what stepSpawning would have delivered with laneEarlyMul dropped. The boost
  // averages 1+LANE_EARLY_BOOST*(1-WINDOW/2/LANE_EARLY_UNTIL) over this window, so demand most of
  // it; the opening credit and the elite cadence ride along on top and only ever help.
  let ringBase = 0
  for (let i = 0; i < Math.round(WINDOW / dt); i++) ringBase += spawnRate(i * dt) * LANE_SPAWN_MUL * dt
  const ringWant = 1 + LANE_EARLY_BOOST * (1 - WINDOW / 2 / LANE_EARLY_UNTIL) * 0.75
  assert(got.ring > ringBase * ringWant,
    `ring stream: expected the opening boost in stepSpawning (baseline ~${ringBase.toFixed(0)}, wanted > ${(ringBase * ringWant).toFixed(0)}, got ${got.ring})`)

  // (c) THE RANKS, which are the bigger half here and the one a rate multiplier alone cannot move:
  // stepFormations' row count is a rounded 1..3 and stays pinned at 1 this early whatever you
  // multiply it by. The boost has to reach the CADENCE. Baseline is exact — the formation timer is
  // pure dt accumulation with no RNG in it at all.
  const rankBase = Math.floor(WINDOW / FORMATION_INTERVAL) * FORMATION_COLS
  assert(got.rank > rankBase,
    `ranks: expected a compressed cadence in stepFormations (shipped cadence lands ${rankBase} in ${WINDOW}s, got ${got.rank}) — a spawn-RATE multiplier alone cannot do this`)

  // (d) SOURCE TRIPWIRE. Two call sites, and losing either is silent: the run still plays, every
  // other test still passes, and the chapter quietly delivers half the boost it advertises.
  const src = readFileSync(new URL('../src/sim.js', import.meta.url), 'utf8')
  assert.ok(src.includes('LANE_SPAWN_MUL * laneEarlyMul(run.time)'), 'stepSpawning must scale the ring stream by laneEarlyMul')
  assert.ok(src.includes('FORMATION_INTERVAL / laneEarlyMul(run.time)'), 'stepFormations must compress the rank cadence by laneEarlyMul')

  console.log(`PASS run WL (lane opening): first ${WINDOW}s of The Beyond — ring ${ringBase.toFixed(0)} -> ${got.ring}, ranks ${rankBase} -> ${got.rank}; boost spent at t=${LANE_EARLY_UNTIL}s`)
}

// ---- Run YY: forward compatibility — an OLDER build must not destroy a NEWER build's save -----
// Slice 0 of docs/superpowers/specs/2026-08-04-cross-device-save-sync-tech-strategy.md (§2.4/§2.5).
// Today a save only ever moves FORWARD through builds, so only backward compatibility mattered.
// Once saves sync between devices, an old bundle routinely reads a save a newer bundle wrote — the
// phone auto-updates, the laptop tab has been open since last week. Three rules, all asserted here:
//
//   R3  Widening a range is a breaking change. CLAMP ON USE, NEVER ON LOAD. loadMeta used to clamp
//       chapters[id].maxDifficulty to this build's ladder and choiceSlots to this build's ceiling,
//       and the very next saveMeta wrote those smaller numbers back — silent, permanent progression
//       loss. Both halves are pinned: what is STORED round-trips untouched, what is PLAYED still
//       respects this build's ranges.
//   R1  Validate table-backed pointers at the CONSUMER. meta.chapter is a pointer into CHAPTERS,
//       and loadMeta only defaults it when MISSING, so an id from a build that shipped a chapter
//       this one lacks reached CHAPTERS[id].balance in createRun and threw TypeError out of the
//       Play handler. The guard is at EVERY consumer — createRun, and main.js's onPlay/onDifficulty
//       through the shared resolveChapterId (config.js) — and never a repair in loadMeta: an old
//       build saves on every chapter switch, run end and purchase, so a load-time repair is written
//       straight back over the newer save.
//   R4  meta.schema exists and defaults. The comparison that REFUSES a newer save lands with
//       sync.js (slice 2); the field and the constant ship now, because a build already in the wild
//       without them can never be taught to refuse.
//
// This scenario stubs localStorage (plain node has none) and runs last, so its Math.random reseed
// cannot perturb any earlier scenario's stream.
// run ZZ — sync.js's pure core (design §6.2 decision table, §6.4 lost ACK) and state.js's four sync
// primitives. No network and no browser: sync.js keeps fetch/localStorage/crypto out of its module
// scope for exactly this reason, so the logic that decides whether to overwrite a save is testable.
// The tech strategy calls this "the slice to over-test" — every scenario below is a data-loss path
// the adversarial review found, not a happy path.
// run LB — the leaderboard (v7.x). Four blocks, and only the first is about scores.js's own logic;
// the other three are CROSS-FILE CONTRACTS, which is where every defect this feature can have
// actually lives. Nothing here touches the network: the module keeps fetch out of its module scope
// for the same reason sync.js does.
function testLeaderboard() {
  // (a) validNick — the one place that decides what a nickname IS. Effects, not state: each case
  // is a string a player can really type and the name that must come out the other side.
  assert.strictEqual(validNick('Bob'), 'Bob', 'the minimum length is accepted')
  assert.strictEqual(validNick('Bo'), null, `${NICK_MIN - 1} characters is refused`)
  assert.strictEqual(validNick('  Bob  '), 'Bob', 'surrounding whitespace is not part of the name')
  assert.strictEqual(validNick('   '), null, 'whitespace alone is not a name')
  assert.strictEqual(validNick('a'.repeat(30)), 'a'.repeat(NICK_MAX), 'an over-long name is clamped, not refused')
  assert.strictEqual(validNick('Big   Bob'), 'Big Bob', 'runs of whitespace collapse — two names that look identical on the podium must BE identical')
  assert.strictEqual(validNick(null), null, 'a non-string is not a name')
  assert.strictEqual(validNick(undefined), null, 'an absent nickname is not a name')
  // EVERY FIXTURE BELOW IS DERIVED FROM NICK_MAX, NEVER WRITTEN AS A LITERAL, and that is the whole
  // lesson of this block. Both of these traps depend on WHERE the cut lands, so a hand-written name
  // stops exercising them the moment the bound moves — silently, still green, still reading like a
  // guard. The emoji case had already done it once at NICK_MAX 10; raising it to 15 would have done
  // it to the space case too, and flipped the emoji case back.

  // THE CLAMP CAN CUT ON A SPACE, and the result is a name the Worker silently rewrites: it trims
  // before storing (it cannot trust a client), so the board would hold the trimmed name while
  // meta.nick held the padded one — and every use of the pair is a string comparison. Nothing
  // throws; the player just never sees their rank chip and never sees their own row highlighted.
  const cutOnSpace = 'a'.repeat(NICK_MAX - 1) + ' zzz'
  assert.strictEqual(cutOnSpace.slice(0, NICK_MAX).at(-1), ' ',
    'run LB: the cut-on-a-space fixture no longer ends on a space — it would pass with the final trim deleted')
  assert.strictEqual(validNick(cutOnSpace), 'a'.repeat(NICK_MAX - 1), 'the clamp must not leave the space it cut on')
  assert.strictEqual(validNick(validNick(cutOnSpace)), 'a'.repeat(NICK_MAX - 1), 'and the result is stable under a second pass')

  // The trap that only shows up on the podium: slice() cuts UTF-16 units, so clamping can bisect an
  // astral character and leave a lone surrogate, which renders as a replacement box and passes every
  // other check here. An emoji is two units, so the cut falls INSIDE a pair only when the units
  // before it are odd — pad by one when NICK_MAX is even, by none when it is odd.
  const oddPad = 'a'.repeat(NICK_MAX % 2 === 0 ? 1 : 0)
  const bisecting = oddPad + '🐛'.repeat(NICK_MAX)
  assert.ok(/\p{Cs}$/u.test(bisecting.slice(0, NICK_MAX)),
    `run LB: the emoji fixture no longer cuts inside a pair at NICK_MAX=${NICK_MAX} — it would pass with the surrogate repair deleted`)
  const clamped = validNick(bisecting)
  // \p{Cs} under the u flag matches only UNPAIRED surrogates — a whole emoji is one code point of
  // category So and does not match, which is the whole reason this is the right assertion. Testing
  // for any trailing surrogate instead fails on every legal emoji name.
  assert.ok(!/\p{Cs}/u.test(clamped), `clamping must not leave a lone surrogate: got ${JSON.stringify(clamped)}`)
  assert.strictEqual(clamped, oddPad + '🐛'.repeat((NICK_MAX - oddPad.length - 1) / 2),
    'the bisected emoji is dropped whole, not left as half of one')
  // And the other parity: a cut that lands cleanly between two pairs keeps every whole emoji.
  const evenPad = 'a'.repeat(NICK_MAX % 2)
  assert.strictEqual(validNick(evenPad + '🐛'.repeat(NICK_MAX)),
    evenPad + '🐛'.repeat((NICK_MAX - evenPad.length) / 2), 'an even split keeps every whole emoji')
  // A control character in a name would corrupt the row it is drawn in, and unlike the length rule
  // there is no visible sign the player pasted one. Built from a char code rather than typed inline,
  // so the byte survives whatever edits this file next.
  const bell = String.fromCharCode(7)
  assert.strictEqual(validNick('Bo' + bell + 'b'), 'Bob', 'control characters are stripped rather than rejected')
  assert.strictEqual(validNick('B' + bell + 'b'), null, 'and stripping one can take a name below the minimum')

  // (b) podiumRank — where a just-submitted run landed, read off the boards the POST answered with.
  const ANN = { nick: 'Ann', kills: 900, level: 20, timeMs: 240000 }
  const BOB = { nick: 'Bob', kills: 500, level: 12, timeMs: 180000 }
  const boards = { kills: [ANN, BOB], level: [BOB, ANN], time: [BOB, ANN] }
  assert.deepStrictEqual(podiumRank(boards, { nick: 'Bob', kills: 500, level: 12 }), { kills: 2, level: 1, time: null },
    'a run on both boards reports both ranks, and they are allowed to differ')
  assert.strictEqual(podiumRank(boards, { nick: 'Cid', kills: 10, level: 2 }), null, 'a run on neither board reports nothing at all')
  assert.strictEqual(podiumRank(null, { nick: 'Bob', kills: 500, level: 12 }), null, 'an unreachable board is not a rank of null-th')
  assert.deepStrictEqual(podiumRank({ kills: [ANN], level: [], time: [] }, { nick: 'Ann', kills: 900, level: 20 }),
    { kills: 1, level: null, time: null }, 'one board without the other is still a result')

  // THE BOSS BOARD. A run that carries a kill time is ranked on it; one that does not must not be,
  // and `timeMs` defaulting to undefined is the whole reason that needs an assertion — findIndex on
  // a row whose own timeMs is null would MATCH a null lookup and hand an ordinary chapter's run a
  // place on a board it never entered.
  assert.deepStrictEqual(podiumRank(boards, { nick: 'Bob', kills: 500, level: 12, timeMs: 180000 }),
    { kills: 2, level: 1, time: 1 }, 'a boss run reports its place on the time board too')
  assert.strictEqual(podiumRank({ kills: [], level: [], time: [{ nick: 'Ann', kills: 1, level: 1, timeMs: null }] },
    { nick: 'Ann', kills: 1, level: 1 }), null,
    'a run with no kill time holds no place on the time board, even against a row whose own time is null')
  // The Worker deploys separately from the game, so between shipping the client and deploying it
  // every response lacks the key. The podium must degrade to "no boss scores", not to a crash.
  assert.deepStrictEqual(podiumRank({ kills: [ANN], level: [] }, { nick: 'Ann', kills: 900, level: 20, timeMs: 240000 }),
    { kills: 1, level: null, time: null }, 'a board response with no time key at all is still readable')

  // (c) THE INTEGRITY RULE, ACROSS TWO FILES. The owner's only anti-cheat ruling is "dev runs don't
  // count", and it is implemented as one write in sim.js and one read in main.js. Nothing imports
  // the other, nothing throws if either half goes, and the symptom is a podium quietly full of
  // dev-menu scores — so it is asserted as source text, the trick run UG.k uses.
  const simSrc = readFileSync(new URL('../src/sim.js', import.meta.url), 'utf8')
  const devTakeBody = /export function devTake\([\s\S]*?\n}/.exec(simSrc)?.[0]
  assert.ok(devTakeBody, 'run LB could not find devTake in sim.js — the regex has gone stale')
  assert.ok(/run\._devUsed\s*=\s*true/.test(devTakeBody),
    'devTake must mark the run: it is the ONLY path by which a dev-menu card reaches a run, and the leaderboard gate reads nothing else')
  const mainSrc2 = readFileSync(new URL('../src/main.js', import.meta.url), 'utf8')
  const endRunBody = /function endRun\([\s\S]*?\n}\n/.exec(mainSrc2)?.[0]
  assert.ok(endRunBody, 'run LB could not find endRun in main.js — the regex has gone stale')
  assert.ok(/submitScore\(/.test(endRunBody), 'endRun is where a run is submitted; nothing else ends a run')
  assert.ok(/!run\._devUsed/.test(endRunBody),
    'endRun must refuse to submit a run that used the dev menu — without this the flag sim.js sets is dead code and the ruling is unimplemented')
  // The OTHER half, and the one that was missing until 2026-08-19: meta.dev — the title's DEV
  // toggle — unlocks WIP chapters, and a run played under it submitted to the public board like any
  // other. Two dev switches, two answers to "is this a dev run". Asserted here rather than trusted
  // because it is one `&&` term whose deletion changes nothing a player or a test can see.
  assert.ok(/!meta\.dev/.test(endRunBody),
    'endRun must refuse to submit a run played with the title DEV toggle on — that toggle is what unlocks WIP chapters, and it put a real dev score on the live board once')

  // ...and the reason the two are not redundant is that the dev CARD LIST is now reachable only
  // while meta.dev is on. If the HUD badge ever grows its own gesture back, the card list becomes a
  // second dev switch again and the run flag above is load-bearing on its own. This asserts the
  // gate, not the absence of a gesture: a burst counter that still ends in a meta.dev test is fine.
  const uiSrc2 = readFileSync(new URL('../src/ui.js', import.meta.url), 'utf8')
  const devTapCase = /case 'dev-tap':[\s\S]*?\n      case /.exec(uiSrc2)?.[0]
  assert.ok(devTapCase, "run LB could not find the 'dev-tap' case in ui.js — the regex has gone stale")
  assert.ok(/meta\.dev/.test(devTapCase),
    "the HUD coin badge must open the dev card list only while meta.dev is on — an independent gesture here is a second dev switch, which is the bug this rule exists for")
  assert.ok(/validNick\(meta\.nick\)/.test(endRunBody),
    'endRun must resolve the nickname through validNick, not send meta.nick raw: that is the only path that could put an illegal name on a public board')

  // THE TIME BOARD'S OWN INTEGRITY RULE, and it is the one that fails LOUDLY WRONG rather than
  // silently absent: the boss board sorts SHORTEST FIRST, so a submitted time that did not come
  // from a kill takes first place off everyone who actually killed the thing. Both terms are one
  // `&&` away from gone and neither leaves a mark anywhere else — a lost run submits a real number,
  // and an ordinary chapter submits its 300s survival clock, so the board just fills with nonsense.
  // v7.x: the term is now HOISTED to a `const timeMs` above the entry literal, because a circuit
  // chapter submits a different clock entirely and the expression stopped fitting on the property
  // line. Only the two gates below are this scenario's business; the circuit arm has its own
  // evaluated proof in run RK.c.
  const timeExpr = /const timeMs = ([\s\S]*?)\n\s*const entry = \{/.exec(endRunBody)?.[1]
  assert.ok(timeExpr, 'run LB could not find the timeMs term in endRun — the leaderboard no longer submits a kill time')
  assert.ok(/\bvictory\b/.test(timeExpr),
    'the kill time must be gated on victory: on a shortest-wins board a death at 12s outranks every real kill')
  assert.ok(/scripted/.test(timeExpr),
    'the kill time must be gated on CHAPTERS[].scripted: an ordinary chapter ends on the same 300s clock for everyone, so its time board would rank whoever died first')

  // THE STARTER, WHICH IS RECORDED BUT NEVER RANKED (owner, 2026-08-19: display the weapon the
  // player got for the run). Two halves that fail in opposite directions and neither throws: sent
  // for a chapter whose starter is FIXED it is a column of one repeated answer, and read off
  // weapons[0] instead of the published field it is an ordering accident one weapon-dropping
  // mechanic away from crediting a public record to the wrong weapon.
  const starterExpr = /starter:\s*([^\n]*)/.exec(endRunBody)?.[1]
  assert.ok(starterExpr, 'run LB could not find the starter term in endRun — the podium no longer records which weapon a run began on')
  assert.ok(/Array\.isArray/.test(starterExpr),
    'the starter must be sent only where the chapter ROLLS it — Array.isArray is the same test createRun rolls on, and anything else is a second answer to which chapters those are')
  assert.ok(/run\.starterId/.test(starterExpr),
    'the starter must come from run.starterId, not run.weapons[0]: index 0 is an ordering accident, and the first mechanic that drops or re-sorts a weapon would credit the record to the wrong one')
  // The publish itself, asserted by CALLING createRun rather than by reading it — source text
  // cannot tell `starterId,` (the property) from `id: starterId,` (the weapons literal), and a
  // check that cannot tell those apart passes with the property deleted. Proven: that exact
  // mutation survived the text version of this line.
  //
  // 40 runs, not one: the point of the field on a rolled chapter is that it tracks THE ROLL, and a
  // single run agrees with a hardcoded first-element read by luck 1 time in 23.
  const rolledSeen = new Set()
  for (let i = 0; i < 40; i++) {
    const r = createRun(makeMeta(), { chapter: 'blank', difficulty: 1 })
    assert.ok(typeof r.starterId === 'string' && r.starterId.length > 0,
      'createRun must publish run.starterId — without it endRun submits undefined and every row records no weapon at all')
    assert.ok(CHAPTERS.blank.starter.includes(r.starterId), `run.starterId is not from the chapter's own pool: ${r.starterId}`)
    assert.strictEqual(r.weapons[0].id, r.starterId, 'the published id must be the weapon the run actually holds, not a second roll')
    rolledSeen.add(r.starterId)
  }
  assert.ok(rolledSeen.size > 1,
    `run.starterId never varied over 40 runs of a chapter with ${CHAPTERS.blank.starter.length} starters — it is not tracking the roll`)
  // ...and a chapter whose starter is a plain string publishes that, so the field is never undefined.
  const fixed = createRun(makeMeta(), { chapter: 'city', difficulty: 1 })
  assert.strictEqual(fixed.starterId, CHAPTERS.city.starter,
    'a fixed-starter chapter must publish its own starter, not undefined — main.js is what decides the field is not SENT there')

  // ...and the other side of that flag, in ui.js: the recto has to CHOOSE the time board for a
  // scripted chapter. Source text, because the alternative is a boss podium that still shows a
  // level board — correct-looking, fully populated, and not the board the scores are being kept on.
  assert.ok(/scripted \? 'time' : 'level'/.test(uiSrc2),
    "ui.js must pick the time board for a scripted chapter — without it the kill times are submitted, stored and never drawn")
  // Drawn off the ROW, not off the chapter: a board where every run began on the same weapon would
  // otherwise print one glyph three times, which is the whole reason main.js sends null there.
  assert.ok(/r\.starter \?/.test(uiSrc2),
    'the podium row must draw the weapon only when the row carries one — a chapter test here would print the same glyph on every row of a fixed-starter board')
  // The RULE, not the substring: a selector renamed to .podium-figure-unused still CONTAINS
  // '.podium-figure', and renaming the rule out from under the markup is exactly what breaking
  // this looks like. That mutation survived the substring version of this line.
  assert.ok(/class="podium-figure"/.test(uiSrc2),
    'the podium row must wrap its figure and its weapon in .podium-figure')
  assert.ok(/\.podium-figure\s*\{/.test(readFileSync(new URL('../src/styles.css', import.meta.url), 'utf8')),
    'styles.css must carry the .podium-figure rule — without it the two stack and every row grows a third line, which is what pushes the bookcase past its scroll box')

  // (d) THE FRENCH. Every leaderboard string lives in ui.js, in a function — which run XX's coverage
  // walk cannot see BY CONSTRUCTION, since it enumerates config TABLES. CLAUDE.md records that
  // exemption shipping untranslated copy four separate times; this list is the guard for this
  // feature's share of it. Checked in BOTH directions, so a string deleted from ui.js fails here
  // too rather than leaving a dead dictionary entry nobody notices.
  const uiSrc = readFileSync(new URL('../src/ui.js', import.meta.url), 'utf8')
  const leaderboardCopy = [
    'Podium', 'Nickname', 'Pick a nickname', 'Your nickname',
    'Other players see this name on the podium.',
    '{min}-{max} characters',
    'all players · difficulty {n}',
    'No scores yet — be the first.',
    'Could not reach the podium. Tap to try again.',
    'Best time',
  ]
  for (const key of leaderboardCopy) {
    assert.ok(FR[key], `leaderboard string has no French: ${JSON.stringify(key)}`)
    assert.ok(uiSrc.includes(key), `run LB's copy list is stale — ui.js no longer contains ${JSON.stringify(key)}`)
  }
  // Placeholder parity, the failure that reads perfectly in review: a misspelt {min} prints literal
  // braces at the player. run XX asserts this across the dictionary; it is repeated here because
  // this is the only tt() template the feature has and it is the one that would carry the typo.
  for (const ph of ['{min}', '{max}']) {
    assert.ok(FR['{min}-{max} characters'].includes(ph),
      `the French for the nickname rule drops ${ph} — the player would see the placeholder, not the number`)
  }

  // (e) THE RANGE, ACROSS THE NETWORK. scores.js clamps and the Worker refuses; if the two numbers
  // ever disagree the client offers a name the server then rejects, and the score vanishes with no
  // error anywhere. The Worker is not importable here (it is a Workers module), so read it as text.
  const workerSrc = readFileSync(new URL('../worker/src/index.js', import.meta.url), 'utf8')
  const workerMin = Number(/const NICK_MIN = (\d+)/.exec(workerSrc)?.[1])
  const workerMax = Number(/const NICK_MAX = (\d+)/.exec(workerSrc)?.[1])
  assert.strictEqual(workerMin, NICK_MIN, "the Worker's NICK_MIN must match scores.js's, or the client offers names the server refuses")
  assert.strictEqual(workerMax, NICK_MAX, "the Worker's NICK_MAX must match scores.js's")
  assert.ok(/pathname === '\/scores'/.test(workerSrc) && workerSrc.indexOf("pathname === '/scores'") < workerSrc.indexOf('normalizeCode(req.headers'),
    'the /scores route must be handled BEFORE the save-sync code check, or every anonymous board read is answered 401')
  // EVERY REAL CHAPTER ID must satisfy the Worker's shape check. The Worker is deliberately
  // ignorant of chapter ids so it never needs a deploy when one is added — which is exactly why
  // nothing on that side can catch an id it happens to refuse. A future `sea_floor` or a 17th
  // character would 400 every submit AND every read for that chapter alone, silently, and the
  // podium would simply be empty there forever. Object.keys(CHAPTERS), not CHAPTER_ORDER: that one
  // is book 1 only and would skip the nine chapters most likely to be new.
  // The Worker's own literal, lifted out of its source and re-run here — not a copy of it, which
  // would be the two-places-one-fact trap this whole scenario exists to close.
  // THE TIME BOARD ACROSS THE NETWORK, all four places it has to agree. Every one of these fails
  // as an empty or a wrong board rather than an error: a DESC ordering silently ranks the SLOWEST
  // kill first, a missing IS NOT NULL puts every ordinary chapter's null-timed row above every real
  // one, and a column the schema never declares takes the whole endpoint to a 500 the client
  // reports as "could not reach the podium".
  assert.ok(/time_ms IS NOT NULL ORDER BY time_ms ASC, at ASC/.test(workerSrc),
    'the Worker must read the time board ASC and skip null times — DESC ranks the slowest kill first, and without the filter the podium is three players who never killed it')
  assert.ok(/INSERT INTO scores \([^)]*time_ms[^)]*\)/.test(workerSrc),
    'the Worker must store time_ms, or every submitted kill time is dropped and the board stays empty forever')
  const schemaSrc = readFileSync(new URL('../worker/schema.sql', import.meta.url), 'utf8')
  assert.ok(/time_ms\s+INTEGER(?!\s+NOT NULL)/.test(schemaSrc),
    'schema.sql must declare time_ms NULLABLE: an ordinary chapter and a lost boss run both store null there')
  assert.ok(/CREATE INDEX[^\n]*scores_time[^\n]*time_ms ASC, at ASC/.test(schemaSrc),
    "schema.sql must index the time board's whole ORDER BY — without the trailing `at` SQLite materialises every row for that chapter and sorts")
  // The migration is what carries the LIVE database across, and the live database is the only one
  // that matters here: schema.sql's CREATE TABLE is a no-op against a table that already exists, so
  // without this file the deployed board would 500 on every read with nothing local to show it.
  const migrateSrc = readFileSync(new URL('../worker/migrate-scores-time.sql', import.meta.url), 'utf8')
  assert.ok(/ALTER TABLE scores ADD COLUMN time_ms INTEGER/.test(migrateSrc),
    'the one-shot migration must add time_ms to an existing scores table')

  assert.ok(/INSERT INTO scores \([^)]*starter[^)]*\)/.test(workerSrc),
    'the Worker must store the starter, or every row records no weapon and the column is decorative')
  assert.ok(/SELECT[^']*starter/.test(workerSrc),
    'the Worker must read the starter back — stored and never selected is the same to a player as never stored')
  assert.ok(/starter\s+TEXT(?!\s+NOT NULL)/.test(schemaSrc),
    'schema.sql must declare starter NULLABLE: every fixed-starter chapter and every older row stores null there')
  const migrateStarter = readFileSync(new URL('../worker/migrate-scores-starter.sql', import.meta.url), 'utf8')
  assert.ok(/ALTER TABLE scores ADD COLUMN starter TEXT/.test(migrateStarter),
    'the one-shot migration must add starter to an existing scores table')

  // EVERY WEAPON ID must satisfy the Worker's shape check, for exactly the reason every chapter id
  // must satisfy validChapter: the Worker is deliberately ignorant of game ids, so nothing on that
  // side can catch one it happens to refuse. A future id with a digit first or an underscore would
  // be dropped from every row on that chapter, and the podium would simply never show a weapon
  // there — no error, no red, and the score itself still landing so nobody has a reason to look.
  // The Worker's own literal, lifted and re-run, not a copy of it.
  const idLiteral = /const validId[^\n]*?(\/\^[^\n/]+\$\/)/.exec(workerSrc)?.[1]
  assert.ok(idLiteral, "run LB could not lift validId's pattern out of the Worker — the regex has gone stale")
  const idRe = new RegExp(idLiteral.slice(1, -1))
  const weaponIds = Object.keys(WEAPONS)
  const refusedIds = weaponIds.filter((id) => !idRe.test(id))
  assert.ok(weaponIds.length >= 30, `expected the whole weapon table, got ${weaponIds.length}`)
  assert.deepStrictEqual(refusedIds, [],
    `weapon id(s) the Worker's validId would drop: [${refusedIds.join(', ')}] — a run starting on one ` +
    `records no weapon on the podium, with the score itself landing normally so nothing looks wrong`)
  // And the rolled pool specifically, since that is the only set that can currently reach the column.
  const rolled = Object.values(CHAPTERS).flatMap((c) => (Array.isArray(c.starter) ? c.starter : []))
  assert.ok(rolled.length > 0, 'no chapter rolls its starter any more — this whole column has no source')
  for (const id of rolled) assert.ok(WEAPONS[id], `a rolled starter resolves to no weapon: ${id}`)

  const chapterLiteral = /const validChapter[^\n]*?(\/\^[^\n/]+\$\/)/.exec(workerSrc)?.[1]
  assert.ok(chapterLiteral, "run LB could not lift validChapter's pattern out of the Worker — the regex has gone stale")
  const chapterRe = new RegExp(chapterLiteral.slice(1, -1))
  const allChapterIds = Object.keys(CHAPTERS)
  const refused = allChapterIds.filter((id) => !chapterRe.test(id))
  assert.ok(allChapterIds.length >= 15, `expected the whole chapter table, got ${allChapterIds.length}`)
  assert.deepStrictEqual(refused, [],
    `chapter id(s) the Worker's validChapter would refuse: [${refused.join(', ')}] — every submit and every ` +
    `board read for those chapters 400s, and the podium is empty there with no error anywhere`)

  // (f) meta.nick is additive (R2) and defaults EMPTY on both paths — the fresh literal and
  // loadMeta's repair. '' is load-bearing: it is what fires the mandatory first-load prompt, so a
  // repair that helpfully invented a placeholder would disable the whole flow with nothing failing.
  // Read as source text rather than by calling loadMeta, which needs a localStorage this scenario
  // has no business stubbing (run ZZ owns that, and its stub must stay the last thing installed).
  const stateSrc = readFileSync(new URL('../src/state.js', import.meta.url), 'utf8')
  assert.ok(/m\.nick \?\?= ''/.test(stateSrc),
    "loadMeta must repair a missing meta.nick to '' — an older save has no such key and every reader would get undefined")
  assert.ok(/nick: '',/.test(stateSrc),
    "the fresh-meta literal must carry nick: '' — loadMeta's repairs are in-memory only and never written back")

  console.log(`PASS run LB (leaderboard): validNick holds ${NICK_MIN}-${NICK_MAX} through whitespace, a cut-on-a-space clamp and a bisected emoji, ` +
    `podiumRank reads all three boards independently, the kill time is gated on victory AND a scripted chapter on both sides, ` +
    `the rolled starter is published, submitted only where it is rolled and drawn off the row (${rolled.length} rollable, all ${weaponIds.length} weapon ids survive the Worker's shape check), ` +
    `both halves of the dev-run gate are wired across sim.js + ui.js + main.js, ` +
    `${leaderboardCopy.length} strings have French with placeholders intact, and the Worker's range, route order ` +
    `and chapter pattern agree with the client across all ${allChapterIds.length} chapters`)
}

function testSyncDecisions() {
  const KEY = 'charming-anomaly-save-v1'
  const store = new Map()
  globalThis.localStorage = {
    getItem: (k) => (store.has(k) ? store.get(k) : null),
    setItem: (k, v) => store.set(k, String(v)),
    removeItem: (k) => store.delete(k),
  }
  const validBlob = (coins) => JSON.stringify({ coins, runs: 0, shop: {}, best: { time: 0, kills: 0 }, chapters: {} })

  // (a) THE DECISION TABLE, all five rows, exhaustively over both dirty values.
  const D = (dirty, cloudGen, baseGen) => decide({ dirty, cloudGen, baseGen }).action
  assert.strictEqual(D(false, 5, 5), 'nothing', 'clean and level: the common case does nothing')
  assert.strictEqual(D(false, 6, 5), 'pull', 'clean and behind: adopt the cloud')
  assert.strictEqual(D(true, 5, 5), 'push', 'dirty and level: fast-forward')
  assert.strictEqual(D(true, 6, 5), 'conflict', 'dirty and behind: both moved from a common ancestor')
  // The row an earlier draft had as `push`. It cannot be: the server writes
  // `UPDATE .. WHERE gen = ?` with ? = baseGen, so a row BELOW baseGen can never match — the row
  // only counts up. That is 409 -> conflict prompt on every trigger, forever, and it is reachable
  // with no database restore (a 404 outside pairing pushes at baseGen 0, so a recreated row sits at
  // gen 1 while the other device holds 12). Every wedge is a modal inviting an overwrite.
  const resync = decide({ dirty: false, cloudGen: 1, baseGen: 12 })
  assert.strictEqual(resync.resynced, true, 'a cloud gen below baseGen is a desynchronisation, not a decision')
  assert.strictEqual(resync.baseGen, 1, 'resync adopts the server gen unconditionally')
  assert.strictEqual(resync.action, 'nothing', 'and re-runs the table, landing on nothing when clean')
  assert.strictEqual(decide({ dirty: true, cloudGen: 1, baseGen: 12 }).action, 'push',
    'and on push when dirty — never on a conflict prompt')
  console.log('PASS run ZZ.a (decision table): all five rows, and a cloud gen below baseGen resyncs instead of wedging on conflict')

  // (b) DERIVED dirty. The hash is asked of the DISK, which is what makes the three silent-loss
  // paths impossible: a save landing mid-push, two tabs with no compare-and-swap, and an old cached
  // bundle that has no hook at all. None of those can cooperate with a writer-set boolean.
  setActiveSlot(1)
  store.set(KEY, validBlob(10))
  const rec = { code: 'ABCDEFGHJKMNPQRS', slot: 1, device: 'devA', gen: 3, syncedHash: hash(validBlob(10)), reqId: 'r1' }
  assert.strictEqual(deriveDirty(rec), false, 'disk matching the last pushed blob is clean')
  store.set(KEY, validBlob(20)) // a save lands — no hook fired, nothing told sync anything
  assert.strictEqual(deriveDirty(rec), true, 'a write that announced nothing is still detected, because the disk is the source')
  assert.strictEqual(deriveDirty(null), false, 'no record means nothing to compare')
  store.delete(KEY)
  assert.strictEqual(deriveDirty(rec), false, 'an empty slot has nothing to push')
  assert.notStrictEqual(hash(validBlob(10)), hash(validBlob(20)), 'the hash must actually distinguish two saves')
  assert.strictEqual(hash(validBlob(10)), hash(validBlob(10)), 'and be stable for identical bytes')
  console.log('PASS run ZZ.b (derived dirty): a save that announced nothing is still seen, because the hash asks the disk not the writer')

  // (c) THE LOST ACK (§6.4). Keyed on reqId, never a timestamp — an earlier draft compared savedAt
  // against a stored sentAt and broke both ways: any save between the lost push and the retry made
  // the rule stop firing (prompting the player against their OWN older save), and a clock stepping
  // backwards made it fire wrongly (silently dropping the pending blob).
  const mine = { device: 'devA', reqId: 'req-1' }
  assert.strictEqual(isOwnLostAck({ device: 'devA', reqId: 'req-1' }, mine), true, 'same device AND same reqId is our own lost ACK')
  assert.strictEqual(isOwnLostAck({ device: 'devB', reqId: 'req-1' }, mine), false, 'another device is a real conflict')
  assert.strictEqual(isOwnLostAck({ device: 'devA', reqId: 'req-2' }, mine), false, 'our device but a different push is a real conflict')
  assert.strictEqual(isOwnLostAck({ device: 'devA', reqId: '' }, { device: 'devA', reqId: '' }), false,
    'two empty reqIds must not match each other into a false "our own ACK"')
  assert.strictEqual(isOwnLostAck(null, mine), false, 'no server row is not our ACK')
  console.log('PASS run ZZ.c (lost ACK): matched on device AND reqId, and an empty reqId never self-matches')

  // (d) THE SCHEMA GATE (R4). Refuse a blob from a build whose save format this one cannot read.
  assert.strictEqual(schemaOk(JSON.stringify({ schema: SCHEMA })), true, 'our own format is adoptable')
  assert.strictEqual(schemaOk(JSON.stringify({ coins: 1 })), true, 'no field means the writer predated it — format 1')
  assert.strictEqual(schemaOk(JSON.stringify({ schema: SCHEMA + 1 })), false, 'a newer format is refused, not guessed at')
  assert.strictEqual(schemaOk(null), true, 'a tombstone carries no format')
  assert.strictEqual(schemaOk('not json'), false, 'an unparseable blob is refused')
  console.log(`PASS run ZZ.d (schema gate): SCHEMA=${SCHEMA} adopts, ${SCHEMA + 1} refuses, a missing field reads as 1`)

  // (e) importSlot VALIDATES SHAPE, NOT SYNTAX. This is the assertion the whole function exists for:
  // every blob below is valid JSON, and every one of them makes loadMeta fall into its
  // `catch { /* corrupted save -> fresh */ }` and hand the player a FRESH SAVE — their slot gone.
  // The mechanism is `for (const id of Object.keys(SHOP)) …` throwing when `shop` is absent or not
  // an object. Reachable with no attacker: a truncated response body, or a future build's shape.
  store.set(KEY, validBlob(99))
  for (const bad of ['{}', 'null', '[]', '{"coins":5,"chapters":{}}', '{"coins":5,"shop":"x","chapters":{}}',
                     '{"coins":5,"shop":[],"chapters":{}}', '{"coins":5,"shop":{},"chapters":"zzz"}',
                     '{"coins":5,"shop":{},"chapters":[]}', 'not json at all']) {
    assert.strictEqual(importSlot(1, bad), false, `importSlot must refuse ${bad} — loadMeta would wipe the slot on it`)
  }
  assert.strictEqual(exportSlot(1), validBlob(99), 'and every refusal must leave the slot on disk untouched')
  assert.strictEqual(importSlot(1, validBlob(42)), true, 'a well-shaped blob is accepted')
  assert.strictEqual(exportSlot(1), validBlob(42), 'and written verbatim — the bytes are what we promised')
  assert.strictEqual(exportSlot(99), null, 'an unwritten slot exports null rather than throwing')
  console.log('PASS run ZZ.e (importSlot shape validation): 9 valid-JSON blobs that would each wipe the slot are refused, disk untouched')

  // (f) THE FREEZE LATCH (§3.3) AND THE SAVE HOOK (§3.2). location.reload() queues a navigation but
  // does not stop script execution, and this repo has no unload handler — so without the latch the
  // carousel's own 130ms setTimeout writes the PRE-ADOPT save back over the blob just adopted, and
  // then announces that write to sync.
  let announced = []
  setSaveHook((slot) => announced.push(slot))
  setActiveSlot(1)
  store.set(KEY, validBlob(7))
  const live = loadMeta()
  live.coins = 123
  saveMeta(live)
  assert.deepStrictEqual(announced, [1], 'a successful save announces its SLOT NUMBER, so sync never learns the key shape')
  assert.strictEqual(JSON.parse(exportSlot(1)).coins, 123, 'and the save actually landed')

  // A hook that throws must not escape: saveMeta runs inside the Pixi ticker via endRun, and Pixi
  // does not catch listener exceptions — a throwing hook would take down the frame loop in the one
  // path that has just banked a run's coins.
  setSaveHook(() => { throw new Error('sync exploded') })
  live.coins = 456
  assert.doesNotThrow(() => saveMeta(live), 'a throwing sync hook must never reach the caller')
  assert.strictEqual(JSON.parse(exportSlot(1)).coins, 456, 'and the save still lands despite the hook throwing')

  // The latch is one-way and there is no unlatch: the only exit is the reload already on its way.
  announced = []
  setSaveHook((slot) => announced.push(slot))
  freezeSaves()
  live.coins = 999
  saveMeta(live)
  assert.strictEqual(JSON.parse(exportSlot(1)).coins, 456, 'after freezeSaves a stale handler cannot overwrite the adopted blob')
  assert.deepStrictEqual(announced, [], 'and a frozen save announces nothing, so it cannot be pushed either')
  setSaveHook(null)
  console.log('PASS run ZZ.f (freeze latch + save hook): the hook reports a slot number, survives a throw, and freezeSaves stops both the write and the announcement')

  // (g) THE RECORD lives under its OWN key and never collides with a save slot.
  assert.notStrictEqual(RECORD_KEY, KEY, 'the sync record must not share the save key')
  assert(!RECORD_KEY.startsWith(`${KEY}:`), 'nor look like a save slot')
  assert.strictEqual(readRecord(), null, 'no record reads as null, not as a throw')
  writeRecord({ code: 'ABCDEFGHJKMNPQRS', slot: 1, device: 'devA', gen: 4, syncedHash: 'deadbeef', reqId: 'r9' })
  assert.strictEqual(readRecord().gen, 4, 'a written record round-trips')
  store.set(RECORD_KEY, '{"nope":true}')
  assert.strictEqual(readRecord(), null, 'a record without a code is treated as absent, never half-trusted')
  store.set(RECORD_KEY, 'not json')
  assert.strictEqual(readRecord(), null, 'and an unparseable record does not throw on boot')
  console.log('PASS run ZZ.g (sync record): its own key, and a malformed record reads as absent rather than throwing at boot')

  // (h) THE SUITE MUST NEVER LEAVE A HOOK INSTALLED (§3.1/§11). Five scenarios in this file call
  // saveMeta against a succeeding setItem stub, so the moment anything installs a hook at module
  // scope the suite starts firing it — and sync.js's hook would attempt a real network request.
  let leaked = false
  setSaveHook(() => { leaked = true })
  setSaveHook(null)
  saveMeta(live)
  assert.strictEqual(leaked, false, 'setSaveHook(null) must fully uninstall — a test suite that quietly talks to the internet is worse than one that fails')
  console.log('PASS run ZZ.h (no leaked hook): setSaveHook(null) uninstalls, so npm test can never fire a real sync request')

  // (i) ERASING ONE SLOT (the slots sheet's delete button). resetSave cannot do this job and the
  // way it fails is silent: it writes through `boundKey`, the key loadMeta actually READ, so it
  // only ever erases the slot being played. Pointed at row 3 from row 1 it erases ROW 1, leaves
  // row 3 on disk, and reports true — a delete button that destroys the wrong save.
  store.clear()
  setActiveSlot(1)
  store.set(KEY, validBlob(11))
  store.set(`${KEY}:2`, validBlob(22))
  store.set(`${KEY}:3`, validBlob(33))
  loadMeta() // binds boundKey to slot 1, exactly as booting on slot 1 does
  assert.strictEqual(deleteSlot(3), true, 'deleteSlot reports what it did')
  assert.strictEqual(exportSlot(3), null, 'the slot it was POINTED AT is gone')
  assert.strictEqual(JSON.parse(exportSlot(1)).coins, 11, 'and the slot being played is untouched — this is the resetSave trap')
  assert.strictEqual(JSON.parse(exportSlot(2)).coins, 22, 'as is every other slot')
  assert.strictEqual(deleteSlot(3), true, 'erasing an already-empty slot is not an error')
  console.log('PASS run ZZ.i (deleteSlot): erases the slot it is handed and only that one, so the picker cannot destroy the save being played')

  // (j) A PAIRING ADOPT MOVES THE SLOT POINTER; A STEADY-STATE PULL MUST NOT. Device B types
  // sixteen characters, picks slot 3, and the page reloads — on whatever slot was already active,
  // with the cloud save sitting invisibly in row 3 under a "Linked." notice. Nothing throws and
  // nothing else in the suite can see it. The other direction is just as silent: a background pull
  // that repointed the slot would drag a player out of the profile they deliberately switched to.
  store.clear()
  setActiveSlot(1)
  const rec3 = { code: 'ABCDEFGHJKMNPQRS', slot: 3, device: 'devB', gen: 0, syncedHash: '', reqId: '', pulledAt: 0 }
  assert.strictEqual(adopt({ record: rec3, blob: validBlob(77), gen: 5, isIdle: () => true, activate: true }), 'adopted')
  assert.strictEqual(activeSlot(), 3, 'a PAIRING adopt points the pointer at the slot it just wrote — the reload boots what the player chose')
  assert.strictEqual(JSON.parse(exportSlot(3)).coins, 77, 'and the blob really landed in that slot')
  setActiveSlot(1)
  assert.strictEqual(adopt({ record: rec3, blob: validBlob(88), gen: 6, isIdle: () => true }), 'adopted')
  assert.strictEqual(activeSlot(), 1, 'a steady-state pull must NOT move it — the player chose the slot they are on')
  // AND THE POINTER IS WRITTEN AFTER THE IMPORT, not before: pointing at a slot whose write was
  // REFUSED boots the player into a fresh save on the strength of an import that never happened.
  setActiveSlot(1)
  assert.strictEqual(adopt({ record: rec3, blob: '{"coins":5}', gen: 7, isIdle: () => true, activate: true }), 'refused-shape')
  assert.strictEqual(activeSlot(), 1, 'a refused import leaves the pointer where it was')
  assert.strictEqual(adopt({ record: rec3, blob: validBlob(9), gen: 8, isIdle: () => false, activate: true }), 'not-idle')
  assert.strictEqual(activeSlot(), 1, 'and so does an adopt blocked by a live run')
  // AND THE CALL SITE, NOT THE PARAMETER — the same trap run SY records against syncRowHtml.
  // Every assertion above drives adopt() directly, which leaves joinInto free to stop passing the
  // flag: the pairing flow then reloads onto the old slot with the cloud save invisible in the one
  // the player chose, and this block stays green. That mutation got through the first cut of it.
  // So drive the real entry point device B actually reaches.
  store.clear()
  setActiveSlot(1)
  let reloads = 0
  const linkNotes = []
  initSync({ isIdle: () => true, reload: () => { reloads++ }, onAdopted: (r) => linkNotes.push(r) })
  assert.strictEqual(joinInto({ code: 'ABCDEFGHJKMNPQRS', slot: 2, cloud: { gen: 3, blob: validBlob(55) } }), 'adopted')
  assert.strictEqual(activeSlot(), 2, 'joinInto must hand adopt the activation — device B picked a destination and the reload has to open it')
  assert.strictEqual(JSON.parse(exportSlot(2)).coins, 55, 'and the cloud blob really landed in that slot')
  assert.deepStrictEqual(linkNotes, ['linked'], 'a pairing adopt is announced, never silent (§9.2)')
  assert.strictEqual(reloads, 1, 'and the caller reloads exactly once')
  // Back to the default that REFUSES, so nothing later in the suite can adopt through a live stub.
  initSync({ isIdle: () => false, reload: () => {}, onAdopted: () => {}, onChange: () => {} })
  console.log('PASS run ZZ.j (adopt activates at pairing only): joinInto opens the slot the player picked, a background pull never repoints, and a refused or blocked adopt moves nothing')

  delete globalThis.localStorage
  console.log('PASS run ZZ (sync core): decision table, derived dirty, lost-ACK reqId rule, schema gate, shape validation, freeze latch, per-slot erase, pairing activation')
}

// run SM — saveSummary's TOTALITY (design §4.2) and the two new meta fields (§4.1). This exists
// because saveSummary feeds the conflict prompt, §7.2 deliberately makes that prompt undismissable
// (no backdrop tap, no Escape), and it runs on a blob that never went through loadMeta. A throw here
// is not a wrong number on screen — it is a half-drawn modal the player can only escape by clearing
// site data, which destroys all three save slots. So every scenario below feeds it something that
// made an earlier draft throw, and asserts a value came back at all.
function testSaveSummary() {
  const store = new Map()
  globalThis.localStorage = {
    getItem: (k) => (store.has(k) ? store.get(k) : null),
    setItem: (k, v) => store.set(k, String(v)),
    removeItem: (k) => store.delete(k),
  }

  // (a) THE THREE BLOBS THAT THREW. Each is realistic — no attacker required.
  //   chapters:{}  a legitimately fresh save; the furthest-chapter walk then indexes undefined
  //   no shop      reachable from a truncated response body
  //   no savedAt   the normal state of EVERY save not rewritten since this build shipped
  const fresh = saveSummary({ coins: 0, shop: {}, chapters: {} })
  assert.strictEqual(fresh.beaten, 0, 'a fresh save reports 0 beaten rather than throwing on chapters[id]')
  assert.strictEqual(fresh.chapterId, CHAPTER_ORDER[0], 'and falls back to the first chapter')
  assert.strictEqual(saveSummary({ coins: 5, chapters: {} }).upgrades, 0, 'a blob with no shop reports 0 upgrades, not a TypeError')
  assert.strictEqual(saveSummary({ shop: {} }).savedAt, 0, 'a blob with no savedAt reports 0, which the render layer shows as "unknown"')
  // And the shapes that are not objects at all. The Worker never parses (§3.4), so "the blob is a
  // JSON array" is a thing the client has to survive, not a thing the server prevents.
  for (const junk of [null, undefined, [], 'a string', 42, { chapters: [], shop: [] }]) {
    const s = saveSummary(junk)
    assert.strictEqual(typeof s.coins, 'number', `saveSummary(${JSON.stringify(junk)}) still returns a numeric coins`)
    assert.strictEqual(typeof s.chapterId, 'string', `saveSummary(${JSON.stringify(junk)}) still names a chapter`)
  }
  console.log('PASS run SM.a (totality): every blob that made an earlier draft throw returns a summary — a throw here locks the player out behind an undismissable modal')

  // (b) THE FURTHEST CHAPTER, including the one a CHAPTER_ORDER walk structurally cannot see.
  const twoUnlocked = saveSummary({ shop: {}, chapters: { [CHAPTER_ORDER[0]]: { unlocked: true }, [CHAPTER_ORDER[1]]: { unlocked: true } } })
  assert.strictEqual(twoUnlocked.chapterId, CHAPTER_ORDER[1], 'the furthest UNLOCKED ordered chapter wins')
  const withBlank = saveSummary({ shop: {}, chapters: { [CHAPTER_ORDER[0]]: { unlocked: true }, blank: { unlocked: true, maxDifficulty: 2 } } })
  assert.strictEqual(withBlank.chapterId, 'blank', "The Blank lives outside CHAPTER_ORDER, so it can only be reached by an explicit override")
  assert.strictEqual(withBlank.beaten, 1, "and its ★ row reads its OWN ladder — the same rule the hero card uses, so the two can never disagree")
  console.log('PASS run SM.b (furthest chapter): the ordered walk plus the explicit Blank override that no loop over CHAPTER_ORDER can reach')

  // (c) COERCION AT THE BOUNDARY. Every field here is attacker-controlled for anyone holding a
  // pairing code (§10 concedes it is an unrevocable bearer token), and the conflict prompt renders
  // BOTH summaries — so merely READING the comparison is the attack, before any button is pressed.
  const hostile = saveSummary({
    coins: '<img src=x onerror=alert(1)>',
    runs: '<svg onload=alert(2)>',
    shop: { hp: '<b>X</b>', dmg: 3 },
    chapters: {},
  })
  assert.strictEqual(hostile.coins, 0, 'a tampered coins string coerces to 0 rather than reaching innerHTML')
  assert.strictEqual(hostile.runs, 0, 'and so does runs')
  assert.strictEqual(hostile.upgrades, 3, 'the upgrades reduction coerces per level — without it Object.values concatenates into "0<b>X</b>3"')
  console.log('PASS run SM.c (coercion): coins, runs and every shop level are numbers before they reach a template')

  // (d) THE NAME CLAMP, applied ON PARSE. It has to be here rather than at adopt time because the
  // prompt renders the CLOUD's name before adopting it — that is the modal's whole purpose.
  assert.strictEqual(saveSummary({ name: 'x'.repeat(200) }).name.length, NAME_MAX, 'a 200-character name is clamped to the layout budget')
  assert.strictEqual(saveSummary({ name: 'a\u0000b\u001fc' }).name, 'abc', 'C0 control characters are stripped — they survive HTML-escaping and still break a row')
  assert.strictEqual(saveSummary({ name: '  \t  ' }).name, '', 'a whitespace-only name is empty, so the numbered fallback renders instead of a blank row')
  assert.strictEqual(saveSummary({ name: 42 }).name, '', 'a non-string name is empty rather than "42"')
  // Escaping is NOT this function's job and must not be, or the value would be double-escaped at
  // the render site. What it guarantees is a short, control-free string.
  assert.strictEqual(saveSummary({ name: '<b>hi' }).name, '<b>hi', 'markup is left intact here — esc() at the render site is what makes it safe, and truncation never is')
  console.log('PASS run SM.d (name clamp): clamped and stripped on parse, not on adopt, because the prompt renders the cloud name before adopting it')

  // (e) THE TWO NEW META FIELDS survive a load, and saveMeta stamps the clock.
  store.clear()
  const m = loadMeta()
  assert.strictEqual(m.name, '', 'a fresh save has an EMPTY name — never a baked "Save 1", which would be a stale English literal travelling between devices forever')
  assert.strictEqual(m.savedAt, 0, 'and savedAt 0, meaning "never written by a build that had this field"')
  const before = Date.now()
  saveMeta(m)
  assert.ok(m.savedAt >= before, 'saveMeta stamps the device clock on every write')
  const onDisk = JSON.parse(exportSlot(activeSlot()))
  assert.strictEqual(onDisk.savedAt, m.savedAt, 'and stamps it BEFORE stringify, so what is on disk is what a push uploads')
  assert.strictEqual(onDisk.name, '', 'the defaults are in the fresh literal too — loadMeta repairs are in-memory only and never written back')
  console.log('PASS run SM.e (new fields): name and savedAt default on load, live in the fresh literal, and savedAt is stamped before the write')

  // (f) slotSummary GAINS a field rather than changing one, so SS.e's asserted shape stays valid.
  store.set('charming-anomaly-save-v1', JSON.stringify({ coins: 7, name: 'Phone', shop: {}, chapters: {} }))
  const ss = slotSummary(1)
  assert.strictEqual(ss.name, 'Phone', 'the slot picker can show a name')
  assert.strictEqual(ss.coins, 7, 'without disturbing what it already showed')
  assert.strictEqual(typeof ss.total, 'number', 'or the rest of its shape')
  console.log('PASS run SM.f (slotSummary): name is an added field, so the shape the existing SS.e scenario asserts still holds')

  // (g) THE FINAL STAR (v6.6.12). Reported from play: the last star of a chapter never lit, no
  // matter how the hardest level went. The cause is that the save had no field for it — the ★ row
  // read `maxDifficulty - 1`, maxDifficulty is the highest UNLOCKED level, and winning the ladder's
  // last level unlocks nothing, so the number stops one short of the row's own length.
  const cap = chapterMaxDifficulty('body')
  const topped = { chapters: { body: { unlocked: true, maxDifficulty: cap, difficulty: cap } } }
  ensureChapterMeta(topped, 'body')
  // The defect itself, asserted rather than described: the old expression CANNOT reach `cap`, so no
  // value of maxDifficulty ever fills the row. This is what makes the new field load-bearing rather
  // than decorative — delete `won` and this line is unsatisfiable.
  assert.ok(topped.chapters.body.maxDifficulty - 1 < cap, 'maxDifficulty - 1 is structurally one short of a full row, whatever the player does')
  assert.strictEqual(topped.chapters.body.won, cap - 1, 'and an existing save backfills to exactly the stars it already showed — nobody gains one for free')
  // Winning the top level is what endRun now records (main.js), and only then does the row fill.
  topped.chapters.body.won = Math.max(topped.chapters.body.won, cap)
  assert.strictEqual(saveSummary(topped).beaten, cap, 'beating the hardest level finally fills every star')

  // R3 again: a future build with a longer ladder stores a bigger `won`, and load must not shrink it.
  const future = { chapters: { body: { unlocked: true, maxDifficulty: 9, difficulty: 1, won: 8 } } }
  ensureChapterMeta(future, 'body')
  assert.strictEqual(future.chapters.body.won, 8, "a future build's higher won survives load — capping it here would write the smaller number straight back to disk")

  // The one retroactive repair: chapters.blank.unlocked is the only record a pre-v6.6.12 save has
  // of winning The Beyond at 5, and it must survive into the new field or those players lose a star
  // they already earned.
  const veteran = { chapters: { beyond: { unlocked: true, maxDifficulty: MAX_DIFFICULTY, difficulty: 1 }, blank: { unlocked: true } } }
  ensureChapterMeta(veteran, 'beyond')
  assert.strictEqual(veteran.chapters.beyond.won, MAX_DIFFICULTY, 'a save that had already beaten The Beyond at 5 keeps that star')
  // And a save that merely UNLOCKED level 5 there does not get it.
  const nearly = { chapters: { beyond: { unlocked: true, maxDifficulty: MAX_DIFFICULTY, difficulty: 1 } } }
  ensureChapterMeta(nearly, 'beyond')
  assert.strictEqual(nearly.chapters.beyond.won, MAX_DIFFICULTY - 1, 'while unlocking the hardest level still leaves the last star hollow')
  console.log('PASS run SM.g (final star): the save now records the level WON, not just the level unlocked — backfilled, R3-safe, and the Beyond veterans keep their fifth star')

  delete globalThis.localStorage
  console.log('PASS run SM (save summary): total against every realistic malformed blob, coerced at the boundary, name clamped on parse, and the final star reachable')
}

function testForwardCompatibleSave() {
  const KEY = 'charming-anomaly-save-v1'
  const store = new Map()
  globalThis.localStorage = {
    getItem: (k) => (store.has(k) ? store.get(k) : null),
    setItem: (k, v) => store.set(k, String(v)),
    removeItem: (k) => store.delete(k),
  }
  const seed = (m) => store.set(KEY, JSON.stringify(m))
  const onDisk = () => JSON.parse(store.get(KEY))

  // (a) R3 THE ROUND TRIP — the assert that catches the real bug. A save from a build with a
  // 7-rung ladder and a 6-card level-up survives loadMeta -> saveMeta with both numbers intact.
  seed({
    coins: 500, runs: 12, shop: {}, best: { time: 300, kills: 100 },
    choiceSlots: 6, chapter: 'body', lang: 'en',
    chapters: { body: { unlocked: true, maxDifficulty: 7, difficulty: 7, best: { time: 300, kills: 100 } } },
  })
  const future = loadMeta()
  saveMeta(future)
  assert.strictEqual(onDisk().chapters.body.maxDifficulty, 7, 'a future maxDifficulty must never be written back lower')
  assert.strictEqual(onDisk().choiceSlots, 6, 'a future choiceSlots must never be written back lower')
  assert.strictEqual(onDisk().coins, 500, 'the round trip leaves the rest of the save alone')
  console.log('PASS run YY.a (R3 range preservation): stored maxDifficulty=7 / choiceSlots=6 survive loadMeta -> saveMeta')

  // (b) R3 THE OTHER HALF — nothing out of range is actually PLAYED. `difficulty` (the level
  // launched) clamps on load, and createRun clamps the cards it deals, so buildLevelUpChoices
  // never rolls 6 cards onto a screen laid out for MAX_CHOICE_SLOTS. main.js caps the same two
  // values independently (onDifficulty, and endRun's "Next level" bump) — not reachable from this
  // headless suite, which has no DOM, so those are read-verified rather than asserted here.
  assert.strictEqual(future.chapters.body.difficulty, MAX_DIFFICULTY,
    `expected the launched difficulty to clamp to ${MAX_DIFFICULTY}, got ${future.chapters.body.difficulty}`)
  // The ceiling is pinned to a LITERAL, deliberately, even though every assert below derives from
  // the constant. `capped.choiceSlots === MAX_CHOICE_SLOTS` is min(MAX, stored) === MAX, an
  // identity for any MAX at or below the stored value — so on its own it cannot catch a ceiling set
  // too HIGH, which is the only direction that overflows the level-up modal. And that modal really
  // is laid out for four: ui.js's level-up key map is a literal { Digit1..Digit4 }, so a 5th card
  // would be unselectable by keyboard while the hint above it counts to 5. Raising this number is a
  // UI change (key map + .lv-cards layout in styles.css), not a config tweak — if you are here
  // because you added a rung to SACRIFICE_COSTS, that is the change you also owe.
  assert.strictEqual(MAX_CHOICE_SLOTS, 4, 'the level-up screen is laid out (and keyboard-mapped) for exactly 4 cards')
  Math.random = mulberry32(20260804)
  const capped = createRun(future, { chapter: 'body', difficulty: future.chapters.body.difficulty })
  assert.strictEqual(capped.difficulty, MAX_DIFFICULTY, "the run launches at this build's ceiling")
  assert.strictEqual(capped.choiceSlots, MAX_CHOICE_SLOTS,
    `expected run.choiceSlots to clamp to ${MAX_CHOICE_SLOTS}, got ${capped.choiceSlots}`)
  capped.player.xp = capped.player.xpNext + 1
  stepSim(capped, { x: 0, y: 0 }, 1 / 60)
  assert.strictEqual(capped.phase, 'levelup', 'expected a level-up to trigger')
  assert.strictEqual(capped.levelUpChoices.length, MAX_CHOICE_SLOTS,
    `a stored choiceSlots of 6 must still deal exactly ${MAX_CHOICE_SLOTS} cards, got ${capped.levelUpChoices.length}`)
  // Per-chapter ceilings use the chapter's OWN ladder, not the game-wide one (blank caps at 3).
  const blankEntry = ensureChapterMeta({ chapters: { blank: { unlocked: true, maxDifficulty: 9, difficulty: 9 } } }, 'blank')
  assert.strictEqual(blankEntry.maxDifficulty, 9, 'blank keeps its stored maxDifficulty')
  assert.strictEqual(blankEntry.difficulty, chapterMaxDifficulty('blank'), "blank plays at its OWN 3-rung cap, not MAX_DIFFICULTY")
  console.log(`PASS run YY.b (R3 play safety): plays at ${MAX_DIFFICULTY}/${MAX_CHOICE_SLOTS} cards, blank still capped at ${chapterMaxDifficulty('blank')}`)

  // (c) R1 POINTER SAFETY — meta.chapter naming a chapter this build has no table entry for. This
  // threw `TypeError: Cannot read properties of undefined (reading 'balance')` before the fix.
  seed({
    coins: 0, runs: 0, shop: {}, best: { time: 0, kills: 0 },
    chapter: 'nebula-of-the-future', chapters: {},
  })
  const alien = loadMeta()
  assert.strictEqual(alien.chapter, 'nebula-of-the-future',
    'loadMeta must NOT repair meta.chapter — a load-time repair is written back over the newer save')
  Math.random = mulberry32(20260804)
  const degraded = createRun(alien, { chapter: alien.chapter, difficulty: 1 })
  assert.strictEqual(degraded.chapter, CHAPTER_ORDER[0], `an unknown chapter id must degrade to ${CHAPTER_ORDER[0]}, got ${degraded.chapter}`)
  assert.strictEqual(degraded.weapons[0].id, CHAPTERS[CHAPTER_ORDER[0]].starter,
    'the fallback run must carry the fallback chapter\'s starter weapon, not undefined')
  // ...and it is a REAL run of that chapter, not a half-built one: identical modifiers (the
  // EARLY_CALM easing and the chapter balance block included), and it steps like any other run.
  Math.random = mulberry32(20260804)
  const reference = createRun(alien, { chapter: CHAPTER_ORDER[0], difficulty: 1 })
  assert.deepStrictEqual(degraded.mods, reference.mods, 'the fallback run must get the fallback chapter\'s modifiers, not a bare baseline')
  for (let i = 0; i < 300 && degraded.phase !== 'dead'; i++) {
    if (degraded.phase === 'levelup') { declineLevelUp(degraded); continue }
    stepSim(degraded, { x: 1, y: 0 }, 1 / 60)
    degraded.player.hp = degraded.player.maxHP
  }
  assert.strictEqual(degraded.phase, 'playing', 'the fallback run must step like any other run')
  // Inherited keys are truthy on any object literal, so a plain `CHAPTERS[id] ?` guard would let
  // them through and build a nameless half-run. Object.hasOwn rejects them too.
  for (const key of ['__proto__', 'constructor', 'toString']) {
    assert.strictEqual(createRun(makeMeta(), { chapter: key }).chapter, CHAPTER_ORDER[0],
      `an inherited key '${key}' must degrade to ${CHAPTER_ORDER[0]}, not be treated as a chapter`)
  }
  // ...and the run must be launched at the FALLBACK chapter's ladder position, not the alien one.
  // createRun degrading run.chapter is only half of R1: main.js's onPlay reads the difficulty and
  // rolls the anomalies BEFORE createRun sees anything, so if it read them from meta.chapter
  // unresolved, an alien chapter at the top of its ladder would drop the player into The Body at
  // level 5 with four anomalies they never unlocked there — and endRun, which keys off run.chapter
  // and therefore says 'body', would credit that win to body's ladder and unlock the next chapter
  // off it. onPlay is not reachable from this headless suite (main.js imports Pixi), which is why
  // the resolution lives in one shared helper — resolveChapterId (config.js) — that every consumer
  // calls and this scenario can pin directly.
  seed({
    coins: 0, runs: 0, shop: {}, best: { time: 0, kills: 0 },
    chapter: 'nebula-of-the-future',
    chapters: {
      // 8/8: above this build's ladder ON PURPOSE, so the round-trip assert below has teeth — a
      // consumer that reached into this entry would clamp `difficulty` to 5 and persist it.
      'nebula-of-the-future': { unlocked: true, maxDifficulty: 8, difficulty: 8, best: { time: 300, kills: 900 } },
      body: { unlocked: true, maxDifficulty: 2, difficulty: 1, best: { time: 0, kills: 0 } },
    },
  })
  const ahead = loadMeta()
  const playedId = resolveChapterId(ahead.chapter) // exactly what main.js's onPlay/onDifficulty do
  assert.strictEqual(playedId, CHAPTER_ORDER[0], 'an unknown selected chapter resolves to the fallback before any ladder is read')
  assert.strictEqual(ensureChapterMeta(ahead, playedId).difficulty, 1,
    "the run must launch at the FALLBACK chapter's own stored level, not the alien chapter's")
  assert.strictEqual(createRun(ahead, { chapter: playedId, difficulty: ensureChapterMeta(ahead, playedId).difficulty }).difficulty, 1,
    'and createRun must build that run at that level')
  // Nor may the alien chapter's entry be touched on the way past: ensureChapterMeta clamps
  // `difficulty` to THIS build's ladder, and onDifficulty/onPlay reaching into a chapter this build
  // cannot play would write that clamp straight back to disk (the R3 loss, no run required).
  saveMeta(ahead)
  assert.deepStrictEqual(onDisk().chapters['nebula-of-the-future'],
    { unlocked: true, maxDifficulty: 8, difficulty: 8, best: { time: 300, kills: 900 } },
    "the unknown chapter's entry must round-trip untouched — no consumer may clamp a ladder it cannot play")
  // The RENDER-side consumer needs the same resolution. Not because of the pip COUNT — that comes
  // from chapterMaxDifficulty, which is `CHAPTERS[id]?.maxDifficultyCap ?? MAX_DIFFICULTY` and so
  // returns the same 5 for an unknown id as for body — but because of which pips read UNLOCKED,
  // which ui.js takes from meta.chapters[browseChapterId] (titleBelowHtml's chMeta). ui.js seeds
  // browseChapterId from the raw meta.chapter, so browsing the alien id unresolved lights every
  // pip off its 8-rung ladder while Play (resolved above) launches body at body's level 1. ui.js
  // imports the DOM and cannot be loaded here, so pin the two ledger reads it derives that from.
  assert.strictEqual(chapterMaxDifficulty(ahead.chapter), chapterMaxDifficulty(playedId),
    'the pip COUNT is identical either way — an unknown id falls through to the full ladder, so the count is not what the render-side resolution fixes')
  assert(ahead.chapters[ahead.chapter].maxDifficulty > ahead.chapters[playedId].maxDifficulty,
    'the ledger read IS what differs: unresolved, the title lights pips off the alien chapter\'s longer ladder while the run uses the fallback\'s')
  console.log(`PASS run YY.c (R1 pointer safety): unknown chapter id -> a real ${CHAPTER_ORDER[0]} run at ${CHAPTER_ORDER[0]}'s own level (was TypeError), meta.chapter and the alien entry left untouched on disk, render cap resolves too`)

  // (d) R1 THE REGRESSION TRAP — The Blank is a real chapter that deliberately lives OUTSIDE
  // CHAPTER_ORDER (config.js; ui.js appends its card by hand), so a guard written against
  // CHAPTER_ORDER membership instead of CHAPTERS membership would silently turn every Blank run
  // into a body run — invisible to a smoke test, because a body run looks perfectly healthy.
  assert(!!CHAPTERS.blank && !CHAPTER_ORDER.includes('blank'),
    'blank must stay a real chapter outside CHAPTER_ORDER — if that ever changes, retune this assert')
  assert.strictEqual(createRun(makeMeta(), { chapter: 'blank' }).chapter, 'blank',
    'The Blank must survive the pointer guard even though it is not in CHAPTER_ORDER')
  for (const id of CHAPTER_ORDER) {
    assert.strictEqual(createRun(makeMeta(), { chapter: id }).chapter, id, `chapter '${id}' must round-trip unchanged`)
  }
  assert.strictEqual(createRun(makeMeta(), {}).chapter, CHAPTER_ORDER[0], 'an omitted opts.chapter must still default')
  console.log(`PASS run YY.d (R1 blank not broken): blank + all ${CHAPTER_ORDER.length} ordered chapters unchanged, omitted id still defaults`)

  // (e) R4 meta.schema — present on a brand-new save, and defaulted on a save that predates the
  // field. The two defaults differ ON PURPOSE: absence is evidence the writer predated the field,
  // so that save IS format 1; stamping SCHEMA there would relabel a legacy blob as this build's
  // format the moment SCHEMA is first bumped. A newer save's higher schema is never lowered.
  assert(Number.isInteger(SCHEMA) && SCHEMA >= 1, `expected SCHEMA to be a positive integer, got ${SCHEMA}`)
  store.delete(KEY)
  assert.strictEqual(loadMeta().schema, SCHEMA, 'a brand-new save is stamped with this build\'s SCHEMA')
  seed({ coins: 7, runs: 0, shop: {}, best: { time: 0, kills: 0 }, chapters: {} })
  const legacy = loadMeta()
  assert.strictEqual(legacy.schema, 1, 'a save written before the field existed loads as format 1')
  saveMeta(legacy)
  assert.strictEqual(onDisk().schema, 1, 'and that 1 is what gets persisted')
  seed({ coins: 7, runs: 0, shop: {}, best: { time: 0, kills: 0 }, chapters: {}, schema: 99 })
  saveMeta(loadMeta())
  assert.strictEqual(onDisk().schema, 99, 'a newer save\'s schema is never lowered')
  console.log(`PASS run YY.e (R4 meta.schema): SCHEMA=${SCHEMA} on a fresh save, 1 on a pre-field save, a stored 99 preserved`)

  // (f) NO BACKWARD REGRESSION. Everything above loosens what loadMeta rewrites, and loadMeta runs
  // on every load of every existing save — so an ordinary, well-formed save must come back byte
  // for byte, and a corrupt one must still resolve to sane in-range values (no NaN, nothing below
  // the floor, nothing playable above the cap). 'abc' used to yield NaN, and `d > NaN` is false,
  // so a tampered ladder read as every difficulty unlocked; it now reads as 1.
  store.delete(KEY)
  const ordinary = loadMeta()
  ordinary.coins = 1234
  ordinary.runs = 7
  ordinary.chapters.body.maxDifficulty = 3
  ordinary.chapters.body.difficulty = 2
  ordinary.chapters.pond.unlocked = true
  // THE CLOCK IS PINNED ACROSS BOTH WRITES, and it has to be: saveMeta stamps `savedAt: Date.now()`,
  // so the two blobs differ whenever the millisecond happens to tick between them. That is a ~1-in-N
  // flake rather than a rare one — it failed a release gate on 2026-08-09, with the two strings
  // differing in exactly one digit (…468666 against …468665), which reads at a glance like a real
  // save-shape regression and costs a re-run to identify. The assertion is about the SHAPE surviving
  // a load/save cycle; a timestamp that advances is not a shape change.
  const realNow = Date.now
  Date.now = () => 1786300000000
  try {
    saveMeta(ordinary)
    const beforeBlob = store.get(KEY)
    saveMeta(loadMeta())
    assert.strictEqual(store.get(KEY), beforeBlob, 'an ordinary save must round-trip byte-identical through loadMeta -> saveMeta')
  } finally {
    Date.now = realNow
  }

  for (const [label, entry] of Object.entries({
    absent: undefined,
    zero: { maxDifficulty: 0, difficulty: 0 },
    negative: { maxDifficulty: -3, difficulty: -5 },
    nulls: { maxDifficulty: null, difficulty: null },
    garbage: { maxDifficulty: 'abc', difficulty: 'abc' },
    numericString: { maxDifficulty: '3', difficulty: '2' },
  })) {
    const e = ensureChapterMeta(entry ? { chapters: { body: { unlocked: true, ...entry } } } : {}, 'body')
    assert(Number.isInteger(e.maxDifficulty) && e.maxDifficulty >= 1,
      `${label}: maxDifficulty must stay a sane integer >= 1, got ${JSON.stringify(e.maxDifficulty)}`)
    assert(Number.isInteger(e.difficulty) && e.difficulty >= 1 && e.difficulty <= MAX_DIFFICULTY,
      `${label}: the playable difficulty must stay in [1, ${MAX_DIFFICULTY}], got ${JSON.stringify(e.difficulty)}`)
  }
  for (const stored of [undefined, null, 0, 1, -3, 2, 4, 6, 99, 'abc']) {
    const m = { coins: 0, runs: 0, shop: {}, best: { time: 0, kills: 0 }, chapters: {} }
    if (stored !== undefined) m.choiceSlots = stored
    seed(m)
    const slots = createRun(loadMeta()).choiceSlots
    assert(Number.isInteger(slots) && slots >= 2 && slots <= MAX_CHOICE_SLOTS,
      `a stored choiceSlots of ${JSON.stringify(stored)} must deal between 2 and ${MAX_CHOICE_SLOTS} cards, got ${slots}`)
  }
  console.log('PASS run YY.f (no backward regression): an ordinary save round-trips byte-identical, corrupt ladders and choiceSlots still resolve sane')

  delete globalThis.localStorage
  console.log(`PASS run YY (forward compatibility): R3 stored ranges preserved and clamped only at use, R1 unknown chapter pointer degrades to ${CHAPTER_ORDER[0]} without throwing (blank intact), R4 meta.schema defaults`)
}

